import { test as base, Page } from "@playwright/test";

const SUPABASE_URL = process.env.VITE_SUPABASE_URL || "https://vrrcagukyfnlhxuvnssp.supabase.co";
const FAKE_USER_ID = "00000000-0000-0000-0000-000000000001";
const FAKE_EMAIL = "test@example.com";

// A structurally valid (but fake) Supabase session object
const fakeSession = {
  access_token: [
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9",
    // payload: { sub: FAKE_USER_ID, role: "authenticated", exp: far future }
    btoa(
      JSON.stringify({
        sub: FAKE_USER_ID,
        email: FAKE_EMAIL,
        role: "authenticated",
        aud: "authenticated",
        exp: Math.floor(Date.now() / 1000) + 86400 * 365,
        iat: Math.floor(Date.now() / 1000),
      })
    )
      .replace(/\+/g, "-")
      .replace(/\//g, "_")
      .replace(/=+$/, ""),
    "fake_signature",
  ].join("."),
  token_type: "bearer",
  expires_in: 86400 * 365,
  expires_at: Math.floor(Date.now() / 1000) + 86400 * 365,
  refresh_token: "fake_refresh_token",
  user: {
    id: FAKE_USER_ID,
    aud: "authenticated",
    role: "authenticated",
    email: FAKE_EMAIL,
    email_confirmed_at: "2024-01-01T00:00:00.000Z",
    app_metadata: { provider: "email", providers: ["email"] },
    user_metadata: { full_name: "Test User" },
    identities: [],
    created_at: "2024-01-01T00:00:00.000Z",
    updated_at: "2024-01-01T00:00:00.000Z",
  },
};

async function mockAuthSession(page: Page) {
  const storageKey = `sb-${SUPABASE_URL.replace("https://", "").replace(".supabase.co", "")}-auth-token`;

  await page.addInitScript(
    ({ key, session }: { key: string; session: object }) => {
      localStorage.setItem(key, JSON.stringify(session));
    },
    { key: storageKey, session: fakeSession }
  );

  // Intercept Supabase auth token refresh ÔÇö return the fake session so the app
  // doesn't immediately redirect to /auth when it validates the session.
  await page.route(`${SUPABASE_URL}/auth/v1/token*`, async (route) => {
    await route.fulfill({
      status: 200,
      contentType: "application/json",
      body: JSON.stringify(fakeSession),
    });
  });

  // Intercept profile query so the app doesn't crash on missing DB record
  await page.route(`${SUPABASE_URL}/rest/v1/profiles*`, async (route) => {
    if (route.request().method() === "GET") {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify([
          {
            id: FAKE_USER_ID,
            full_name: "Test User",
            email: FAKE_EMAIL,
            avatar_url: null,
            theme: "system",
            language: "pt-BR",
            currency: "BRL",
            default_account_id: null,
            default_credit_card_id: null,
            app_pin_hash: null,
            created_at: "2024-01-01T00:00:00.000Z",
            updated_at: "2024-01-01T00:00:00.000Z",
          },
        ]),
      });
    } else {
      await route.continue();
    }
  });
}

type AuthFixtures = {
  authenticatedPage: Page;
};

export const test = base.extend<AuthFixtures>({
  authenticatedPage: async ({ page }, use) => {
    await mockAuthSession(page);
    await use(page);
  },
});

export { mockAuthSession };
export { expect } from "@playwright/test";

import { supabase } from '../src/integrations/supabase/client.ts';

async function test() {
  const { data, error } = await supabase
    .from("transactions")
    .select(`
      *,
      account:accounts!account_id(id, name, currency, bank_id),
      category:categories(id, name, icon, parent_category_id),
      transaction_splits:transaction_splits!transaction_id(*)
    `)
    .in("id", ["002933ac-f34d-4f23-9957-fed4db265e4f", "f2800da9-82db-4603-bc19-12bc92f9ffc1", "4a576e22-143e-473b-886f-48f2a9dffd12"]);

  console.log(JSON.stringify(data, null, 2));
}

test();

import { Link } from "react-router-dom";
import { ArrowUpRight, ArrowDownRight, Globe, ArrowRight, CreditCard } from "lucide-react";
import { cn } from "@/lib/utils";
import { BankIcon } from "@/components/financial/BankIcon";
import { getBankById } from "@/lib/banks";
import { usePrivacy } from "@/contexts/PrivacyContext";

interface AccountInfo {
  id: string;
  name: string;
  type: string;
  balance: number;
  bank_id: string | null;
  currency: string;
  is_international: boolean | null;
  bank_color?: string | null;
  hide_balance?: boolean;
}

interface SimpleTransaction {
  id: string;
  description: string;
  type: string;
  amount: number;
  destination_account_id: string | null;
  destination_amount?: number | null;
}

const getCurrencyFlag = (currency: string) => {
  switch (currency) {
    case "USD": return "­ƒç║­ƒç©";
    case "EUR": return "­ƒç¬­ƒç║";
    case "GBP": return "­ƒç¼­ƒçº";
    case "CAD": return "­ƒç¿­ƒçª";
    case "AUD": return "­ƒçª­ƒç║";
    case "JPY": return "­ƒç»­ƒçÁ";
    case "CHF": return "­ƒç¿­ƒç¡";
    case "CNY": return "­ƒç¿­ƒç│";
    case "BRL": return "­ƒçº­ƒçÀ";
    default: return "­ƒîÉ";
  }
};

interface AccountCardProps {
  account: AccountInfo;
  lastTransactions: SimpleTransaction[];
  formatCurrency: (value: number) => string;
  getCurrencySymbol: (currency: string) => string;
  accountTypeLabels: Record<string, string>;
}

export function AccountCard({
  account,
  lastTransactions,
  formatCurrency,
  getCurrencySymbol,
  accountTypeLabels
}: AccountCardProps) {
  const bank = getBankById(account.bank_id);
  const isInternational = account.is_international;
  const currencySymbol = getCurrencySymbol(account.currency || 'BRL');
  const { isPrivate } = usePrivacy();
  const shouldHideBalance = isPrivate || account.hide_balance;

  return (
    <div className="group flex flex-col rounded-2xl border border-border/50 bg-card hover:border-primary/30 transition-all duration-300 hover:shadow-xl hover:shadow-primary/5 hover:-translate-y-1 overflow-hidden focus-within:ring-2 focus-within:ring-primary focus-within:ring-offset-2 focus-within:ring-offset-background">
      <Link to={`/contas/${account.id}`} className="flex flex-col flex-1" aria-label={`Conta: ${account.name}, saldo ${formatCurrency(account.balance)}`}>
        {/* Card Header visual mimicry */}
        <div className="p-4 md:p-5 relative overflow-hidden" style={{ backgroundColor: account.bank_color || bank.color }}>
          {/* Subtle glowing orb */}
          <div className="absolute -top-10 -right-10 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-125 transition-transform duration-500" />

          <div className="flex items-center justify-between gap-3 relative z-10">
            <div className="flex items-center gap-3">
              <div className="p-1 rounded-xl bg-white/15 backdrop-blur-sm flex items-center justify-center">
                {account.type === 'CREDIT_CARD' ? (
                  <CreditCard className="w-8 h-8 opacity-90" style={{ color: bank.textColor }} />
                ) : (
                  <BankIcon bankId={account.bank_id} size="md" />
                )}
              </div>
              <div>
                <p className="font-display font-bold text-base tracking-tight" style={{ color: bank.textColor }}>
                  {account.name}
                </p>
                <p className="text-sm uppercase font-bold tracking-widest opacity-80" style={{ color: bank.textColor }}>
                  {isInternational ? 'Conta Global' : (accountTypeLabels[account.type] || account.type)}
                </p>
              </div>
            </div>
            {isInternational && (
              <span className="text-sm bg-white/20 dark:bg-black/20 px-2 py-0.5 rounded-full font-bold flex items-center gap-2 backdrop-blur-sm" style={{ color: bank.textColor }}>
                <span>{getCurrencyFlag(account.currency)}</span>
                {account.currency}
              </span>
            )}
          </div>

          <div className="mt-4 md:mt-6 relative z-10">
            <p className="text-sm uppercase tracking-wider font-bold opacity-75" style={{ color: bank.textColor }}>Saldo Dispon├¡vel</p>
            <p className={cn("font-mono text-2xl sm:text-3xl font-black tracking-tight mt-1", shouldHideBalance && "blur-md opacity-50 select-none")} style={{ color: bank.textColor }}>
              {shouldHideBalance ? "ÔÇóÔÇóÔÇóÔÇóÔÇó" : (isInternational
                ? `${currencySymbol} ${Number(account.balance).toLocaleString('en-US', { minimumFractionDigits: 2 })}`
                : formatCurrency(Number(account.balance)))
              }
            </p>
          </div>

        </div>

        {/* Card transactions footer */}
        <div className="p-4 md:p-5 space-y-3.5 flex-1 bg-gradient-to-b from-card to-background border-t border-border/40">
          <div className="flex items-center justify-between mb-1">
            <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest">├Ültimas transa├º├Áes</p>
            <span className="text-sm text-primary font-bold flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
              Ver tudo <ArrowRight className="h-3 w-3" />
            </span>
          </div>

          {lastTransactions.length === 0 ? (
            <p className="text-sm text-muted-foreground italic py-2">Nenhuma movimenta├º├úo registrada</p>
          ) : (
            <div className="space-y-2.5">
              {lastTransactions.map((tx) => {
                const isIncome = tx.type === "INCOME" || tx.destination_account_id === account.id;
                const displayAmt = (tx.destination_account_id === account.id && tx.destination_amount !== null && tx.destination_amount !== undefined)
                  ? Math.abs(Number(tx.destination_amount))
                  : Math.abs(Number(tx.amount));
                return (
                  <div
                    key={tx.id}
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      window.dispatchEvent(new CustomEvent('openTransactionModal', { detail: { transaction: tx } }));
                    }}
                    className="flex items-center justify-between text-sm p-1.5 rounded-lg hover:bg-muted/50 transition-colors cursor-pointer"
                  >
                    <div className="flex items-center gap-2 flex-1 min-w-0">
                      <div className={cn(
                        "p-1 rounded-md shrink-0",
                        isIncome ? "bg-positive/10 text-positive" : "bg-negative/10 text-negative"
                      )}>
                        {isIncome ? (
                          <ArrowDownRight className="h-3 w-3" />
                        ) : (
                          <ArrowUpRight className="h-3 w-3" />
                        )}
                      </div>
                      <span className="truncate text-muted-foreground font-medium">{tx.description}</span>
                    </div>
                    <span className={cn("font-mono font-bold ml-2 shrink-0 tabular-nums", isIncome ? "text-positive" : "text-negative")}>
                      {isIncome ? "+" : "-"}{isInternational ? currencySymbol : ""}{isInternational ? displayAmt.toFixed(2) : formatCurrency(displayAmt)}
                    </span>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </Link>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { FormField } from "@/components/ui/form-field";
import { Switch } from "@/components/ui/switch";
import { CurrencyInput } from "@/components/ui/currency-input";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Globe, Loader2 } from "lucide-react";
import { banks, internationalBanks } from "@/lib/banks";
import { BankIcon } from "@/components/financial/BankIcon";
import { Account } from "@/hooks/useAccounts";
import { moneyUtils } from "@/utils/money";

interface AccountFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: any) => Promise<void>;
  mode: "create" | "edit";
  initialData?: Account | null;
  isLoading?: boolean;
}

const accountTypeLabels: Record<string, string> = {
  CHECKING: "Conta Corrente",
  SAVINGS: "Poupan├ºa",
  CREDIT_CARD: "Cart├úo de Cr├®dito",
  INVESTMENT: "Investimento",
  CASH: "Dinheiro",
  EMERGENCY_FUND: "Reserva de Emerg├¬ncia",
  GLOBAL_ACCOUNT: "Conta Global",
};

const currencies = [
  { value: "USD", label: "USD - D├│lar Americano", symbol: "$" },
  { value: "EUR", label: "EUR - Euro", symbol: "Ôé¼" },
  { value: "GBP", label: "GBP - Libra Esterlina", symbol: "┬ú" },
  { value: "CAD", label: "CAD - D├│lar Canadense", symbol: "C$" },
  { value: "AUD", label: "AUD - D├│lar Australiano", symbol: "A$" },
  { value: "JPY", label: "JPY - Iene Japon├¬s", symbol: "┬Ñ" },
  { value: "CHF", label: "CHF - Franco Su├¡├ºo", symbol: "CHF" },
  { value: "CNY", label: "CNY - Yuan Chin├¬s", symbol: "┬Ñ" },
  { value: "MXN", label: "MXN - Peso Mexicano", symbol: "$" },
  { value: "ARS", label: "ARS - Peso Argentino", symbol: "$" },
  { value: "CLP", label: "CLP - Peso Chileno", symbol: "$" },
  { value: "COP", label: "COP - Peso Colombiano", symbol: "$" },
  { value: "PEN", label: "PEN - Sol Peruano", symbol: "S/" },
  { value: "UYU", label: "UYU - Peso Uruguaio", symbol: "$" },
  { value: "NZD", label: "NZD - D├│lar Neozeland├¬s", symbol: "NZ$" },
  { value: "SGD", label: "SGD - D├│lar de Singapura", symbol: "S$" },
  { value: "HKD", label: "HKD - D├│lar de Hong Kong", symbol: "HK$" },
  { value: "KRW", label: "KRW - Won Sul-Coreano", symbol: "Ôé®" },
  { value: "INR", label: "INR - R├║pia Indiana", symbol: "Ôé╣" },
  { value: "THB", label: "THB - Baht Tailand├¬s", symbol: "Ó©┐" },
  { value: "ZAR", label: "ZAR - Rand Sul-Africano", symbol: "R" },
  { value: "TRY", label: "TRY - Lira Turca", symbol: "Ôé║" },
  { value: "RUB", label: "RUB - Rublo Russo", symbol: "Ôé¢" },
  { value: "PLN", label: "PLN - Zloty Polon├¬s", symbol: "z┼é" },
  { value: "SEK", label: "SEK - Coroa Sueca", symbol: "kr" },
  { value: "NOK", label: "NOK - Coroa Norueguesa", symbol: "kr" },
  { value: "DKK", label: "DKK - Coroa Dinamarquesa", symbol: "kr" },
  { value: "CZK", label: "CZK - Coroa Tcheca", symbol: "K─ì" },
  { value: "HUF", label: "HUF - Forint H├║ngaro", symbol: "Ft" },
  { value: "ILS", label: "ILS - Shekel Israelense", symbol: "Ôé¬" },
  { value: "AED", label: "AED - Dirham dos Emirados", symbol: "Ï».ÏÑ" },
  { value: "SAR", label: "SAR - Riyal Saudita", symbol: "´À╝" },
];

export function AccountFormModal({
  isOpen,
  onClose,
  onSubmit,
  mode,
  initialData,
  isLoading = false,
}: AccountFormModalProps) {
  const [isInternational, setIsInternational] = useState(false);
  const [bankId, setBankId] = useState("");
  const [customBankName, setCustomBankName] = useState("");
  const [currency, setCurrency] = useState("USD");
  const [type, setType] = useState<string>("CHECKING");
  const [balance, setBalance] = useState("");

  const [name, setName] = useState("");
  const [hideBalance, setHideBalance] = useState(false);
  const [yieldType, setYieldType] = useState<string>("NONE");
  const [yieldRate, setYieldRate] = useState<string>("100");

  useEffect(() => {
    if (isOpen) {
      if (mode === "edit" && initialData) {
        setName(initialData.name || "");
        setHideBalance(initialData.hide_balance || false);
        setYieldType(initialData.yield_type || "NONE");
        setYieldRate(initialData.yield_rate ? initialData.yield_rate.toString() : "100");
        setIsInternational(initialData.is_international || false);
        setType(initialData.type || "CHECKING");
        setCurrency(initialData.currency || "BRL");

        const isCustomBank = initialData.bank_id?.startsWith("custom:");
        if (isCustomBank) {
          setBankId(initialData.is_international ? "default_international" : "default");
          setCustomBankName(initialData.bank_id!.substring(7));
        } else {
          setBankId(initialData.bank_id || "");
          setCustomBankName("");
        }
      } else {
        setIsInternational(false);
        setBankId("");
        setCustomBankName("");
        setCurrency("USD");
        setType("CHECKING");
        setBalance("");
        setName("");
        setHideBalance(false);
        setYieldType("NONE");
        setYieldRate("100");
      }
    }
  }, [isOpen, mode, initialData]);

  const handleSubmit = async () => {
    const isCustom = bankId === "default" || bankId === "default_international";
    const finalBankId =
      isCustom && customBankName.trim() ? `custom:${customBankName.trim()}` : bankId;

    const yRate = yieldType !== "NONE" ? moneyUtils.parse(yieldRate) : null;
    const yType = yieldType !== "NONE" ? yieldType : null;

    if (mode === "create") {
      let bankName = "";
      if (isCustom) {
        bankName = customBankName.trim();
      } else if (finalBankId) {
        const bank = isInternational ? internationalBanks[finalBankId] : banks[finalBankId];
        bankName = bank ? bank.name : "";
      }

      const defaultName = bankName
        ? `${bankName} - ${accountTypeLabels[type] || type}`
        : accountTypeLabels[type] || type;

      // Usa o nome digitado pelo usu├írio ou o nome gerado automaticamente como fallback
      const finalName = name.trim() || defaultName;

      await onSubmit({
        name: finalName,
        type,
        bank_id: finalBankId || null,
        balance: moneyUtils.parse(balance) || 0,
        is_international: isInternational,
        currency: isInternational ? currency : "BRL",
        hide_balance: hideBalance,
        yield_rate: yRate,
        yield_type: yType,
      });
    } else {
      await onSubmit({
        name: name.trim(),
        hide_balance: hideBalance,
        yield_type: yType,
        yield_rate: yRate,
        bank_id: finalBankId || null,
        type,
        is_international: isInternational,
        currency: isInternational ? currency : "BRL",
      });
    }
  };

  // Pr├®-preenche o nome quando o banco ou tipo mudam no modo create
  // O usu├írio pode sobrescrever livremente
  const getAutoName = () => {
    const isCustom = bankId === "default" || bankId === "default_international";
    let bankName = "";
    if (isCustom) {
      bankName = customBankName.trim();
    } else if (bankId) {
      const bank = isInternational ? internationalBanks[bankId] : banks[bankId];
      bankName = bank ? bank.name : "";
    }
    return bankName
      ? `${bankName} - ${accountTypeLabels[type] || type}`
      : accountTypeLabels[type] || type;
  };

  const isFormValid = () => {
    const isCustom = bankId === "default" || bankId === "default_international";
    if (isCustom && !customBankName.trim()) return false;
    if (!bankId) return false;

    if (mode === "create") {
      return true;
    }
    return !!name.trim();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="w-full sm:w-[500px] max-w-lg !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-3xl sm:!rounded-3xl !rounded-b-none sm:!rounded-b-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b">
        <div className="w-full flex justify-center pt-4 pb-2 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader>
          <DialogTitle className="text-base font-display font-bold">
            {mode === "create" ? "Nova conta" : "Editar conta"}
          </DialogTitle>
          {mode === "edit" && (
            <DialogDescription>
              Edite as prefer├¬ncias e o nome da sua conta. Para ajustar o saldo, registre uma nova
              transa├º├úo.
            </DialogDescription>
          )}
        </DialogHeader>

        <div className="overflow-y-auto hide-scrollbar space-y-4">
          <div className="flex items-center justify-between p-4 border rounded-2xl">
            <div className="flex items-center gap-3">
              <Globe className="h-5 w-5 text-accent" />
              <div>
                <p className="font-medium">Conta Internacional</p>
              </div>
            </div>
            <Switch
              checked={isInternational}
              onCheckedChange={(v) => {
                setIsInternational(v);
                setBankId("");
                setType(v ? "GLOBAL_ACCOUNT" : "CHECKING");
              }}
            />
          </div>

          <FormField label={isInternational ? "Institui├º├úo" : "Banco"} htmlFor="account-bank">
            <Select value={bankId} onValueChange={setBankId}>
              <SelectTrigger id="account-bank">
                <SelectValue placeholder="SelecioneÔÇª" />
              </SelectTrigger>
              <SelectContent className="max-h-[300px]">
                {isInternational
                  ? Object.values(internationalBanks).map((b) => (
                      <SelectItem key={b.id} value={b.id}>
                        <div className="flex items-center gap-2">
                          <BankIcon bankId={b.id} size="sm" />
                          {b.name}
                        </div>
                      </SelectItem>
                    ))
                  : Object.values(banks).map((b) => (
                      <SelectItem key={b.id} value={b.id}>
                        <div className="flex items-center gap-2">
                          <BankIcon bankId={b.id} size="sm" />
                          {b.name}
                        </div>
                      </SelectItem>
                    ))}
              </SelectContent>
            </Select>
          </FormField>

          {(bankId === "default" || bankId === "default_international") && (
            <FormField label="Nome da Institui├º├úo" htmlFor="account-custom-bank">
              <Input
                id="account-custom-bank"
                name="account-custom-bank"
                value={customBankName}
                onChange={(e) => setCustomBankName(e.target.value)}
                placeholder="Digite o nome do bancoÔÇª"
                autoComplete="organization"
              />
            </FormField>
          )}

          {isInternational && (
            <FormField label="Moeda" htmlFor="account-currency">
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger id="account-currency">
                  <SelectValue placeholder="Selecione a moedaÔÇª" />
                </SelectTrigger>
                <SelectContent>
                  {currencies.map((c) => (
                    <SelectItem key={c.value} value={c.value}>
                      <span className="font-mono text-sm mr-2">{c.symbol}</span>
                      {c.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </FormField>
          )}

          <FormField label="Tipo" htmlFor="account-type">
            <Select value={type} onValueChange={setType}>
              <SelectTrigger id="account-type">
                <SelectValue placeholder="Selecione o tipoÔÇª" />
              </SelectTrigger>
              <SelectContent>
                {(isInternational
                  ? [{ v: "GLOBAL_ACCOUNT", l: "Conta Global" }]
                  : [
                      { v: "CHECKING", l: "Conta Corrente" },
                      { v: "SAVINGS", l: "Poupan├ºa" },
                      { v: "INVESTMENT", l: "Investimento" },
                      { v: "CASH", l: "Dinheiro" },
                      { v: "EMERGENCY_FUND", l: "Reserva de Emerg├¬ncia" },
                    ]
