                    return (
                      <div
                        key={tx.id}
                        className={cn(
                          "flex items-center justify-between p-4 hover:bg-muted/50 transition-colors",
                          idx !== dayTransactions.length - 1 && "border-b border-border",
                          isInitialBalance && "bg-primary/5"
