                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* ÔöÇÔöÇ Linha de Saldo Final (fechamento do m├¬s) ÔöÇÔöÇ */}
      <div className="rounded-xl border border-border overflow-hidden">
        <div className="flex items-center justify-between px-4 py-3 bg-muted/40">
          <div className="flex items-center gap-3">
            <div className="w-9 h-10 rounded-full flex items-center justify-center bg-muted">
              <Landmark className="h-4 w-4 text-muted-foreground" />
            </div>
            <div>
              <p className="text-sm font-semibold">Saldo Final do Per├¡odo</p>
              <p className="text-sm text-muted-foreground">Abertura do pr├│ximo m├¬s</p>
            </div>
          </div>
          <p className={cn(
            "font-mono font-bold text-lg",
            closingBalance >= 0 ? "text-positive" : "text-negative",
            isPrivate && "blur-md opacity-50 select-none"
          )}>
            {fmt(closingBalance)}
          </p>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { CurrencyInput } from '@/components/ui/currency-input';
import { AmountInput } from '@/components/ui/amount-input';
import { Loader2, Banknote } from "lucide-react";
import { useWithdrawal } from "@/hooks/useWithdrawal";
import { moneyUtils } from "@/utils/money";

interface WithdrawalModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  accountId: string;
  accountName: string;
  accountBalance: number;
}

export function WithdrawalModal({
  open,
  onOpenChange,
  accountId,
  accountName,
  accountBalance,
}: WithdrawalModalProps) {
  const [amount, setAmount] = useState("");
  const [description, setDescription] = useState("Saque em dinheiro");

  const withdrawal = useWithdrawal();

  const handleAmountChange = (value: string) => {
    setAmount(value);
  };

  const getNumericAmount = () => {
    return moneyUtils.parse(amount) || 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const numericAmount = getNumericAmount();

    if (numericAmount <= 0) {
      return;
    }

    if (numericAmount > accountBalance) {
      return;
    }

    await withdrawal.mutateAsync({
      accountId,
      amount: numericAmount,
      description,
      date: new Date().toISOString().split("T")[0],
    });

    // Reset form
    setAmount("");
    setDescription("Saque em dinheiro");
    onOpenChange(false);
  };

  const numericAmount = getNumericAmount();
  const isInvalid = numericAmount > accountBalance;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[450px] w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <DialogHeader className="px-5 pt-5 pb-2 sm:px-6 sm:pt-6">
          <DialogTitle className="flex items-center gap-2">
            <Banknote className="h-5 w-5" />
            Sacar dinheiro
          </DialogTitle>
          <DialogDescription>
            Registre um saque em dinheiro desta conta
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 px-5 pb-5 sm:px-6 sm:pb-6">
          {/* Conta */}
          <div className="space-y-2">
            <Label>Conta</Label>
            <div className="p-3 rounded-xl border border-border bg-muted/30">
              <p className="font-medium">{accountName}</p>
              <p className="text-sm text-muted-foreground">
                Saldo dispon├¡vel: R$ {accountBalance.toFixed(2)}
              </p>
            </div>
          </div>

          {/* Valor */}
          <div className="space-y-2">
            <AmountInput 
              label="Valor do saque"
              value={amount}
              onChange={handleAmountChange}
              size="md"
              textColorClass={isInvalid ? "text-destructive" : ""}
              autoFocus
            />
            {isInvalid && (
              <p className="text-sm text-destructive text-center">Saldo insuficiente</p>
            )}
          </div>

          {/* Descri├º├úo */}
          <div className="space-y-2">
            <Label htmlFor="description">Descri├º├úo (opcional)</Label>
            <Input
              id="description"
              type="text"
              placeholder="Ex: Saque no caixa eletr├┤nico"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
            />
          </div>

          {/* Bot├Áes */}
          <div className="flex gap-2 pt-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="flex-1"
            >
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={
                numericAmount <= 0 ||
                isInvalid ||
                withdrawal.isPending
              }
              className="flex-1"
            >
              {withdrawal.isPending ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Sacando...
                </>
              ) : (
                "Confirmar Saque"
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { useUserProfile } from "@/hooks/useUserProfile";
import { supabase } from "@/integrations/supabase/client";
import { Lock, ShieldCheck } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

/**
 * PinWrapper ÔÇö Prote├º├úo de sess├úo com PIN.
 *
 * Seguran├ºa (LGPD Art. 46):
 * - PIN armazenado com bcrypt (pgcrypto) ÔÇö nunca plaintext
 * - Verifica├º├úo server-side via verify_pin RPC
 * - Lockout server-side: 5 tentativas, 60s (tabela pin_attempts)
 * - PIN nunca trafega em localStorage para lockout (era bypass├ível)
 */

export function PinWrapper({ children }: { children: React.ReactNode }) {
  const { data: profile } = useUserProfile();

  const [isLocked, setIsLocked] = useState(() => {
    try {
      return localStorage.getItem("@pedemeia:require_pin") === "true";
    } catch {
      return false;
    }
  });

  const [pinInput, setPinInput] = useState("");
  const [isVerifying, setIsVerifying] = useState(false);
  const [errorMessage, setErrorMessage] = useState("");
  const hasCheckedProfile = useRef(false);

  useEffect(() => {
    if (!hasCheckedProfile.current && profile) {
      hasCheckedProfile.current = true;
      const hasPinHash = !!(profile as any).app_pin_hash;
      if (profile.require_pin_on_open && hasPinHash) {
        const localConfig = localStorage.getItem("@pedemeia:require_pin");
        if (localConfig !== "true" && localConfig !== "false") {
          setIsLocked(true);
        }
      }
    }
  }, [profile]);

  const requirePin =
    profile?.require_pin_on_open ?? localStorage.getItem("@pedemeia:require_pin") === "true";
  const hasPinHash = !!(profile as any)?.app_pin_hash;

  if (!requirePin || !hasPinHash || !isLocked) {
    return <>{children}</>;
  }

  const handleUnlock = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsVerifying(true);
    setErrorMessage("");

    try {
      const { data: ok, error } = await supabase.rpc("verify_pin", { p_pin: pinInput });

      if (error) {
        // Erro do servidor (inclui lockout ÔÇö P0004)
        setErrorMessage(error.message);
        setPinInput("");
        return;
      }

      if (ok === true) {
        setIsLocked(false);
      } else {
        setErrorMessage("PIN incorreto.");
        setPinInput("");
      }
    } finally {
      setIsVerifying(false);
    }
  };

  return (
    <div className="flex h-screen w-full flex-col items-center justify-center bg-background px-4">
      <div className="w-full max-w-sm rounded-2xl border border-border bg-card p-8 shadow-sm">
        <div className="mb-6 flex flex-col items-center justify-center space-y-3 text-center">
          <div className="flex h-16 w-16 items-center justify-center rounded-full bg-primary/10">
            <Lock className="h-8 w-8 text-primary" />
          </div>
          <h2 className="text-xl font-bold font-display">Aplicativo Bloqueado</h2>
          <p className="text-sm text-muted-foreground">
            Digite o seu PIN de seguran├ºa para acessar as suas informa├º├Áes financeiras.
          </p>
          {errorMessage && <p className="text-sm font-medium text-destructive">{errorMessage}</p>}
        </div>

        <form onSubmit={handleUnlock} className="space-y-4">
          <Input
            type="password"
            inputMode="numeric"
            pattern="[0-9]*"
            maxLength={6}
            placeholder="Digite o PIN num├®rico"
            value={pinInput}
            onChange={(e) => setPinInput(e.target.value.replace(/\D/g, ""))}
            className="text-center text-xl tracking-[0.5em] h-14"
            autoFocus
            disabled={isVerifying}
          />
          <Button
            type="submit"
            className="w-full h-12"
            disabled={pinInput.length < 4 || isVerifying}
          >
            {isVerifying ? "Verificando..." : "Desbloquear"}
          </Button>
        </form>

        <div className="mt-6 flex items-center justify-center gap-1 text-xs text-muted-foreground">
          <ShieldCheck className="h-4 w-4 text-emerald-500" />
          <span>Prote├º├úo ativa.</span>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { CurrencyInput } from "@/components/ui/currency-input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useEconomicIndicators } from "@/hooks/useEconomicIndicators";
import { moneyUtils } from "@/utils/money";
import { Download, Info } from "lucide-react";
import { exportCalculatorToPDF } from "@/utils/calculatorExport";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

export function FixedIncomeSimulator() {
  const { data: indicators } = useEconomicIndicators();
  
  const [initialAmount, setInitialAmount] = useState<string>("1000");
  const [monthlyContribution, setMonthlyContribution] = useState<string>("500");
  const [term, setTerm] = useState<number>(5);
  const [termType, setTermType] = useState<"YEARS" | "MONTHS">("YEARS");
  const [rateType, setRateType] = useState<"CDI" | "SELIC" | "FIXED">("CDI");
  const [percentRate, setPercentRate] = useState<number>(100); // 100% of CDI/Selic or 10% Fixed
  const [investmentType, setInvestmentType] = useState<"CDB" | "LCI" | "FREE">("CDB");
  const [viewMode, setViewMode] = useState<"YEARLY" | "MONTHLY">("YEARLY");
  
  // Sincroniza dados API
  const baseRate = useMemo(() => {
    if (rateType === "CDI") return indicators?.cdi?.value || 10.4;
    if (rateType === "SELIC") return indicators?.selic?.value || 10.5;
    return 1; // Para FIXED, a base ├® 1 e o usu├írio digita o percentual direto
  }, [rateType, indicators]);

  const annualRate = rateType === "FIXED" ? percentRate : (baseRate * percentRate) / 100;

  const results = useMemo(() => {
    const months = termType === "YEARS" ? term * 12 : term;
    const monthlyRate = Math.pow(1 + (annualRate / 100), 1 / 12) - 1;
    
    const initAmt = moneyUtils.parse(initialAmount) || 0;
    const monthlyCont = moneyUtils.parse(monthlyContribution) || 0;
    
    let totalInvested = initAmt;
    let balance = initAmt;
    
    const monthlyData = [];
    
    for (let i = 1; i <= months; i++) {
      balance = balance * (1 + monthlyRate) + monthlyCont;
      totalInvested += monthlyCont;
      
      monthlyData.push({
        month: i,
        year: Math.ceil(i / 12),
        invested: totalInvested,
        grossBalance: balance,
        grossYield: balance - totalInvested
      });
    }

    const grossYield = balance - totalInvested;
    
    // C├ílculo do IR (Tabela Regressiva)
    let taxRate = 0;
    if (investmentType === "CDB") {
      const days = months * 30;
      if (days <= 180) taxRate = 0.225;
      else if (days <= 360) taxRate = 0.20;
      else if (days <= 720) taxRate = 0.175;
      else taxRate = 0.15;
    } else if (investmentType === "LCI" || investmentType === "FREE") {
      taxRate = 0; // Isento
    }

    const totalTax = grossYield * taxRate;
    const netYield = grossYield - totalTax;
    const netBalance = totalInvested + netYield;

    return {
      totalInvested,
      grossBalance: balance,
      grossYield,
      totalTax,
      netYield,
      netBalance,
      monthlyData,
      taxRate: taxRate * 100,
      months
    };
  }, [initialAmount, monthlyContribution, term, termType, annualRate, investmentType]);

  const visibleData = viewMode === "YEARLY" 
    ? results.monthlyData.filter(d => d.month % 12 === 0 || d.month === results.months)
    : results.monthlyData;

  const handleExportPDF = () => {
    exportCalculatorToPDF({
      title: "Simula├º├úo de Renda Fixa",
      parameters: [
        { label: "Investimento Inicial", value: moneyUtils.format(initialAmount, 'BRL') },
        { label: "Aporte Mensal", value: moneyUtils.format(monthlyContribution, 'BRL') },
        { label: "Prazo", value: `${term} ${termType === 'YEARS' ? 'anos' : 'meses'} (${results.months} meses)` },
        { label: "Tipo / Imposto", value: `${investmentType} (IR: ${results.taxRate.toFixed(1)}%)` },
        { label: "Taxa Bruta Projetada", value: `${annualRate.toFixed(2)}% ao ano` }
      ],
      summary: [
        { label: "Total Investido", value: moneyUtils.format(results.totalInvested, 'BRL') },
        { label: "Saldo L├¡quido", value: moneyUtils.format(results.netBalance, 'BRL'), isWarning: true },
        { label: "Rendimento L├¡quido", value: moneyUtils.format(results.netYield, 'BRL'), isWarning: true },
        { label: "Imposto Retido", value: moneyUtils.format(results.totalTax, 'BRL') }
      ],
      tableHead: ["Tempo", "Total Investido", "Saldo Bruto", "Rendimento Bruto"],
      tableBody: visibleData.map(d => [
        `M├¬s ${d.month} (Ano ${d.year})`,
        moneyUtils.format(d.invested, 'BRL'),
        moneyUtils.format(d.grossBalance, 'BRL'),
        moneyUtils.format(d.grossYield, 'BRL')
      ])
    });
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <Card className="lg:col-span-1 bg-card/50 border-border/50 shadow-sm h-fit">
        <CardHeader>
          <CardTitle className="text-base">Par├ómetros</CardTitle>
          <CardDescription>Configure os aportes e a taxa de juros</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Investimento Inicial</Label>
              <CurrencyInput 
                value={initialAmount} 
                onChange={setInitialAmount}
                className="bg-background"
              />
            </div>
            <div className="space-y-2">
              <Label>Aporte Mensal</Label>
              <CurrencyInput 
                value={monthlyContribution} 
                onChange={setMonthlyContribution}
                className="bg-background"
              />
            </div>
            <div className="space-y-2">
              <Label>Prazo</Label>
              <div className="flex items-center gap-2">
                <Input type="number" inputMode="decimal" 
                  value={term || ''} 
                  onChange={e => setTerm(Number(e.target.value))}
                  className="font-mono bg-background flex-1"
                />
                <Select value={termType} onValueChange={(v: any) => setTermType(v)}>
                  <SelectTrigger className="w-[110px] bg-background">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="YEARS">Anos</SelectItem>
                    <SelectItem value="MONTHS">Meses</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            
            <div className="space-y-2 pt-4 border-t border-border/50">
              <Label>Produto</Label>
              <Select value={investmentType} onValueChange={(v: any) => setInvestmentType(v)}>
                <SelectTrigger className="bg-background">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="CDB">CDB / Tesouro Direto (Tributado)</SelectItem>
                  <SelectItem value="LCI">LCI / LCA / Poupan├ºa (Isento)</SelectItem>
                  <SelectItem value="FREE">Juros Compostos Livres</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-3 pt-2">
              <div className="space-y-2">
                <Label className="flex h-5 items-center">Indexador</Label>
                <Select value={rateType} onValueChange={(v: any) => setRateType(v)}>
                  <SelectTrigger className="bg-background">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="CDI">CDI</SelectItem>
                    <SelectItem value="SELIC">Selic</SelectItem>
                    <SelectItem value="FIXED">Prefixado</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label className="flex h-5 justify-between items-center">
                  <span>{rateType === 'FIXED' ? 'Taxa (a.a)' : 'Percentual'}</span>
                  {rateType !== 'FIXED' && (
                    <TooltipProvider>
                      <Tooltip>
                        <TooltipTrigger asChild>
                          <Info className="h-3.5 w-3.5 text-muted-foreground cursor-help" />
                        </TooltipTrigger>
                        <TooltipContent>
                          Ex: 100% do CDI ({indicators?.cdi?.value}% a.a.)
                        </TooltipContent>
                      </Tooltip>
                    </TooltipProvider>
                  )}
                </Label>
                <div className="flex items-center gap-2">
                  <Input type="number" inputMode="decimal" 
                    value={percentRate || ''} 
                    onChange={e => setPercentRate(Number(e.target.value))}
                    className="font-mono bg-background"
                  />
                  <span className="text-sm font-bold text-muted-foreground">%</span>
                </div>
              </div>
            </div>
            
            <div className="p-3 bg-muted/50 rounded-xl flex items-center justify-between text-sm border border-border/50">
              <span className="text-muted-foreground font-medium">Rentabilidade Bruta:</span>
              <div className="flex flex-col items-end">
                <span className="font-bold text-primary font-mono">{annualRate.toFixed(2)}% a.a</span>
                <span className="text-sm text-muted-foreground font-mono">
                  ({((Math.pow(1 + annualRate / 100, 1 / 12) - 1) * 100).toFixed(2)}% a.m)
                </span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="lg:col-span-2 space-y-6">
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <Card className="bg-card/50 border-border/50 shadow-sm relative overflow-hidden">
            <CardContent className="p-6 relative z-10">
              <p className="text-sm font-medium text-muted-foreground mb-1">Total Investido</p>
              <p className="text-2xl font-mono font-bold text-foreground">
                {moneyUtils.format(results.totalInvested, 'BRL')}
              </p>
            </CardContent>
          </Card>
          
          <Card className="bg-card/50 border-border/50 shadow-sm relative overflow-hidden">
            <CardContent className="p-6 relative z-10">
              <p className="text-sm font-medium text-muted-foreground mb-1">Rendimento L├¡quido</p>
              <p className="text-2xl font-mono font-bold text-emerald-600 dark:text-emerald-500">
                + {moneyUtils.format(results.netYield, 'BRL')}
              </p>
            </CardContent>
          </Card>
          
          <Card className="bg-primary/5 border-primary/20 shadow-sm relative overflow-hidden sm:col-span-3 lg:col-span-1">
            <div className="absolute top-0 right-0 w-24 h-24 bg-primary/10 rounded-full blur-2xl -translate-y-1/2 translate-x-1/2" />
            <CardContent className="p-6 relative z-10">
              <p className="text-sm font-medium text-primary mb-1 font-bold">Saldo Final L├¡quido</p>
              <p className="text-3xl font-mono font-black text-primary tracking-tighter">
                {moneyUtils.format(results.netBalance, 'BRL')}
              </p>
              {results.totalTax > 0 && (
                <p className="text-sm text-muted-foreground mt-2 font-medium">
                  J├í descontado {moneyUtils.format(results.totalTax, 'BRL')} de IR ({results.taxRate}%).
                </p>
              )}
            </CardContent>
          </Card>
        </div>

        <Card className="bg-card/50 border-border/50 shadow-sm">
          <CardHeader className="flex flex-col sm:flex-row sm:items-center justify-between pb-2 gap-4">
            <div>
              <CardTitle className="text-base">Evolu├º├úo do Patrim├┤nio</CardTitle>
              <CardDescription>O poder dos juros compostos com o tempo</CardDescription>
            </div>
            <div className="flex items-center gap-2">
              <Select value={viewMode} onValueChange={(v: any) => setViewMode(v)}>
                <SelectTrigger className="w-[130px] h-8 text-sm bg-background">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="YEARLY">Vis├úo Anual</SelectItem>
                  <SelectItem value="MONTHLY">Vis├úo Mensal</SelectItem>
                </SelectContent>
              </Select>
              <Button variant="outline" size="sm" onClick={handleExportPDF} className="gap-2 h-8">
                <Download className="h-4 w-4" /> PDF
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            <div className="rounded-xl border border-border/50 overflow-hidden mt-4">
              <div className="max-h-[350px] overflow-y-auto scrollbar-hide">
                <table className="w-full text-sm text-left">
                  <thead className="text-sm text-muted-foreground uppercase tracking-widest font-bold bg-muted/50 sticky top-0 z-10 shadow-sm">
                    <tr>
                      <th className="px-4 py-3">Per├¡odo</th>
                      <th className="px-4 py-3 text-right">Total Investido</th>
                      <th className="px-4 py-3 text-right text-emerald-600 dark:text-emerald-500">Rendimento Acum.</th>
                      <th className="px-4 py-3 text-right text-primary">Saldo Bruto</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/50">
                    {visibleData.map((d) => (
                      <tr key={d.month} className="hover:bg-muted/30 transition-colors">
                        <td className="px-4 py-3 font-medium text-sm">
                          M├¬s {d.month} <span className="text-muted-foreground font-normal">(Ano {d.year})</span>
                        </td>
                        <td className="px-4 py-3 font-mono text-right text-sm text-muted-foreground">
                          {moneyUtils.format(d.invested, 'BRL')}
                        </td>
                        <td className="px-4 py-3 font-mono text-right text-sm font-bold text-emerald-600/80 dark:text-emerald-500/80">
                          +{moneyUtils.format(d.grossYield, 'BRL')}
                        </td>
                        <td className="px-4 py-3 font-mono text-right text-sm font-bold text-foreground">
                          {moneyUtils.format(d.grossBalance, 'BRL')}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { useEconomicIndicators } from '@/hooks/useEconomicIndicators';
import { moneyUtils } from '@/utils/money';
import { RefreshCcw, Download, Info } from 'lucide-react';
import { exportCalculatorToPDF } from '@/utils/calculatorExport';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';

export function PurchasingPowerSimulator() {
  const { data: indicators, isLoading } = useEconomicIndicators();

  const [initialAmount, setInitialAmount] = useState<number>(10000);
  const [term, setTerm] = useState<number>(5);
  const [termType, setTermType] = useState<'YEARS' | 'MONTHS'>('YEARS');
  const [inflationRate, setInflationRate] = useState<number>(4.5);
  const [viewMode, setViewMode] = useState<'YEARLY' | 'MONTHLY'>('YEARLY');

  // Sincroniza com a API quando carrega, mas permite edi├º├úo
  const [hasSynced, setHasSynced] = useState(false);
  if (indicators?.ipca && !hasSynced) {
    setInflationRate(indicators.ipca.value);
    setHasSynced(true);
  }

  const results = useMemo(() => {
    const rateDecimal = inflationRate / 100;
    const months = termType === 'YEARS' ? term * 12 : term;
    const monthlyRate = Math.pow(1 + rateDecimal, 1 / 12) - 1;

    const requiredFutureAmount = initialAmount * Math.pow(1 + monthlyRate, months);
    const futurePurchasingPower = initialAmount / Math.pow(1 + monthlyRate, months);
    const lostPower = initialAmount - futurePurchasingPower;

    const monthlyData = [];
    for (let i = 1; i <= months; i++) {
      monthlyData.push({
        month: i,
        year: Math.ceil(i / 12),
        requiredToMaintain: initialAmount * Math.pow(1 + monthlyRate, i),
        purchasingPowerOfInitial: initialAmount / Math.pow(1 + monthlyRate, i),
      });
    }

    return {
      requiredFutureAmount,
      futurePurchasingPower,
      lostPower,
      monthlyData,
      months,
    };
  }, [initialAmount, term, termType, inflationRate]);

  const visibleData =
    viewMode === 'YEARLY'
      ? results.monthlyData.filter((d) => d.month % 12 === 0 || d.month === results.months)
      : results.monthlyData;

  const handleExportPDF = () => {
    exportCalculatorToPDF({
      title: 'Simula├º├úo de Poder de Compra (Infla├º├úo)',
      parameters: [
        { label: 'Valor Base', value: moneyUtils.format(initialAmount, 'BRL') },
        { label: 'Prazo', value: `${term} ${termType === 'YEARS' ? 'anos' : 'meses'}` },
        { label: 'Infla├º├úo (IPCA) Projetada', value: `${inflationRate.toFixed(2)}% ao ano` },
      ],
      summary: [
        {
          label: 'Valor necess├írio no futuro',
          value: moneyUtils.format(results.requiredFutureAmount, 'BRL'),
        },
        {
          label: 'Poder de compra real no futuro',
          value: moneyUtils.format(results.futurePurchasingPower, 'BRL'),
          isWarning: true,
        },
        {
          label: 'Poder de compra perdido',
          value: moneyUtils.format(results.lostPower, 'BRL'),
          isWarning: true,
        },
      ],
      tableHead: ['Per├¡odo', 'Necess├írio p/ Manter Padr├úo', 'Poder de Compra Real'],
      tableBody: visibleData.map((d) => [
        `M├¬s ${d.month} (Ano ${d.year})`,
        moneyUtils.format(d.requiredToMaintain, 'BRL'),
        moneyUtils.format(d.purchasingPowerOfInitial, 'BRL'),
      ]),
    });
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      <Card className="lg:col-span-1 bg-card/50 border-border/50 shadow-sm h-fit">
        <CardHeader>
          <CardTitle className="text-base">Par├ómetros</CardTitle>
          <CardDescription>Ajuste os valores para simular a infla├º├úo</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="space-y-3">
            <Label>Valor Base (R$)</Label>
            <Input
              type="number"
              inputMode="decimal"
              value={initialAmount || ''}
              onChange={(e) => setInitialAmount(Number(e.target.value))}
              className="text-base font-mono bg-background"
            />
          </div>

          <div className="space-y-2">
            <Label>Prazo</Label>
            <div className="flex items-center gap-2">
              <Input
                type="number"
                inputMode="decimal"
                value={term || ''}
                onChange={(e) => setTerm(Number(e.target.value))}
                className="font-mono bg-background flex-1"
              />
              <Select value={termType} onValueChange={(v: any) => setTermType(v)}>
                <SelectTrigger className="w-[110px] bg-background">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="YEARS">Anos</SelectItem>
                  <SelectItem value="MONTHS">Meses</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-3 pt-2 border-t border-border/50">
            <div className="flex justify-between items-center">
              <Label className="flex items-center gap-2">
                Infla├º├úo (IPCA) a.a.
                <TooltipProvider>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Info className="h-3.5 w-3.5 text-muted-foreground cursor-help" />
                    </TooltipTrigger>
                    <TooltipContent className="w-64">
                      A infla├º├úo acumulada de 12 meses pelo Banco Central hoje ├® de{' '}
                      {indicators?.ipca?.value}%.
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </Label>
              <Button
                variant="ghost"
                size="sm"
                className="h-6 px-2 text-sm uppercase gap-1"
                onClick={() => setInflationRate(indicators?.ipca?.value || 4.5)}
                disabled={isLoading}
              >
                <RefreshCcw className="h-3 w-3" /> Puxar do BCB
              </Button>
            </div>
            <div className="flex items-center gap-2">
              <Input
                type="number"
                inputMode="decimal"
                step="0.01"
                value={inflationRate || ''}
                onChange={(e) => setInflationRate(Number(e.target.value))}
                className="font-mono bg-background"
              />
              <span className="text-muted-foreground font-bold">%</span>
            </div>
          </div>
        </CardContent>
      </Card>

      <div className="lg:col-span-2 space-y-6">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Card className="bg-primary/5 border-primary/20 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full blur-2xl -translate-y-1/2 translate-x-1/2" />
            <CardContent className="p-6 relative z-10">
              <p className="text-sm font-medium text-muted-foreground mb-1">Necess├írio no futuro</p>
              <p className="text-3xl font-mono font-bold text-foreground">
                {moneyUtils.format(results.requiredFutureAmount, 'BRL')}
              </p>
              <p className="text-sm text-muted-foreground mt-2 leading-relaxed">
                Para comprar as mesmas coisas que{' '}
                <strong className="text-foreground">
                  {moneyUtils.format(initialAmount, 'BRL')}
                </strong>{' '}
                compra hoje.
              </p>
            </CardContent>
          </Card>

          <Card className="bg-warning/5 border-warning/20 shadow-sm relative overflow-hidden">
            <div className="absolute top-0 right-0 w-32 h-32 bg-warning/10 rounded-full blur-2xl -translate-y-1/2 translate-x-1/2" />
            <CardContent className="p-6 relative z-10">
              <p className="text-sm font-medium text-muted-foreground mb-1">Poder de compra real</p>
              <p className="text-3xl font-mono font-bold text-warning dark:text-warning">
                {moneyUtils.format(results.futurePurchasingPower, 'BRL')}
              </p>
              <p className="text-sm text-muted-foreground mt-2 leading-relaxed">
                Seus {moneyUtils.format(initialAmount, 'BRL')} debaixo do colch├úo ter├úo o poder de
                compra equivalente a este valor.
              </p>
            </CardContent>
          </Card>
        </div>

        <Card className="bg-card/50 border-border/50 shadow-sm">
          <CardHeader className="flex flex-col sm:flex-row sm:items-center justify-between pb-2 gap-4">
            <div>
              <CardTitle className="text-base">Evolu├º├úo da Desvaloriza├º├úo</CardTitle>
              <CardDescription>Mesa a m├¬s, como a infla├º├úo corr├│i o dinheiro</CardDescription>
            </div>
            <div className="flex items-center gap-2">
              <Select value={viewMode} onValueChange={(v: any) => setViewMode(v)}>
                <SelectTrigger className="w-[130px] h-8 text-sm bg-background">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="YEARLY">Vis├úo Anual</SelectItem>
                  <SelectItem value="MONTHLY">Vis├úo Mensal</SelectItem>
                </SelectContent>
              </Select>
              <Button variant="outline" size="sm" onClick={handleExportPDF} className="gap-2 h-8">
                <Download className="h-4 w-4" /> PDF
              </Button>
            </div>
          </CardHeader>
          <CardContent>
            <div className="rounded-xl border border-border/50 overflow-hidden mt-4">
              <div className="max-h-[300px] overflow-y-auto">
                <table className="w-full text-sm text-left">
                  <thead className="text-sm text-muted-foreground uppercase bg-muted/50 sticky top-0 z-10">
                    <tr>
                      <th className="px-4 py-3 font-medium">Per├¡odo</th>
                      <th className="px-4 py-3 font-medium text-right">Manter Padr├úo</th>
                      <th className="px-4 py-3 font-medium text-right text-warning dark:text-warning">
                        Poder de Compra Real
                      </th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-border/50">
                    {visibleData.map((d) => (
                      <tr key={d.month} className="hover:bg-muted/30 transition-colors">
                        <td className="px-4 py-3 font-medium text-sm">
                          M├¬s {d.month}{' '}
                          <span className="text-muted-foreground font-normal">(Ano {d.year})</span>
                        </td>
                        <td className="px-4 py-3 font-mono text-right text-sm">
                          {moneyUtils.format(d.requiredToMaintain, 'BRL')}
                        </td>
                        <td className="px-4 py-3 font-mono text-right text-warning dark:text-warning text-sm font-bold">
                          {moneyUtils.format(d.purchasingPowerOfInitial, 'BRL')}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { Button } from "@/components/ui/button";
import { Archive, ChevronDown, RotateCcw } from "lucide-react";
import { getBankById } from "@/lib/banks";
import { BankIcon } from "@/components/financial/BankIcon";

interface ArchivedCardsSectionProps {
  archivedCards: any[];
  formatCurrency: (value: number) => string;
  onUnarchive: (id: string) => void;
  isUnarchiving: boolean;
  onCardSelect: (card: any) => void;
}

export function ArchivedCardsSection({
  archivedCards,
  formatCurrency,
  onUnarchive,
  isUnarchiving,
  onCardSelect
}: ArchivedCardsSectionProps) {
  const cards = archivedCards.filter(c => c.type === 'CREDIT_CARD');
  
  if (cards.length === 0) return null;

  return (
    <div className="space-y-4">
      <details className="group">
        <summary className="flex items-center justify-between cursor-pointer list-none p-4 rounded-xl border border-border hover:bg-muted/50 transition-colors">
          <span className="text-sm font-medium text-muted-foreground flex items-center gap-2">
            <Archive className="h-4 w-4" />
            Cart├Áes Arquivados ({cards.length})
          </span>
          <ChevronDown className="h-4 w-4 transition-transform group-open:rotate-180" />
        </summary>
        <div className="mt-4 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 animate-fade-in">
          {cards.map((card) => {
            const bank = getBankById(card.bank_id);
            return (
              <div
                key={card.id}
                className="group p-4 rounded-xl border border-border bg-muted/30 hover:bg-muted/50 transition-colors cursor-pointer"
                style={{ borderColor: bank.color + '40' }}
                onClick={() => onCardSelect(card)}
              >
                <div className="flex items-start justify-between mb-3">
                  <div className="flex items-center gap-3 min-w-0 flex-1">
                    <BankIcon bankId={card.bank_id} accountName={card.name} size="md" />
                    <div className="min-w-0 flex-1">
                      <p className="font-medium text-sm truncate group-hover:text-primary transition-colors">{card.name}</p>
                      <p className="text-xs text-muted-foreground">Cart├úo de Cr├®dito</p>
                    </div>
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-xs text-muted-foreground">Saldo:</span>
                    <span className="font-mono text-sm font-semibold text-destructive">
                      {formatCurrency(Math.abs(Number(card.balance)))}
                    </span>
                  </div>

                  <Button
                    variant="outline"
                    size="sm"
                    onClick={(e) => {
                      e.stopPropagation();
                      onUnarchive(card.id);
                    }}
                    disabled={isUnarchiving}
                    className="w-full gap-2 relative z-10"
                  >
                    <RotateCcw className="h-3 w-3" />
                    Restaurar
                  </Button>
                </div>
              </div>
            );
          })}
        </div>
      </details>
    </div>
  );
}

import { useMemo } from "react";
import { useCategories } from "@/hooks/useCategories";
import { moneyUtils } from "@/utils/money";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { EmptyState } from "@/components/ui/empty-state";
import { LayoutGrid } from "lucide-react";

interface CreditCardCategoriesProps {
  transactions: any[];
}

export function CreditCardCategories({ transactions }: CreditCardCategoriesProps) {
  const { data: categories = [] } = useCategories();

  const categoryData = useMemo(() => {
    const map: Record<string, { value: number; count: number; icon: string }> = {};
    const expenses = transactions.filter(t => t.type === "EXPENSE");
    
    expenses.forEach(tx => {
      let categoryName = "Sem categoria";
      let categoryIcon = "­ƒÅÀ´©Å";
      
      if (tx.category && tx.category.id && tx.category.name && tx.category.name !== "null" && tx.category.name !== "undefined") {
        const catId = tx.category.id;
        const catInfo = categories.find(c => c.id === catId);
        
        if (catInfo) {
          categoryIcon = catInfo.icon || "­ƒÅÀ´©Å";
          if (catInfo.parent_category_id) {
            const parentCat = categories.find(c => c.id === catInfo.parent_category_id);
            if (parentCat) {
              categoryName = `${parentCat.name} ÔÇ║ ${catInfo.name}`.trim();
              categoryIcon = parentCat.icon || categoryIcon;
            } else {
              categoryName = catInfo.name.trim();
            }
          } else {
            categoryName = catInfo.name.trim();
          }
        } else {
          categoryName = tx.category.name;
          categoryIcon = tx.category.icon || "­ƒÅÀ´©Å";
        }
      }

      if (!categoryName || categoryName.trim() === "" || categoryName === "null" || categoryName === "undefined") {
        categoryName = "Sem categoria";
      }

      const finalAmount = Number(tx.amount || 0);

      if (finalAmount > 0) {
        if (!map[categoryName]) map[categoryName] = { value: 0, count: 0, icon: categoryIcon };
        map[categoryName].value = SafeFinancialCalculator.add(map[categoryName].value, finalAmount);
        map[categoryName].count += 1;
      }
    });
    
    const total = Object.values(map).reduce((sum, c) => SafeFinancialCalculator.add(sum, c.value), 0);
    
    return Object.entries(map)
      .map(([category, d]) => ({ 
        category, 
        icon: d.icon,
        value: d.value, 
        count: d.count, 
        percent: total > 0 ? Math.round((d.value / total) * 100) : 0 
      }))
      .sort((a, b) => b.value - a.value);
  }, [transactions, categories]);

  if (categoryData.length === 0) {
    return (
      <EmptyState
        icon={LayoutGrid}
        title="Nenhum gasto por categoria"
        description="Nenhuma despesa registrada nesta fatura ainda."
      />
    );
  }

  return (
    <div className="bg-card/40 border border-border/50 rounded-2xl p-5 shadow-sm mt-4 mb-6">
      <h3 className="text-sm font-bold tracking-tight mb-4 flex items-center gap-2">
        <span>Resumo por Categoria</span>
      </h3>
      
      <div className="space-y-4">
        {categoryData.map((item) => (
          <div key={item.category} className="group relative">
            <div className="flex justify-between items-end mb-2">
              <div className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-lg bg-primary/10 text-primary flex items-center justify-center text-sm group-hover:scale-110 transition-transform">
                  {item.icon}
                </div>
                <div>
                  <p className="text-sm font-bold text-foreground leading-none">{item.category}</p>
                  <p className="text-sm text-muted-foreground mt-1 font-medium">{item.count} {item.count === 1 ? 'transa├º├úo' : 'transa├º├Áes'}</p>
                </div>
              </div>
              <div className="text-right">
                <p className="text-sm font-bold text-foreground leading-none">{moneyUtils.format(item.value)}</p>
                <p className="text-sm text-muted-foreground mt-1 font-semibold">{item.percent}%</p>
              </div>
            </div>
            
            <div className="h-2 w-full bg-secondary/50 rounded-full overflow-hidden">
              <div 
                className="h-full bg-primary/80 transition-all duration-1000 ease-out" 
                style={{ width: `${item.percent}%` }}
              />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

import React from "react";
import { useSharedCreditCards, useRevokeSharedCard } from "@/hooks/useSharedCreditCards";
import { UserAvatar } from "@/components/ui/user-avatar";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { CreditCardCategories } from "./CreditCardCategories";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  ArrowLeft,
  Settings,
  Pencil,
  Trash2,
  ChevronLeft,
  ChevronRight,
  Wallet,
  Download,
  CreditCard,
  MoreHorizontal,
  Archive,
  RotateCcw,
  Share2,
  CalendarClock,
  AlertCircle,
} from "lucide-react";
import { InstallmentSimulator } from "./InstallmentSimulator";
import { BankIcon } from "@/components/financial/BankIcon";
import { cn } from "@/lib/utils";
import { EmptyState } from "@/components/ui/empty-state";
import { useAuth } from "@/contexts/AuthContext";
import { getInvoiceData } from "@/lib/invoiceUtils";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";

interface CreditCardDetailViewProps {
  selectedCard: any;
  goBack: () => void;
  openEditCardDialog: (card: any) => void;
  setDeleteCardConfirm: (state: { isOpen: boolean; card: any | null }) => void;
  selectedDate: Date;
  changeMonth: (offset: number) => void;
  goToCurrentMonth: () => void;
  monthName: string;
  cycleRange: string;
  invoiceFetching: boolean;
  invoiceData: any;
  formatCurrency: (value: number) => string;
  daysUntilDue: number;
  usagePercent: number;
  bank: any;
  setShowPayDialog: (v: boolean) => void;
  setShowImportDialog: (v: boolean) => void;
  handleEditTransaction: (tx: any) => void;
  setDeleteConfirm: (v: { isOpen: boolean; transaction: any | null }) => void;
  installments: any[];
  allYearTransactions?: any[];
  dependentTransactions?: any[];
  canDelete?: boolean;
  onArchive: (card: any) => void;
  onUnarchive: (card: any) => void;
  setShowSharingDialog: (v: boolean) => void;
  onAdjustClosingDate?: (newDay: number, referenceDate: Date) => void;
}

export function CreditCardDetailView({
  selectedCard,
  goBack,
  openEditCardDialog,
  setDeleteCardConfirm,
  selectedDate,
  changeMonth,
  goToCurrentMonth,
  monthName,
  cycleRange,
  invoiceFetching,
  invoiceData,
  formatCurrency,
  daysUntilDue,
  usagePercent,
  bank,
  setShowPayDialog,
  setShowImportDialog,
  handleEditTransaction,
  setDeleteConfirm,
  installments,
  allYearTransactions = [],
  dependentTransactions = [],
  canDelete = false,
  onArchive,
  onUnarchive,
  setShowSharingDialog,
  onAdjustClosingDate,
}: CreditCardDetailViewProps) {
  const { user } = useAuth();
  const { data: sharedCards = [] } = useSharedCreditCards(selectedCard.id);

  const isOwner = selectedCard.user_id === user?.id;
  const [editingClosingDay, setEditingClosingDay] = React.useState(false);
  const [tempClosingDay, setTempClosingDay] = React.useState("");

  const handleStartEditClosing = () => {
    setTempClosingDay((selectedCard.closing_day || 1).toString());
    setEditingClosingDay(true);
  };

  const handleSaveClosing = () => {
    const d = parseInt(tempClosingDay, 10);
    if (d >= 1 && d <= 31 && onAdjustClosingDate) {
      onAdjustClosingDate(d, selectedDate);
    }
    setEditingClosingDay(false);
  };

  const [activeTab, setActiveTab] = React.useState("mine");

  const myTransactions = React.useMemo(() => {
    return allYearTransactions.filter(
      (t) => t.account_id === selectedCard.id || t.destination_account_id === selectedCard.id
    );
  }, [allYearTransactions, selectedCard.id]);

  const dependentTransactionsForCard = React.useMemo(() => {
    return dependentTransactions.filter(
      (t) => t.account_id === selectedCard.id || t.destination_account_id === selectedCard.id
    );
  }, [dependentTransactions, selectedCard.id]);

  const cardTransactions = React.useMemo(() => {
    if (!isOwner || sharedCards.length === 0) return myTransactions;
    if (activeTab === "all") return [...myTransactions, ...dependentTransactionsForCard];
    if (activeTab === "mine") return myTransactions;
    // For a specific dependent:
    return dependentTransactionsForCard.filter((t) => t.user_id === activeTab);
  }, [isOwner, sharedCards.length, activeTab, myTransactions, dependentTransactionsForCard]);

  // Recalculate invoice based on selected tab transactions
  const localInvoiceData = React.useMemo(() => {
    // invoiceData originally comes from props (which is global), but we override it locally for tabs!
    const baseData = getInvoiceData(selectedCard, cardTransactions, selectedDate);
    // Preservar propriedades do invoiceData recebido via prop (como status) caso a gente n├úo tenha calculado
    return { ...baseData, status: invoiceData?.status || baseData.status };
  }, [selectedCard, cardTransactions, selectedDate, invoiceData?.status]);

  const handleExportCard = async (format: "pdf" | "csv", txs: any[], periodLabel: string) => {
    const { exportDetailedCardReportToCSV, exportDetailedCardReportToPDF } =
      await import("@/utils/exportData");
    if (format === "pdf") exportDetailedCardReportToPDF(txs, selectedCard, periodLabel);
    else exportDetailedCardReportToCSV(txs, selectedCard, periodLabel);
  };

  const onBack = () => goBack();

  return (
    <div className="space-y-6 pb-20 animate-fade-in-up">
      {/* Header */}
      <div className="flex items-center gap-4 mb-6">
        <Button variant="ghost" size="icon" onClick={onBack} className="hover:bg-muted">
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex items-center gap-4 flex-1">
          <BankIcon bankId={selectedCard.bank_id} accountName={selectedCard.name} size="lg" />

          <div className="flex flex-col">
            <h1 className="font-display font-bold text-2xl tracking-tight">{selectedCard.name}</h1>
          </div>
        </div>

        {/* Share Button highlighted */}
        {isOwner && (
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  onClick={() => setShowSharingDialog(true)}
                  className="bg-success hover:bg-success text-white font-semibold rounded-xl shadow-md flex items-center justify-center transition-all hover:scale-105 shrink-0 px-3 md:px-4"
                >
                  <Share2 className="h-4 w-4" />
                  <span className="hidden md:inline md:ml-2">Compartilhar</span>
                </Button>
              </TooltipTrigger>
              <TooltipContent className="max-w-xs space-y-2 p-3 bg-card text-card-foreground shadow-premium-sm border-border">
                <p className="font-bold text-sm">Dividindo os Gastos?</p>
                <p className="text-sm text-muted-foreground">
                  Envie um link para o seu parceiro ou familiar para que ele possa acompanhar os
                  lan├ºamentos da fatura e lan├ºar os pr├│prios gastos nesse cart├úo em tempo real!
                </p>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        )}

        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="outline" size="icon" className="rounded-xl border-border shrink-0">
              <Settings className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={() => openEditCardDialog(selectedCard)}>
              <Pencil className="h-4 w-4 mr-2" />
              Editar Cart├úo
            </DropdownMenuItem>

            <DropdownMenuSeparator />
            <DropdownMenuItem
              onClick={() =>
                selectedCard.is_archived ? onUnarchive(selectedCard) : onArchive(selectedCard)
              }
            >
              {selectedCard.is_archived ? (
                <>
                  <RotateCcw className="h-4 w-4 mr-2" />
                  Desarquivar Cart├úo
                </>
              ) : (
                <>
                  <Archive className="h-4 w-4 mr-2" />
                  Arquivar Cart├úo
                </>
              )}
            </DropdownMenuItem>

            {canDelete && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem
                  onClick={() => setDeleteCardConfirm({ isOpen: true, card: selectedCard })}
                  className="text-destructive focus:text-destructive"
                >
                  <Trash2 className="h-4 w-4 mr-2" />
                  Excluir Cart├úo
                </DropdownMenuItem>
              </>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>

      {/* Month Navigation */}
      <div className="flex items-center justify-between bg-muted/30 p-2 rounded-xl">
        <Button
          variant="ghost"
          size="icon"
          onClick={() => changeMonth(-1)}
