            </div>
          </div>

          <div className="flex flex-col items-end shrink-0">
            {/* O helper CardBrandIcon exibe a rede se existir. A prop 'brand' ser├í pega do banco ou fallbacks. Se n├úo houver, exibe mastercard fallback */}
            <CardBrandIcon brand={card.brand || "mastercard"} size="lg" />
          </div>
        </div>
      </div>
    </div>
  );
}

import { CreditCardSummary } from "@/components/credit-cards/CreditCardSummary";
import { CreditCardItem } from "@/components/credit-cards/CreditCardItem";

interface CreditCardsListProps {
  creditCards: any[];
  totalInvoices: number;
  totalDebt: number;
  nextDueDate: number;
  formatCurrency: (value: number) => string;
  getCardInvoice: (card: any) => { value: number; dueDate: Date | null; status: string };
  isLoading: boolean;
  onRefresh: () => void;
  onSelectCard: (card: any) => void;
}

export function CreditCardsList({
  creditCards,
  totalInvoices,
  totalDebt,
  nextDueDate,
  formatCurrency,
  getCardInvoice,
