}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { CurrencyInput } from "@/components/ui/currency-input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { ChevronLeft, ChevronRight, Calendar, DollarSign, Save, Users, Loader2 } from "lucide-react";
import { formatDateISO } from "@/utils/dateUtils";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";

import { useFamilyMembers } from "@/hooks/useFamily";
import { useCategoriesHierarchical } from "@/hooks/useCategories";
import { useCreateTransaction } from "@/hooks/useTransactions";
import { useAuth } from "@/contexts/AuthContext";
import { CategorySelector } from "@/components/transactions/CategorySelector";
import { toast } from "sonner";
import { moneyUtils } from "@/utils/money";
import { logger } from '@/utils/logger';

type CreditCardAccount = any;

interface ImportBillsDialogProps {
  isOpen: boolean;
  onClose: () => void;
  account: CreditCardAccount;
  onImport: (transactions: unknown[]) => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
};

export function ImportBillsDialog({ isOpen, onClose, account, onImport }: ImportBillsDialogProps) {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState("installment");

  // Tab 1: Global state
  const [year, setYear] = useState(new Date().getFullYear());
  const [months, setMonths] = useState<{ date: string; label: string; amount: string; isPast: boolean }[]>([]);

  // Tab 2: Installments state
  const [desc, setDesc] = useState("");
  const [instValue, setInstValue] = useState("");
  const [currentInst, setCurrentInst] = useState("1");
  const [totalInst, setTotalInst] = useState("2");
  
  // New Installment Fields
  const [selectedMonth, setSelectedMonth] = useState(dateFns.format(new Date(), 'yyyy-MM'));
  const [categoryId, setCategoryId] = useState("");
  const [isShared, setIsShared] = useState(false);
  const [assigneeId, setAssigneeId] = useState("");
  const [assigneePercentage, setAssigneePercentage] = useState(50);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const { data: familyMembers = [] } = useFamilyMembers();
  const { data: categories = [] } = useCategoriesHierarchical();
  const createTransaction = useCreateTransaction();

  const availableMembers = familyMembers.filter(m => m.linked_user_id !== user?.id);

  // Gerar lista de meses (12 meses: atual + 11 pr├│ximos)
  const availableMonths = Array.from({ length: 12 }, (_, i) => {
    const date = dateFns.addMonths(new Date(), i);
    return {
      value: dateFns.format(date, 'yyyy-MM'),
      label: dateFns.format(date, 'MMMM yyyy', { locale: ptBR }).replace(/^\w/, c => c.toUpperCase()),
    };
  });

  useEffect(() => {
    if (isOpen) {
      const nextMonths = [];
      const today = new Date();
      
      for (let i = 0; i < 12; i++) {
        const targetDate = new Date(year, i, 1);
        let isPast = false;
        if (year < today.getFullYear() || (year === today.getFullYear() && i < today.getMonth())) {
          isPast = true;
        } else if (year === today.getFullYear() && i === today.getMonth()) {
          const closingDay = account?.closing_day || 1;
          if (today.getDate() >= closingDay) {
            isPast = true;
          }
        }
        const monthName = targetDate.toLocaleDateString('pt-BR', { month: 'long' });
        const label = `${monthName.charAt(0).toUpperCase() + monthName.slice(1)} ${year}`;
        
        nextMonths.push({
          date: formatDateISO(targetDate),
          label,
          amount: '',
          isPast
        });
      }
      setMonths(nextMonths);
    }
  }, [isOpen, year, account]);

  useEffect(() => {
    if (isOpen && availableMembers.length > 0 && !assigneeId) {
      setAssigneeId(availableMembers[0].id);
    }
  }, [isOpen, availableMembers, assigneeId]);

  const handleAmountChange = (index: number, value: string) => {
    if (months[index].isPast) return;
    const newMonths = [...months];
    newMonths[index].amount = value;
    setMonths(newMonths);
  };

  const handleSaveGlobal = () => {
    const transactionsToCreate = months
      .filter(m => m.amount && moneyUtils.parse(m.amount) > 0)
      .map(m => {
        const [y, month] = m.date.split('-').map(Number);
        const closingDay = account.closing_day || 1;
        const transactionDate = new Date(y, month - 1, closingDay);
        
        return {
          date: formatDateISO(transactionDate),
          competence_date: formatDateISO(new Date(y, month - 1, 1)),
          amount: moneyUtils.parse(m.amount),
          type: "EXPENSE",
          description: `Fatura Importada - ${m.label}`,
          account_id: account.id,
          domain: "PERSONAL",
        };
      });

    if (transactionsToCreate.length > 0) {
      onImport(transactionsToCreate);
    }
  };

  const handleSaveInstallments = async () => {
    const valueNum = moneyUtils.parse(instValue.replace(/\./g, '').replace(',', '.')); // in case user types with comma
    const currNum = parseInt(currentInst);
    const totNum = parseInt(totalInst);

    if (!desc || isNaN(valueNum) || valueNum <= 0 || isNaN(currNum) || isNaN(totNum) || currNum > totNum) {
      toast.error("Preencha todos os campos corretamente.");
      return;
    }

    if (isShared && !assigneeId) {
      toast.error("Selecione um membro para compartilhar.");
      return;
    }

    setIsSubmitting(true);

    try {
      const [yearStr, monthStr] = selectedMonth.split('-');
      
      // Criamos a transa├º├úo num dia anterior ao fechamento para que a compet├¬ncia (fatura)
      // caia exatamente no m├¬s selecionado, de acordo com o ciclo do cart├úo.
      const closingDay = account?.closing_day || 1;
      const transactionDate = new Date(Number(yearStr), Number(monthStr) - 1, closingDay - 1);
      const transactionDateStr = formatDateISO(transactionDate);

      // Quantas parcelas vamos criar
      const installmentsToCreate = totNum - currNum + 1;
      const totalRemainingAmount = valueNum * installmentsToCreate;

      const baseTransaction = {
        amount: totalRemainingAmount,
        description: desc,
        date: transactionDateStr,
        type: "EXPENSE" as const,
        account_id: account.id,
        category_id: categoryId || undefined,
        domain: isShared ? ("SHARED" as const) : ("PERSONAL" as const),
        is_installment: true,
        current_installment: currNum,
        total_installments: totNum,
        is_shared: isShared,
        splits: isShared ? [
          {
            member_id: user!.id,
            percentage: 100 - assigneePercentage,
            amount: totalRemainingAmount * ((100 - assigneePercentage) / 100),
          },
          {
            member_id: assigneeId,
            percentage: assigneePercentage,
            amount: totalRemainingAmount * (assigneePercentage / 100),
          }
        ] : undefined
      };

      await createTransaction.mutateAsync(baseTransaction);

      toast.success("Parcelas criadas com sucesso!");
      onClose();
    } catch (error: any) {
      logger.error(error);
      toast.error(error.message || "Erro ao criar parcelas.");
    } finally {
      setIsSubmitting(false);
    }
  };

  // Calcular data da ├║ltima parcela
  let lastInstallmentText = '';
  if (selectedMonth && currentInst && totalInst) {
    const installmentsToCreate = parseInt(totalInst) - parseInt(currentInst) + 1;
    if (installmentsToCreate >= 1) {
      const [year, month] = selectedMonth.split('-').map(Number);
      const baseDate = new Date(year, month - 1, 1);
      const lastDate = dateFns.addMonths(baseDate, installmentsToCreate - 1);
      lastInstallmentText = dateFns.format(lastDate, 'MMMM yyyy', { locale: ptBR }).replace(/^\w/, c => c.toUpperCase());
    }
  }

  // Valores da divis├úo
  const parsedValue = moneyUtils.parse(instValue) || 0;
  const assigneeParcelAmount = (parsedValue * assigneePercentage) / 100;
  const creatorParcelAmount = parsedValue - assigneeParcelAmount;

  if (!isOpen) return null;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-full sm:max-w-2xl !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-3xl sm:!rounded-3xl !rounded-b-none sm:!rounded-b-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b">
        <div className="w-full flex justify-center pt-4 pb-2 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <span>Importar Transa├º├Áes - {account?.name}</span>
          </DialogTitle>
          <DialogDescription>
            Escolha como deseja importar compras para este cart├úo.
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={setActiveTab} className="flex-1 flex flex-col overflow-hidden">
          {/* Aba 'global' removida provisoriamente conforme solicitado */}
          <TabsList className="grid w-full grid-cols-1 hidden">
            <TabsTrigger value="installment">Compra Parcelada</TabsTrigger>
          </TabsList>

          <TabsContent value="global" className="flex-1 overflow-hidden flex flex-col mt-6">
            <div className="flex items-center justify-center gap-4 py-1.5">
              <Button variant="ghost" size="icon" onClick={() => setYear(y => y - 1)}>
                <ChevronLeft className="h-6 w-6" />
              </Button>
              <span className="text-base font-bold font-mono">{year}</span>
              <Button variant="ghost" size="icon" onClick={() => setYear(y => y + 1)}>
                <ChevronRight className="h-6 w-6" />
              </Button>
            </div>
            
            <div className="flex-1 overflow-y-auto space-y-4 py-4 no-scrollbar pr-4">
              {months.map((month, index) => (
                <div key={month.date} className="flex items-center gap-4 p-3 rounded-xl border border-border">
                  <div className="flex items-center gap-4 flex-1">
                    <Calendar className="h-5 w-5 text-muted-foreground" />
                    <span className="font-medium text-sm">{month.label}</span>
                  </div>
                  <div className="w-32">
                    {month.isPast ? (
                      <span className="text-sm text-muted-foreground">Encerrado</span>
                    ) : (
                      <CurrencyInput
                        placeholder="0,00"
                        value={month.amount}
                        onChange={(val) => handleAmountChange(index, val)}
                        currency={account?.currency || "BRL"}
                        className="h-10 text-sm"
                      />
                    )}
                  </div>
                </div>
              ))}
            </div>

            <DialogFooter className="mt-6 pt-6 border-t">
              <Button variant="outline" onClick={onClose} disabled={isSubmitting}>Cancelar</Button>
              <Button 
                onClick={handleSaveGlobal}
                disabled={!months.some(m => m.amount && moneyUtils.parse(m.amount) > 0) || isSubmitting}
              >
                <Save className="h-5 w-5 mr-2" />
                Salvar Faturas
              </Button>
            </DialogFooter>
          </TabsContent>

          <TabsContent value="installment" className="flex-1 overflow-y-auto overflow-x-hidden flex flex-col mt-4 space-y-4 no-scrollbar pr-2 pb-4">
            <div className="space-y-4 px-1">
              <div className="space-y-2">
                <Label>Descri├º├úo da Compra</Label>
                <Input placeholder="Ex: TV Nova" value={desc} onChange={e => setDesc(e.target.value)} />
              </div>
              
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>M├¬s da Pr├│xima Parcela</Label>
                  <Select value={selectedMonth} onValueChange={setSelectedMonth}>
                    <SelectTrigger>
                      <SelectValue placeholder="Selecione o m├¬s" />
                    </SelectTrigger>
                    <SelectContent>
                      {availableMonths.map((m) => (
                        <SelectItem key={m.value} value={m.value}>
                          {m.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Valor da Parcela</Label>
                  <CurrencyInput 
                    value={instValue} 
                    onChange={setInstValue} 
                    currency={account?.currency || "BRL"} 
                    placeholder="0,00" 
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Parcela Atual (Ex: 3)</Label>
                  <Input type="number" inputMode="decimal" value={currentInst} onChange={e => setCurrentInst(e.target.value)} min="1" />
                </div>
                <div className="space-y-2">
                  <Label>Total de Parcelas (Ex: 10)</Label>
                  <Input type="number" inputMode="decimal" value={totalInst} onChange={e => setTotalInst(e.target.value)} min="2" />
                </div>
              </div>

              {lastInstallmentText && (
                <div className="flex items-start gap-2 p-3 bg-muted/50 rounded-2xl border border-border/50">
                  <Calendar className="h-5 w-5 text-muted-foreground shrink-0 mt-0.5" />
                  <div className="text-sm">
                    <p className="font-medium">├Ültima Parcela</p>
                    <p className="text-muted-foreground">A ├║ltima parcela ser├í em <strong>{lastInstallmentText}</strong>.</p>
                  </div>
                </div>
              )}

              <div className="space-y-2">
                <Label>Categoria</Label>
                <CategorySelector
                  categories={categories}
                  value={categoryId}
                  onValueChange={setCategoryId}
                  type="expense"
                />
              </div>

              <div className="flex items-center justify-between p-4 bg-muted/30 rounded-2xl border border-border">
                <div className="space-y-0.5">
                  <Label className="text-base flex items-center gap-2">
                    <Users className="h-4 w-4" />
                    ├ë uma compra compartilhada?
                  </Label>
                  <p className="text-sm text-muted-foreground">
                    O valor total fica no cart├úo, mas a outra pessoa ficar├í com saldo devedor para voc├¬ nas Contas Compartilhadas.
                  </p>
                </div>
                <Switch 
                  checked={isShared}
                  onCheckedChange={setIsShared}
                />
              </div>

              {isShared && (
                <div className="p-4 bg-primary/5 rounded-2xl border border-primary/20 space-y-4 animate-in fade-in slide-in-from-top-2">
                  <div className="space-y-2">
                    <Label>Com quem voc├¬ dividiu?</Label>
                    <Select value={assigneeId} onValueChange={setAssigneeId}>
                      <SelectTrigger>
                        <SelectValue placeholder="Selecione um membro" />
                      </SelectTrigger>
                      <SelectContent>
                        {availableMembers.map((member) => (
                          <SelectItem key={member.id} value={member.id}>
                            {member.name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <Label>Porcentagem da outra pessoa ({assigneePercentage}%)</Label>
                      <span className="text-sm font-medium text-primary">
                        {formatCurrency(assigneeParcelAmount)} / parcela
                      </span>
                    </div>
                    <input
                      type="range"
                      min="1"
                      max="99"
                      value={assigneePercentage}
                      onChange={(e) => setAssigneePercentage(Number(e.target.value))}
                      className="w-full accent-primary"
                    />
                    <div className="flex justify-between text-sm text-muted-foreground">
                      <span>Sua parte: {formatCurrency(creatorParcelAmount)} ({(100 - assigneePercentage).toFixed(0)}%)</span>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <DialogFooter className="mt-auto pt-4 border-t">
              <Button variant="outline" onClick={onClose} disabled={isSubmitting}>Cancelar</Button>
              <Button onClick={handleSaveInstallments} disabled={!desc || !instValue || moneyUtils.parse(instValue) <= 0 || isSubmitting}>
                {isSubmitting ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
                Importar Parcelas
              </Button>
            </DialogFooter>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Calculator, ChevronDown, ChevronUp } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { NumericFormat } from "react-number-format";
import { cn } from "@/lib/utils";

interface InstallmentSimulatorProps {
  creditLimit: number | null;
  currentBalance: number;
  formatCurrency: (v: number) => string;
}

export function InstallmentSimulator({ creditLimit, currentBalance, formatCurrency }: InstallmentSimulatorProps) {
  const [open, setOpen] = useState(false);
  const [purchaseAmount, setPurchaseAmount] = useState(0);
  const [installments, setInstallments] = useState(12);
  const [interestRate, setInterestRate] = useState(2.99);

  const available = Math.max(0, (creditLimit ?? 0) - Math.abs(currentBalance));
  const monthly = purchaseAmount > 0 ? purchaseAmount / installments : 0;
  const totalWithInterest = purchaseAmount > 0 && installments > 1
    ? purchaseAmount * Math.pow(1 + interestRate / 100, installments)
    : purchaseAmount;
  const monthlyWithInterest = totalWithInterest / installments;
  const exceedsLimit = purchaseAmount > available;

  return (
    <div className="mt-4 pt-3 border-t border-white/10">
      <button
        className="w-full flex items-center justify-between text-xs font-bold uppercase tracking-wider opacity-80 hover:opacity-100 transition-opacity"
        onClick={() => setOpen(v => !v)}
      >
        <span className="flex items-center gap-1.5">
          <Calculator className="w-3.5 h-3.5" />
          Simulador de Parcelamento
        </span>
        {open ? <ChevronUp className="w-3.5 h-3.5" /> : <ChevronDown className="w-3.5 h-3.5" />}
      </button>

      {open && (
        <div className="mt-3 space-y-4 bg-black/20 rounded-2xl p-4 border border-white/10">
          {/* Purchase amount */}
          <div className="space-y-1.5">
            <Label className="text-xs text-white/70">Valor da compra</Label>
            <NumericFormat
              value={purchaseAmount || ""}
              onValueChange={(v) => setPurchaseAmount(v.floatValue ?? 0)}
              thousandSeparator="."
              decimalSeparator=","
              decimalScale={2}
              prefix="R$ "
              placeholder="R$ 0,00"
              className="w-full bg-white/10 border border-white/20 rounded-xl px-3 py-2 text-white text-sm placeholder:text-white/30 focus:outline-none focus:border-white/50"
            />
            {exceedsLimit && (
              <p className="text-xs text-red-300">ÔÜá Excede o limite dispon├¡vel ({formatCurrency(available)})</p>
            )}
          </div>

          {/* Installments */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label className="text-xs text-white/70">Parcelas</Label>
              <span className="text-sm font-bold text-white">{installments}x</span>
            </div>
            <Slider
              min={1}
              max={24}
              step={1}
              value={[installments]}
              onValueChange={([v]) => setInstallments(v)}
              className="accent-white"
            />
            <div className="flex justify-between text-xs text-white/40">
              <span>1x</span><span>6x</span><span>12x</span><span>18x</span><span>24x</span>
            </div>
          </div>

          {/* Interest rate */}
          {installments > 1 && (
            <div className="space-y-1.5">
              <div className="flex items-center justify-between">
                <Label className="text-xs text-white/70">Juros/m├¬s</Label>
                <NumericFormat
                  value={interestRate}
                  onValueChange={(v) => setInterestRate(v.floatValue ?? 0)}
                  decimalSeparator=","
                  decimalScale={2}
                  suffix="%"
                  className="w-20 text-right bg-white/10 border border-white/20 rounded-lg px-2 py-1 text-white text-xs focus:outline-none focus:border-white/50"
                />
              </div>
            </div>
          )}

          {/* Result */}
          {purchaseAmount > 0 && (
            <div className={cn(
              "rounded-xl p-3 space-y-2 border",
              exceedsLimit ? "bg-red-500/20 border-red-400/30" : "bg-white/10 border-white/15"
            )}>
              <div className="flex justify-between items-center">
                <span className="text-xs text-white/70">Parcela</span>
                <span className="font-bold text-white text-sm">
                  {installments}x {formatCurrency(installments === 1 ? purchaseAmount : monthlyWithInterest)}
                </span>
              </div>
              {installments > 1 && interestRate > 0 && (
                <>
                  <div className="flex justify-between items-center">
                    <span className="text-xs text-white/60">Sem juros</span>
                    <span className="text-xs text-white/60">{formatCurrency(monthly)}/m├¬s</span>
                  </div>
                  <div className="flex justify-between items-center pt-1 border-t border-white/10">
                    <span className="text-xs text-white/70">Total com juros</span>
                    <span className="text-xs font-semibold text-orange-300">{formatCurrency(totalWithInterest)}</span>
                  </div>
                </>
              )}
              {installments === 1 && (
                <p className="text-xs text-white/50 text-center">Pagamento ├á vista</p>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Globe, Wallet, ChevronRight, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { FormField } from "@/components/ui/form-field";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { AmountInput } from "@/components/ui/amount-input";
import { BankIcon } from "@/components/financial/BankIcon";
import { moneyUtils } from "@/utils/money";

const currencies = [
  { value: "USD", label: "USD - D├│lar Americano", symbol: "$" },
  { value: "EUR", label: "EUR - Euro", symbol: "Ôé¼" },
  { value: "GBP", label: "GBP - Libra Esterlina", symbol: "┬ú" },
  { value: "CAD", label: "CAD - D├│lar Canadense", symbol: "C$" },
  { value: "AUD", label: "AUD - D├│lar Australiano", symbol: "A$" },
  { value: "JPY", label: "JPY - Iene Japon├¬s", symbol: "┬Ñ" },
  { value: "CHF", label: "CHF - Franco Su├¡├ºo", symbol: "CHF" },
];

const getCurrencyFlag = (currency: string) => {
  switch (currency) {
    case 'USD': return '­ƒç║­ƒç©';
    case 'EUR': return '­ƒç¬­ƒç║';
    case 'GBP': return '­ƒç¼­ƒçº';
    case 'CAD': return '­ƒç¿­ƒçª';
    case 'AUD': return '­ƒçª­ƒç║';
    case 'JPY': return '­ƒç»­ƒçÁ';
    case 'CHF': return '­ƒç¿­ƒç¡';
    default: return '­ƒçº­ƒçÀ';
  }
};

type CreditCardAccount = any;

interface PayInvoiceDialogProps {
  isOpen: boolean;
  onClose: () => void;
  card: CreditCardAccount & { currency?: string; is_international?: boolean };
  invoiceTotal: number;
  accounts: any[];
  onPay: (fromAccountId: string, amount: number, exchangeRate?: number) => void;
}

export function PayInvoiceDialog({ isOpen, onClose, card, invoiceTotal, accounts, onPay }: PayInvoiceDialogProps) {
  const [step, setStep] = useState(1);
  const [amountToPay, setAmountToPay] = useState(invoiceTotal.toString());
  const [selectedAccountId, setSelectedAccountId] = useState("");
  const [exchangeRate, setExchangeRate] = useState("");
  const [showExchangeField, setShowExchangeField] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);

  React.useEffect(() => {
    if (invoiceTotal > 0 && isOpen && step === 1) {
      setAmountToPay(invoiceTotal.toString());
      setStep(1);
    }
  }, [invoiceTotal, isOpen, step]);

  const cardCurrency = card.currency || 'BRL';
  const isInternationalCard = card.is_international || cardCurrency !== 'BRL';

  const compatibleAccounts = (accounts || []).filter(acc => {
    if (isInternationalCard) {
      return acc.currency === cardCurrency || acc.currency === 'BRL' || !acc.currency;
    }
    return !acc.is_international && (acc.currency === 'BRL' || !acc.currency);
  });

  const selectedAccount = accounts.find(a => a.id === selectedAccountId);
  const needsExchange = isInternationalCard && selectedAccount && 
    (selectedAccount.currency === 'BRL' || (!selectedAccount.currency && !selectedAccount.is_international));

  React.useEffect(() => {
    setShowExchangeField(needsExchange);
    if (!needsExchange) {
      setExchangeRate("");
    }
  }, [needsExchange]);

  const formatCurrencyValue = (value: number, currency: string = 'BRL') => {
    const symbol = currencies.find(c => c.value === currency)?.symbol || 
      (currency === 'BRL' ? 'R$' : currency);
    
    if (currency === 'BRL') {
      return new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);
    }
    return `${symbol} ${value.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const currentAmountToPay = moneyUtils.parse(amountToPay) || 0;

  const calculatedBrlAmount = needsExchange && exchangeRate 
    ? currentAmountToPay * moneyUtils.parse(exchangeRate) 
    : currentAmountToPay;

  const stepTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

  React.useEffect(() => {
    return () => {
      if (stepTimeoutRef.current) clearTimeout(stepTimeoutRef.current);
    };
  }, []);

  const handlePay = async () => {
    setIsProcessing(true);
    try {
      if (needsExchange && exchangeRate) {
        await onPay(selectedAccountId, currentAmountToPay, moneyUtils.parse(exchangeRate));
      } else {
        await onPay(selectedAccountId, currentAmountToPay);
      }
      if (stepTimeoutRef.current) clearTimeout(stepTimeoutRef.current);
      stepTimeoutRef.current = setTimeout(() => {
        setStep(1);
      }, 500);
    } finally {
      setIsProcessing(false);
    }
  };

  const variants = {
    enter: (direction: number) => ({ x: direction > 0 ? 50 : -50, opacity: 0 }),
    center: { x: 0, opacity: 1 },
    exit: (direction: number) => ({ x: direction < 0 ? 50 : -50, opacity: 0 })
  };

  const [direction, setDirection] = useState(1);

  const nextStep = () => {
    setDirection(1);
    setStep(2);
  };

  const prevStep = () => {
    setDirection(-1);
    setStep(1);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b overflow-hidden bg-background">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-5 pt-2 pb-2 text-left shrink-0 border-b border-border/40">
          <DialogTitle className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
              <Wallet className="w-4 h-4 text-primary" />
            </div>
            <div className="flex flex-col">
              <span className="text-sm font-bold">Pagar Fatura</span>
              <span className="text-xs font-medium text-muted-foreground flex items-center gap-2">
                <BankIcon bankId={card.bank_id} size="xs" />
                {card.name}
              </span>
            </div>
          </DialogTitle>
          <DialogDescription>
            {step === 1 ? 'Defina o valor a pagar' : 'Escolha a conta de origem'}
          </DialogDescription>
          <div className="flex gap-2 mt-3">
            <div className={`h-2 flex-1 rounded-full ${step >= 1 ? 'bg-primary' : 'bg-muted'}`} />
            <div className={`h-2 flex-1 rounded-full ${step >= 2 ? 'bg-primary' : 'bg-muted'}`} />
          </div>
        </DialogHeader>
        
        <div className="flex-1 min-h-0 overflow-y-auto">
          <AnimatePresence mode="wait" custom={direction} initial={false}>
            {step === 1 && (
              <motion.div 
                key="step1"
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ type: "spring", stiffness: 300, damping: 30 }}
                className="p-4 flex flex-col min-h-full"
              >
                <div className="flex-1 space-y-4">
                  <div className="p-4 rounded-xl bg-gradient-to-br from-primary/10 to-transparent border border-primary/20 flex flex-col items-center justify-center text-center">
                    <span className="text-xs font-medium text-muted-foreground mb-0.5 uppercase tracking-wider">Total da fatura</span>
                    <span className="text-2xl font-display font-bold text-foreground">
                      {formatCurrencyValue(invoiceTotal, cardCurrency)}
                    </span>
                  </div>

                  <div className="space-y-3">
                    <AmountInput
                      label="Qual valor deseja pagar agora?"
                      value={amountToPay}
                      onChange={setAmountToPay}
                      currency={cardCurrency}
                      currencySymbol={currencies.find(c => c.value === cardCurrency)?.symbol || (cardCurrency === 'BRL' ? 'R$' : cardCurrency)}
                      size="md"
                      autoFocus
                    />
                    {currentAmountToPay < invoiceTotal && currentAmountToPay > 0 && (
                      <p className="text-sm text-warning font-medium bg-warning/10 p-2 rounded-lg border border-warning/20">
                        ÔÜá´©Å Pagamento parcial: restar├í {formatCurrencyValue(invoiceTotal - currentAmountToPay, cardCurrency)} para o pr├│ximo m├¬s.
                      </p>
                    )}
                  </div>
                </div>

                <div className="pt-4 mt-auto shrink-0">
                  <Button 
                    onClick={nextStep} 
                    className="w-full text-md font-semibold rounded-xl shadow-lg shadow-primary/20"
                    disabled={currentAmountToPay <= 0}
                  >
                    Continuar <ChevronRight className="w-5 h-5 ml-1" />
                  </Button>
                </div>
              </motion.div>
            )}

            {step === 2 && (
              <motion.div 
                key="step2"
                custom={direction}
                variants={variants}
                initial="enter"
                animate="center"
                exit="exit"
                transition={{ type: "spring", stiffness: 300, damping: 30 }}
                className="p-4 flex flex-col min-h-full"
              >
                <div className="flex-1 space-y-4">
                  <FormField label="De onde sair├í o dinheiro?" htmlFor="pay-account">
                    <Select value={selectedAccountId} onValueChange={setSelectedAccountId}>
                      <SelectTrigger id="pay-account" className="rounded-xl bg-background/50 border-white/10">
                        <SelectValue placeholder="Selecione a conta de origemÔÇª" />
                      </SelectTrigger>
                      <SelectContent>
                        {compatibleAccounts.map(acc => {
                          const accCurrency = acc.currency || 'BRL';
                          const willNeedExchange = isInternationalCard && accCurrency === 'BRL';
                          
                          return (
                            <SelectItem key={acc.id} value={acc.id} className="py-3">
                              <div className="flex items-center gap-3 w-full">
                                <BankIcon bankId={acc.bank_id} size="sm" />
                                <div className="flex flex-col text-left">
                                  <span className="font-medium flex items-center gap-2">
                                    {acc.name}
                                    <span className="text-sm bg-background border border-border/50 px-1 rounded shadow-sm">{getCurrencyFlag(accCurrency)}</span>
                                  </span>
                                  <span className="text-sm text-muted-foreground flex gap-1">
                                    Saldo: {formatCurrencyValue(acc.balance, accCurrency)}
                                    {willNeedExchange && <span className="text-warning font-medium">(c├ómbio)</span>}
                                  </span>
                                </div>
                              </div>
                            </SelectItem>
                          );
                        })}
                      </SelectContent>
                    </Select>
                    
                    {compatibleAccounts.length === 0 && (
                      <p className="text-sm text-destructive font-medium p-3 bg-destructive/10 rounded-lg">
                        Nenhuma conta compat├¡vel. Crie uma conta em {cardCurrency} ou use uma conta BRL com c├ómbio.
                      </p>
                    )}
                  </FormField>

                  {showExchangeField && (
                    <div className="space-y-3 p-4 rounded-xl border border-warning/30 bg-warning/5 shadow-inner">
                      <div className="flex items-center gap-2 text-sm font-semibold text-warning">
                        <Globe className="h-4 w-4" />
                        <span>Convers├úo de Moeda Necess├íria</span>
                      </div>
                      <FormField label={`Taxa de c├ómbio (${cardCurrency} ÔåÆ BRL)`} htmlFor="pay-exchange-rate">
                        <Input type="number" inputMode="decimal"
                          id="pay-exchange-rate"
                          name="pay-exchange-rate"
                          step="0.0001"
                          placeholder="Ex: 5,50ÔÇª"
                          className="bg-background font-mono"
                          value={exchangeRate}
                          onChange={(e) => setExchangeRate(e.target.value)}
                          autoComplete="off"
                        />
                      </FormField>
                      {exchangeRate && (
                        <div className="flex justify-between items-center pt-2 border-t border-border/50">
                          <span className="text-sm text-muted-foreground">D├®bito em BRL:</span>
                          <span className="font-mono font-bold text-foreground">
                            {formatCurrencyValue(calculatedBrlAmount, 'BRL')}
                          </span>
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <div className="pt-4">
                  <Button 
                    onClick={handlePay}
                    disabled={!selectedAccountId || currentAmountToPay <= 0 || (showExchangeField && !exchangeRate) || isProcessing}
                    className="w-full text-md font-semibold rounded-xl shadow-lg shadow-primary/20 hover:-translate-y-0.5 transition-all"
                  >
                    {isProcessing ? (
                      <>
                        <Loader2 className="h-5 w-5 mr-2 animate-spin" />
                        ProcessandoÔÇª
                      </>
                    ) : (
                      <>
                        <Wallet className="h-5 w-5 mr-2" />
                        Confirmar Pagamento
                      </>
                    )}
                  </Button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { useFamilyMembers } from "@/hooks/useFamily";
import { useSharedCreditCards, useInviteSharedCard, useRevokeSharedCard } from "@/hooks/useSharedCreditCards";
import { Users, UserPlus, X, ShieldAlert } from "lucide-react";
import { UserAvatar } from "@/components/ui/user-avatar";
import { useAuth } from "@/contexts/AuthContext";
import { Input } from "@/components/ui/input";
import { CurrencyInput } from "@/components/ui/currency-input";

interface ShareCardDialogProps {
  isOpen: boolean;
  onClose: () => void;
  card: any;
}

export function ShareCardDialog({ isOpen, onClose, card }: ShareCardDialogProps) {
  const { user } = useAuth();
  const { data: familyMembers = [], isLoading: membersLoading } = useFamilyMembers();
  const { data: sharedCards = [], isLoading: sharedLoading } = useSharedCreditCards(card?.id);
  const inviteMutation = useInviteSharedCard();
  const revokeMutation = useRevokeSharedCard();
  const [selectedMemberForInvite, setSelectedMemberForInvite] = useState<any>(null);
  const [inviteLimit, setInviteLimit] = useState<string>("");

  if (!card) return null;

  // Filtra membros da fam├¡lia que t├¬m usu├írio logado (linked_user_id)
  const availableMembers = familyMembers.filter(m => m.linked_user_id && m.status === 'active' && m.linked_user_id !== user?.id);

  const confirmInvite = () => {
    if (!selectedMemberForInvite || !inviteLimit || Number(inviteLimit) <= 0) return;
    inviteMutation.mutate({
      accountId: card.id,
      userId: selectedMemberForInvite.linked_user_id,
      cardName: card.name,
      creditLimit: Number(inviteLimit)
    });
    setSelectedMemberForInvite(null);
    setInviteLimit("");
  };

  const handleOpenInviteLimit = (member: any) => {
    setSelectedMemberForInvite(member);
    setInviteLimit("");
  };

  const handleRevoke = (inviteId: string) => {
    revokeMutation.mutate(inviteId);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-md w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <DialogHeader className="px-5 pt-5 pb-2 sm:px-6 sm:pt-6">
          <DialogTitle className="flex items-center gap-2">
            <Users className="w-5 h-5 text-primary" />
            Compartilhar Cart├úo
          </DialogTitle>
          <DialogDescription>
            Convide membros da sua fam├¡lia para compartilhar o limite e a fatura do cart├úo <b>{card.name}</b>.
            As compras de cada um ser├úo isoladas para maior privacidade.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6 px-5 pb-5 sm:px-6 sm:pb-6 overflow-y-auto flex-1">
          <div className="bg-warning/8 p-3 flex gap-3 rounded-lg border border-warning/20">
            <ShieldAlert className="w-5 h-5 text-warning shrink-0" />
            <p className="text-sm text-warning">
              O convidado n├úo poder├í editar o Vencimento nem o Fechamento da fatura. Ao fechar a fatura, ele far├í o acerto do valor devido para voc├¬.
            </p>
          </div>

          <div>
            <h4 className="text-sm font-semibold mb-3">Membros Compartilhados / Convites</h4>
            {sharedLoading ? (
              <div className="text-center text-sm text-muted-foreground py-2">Carregando...</div>
            ) : sharedCards.length === 0 ? (
              <div className="text-center text-sm text-muted-foreground py-4 border border-dashed rounded-lg">
                Nenhum membro compartilhando este cart├úo.
              </div>
            ) : (
              <div className="space-y-2">
                {sharedCards.map((sc) => (
                  <div key={sc.id} className="flex items-center justify-between p-2 border rounded-lg bg-card">
                    <div className="flex items-center gap-3">
                      <UserAvatar name={sc.user?.full_name || 'Usu├írio'} avatarUrl={sc.user?.avatar_url} iconId={sc.user?.avatar_icon} colorId={sc.user?.avatar_color} size="sm" />
                      <div>
                        <p className="text-sm font-medium">{sc.user?.full_name}</p>
                        <p className="text-sm text-muted-foreground">
                          {sc.status === 'PENDING' ? 'Pendente' : sc.status === 'ACCEPTED' ? 'Aceito' : 'Recusado'}
                        </p>
                      </div>
                    </div>
                    <Button variant="ghost" size="icon" onClick={() => handleRevoke(sc.id)} title="Remover acesso">
                      <X className="w-4 h-4 text-destructive" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div>
            <h4 className="text-sm font-semibold mb-3">Convidar Membro da Fam├¡lia</h4>
            {membersLoading ? (
              <div className="text-center text-sm text-muted-foreground py-2">Carregando membros...</div>
            ) : availableMembers.length === 0 ? (
              <div className="text-center text-sm text-muted-foreground py-4 border border-dashed rounded-lg">
                Nenhum membro ativo encontrado na sua fam├¡lia.
              </div>
            ) : (
              <div className="space-y-2">
                {availableMembers.map((member) => {
                  const isAlreadyShared = sharedCards.some(sc => sc.user_id === member.linked_user_id);
                  if (isAlreadyShared) return null;

                  return (
                    <div key={member.id} className="flex items-center justify-between p-2 border border-transparent hover:border-border rounded-lg transition-colors">
                      <div className="flex items-center gap-3">
                        <UserAvatar name={member.name} avatarUrl={member.avatar_url || undefined} iconId={member.avatar_icon || undefined} colorId={member.avatar_color || undefined} size="sm" />
                        <div>
                          <p className="text-sm font-medium">{member.name}</p>
                          <p className="text-sm text-muted-foreground">{member.role === 'admin' ? 'Administrador' : 'Membro'}</p>
                        </div>
                      </div>
                      <div className="flex flex-col sm:flex-row items-end sm:items-center gap-2">
                        <Button 
                          size="sm" 
                          onClick={() => handleOpenInviteLimit(member)} 
                          className="h-8"
                          variant="secondary"
                        >
                          <UserPlus className="w-4 h-4 mr-2" />
                          Convidar
                        </Button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      </DialogContent>

      <Dialog open={!!selectedMemberForInvite} onOpenChange={(o) => !o && setSelectedMemberForInvite(null)}>
        <DialogContent className="max-w-[320px] w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
          <div className="flex flex-col items-center gap-4 text-center">
            <div className="bg-primary/10 p-4 rounded-full">
              <UserPlus className="w-8 h-8 text-primary" />
            </div>
            <div>
              <h3 className="font-semibold text-base">Definir Limite</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Qual ser├í o limite para <b>{selectedMemberForInvite?.name}</b> usar neste cart├úo?
              </p>
            </div>
            
            <CurrencyInput 
              placeholder="R$ 0,00" 
              className="w-full h-12 text-center text-base font-medium" 
              value={inviteLimit} 
              onChange={(val) => setInviteLimit(val)} 
              currency={card?.currency || "BRL"}
            />

            <div className="flex items-center gap-2 w-full mt-2">
              <Button variant="outline" className="flex-1" onClick={() => setSelectedMemberForInvite(null)}>
                Cancelar
              </Button>
              <Button 
                className="flex-1" 
                onClick={confirmInvite}
                disabled={inviteMutation.isPending || !inviteLimit || Number(inviteLimit) <= 0}
              >
                Confirmar
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </Dialog>
  );
}

import { Link } from "react-router-dom";
import { ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { BankIcon } from "@/components/financial/BankIcon";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { memo } from "react";
import { logger } from "@/utils/logger";

interface DashboardInvoicesProps {
  creditCardsWithBalance: any[];
  formatCurrency: (value: number) => string;
}

export const DashboardInvoices = memo(function DashboardInvoices({
  creditCardsWithBalance,
  formatCurrency,
}: DashboardInvoicesProps) {
  const cardIds = creditCardsWithBalance.map((c) => c.id);

  // Buscar transa├º├Áes dos ├║ltimos 4 meses para os cart├Áes de cr├®dito
  const { data: txs = [], isLoading } = useQuery({
    queryKey: ["dashboard-cards-transactions", cardIds],
    queryFn: async () => {
      if (cardIds.length === 0) return [];

      // Pegar a partir de 4 meses atr├ís para cobrir faturas antigas em aberto
      const fourMonthsAgo = dateFns.subMonths(new Date(), 4);
      const startDateStr = dateFns.format(fourMonthsAgo, "yyyy-MM-01");

      const { data, error } = await supabase
        .from("transactions")
        .select("id, account_id, destination_account_id, type, amount, competence_date, date")
        .or(`account_id.in.(${cardIds.join(",")}),destination_account_id.in.(${cardIds.join(",")})`)
        .gte("competence_date", startDateStr);

      if (error) {
        logger.error("Erro ao buscar transa├º├Áes dos cart├Áes no dashboard", error);
        return [];
      }
      return data;
    },
    enabled: cardIds.length > 0,
    staleTime: 30 * 1000,
  });

  if (creditCardsWithBalance.length === 0) return null;
  if (isLoading) return null;

  // Processar cada cart├úo e calcular a fatura pendente real mais antiga
  const cardsWithPendingInvoices = creditCardsWithBalance
    .map((card) => {
      const dueDay = card.due_day || 10;
      const closingDay = card.closing_day || 1;
      const today = new Date();

      // Avaliar os ├║ltimos 4 meses at├® o m├¬s atual
      const monthsToEvaluate: Date[] = [];
      for (let i = 4; i >= 0; i--) {
        monthsToEvaluate.push(dateFns.subMonths(today, i));
      }

      let targetInvoiceMonth: Date | null = null;
      let targetInvoiceTotal = 0;
      let daysUntilDue = 0;
      let isOverdue = false;

      for (const refMonth of monthsToEvaluate) {
        const year = refMonth.getFullYear();
        const month = refMonth.getMonth();

        // Filtrar transa├º├Áes da compet├¬ncia refMonth para esse card
        const monthTxs = txs.filter((t) => {
          if (t.account_id !== card.id && t.destination_account_id !== card.id) return false;
          if (t.type === "TRANSFER" && t.destination_account_id !== card.id) return false;

          // Tratar timezone com parse seguro
          const txDate = t.competence_date
            ? dateFns.parse(t.competence_date, "yyyy-MM-dd", new Date())
            : new Date(t.date);
          return txDate.getFullYear() === year && txDate.getMonth() === month;
        });

        // Calcular total da fatura (Gastos - Recebimentos/Pagamentos)
        const total = monthTxs.reduce((acc, t) => {
          const amt = Number(t.amount);
          if (t.type === "EXPENSE") return acc + amt;
          if (t.type === "INCOME") return acc - amt;
          if (t.type === "TRANSFER" && t.destination_account_id === card.id) return acc - amt;
          if (t.type === "TRANSFER" && t.account_id === card.id) return acc + amt;
          return acc;
        }, 0);

        // Se a fatura tiver saldo pendente devedor
        if (total > 0.01) {
          // S├│ mostrar como pendente se o fechamento do m├¬s j├í passou
          // (fatura do m├¬s atual s├│ fica pendente DEPOIS de fechar)
          const isCurrentMonth =
            refMonth.getMonth() === today.getMonth() &&
            refMonth.getFullYear() === today.getFullYear();
          const isPastMonth = refMonth < dateFns.startOfMonth(today);

          if (isCurrentMonth && today.getDate() < closingDay) {
            continue; // Cart├úo ainda n├úo fechou este m├¬s ÔÇö n├úo mostrar
          }
          const dueDateStr = `${year}-${String(month + 1).padStart(2, "0")}-${String(dueDay).padStart(2, "0")}`;
          let dueDate = dateFns.parse(dueDateStr, "yyyy-MM-dd", new Date());
          if (dueDay <= closingDay) {
            dueDate = dateFns.addMonths(dueDate, 1);
          }

          const diffDays = dateFns.differenceInCalendarDays(dueDate, today);

          // Pega a mais antiga que encontrar
          if (!targetInvoiceMonth) {
            targetInvoiceMonth = refMonth;
            targetInvoiceTotal = total;
            daysUntilDue = diffDays;
            isOverdue = diffDays < 0;
          }
        }
      }

      return {
        ...card,
        targetInvoiceMonth,
        targetInvoiceTotal,
        daysUntilDue,
        isOverdue,
      };
    })
    // Filtrar apenas cart├Áes que possuem faturas realmente pendentes
    .filter((c) => c.targetInvoiceMonth !== null && c.targetInvoiceTotal > 0.01);

  if (cardsWithPendingInvoices.length === 0) return null;

  return (
    <div className="space-y-3 animate-fade-in-up stagger-4">
      <h2 className="text-xs uppercase tracking-widest text-muted-foreground font-medium">
        Faturas pendentes
      </h2>
      <div className="space-y-2">
        {cardsWithPendingInvoices.map((card, index) => {
          const invoiceMonth = card.targetInvoiceMonth!;
          const invoiceDateParam = `${invoiceMonth.getFullYear()}-${String(invoiceMonth.getMonth() + 1).padStart(2, "0")}`;

          // Formata o m├¬s de refer├¬ncia (compet├¬ncia) em formato de exibi├º├úo eleg├¡vel (ex: Maio/2026)
          const monthLabel = dateFns.format(invoiceMonth, "MMMM/yyyy", { locale: ptBR });
          const capitalizedMonthLabel = monthLabel.charAt(0).toUpperCase() + monthLabel.slice(1);

          return (
            <Link
              key={card.id}
              to={`/cartoes?cardId=${card.id}&invoiceDate=${invoiceDateParam}`}
              className={cn(
                "group flex items-center justify-between py-4 border-b border-border/40 last:border-0 hover:bg-card/30 transition-colors animate-stagger -mx-2 px-2 rounded-xl",
                `stagger-${index + 1}`
              )}
            >
              <div className="flex items-center gap-2 md:gap-4 min-w-0 flex-1">
                <BankIcon bankId={card.bank_id} accountName={card.name} size="md" />
                <div className="min-w-0 flex-1">
                  <p className="font-medium text-sm md:text-base truncate">Fatura {card.name}</p>
                  <p
                    className={cn(
                      "text-xs md:text-sm truncate font-medium",
                      card.isOverdue ? "text-negative" : "text-muted-foreground"
                    )}
                  >
                    {card.isOverdue
                      ? `Atrasada ${Math.abs(card.daysUntilDue)} dia${Math.abs(card.daysUntilDue) !== 1 ? "s" : ""} ÔÇó ${capitalizedMonthLabel}`
                      : card.daysUntilDue === 0
                        ? `Vence hoje ÔÇó ${capitalizedMonthLabel}`
                        : `Vence em ${card.daysUntilDue} dia${card.daysUntilDue !== 1 ? "s" : ""} ÔÇó ${capitalizedMonthLabel}`}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-1 md:gap-2 shrink-0">
                <span className="text-destructive font-mono font-semibold text-sm md:text-base whitespace-nowrap">
                  -{formatCurrency(card.targetInvoiceTotal)}
                </span>
                <ChevronRight className="h-4 w-4 text-muted-foreground group-hover:translate-x-1 transition-transform" />
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
});

import { memo } from "react";
import { Link } from "react-router-dom";
import { CreditCard, Users, Wallet, Plane } from "lucide-react";
import { cn } from "@/lib/utils";

interface ShortcutProps {
