import { useMemo, memo } from "react";
import { Link } from "react-router-dom";
import { Repeat2, ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { calculateNextOccurrence } from "@/services/recurrenceService";
import { usePrivacy } from "@/contexts/PrivacyContext";
import { moneyUtils } from "@/utils/money";
import * as dateFns from "date-fns";

const MAX_ITEMS = 3;

function urgencyClass(daysUntil: number) {
  if (daysUntil <= 3) return "text-warning";
  return "text-muted-foreground";
}

function daysLabel(daysUntil: number) {
  if (daysUntil === 0) return "Hoje";
  if (daysUntil === 1) return "Amanh├ú";
  if (daysUntil <= 7) return `${daysUntil} dias`;
  return dateFns.format(dateFns.addDays(dateFns.startOfDay(new Date()), daysUntil), "dd/MM");
}

export const DashboardUpcomingRecurring = memo(function DashboardUpcomingRecurring() {
  const { user } = useAuth();
  const { isPrivate } = usePrivacy();

  const { data: transactions = [] } = useQuery({
    queryKey: ["upcoming-recurring", user?.id],
    enabled: !!user,
    queryFn: async () => {
      if (!user) return [];
      const { data, error } = await supabase
        .from("transactions")
        .select(
          `
          *,
          category:categories(id, name, icon)
        `
        )
        .eq("user_id", user.id)
        .eq("is_recurring", true)
        .not("recurrence_pattern", "is", null)
        .is("deleted_at", null)
        .order("date", { ascending: false })
        .limit(50);
      if (error) throw error;
      return data || [];
    },
  });

  const today = useMemo(() => dateFns.startOfDay(new Date()), []);

  const upcoming = useMemo(() => {
    return transactions
      .filter((t) => t.is_recurring && t.recurrence_pattern)
      .map((tx) => {
        const lastDate = (tx as any).last_generated_date
          ? new Date((tx as any).last_generated_date + "T12:00:00")
          : new Date(tx.date + "T12:00:00");

        let nextDate = calculateNextOccurrence(
          lastDate,
          tx.recurrence_pattern!,
          (tx as any).recurrence_day ?? null
        );
        let safety = 0;
        while (dateFns.isBefore(dateFns.startOfDay(nextDate), today) && safety < 1000) {
          nextDate = calculateNextOccurrence(nextDate, tx.recurrence_pattern!, (tx as any).recurrence_day ?? null);
          safety++;
        }

        const daysUntil = dateFns.differenceInCalendarDays(dateFns.startOfDay(nextDate), today);

        return { tx, daysUntil };
      })
      .filter(({ daysUntil }) => daysUntil >= 0)
      .sort((a, b) => a.daysUntil - b.daysUntil)
      .slice(0, MAX_ITEMS);
  }, [transactions, today]);

  if (upcoming.length === 0) return null;

  return (
    <div className="rounded-2xl border border-border/60 bg-card overflow-hidden">
      <div className="flex items-center gap-2.5 px-4 pt-4 pb-3 border-b border-border/40">
        <div className="w-8 h-8 rounded-xl bg-primary/10 flex items-center justify-center shrink-0">
          <Repeat2 className="w-4 h-4 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="font-bold text-sm">Recorr├¬ncias pr├│ximas</h3>
          <p className="text-xs text-muted-foreground">Pr├│ximas cobran├ºas autom├íticas</p>
        </div>
        <Link
          to="/transacoes"
          state={{ tab: "proximas" }}
          className="text-xs text-primary font-medium hover:underline flex items-center gap-1 shrink-0"
        >
          Ver mais <ArrowRight className="h-3 w-3" />
        </Link>
      </div>

      <div className="divide-y divide-border/40">
        {upcoming.map(({ tx, daysUntil }) => (
          <div
            key={tx.id}
            className="flex items-center gap-3 px-4 py-3 hover:bg-muted/30 transition-colors"
          >
            <span className="text-xl shrink-0">{tx.category?.icon ?? "­ƒöü"}</span>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-semibold truncate">{tx.description}</p>
              <p className={cn("text-xs font-medium", urgencyClass(daysUntil))}>
                {daysLabel(daysUntil)}
              </p>
            </div>
            <span
              className={cn(
                "text-sm font-bold font-mono tabular-nums shrink-0",
                tx.type === "EXPENSE" ? "text-destructive" : "text-positive"
              )}
            >
              {isPrivate
                ? "ÔÇóÔÇóÔÇóÔÇó"
                : (tx.type === "EXPENSE" ? "-" : "+") +
                  moneyUtils.format(Number(tx.amount), tx.currency || "BRL")}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
});

import { memo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { useFamilyMembers } from '@/hooks/useFamily';
import { moneyUtils } from '@/utils/money';
import { usePrivacy } from '@/contexts/PrivacyContext';
import { cn } from '@/lib/utils';
import { Users, TrendingUp, TrendingDown, ArrowRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import { rpcWithRetry } from '@/utils/rpcWithRetry';


export const FamilyBalancePanel = memo(function FamilyBalancePanel() {
  const { user } = useAuth();
  const { isPrivate } = usePrivacy();
  const { data: members = [], isLoading: membersLoading } = useFamilyMembers(true);

  const { data: sharedBalances, isLoading: balancesLoading } = useQuery({
    queryKey: ['shared-balances', user?.id],
    queryFn: async () => {
      if (!user) return [];
      try {
        const data = await rpcWithRetry('get_current_shared_debts', { p_user_id: user.id });
        return data as Array<{
          member_id: string;
          currency: string;
          total_credits: number;
          total_debits: number;
          net_balance: number;
        }>;
      } catch {
        return [];
      }
    },
    enabled: !!user,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });

  // NOVO: Busca o m├¬s com a transa├º├úo mais recente para direcionar o link "Ver tudo"
  const { data: targetDebtMonth } = useQuery({
    queryKey: ['target-debt-month', user?.id],
    queryFn: async () => {
      if (!user) return null;
      try {
        const data = await rpcWithRetry('get_shared_invoice_data', { p_user_id: user.id }) as any;
        const txList = data?.transactions;
        if (Array.isArray(txList) && txList.length > 0) {
          const unsettled = txList.filter((tx: any) => {
            const txDate = tx.competence_date || tx.date;
            if (!txDate) return false;
            // Check splits for unsettled debts
            if (tx.transaction_splits && Array.isArray(tx.transaction_splits)) {
               return tx.transaction_splits.some((s: any) => !s.is_settled && !s.settled_by_creditor);
            }
            return tx.is_settled === false;
          });

          if (unsettled.length > 0) {
            unsettled.sort((a, b) => {
              const dateA = a.competence_date || a.date;
              const dateB = b.competence_date || b.date;
              return new Date(dateB).getTime() - new Date(dateA).getTime();
            });
            const selectedDate = unsettled[0].competence_date || unsettled[0].date;
            return selectedDate.substring(0, 7); // 'YYYY-MM'
          }

          // Fallback: se n├úo encontrar transa├º├Áes n├úo liquidadas (por algum motivo),
          // pega o m├¬s da transa├º├úo compartilhada mais recente.
          const validTx = txList.filter((tx: any) => tx.competence_date || tx.date);
          if (validTx.length > 0) {
            validTx.sort((a, b) => {
              const dateA = a.competence_date || a.date;
              const dateB = b.competence_date || b.date;
              return new Date(dateB).getTime() - new Date(dateA).getTime();
            });
            const selectedDate = validTx[0].competence_date || validTx[0].date;
            return selectedDate.substring(0, 7); // 'YYYY-MM'
          }
        }
        return null;
      } catch {
        return null;
      }
    },
    enabled: !!user,
    staleTime: 60 * 1000,
  });

  // S├│ mostrar se h├í membros de fam├¡lia com linked_user_id (membros reais)
  const linkedMembers = members.filter(m => m.linked_user_id && m.linked_user_id !== user?.id);
  if (membersLoading || balancesLoading) return null;
  if (linkedMembers.length === 0) return null;
  if (!sharedBalances || sharedBalances.length === 0) return null;

  // Agrupa saldos por membro
  const balanceByMember = new Map<string, { credits: number; debits: number; net: number }>();
  sharedBalances.forEach(b => {
    const existing = balanceByMember.get(b.member_id);
    if (existing) {
      existing.credits += Number(b.total_credits);
      existing.debits += Number(b.total_debits);
      existing.net += Number(b.net_balance);
    } else {
      balanceByMember.set(b.member_id, {
        credits: Number(b.total_credits),
        debits: Number(b.total_debits),
        net: Number(b.net_balance),
      });
    }
  });

  const membersWithBalance = linkedMembers
    .map(m => ({ member: m, balance: balanceByMember.get(m.id) }))
    .filter(x => x.balance && (x.balance.credits > 0 || x.balance.debits > 0));

  if (membersWithBalance.length === 0) return null;

  const linkTo = targetDebtMonth ? `/compartilhados?month=${targetDebtMonth}` : `/compartilhados`;

  return (
    <div className="p-4 rounded-2xl border border-border bg-card space-y-3 animate-fade-in">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="p-1.5 rounded-lg bg-primary/10">
            <Users className="h-4 w-4 text-primary" />
          </div>
          <h3 className="text-sm font-bold uppercase tracking-widest text-muted-foreground">
            Saldo com a Fam├¡lia
          </h3>
        </div>
        <Link
          to={linkTo}
          className="text-xs text-primary flex items-center gap-1 hover:underline"
        >
          Ver tudo <ArrowRight className="h-3 w-3" />
        </Link>
      </div>

      <div className="space-y-2">
        {membersWithBalance.map(({ member, balance }) => {
          if (!balance) return null;
          const isPositive = balance.net >= 0;
          return (
            <div
              key={member.id}
              className="flex items-center justify-between p-3 rounded-xl bg-muted/30 border border-border/50"
            >
              <div className="flex items-center gap-3">
                <div className="w-9 h-9 rounded-full bg-primary/10 flex items-center justify-center text-sm font-bold text-primary">
                  {member.name.charAt(0).toUpperCase()}
                </div>
                <div>
                  <p className="text-sm font-semibold leading-none">{member.name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {isPositive ? 'Te deve' : 'Voc├¬ deve'}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2">
                {isPositive ? (
                  <TrendingUp className="h-4 w-4 text-success" />
                ) : (
                  <TrendingDown className="h-4 w-4 text-destructive" />
                )}
                <span
                  className={cn(
                    'text-sm font-bold',
                    isPrivate && 'blur-md opacity-50 select-none',
                    isPositive ? 'text-success' : 'text-destructive'
                  )}
                >
                  {isPrivate ? 'ÔÇóÔÇóÔÇóÔÇóÔÇó' : moneyUtils.format(Math.abs(balance.net), 'BRL')}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
});

