  const [foundUser, setFoundUser] = useState<{ id: string; full_name: string | null } | null>(null);

  useEffect(() => {
    if (user && sharingScope === "specific_trip") {
      supabase
        .from("trip_members")
        .select(`
          trip_id,
          trips:trip_id (
            id,
            name,
            start_date,
            end_date,
            destination
          )
        `)
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .then(({ data }) => {
          if (data) {
            const userTrips = data
              .map(item => item.trips)
              .filter(trip => trip !== null)
              .map(trip => ({
                id: trip.id,
                name: trip.name,
                start_date: trip.start_date,
                end_date: trip.end_date,
                destination: trip.destination
              }));
            setTrips(userTrips);
          } else {
            setTrips([]);
          }
        });
    }
  }, [user, sharingScope]);

  useEffect(() => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    
    if (!email || !emailRegex.test(email.trim())) {
      setUserExists(null);
      setFoundUser(null);
      return;
    }

    const timer = setTimeout(async () => {
      setIsChecking(true);
      
      try {
        const { data } = await supabase
          .from("profiles")
          .select("id, full_name, email")
          .ilike("email", email.trim())
          .maybeSingle();

        if (data) {
          setUserExists(true);
          setFoundUser({ 
            id: data.id, 
            full_name: data.full_name || data.email.split('@')[0]
          });
          if (!name) {
            setName(data.full_name || data.email.split('@')[0]);
          }
        } else {
          setUserExists(false);
          setFoundUser(null);
        }
      } catch (error) {
        setUserExists(null);
        setFoundUser(null);
      } finally {
        setIsChecking(false);
      }
    }, 1500);

    return () => clearTimeout(timer);
  }, [email, name]);

  const handleSubmit = async () => {
    if (tab === 'contact' && onAddContact) {
      await onAddContact({ name, email: email || undefined });
    } else {
      await onInvite({ 
        name, 
        email, 
        role,
        sharingScope: showAdvanced ? sharingScope : "all",
        scopeStartDate: sharingScope === "date_range" ? scopeStartDate : undefined,
        scopeEndDate: sharingScope === "date_range" ? scopeEndDate : undefined,
        scopeTripId: sharingScope === "specific_trip" ? scopeTripId : undefined,
      });
    }
    handleClose(false);
  };

  const handleClose = (isOpen: boolean) => {
    if (!isOpen) {
      setName("");
      setEmail("");
      setRole("editor");
      setSharingScope("all");
      setScopeStartDate("");
      setScopeEndDate("");
      setScopeTripId("");
      setShowAdvanced(false);
      setUserExists(null);
      setFoundUser(null);
      setTab('family');
    }
    onOpenChange(isOpen);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="w-full sm:max-w-2xl !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0 border-b border-border/40">
          <DialogTitle>{tab === 'family' ? 'Convidar membro' : 'Adicionar contato'}</DialogTitle>
          <DialogDescription>
            {tab === 'family'
              ? (userExists 
                ? "Usu├írio encontrado! Ser├í enviada uma solicita├º├úo." 
                : "Adicione algu├®m para compartilhar finan├ºas")
              : "Contatos aparecem no formul├írio de transa├º├úo mas n├úo t├¬m acesso ├á fam├¡lia"
            }
          </DialogDescription>
        </DialogHeader>

        {/* Tab toggle */}
        <div className="px-6 pt-3 pb-1 shrink-0">
          <div className="flex gap-1 p-1 rounded-xl bg-muted">
            <button
              type="button"
              onClick={() => setTab('family')}
              className={cn(
                "flex-1 py-2 text-xs font-medium rounded-lg transition-all flex items-center justify-center gap-1.5",
                tab === 'family' ? "bg-background shadow-sm text-foreground" : "text-muted-foreground"
              )}
            >
              <Users className="h-3.5 w-3.5" />
              Fam├¡lia
            </button>
            <button
              type="button"
              onClick={() => setTab('contact')}
              className={cn(
                "flex-1 py-2 text-xs font-medium rounded-lg transition-all flex items-center justify-center gap-1.5",
                tab === 'contact' ? "bg-background shadow-sm text-foreground" : "text-muted-foreground"
              )}
            >
              <UserCircle2 className="h-3.5 w-3.5" />
              Contato
            </button>
          </div>
        </div>
        
        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar space-y-4">
          <div className="space-y-4 mt-4">
            <FormField label="Email" htmlFor="invite-email">
              <div className="relative">
                <Input
                  id="invite-email"
                  name="invite-email"
                  type="email"
                  placeholder="email@exemplo.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  autoComplete="email"
                  autoCapitalize="none"
                  spellCheck={false}
                  className={cn(
                    "pr-10 h-12 rounded-xl",
                    userExists === true && "border-positive focus-visible:ring-positive",
                    userExists === false && "border-warning focus-visible:ring-warning"
                  )}
                />
                <div className="absolute right-3 top-1/2 -translate-y-1/2">
                  {isChecking && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
                  {!isChecking && userExists === true && <Check className="h-4 w-4 text-positive" />}
                  {!isChecking && userExists === false && <X className="h-4 w-4 text-warning" />}
                </div>
              </div>
              {userExists === true && foundUser?.full_name && (
                <p className="text-sm text-positive flex items-center gap-1">
                  <Check className="h-3 w-3" />
                  Usu├írio cadastrado: {foundUser.full_name}
                </p>
              )}
              {userExists === false && (
                <p className="text-sm text-muted-foreground">
                  Usu├írio n├úo cadastrado. Os dados ficar├úo salvos localmente.
                </p>
              )}
            </FormField>

            <FormField label="Nome" htmlFor="invite-name">
              <Input
                id="invite-name"
                name="invite-name"
                placeholder="Nome do membroÔÇª"
                value={name}
                onChange={(e) => setName(e.target.value)}
                autoComplete="name"
                autoCapitalize="words"
                className="h-12 rounded-xl"
              />
            </FormField>

            {tab === 'family' && (
            <FormField label="Permiss├úo" htmlFor="invite-role">
              <Select value={role} onValueChange={(v) => setRole(v as FamilyRole)}>
                <SelectTrigger id="invite-role" className="h-12 rounded-xl">
                  <SelectValue placeholder="SelecioneÔÇª" />
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  <SelectItem value="admin">
                    <div className="flex flex-col items-start py-1">
                      <span>Administrador</span>
                      <span className="text-sm text-muted-foreground">Acesso total</span>
                    </div>
                  </SelectItem>
                  <SelectItem value="editor">
                    <div className="flex flex-col items-start py-1">
                      <span>Editor</span>
                      <span className="text-sm text-muted-foreground">Pode criar e editar</span>
                    </div>
                  </SelectItem>
                  <SelectItem value="viewer">
                    <div className="flex flex-col items-start py-1">
                      <span>Visualizador</span>
                      <span className="text-sm text-muted-foreground">Apenas visualiza├º├úo</span>
                    </div>
                  </SelectItem>
                </SelectContent>
              </Select>
            </FormField>
            )}

            {tab === 'family' && (
            <Collapsible open={showAdvanced} onOpenChange={setShowAdvanced} className="border border-border/50 rounded-xl overflow-hidden bg-muted/10">
              <CollapsibleTrigger asChild>
                <Button variant="ghost" className="gap-2 w-full justify-between h-12 px-4 hover:bg-muted/20">
                  <div className="flex items-center gap-2 font-semibold">
                    <Settings className="h-4 w-4" />
                    Op├º├Áes Avan├ºadas
                  </div>
                  <ChevronDown className={cn("h-4 w-4 transition-transform", showAdvanced && "rotate-180")} />
                </Button>
              </CollapsibleTrigger>
              <CollapsibleContent className="space-y-4 p-4 border-t border-border/50">
                <FormField label="Escopo de Compartilhamento" htmlFor="invite-scope">
                  <Select value={sharingScope} onValueChange={(v) => setSharingScope(v as SharingScope)}>
                    <SelectTrigger id="invite-scope" className="h-12 rounded-xl">
                      <SelectValue placeholder="SelecioneÔÇª" />
                    </SelectTrigger>
                    <SelectContent className="rounded-xl">
                      <SelectItem value="all">
                        <div className="flex flex-col items-start py-1">
                          <span>Tudo</span>
                          <span className="text-sm text-muted-foreground">Compartilhar todas as transa├º├Áes</span>
                        </div>
                      </SelectItem>
                      <SelectItem value="trips_only">
                        <div className="flex flex-col items-start py-1">
                          <span>­ƒº│ Apenas Viagens</span>
                          <span className="text-sm text-muted-foreground">Apenas transa├º├Áes de viagens</span>
                        </div>
                      </SelectItem>
                      <SelectItem value="date_range">
                        <div className="flex flex-col items-start py-1">
                          <span>­ƒôà Per├¡odo Espec├¡fico</span>
                          <span className="text-sm text-muted-foreground">Transa├º├Áes em um per├¡odo</span>
                        </div>
                      </SelectItem>
                      <SelectItem value="specific_trip">
                        <div className="flex flex-col items-start py-1">
                          <span>­ƒÄ» Viagem Espec├¡fica</span>
                          <span className="text-sm text-muted-foreground">Apenas uma viagem</span>
                        </div>
                      </SelectItem>
                    </SelectContent>
                  </Select>
                </FormField>

                {sharingScope === "date_range" && (
                  <>
                    <FormField label="Data In├¡cio" htmlFor="invite-start">
                      <Input
                        id="invite-start"
                        name="invite-start"
                        type="date"
                        value={scopeStartDate}
                        onChange={(e) => setScopeStartDate(e.target.value)}
                        autoComplete="off"
                        className="h-12 rounded-xl"
                      />
                    </FormField>
                    <FormField label="Data Fim" htmlFor="invite-end">
                      <Input
                        id="invite-end"
                        name="invite-end"
                        type="date"
                        value={scopeEndDate}
                        onChange={(e) => setScopeEndDate(e.target.value)}
                        autoComplete="off"
                        className="h-12 rounded-xl"
                      />
                    </FormField>
                    <p className="text-sm text-muted-foreground bg-background p-2 rounded-lg border">
                      ­ƒôå Transa├º├Áes antigas do per├¡odo permanecer├úo vis├¡veis
                    </p>
                  </>
                )}

                {sharingScope === "specific_trip" && (
                  <FormField label="Viagem" htmlFor="invite-trip">
                    <Select value={scopeTripId} onValueChange={setScopeTripId}>
                      <SelectTrigger id="invite-trip" className="h-12 rounded-xl">
                        <SelectValue placeholder="Selecione uma viagemÔÇª" />
                      </SelectTrigger>
                      <SelectContent className="rounded-xl">
                        {trips.map((trip) => (
                          <SelectItem key={trip.id} value={trip.id} className="py-2">
                            <div className="flex flex-col items-start">
                              <span>{trip.name}</span>
                              {trip.destination && (
                                <span className="text-sm text-muted-foreground">
                                  ­ƒôì {trip.destination}
                                </span>
                              )}
                            </div>
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    {trips.length === 0 && (
                      <p className="text-sm text-warning bg-warning/10 p-2 rounded-lg">
                        ÔÜá´©Å Nenhuma viagem encontrada. Crie ou participe de uma viagem primeiro.
                      </p>
                    )}
                    {trips.length > 0 && (
                      <p className="text-sm text-muted-foreground bg-background p-2 rounded-lg border">
                        ­ƒº│ Apenas transa├º├Áes desta viagem ser├úo compartilhadas
                      </p>
                    )}
                  </FormField>
                )}

                {sharingScope === "trips_only" && (
                  <p className="text-sm text-muted-foreground bg-background p-2 rounded-lg border">
                    Ô£ê´©Å Apenas transa├º├Áes vinculadas a viagens ser├úo compartilhadas
                  </p>
                )}
              </CollapsibleContent>
            </Collapsible>
            )}

            {tab === 'family' && userExists === true && (
              <div className="p-3 rounded-xl bg-positive/10 border border-positive/20">
                <p className="text-sm text-positive">
                  Ô£ô Solicita├º├úo ser├í enviada. O usu├írio precisa aceitar para criar o v├¡nculo.
                </p>
              </div>
            )}
          </div>

          <div className="pt-4 flex gap-3">
            <Button type="button" variant="outline" className="flex-1 rounded-xl h-12" onClick={() => handleClose(false)}>
              Cancelar
            </Button>
            <Button
              className="flex-1 rounded-xl h-12 font-bold"
              onClick={handleSubmit}
              disabled={
                !email.trim() ||
                !name.trim() ||
                (tab === 'family' ? isPending : isContactPending)
              }
            >
              {(tab === 'family' ? isPending : isContactPending) ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              {tab === 'family' ? 'Enviar Convite' : 'Salvar Contato'}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { AmountInput } from '@/components/ui/amount-input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useGoals } from '@/hooks/useGoals';
import { useAccounts } from '@/hooks/useAccounts';
import { useGoalHistory } from '@/hooks/useGoalHistory';
import { Goal } from '@/types/database';
import { TrendingDown, TrendingUp } from 'lucide-react';
import { cn } from '@/lib/utils';
import { logger } from '@/utils/logger';
import { moneyUtils } from '@/utils/money';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { AreaChart, Area, XAxis, YAxis, Tooltip as ReTooltip, ResponsiveContainer } from 'recharts';
import confetti from 'canvas-confetti';

interface GoalContributeDialogProps {
  isOpen: boolean;
  onClose: () => void;
  goal: Goal;
}

export function GoalContributeDialog({ isOpen, onClose, goal }: GoalContributeDialogProps) {
  const { contributeToGoal } = useGoals();
  const { data: accounts } = useAccounts();
  const { data: history = [] } = useGoalHistory(goal.id, goal.name);

  const [amount, setAmount] = useState('');
  const [type, setType] = useState<'add' | 'withdraw'>('add');
  const [accountId, setAccountId] = useState(goal.linked_account_id || 'none');

  // Detectar moeda da meta via conta vinculada
  const linkedAccount = accounts?.find(a => a.id === goal.linked_account_id);
  const goalCurrency = linkedAccount?.currency || 'BRL';
  const currencySymbol = goalCurrency === 'BRL' ? 'R$' : goalCurrency === 'USD' ? '$' : goalCurrency;

  // Filtrar contas que tenham a mesma moeda da meta
  const filteredAccounts = accounts?.filter(acc => acc.currency === goalCurrency) || [];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const value = Number(amount);
    if (!value || value <= 0) return;

    try {
      // O hook contributeToGoal agora lida com a cria├º├úo da transa├º├úo internamente
      // de forma robusta, suportando moedas e tipos (income/expense)
      contributeToGoal(
        { 
          id: goal.id, 
          amount: type === 'add' ? value : -value,
          accountId: accountId !== 'none' ? accountId : undefined,
          description: type === 'add' 
            ? `Contribui├º├úo para Meta: ${goal.name}` 
            : `Resgate da Meta: ${goal.name}`
        },
        { onSuccess: () => {
          if (type === 'add' && (goal.current_amount + value) >= goal.target_amount) {
            confetti({
              particleCount: 150,
              spread: 70,
              origin: { y: 0.6 },
              colors: ['#22c55e', '#3b82f6', '#f59e0b', '#ec4899']
            });
          }
          onClose();
        } }
      );
    } catch (error) {
      logger.error("Erro ao contribuir para meta:", error);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="w-full sm:w-[400px] max-w-sm !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle className="text-base font-display font-bold">
            Movimentar: {goal.name}
          </DialogTitle>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto px-6 hide-scrollbar">
          {/* Gr├ífico de evolu├º├úo */}
          {history.length >= 2 && (
            <div className="mb-4">
              <p className="text-xs text-muted-foreground uppercase font-bold tracking-widest mb-2">Evolu├º├úo do saldo</p>
              <ResponsiveContainer width="100%" height={100}>
                <AreaChart data={history} margin={{ top: 4, right: 4, left: 0, bottom: 0 }}>
                  <defs>
                    <linearGradient id="goalGrad" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="hsl(var(--primary))" stopOpacity={0.3} />
                      <stop offset="95%" stopColor="hsl(var(--primary))" stopOpacity={0} />
                    </linearGradient>
                  </defs>
                  <XAxis dataKey="date" hide />
                  <YAxis hide domain={['auto', 'auto']} />
                  <ReTooltip
                    content={({ active, payload }) => {
                      if (!active || !payload?.length) return null;
                      const p = payload[0].payload;
                      return (
                        <div className="bg-popover border border-border rounded-lg px-3 py-1.5 text-xs shadow-lg">
                          <p className="text-muted-foreground">{format(new Date(p.date), "dd MMM yyyy", { locale: ptBR })}</p>
                          <p className="font-bold text-foreground">{moneyUtils.format(p.cumulative, 'BRL')}</p>
                        </div>
                      );
                    }}
                  />
                  <Area type="monotone" dataKey="cumulative" stroke="hsl(var(--primary))" strokeWidth={2} fill="url(#goalGrad)" dot={false} />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          )}

          <form id="contribute-form" onSubmit={handleSubmit} className="space-y-6">
            <div className="flex bg-secondary p-1 rounded-xl border border-border">
            <button
              type="button"
              onClick={() => setType('add')}
              className={cn(
                "flex-1 flex items-center justify-center gap-2 py-2 px-4 rounded-lg text-sm font-medium transition-all duration-200",
                type === 'add' ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <TrendingUp className="w-4 h-4 text-success" />
              Adicionar
            </button>
            <button
              type="button"
              onClick={() => setType('withdraw')}
              className={cn(
                "flex-1 flex items-center justify-center gap-2 py-2 px-4 rounded-lg text-sm font-medium transition-all duration-200",
                type === 'withdraw' ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <TrendingDown className="w-4 h-4 text-destructive" />
              Retirar
            </button>
          </div>

          <div className="space-y-2">
            <AmountInput
              label="Valor"
              value={amount}
              onChange={setAmount}
              currency={goalCurrency}
              size="md"
              textColorClass={type === 'withdraw' ? 'text-destructive' : 'text-positive'}
              autoFocus
            />
            {goalCurrency !== 'BRL' && (
              <p className="text-sm text-warning font-medium text-center">
                Opera├º├úo em moeda estrangeira ({goalCurrency})
              </p>
            )}
          </div>

          <div className="space-y-2">
            <Label>Debitar/Creditar na Conta (Opcional)</Label>
            <Select value={accountId} onValueChange={setAccountId}>
              <SelectTrigger>
                <SelectValue placeholder="N├úo registrar transa├º├úo" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">N├úo registrar na conta (apenas virtual)</SelectItem>
                {filteredAccounts.map((acc) => (
                  <SelectItem key={acc.id} value={acc.id}>
                    {acc.name} ({acc.currency})
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

        </form>
        </div>
        <div className="shrink-0 flex gap-3 px-6 py-4 border-t border-border bg-background">
          <Button type="button" variant="outline" className="flex-1 h-11" onClick={onClose}>
            Cancelar
          </Button>
          <Button type="submit" form="contribute-form" className="flex-1 h-11 font-bold">
            Confirmar
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Edit, Trash2, Clock, ArrowRightLeft } from 'lucide-react';
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { Asset } from '../../types/database';
import { getBrokerById } from '@/lib/brokers';

interface AssetCardProps {
  asset: Asset;
  index: number;
  onEdit: (asset: Asset) => void;
  onDelete: (asset: Asset) => void;
  onShowHistory: (asset: Asset) => void;
  onTransact: (asset: Asset) => void;
  formatAssetValue: (value: number, currency: string) => string;
}

export function AssetCard({
  asset,
  index,
  onEdit,
  onDelete,
  onShowHistory,
  onTransact,
  formatAssetValue
}: AssetCardProps) {
  const totalInvested = (asset.quantity || 0) * (asset.purchase_price || 0);
  const currentValue = (asset.quantity || 0) * ((asset.current_price && asset.current_price > 0) ? asset.current_price : asset.purchase_price || 0);
  const pnl = currentValue - totalInvested;
  const pnlPercent = totalInvested > 0 ? (pnl / totalInvested) * 100 : 0;
  const isPositive = pnl >= 0;
  const hasCurrentPrice = asset.current_price && asset.current_price > 0;

  return (
    <div
      className={cn(
        "bg-card border border-border p-6 rounded-2xl relative overflow-hidden group hover-lift card-animated animate-stagger",
        `stagger-${(index % 5) + 1}`
      )}
    >
      <div className="absolute top-2 right-2 p-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <Button variant="ghost" size="icon" onClick={() => onEdit(asset)} className="h-8 w-8">
          <Edit className="w-4 h-4 text-muted-foreground" />
        </Button>
        <Button variant="ghost" size="icon" onClick={() => onDelete(asset)} className="h-8 w-8 hover:text-destructive">
          <Trash2 className="w-4 h-4 text-muted-foreground" />
        </Button>
      </div>

      <div className="flex items-center gap-4 mb-6">
        <div className="w-12 h-12 rounded-xl bg-secondary flex items-center justify-center text-foreground font-display font-bold text-base shadow-sm group-hover:scale-110 transition-transform">
          {asset.ticker ? asset.ticker.substring(0, 2) : asset.type.substring(0, 2)}
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <h3 className="text-base font-display font-bold text-foreground leading-tight truncate">{asset.ticker || asset.name}</h3>
            <span className={cn(
              "text-[8px] px-1.5 py-0.5 rounded-full font-bold tracking-tighter uppercase",
              asset.location === 'BR' ? "bg-success/12 text-success" : "bg-accent/15 text-accent"
            )}>
              {asset.location}
            </span>
          </div>
          <p className="text-sm text-muted-foreground truncate flex items-center gap-1">
            {asset.type} {asset.sector && <span className="opacity-50">ÔÇó {asset.sector}</span>}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4 mb-6">
        <div>
          <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest flex items-center gap-2">
            Valor Total
            {asset.ticker && (
              <span className="relative flex h-2 w-2" title="Cota├º├úo em tempo real">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-success"></span>
              </span>
            )}
          </p>
          <p className="text-base font-mono font-bold text-foreground">
            {formatAssetValue(currentValue, asset.currency || 'BRL')}
          </p>
        </div>
        <div className="text-right">
          <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest">Retorno</p>
          {!hasCurrentPrice ? (
            <p className="text-sm text-muted-foreground font-medium mt-1">Aguardando API</p>
          ) : (
            <div className="flex flex-col items-end">
              <p className={cn(
                "text-sm font-mono font-bold",
                isPositive ? "text-success" : "text-destructive"
              )}>
                {isPositive ? '+' : ''}{formatAssetValue(pnl, asset.currency || 'BRL')}
              </p>
              <p className={cn(
                "text-xs font-bold px-1.5 py-0.5 rounded-sm mt-0.5",
                isPositive ? "bg-success/12 text-success" : "bg-destructive/12 text-destructive"
              )}>
                {isPositive ? 'Ôû▓' : 'Ôû╝'} {Math.abs(pnlPercent).toFixed(2)}%
              </p>
            </div>
          )}
        </div>
      </div>

      <div className="flex justify-between items-center pt-4 border-t border-border mt-2">
        <div className="text-sm text-muted-foreground flex flex-col gap-0.5">
          <div className="flex items-center gap-1">
            Qtd: <span className="text-foreground font-medium font-mono">{(asset.quantity || 0).toFixed(8).replace(/\.?0+$/, '')}</span>
            <span className="opacity-30">┬À</span>
            PM: <span className="text-foreground font-medium font-mono">{formatAssetValue(asset.purchase_price || 0, asset.currency || 'BRL')}</span>
            {hasCurrentPrice && (
              <>
                <span className="opacity-30">┬À</span>
                Atual: <span className="text-foreground font-medium font-mono">{formatAssetValue(asset.current_price || 0, asset.currency || 'BRL')}</span>
              </>
            )}
          </div>
          {((asset as any).broker_name || (asset as any).broker_id) && (
            <span className="text-[11px] opacity-60">
              {(asset as any).broker_name || getBrokerById((asset as any).broker_id)?.shortName}
            </span>
          )}
        </div>
        <div className="flex gap-2 items-center">
          <Button
            variant="ghost"
            size="icon"
            onClick={() => onShowHistory(asset)}
            className="h-8 w-8 text-muted-foreground hover:text-primary"
            title="Ver hist├│rico"
          >
            <Clock className="w-4 h-4" />
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={() => onTransact(asset)}
            className="gap-2 h-8 px-3 text-sm"
          >
            <ArrowRightLeft className="w-3.5 h-3.5" />
            Operar
          </Button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { AmountInput } from '@/components/ui/amount-input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useAssets } from '@/hooks/useAssets';
import { useAccounts } from '@/hooks/useAccounts';
import { Asset } from '@/types/database';
import { BR_BROKERS, ABROAD_BROKERS, getBrokerById, isCustomBroker } from '@/lib/brokers';
import { searchAbroadAssets, AbroadAsset } from '@/lib/abroadAssets';
import { searchCryptoAssets } from '@/lib/cryptoAssets';
import { useB3TickersSearch, B3Ticker } from '@/hooks/useB3TickersSearch';
import { Globe, Building2, Search, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';
import { moneyUtils } from "@/utils/money";

interface AssetFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  asset?: Asset | null;
}

const CURRENCIES: { code: string; label: string; symbol: string }[] = [
  { code: 'BRL', label: 'Real Brasileiro', symbol: 'R$' },
  { code: 'USD', label: 'D├│lar Americano', symbol: 'US$' },
  { code: 'EUR', label: 'Euro', symbol: 'Ôé¼' },
  { code: 'GBP', label: 'Libra Esterlina', symbol: '┬ú' },
];

const ASSET_TYPES = [
  { value: 'STOCK', label: 'A├º├Áes' },
  { value: 'ETF', label: 'ETF' },
  { value: 'FII', label: 'FII - Fundo Imobili├írio' },
  { value: 'REIT', label: 'REIT (Exterior)' },
  { value: 'BOND', label: 'Renda Fixa' },
  { value: 'CRYPTO', label: 'Criptomoedas' },
  { value: 'FUND', label: 'Fundo de Investimento' },
  { value: 'OTHER', label: 'Outros' },
];

const SECTORS_BR = [
  'Petr├│leo e G├ís', 'Minera├º├úo', 'Bancos', 'Seguros', 'Varejo',
  'Alimentos e Bebidas', 'Papel e Celulose', 'Siderurgia', 'Energia El├®trica',
  'Saneamento', 'Telecomunica├º├Áes', 'Sa├║de', 'Educa├º├úo', 'Tecnologia',
  'Imobili├írio', 'Log├¡stica', 'Transporte', 'Holdings', '├ìndice', 'Criptomoedas', 'Outros',
];

export function AssetFormDialog({ isOpen, onClose, asset }: AssetFormDialogProps) {
  const { createAsset, updateAsset, isCreating, isUpdating } = useAssets();
  const { data: accounts } = useAccounts();

  // Localiza├º├úo e moeda
  const [location, setLocation] = useState<'BR' | 'ABROAD'>('BR');
  const [currency, setCurrency] = useState('BRL');

  // Identifica├º├úo
  const [type, setType] = useState<Asset['type']>('STOCK');
  const [ticker, setTicker] = useState('');
  const [name, setName] = useState('');
  const [sector, setSector] = useState('');
  const [cdiRate, setCdiRate] = useState('');

  // Autocomplete
  const [tickerSearch, setTickerSearch] = useState('');
  const { results: b3Results, isLoading: isSearchingB3 } = useB3TickersSearch(tickerSearch);
  const [suggestions, setSuggestions] = useState<(B3Ticker | AbroadAsset)[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const tickerRef = useRef<HTMLDivElement>(null);
  const blurTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current);
    };
  }, []);

  // Posi├º├úo e valor
  const [quantity, setQuantity] = useState('');
  const [investedAmount, setInvestedAmount] = useState(''); // valor total investido
  const [purchaseDate, setPurchaseDate] = useState('');

  // Corretora
  const [brokerId, setBrokerId] = useState('');
  const [customBrokerName, setCustomBrokerName] = useState('');
  const [linkedAccountId, setLinkedAccountId] = useState('none');

  // PM calculado automaticamente
  const avgPrice = useMemo(() => {
    const qty = moneyUtils.parse(quantity);
    const invested = moneyUtils.parse(investedAmount.replace(',', '.'));
    if (qty > 0 && invested > 0) return moneyUtils.round(invested / qty).toString();
    return null;
  }, [quantity, investedAmount]);

  const currencySymbol = CURRENCIES.find(c => c.code === currency)?.symbol || 'R$';
  const brokerList = location === 'BR' ? BR_BROKERS : ABROAD_BROKERS;

  // Auto-set currency when location changes
  useEffect(() => {
    if (location === 'ABROAD' && currency === 'BRL') {
      setCurrency('USD');
      setBrokerId(''); // reset corretora ao trocar localiza├º├úo
    } else if (location === 'BR') {
      setCurrency('BRL');
      setBrokerId('');
    }
  }, [location, currency]);

  // Populate form when editing
  useEffect(() => {
    if (asset) {
      setLocation((asset.location as 'BR' | 'ABROAD') || 'BR');
      setCurrency(asset.currency || 'BRL');
      setType(asset.type);
      setTicker(asset.ticker || '');
      setTickerSearch(asset.ticker || '');
      setName(asset.name);
      setSector(asset.sector || '');
      
      const cdiMatch = asset.notes?.match(/(\d+(?:\.\d+)?)%\s*CDI/i) || asset.notes?.match(/CDI:\s*(\d+(?:\.\d+)?)%/i);
      setCdiRate(cdiMatch ? cdiMatch[1] : '');

      setQuantity(asset.quantity?.toString() || '');
      // Reconstruct invested amount from qty * purchase_price
      if (asset.quantity && asset.purchase_price) {
        setInvestedAmount(moneyUtils.round(asset.quantity * asset.purchase_price).toString());
      } else {
        setInvestedAmount('');
      }
      setPurchaseDate(asset.purchase_date || '');
      setBrokerId((asset as any).broker_id || '');
      setCustomBrokerName((asset as any).broker_name || '');
      setLinkedAccountId(asset.account_id || 'none');
    } else {
      resetForm();
    }
  }, [asset, isOpen]);

  const resetForm = () => {
    setLocation('BR');
    setCurrency('BRL');
    setType('STOCK');
    setTicker('');
    setTickerSearch('');
    setName('');
    setSector('');
    setCdiRate('');
    setQuantity('');
    setInvestedAmount('');
    setPurchaseDate('');
    setBrokerId('');
    setCustomBrokerName('');
    setLinkedAccountId('none');
    setSuggestions([]);
  };

  // Ticker autocomplete
  const handleTickerInput = (val: string) => {
    setTickerSearch(val);
    setTicker(val.toUpperCase());
    
    if (val.length >= 2) {
      if (type === 'CRYPTO') {
        const results = searchCryptoAssets(val);
        setSuggestions(results as any[]);
        setShowSuggestions(results.length > 0);
      } else if (location === 'ABROAD') {
        const results = searchAbroadAssets(val);
        setSuggestions(results as any[]);
        setShowSuggestions(results.length > 0);
      }
    } else {
      setSuggestions([]);
      setShowSuggestions(false);
    }
  };

  // Effect to sync B3 results with suggestions dropdown when location is BR
  useEffect(() => {
    if (location === 'BR' && type !== 'CRYPTO' && tickerSearch.length >= 2) {
      setSuggestions(b3Results as any[]);
      setShowSuggestions(b3Results.length > 0);
    }
  }, [b3Results, location, type, tickerSearch]);

  const handleSelectSuggestion = (stock: any) => {
    setTicker(stock.ticker);
    setTickerSearch(stock.ticker);
    setName(stock.name);
    setSector(stock.sector || '');
    if (stock.type) {
      // Map B3 type to our enum if possible, or fallback
      const typeStr = stock.type.toUpperCase();
      if (['STOCK', 'FII', 'ETF', 'BDR'].includes(typeStr)) {
        setType(typeStr as any);
      }
    }
    setShowSuggestions(false);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const qty = moneyUtils.parse(quantity) || 0;
    const invested = moneyUtils.parse(investedAmount.replace(',', '.')) || 0;
    const calcAvgPrice = qty > 0 && invested > 0 ? invested / qty : 0;

    const finalBrokerName = isCustomBroker(brokerId) ? customBrokerName :
      (getBrokerById(brokerId)?.name || customBrokerName || null);

    const payload = {
      name,
      type,
      ticker: ticker || null,
      quantity: qty,
      purchase_price: calcAvgPrice,
      current_price: calcAvgPrice, // Pre├ºo atual = PM inicial ao cadastrar
      purchase_date: purchaseDate || null,
      account_id: linkedAccountId === 'none' ? null : linkedAccountId,
      location,
      currency,
      sector: sector || null,
      notes: type === 'BOND' && cdiRate ? `CDI: ${cdiRate}%` : '',
      broker_id: brokerId || null,
      broker_name: finalBrokerName,
    } as any;

    if (asset) {
      delete payload.current_price; // n├úo sobrescrever pre├ºo atual ao editar
      updateAsset({ id: asset.id, ...payload }, { onSuccess: () => { resetForm(); onClose(); } });
    } else {
      createAsset(payload, { onSuccess: () => { resetForm(); onClose(); } });
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => { if (!open) { resetForm(); onClose(); } }}>
      <DialogContent className="w-full sm:w-[520px] max-w-lg !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle className="text-base font-display font-bold">
            {asset ? 'Editar Ativo' : 'Novo Investimento'}
          </DialogTitle>
          <DialogDescription>
            Registre um ativo na sua carteira de investimentos.
          </DialogDescription>
        </DialogHeader>

        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar">
          <form onSubmit={handleSubmit} className="space-y-5">

          {/* 1. LOCALIZA├ç├âO (sempre primeiro - condiciona tudo) */}
          <div className="space-y-2">
            <Label className="text-sm uppercase tracking-wider font-bold text-muted-foreground">
              Onde est├í custodiado?
            </Label>
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => setLocation('BR')}
                className={cn(
                  "flex items-center gap-3 p-3 rounded-xl border-2 transition-all text-left",
                  location === 'BR'
                    ? "border-foreground bg-foreground/5"
                    : "border-border hover:border-foreground/30"
                )}
              >
                <span className="text-2xl">­ƒçº­ƒçÀ</span>
                <div>
                  <p className="text-sm font-semibold">Brasil</p>
                  <p className="text-sm text-muted-foreground">B3 ┬À BRL</p>
                </div>
              </button>
              <button
                type="button"
                onClick={() => setLocation('ABROAD')}
                className={cn(
                  "flex items-center gap-3 p-3 rounded-xl border-2 transition-all text-left",
                  location === 'ABROAD'
                    ? "border-accent bg-accent/5"
                    : "border-border hover:border-accent/30"
                )}
              >
                <Globe className="w-7 h-7 text-accent shrink-0" />
                <div>
                  <p className="text-sm font-semibold">Exterior</p>
                  <p className="text-sm text-muted-foreground">NYSE ┬À NASDAQ ┬À etc.</p>
                </div>
              </button>
            </div>
          </div>

          {/* 2. MOEDA (vis├¡vel apenas quando exterior) */}
          {location === 'ABROAD' && (
            <div className="space-y-2">
              <Label>Moeda do Ativo</Label>
              <Select value={currency} onValueChange={setCurrency}>
                <SelectTrigger id="assetCurrency" name="assetCurrency">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {CURRENCIES.filter(c => c.code !== 'BRL').map(c => (
                    <SelectItem key={c.code} value={c.code}>
                      <span className="font-mono font-bold">{c.symbol}</span> {c.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* 3. TIPO E TICKER */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Tipo de Ativo</Label>
              <Select value={type} onValueChange={(val: any) => setType(val)}>
                <SelectTrigger id="assetType" name="assetType">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ASSET_TYPES.map(t => (
                    <SelectItem key={t.value} value={t.value}>{t.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2" ref={tickerRef}>
              <Label>C├│digo (Ticker)</Label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground pointer-events-none" />
                <Input
                  id="ticker" name="ticker"
                  value={tickerSearch}
                  onChange={(e) => handleTickerInput(e.target.value)}
                  onBlur={() => { if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current); blurTimeoutRef.current = setTimeout(() => setShowSuggestions(false), 150); }}
                  placeholder={location === 'BR' ? 'PETR4, VALE3ÔÇª' : 'AAPL, MSFTÔÇª'}
                  className="uppercase font-mono pl-8"
                  autoComplete="off"
                />
                {showSuggestions && suggestions.length > 0 && (
                  <div className="absolute z-50 top-full mt-1 w-full bg-popover border border-border rounded-xl shadow-lg overflow-hidden">
                    {suggestions.map(s => (
                      <button
                        key={s.ticker}
                        type="button"
                        onMouseDown={() => handleSelectSuggestion(s)}
                        className="w-full flex items-center gap-3 px-3 py-2 hover:bg-muted text-left transition-colors"
                      >
                        <span className="font-mono font-bold text-sm w-16 shrink-0">{s.ticker}</span>
                        <div className="min-w-0">
                          <p className="text-sm font-medium truncate">{s.name}</p>
                          <p className="text-sm text-muted-foreground">{s.sector}</p>
                        </div>
                      </button>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Renda Fixa: Taxa do CDI */}
          {type === 'BOND' && (
            <div className="space-y-2 p-3 bg-accent/10 border border-accent/20 rounded-xl">
              <Label className="text-accent font-bold">Rendimento (% do CDI)</Label>
              <Input type="number" inputMode="decimal"
                id="cdiRate" name="cdiRate"
                value={cdiRate}
                onChange={(e) => setCdiRate(e.target.value)}
                placeholder="Ex: 110"
                className="bg-background"
              />
              <p className="text-sm text-accent/80">Opcional. Preencha para calcular o rendimento autom├ítico.</p>
            </div>
          )}

          {/* 4. NOME E SETOR */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Nome do Ativo</Label>
              <Input
                id="name" name="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ex: Petrobras PN"
                required
              />
            </div>
            <div className="space-y-2">
              <Label>Setor</Label>
              <Select value={sector || '_'} onValueChange={v => setSector(v === '_' ? '' : v)}>
                <SelectTrigger id="sector" name="sector">
                  <SelectValue placeholder="SelecioneÔÇª" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="_">N├úo definido</SelectItem>
                  {SECTORS_BR.map(s => (
                    <SelectItem key={s} value={s}>{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* 5. QUANTIDADE + VALOR INVESTIDO ÔåÆ CALCULA PM */}
          <div className="space-y-6 pt-4 border-t border-border">
            <div className="space-y-2">
              <Label>Quantidade de Cotas</Label>
              <Input type="number" inputMode="decimal"
                id="quantity" name="quantity"
                step="0.00000001"
                value={quantity}
                onChange={(e) => setQuantity(e.target.value)}
                placeholder="0"
                className="font-mono h-12 text-base text-center"
              />
            </div>
            
            <div className="space-y-2">
              <AmountInput
                label="Valor Investido"
                value={investedAmount}
                onChange={setInvestedAmount}
                currency={currency}
                currencySymbol={currencySymbol}
                size="sm"
              />
              <p className="text-sm text-muted-foreground text-center">Total pago pela posi├º├úo</p>
            </div>

            {/* PM calculado em tempo real */}
            {avgPrice && (
              <div className="flex items-center justify-between p-2.5 rounded-lg bg-background border border-border">
                <span className="text-sm text-muted-foreground font-medium">Pre├ºo M├®dio calculado:</span>
                <span className="font-mono font-bold text-sm text-foreground">
                  {currencySymbol} {moneyUtils.parse(avgPrice).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}
                </span>
              </div>
            )}

            <div className="space-y-2">
              <Label>Data da Compra</Label>
              <Input
                id="purchaseDate" name="purchaseDate"
                type="date"
                value={purchaseDate}
                onChange={(e) => setPurchaseDate(e.target.value)}
              />
            </div>
          </div>

          {/* 6. CORRETORA */}
          <div className="space-y-3">
            <Label className="text-sm uppercase tracking-wider font-bold text-muted-foreground flex items-center gap-2">
              <Building2 className="w-3.5 h-3.5" />
              Corretora / Institui├º├úo
            </Label>
            <Select value={brokerId} onValueChange={setBrokerId}>
              <SelectTrigger id="brokerId" name="brokerId">
                <SelectValue placeholder="Selecione a corretoraÔÇª" />
              </SelectTrigger>
              <SelectContent>
                {brokerList.map(b => (
                  <SelectItem key={b.id} value={b.id}>
                    <div className="flex items-center gap-2">
                      <div
                        className="w-6 h-6 rounded text-sm font-bold flex items-center justify-center shrink-0"
                        style={{ backgroundColor: b.color, color: b.textColor }}
                      >
                        {b.icon}
                      </div>
                      <span>{b.name}</span>
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            {isCustomBroker(brokerId) && (
              <div className="space-y-2">
                <Label>Nome da corretora (personalizado)</Label>
                <Input
                  id="customBrokerName" name="customBrokerName"
                  value={customBrokerName}
                  onChange={(e) => setCustomBrokerName(e.target.value)}
                  placeholder="Ex: Minha Corretora"
                  required={isCustomBroker(brokerId)}
                />
              </div>
            )}

            {/* Conta banc├íria vinculada (opcional) */}
            {accounts && accounts.filter(a => a.type !== 'CREDIT_CARD').length > 0 && (
              <div className="space-y-2">
                <Label className="text-muted-foreground text-sm">Conta banc├íria vinculada (opcional)</Label>
                <Select value={linkedAccountId} onValueChange={setLinkedAccountId}>
                  <SelectTrigger id="linkedAccountId" name="linkedAccountId">
                    <SelectValue placeholder="Nenhuma" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Nenhuma</SelectItem>
                    {accounts
                      .filter(a => a.type !== 'CREDIT_CARD' && (a.currency === currency || (!a.currency && currency === 'BRL')))
                      .map(acc => (
                        <SelectItem key={acc.id} value={acc.id}>
                          {acc.name} ({acc.currency || 'BRL'})
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
                <p className="text-sm text-muted-foreground">
                  Vinculando a uma conta, as opera├º├Áes de compra/venda debitar├úo/creditar├úo nela.
                </p>
              </div>
            )}
          </div>

          <div className="pt-2 flex gap-3">
            <Button type="button" variant="outline" onClick={() => { resetForm(); onClose(); }} className="flex-1">
              Cancelar
            </Button>
            <Button type="submit" disabled={isCreating || isUpdating} className="flex-1">
              {isCreating || isUpdating ? 'SalvandoÔÇª' : 'Salvar Ativo'}
            </Button>
          </div>
        </form>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import React, { useState, useMemo } from 'react';
import { supabase } from '@/integrations/supabase/client';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { CurrencyInput } from '@/components/ui/currency-input';
import { AmountInput } from '@/components/ui/amount-input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { useAssets } from '@/hooks/useAssets';
import { useAccounts } from '@/hooks/useAccounts';
import { useCreateTransaction } from '@/hooks/useTransactions';
import { Asset } from '@/types/database';
import { TrendingDown, TrendingUp, RefreshCw, AlertCircle, Info, Coins } from 'lucide-react';
import * as dateFns from 'date-fns';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { moneyUtils } from "@/utils/money";
import { logger } from '@/utils/logger';

interface AssetTransactionDialogProps {
  isOpen: boolean;
  onClose: () => void;
  asset: Asset;
}

const DIVIDEND_TYPES_BY_ASSET: Record<string, { value: string, label: string }[]> = {
  STOCK: [
    { value: 'DIVIDENDOS', label: 'Dividendos' },
    { value: 'JCP', label: 'Juros sobre Capital Pr├│prio (JCP)' },
    { value: 'RESTITUICAO', label: 'Restitui├º├úo de Capital' },
  ],
  FII: [
    { value: 'RENDIMENTO', label: 'Rendimentos' },
    { value: 'AMORTIZACAO', label: 'Amortiza├º├úo' },
  ],
  BOND: [
    { value: 'JUROS', label: 'Juros' },
    { value: 'AMORTIZACAO', label: 'Amortiza├º├úo' },
    { value: 'RENDIMENTO', label: 'Rendimento' },
  ],
  CRYPTO: [
    { value: 'STAKING', label: 'Staking' },
    { value: 'AIRDROP', label: 'Airdrop' },
  ],
  ETF: [
    { value: 'DIVIDENDOS', label: 'Dividendos' }
  ],
  REIT: [
    { value: 'DIVIDENDOS', label: 'Dividendos' }
  ],
  FUND: [
    { value: 'RENDIMENTO', label: 'Rendimentos' },
    { value: 'AMORTIZACAO', label: 'Amortiza├º├úo' },
  ],
  DEFAULT: [
    { value: 'RENDIMENTO', label: 'Rendimentos' },
    { value: 'DIVIDENDOS', label: 'Dividendos' },
  ]
};

const CURRENCY_SYMBOLS: Record<string, string> = {
  BRL: 'R$',
  USD: 'US$',
  EUR: 'Ôé¼',
  GBP: '┬ú',
};

export function AssetTransactionDialog({ isOpen, onClose, asset }: AssetTransactionDialogProps) {
  const { updateAssetPrice } = useAssets();
  const { data: accounts } = useAccounts();
  const { mutateAsync: createTransaction } = useCreateTransaction();

  const [type, setType] = useState<'buy' | 'sell' | 'update' | 'dividend'>('buy');
  const [dividendType, setDividendType] = useState('RENDIMENTO');
  const [quantity, setQuantity] = useState('');
  const [price, setPrice] = useState(''); // pre├ºo POR COTA executado
  const [accountId, setAccountId] = useState(asset.account_id || '');
  const [opDate, setOpDate] = useState(dateFns.format(new Date(), 'yyyy-MM-dd'));
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Set default dividendType when asset or dialog opens
  React.useEffect(() => {
    const opts = DIVIDEND_TYPES_BY_ASSET[asset.type] || DIVIDEND_TYPES_BY_ASSET['DEFAULT'];
    setDividendType(opts[0].value);
  }, [asset.type, isOpen]);

  const currency = asset.currency || 'BRL';
  const isAbroad = asset.location === 'ABROAD';
  const currencySymbol = CURRENCY_SYMBOLS[currency] || currency;

  const currentQty = asset.quantity || 0;
  const currentAvgPrice = asset.purchase_price || 0;

  // ÔöÇÔöÇ C├üLCULOS EM TEMPO REAL ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  const qty = moneyUtils.parse(quantity) || 0;
  const prc = moneyUtils.parse(price) || 0;
  const totalOp = qty * prc;

  // Simula├º├úo do PM ap├│s opera├º├úo
  const simulatedAvgPrice = useMemo(() => {
    if (type === 'buy' && qty > 0 && prc > 0) {
      const newTotalCost = (currentQty * currentAvgPrice) + totalOp;
      const newQty = currentQty + qty;
      return newQty > 0 ? newTotalCost / newQty : 0;
    }
    return currentAvgPrice; // venda n├úo muda PM (FIFO)
  }, [type, qty, prc, currentQty, currentAvgPrice, totalOp]);

  const simulatedQty = useMemo(() => {
    if (type === 'buy') return currentQty + qty;
    if (type === 'sell') return Math.max(0, currentQty - qty);
    return currentQty;
  }, [type, qty, currentQty]);

  // Lucro/Preju├¡zo na venda
  const sellPnl = useMemo(() => {
    if (type === 'sell' && qty > 0 && prc > 0) {
      return (prc - currentAvgPrice) * qty;
    }
    return null;
  }, [type, qty, prc, currentAvgPrice]);

  // Contas v├ílidas para a opera├º├úo
  const validAccounts = accounts?.filter(a => {
    if (isAbroad) {
      // Para ativos no exterior, mostrar contas internacionais preferencialmente
      return a.type !== 'CREDIT_CARD';
    }
    return a.type !== 'CREDIT_CARD';
  }) || [];

  const selectedAccount = validAccounts.find(a => a.id === accountId);

  const formatMoney = (val: number) => {
    if (currency === 'BRL') {
      return `R$ ${val.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}`;
    }
    return `${currencySymbol} ${val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 8 })}`;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Atualiza├º├úo de cota├º├úo n├úo precisa de conta
    if (type === 'update') {
      if (!prc) return;
      updateAssetPrice({ id: asset.id, currentPrice: prc }, {
        onSuccess: () => { toast.success('Cota├º├úo atualizada!'); resetAndClose(); }
      });
      return;
    }

    if (type !== 'dividend') {
      if (!qty || !prc) {
        toast.error('Informe a quantidade e o pre├ºo.');
        return;
      }
    } else {
      if (!prc) {
        toast.error('Informe o valor do rendimento recebido.');
        return;
      }
    }

    // Conta ├® OBRIGAT├ôRIA para compra/venda/rendimento
    if (!accountId) {
      toast.error('Selecione a conta para d├®bito/cr├®dito da opera├º├úo.');
      return;
    }

    // Venda: n├úo pode vender mais do que tem
    if (type === 'sell' && qty > currentQty) {
      toast.error(`Voc├¬ possui apenas ${currentQty} cotas dispon├¡veis para vender.`);
      return;
    }

    setIsSubmitting(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usu├írio n├úo autenticado');

      if (type === 'buy') {
        // 1. Criar transa├º├úo de DESPESA no extrato
        await createTransaction({
          account_id: accountId,
          amount: totalOp,
          description: `Compra ${asset.ticker || asset.name} (${qty}x ${formatMoney(prc)})`,
          date: opDate,
          type: 'EXPENSE',
          domain: 'PERSONAL',
          competence_date: opDate,
        } as any);

        // 2. Registrar no hist├│rico de ativos (O banco atualizar├í o PM automaticamente)
        await supabase.from('asset_transactions').insert({
          user_id: user.id,
          asset_id: asset.id,
          account_id: accountId,
          type: 'BUY',
          quantity: qty,
          price: prc,
          date: opDate
        });

        toast.success('Compra registrada com sucesso!');
        resetAndClose();

      } else if (type === 'sell') {
        // 1. Criar transa├º├úo de RECEITA no extrato
        await createTransaction({
          account_id: accountId,
          amount: totalOp,
          description: `Venda ${asset.ticker || asset.name} (${qty}x ${formatMoney(prc)})`,
          date: opDate,
          type: 'INCOME',
          domain: 'PERSONAL',
          competence_date: opDate,
        } as any);

        // 2. Registrar no hist├│rico de ativos
        await supabase.from('asset_transactions').insert({
          user_id: user.id,
          asset_id: asset.id,
          account_id: accountId,
          type: 'SELL',
          quantity: qty,
          price: prc,
          date: opDate
        });

        toast.success('Venda registrada com sucesso!');
        resetAndClose();

      } else if (type === 'dividend') {
        // 1. Buscar categoria de Investimentos ou usar uma padr├úo
        let categoryId: string | null = null;
        try {
          const { data: catData } = await supabase
            .from('categories')
            .select('id')
            .eq('user_id', user.id)
            .ilike('name', '%investimento%')
            .limit(1)
            .maybeSingle();
          if (catData) {
            categoryId = catData.id;
          }
        } catch (catErr) {
          logger.error("Erro ao buscar categoria de investimentos:", catErr);
        }

        // 2. Criar transa├º├úo de RECEITA no extrato
        const dividendLabel = (DIVIDEND_TYPES_BY_ASSET[asset.type] || DIVIDEND_TYPES_BY_ASSET['DEFAULT']).find(d => d.value === dividendType)?.label || 'Rendimento';
        
        await createTransaction({
          account_id: accountId,
          amount: prc,
          description: `${dividendLabel} - ${asset.ticker || asset.name}`,
          date: opDate,
          type: 'INCOME',
          domain: 'PERSONAL',
          competence_date: opDate,
          category_id: categoryId,
        } as any);

        // 3. Registrar no hist├│rico de ativos (com quantidade fict├¡cia 1 e pre├ºo igual ao total recebido)
        await supabase.from('asset_transactions').insert({
          user_id: user.id,
          asset_id: asset.id,
          account_id: accountId,
          type: `DIVIDEND:${dividendType}`,
          quantity: 1,
          price: prc,
          date: opDate
        });

        toast.success('Rendimento registrado com sucesso!');
        resetAndClose();
      }
    } catch (error: any) {
      toast.error(`Erro ao registrar opera├º├úo: ${error?.message || 'Tente novamente.'}`);
    } finally {
      setIsSubmitting(false);
    }
  };

  const resetAndClose = () => {
    setQuantity('');
    setPrice('');
    setOpDate(dateFns.format(new Date(), 'yyyy-MM-dd'));
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && resetAndClose()}>
      <DialogContent className="sm:max-w-[440px] w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <DialogHeader className="px-5 pt-5 pb-2 sm:px-6 sm:pt-6">
          <DialogTitle className="text-base font-display font-bold flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-secondary flex items-center justify-center font-bold text-sm">
              {(asset.ticker || asset.name).substring(0, 3)}
            </div>
            <div>
              <span>{asset.ticker || asset.name}</span>
              <p className="text-sm font-normal text-muted-foreground">{asset.name}</p>
            </div>
          </DialogTitle>
          <DialogDescription>
            PM atual: <span className="font-mono font-semibold">{formatMoney(currentAvgPrice)}</span>
            {' ┬À '} Qtd: <span className="font-mono font-semibold">{currentQty}</span>
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-5 mt-2 px-5 pb-5 sm:px-6 sm:pb-6 overflow-y-auto flex-1">
          {/* Tabs de opera├º├úo */}
          <div className="flex bg-secondary p-1 rounded-xl border border-border overflow-x-auto gap-1 scrollbar-none">
            {[
              { key: 'buy', label: 'Comprar', icon: <TrendingUp className="w-4 h-4 text-success" /> },
              { key: 'sell', label: 'Vender', icon: <TrendingDown className="w-4 h-4 text-destructive" /> },
              { key: 'dividend', label: 'Rendimento', icon: <Coins className="w-4 h-4 text-accent" /> },
              { key: 'update', label: 'Cota├º├úo', icon: <RefreshCw className="w-4 h-4 text-accent" /> },
            ].map(t => (
              <button
                key={t.key}
                type="button"
                onClick={() => setType(t.key as any)}
                className={cn(
                  "flex-1 flex items-center justify-center gap-2 py-2 px-2 rounded-lg text-xs font-medium transition-all duration-200 white-space-nowrap min-w-[80px]",
                  type === t.key
                    ? "bg-background text-foreground shadow-sm"
                    : "text-muted-foreground hover:text-foreground"
                )}
              >
                {t.icon}
                {t.label}
              </button>
            ))}
          </div>

          {/* Aviso conta obrigat├│ria para compra/venda/rendimento */}
          {type !== 'update' && (
            <Alert className="border-warning/20 bg-warning/8">
              <Info className="h-4 w-4 text-warning" />
              <AlertDescription className="text-sm text-warning">
                {type === 'buy' && 'O valor da compra ser├í debitado da conta selecionada.'}
                {type === 'sell' && 'O valor da venda ser├í creditado na conta selecionada.'}
                {type === 'dividend' && 'O valor do rendimento ser├í creditado como receita na conta selecionada.'}
              </AlertDescription>
            </Alert>
          )}

          {/* Campos de Qtd + Pre├ºo */}
          {type === 'dividend' ? (
            <div className="grid grid-cols-1 gap-4">
              <div className="space-y-2">
                <Label>Tipo de Rendimento</Label>
                <Select value={dividendType} onValueChange={setDividendType}>
                  <SelectTrigger id="dividendType" name="dividendType">
                    <SelectValue placeholder="Selecione o tipoÔÇª" />
                  </SelectTrigger>
                  <SelectContent>
                    {(DIVIDEND_TYPES_BY_ASSET[asset.type] || DIVIDEND_TYPES_BY_ASSET['DEFAULT']).map(opt => (
                      <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              
              <div className="space-y-2 pt-4 border-t border-border mt-4">
                <AmountInput
                  label="Valor Total Recebido"
                  value={price}
                  onChange={setPrice}
                  currency={currency}
                  currencySymbol={currencySymbol}
                  size="sm"
                  textColorClass="text-positive"
                />
              </div>
            </div>
          ) : type !== 'update' ? (
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Quantidade</Label>
                <Input type="number" inputMode="decimal"
                  id="quantity" name="quantity"
                  step="0.00000001"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  placeholder="0"
                  className="font-mono"
                  required
                />
              </div>
              <div className="space-y-2">
                <Label>Pre├ºo por Cota</Label>
                {asset.type === 'CRYPTO' ? (
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm font-mono">
                      {currencySymbol}
                    </span>
                    <Input type="number" inputMode="decimal"
                      id="price" name="price"
                      step="0.00000001"
                      value={price}
                      onChange={(e) => setPrice(e.target.value)}
                      placeholder="0,00"
                      className="font-mono pl-10"
                      required
                    />
                  </div>
                ) : (
                  <CurrencyInput
                    id="price" name="price"
                    value={price}
                    onChange={setPrice}
                    currency={currency}
                    placeholder="0,00"
                    className="font-mono"
                    required
                  />
                )}
              </div>
            </div>
          ) : (
            <div className="space-y-2">
              <Label>Nova Cota├º├úo Atual</Label>
              {asset.type === 'CRYPTO' ? (
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm font-mono">
                    {currencySymbol}
                  </span>
                  <Input type="number" inputMode="decimal"
                    id="currentPrice" name="currentPrice"
                    step="0.00000001"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    placeholder="0,00"
                    className="font-mono pl-10"
                    required
                  />
                </div>
              ) : (
                <CurrencyInput
                  id="currentPrice" name="currentPrice"
                  value={price}
                  onChange={setPrice}
                  currency={currency}
                  placeholder="0,00"
                  className="font-mono"
                  required
                />
              )}
            </div>
          )}

          {/* Simula├º├úo em tempo real */}
          {type !== 'update' && type !== 'dividend' && qty > 0 && prc > 0 && (
            <div className="p-3 rounded-xl bg-muted/50 border border-border space-y-2 text-sm">
              <p className="text-sm uppercase tracking-wider font-bold text-muted-foreground">Resumo da opera├º├úo</p>
              <div className="flex justify-between">
                <span className="text-muted-foreground">Total da opera├º├úo</span>
                <span className="font-mono font-bold">{formatMoney(totalOp)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">Nova quantidade</span>
                <span className="font-mono">{simulatedQty.toFixed(8).replace(/\.?0+$/, '')}</span>
              </div>
              {type === 'buy' && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Novo PM</span>
                  <span className="font-mono font-semibold text-foreground">{formatMoney(simulatedAvgPrice)}</span>
                </div>
              )}
              {type === 'sell' && sellPnl !== null && (
                <div className="flex justify-between border-t border-border pt-2 mt-2">
                  <span className="text-muted-foreground">Lucro/Preju├¡zo</span>
                  <span className={cn("font-mono font-bold", sellPnl >= 0 ? "text-success" : "text-destructive")}>
                    {sellPnl >= 0 ? '+' : ''}{formatMoney(sellPnl)}
                  </span>
                </div>
              )}
            </div>
          )}

          {/* Data da opera├º├úo */}
          {type !== 'update' && (
            <div className="space-y-2">
              <Label>Data da Opera├º├úo</Label>
              <Input
                id="opDate" name="opDate"
                type="date"
                value={opDate}
                onChange={(e) => setOpDate(e.target.value)}
                required
              />
            </div>
          )}

          {/* Conta ÔÇö OBRIGAT├ôRIA para compra/venda */}
          {type !== 'update' && (
            <div className="space-y-2">
              <Label>
                Conta para {type === 'buy' ? 'd├®bito' : 'cr├®dito'}
                <span className="text-destructive ml-1">*</span>
              </Label>
              <Select value={accountId} onValueChange={setAccountId} required>
                <SelectTrigger className={cn(!accountId && "border-destructive/50")}>
                  <SelectValue placeholder="Selecione a conta..." />
                </SelectTrigger>
                <SelectContent>
                  {validAccounts.map(acc => (
                    <SelectItem key={acc.id} value={acc.id}>
                      <div className="flex items-center gap-2">
                        <span>{acc.name}</span>
                        {acc.is_international && (
                          <span className="text-sm bg-accent/15 text-accent px-1 rounded">
                            {acc.currency}
                          </span>
                        )}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {isAbroad && selectedAccount && !selectedAccount.is_international && (
                <p className="text-sm text-warning flex items-center gap-1">
                  <AlertCircle className="w-3 h-3" />
                  Conta em BRL selecionada. Considere usar uma conta internacional para ativos em {currency}.
                </p>
              )}
            </div>
          )}

          <div className="pt-2 flex gap-3">
            <Button type="button" variant="outline" onClick={resetAndClose} className="flex-1">
              Cancelar
            </Button>
             <Button
              type="submit"
              disabled={isSubmitting}
              className={cn(
                "flex-1",
                type === 'buy' && "bg-success hover:bg-success/92",
                type === 'sell' && "bg-destructive hover:bg-destructive/92",
                type === 'dividend' && "bg-accent hover:bg-accent/92",
              )}
            >
              {isSubmitting ? 'ProcessandoÔÇª' : (
                type === 'buy' ? 'Ô£ô Confirmar Compra' :
                type === 'sell' ? 'Ô£ô Confirmar Venda' :
                type === 'dividend' ? 'Ô£ô Confirmar Rendimento' :
                'Ô£ô Atualizar Cota├º├úo'
              )}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { cn } from "@/lib/utils";
import { useTheme } from "next-themes";
import { useAuth } from "@/contexts/AuthContext";
import { useUserProfile } from "@/hooks/useUserProfile";
import { useGlobalRealtime } from "@/hooks/useGlobalRealtime";
import { useCategories, useCreateDefaultCategories } from "@/hooks/useCategories";
import { UserAvatar } from "@/components/ui/user-avatar";
import {
  LayoutDashboard,
  ArrowLeftRight,
  CreditCard,
  Users,
  Plane,
  BarChart3,
  Settings,
  Menu,
  X,
  Moon,
  Sun,
  LogOut,
  UsersRound,
  Wallet,
  Plus,
  PiggyBank,
  Target,
  Eye,
  EyeOff,
  Calculator,
  ChevronDown,
  Search,
  Grid3X3,
} from "lucide-react";
import { GlobalSearch } from "@/components/search/GlobalSearch";
import { navigationItems, secondaryNavItems } from "@/config/navigation";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { NotificationButton } from "./NotificationButton";
import { MonthSelector } from "./MonthSelector";
import { useTransactionModal } from "@/hooks/useTransactionModal";
import { TransactionModal } from "@/components/modals/TransactionModal";
import { MobileNav } from "./MobileNav";
import { VersionGuard } from "./VersionGuard";
import { usePrivacy } from "@/contexts/PrivacyContext";
import { OnboardingGuard } from "@/components/onboarding/OnboardingGuard";
import { ErrorBoundary } from "@/components/ErrorBoundary";

interface AppLayoutProps {
  children: React.ReactNode;
}

export function AppLayout({ children }: AppLayoutProps) {
  const { theme, setTheme, systemTheme } = useTheme();

  // Resolvemos o tema atual (se 'system', olhamos para systemTheme)
  const currentTheme = theme === "system" ? systemTheme : theme;
  const isDark = currentTheme === "dark";
  const location = useLocation();
  const navigate = useNavigate();
  const { user, signOut } = useAuth();
  const { data: profile } = useUserProfile();
  const { showTransactionModal, setShowTransactionModal } = useTransactionModal();

  const { isPrivate, togglePrivacy } = usePrivacy();
  const [showSearch, setShowSearch] = useState(false);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault();
        setShowSearch(true);
      }
    };
    window.addEventListener("keydown", handler);
    return () => window.removeEventListener("keydown", handler);
  }, []);

  // Ativa a escuta de Realtime global para toda a aplica├º├úo
  useGlobalRealtime();

  // Inje├º├úo autom├ítica de categorias padr├úo para novos usu├írios
  const { data: categories, isSuccess: categoriesLoaded } = useCategories();
  const createDefaultCategories = useCreateDefaultCategories();

  useEffect(() => {
    if (
      categoriesLoaded &&
      categories &&
      categories.length < 10 &&
      !createDefaultCategories.isPending
    ) {
      createDefaultCategories.mutate({ force: false });
    }
  }, [categoriesLoaded, categories, createDefaultCategories]);

  const toggleTheme = () => {
    setTheme(isDark ? "light" : "dark");
  };

  const handleSignOut = async () => {
    await signOut();
    navigate("/auth");
  };

  // Detectar contexto baseado na rota atual
  const handleNewTransaction = () => {
    // Extrair contexto da URL
    const context: Record<string, any> = {};

    // Se estiver em uma viagem espec├¡fica
    if (location.pathname.startsWith("/viagens/")) {
      const tripId = location.pathname.split("/viagens/")[1];
      if (tripId && tripId !== "") {
        context.tripId = tripId;
      }
    }

    // Se estiver em uma conta espec├¡fica
    if (location.pathname.startsWith("/contas/")) {
      const accountId = location.pathname.split("/contas/")[1];
      if (accountId && accountId !== "") {
        context.accountId = accountId;
      }
    }

    setShowTransactionModal(true, context);
  };

  return (
    <div className="min-h-screen flex flex-col w-full bg-background">
      <VersionGuard />
      {/* Skip-to-content ÔÇö WCAG 2.4.1 */}
      <a
        href="#main-content"
        className="sr-only focus:not-sr-only focus:absolute focus:top-3 focus:left-3 focus:z-[100] focus:px-4 focus:py-2 focus:bg-accent focus:text-accent-foreground focus:rounded-lg focus:shadow-lg focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2"
      >
        Pular para o conte├║do principal
      </a>
      {/* TopBar */}
      <header className="sticky top-0 z-50 w-full border-b border-border bg-background transform-gpu">
        <div className="w-full px-4 md:px-6 lg:px-8">
          <div className="flex h-12 items-center justify-between gap-2">
            {/* Logo Wordmark */}
            <Link to="/" className="flex items-center gap-2 flex-shrink-0 mr-1 lg:mr-6 min-w-max">
              <span className="font-display font-bold text-sm md:text-base tracking-tight whitespace-nowrap block">
                p├® de meia
              </span>
            </Link>

            {/* Desktop Navigation */}
            <nav
              className="hidden md:flex items-center gap-0 flex-1 justify-center flex-wrap"
              aria-label="Navega├º├úo principal"
            >
              {navigationItems.map((item) => {
                const isActive =
                  location.pathname === item.path ||
                  (item.path !== "/" && location.pathname.startsWith(item.path));
                const Icon = item.icon;
                return (
                  <Link
                    key={item.path}
                    to={item.path}
                    title={item.label}
                    className={cn(
                      "flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors duration-150 whitespace-nowrap",
                      isActive
                        ? "bg-primary text-primary-foreground"
                        : "text-muted-foreground hover:text-foreground hover:bg-secondary/70"
                    )}
                  >
                    <Icon className="h-3.5 w-3.5 flex-shrink-0" />
                    {item.label}
                  </Link>
                );
              })}
              {secondaryNavItems.length > 0 && (
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button
                      className={cn(
                        "flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium transition-colors duration-150 whitespace-nowrap",
                        "text-muted-foreground hover:text-foreground hover:bg-secondary/70"
                      )}
                      aria-label="Mais itens de navega├º├úo"
                    >
                      <Grid3X3 className="h-3.5 w-3.5 flex-shrink-0" />
                      Mais
                      <ChevronDown className="h-3 w-3 opacity-50" />
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="start" className="w-48">
                    {secondaryNavItems.map((item) => {
                      const Icon = item.icon;
                      const isActive =
                        location.pathname === item.path ||
                        (item.path !== "/" && location.pathname.startsWith(item.path));
                      return (
                        <DropdownMenuItem key={item.path} asChild>
                          <Link
                            to={item.path}
                            className={cn(
                              "flex items-center gap-2 cursor-pointer",
                              isActive && "text-primary font-medium"
                            )}
                          >
                            <Icon className="h-4 w-4" />
                            {item.label}
                          </Link>
                        </DropdownMenuItem>
                      );
                    })}
                  </DropdownMenuContent>
                </DropdownMenu>
              )}
            </nav>

            {/* Right Section ÔÇö isolado para n├úo derrubar o header inteiro em caso de erro */}
            <ErrorBoundary fallback={null}>
              <div className="flex items-center gap-2 flex-shrink-0 ml-auto">
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setShowSearch(true)}
                  className="text-muted-foreground hover:text-foreground relative"
                  aria-label="Buscar (Ctrl+K)"
                  title="Buscar (Ctrl+K)"
                >
                  <Search className="h-4 w-4" />
                  <span className="absolute -bottom-0.5 right-0 text-[9px] font-mono text-muted-foreground/60 hidden md:inline">
                    Ctrl+K
                  </span>
                </Button>
                <NotificationButton />

                <Button
                  variant="ghost"
                  size="icon"
                  onClick={togglePrivacy}
                  className="text-muted-foreground hover:text-foreground"
                  aria-label={isPrivate ? "Mostrar valores" : "Ocultar valores"}
                >
                  {isPrivate ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                </Button>

                <Button
                  variant="ghost"
                  size="icon"
                  onClick={toggleTheme}
                  className="text-muted-foreground hover:text-foreground"
                  aria-label={isDark ? "Ativar modo claro" : "Ativar modo escuro"}
                >
                  {isDark ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}
                </Button>

                <Link to="/configuracoes" className="hidden md:block">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="text-muted-foreground hover:text-foreground"
                    aria-label="Configura├º├Áes"
                  >
                    <Settings className="h-4 w-4" />
                  </Button>
                </Link>

                {/* User Menu - Hidden on mobile */}
                <DropdownMenu>
                  <DropdownMenuTrigger asChild className="hidden md:flex">
                    <Button
                      variant="ghost"
                      size="icon"
                      className="rounded-full p-0"
                      aria-label="Menu do usu├írio"
                    >
                      <UserAvatar
                        name={profile?.full_name || user?.email || "User"}
                        avatarUrl={profile?.avatar_url}
                        colorId={profile?.avatar_color || "green"}
                        iconId={profile?.avatar_icon || "avatar_1"}
                        size="sm"
                      />
                    </Button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="end" className="w-56">
                    <div className="flex items-center gap-2 p-2">
                      <div className="flex flex-col space-y-2 leading-none">
                        <p className="font-medium text-sm truncate">
                          {profile?.full_name ||
                            user?.user_metadata?.full_name ||
                            user?.email?.split("@")[0]}
                        </p>
                        <p className="text-sm text-muted-foreground truncate">{user?.email}</p>
                      </div>
                    </div>
                    <DropdownMenuSeparator />
                    <DropdownMenuItem onClick={handleSignOut} className="text-destructive">
                      <LogOut className="mr-2 h-4 w-4" />
                      Sair
                    </DropdownMenuItem>
                  </DropdownMenuContent>
                </DropdownMenu>
              </div>
            </ErrorBoundary>
          </div>
        </div>

        {/* Month Selector - Below TopBar */}
        {/* Hide month selector on pages that don't use monthly context */}
        {!["/cartoes", "/simuladores", "/configuracoes", "/familia"].includes(location.pathname) &&
          !location.pathname.startsWith("/cartoes/") && (
            <div className="border-t border-border bg-background shadow-sm">
              <div className="w-full px-4 md:px-6 lg:px-8 py-1.5 md:py-2 flex items-center justify-between gap-4">
                <div className="flex-1 hidden md:block" />

                <div className="flex items-center gap-2 flex-1 md:flex-initial justify-center md:justify-center">
                  <MonthSelector />
                </div>

                <div className="hidden md:flex justify-end md:flex-1">
                  <Button size="default" onClick={handleNewTransaction} className="gap-2">
                    <Plus className="h-4 w-4" />
                    <span>Nova transa├º├úo</span>
                  </Button>
                </div>
              </div>
            </div>
          )}
      </header>

      {/* Main Content */}
      <main id="main-content" className="flex-1 pb-32 md:pb-8" tabIndex={-1}>
        <div className="max-w-7xl mx-auto px-4 md:px-6 lg:px-8 py-4 md:py-5">
          <OnboardingGuard>{children}</OnboardingGuard>
        </div>
      </main>

      {/* Mobile Navigation Bar */}
      <MobileNav />

      {/* Global Transaction Modal */}
      <TransactionModal open={showTransactionModal} onOpenChange={setShowTransactionModal} />

      <GlobalSearch open={showSearch} onOpenChange={setShowSearch} />
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate, useLocation } from "react-router-dom";
