// AUDITORIA 2026-05-10: Componente de Navega├º├úo Inferior para Mobile com BottomSheet.
// Foco em usabilidade com uma m├úo s├│ e est├®tica de app nativo.

export function MobileNav() {
  const navigate = useNavigate();
  const location = useLocation();
  const { setShowTransactionModal } = useTransactionModal();
  const [isSheetOpen, setIsSheetOpen] = useState(false);
  const { theme, setTheme, systemTheme } = useTheme();
  const { signOut } = useAuth();

  const currentTheme = theme === "system" ? systemTheme : theme;
  const isDark = currentTheme === "dark";

  const toggleTheme = () => {
    setTheme(isDark ? "light" : "dark");
  };

  const handleSignOut = async () => {
    await signOut();
    navigate("/auth");
  };

  const closeSheet = () => setIsSheetOpen(false);

  // Fecha o sheet caso a rota mude (pelo bot├úo voltar do Android, por exemplo)
  useEffect(() => {
    closeSheet();
  }, [location.pathname]);

  const navItems = [
    { label: "In├¡cio", icon: Home, path: "/" },
    { label: "Extrato", icon: ArrowLeftRight, path: "/transacoes" },
    { label: "Add", icon: Plus, isAction: true },
    { label: "Relat├│rios", icon: BarChart2, path: "/relatorios" },
    { label: "Mais", icon: Grid3X3, isMenu: true },
  ];

  const sheetItems = navigationItems;

  const isActive = (path: string) => location.pathname === path;

  return (
    <>
      {/* Overlay do Bottom Sheet */}
      {isSheetOpen && (
        <div
          className="md:hidden fixed inset-0 z-[60] bg-background/80 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={closeSheet}
        />
      )}

      {/* Bottom Sheet Modal */}
      <div
        className={cn(
          "md:hidden fixed bottom-0 left-0 right-0 z-[70] bg-background border-t border-border rounded-t-3xl shadow-[0_-10px_40px_rgba(0,0,0,0.1)] transition-transform duration-300 ease-out flex flex-col",
          isSheetOpen ? "translate-y-0" : "translate-y-full"
        )}
        style={{ maxHeight: "85vh" }}
      >
        <div className="w-full flex justify-center py-3" onClick={closeSheet}>
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>

        <div className="px-6 pb-6 overflow-y-auto no-scrollbar flex-1">
          <div className="flex items-center justify-between mb-4">
            <h2 className="font-display font-semibold text-base">Explorar</h2>
            <button
              onClick={closeSheet}
              className="p-2 bg-muted/50 rounded-full text-muted-foreground hover:text-foreground"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          <div className="grid gap-2 mb-6">
            {[...navigationItems, ...secondaryNavItems].map((item) => {
              const active = isActive(item.path);
              const Icon = item.icon;
              return (
                <button
                  key={item.path}
                  onClick={() => {
                    navigate(item.path);
                    closeSheet();
                  }}
                  className={cn(
                    "flex items-center gap-3 w-full p-3 rounded-xl transition-all duration-200",
                    active
                      ? "bg-primary text-primary-foreground font-medium shadow-md shadow-primary/20"
                      : "bg-card text-foreground hover:bg-muted"
                  )}
                >
                  <Icon className="w-5 h-5" />
                  <span>{item.label}</span>
                </button>
              );
            })}
          </div>

          <div className="space-y-2 border-t border-border pt-4">
            <button
              onClick={() => {
                toggleTheme();
              }}
              className="flex items-center gap-3 w-full p-3 rounded-xl bg-card text-foreground hover:bg-muted transition-colors"
            >
              {isDark ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
              <span>{isDark ? "Tema Claro" : "Tema Escuro"}</span>
            </button>

            <button
              onClick={() => {
                navigate("/configuracoes");
                closeSheet();
              }}
              className="flex items-center gap-3 w-full p-3 rounded-xl bg-card text-foreground hover:bg-muted transition-colors"
            >
              <Settings className="w-5 h-5" />
              <span>Configura├º├Áes</span>
            </button>

            <button
              onClick={() => {
                closeSheet();
                handleSignOut();
              }}
