                    className="max-w-xs"
                    placeholder="Seu nome"
                    autoFocus
                  />
                  <Button size="sm" onClick={handleSaveName} disabled={updateProfile.isPending}>
                    {updateProfile.isPending ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                  </Button>
                  <Button size="sm" variant="ghost" onClick={() => { setEditingName(false); setNewName(profile?.name || ""); }}>
                    Cancelar
                  </Button>
                </div>
              ) : (
                <div className="flex items-center gap-2">
                  <p className="font-semibold text-base">{profile?.name || "Sem nome"}</p>
                  <Button size="sm" variant="ghost" onClick={() => setEditingName(true)}>Editar</Button>
                </div>
              )}
              <p className="text-sm text-muted-foreground flex items-center gap-1">
                <Mail className="h-3 w-3" />
                {user?.email}
              </p>
            </div>
          </div>
        </div>

        <div className="p-4 rounded-xl border border-border">
          <div className="mb-4">
            <p className="font-medium mb-1">Personalizar Avatar</p>
            <p className="text-sm text-muted-foreground">Escolha uma cor e ├¡cone para seu perfil</p>
          </div>
          <AvatarCustomizer
            currentColor={profile?.avatar_color || "green"}
            currentIcon={profile?.avatar_icon || "avatar_1"}
            onSave={async (color, icon) => {
              const selectedAvatar = avatarIcons.find(a => a.id === icon);
              const avatarPath = selectedAvatar?.path || null;
              await updateProfile.mutateAsync({ 
                avatar_url: avatarPath,
                avatar_color: color,
                avatar_icon: icon
              });
            }}
            isSaving={updateProfile.isPending}
          />
        </div>

        <div className="p-4 rounded-xl border border-border hover:border-foreground/20 transition-all">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                <LogOut className="h-5 w-5" />
              </div>
              <div>
                <p className="font-medium">Sair da Conta</p>
                <p className="text-sm text-muted-foreground">Encerrar sess├úo neste dispositivo</p>
              </div>
            </div>
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <Button variant="outline">Sair</Button>
              </AlertDialogTrigger>
              <AlertDialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden">
                <div className="px-6 pt-6 pb-2">
                  <AlertDialogHeader>
                    <AlertDialogTitle>Voc├¬ deseja realmente sair?</AlertDialogTitle>
                    <AlertDialogDescription>
                      Voc├¬ precisar├í fazer login novamente para acessar seus dados financeiros.
                    </AlertDialogDescription>
                  </AlertDialogHeader>
                </div>
                <div className="px-6 pb-6">
                  <AlertDialogFooter>
                    <AlertDialogCancel>Cancelar</AlertDialogCancel>
                    <AlertDialogAction onClick={signOut}>Sair</AlertDialogAction>
                  </AlertDialogFooter>
                </div>
              </AlertDialogContent>
            </AlertDialog>
          </div>
        </div>

        <div className="pt-6 border-t border-border">
          <h3 className="text-sm font-medium text-destructive uppercase tracking-wider mb-3">Zona de Perigo</h3>
          <div className="p-4 rounded-xl border border-destructive/30 bg-destructive/5">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 rounded-xl bg-destructive/10 flex items-center justify-center">
                  <AlertTriangle className="h-5 w-5 text-destructive" />
                </div>
                <div>
                  <p className="font-medium text-destructive">Excluir Conta</p>
                  <p className="text-sm text-muted-foreground">Esta a├º├úo ├® irrevers├¡vel</p>
                </div>
              </div>
              <Button variant="destructive" onClick={onDeleteAccount}>Excluir</Button>
            </div>
          </div>
        </div>
      </div>

    </div>
  );
}

import { useState } from "react";
import { Plus, Trash2, ToggleLeft, ToggleRight, Zap } from "lucide-react";
import { EmptyState } from "@/components/ui/empty-state";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { useAutoShareRules, useCreateAutoShareRule, useDeleteAutoShareRule, useUpdateAutoShareRule } from "@/hooks/useAutoShareRules";
import { useFamilyMembers } from "@/hooks/useFamily";
import { useCategories } from "@/hooks/useCategories";
import { cn } from "@/lib/utils";
import { NumericFormat } from "react-number-format";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

export function AutoShareRulesSettings() {
  const { data: rules = [], isLoading } = useAutoShareRules();
  const { data: members = [] } = useFamilyMembers();
  const { data: categories = [] } = useCategories();
  const createRule = useCreateAutoShareRule();
  const deleteRule = useDeleteAutoShareRule();
  const updateRule = useUpdateAutoShareRule();

  const [showForm, setShowForm] = useState(false);
  const [name, setName] = useState("");
  const [triggerType, setTriggerType] = useState<"category" | "keyword">("keyword");
  const [triggerValue, setTriggerValue] = useState("");
  const [memberId, setMemberId] = useState("");
  const [splitRatio, setSplitRatio] = useState(50);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);

  const activeMembers = members.filter(m => m.linked_user_id !== undefined || m.name);

  const handleCreate = async () => {
    if (!name || !triggerValue || !memberId) return;
    await createRule.mutateAsync({
      name,
      trigger_type: triggerType,
      trigger_value: triggerValue,
      member_id: memberId,
      split_ratio: splitRatio / 100,
    });
    setShowForm(false);
    setName(""); setTriggerValue(""); setMemberId(""); setSplitRatio(50);
  };

  const expenseCategories = categories.filter(c => c.type === "expense" && !c.parent_category_id);

  if (isLoading) return null;

  return (
    <div className="space-y-8 animate-fade-in">
      <div>
        <h2 className="font-display font-semibold text-lg flex items-center gap-2">
          <Zap className="h-5 w-5 text-primary" />
          Automa├º├Áes de Compartilhamento
        </h2>
        <p className="text-sm text-muted-foreground mt-1">
          Crie regras para que despesas sejam automaticamente divididas com membros da fam├¡lia quando lan├ºadas.
          Ex: toda compra no "Supermercado" j├í vai 50% para a esposa.
        </p>
      </div>

      {/* Rules list */}
      <div className="space-y-3">
        {rules.length === 0 && !showForm && (
          <EmptyState
            icon={Zap}
            title="Nenhuma regra configurada"
            description="Adicione regras para automatizar o compartilhamento de despesas."
          />
        )}

        {rules.map(rule => {
          const member = members.find(m => m.id === rule.member_id);
          const category = categories.find(c => c.id === rule.trigger_value);
          return (
            <div key={rule.id} className={cn(
              "flex items-center gap-3 p-4 rounded-2xl border transition-all",
              rule.is_active ? "border-border/50 bg-card" : "border-border/30 bg-muted/30 opacity-60"
            )}>
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-sm">{rule.name}</p>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {rule.trigger_type === "category"
                    ? `Categoria: ${category?.icon ?? ""} ${category?.name ?? rule.trigger_value}`
                    : `Palavra-chave: "${rule.trigger_value}"`
                  }
                  {" ┬À "}
                  <span className="font-medium text-foreground">{(rule.split_ratio * 100).toFixed(0)}%</span>
                  {" com "}
                  <span className="font-medium text-foreground">{member?.name ?? "membro"}</span>
                </p>
              </div>
              <Switch
                checked={rule.is_active}
                onCheckedChange={(v) => updateRule.mutate({ id: rule.id, is_active: v })}
              />
              <Button
                size="icon"
                variant="ghost"
                className="h-8 w-8 text-destructive hover:bg-destructive/10 shrink-0"
                onClick={() => setConfirmDeleteId(rule.id)}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          );
        })}
      </div>

      {/* Add form */}
      {showForm ? (
        <div className="p-5 rounded-2xl border border-primary/20 bg-primary/5 space-y-4">
          <h3 className="font-bold text-sm">Nova Regra</h3>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label>Nome da regra</Label>
              <Input
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder='Ex: "Mercado com esposa"'
              />
            </div>

            <div className="space-y-1.5">
              <Label>Disparar por</Label>
              <Select value={triggerType} onValueChange={v => { setTriggerType(v as any); setTriggerValue(""); }}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="keyword">Palavra-chave na descri├º├úo</SelectItem>
                  <SelectItem value="category">Categoria da transa├º├úo</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <Label>{triggerType === "keyword" ? "Palavra-chave" : "Categoria"}</Label>
              {triggerType === "keyword" ? (
                <Input
                  value={triggerValue}
                  onChange={e => setTriggerValue(e.target.value)}
                  placeholder='Ex: "mercado", "escola", "farm├ícia"'
                />
              ) : (
                <Select value={triggerValue} onValueChange={setTriggerValue}>
                  <SelectTrigger><SelectValue placeholder="Selecionar categoria" /></SelectTrigger>
                  <SelectContent>
                    {expenseCategories.map(c => (
                      <SelectItem key={c.id} value={c.id}>{c.icon} {c.name}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="space-y-1.5">
              <Label>Dividir com</Label>
              <Select value={memberId} onValueChange={setMemberId}>
                <SelectTrigger><SelectValue placeholder="Selecionar membro" /></SelectTrigger>
                <SelectContent>
                  {activeMembers.map(m => (
                    <SelectItem key={m.id} value={m.id}>{m.name}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5 sm:col-span-2">
              <Label>Percentual que o membro paga</Label>
              <div className="flex items-center gap-3">
                <NumericFormat
                  value={splitRatio}
                  onValueChange={v => setSplitRatio(v.floatValue ?? 50)}
                  decimalScale={0}
                  suffix="%"
                  className="w-24 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                />
                <p className="text-xs text-muted-foreground">
                  Voc├¬ paga <strong>{100 - splitRatio}%</strong> ┬À membro paga <strong>{splitRatio}%</strong>
                </p>
              </div>
            </div>
          </div>

          <div className="flex gap-2 justify-end">
            <Button variant="outline" onClick={() => setShowForm(false)}>Cancelar</Button>
            <Button
              onClick={handleCreate}
              disabled={!name || !triggerValue || !memberId || createRule.isPending}
            >
              Salvar Regra
            </Button>
          </div>
        </div>
      ) : (
        <Button variant="outline" className="gap-2 w-full sm:w-auto" onClick={() => setShowForm(true)}>
          <Plus className="h-4 w-4" />
          Nova Regra de Auto-Compartilhamento
        </Button>
      )}

      <AlertDialog open={!!confirmDeleteId} onOpenChange={(open) => !open && setConfirmDeleteId(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir regra?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta a├º├úo n├úo pode ser desfeita. A regra de compartilhamento autom├ítico ser├í removida permanentemente.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => {
                if (confirmDeleteId) deleteRule.mutate(confirmDeleteId);
                setConfirmDeleteId(null);
              }}
            >
              Excluir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useQueryClient } from "@tanstack/react-query";
import { Download, Upload, AlertTriangle, ShieldAlert, CheckCircle, Database } from "lucide-react";
import { toast } from "sonner";
import { logger } from "@/utils/logger";

interface BackupData {
  version: string;
  exportedAt: string;
  userId: string;
  data: {
    accounts: any[];
    categories: any[];
    transactions: any[];
    transaction_splits: any[];
    trips: any[];
    trip_members: any[];
    trip_itinerary: any[];
    trip_checklist: any[];
    trip_exchange_purchases: any[];
    budgets: any[];
    goals: any[];
    assets: any[];
    asset_transactions: any[];
    notification_preferences: any[];
  };
}

export function BackupManager() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [isExporting, setIsExporting] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [importProgress, setImportProgress] = useState<{ step: string; percent: number }>({ step: "", percent: 0 });
  const [confirmText, setConfirmText] = useState("");
  const [importedFile, setImportedFile] = useState<BackupData | null>(null);

  // 1. Exportar Backup
  const handleExport = async () => {
    if (!user) return;
    setIsExporting(true);
    toast.info("Iniciando exporta├º├úo completa de dados...");

    try {
      const getTableData = async (tableName: string) => {
        const { data, error } = await supabase
          .from(tableName)
          .select("*");
        if (error) {
          logger.error(`Erro ao exportar tabela ${tableName}:`, error);
          throw error;
        }
        return data || [];
      };

      const [
        accounts,
        categories,
        transactions,
        transaction_splits,
        trips,
        trip_members,
        trip_itinerary,
        trip_checklist,
        trip_exchange_purchases,
        budgets,
        goals,
        assets,
        asset_transactions,
        notification_preferences
      ] = await Promise.all([
        getTableData("accounts"),
        getTableData("categories"),
        getTableData("transactions"),
        getTableData("transaction_splits"),
        getTableData("trips"),
        getTableData("trip_members"),
        getTableData("trip_itinerary"),
        getTableData("trip_checklist"),
        getTableData("trip_exchange_purchases"),
        getTableData("budgets"),
        getTableData("goals"),
        getTableData("assets"),
        getTableData("asset_transactions"),
        getTableData("notification_preferences")
      ]);

      const backup: BackupData = {
        version: "1.0",
        exportedAt: new Date().toISOString(),
        userId: user.id,
        data: {
          accounts,
          categories,
          transactions,
          transaction_splits,
          trips,
          trip_members,
          trip_itinerary,
          trip_checklist,
          trip_exchange_purchases,
          budgets,
          goals,
          assets,
          asset_transactions,
          notification_preferences
        }
      };

      // Disparar download do arquivo JSON
      const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `pe-de-meia-backup-${new Date().toISOString().split('T')[0]}.json`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast.success("Todos os dados do sistema foram exportados com orgulho cont├íbil!");
    } catch (error) {
      logger.error(error);
      toast.error("Falha ao exportar backup.");
    } finally {
      setIsExporting(false);
    }
  };

  // 2. Upload do Arquivo para Pr├®-visualiza├º├úo
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (!json.version || !json.data || !json.data.accounts || !json.data.categories) {
          toast.error("Formato de backup inv├ílido.");
          return;
        }
        setImportedFile(json);
        setConfirmText("");
        toast.success("Arquivo de backup carregado com sucesso. Pronto para restaura├º├úo.");
      } catch (err) {
        toast.error("Erro ao ler o arquivo JSON.");
      }
    };
    reader.readAsText(file);
  };

  // 3. Executar Restaura├º├úo Completa
  const handleRestore = async () => {
    if (!user || !importedFile) return;
    if (confirmText !== "RESTAURAR") {
      toast.warning("Por favor, digite RESTAURAR para prosseguir.");
      return;
    }

    setIsImporting(true);
    const data = importedFile.data;

    try {
      // Helper para deletar em lote
      const cleanTable = async (tableName: string) => {
        const { error } = await supabase.from(tableName).delete().eq("user_id", user.id);
        if (error) {
          logger.error(`Erro ao limpar tabela ${tableName}:`, error);
          throw error;
        }
      };

      // Helper para inserir em lote mantendo IDs originais
      const insertRows = async (tableName: string, rows: any[]) => {
        if (!rows || rows.length === 0) return;
        
        // Garante que cada linha est├í associada ao usu├írio correto (seguran├ºa extra!)
        const safeRows = rows.map(r => ({ ...r, user_id: user.id }));
        
        const { error } = await supabase.from(tableName).insert(safeRows);
        if (error) {
          logger.error(`Erro ao restaurar tabela ${tableName}:`, error);
          throw error;
        }
      };

      // PASSO 1: LIMPAR DADOS EXISTENTES (Respeitando Constraints de Foreign Key)
      setImportProgress({ step: "1. Limpando dados atuais do usu├írio...", percent: 10 });
      await cleanTable("asset_transactions");
      await cleanTable("assets");
      await cleanTable("transaction_splits");
      await cleanTable("transactions");
      await cleanTable("budgets");
      await cleanTable("goals");
      await cleanTable("trip_itinerary");
      await cleanTable("trip_checklist");
      await cleanTable("trip_exchange_purchases");
      await cleanTable("trip_members");
      await cleanTable("trips");
      await cleanTable("accounts");
      await cleanTable("categories");

      // PASSO 2: RESTAURAR DADOS EM ORDEM DE INDEPEND├èNCIA
      setImportProgress({ step: "2. Restaurando categorias...", percent: 25 });
      await insertRows("categories", data.categories);

      setImportProgress({ step: "3. Restaurando contas...", percent: 40 });
      await insertRows("accounts", data.accounts);

      setImportProgress({ step: "4. Restaurando objetivos de poupan├ºa...", percent: 50 });
      await insertRows("goals", data.goals);

      setImportProgress({ step: "5. Restaurando or├ºamentos mensais...", percent: 60 });
      await insertRows("budgets", data.budgets);

      setImportProgress({ step: "6. Restaurando viagens organizadas...", percent: 70 });
      await insertRows("trips", data.trips);
      await insertRows("trip_members", data.trip_members);
      await insertRows("trip_itinerary", data.trip_itinerary);
      await insertRows("trip_checklist", data.trip_checklist);
      await insertRows("trip_exchange_purchases", data.trip_exchange_purchases);

      setImportProgress({ step: "7. Restaurando investimentos e ativos...", percent: 80 });
      await insertRows("assets", data.assets);
      await insertRows("asset_transactions", data.asset_transactions);

      setImportProgress({ step: "8. Restaurando transa├º├Áes e lan├ºamentos...", percent: 90 });
      await insertRows("transactions", data.transactions);
      await insertRows("transaction_splits", data.transaction_splits);

      setImportProgress({ step: "9. Sincronizando prefer├¬ncias...", percent: 98 });
      await insertRows("notification_preferences", data.notification_preferences);

      setImportProgress({ step: "Conclu├¡do!", percent: 100 });
      toast.success("Sistema restaurado com sucesso absoluto para a data do backup!");
      
      // Invalidar todas as queries para recarregar a interface
      queryClient.invalidateQueries();
      setImportedFile(null);
      setConfirmText("");
    } catch (error) {
      logger.error(error);
      toast.error("Ocorreu um erro cr├¡tico durante a restaura├º├úo do banco de dados.");
    } finally {
      setIsImporting(false);
      setImportProgress({ step: "", percent: 0 });
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="font-display font-black text-2xl tracking-tight">Backup e Dados</h2>
        <p className="text-sm text-muted-foreground">Exporta├º├úo integral e restaura├º├úo total do banco de dados</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        
        {/* Bloco de Exportar */}
        <Card className="p-6 border border-border bg-card/50 shadow-sm rounded-2xl flex flex-col justify-between">
          <div className="space-y-4">
            <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
              <Download className="h-5 w-5 text-primary" />
            </div>
            <div>
              <h3 className="font-semibold text-base">Exportar Backup Completo</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Gera um arquivo seguro contendo todas as suas transa├º├Áes, contas, categorias, metas, viagens e ativos. Ideal para guardar como c├│pia f├¡sica ou migrar de conta.
              </p>
            </div>
          </div>
          <Button 
            className="w-full mt-6 gap-2 rounded-xl h-10 font-medium" 
            onClick={handleExport}
            disabled={isExporting}
          >
            {isExporting ? "Exportando..." : "Baixar arquivo de Backup"}
          </Button>
        </Card>

        {/* Bloco de Restaurar */}
        <Card className="p-6 border border-border bg-card/50 shadow-sm rounded-2xl flex flex-col justify-between">
          <div className="space-y-4">
            <div className="h-10 w-10 rounded-xl bg-warning/10 flex items-center justify-center">
              <Upload className="h-5 w-5 text-warning" />
            </div>
            <div>
              <h3 className="font-semibold text-base">Restaurar do Backup</h3>
              <p className="text-sm text-muted-foreground mt-1">
                Substitui de forma completa todos os seus dados atuais pelas informa├º├Áes de um backup anterior.
              </p>
            </div>

            {/* Input de Arquivo */}
            <div className="space-y-2 mt-4">
              <Label htmlFor="backup-file" className="text-sm font-semibold uppercase tracking-wider text-muted-foreground">Selecionar arquivo de Backup (.json)</Label>
              <Input 
                id="backup-file" 
                type="file" 
                accept=".json" 
                onChange={handleFileChange}
                disabled={isImporting}
                className="cursor-pointer bg-muted/20 border-border/50 rounded-xl file:bg-primary file:text-white file:border-0 file:rounded-lg file:mr-2 file:text-sm file:font-semibold"
              />
            </div>
          </div>

          {importedFile && (
            <div className="mt-6 p-4 rounded-xl border border-destructive/20 bg-destructive/5 space-y-4">
              <div className="flex gap-3 text-destructive">
                <AlertTriangle className="h-5 w-5 shrink-0 mt-0.5" />
                <div className="text-sm space-y-2">
                  <p className="font-bold uppercase tracking-wide">Aten├º├úo Cr├¡tica</p>
                  <p>A restaura├º├úo ir├í deletar <strong>todos os seus lan├ºamentos, contas e configura├º├Áes atuais</strong> para inserir os dados do backup.</p>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="confirm-restore" className="text-sm font-bold uppercase text-muted-foreground">Digite RESTAURAR para autorizar:</Label>
                <Input 
                  id="confirm-restore"
                  placeholder="RESTAURAR"
                  value={confirmText}
                  onChange={(e) => setConfirmText(e.target.value)}
                  disabled={isImporting}
                  className="rounded-xl border-destructive/30 focus-visible:ring-destructive font-bold text-center placeholder:font-normal placeholder:text-muted-foreground/50 h-10"
                />
              </div>

              <Button 
                variant="destructive"
                className="w-full gap-2 rounded-xl h-10 font-bold" 
                onClick={handleRestore}
                disabled={isImporting || confirmText !== "RESTAURAR"}
              >
                {isImporting ? "Restaurando..." : "Confirmar Restaura├º├úo Total"}
              </Button>
            </div>
          )}
        </Card>
      </div>

      {/* Barra de Progresso da Restaura├º├úo */}
      {isImporting && (
        <Card className="p-6 border border-primary/20 bg-primary/5 rounded-2xl animate-pulse">
          <div className="space-y-4">
            <div className="flex items-center justify-between text-sm">
              <span className="font-semibold text-primary">{importProgress.step}</span>
              <span className="font-mono font-bold text-primary">{importProgress.percent}%</span>
            </div>
            <div className="w-full bg-muted rounded-full h-2.5 overflow-hidden">
              <div 
                className="bg-primary h-2.5 rounded-full transition-all duration-300 ease-out" 
                style={{ width: `${importProgress.percent}%` }}
              />
            </div>
          </div>
        </Card>
      )}
    </div>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Plus, Trash2, RefreshCw, Pencil, Check, X } from "lucide-react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { useUserProfile, useUpdateUserProfile } from "@/hooks/useUserProfile";
import { useCreateDefaultCategories, useUpdateCategory } from "@/hooks/useCategories";
import { toast } from "sonner";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { logger } from "@/utils/logger";

interface CategorySettingsProps {
  categories: any[];
  isLoading: boolean;
  onAddCategory: () => void;
  onDeleteCategory: (id: string) => void;
}

export function CategorySettings({
  categories,
  isLoading,
  onAddCategory,
  onDeleteCategory,
}: CategorySettingsProps) {
  const { data: profile } = useUserProfile();
  const updateProfile = useUpdateUserProfile();
  const createDefaultCategories = useCreateDefaultCategories();
  const updateCategory = useUpdateCategory();
  const useSubcategories = profile?.use_subcategories ?? false;

  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState("");
  const [editIcon, setEditIcon] = useState("");

  const startEdit = (cat: any) => {
    setEditingId(cat.id);
    setEditName(cat.name);
    setEditIcon(cat.icon || "");
  };

  const cancelEdit = () => {
    setEditingId(null);
    setEditName("");
    setEditIcon("");
  };

  const saveEdit = async (id: string) => {
    if (!editName.trim()) return;
    showActionFeedback("success");
    setTimeout(() => {
      setEditingId(null);
      setEditName("");
      setEditIcon("");
    }, 80);
    try {
      updateCategory.mutate({
        id,
        name: editName.trim(),
        icon: editIcon.trim() || "­ƒôª",
      });
    } catch (err) {
      logger.error("Erro ao atualizar categoria", err instanceof Error ? err : undefined);
    }
  };

  const handleDelete = (id: string) => {
    showActionFeedback("error");
    onDeleteCategory(id);
  };

  const handleRestoreDefaults = () => {
    toast.promise(createDefaultCategories.mutateAsync({ force: true }), {
      loading: "Restaurando categorias padr├úo...",
      success: "Categorias padr├úo recriadas e atualizadas com sucesso!",
      error: "Erro ao recriar categorias",
    });
  };

  if (isLoading) {
    return (
      <div className="grid grid-cols-2 gap-2">
        {[1, 2, 3, 4].map((i) => (
          <div key={i} className="h-12 bg-muted rounded animate-pulse" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="font-display font-semibold text-lg">Categorias</h2>
          <p className="text-sm text-muted-foreground">Organize suas transa├º├Áes</p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            onClick={handleRestoreDefaults}
            disabled={createDefaultCategories.isPending}
            className="transition-all"
          >
            <RefreshCw
              className={`h-4 w-4 mr-2 ${createDefaultCategories.isPending ? "animate-spin" : ""}`}
            />
            Restaurar Padr├úo
          </Button>
          <Button
            onClick={onAddCategory}
            className="group transition-all hover:scale-[1.02] active:scale-[0.98]"
          >
            <Plus className="h-4 w-4 mr-2 transition-transform group-hover:rotate-90" />
            Nova
          </Button>
        </div>
      </div>

      {/* Switch Premium para ativar/desativar subcategorias */}
      <div className="flex items-center justify-between p-4 rounded-2xl border border-primary/20 bg-primary/5 dark:bg-primary/10 backdrop-blur-sm shadow-sm transition-all duration-300 hover:border-primary/30">
        <div className="space-y-2 pr-4">
          <Label
            htmlFor="toggle-subcategories"
            className="font-bold text-sm sm:text-base cursor-pointer"
          >
            Ativar Subcategorias e Hierarquia
          </Label>
          <p className="text-xs text-muted-foreground max-w-md">
            Mostra subcategorias detalhadas nos seletores de transa├º├úo (Ex: Supermercado dentro de
            Alimenta├º├úo). Se desativado, o sistema exibir├í apenas as categorias principais.
          </p>
        </div>
        <Switch
          id="toggle-subcategories"
          checked={useSubcategories}
          onCheckedChange={(checked) => {
            updateProfile.mutate({ use_subcategories: checked });
          }}
          disabled={updateProfile.isPending}
        />
      </div>

      <div className="space-y-4">
        <div className="space-y-6">
          {["expense", "income"].map((type) => {
            const typeCategories = categories.filter((c) => c.type === type);
            const parentCategories = typeCategories.filter((c) => !c.parent_category_id);

            return (
              <div key={type}>
                <h3 className="text-xs uppercase tracking-widest text-muted-foreground font-bold mb-4 px-1">
                  {type === "expense" ? "Despesas" : "Receitas"}
                </h3>
                <div className="space-y-3">
                  {parentCategories.map((parent) => {
                    const children = typeCategories.filter(
                      (c) => c.parent_category_id === parent.id
                    );

                    return (
                      <div key={parent.id} className="space-y-2">
                        {/* Categoria Pai */}
                        {editingId === parent.id ? (
                          <div className="flex items-center gap-2 p-2 rounded-2xl border border-primary/40 bg-primary/5">
                            <Input
                              value={editIcon}
                              onChange={(e) => setEditIcon(e.target.value)}
                              className="w-14 text-center text-lg p-1 h-9"
                              placeholder="­ƒÅá"
                              maxLength={4}
                            />
                            <Input
                              value={editName}
                              onChange={(e) => setEditName(e.target.value)}
                              className="flex-1 h-9"
                              onKeyDown={(e) => {
                                if (e.key === "Enter") saveEdit(parent.id);
                                if (e.key === "Escape") cancelEdit();
                              }}
                              autoFocus
                            />
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-9 w-9 text-success hover:bg-success/10"
                              onClick={() => saveEdit(parent.id)}
                              disabled={updateCategory.isPending}
                            >
                              <Check className="h-4 w-4" />
                            </Button>
                            <Button
                              size="icon"
                              variant="ghost"
                              className="h-9 w-9"
                              onClick={cancelEdit}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </div>
                        ) : (
                          <div className="group flex items-center justify-between p-3 rounded-2xl border border-border/60 bg-card hover:border-primary/30 transition-all shadow-sm">
                            <div className="flex items-center gap-3">
                              <span className="text-xl">{parent.icon}</span>
                              <span className="font-bold text-sm sm:text-base">{parent.name}</span>
                            </div>
                            <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 hover:bg-primary/10 text-muted-foreground hover:text-primary"
                                onClick={() => startEdit(parent)}
                              >
                                <Pencil className="h-3.5 w-3.5" />
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-8 w-8 text-destructive hover:bg-destructive/10"
                                onClick={() => handleDelete(parent.id)}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            </div>
                          </div>
                        )}

                        {/* Subcategorias (Filhas) */}
                        {useSubcategories && children.length > 0 && (
                          <div className="ml-6 pl-4 border-l-2 border-border/40 space-y-2">
                            {children.map((child) =>
                              editingId === child.id ? (
                                <div
                                  key={child.id}
                                  className="flex items-center gap-2 p-1.5 rounded-xl border border-primary/40 bg-primary/5"
                                >
                                  <Input
                                    value={editIcon}
                                    onChange={(e) => setEditIcon(e.target.value)}
                                    className="w-12 text-center text-base p-1 h-8"
                                    placeholder="­ƒÅá"
                                    maxLength={4}
                                  />
                                  <Input
                                    value={editName}
                                    onChange={(e) => setEditName(e.target.value)}
                                    className="flex-1 h-8 text-sm"
                                    onKeyDown={(e) => {
                                      if (e.key === "Enter") saveEdit(child.id);
                                      if (e.key === "Escape") cancelEdit();
                                    }}
                                    autoFocus
                                  />
                                  <Button
                                    size="icon"
                                    variant="ghost"
                                    className="h-8 w-8 text-success hover:bg-success/10"
                                    onClick={() => saveEdit(child.id)}
                                    disabled={updateCategory.isPending}
                                  >
                                    <Check className="h-3.5 w-3.5" />
                                  </Button>
                                  <Button
                                    size="icon"
                                    variant="ghost"
                                    className="h-8 w-8"
                                    onClick={cancelEdit}
                                  >
                                    <X className="h-3.5 w-3.5" />
                                  </Button>
                                </div>
                              ) : (
                                <div
                                  key={child.id}
                                  className="group flex items-center justify-between p-2.5 rounded-xl border border-dashed border-border/80 bg-muted/20 hover:bg-muted/40 transition-all"
                                >
                                  <div className="flex items-center gap-2">
                                    <span className="text-base">{child.icon}</span>
                                    <span className="text-sm font-medium text-muted-foreground group-hover:text-foreground transition-colors">
                                      {child.name}
                                    </span>
                                  </div>
                                  <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-7 w-7 hover:bg-primary/10 text-muted-foreground hover:text-primary"
                                      onClick={() => startEdit(child)}
                                    >
                                      <Pencil className="h-3 w-3" />
                                    </Button>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      className="h-7 w-7 text-destructive/70 hover:text-destructive"
                                      onClick={() => onDeleteCategory(child.id)}
                                    >
                                      <Trash2 className="h-3.5 w-3.5" />
                                    </Button>
                                  </div>
                                </div>
                              )
                            )}
                          </div>
                        )}
                      </div>
                    );
                  })}

                  {/* Categorias ├ôrf├ús (Sem pai e n├úo s├úo pais de ningu├®m - caso ocorra erro de dados) */}
                  {typeCategories
                    .filter(
                      (c) => !c.parent_category_id && !parentCategories.find((p) => p.id === c.id)
                    )
                    .map((orphan) => (
                      <div
                        key={orphan.id}
                        className="group flex items-center justify-between p-3 rounded-xl border border-border"
                      >
                        <div className="flex items-center gap-3">
                          <span className="text-xl">{orphan.icon}</span>
                          <span className="font-medium">{orphan.name}</span>
                        </div>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 opacity-0 group-hover:opacity-100 text-destructive"
                          onClick={() => handleDelete(orphan.id)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    ))}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { Users } from "lucide-react";
import { cn } from "@/lib/utils";
import { EmptyState } from "@/components/ui/empty-state";

interface PeopleSettingsProps {
  members: any[];
  isLoading: boolean;
  getInitials: (name: string) => string;
}

export function PeopleSettings({ members, isLoading, getInitials }: PeopleSettingsProps) {
  if (isLoading) {
    return (
      <div className="space-y-2">
        {[1, 2, 3].map(i => (
          <div key={i} className="h-16 bg-muted rounded animate-pulse" />
        ))}
      </div>
    );
  }

  if (members.length === 0) {
    return (
      <EmptyState
        icon={Users}
        title="Nenhum membro"
        description="Adicione membros na p├ígina Fam├¡lia para gerenci├í-los aqui."
      />
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h2 className="font-display font-semibold text-lg">Pessoas</h2>
        <p className="text-sm text-muted-foreground">Membros para dividir despesas</p>
      </div>
      <div className="space-y-2">
        {members.map((person) => (
          <div
            key={person.id}
            className="group flex items-center justify-between p-4 rounded-xl border border-border 
                       hover:border-foreground/20 transition-all duration-200 hover:shadow-sm"
          >
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-full bg-gradient-to-br from-foreground/80 to-foreground 
                              text-background flex items-center justify-center font-medium
                              transition-transform duration-200 group-hover:scale-110">
                {getInitials(person.name)}
              </div>
              <div>
                <p className="font-medium">{person.name}</p>
                <p className="text-sm text-muted-foreground">{person.email}</p>
              </div>
            </div>
            <span className={cn(
              "text-xs px-2 py-0.5 rounded-full",
              person.role === "admin" ? "bg-foreground text-background" : "bg-muted"
            )}>
              {person.role === "admin" ? "Admin" : person.role === "editor" ? "Editor" : "Visualizador"}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Coins,
  CalendarDays,
  TrendingDown,
  CreditCard,
  BellRing,
  Wallet,
} from "lucide-react";
import { UserProfile } from "@/hooks/useUserProfile";
import { useAccounts } from "@/hooks/useAccounts";
import { NumericFormat } from "react-number-format";
import { InfoTooltip } from "@/components/ui/info-tooltip";

interface PreferencesSettingsProps {
  profile: UserProfile | null;
  isLoading: boolean;
  updateProfile: any;
}

export function PreferencesSettings({
  profile,
  isLoading,
  updateProfile,
}: PreferencesSettingsProps) {
  const { data: accounts } = useAccounts();
  const [baseCurrency, setBaseCurrency] = useState("BRL");
  const [monthStartDay, setMonthStartDay] = useState("1");
  const [monthlyBudget, setMonthlyBudget] = useState(0);
  const [sharedSyncCreditCardId, setSharedSyncCreditCardId] = useState<string>("none");
  const [globalCdiRate, setGlobalCdiRate] = useState<number>(11.15);
  const [lowBalanceThreshold, setLowBalanceThreshold] = useState<number>(0);
  const [defaultAccountId, setDefaultAccountId] = useState<string>("none");
  const [defaultCreditCardId, setDefaultCreditCardId] = useState<string>("none");
  const [monthlyReportEnabled, setMonthlyReportEnabled] = useState<boolean>(true);

  const creditCards = accounts?.filter((acc) => acc.type === "CREDIT_CARD") || [];
  const checkingAccounts = accounts?.filter((acc) => acc.type !== "CREDIT_CARD") || [];

  useEffect(() => {
    if (profile) {
      setBaseCurrency(profile.base_currency || "BRL");
      setMonthStartDay(profile.month_start_day?.toString() || "1");
      setMonthlyBudget(profile.monthly_budget || 0);

      let initialCardId = profile.shared_sync_credit_card_id || "none";
      setSharedSyncCreditCardId(initialCardId);
      setGlobalCdiRate(profile.global_cdi_rate ?? 11.15);
      setLowBalanceThreshold(profile.low_balance_threshold ?? 0);
      setDefaultAccountId(profile.default_account_id ?? "none");
      setDefaultCreditCardId(profile.default_credit_card_id ?? "none");
      setMonthlyReportEnabled(profile.monthly_report_enabled ?? true);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [profile]);

  const handleSave = async () => {
    await updateProfile.mutateAsync({
      baseCurrency: baseCurrency,
      month_start_day: parseInt(monthStartDay, 10) || 1,
      monthly_budget: monthlyBudget,
      shared_expenses_behavior: "CYCLE",
      shared_sync_credit_card_id: sharedSyncCreditCardId === "none" ? null : sharedSyncCreditCardId,
      global_cdi_rate: globalCdiRate,
      low_balance_threshold: lowBalanceThreshold || null,
      default_account_id: defaultAccountId === "none" ? null : defaultAccountId,
      default_credit_card_id: defaultCreditCardId === "none" ? null : defaultCreditCardId,
    });
  };

  const hasChanges = () => {
    if (!profile) return false;
    const currentCardId = profile.shared_sync_credit_card_id || "none";
    return (
      baseCurrency !== (profile.base_currency || "BRL") ||
      monthStartDay !== (profile.month_start_day?.toString() || "1") ||
      monthlyBudget !== (profile.monthly_budget || 0) ||
      sharedSyncCreditCardId !== currentCardId ||
      globalCdiRate !== (profile.global_cdi_rate ?? 11.15) ||
      lowBalanceThreshold !== (profile.low_balance_threshold ?? 0) ||
      defaultAccountId !== (profile.default_account_id ?? "none") ||
      defaultCreditCardId !== (profile.default_credit_card_id ?? "none")
    );
  };

  if (isLoading) {
    return (
      <div className="flex justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in">
      <div>
        <h2 className="font-display font-semibold text-lg">Prefer├¬ncias Financeiras</h2>
        <p className="text-sm text-muted-foreground">
          Configure as moedas, datas e limites globais da sua conta.
        </p>
      </div>

      <div className="space-y-6 max-w-2xl">
        <div className="space-y-4">
          {/* CONTA PADR├âO */}
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
            <div className="p-3 bg-primary/10 text-primary rounded-xl shrink-0">
              <Wallet className="h-5 w-5" />
            </div>
            <div className="flex-1 space-y-2 w-full">
              <div className="flex items-center gap-2">
                <Label>Conta Padr├úo</Label>
                <InfoTooltip content="Pr├®-selecionada ao abrir nova transa├º├úo de receita ou transfer├¬ncia." />
              </div>
              <Select value={defaultAccountId} onValueChange={setDefaultAccountId}>
                <SelectTrigger>
                  <SelectValue placeholder="Sem padr├úo" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">Sem conta padr├úo</SelectItem>
                  {checkingAccounts.map((acc) => (
                    <SelectItem key={acc.id} value={acc.id}>
                      {acc.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* CART├âO PADR├âO */}
          {creditCards.length > 0 && (
            <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
              <div className="p-3 bg-primary/10 text-primary rounded-xl shrink-0">
                <CreditCard className="h-5 w-5" />
              </div>
              <div className="flex-1 space-y-2 w-full">
                <div className="flex items-center gap-2">
                  <Label>Cart├úo Padr├úo</Label>
                  <InfoTooltip content="Pr├®-selecionado ao abrir nova despesa. Tem prioridade sobre a conta padr├úo." />
                </div>
                <Select value={defaultCreditCardId} onValueChange={setDefaultCreditCardId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sem padr├úo" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">Sem cart├úo padr├úo</SelectItem>
                    {creditCards.map((card) => (
                      <SelectItem key={card.id} value={card.id}>
                        {card.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}

          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center">
            <div className="p-3 bg-primary/10 text-primary rounded-xl shrink-0">
              <CalendarDays className="h-5 w-5" />
            </div>
            <div className="flex-1 space-y-2 w-full animate-in slide-in-from-bottom-2 duration-300 delay-100 fill-mode-both">
              <div className="flex items-center gap-2">
                <Label>Dia de In├¡cio do M├¬s</Label>
                <InfoTooltip content="Define em qual dia o seu ciclo financeiro mensal reinicia. Ex: Se voc├¬ recebe sal├írio no dia 5, configure como dia 5. O app calcular├í seu saldo do dia 5 ao dia 4 do m├¬s seguinte." />
              </div>
              <Select value={monthStartDay} onValueChange={setMonthStartDay}>
                <SelectTrigger>
