import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Download, Trash2, FileText, ShieldCheck, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Link } from "react-router-dom";

export function PrivacySettings() {
  const { user, signOut } = useAuth();
  const [isExporting, setIsExporting] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);

  const handleExport = async () => {
    if (!user) return;
    setIsExporting(true);
    toast.info("Preparando seus dadosÔÇª");

    try {
      const tables = [
        "accounts",
        "categories",
        "transactions",
        "transaction_splits",
        "trips",
        "trip_members",
        "trip_itinerary",
        "trip_checklist",
        "trip_exchange_purchases",
        "budgets",
        "goals",
        "assets",
        "asset_transactions",
      ];

      // [B-25] Evitar SELECT * massivo ÔÇö limita a 500 linhas por tabela
      const results = await Promise.all(tables.map((t) => supabase.from(t).select("*").limit(500)));

      const data: Record<string, any[]> = {};
      tables.forEach((t, i) => {
        data[t] = results[i].data || [];
      });

      const payload = { exportedAt: new Date().toISOString(), userId: user.id, data };

      // [SEC] Validate payload size before creating blob (prevent memory DoS)
      const jsonStr = JSON.stringify(payload);
      if (jsonStr.length > 50 * 1024 * 1024) {
        // 50 MB max
        toast.error("Dados muito grandes para exporta├º├úo. Tente exportar por per├¡odo.");
        setIsExporting(false);
        return;
      }

      const blob = new Blob([jsonStr], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `pedemeia-dados-${new Date().toISOString().split("T")[0]}.json`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success("Dados exportados com sucesso.");
    } catch {
      toast.error("Falha ao exportar dados. Tente novamente.");
    } finally {
      setIsExporting(false);
    }
  };

  const handleDelete = async () => {
    if (!user) return;
    setIsDeleting(true);
    try {
      const { error } = await supabase.rpc("delete_user_account" as any);
      if (error) throw error;
      toast.success("Conta exclu├¡da. At├® logo!");
      await signOut();
    } catch {
      toast.error("Falha ao excluir conta. Contate o suporte.");
      setIsDeleting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="font-display font-black text-2xl tracking-tight">Privacidade & LGPD</h2>
        <p className="text-sm text-muted-foreground">
          Seus direitos sobre seus dados pessoais conforme a Lei 13.709/2018
        </p>
      </div>

      <Card className="p-5 border border-primary/20 bg-primary/5 rounded-2xl flex gap-4">
        <ShieldCheck className="h-5 w-5 text-primary shrink-0 mt-0.5" />
        <div className="space-y-1">
          <p className="text-sm font-semibold">Seus dados pertencem a voc├¬</p>
          <p className="text-sm text-muted-foreground">
            O P├® de Meia armazena seus dados financeiros exclusivamente para funcionar. Nunca
            vendemos ou compartilhamos dados com terceiros para fins publicit├írios.
          </p>
          <Link
            to="/privacidade"
            className="inline-flex items-center gap-1 text-sm text-primary hover:underline mt-1"
          >
            <FileText className="h-3.5 w-3.5" />
            Ler Pol├¡tica de Privacidade completa
            <ExternalLink className="h-3 w-3" />
          </Link>
        </div>
      </Card>

      <div className="grid gap-4 sm:grid-cols-2">
        <Card className="p-5 rounded-2xl border border-border bg-card/50 flex flex-col gap-4">
          <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
            <Download className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h3 className="font-semibold">Exportar meus dados</h3>
            <p className="text-sm text-muted-foreground mt-1">
              Baixe uma c├│pia completa de todas as suas transa├º├Áes, contas, metas e viagens em
              formato JSON.
            </p>
          </div>
          <Button className="w-full rounded-xl h-10" onClick={handleExport} disabled={isExporting}>
            {isExporting ? "ExportandoÔÇª" : "Baixar meus dados"}
          </Button>
        </Card>

        <Card className="p-5 rounded-2xl border border-destructive/20 bg-destructive/5 flex flex-col gap-4">
          <div className="h-10 w-10 rounded-xl bg-destructive/10 flex items-center justify-center">
            <Trash2 className="h-5 w-5 text-destructive" />
          </div>
          <div>
            <h3 className="font-semibold text-destructive">Excluir minha conta</h3>
            <p className="text-sm text-muted-foreground mt-1">
              Remove permanentemente sua conta e todos os dados associados. Esta a├º├úo ├®
              irrevers├¡vel.
            </p>
          </div>
          <Button
            variant="destructive"
            className="w-full rounded-xl h-10"
            onClick={() => setShowDeleteConfirm(true)}
          >
            Excluir conta permanentemente
          </Button>
        </Card>
      </div>

      <AlertDialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir conta permanentemente?</AlertDialogTitle>
            <AlertDialogDescription>
              Todos os seus dados financeiros, transa├º├Áes, contas e configura├º├Áes ser├úo removidos do
              nosso sistema. Esta a├º├úo n├úo pode ser desfeita.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={isDeleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isDeleting ? "ExcluindoÔÇª" : "Sim, excluir tudo"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Loader2, Lock, ShieldCheck, Smartphone } from "lucide-react";
import { UserProfile } from "@/hooks/useUserProfile";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { InfoTooltip } from "@/components/ui/info-tooltip";
import { supabase } from "@/integrations/supabase/client";

interface SecuritySettingsProps {
  profile: UserProfile | null;
  isLoading: boolean;
  updateProfile: any;
  onChangePassword: () => void;
}

export function SecuritySettings({ profile, isLoading, updateProfile, onChangePassword }: SecuritySettingsProps) {
  const [requirePin, setRequirePin] = useState(false);
  const [pin, setPin] = useState("");
  const [confirmPin, setConfirmPin] = useState("");
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (profile) {
      setRequirePin(profile.require_pin_on_open || false);
      if ((profile as any).app_pin_hash) {
        setPin("****"); // Visual placeholder ÔÇö PIN j├í configurado
        setConfirmPin("****");
      }
    }
  }, [profile]);

  const handleSavePin = async () => {
    if (requirePin && pin !== confirmPin) {
      toast.error("Os PINs n├úo coincidem.");
      return;
    }
    if (requirePin && pin.length < 4) {
      toast.error("O PIN deve ter 4 d├¡gitos.");
      return;
    }

    try {
      if (!requirePin) {
        // Disabling PIN: clear hash via RPC + update flag
        const { error } = await supabase.rpc('clear_pin');
        if (error) throw error;
      } else if (pin !== "****" && pin.length >= 4) {
        // New PIN: hash via RPC (never send to profiles directly)
        const { error } = await supabase.rpc('set_pin', {
          p_pin: pin,
          p_require_on_open: requirePin,
        });
        if (error) throw error;
      } else {
        // Only toggling require_pin_on_open without changing PIN
        await updateProfile.mutateAsync({ require_pin_on_open: requirePin });
      }

      toast.success("Configura├º├úo de seguran├ºa salva!");
      setIsEditing(false);
    } catch (err: any) {
      toast.error(err?.message || "Erro ao salvar PIN.");
    }
  };

  if (isLoading) {
    return <div className="flex justify-center p-8"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  }

  const hasPinSet = !!(profile as any)?.app_pin_hash;

  return (
    <div className="space-y-8 animate-fade-in">
      <div>
        <h2 className="font-display font-semibold text-lg">Seguran├ºa de Acesso</h2>
        <p className="text-sm text-muted-foreground">Proteja seus dados financeiros com um bloqueio por PIN.</p>
      </div>

      <div className="space-y-6 max-w-2xl">

        <div className="p-4 rounded-xl border border-border hover:border-foreground/20 transition-all">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 rounded-xl bg-muted flex items-center justify-center">
                <Lock className="h-5 w-5" />
              </div>
              <div>
                <p className="font-medium">Alterar Senha</p>
                <p className="text-sm text-muted-foreground">Atualize sua senha de acesso ao app</p>
              </div>
            </div>
            <Button variant="outline" onClick={onChangePassword}>Alterar</Button>
          </div>
        </div>

        <div className="p-4 bg-muted/30 border border-border rounded-xl flex items-start gap-4">
          <div className="p-3 bg-primary/10 text-primary rounded-xl shrink-0 mt-1">
            <ShieldCheck className="h-6 w-6" />
          </div>
          <div>
            <h3 className="font-medium text-foreground">Bloqueio do Aplicativo</h3>
            <p className="text-sm text-muted-foreground mt-1">
              Ao ativar, o sistema pedir├í um PIN num├®rico de 4 d├¡gitos sempre que o aplicativo for aberto. Isso protege seus dados caso algu├®m pegue seu dispositivo destravado.
            </p>
            
            <div className="mt-6 flex items-center justify-between p-4 bg-background border border-border rounded-lg">
              <div className="flex items-center gap-3">
                <Smartphone className="h-5 w-5 text-muted-foreground" />
                <Label htmlFor="require-pin" className="cursor-pointer">Exigir PIN ao abrir o app</Label>
                <InfoTooltip content="Quando ativado, caso o aplicativo seja fechado ou recarregado, ser├í necess├írio digitar o PIN para visualizar suas finan├ºas." />
              </div>
              <Switch 
                id="require-pin" 
                checked={requirePin} 
                onCheckedChange={(checked) => {
                  setRequirePin(checked);
                  setIsEditing(true);
                  if (checked && !hasPinSet) {
                    setPin("");
                    setConfirmPin("");
                  }
                }} 
              />
            </div>

            {requirePin && (hasPinSet || isEditing) && (
              <div className="mt-4 p-4 border border-border rounded-lg bg-background space-y-4">
                <div className="flex items-center gap-2 mb-2 text-sm font-medium">
                  <Lock className="h-4 w-4" />
                  {hasPinSet && !isEditing ? "PIN Configurado" : "Configure seu PIN de 4 d├¡gitos"}
                </div>
                
                {hasPinSet && !isEditing ? (
                  <Button variant="outline" size="sm" onClick={() => { setIsEditing(true); setPin(""); setConfirmPin(""); }}>
                    Alterar PIN
                  </Button>
                ) : (
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label>PIN Num├®rico</Label>
                      <Input 
                        type="password" 
                        maxLength={4} 
                        inputMode="numeric"
                        pattern="[0-9]*"
                        value={pin}
                        onChange={(e) => setPin(e.target.value.replace(/[^0-9]/g, ''))}
                        placeholder="0000"
                        className="text-center tracking-widest text-lg"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Confirmar PIN</Label>
                      <Input 
                        type="password" 
                        maxLength={4} 
                        inputMode="numeric"
                        pattern="[0-9]*"
                        value={confirmPin}
                        onChange={(e) => setConfirmPin(e.target.value.replace(/[^0-9]/g, ''))}
                        placeholder="0000"
                        className="text-center tracking-widest text-lg"
                      />
                    </div>
                  </div>
                )}
              </div>
            )}

            {isEditing && (
              <div className="mt-6 flex justify-end">
                <Button 
                  onClick={handleSavePin} 
                  disabled={updateProfile.isPending || (requirePin && (pin.length !== 4 || pin !== confirmPin))}
                >
                  {updateProfile.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                  Salvar Configura├º├úo de Seguran├ºa
                </Button>
              </div>
            )}

          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
