interface SettlementConfirmationDialogProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  items: InvoiceItem[];
  onConfirm: (
    items: InvoiceItem[],
    accountId: string,
    date: string,
    exchangeRate?: number
  ) => Promise<void>;
  isSettling: boolean;
}

export function SettlementConfirmationDialog({
  isOpen,
  onOpenChange,
  items: initialItems,
  onConfirm,
  isSettling,
}: SettlementConfirmationDialogProps) {
  const { data: accounts = [] } = useAccounts();
  const [selectedAccountId, setSelectedAccountId] = useState("");
  const [date, setDate] = useState(dateFns.format(new Date(), "yyyy-MM-dd"));
  const [currentItems, setCurrentItems] = useState<InvoiceItem[]>([]);
  const [exchangeRate, setExchangeRate] = useState("5.15");

  useEffect(() => {
    if (isOpen) {
      setCurrentItems(initialItems);
    }
  }, [isOpen, initialItems]);

  const netBalance = currentItems.reduce((sum, item) => {
    if (item.type === "CREDIT") return SafeFinancialCalculator.subtract(sum, item.amount);
    return SafeFinancialCalculator.add(sum, item.amount);
  }, 0);

  const total = Math.abs(netBalance);
  const currency = currentItems[0]?.currency || "BRL";

  // NOVO: Detectar se a a├º├úo ├® de pagamento (D├®bito) ou recebimento (Cr├®dito) com base no saldo l├¡quido
  const isPayment = netBalance >= 0;

  // Mostrar todas as contas de movimenta├º├úo l├¡quida (n├úo cart├Áes)
  // E apenas contas que sejam da mesma moeda da transa├º├úo
  const filteredAccounts = accounts.filter(
    (a) => a.type !== "CREDIT_CARD" && a.currency === currency
  );

  const selectedAccount = accounts.find((a) => a.id === selectedAccountId);
  const accountCurrency = selectedAccount?.currency || "BRL";
  const isMultiCurrency = accountCurrency.toUpperCase() !== currency.toUpperCase();

  useEffect(() => {
    if (isOpen && filteredAccounts.length > 0) {
      const isAlreadyValid = filteredAccounts.some((a) => a.id === selectedAccountId);
      if (!isAlreadyValid) {
        const defaultAcc =
          filteredAccounts.find((a) => a.type === "CHECKING") || filteredAccounts[0];
        setSelectedAccountId(defaultAcc.id);
      }
    }
  }, [isOpen, filteredAccounts, selectedAccountId]);

  useEffect(() => {
    if (isOpen && filteredAccounts.length > 0) {
      const isAlreadyValid = filteredAccounts.some((a) => a.id === selectedAccountId);
      if (!isAlreadyValid) {
        const defaultAcc =
          filteredAccounts.find((a) => a.type === "CHECKING") || filteredAccounts[0];
        setSelectedAccountId(defaultAcc.id);
      }
    } else if (isOpen && filteredAccounts.length === 0) {
      // For├ºar reset se n├úo houver conta v├ílida na mesma moeda
      setSelectedAccountId("");
    }
  }, [isOpen, filteredAccounts, selectedAccountId]);

  const handleConfirm = async () => {
    if (filteredAccounts.length === 0) {
      toast.error(
        `Voc├¬ n├úo possui conta cadastrada na moeda da despesa (${currency}). Por favor, cadastre uma conta nessa moeda primeiro.`
      );
      return;
    }

    if (!selectedAccountId || currentItems.length === 0) return;

    // Dupla valida├º├úo de seguran├ºa para impedir pagamentos em moedas diferentes
    const selectedAccount = accounts.find((a) => a.id === selectedAccountId);
    if (!selectedAccount || selectedAccount.currency.toUpperCase() !== currency.toUpperCase()) {
      toast.error(
        `A conta selecionada (${selectedAccount?.currency}) n├úo ├® compat├¡vel com a moeda do acerto (${currency}).`
      );
      return;
    }

    // Se for um pagamento (sa├¡da de dinheiro), validar se o saldo ├® suficiente
    if (isPayment) {
      if (selectedAccount.type !== "CREDIT_CARD") {
        if (selectedAccount.balance < total) {
          toast.error(
            `Saldo insuficiente na conta "${selectedAccount.name}". Saldo atual: ${new Intl.NumberFormat("pt-BR", { style: "currency", currency: selectedAccount.currency }).format(selectedAccount.balance)}. Valor necess├írio: ${new Intl.NumberFormat("pt-BR", { style: "currency", currency: selectedAccount.currency }).format(total)}`
          );
          return;
        }
      }
    }

    await onConfirm(currentItems, selectedAccountId, date, undefined);
    onOpenChange(false);
  };

  const removeItem = (id: string) => {
    setCurrentItems((prev) => prev.filter((item) => item.id !== id));
  };

  const formatCurrencyValue = (value: number) => {
    return new Intl.NumberFormat("pt-BR", { style: "currency", currency }).format(value);
  };

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
