import { useMemo } from "react";
import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { TrendingUp, TrendingDown } from "lucide-react";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { logger } from "@/utils/logger";

interface ChartDataPoint {
  month: string;
  credits: number;
  debits: number;
  net: number;
}

interface SharedBalanceChartProps {
  transactions: any[];
  invoices?: Record<string, InvoiceItem[]>;
  currentDate: Date;
  isGeneralReport?: boolean;
  monthlyData?: any[];
  currency?: string;
}

export function SharedBalanceChart({
  transactions,
  invoices = {},
  currentDate,
  isGeneralReport = false,
  monthlyData = [],
  currency = "BRL",
}: SharedBalanceChartProps) {
  const chartData = useMemo(() => {
    if (isGeneralReport && monthlyData && monthlyData.length > 0) {
      logger.debug("[SharedBalanceChart] Usando monthlyData para relat├│rio geral");
      return monthlyData.map((item) => ({
        month: item.month,
        credits: item.income,
        debits: item.expense,
        net: SafeFinancialCalculator.subtract(item.income, item.expense),
      }));
    }

    const data: ChartDataPoint[] = [];
    // Usar currentDate como ├óncora para os ├║ltimos 6 meses
    const anchor = dateFns.startOfMonth(currentDate);

    for (let i = 5; i >= 0; i--) {
      const monthDate = dateFns.subMonths(anchor, i);
      const monthLabel = dateFns.format(monthDate, "MMM", { locale: ptBR });

      let credits = 0;
      let debits = 0;

      // Todos os itens de todos os membros, pagos ou n├úo
      Object.values(invoices).forEach((items) => {
        items.forEach((item: InvoiceItem) => {
          if (!item.date) return;

          // Parse date as YYYY-MM-DD to avoid timezone issues
          const datePart = item.date.split("T")[0];
          const [year, month] = datePart.split("-").map(Number);

          if (isNaN(year) || isNaN(month)) return;

          const itemMonth = month - 1; // JavaScript months are 0-indexed
          const itemYear = year;

          if (itemMonth === monthDate.getMonth() && itemYear === monthDate.getFullYear()) {
            // Incluir todos os itens, n├úo apenas isPaid === false
            if (item.type === "CREDIT") {
              credits = SafeFinancialCalculator.add(credits, item.amount);
            } else if (item.type === "DEBIT") {
              debits = SafeFinancialCalculator.add(debits, item.amount);
            }
          }
        });
      });

      data.push({
        month: monthLabel,
        credits,
        debits,
        net: SafeFinancialCalculator.subtract(credits, debits),
      });
    }

    return data;
  }, [invoices, isGeneralReport, monthlyData, currentDate]);

  const safeChartData = chartData || [];
  const currentMonthData =
    safeChartData.length > 0 ? safeChartData[safeChartData.length - 1] : null;
  const previousMonthData =
    safeChartData.length > 1 ? safeChartData[safeChartData.length - 2] : null;
  const trend = currentMonthData
    ? SafeFinancialCalculator.subtract(currentMonthData.net, previousMonthData?.net || 0)
    : 0;

  const formatCurrency = (value: number) => {
    if (currency && currency !== "BRL") {
      return new Intl.NumberFormat("en-US", {
        style: "currency",
        currency: currency,
        notation: "compact",
      }).format(value);
    }
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
      notation: "compact",
    }).format(value);
  };

  const CustomTooltip = ({ active, payload, label }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <div className="bg-popover border border-border rounded-lg p-3 shadow-lg">
          <p className="font-medium capitalize mb-2">{label}</p>
          <div className="space-y-2 text-sm">
            {isGeneralReport ? (
              <>
                <p className="text-positive">Receitas: {formatCurrency(data.credits)}</p>
                <p className="text-negative">Despesas: {formatCurrency(data.debits)}</p>
              </>
            ) : (
              <>
                <p className="text-positive">A receber: {formatCurrency(data.credits)}</p>
                <p className="text-negative">A pagar: {formatCurrency(data.debits)}</p>
              </>
            )}
            <p
              className={data.net >= 0 ? "text-positive font-medium" : "text-negative font-medium"}
            >
              Saldo: {formatCurrency(data.net)}
            </p>
          </div>
        </div>
      );
    }
    return null;
  };

  return (
    <Card>
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base font-medium flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
            Evolu├º├úo do Saldo
          </CardTitle>
          {trend !== 0 && (
            <div
              className={`flex items-center gap-1 text-sm ${trend > 0 ? "text-positive" : "text-negative"}`}
            >
              {trend > 0 ? (
                <TrendingUp className="h-4 w-4" />
              ) : (
                <TrendingDown className="h-4 w-4" />
              )}
              <span>{formatCurrency(Math.abs(trend))}</span>
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="h-[200px] w-full" role="img" aria-label="Gr├ífico de evolu├º├úo do balan├ºo compartilhado nos ├║ltimos meses">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={safeChartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
              <defs>
                <linearGradient id="colorNet" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="hsl(var(--primary))" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="hsl(var(--primary))" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" className="stroke-muted" />
              <XAxis
                dataKey="month"
                tick={{ fontSize: 12 }}
                tickLine={false}
                axisLine={false}
                className="fill-muted-foreground"
              />
              <YAxis
                tickFormatter={(v) => formatCurrency(v)}
                tick={{ fontSize: 10 }}
                tickLine={false}
                axisLine={false}
                className="fill-muted-foreground"
              />
              <Tooltip content={<CustomTooltip />} />
              <Area
                type="monotone"
                dataKey="net"
                stroke="hsl(var(--primary))"
                strokeWidth={2}
                fill="url(#colorNet)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { FormField } from '@/components/ui/form-field';
import { CurrencyInput } from '@/components/ui/currency-input';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  DollarSign,
  Layers,
  Check,
  AlertCircle,
  Loader2,
  Users,
  HelpCircle,
  Info,
  Calendar,
} from 'lucide-react';
import { FormSection } from '@/components/ui/form-section';
import { cn } from '@/lib/utils';
import { FamilyMember } from '@/hooks/useFamily';
import { useCreateTransaction } from '@/hooks/useTransactions';
import { useCategoriesHierarchical } from '@/hooks/useCategories';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';
import * as dateFns from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { CategorySelector } from '@/components/transactions/CategorySelector';
import { Popover, PopoverTrigger, PopoverContent } from '@/components/ui/popover';
import { moneyUtils } from "@/utils/money";

interface SharedInstallmentImportProps {
  isOpen: boolean;
  onClose: () => void;
  members: FamilyMember[];
  onSuccess?: () => void;
}

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
};

export function SharedInstallmentImport({
  isOpen,
  onClose,
  members,
  onSuccess,
}: SharedInstallmentImportProps) {
  const { user } = useAuth();
  const createTransaction = useCreateTransaction();
  const { data: categories = [] } = useCategoriesHierarchical();

  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [installments, setInstallments] = useState('2');
  const [selectedMonth, setSelectedMonth] = useState(dateFns.format(new Date(), 'yyyy-MM'));
  const [categoryId, setCategoryId] = useState('');
  const [assigneeId, setAssigneeId] = useState('');
  const [assigneePercentage, setAssigneePercentage] = useState(50);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<string[]>([]);

  // Filter out current user from assignee list
  const availableMembers = members.filter(m => m.linked_user_id !== user?.id);

  // Gerar lista de meses (12 meses: atual + 11 pr├│ximos)
  const availableMonths = Array.from({ length: 12 }, (_, i) => {
    const date = dateFns.addMonths(new Date(), i);
    return {
      value: dateFns.format(date, 'yyyy-MM'),
      label: dateFns.format(date, 'MMMM yyyy', { locale: ptBR }).replace(/^\w/, c => c.toUpperCase()),
    };
  });

  useEffect(() => {
    if (isOpen) {
      setDescription('');
      setAmount(''); // Iniciar vazio para o usu├írio digitar
      setInstallments('2');
      setSelectedMonth(dateFns.format(new Date(), 'yyyy-MM'));
      setCategoryId('');
      setAssigneePercentage(50);
      setIsSubmitting(false);
      setErrors([]);
      if (availableMembers.length > 0) {
        setAssigneeId(availableMembers[0].id);
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, availableMembers.length]);

  const parseAmount = (val: string) => {
    return moneyUtils.parse(val) || 0;
  };

  const installmentAmount = parseAmount(amount);
  const totalAmount = installmentAmount * (parseInt(installments) || 1);

  // Calcular parcelas por membro
  const assigneeParcelAmount = (installmentAmount * assigneePercentage) / 100;
  const creatorParcelAmount = installmentAmount - assigneeParcelAmount;

  const assigneeTotalAmount = totalAmount * (assigneePercentage / 100);
  const creatorTotalAmount = totalAmount - assigneeTotalAmount;

  // Calcular data da ├║ltima parcela
  let lastInstallmentText = '';
  if (selectedMonth && installments) {
    const totalInstallmentsNum = parseInt(installments) || 0;
    if (totalInstallmentsNum >= 1) {
      const [year, month] = selectedMonth.split('-').map(Number);
      const baseDate = new Date(year, month - 1, 1);
      const lastDate = dateFns.addMonths(baseDate, totalInstallmentsNum - 1);
      lastInstallmentText = dateFns.format(lastDate, 'MMMM yyyy', { locale: ptBR }).replace(/^\w/, c => c.toUpperCase());
    }
  }

  const validateForm = (): boolean => {
    const newErrors: string[] = [];

    if (!description.trim()) {
      newErrors.push('Descri├º├úo ├® obrigat├│ria');
    }

    const parsedAmount = parseAmount(amount);
    if (!parsedAmount || parsedAmount <= 0) {
      newErrors.push('Valor da parcela deve ser maior que zero');
    }

    const parsedInstallments = parseInt(installments);
    if (!parsedInstallments || parsedInstallments < 1) {
      newErrors.push('N├║mero de parcelas deve ser pelo menos 1');
    }

    if (parsedInstallments > 48) {
      newErrors.push('N├║mero m├íximo de parcelas ├® 48');
    }

    if (!assigneeId) {
      newErrors.push('Selecione quem vai pagar as parcelas');
    }

    if (!selectedMonth) {
      newErrors.push('Selecione o m├¬s da pr├│xima parcela');
    }

    setErrors(newErrors);
    return newErrors.length === 0;
  };

  const handleAmountChange = (value: string) => {
    setAmount(value);
  };

  const handleSubmit = async () => {
    if (isSubmitting) return;
    if (!validateForm()) return;

    setIsSubmitting(true);

    try {
      const selectedMember = members.find(m => m.id === assigneeId);
      if (!selectedMember) throw new Error('Membro n├úo encontrado');

      // Usar o primeiro dia do m├¬s selecionado
      const [year, month] = selectedMonth.split('-').map(Number);
      const baseDate = new Date(year, month - 1, 1);
      const totalInstallmentsNum = parseInt(installments);

      // Passar o valor TOTAL, n├úo o valor da parcela
      // O hook useCreateTransaction divide o total pelo n├║mero de parcelas
      // E passa os splits proporcionais customizados
      const mainSplitAmount = totalAmount * (assigneePercentage / 100);
      const splits = [{
        member_id: assigneeId,
        percentage: assigneePercentage,
        amount: mainSplitAmount,
      }];

      // Se a porcentagem for menor que 100%, o criador paga a outra parte.
      const creatorPercentage = 100 - assigneePercentage;
      if (creatorPercentage > 0) {
        splits.push({
          member_id: user.id,
          percentage: creatorPercentage,
          amount: totalAmount - mainSplitAmount,
        });
      }

      await createTransaction.mutateAsync({
        amount: totalAmount, 
        description: description.trim(),
        date: dateFns.format(baseDate, 'yyyy-MM-dd'),
        type: 'EXPENSE',
        category_id: categoryId || undefined,
        domain: 'SHARED',
        is_shared: true,
        is_installment: true,
        total_installments: totalInstallmentsNum,
        splits: splits,
      });

      toast.success(`${totalInstallmentsNum} parcelas importadas com sucesso!`);
      onSuccess?.();
      onClose();
    } catch (error: unknown) {
      toast.error('Erro ao importar parcelas');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md overflow-hidden flex flex-col w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] border-b-0 sm:border-b bg-background">
        <DialogHeader className="px-5 pt-5 pb-2 sm:px-6 sm:pt-6">
          <DialogTitle className="flex items-center gap-2 pr-8">
            <Layers className="h-5 w-5 text-primary shrink-0" />
            <span>Importar Parcelado Compartilhado</span>
            <Popover>
              <PopoverTrigger asChild>
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-6 w-6 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground shrink-0"
                  aria-label="O que ├® o Parcelado Compartilhado?"
                >
                  <HelpCircle className="h-3.5 w-3.5" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-80 p-4 border bg-popover text-popover-foreground rounded-xl shadow-md z-50 font-normal">
                <div className="space-y-3">
                  <div className="flex items-center gap-2 font-bold text-sm text-primary">
                    <Info className="h-4 w-4 shrink-0" />
                    <span>O que ├® o Parcelado Compartilhado?</span>
                  </div>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    Esta funcionalidade serve para <strong>importar parcelas que j├í est├úo em andamento</strong> no compartilhado, dividindo e cobrando outro membro automaticamente pelos meses restantes.
                  </p>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    <strong>Exemplo Pr├ítico:</strong> Se voc├¬ comprou uma geladeira em 10x, j├í pagou 2 e faltam 8 parcelas, informe "8" em Parcelas Restantes e o m├¬s da pr├│xima cobran├ºa. A ferramenta projetar├í essas parcelas futuras e cobrar├í o membro selecionado m├¬s a m├¬s.
                  </p>
                  <div className="pt-1.5 text-sm font-semibold text-primary border-t border-border mt-1">
                    ­ƒÆí Dica: Informe o valor unit├írio de <strong>cada parcela</strong>. O total da compra ser├í calculado de forma precisa e automatizada.
                  </div>
                </div>
              </PopoverContent>
            </Popover>
          </DialogTitle>
          <DialogDescription>
            Importe as parcelas restantes para outro membro pagar.
            <br />
            <span className="text-sm text-muted-foreground">
              ­ƒÆ░ Informe o valor de cada parcela - o total ser├í calculado automaticamente
            </span>
          </DialogDescription>
        </DialogHeader>

        <div className="flex-1 overflow-y-auto flex flex-col gap-3 px-5 py-4 sm:px-6 no-scrollbar">
          {/* Erros de valida├º├úo */}
          {errors.length > 0 && (
            <div className="px-1 py-2 bg-destructive/10 text-destructive rounded-lg space-y-1.5">
              {errors.map((error, idx) => (
                <p key={idx} className="text-xs flex items-center gap-2 font-medium px-2">
                  <AlertCircle className="h-3.5 w-3.5 shrink-0" />
                  {error}
                </p>
              ))}
            </div>
          )}

          {/* Se├º├úo: Detalhes do parcelado */}
          <FormSection icon={<DollarSign />} title="Valor e parcelas">
            <FormField label="Descri├º├úo" htmlFor="si-description" required>
              <Input
                id="si-description"
                name="si-description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="Ex: Compra GeladeiraÔÇª"
                disabled={isSubmitting}
                autoComplete="off"
              />
            </FormField>

            <div className="grid grid-cols-2 gap-3">
              <FormField label="Valor da Parcela" htmlFor="si-amount" required>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground z-10 pointer-events-none" />
                  <CurrencyInput
                    id="si-amount"
                    value={amount}
                    onChange={handleAmountChange}
                    placeholder="0,00"
                    className="pl-9 font-mono"
                    disabled={isSubmitting}
                  />
                </div>
              </FormField>
              <FormField label="Parcelas Restantes" htmlFor="si-installments" required>
                <Input type="number" inputMode="decimal"
                  id="si-installments"
                  name="si-installments"
                  value={installments}
                  onChange={(e) => setInstallments(e.target.value)}
                  min="1"
                  max="48"
                  disabled={isSubmitting}
                  autoComplete="off"
                />
              </FormField>
            </div>

            {totalAmount > 0 && (
              <div className="bg-background border border-border/60 rounded-lg px-3 py-2 flex justify-between items-center">
                <span className="text-xs text-muted-foreground">Total da compra</span>
                <span className="font-mono text-sm font-bold">{formatCurrency(totalAmount)}</span>
              </div>
            )}
          </FormSection>

          {/* Se├º├úo: Datas e categoria */}
          <FormSection icon={<Calendar />} title="Agendamento e categoria">
            <FormField label="M├¬s da Primeira Parcela" htmlFor="si-month" required>
              <Select value={selectedMonth} onValueChange={setSelectedMonth} disabled={isSubmitting}>
                <SelectTrigger id="si-month">
                  <SelectValue placeholder="Selecione o m├¬sÔÇª" />
                </SelectTrigger>
                <SelectContent>
                  {availableMonths.map((month) => (
                    <SelectItem key={month.value} value={month.value}>
                      {month.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {lastInstallmentText && (
                <div className="bg-primary/5 border border-primary/20 rounded-lg px-3 py-2 flex items-center gap-2">
                  <AlertCircle className="h-3.5 w-3.5 text-primary shrink-0" />
                  <span className="text-xs text-foreground">
                    ├Ültima parcela em <strong className="text-primary">{lastInstallmentText}</strong>
                  </span>
                </div>
              )}
            </FormField>

            <FormField label="Categoria (opcional)" htmlFor="si-category">
              <CategorySelector
                categories={categories}
                value={categoryId}
                onValueChange={setCategoryId}
                type="expense"
                placeholder="Selecione uma categoriaÔÇª"
              />
            </FormField>
          </FormSection>

          {/* Se├º├úo: Respons├ível */}
          <FormSection icon={<Users />} title="Quem paga">
            <FormField label="Membro respons├ível" htmlFor="si-assignee-section" required>
            {availableMembers.length === 0 ? (
              <div className="text-center py-4 border border-dashed rounded-lg">
                <Users className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
                <p className="text-sm text-muted-foreground">Nenhum membro dispon├¡vel</p>
              </div>
            ) : (
              <>
                <div className="grid grid-cols-2 gap-2">
                  {availableMembers.map((member) => (
                    <button
                      key={member.id}
                      type="button"
                      disabled={isSubmitting}
                      onClick={() => setAssigneeId(member.id)}
                      className={cn(
                        'p-3 rounded-lg border text-sm font-medium transition-all',
                        assigneeId === member.id
                          ? 'bg-primary text-primary-foreground border-primary'
                          : 'bg-background border-border hover:border-primary'
                      )}
                    >
                      <div className="flex items-center justify-center gap-2">
                        {assigneeId === member.id && <Check className="h-4 w-4" />}
                        {member.name.split(' ')[0]}
                      </div>
                    </button>
                  ))}
                </div>

                {assigneeId && (
                  <div className="p-3 bg-muted/30 border border-border rounded-xl space-y-3 animate-fade-in mt-2">
                    <div className="flex justify-between items-center">
                      <p className="text-sm font-semibold text-muted-foreground">Porcentagem do membro selecionado</p>
                      <span className="font-mono text-sm font-bold text-primary">{assigneePercentage}%</span>
                    </div>

                    {/* Controle deslizante com atalhos r├ípidos */}
                    <div className="space-y-2">
                      <div className="flex items-center gap-3">
                        <input
                          type="range"
                          min="1"
                          max="100"
                          value={assigneePercentage}
                          onChange={(e) => setAssigneePercentage(parseInt(e.target.value))}
                          disabled={isSubmitting}
                          className="flex-1 accent-primary h-2 bg-muted rounded-lg cursor-pointer"
                        />
                        <input
                          type="number"
                          min="1"
                          max="100"
                          value={assigneePercentage}
                          onChange={(e) => {
                            const val = Math.max(1, Math.min(100, parseInt(e.target.value) || 0));
                            setAssigneePercentage(val);
                          }}
                          disabled={isSubmitting}
                          className="w-14 h-8 text-center rounded border border-border bg-background text-sm font-mono"
                        />
                      </div>

                      {/* Atalhos R├ípidos */}
                      <div className="flex justify-between gap-2">
                        {[50, 70, 100].map((pct) => (
                          <button
                            key={pct}
                            type="button"
                            disabled={isSubmitting}
                            onClick={() => setAssigneePercentage(pct)}
                            className={cn(
                              "flex-1 py-1 px-2 text-xs rounded font-semibold border transition-all",
                              assigneePercentage === pct
                                ? "bg-primary/10 text-primary border-primary/30"
                                : "bg-background border-border hover:bg-muted text-muted-foreground"
                            )}
                          >
                            {pct === 50 ? "Divis├úo Igual (50%)" : pct === 100 ? "Valor Integral (100%)" : `${pct}%`}
                          </button>
                        ))}
                      </div>
                    </div>

                    {/* Simulador de Gastos em Tempo Real */}
                    {installmentAmount > 0 && (
                      <div className="pt-2.5 border-t border-border space-y-2.5 text-sm">
                        <p className="font-bold text-sm uppercase tracking-wider text-muted-foreground flex items-center gap-1">­ƒôè Resumo da divis├úo das parcelas</p>
                        
                        <div className="flex justify-between items-center text-muted-foreground">
                          <span>Sua parte ({100 - assigneePercentage}%):</span>
                          <span className="font-mono text-foreground font-medium">
                            {formatCurrency(creatorParcelAmount)} <span className="text-sm text-muted-foreground">/ m├¬s</span>
                            {parseInt(installments) > 1 && (
                              <span className="text-sm ml-1 block text-right text-muted-foreground">(Total: {formatCurrency(creatorTotalAmount)})</span>
                            )}
                          </span>
                        </div>

                        <div className="flex justify-between items-center text-foreground font-medium">
                          <span>Parte de {members.find(m => m.id === assigneeId)?.name.split(' ')[0]} ({assigneePercentage}%):</span>
                          <span className="font-mono text-primary font-bold">
                            {formatCurrency(assigneeParcelAmount)} <span className="text-sm text-primary/70">/ m├¬s</span>
                            {parseInt(installments) > 1 && (
                              <span className="text-sm ml-1 block text-right text-primary/70 font-normal">(Total: {formatCurrency(assigneeTotalAmount)})</span>
                            )}
                          </span>
                        </div>
                      </div>
                    )}
                  </div>
                )}
              </>
            )}
          </FormField>
          </FormSection>
        </div>

        <DialogFooter className="px-5 pb-5 pt-2 sm:px-6 sm:pb-6">
          <Button variant="outline" onClick={onClose} disabled={isSubmitting}>
            Cancelar
          </Button>
          <Button onClick={handleSubmit} disabled={isSubmitting || availableMembers.length === 0}>
            {isSubmitting ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Importando...
              </>
            ) : (
              installmentAmount > 0
                ? `Confirmar ${installments}x de ${formatCurrency(installmentAmount)}`
                : 'Confirmar'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { SharedExpenseCard } from "@/components/shared/SharedExpenseCard";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";
import { Database } from "@/types/database";

type FamilyMember = Database["public"]["Tables"]["family_members"]["Row"] & {
  linked_user_id?: string | null;
  sharing_scope?: string | null;
  scope_start_date?: string | null;
  scope_end_date?: string | null;
  scope_trip_id?: string | null;
};

interface SharedRegularListProps {
  members: FamilyMember[];
  user: any;
  activeTab: "REGULAR" | "HISTORY";
  getFilteredInvoice: (memberId: string) => InvoiceItem[];
  getTotals: (items: InvoiceItem[]) => Record<string, any>;
  formatCurrency: (val: number, cur?: string) => string;
  onSettle: (id: string, type: "PAY" | "RECEIVE", amt: number, specificItem?: InvoiceItem) => void;
  onUndo: (item: InvoiceItem) => void;
  onDelete: (item: InvoiceItem) => void;
  onConfirmReceipt: (item: InvoiceItem) => void;
  onRejectSettlement: (item: InvoiceItem) => void;
  onAnticipate: (item: InvoiceItem) => void;
}

export function SharedRegularList({
  members,
  user,
  activeTab,
  getFilteredInvoice,
  getTotals,
  formatCurrency,
  onSettle,
  onUndo,
  onDelete,
  onConfirmReceipt,
  onRejectSettlement,
  onAnticipate,
}: SharedRegularListProps) {
  const filteredMembers = members.filter((m) => m.linked_user_id !== user?.id);

  return (
    <>
      {filteredMembers.map((m) => {
        const items = getFilteredInvoice(m.id);
        if (items.length === 0) return null;

        return (
          <SharedExpenseCard
            key={m.id}
            member={m}
            items={items}
            netAmount={getTotals(items)["BRL"]?.net || 0}
            currency="BRL"
            isHistory={activeTab === "HISTORY"}
            currentUserId={user?.id}
            formatCurrency={formatCurrency}
            onSettle={onSettle}
            onUndo={onUndo}
            onDelete={onDelete}
            onConfirmReceipt={onConfirmReceipt}
            onRejectSettlement={onRejectSettlement}
            onAnticipate={onAnticipate}
          />
        );
      })}
    </>
  );
}

import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { UserAvatar } from "@/components/ui/user-avatar";
import { Wallet, Globe, ArrowRight, Loader2, Info } from "lucide-react";
import { cn } from "@/lib/utils";
import * as dateFns from "date-fns";
import { getCurrencySymbol } from "@/services/exchangeCalculations";

interface SharedSettleDialogProps {
  isOpen: boolean;
  onOpenChange: (open: boolean) => void;
  selectedMember: string | null;
  members: any[];
  pendingMemberItems: any[];
  selectedItems: string[];
  onToggleItem: (id: string) => void;
  onSelectAll: () => void;
  settleType: "PAY" | "RECEIVE";
  settleAmount: string;
  settleDate: string;
  setSettleDate: (date: string) => void;
  settleAccountId: string;
  setSettleAccountId: (id: string) => void;
  accounts: any[];
  trips: any[];
  profile: any;
  user: any;
  onSettle: () => void;
  isSettling: boolean;
  settlingMode: "ALL" | "SINGLE";
}

export function SharedSettleDialog({
  isOpen,
  onOpenChange,
  selectedMember,
  members,
  pendingMemberItems,
  selectedItems,
  onToggleItem,
  onSelectAll,
  settleType,
  settleAmount,
  settleDate,
  setSettleDate,
  settleAccountId,
  setSettleAccountId,
  accounts,
  trips,
  profile,
  user,
  onSettle,
  isSettling,
  settlingMode,
}: SharedSettleDialogProps) {
  if (!selectedMember) return null;

  const member = members.find(m => m.id === selectedMember);
  const itemsToConsider = selectedItems.length > 0
    ? pendingMemberItems.filter(i => selectedItems.includes(i.id))
    : pendingMemberItems;

  const tripIds = [...new Set(itemsToConsider.filter(i => i.tripId).map(i => i.tripId))];
  const internationalTrip = tripIds.length > 0
    ? trips.find(t => tripIds.includes(t.id) && t.currency !== "BRL")
    : null;

  const settlementCurrency = internationalTrip?.currency || "BRL";
  const isInternationalSettlement = settlementCurrency !== "BRL";

  const filteredSettleAccounts = (accounts || []).filter(a => {
    if (a.type === "CREDIT_CARD") return false;
    if (isInternationalSettlement) {
      return a.is_international && a.currency === settlementCurrency;
    }
    return !a.is_international;
  });

  return (
    <Dialog open={isOpen} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg w-full flex flex-col gap-0 p-0 !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-3xl sm:rounded-3xl !rounded-b-none sm:!rounded-b-3xl max-h-[92dvh] border-b-0 sm:border-b overflow-hidden">
        {/* Header fixo */}
        <div className="px-6 pt-6 pb-4 shrink-0">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2 text-lg font-bold">
              <Wallet className="h-5 w-5 text-primary" />
              {settlingMode === "SINGLE"
                ? "Acertar Item Espec├¡fico"
                : (settleType === "PAY" ? "Pagar Conta" : "Receber Pagamento")}
            </DialogTitle>
            <DialogDescription className="text-sm text-muted-foreground">
              {settlingMode === "SINGLE"
                ? "Registre o acerto apenas deste item espec├¡fico"
                : (settleType === "PAY" ? "Registre o pagamento da sua d├¡vida total" : "Registre o recebimento do valor total devido")}
            </DialogDescription>
          </DialogHeader>
        </div>

        {/* Corpo rol├ível */}
        <div className="flex-1 overflow-y-auto px-6 space-y-4 pb-2">
          {isInternationalSettlement && (
            <Alert className="border-accent/20 bg-accent/5 dark:bg-accent/10">
              <Globe className="h-4 w-4 text-accent" />
              <AlertDescription className="text-sm text-accent">
                Acerto de viagem internacional em <span className="font-semibold">{settlementCurrency}</span>.
              </AlertDescription>
            </Alert>
          )}

          {(() => {
            const hasCredits = itemsToConsider.some(i => i.type === "CREDIT");
            const hasDebits = itemsToConsider.some(i => i.type === "DEBIT");
            if (hasCredits && hasDebits) {
              return (
                <Alert className="border-primary/20 bg-primary/5">
                  <Info className="h-4 w-4 text-primary shrink-0" />
                  <AlertDescription className="text-sm text-primary/80 leading-relaxed">
                    <strong>Compensa├º├úo Autom├ítica:</strong> Como voc├¬ possui valores a pagar e a receber com <strong>{member?.name}</strong>, o sistema abate os d├®bitos e cr├®ditos m├║tuos, resultando no valor l├¡quido final.
                  </AlertDescription>
                </Alert>
              );
            }
            return null;
          })()}

          {/* Card de transfer├¬ncia */}
          <div className={cn(
            "flex items-center justify-center gap-6 p-4 rounded-2xl",
            settleType === "PAY" ? "bg-destructive/5" : "bg-success/5"
          )}>
            <div className="text-center">
              <div className="mx-auto w-12 h-12">
                {settleType === "PAY" ? (
                  <UserAvatar name={profile?.full_name || user?.email || "Eu"} avatarUrl={profile?.avatar_url} colorId={profile?.avatar_color || "green"} iconId={profile?.avatar_icon || "avatar_1"} size="md" />
                ) : (
                  <UserAvatar name={member?.name || ""} avatarUrl={member?.avatar_url} colorId={member?.avatar_color} iconId={member?.avatar_icon} size="md" />
                )}
              </div>
              <p className="text-xs font-medium mt-1.5 text-muted-foreground">{settleType === "PAY" ? "Eu" : member?.name}</p>
            </div>

            <div className="flex flex-col items-center gap-1">
              <ArrowRight className={cn("h-5 w-5", settleType === "PAY" ? "text-destructive" : "text-success")} />
              <p className={cn("font-mono font-bold text-base tabular-nums", settleType === "PAY" ? "text-destructive" : "text-success")}>
                {getCurrencySymbol(settlementCurrency)} {settleAmount || "0,00"}
              </p>
            </div>

            <div className="text-center">
              <div className="mx-auto w-12 h-12">
                {settleType === "PAY" ? (
                  <UserAvatar name={member?.name || ""} avatarUrl={member?.avatar_url} colorId={member?.avatar_color} iconId={member?.avatar_icon} size="md" />
                ) : (
                  <UserAvatar name={profile?.full_name || user?.email || "Eu"} avatarUrl={profile?.avatar_url} colorId={profile?.avatar_color || "green"} iconId={profile?.avatar_icon || "avatar_1"} size="md" />
                )}
              </div>
              <p className="text-xs font-medium mt-1.5 text-muted-foreground">{settleType === "PAY" ? member?.name : "Eu"}</p>
            </div>
          </div>

          {pendingMemberItems.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center justify-between gap-2">
                <Label className="text-sm font-semibold">Itens para acertar</Label>
                {settlingMode !== "SINGLE" && (
                  <Button variant="ghost" size="sm" onClick={onSelectAll} className="text-xs h-7 px-2 text-primary shrink-0">
                    {selectedItems.length === pendingMemberItems.length ? "Desmarcar todos" : "Selecionar todos"}
                  </Button>
                )}
              </div>
              <div className="border border-border/60 rounded-2xl divide-y divide-border/40 overflow-hidden">
                {pendingMemberItems.filter(i => settlingMode === "SINGLE" ? selectedItems.includes(i.id) : true).map(item => {
                  const itemTrip = item.tripId ? trips.find(t => t.id === item.tripId) : null;
                  const itemCurrency = itemTrip?.currency || "BRL";
                  const isCredit = item.type === "CREDIT";
                  return (
                    <label key={item.id} className="flex items-center gap-3 px-4 py-3 hover:bg-muted/40 cursor-pointer transition-colors">
                      <Checkbox
                        checked={selectedItems.includes(item.id)}
                        onCheckedChange={() => onToggleItem(item.id)}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate">{item.description}</p>
                        <p className="text-xs text-muted-foreground mt-0.5">{(() => { if (!item.date) return '-'; const dt = new Date(item.date + 'T12:00:00'); return dateFns.isValid(dt) ? dateFns.format(dt, "dd/MM/yyyy") : '-'; })()}</p>
                      </div>
                      <span className={cn("font-mono text-sm font-semibold tabular-nums shrink-0", isCredit ? "text-success" : "text-foreground")}>
                        {getCurrencySymbol(itemCurrency)} {item.amount.toLocaleString("pt-BR", { minimumFractionDigits: 2 })}
                      </span>
                    </label>
                  );
                })}
              </div>
            </div>
          )}

          <div className="grid gap-3">
            <div className="space-y-1.5">
              <Label className="text-sm font-semibold">Data do {settleType === "PAY" ? "Pagamento" : "Recebimento"}</Label>
              <Input type="date" value={settleDate} onChange={(e) => setSettleDate(e.target.value)} className="rounded-xl" max={new Date().toISOString().split("T")[0]} />
            </div>

            <div className="space-y-1.5">
              <Label className="text-sm font-semibold">Conta {isInternationalSettlement && <span className="text-muted-foreground font-normal">({settlementCurrency})</span>}</Label>
              <Select value={settleAccountId} onValueChange={setSettleAccountId}>
                <SelectTrigger className="rounded-xl">
                  <SelectValue placeholder="Selecione a conta" />
                </SelectTrigger>
                <SelectContent>
                  {filteredSettleAccounts.length === 0 ? (
                    <SelectItem value="no-accounts" disabled>Nenhuma conta dispon├¡vel</SelectItem>
                  ) : (
                    filteredSettleAccounts.map((account) => (
                      <SelectItem key={account.id} value={account.id}>{account.name}</SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {/* Footer fixo */}
        <div className="px-6 py-4 shrink-0 border-t border-border/40 flex gap-3 pb-[max(1rem,env(safe-area-inset-bottom))]">
          <Button variant="outline" className="flex-1 rounded-xl h-11" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button
            onClick={onSettle}
            disabled={isSettling || !settleAccountId}
            className="flex-1 rounded-xl h-11"
          >
            {isSettling ? <><Loader2 className="h-4 w-4 mr-2 animate-spin" />Processando...</> : "Confirmar"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

