/**
 * Shared Transaction Badge Component
 * 
 * Visual badge to identify shared transactions consistently across all pages.
 * Shows settlement status, transaction type (CREDIT/DEBIT), and member name.
 */

import { Badge } from "@/components/ui/badge";
import { Users, CheckCircle2, Clock } from "lucide-react";
import { cn } from "@/lib/utils";

// ============================================================================
// Types and Interfaces
// ============================================================================

export interface SharedTransactionBadgeProps {
  isShared: boolean;
  isSettled: boolean;
  type: 'CREDIT' | 'DEBIT';
  memberName?: string;
  compact?: boolean;
}

// ============================================================================
// Component
// ============================================================================

/**
 * Badge component for shared transactions
 * 
 * @param props - Component props
 * @returns JSX.Element
 * 
 * @example
 * ```tsx
 * <SharedTransactionBadge
 *   isShared={true}
 *   isSettled={false}
 *   type="CREDIT"
 *   memberName="Wesley"
 * />
 * ```
 */
export function SharedTransactionBadge({
  isShared,
  isSettled,
  type,
  memberName,
  compact = false,
}: SharedTransactionBadgeProps) {
  if (!isShared) {
    return null;
  }

  return (
    <div className="flex items-center gap-1 flex-wrap">
      {/* Status Badge - Priority 1: Settled/Pending */}
      <Badge
        variant="outline"
        className={cn(
          "text-[11px] px-2 py-0.5 rounded-full font-medium whitespace-nowrap border-0",
          isSettled
            ? "bg-success/12 text-success"
            : "bg-warning/12 text-warning"
        )}
      >
        {isSettled ? (
          <><CheckCircle2 className="h-3 w-3 mr-1" /> Pago</>
        ) : (
          <><Clock className="h-3 w-3 mr-1" /> Pendente</>
        )}
      </Badge>

      {/* Tipo Badge - Priority 2: Shared type indicator */}
      <Badge
        variant="outline"
        className="text-[11px] px-2 py-0.5 rounded-full font-medium whitespace-nowrap border-0 bg-accent/12 text-accent"
      >
        <Users className="h-3 w-3 mr-1" />
        {compact ? "Comp." : "Compartilhado"}
        {memberName && !compact && ` - ${memberName}`}
      </Badge>
    </div>
  );
}

import { SharedTripCard } from "@/components/shared/SharedTripCard";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";
import { Database } from "@/types/database";

type Trip = Database["public"]["Tables"]["trips"]["Row"];
type FamilyMember = Database["public"]["Tables"]["family_members"]["Row"] & {
  linked_user_id?: string | null;
  sharing_scope?: string | null;
  scope_start_date?: string | null;
  scope_end_date?: string | null;
  scope_trip_id?: string | null;
};

interface SharedTravelListProps {
  trips: Trip[];
  members: FamilyMember[];
  user: any;
  getFilteredInvoice: (memberId: string) => InvoiceItem[];
  getTotals: (items: InvoiceItem[]) => Record<string, any>;
  formatCurrency: (val: number, cur?: string) => string;
  onSettle: (
    id: string,
    type: "PAY" | "RECEIVE",
    amt: number,
    specificItem: InvoiceItem | undefined,
    tripId: string
  ) => void;
  onUndo: (item: InvoiceItem) => void;
  onDelete: (item: InvoiceItem) => void;
  onDeleteSeries: (item: InvoiceItem) => void;
  onConfirmReceipt: (item: InvoiceItem) => void;
  onAnticipate: (item: InvoiceItem) => void;
}

export function SharedTravelList({
  trips,
  members,
  user,
  getFilteredInvoice,
  getTotals,
  formatCurrency,
  onSettle,
  onUndo,
  onDelete,
  onDeleteSeries,
  onConfirmReceipt,
  onAnticipate,
}: SharedTravelListProps) {
  const filteredTrips = trips.filter((t) =>
    members.some((m) => getFilteredInvoice(m.id).some((i) => i.tripId === t.id))
  );

  return (
    <>
      {filteredTrips.map((t) => (
        <SharedTripCard
          key={t.id}
          trip={t}
          members={members}
          getFilteredInvoice={getFilteredInvoice}
          getTotals={getTotals}
          formatCurrency={formatCurrency}
          user={user}
          onSettle={(id, type, amt, specificItem) => onSettle(id, type, amt, specificItem, t.id)}
          onUndo={onUndo}
          onDelete={onDelete}
          onDeleteSeries={onDeleteSeries}
          onConfirmReceipt={onConfirmReceipt}
          onAnticipate={onAnticipate}
        />
      ))}
    </>
  );
}

import {
  Plane,
  Clock,
  CheckCircle2,
  MoreHorizontal,
  Undo2,
  Calendar,
  Trash2,
  CheckCircle,
} from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { UserAvatar } from "@/components/ui/user-avatar";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { cn } from "@/lib/utils";
import * as dateFns from "date-fns";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";

interface SharedTripCardProps {
  trip: any;
  members: any[];
  getFilteredInvoice: (memberId: string) => InvoiceItem[];
  getTotals: (items: InvoiceItem[]) => any;
  formatCurrency: (value: number, currency: string) => string;
  user: any;
  onSettle: (
    memberId: string,
    type: "PAY" | "RECEIVE",
    amount: number,
    specificItem?: InvoiceItem
  ) => void;
  onUndo: (item: InvoiceItem) => void;
  onDelete: (item: InvoiceItem) => void;
  onDeleteSeries: (item: InvoiceItem) => void;
  onConfirmReceipt: (item: InvoiceItem) => void;
  onAnticipate: (item: InvoiceItem) => void;
}

export function SharedTripCard({
  trip,
  members,
  getFilteredInvoice,
  getTotals,
  formatCurrency,
  user,
  onSettle,
  onUndo,
  onDelete,
  onDeleteSeries,
  onConfirmReceipt,
  onAnticipate,
}: SharedTripCardProps) {
  const tripItems: InvoiceItem[] = [];
  members.forEach((member) => {
    const memberItems = getFilteredInvoice(member.id).filter((i) => i.tripId === trip.id);
    tripItems.push(...memberItems);
  });

  if (tripItems.length === 0) return null;

  const totals = getTotals(tripItems);
  const tripCurrency = trip.currency || "BRL";
  const net = totals[tripCurrency]?.net || 0;

  const itemsByMember: Record<string, InvoiceItem[]> = {};
  tripItems.forEach((item) => {
    if (!itemsByMember[item.memberId]) {
      itemsByMember[item.memberId] = [];
    }
    itemsByMember[item.memberId].push(item);
  });

  const pendingCount = tripItems.filter((i) => !i.isPaid).length;

  const itemsWaitingMe = tripItems.filter((item) => {
    if (item.isPaid) return false;
    const isCredit = item.type === "CREDIT";
    return !isCredit && item.settledByDebtor && !item.settledByCreditor;
  });

  return (
    <div
      key={trip.id}
      className="rounded-xl border-2 border-accent/20 overflow-hidden transition-all bg-card"
    >
      <div className="p-4 bg-accent/5 dark:bg-accent/10">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 rounded-2xl flex items-center justify-center font-bold text-white bg-accent shrink-0 shadow-lg shadow-accent/20">
              <Plane className="h-6 w-6" />
            </div>
            <div className="min-w-0">
              <div className="flex items-center gap-2">
                <p className="font-display font-semibold text-base truncate">{trip.name}</p>
                <Badge
                  variant="outline"
                  className="text-sm font-bold border-accent/30 text-accent bg-accent/15"
                >
                  {tripCurrency}
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground flex items-center gap-1 mt-0.5">
                <Clock className="h-3 w-3" />
                {pendingCount} {pendingCount === 1 ? "item pendente" : "itens pendentes"}
              </p>
            </div>
          </div>

          <div className="flex items-center justify-between sm:justify-end gap-4 border-t sm:border-t-0 pt-3 sm:pt-0 border-accent/20">
            <div className="text-left sm:text-right">
              <p className="text-sm text-muted-foreground uppercase tracking-wider mb-0.5 font-medium">
                Saldo da Viagem
              </p>
              <p
                className={cn(
                  "font-mono font-bold text-2xl leading-none tracking-tight",
                  net === 0
                    ? "text-muted-foreground"
                    : net < 0
                      ? "text-destructive dark:text-destructive"
                      : "text-success dark:text-success"
                )}
              >
                {net === 0 ? "Em dia" : formatCurrency(Math.abs(net), tripCurrency)}
              </p>
            </div>
          </div>
        </div>
      </div>

      {itemsWaitingMe.length > 0 && (
        <div className="bg-warning/8 border-t border-b border-warning/20 p-4 space-y-3 animate-in fade-in duration-300">
          <div className="flex items-start gap-3">
            <div className="p-2 bg-warning/12 rounded-xl text-warning shrink-0">
              <Clock className="h-5 w-5 animate-pulse" />
            </div>
            <div className="flex-1 min-w-0">
              <p className="font-semibold text-sm text-warning">
                Aguardando sua confirma├º├úo nesta viagem
              </p>
              <p className="text-sm text-warning dark:text-warning/90 mt-0.5 leading-relaxed">
                {itemsWaitingMe.length === 1 ? (
                  <>
                    Um participante marcou a transa├º├úo de acerto{" "}
                    <strong>"{itemsWaitingMe[0].description}"</strong> de{" "}
                    <strong>
                      {formatCurrency(itemsWaitingMe[0].amount, itemsWaitingMe[0].currency)}
                    </strong>{" "}
                    como paga. Confirme o recebimento e escolha em qual conta deseja creditar.
                  </>
                ) : (
                  <>
                    H├í <strong>{itemsWaitingMe.length} acertos pendentes</strong> (total de{" "}
                    <strong>
                      {formatCurrency(
                        itemsWaitingMe.reduce(
                          (sum, i) => SafeFinancialCalculator.add(sum, i.amount),
                          0
                        ),
                        tripCurrency
                      )}
                    </strong>
                    ) marcados como pagos. Confirme para atualizar seu saldo e escolher as contas de
                    recebimento.
                  </>
                )}
              </p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2 pt-1">
            {itemsWaitingMe.map((item) => (
              <Button
                key={item.id}
                size="sm"
                className="bg-warning hover:bg-warning/92 text-white font-semibold text-sm rounded-xl shadow-md shadow-warning/10 active:scale-95 transition-all"
                onClick={() => onConfirmReceipt(item)}
              >
                <CheckCircle className="h-3.5 w-3.5 mr-1.5" />
                {itemsWaitingMe.length === 1
                  ? "Confirmar e Escolher Conta"
                  : `Confirmar R$ ${item.amount.toFixed(2).replace(".", ",")}`}
              </Button>
            ))}
          </div>
        </div>
      )}

      <div className="border-t border-border">
        {Object.entries(itemsByMember).map(([memberId, memberItems]) => {
          const member = members.find((m) => m.id === memberId);
          if (!member) return null;

          const memberTotals = getTotals(memberItems);
          const memberNet = memberTotals[tripCurrency]?.net || 0;

          return (
            <div key={memberId} className="border-b border-border last:border-0">
              <div className="px-4 py-3 bg-muted/30 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <UserAvatar name={member.name} avatarUrl={member.avatar_url} size="sm" />
                  <span className="font-medium">{member.name}</span>
                </div>
                <span
                  className={cn(
                    "font-mono font-semibold",
                    memberNet === 0
                      ? "text-muted-foreground"
                      : memberNet < 0
                        ? "text-destructive"
                        : "text-success"
                  )}
                >
                  {formatCurrency(Math.abs(memberNet), tripCurrency)}
                </span>
              </div>

              <div className="divide-y divide-border">
                {memberItems.map((item) => {
                  const isCredit = item.type === "CREDIT";
                  const isWaitingMe = !isCredit && item.settledByDebtor && !item.settledByCreditor;
                  const isWaitingOther =
                    isCredit && item.settledByDebtor && !item.settledByCreditor;
                  return (
                    <div
                      key={item.id}
                      className={cn(
                        "px-3 md:px-4 py-3 hover:bg-muted/30 transition-colors flex flex-col md:grid md:grid-cols-12 gap-2 md:gap-2 md:items-center text-sm",
                        item.isPaid && "opacity-60 bg-success/5"
                      )}
                    >
                      <div className="flex md:hidden items-start gap-3">
                        <div className="shrink-0 pt-0.5">
                          {item.isPaid ? (
                            <CheckCircle2 className="h-5 w-5 text-success" />
                          ) : isWaitingMe || isWaitingOther ? (
                            <Clock className="h-5 w-5 text-warning animate-pulse" />
                          ) : (
                            <div
                              className={cn(
                                "h-5 w-5 rounded-full border-2",
                                isCredit ? "border-success" : "border-destructive"
                              )}
                            />
                          )}
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-2 mb-1">
                            <div className="flex-1 min-w-0">
                              <p
                                className={cn(
                                  "text-sm font-medium truncate",
                                  item.isPaid && "text-muted-foreground line-through"
                                )}
                              >
                                {item.description}
                              </p>
                              {item.creatorName && (
                                <span className="text-[11px] bg-accent/15 text-accent px-1 py-0.5 rounded uppercase tracking-wider font-medium inline-block mt-1">
                                  ­ƒÆ│ {item.creatorName}
                                </span>
                              )}
                            </div>
                            <span
                              className={cn(
                                "font-mono text-sm font-bold shrink-0 whitespace-nowrap",
                                item.isPaid
                                  ? "text-muted-foreground"
                                  : isCredit
                                    ? "text-success dark:text-success"
                                    : "text-destructive dark:text-destructive"
                              )}
                            >
                              {formatCurrency(item.amount, item.currency)}
                            </span>
                          </div>

                          <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                            {item.category && <span className="truncate">{item.category}</span>}
                            <span className="whitespace-nowrap">
                              {(() => {
                                if (!item.date) return "-";
                                const dt = new Date(item.date + "T12:00:00");
                                return dateFns.isValid(dt) ? dateFns.format(dt, "dd/MM/yy") : "-";
                              })()}
                            </span>
                          </div>

                          <div className="flex items-center gap-2 mt-2">
                            {item.isPaid && (
                              <Badge
                                variant="outline"
                                className="text-xs font-bold bg-success/12 text-success border-0"
                              >
                                PAGO
                              </Badge>
                            )}
                            <Badge
                              variant="outline"
                              className={cn(
                                "text-xs font-bold border-0",
                                item.isPaid
                                  ? "bg-muted text-muted-foreground"
                                  : isCredit
                                    ? "bg-success/12 text-success"
                                    : "bg-destructive/12 text-destructive"
                              )}
                            >
                              {isCredit ? "CR├ëDITO" : "D├ëBITO"}
                            </Badge>

                            {isWaitingMe && (
                              <Button
                                size="sm"
                                variant="outline"
                                className="h-8 text-sm bg-warning/8 border-warning/20 text-warning hover:bg-warning/12 font-bold"
                                onClick={() => onConfirmReceipt(item)}
                              >
                                <CheckCircle className="h-3 w-3 mr-1" />
                                Confirmar
                              </Button>
                            )}

                            {isWaitingOther && (
                              <Badge
                                variant="outline"
                                className="text-[11px] bg-warning/8 text-warning border-warning/20"
                              >
                                Aguardando
                              </Badge>
                            )}

                            {(item.isPaid ||
                              item.creatorUserId === user?.id ||
                              (item.totalInstallments &&
                                item.totalInstallments > 1 &&
                                !item.isPaid &&
                                item.canAnticipate)) && (
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild>
                                  <Button variant="ghost" size="icon" className="h-7 w-7 ml-auto">
                                    <MoreHorizontal className="h-4 w-4" />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                  {item.isPaid && (
                                    <DropdownMenuItem onClick={() => onUndo(item)}>
                                      <Undo2 className="h-4 w-4 mr-2" />
                                      Desfazer acerto
                                    </DropdownMenuItem>
                                  )}
                                  {!item.isPaid &&
                                    item.totalInstallments &&
                                    item.totalInstallments > 1 &&
                                    item.seriesId &&
                                    item.canAnticipate && (
                                      <DropdownMenuItem
                                        onClick={() => onAnticipate(item)}
                                        className="text-accent focus:text-accent"
                                      >
                                        <Calendar className="h-4 w-4 mr-2" />
                                        Antecipar Parcelas
                                      </DropdownMenuItem>
                                    )}
                                  {item.creatorUserId === user?.id && (
                                    <>
                                      {item.totalInstallments && item.totalInstallments > 1 ? (
                                        <DropdownMenuItem
                                          onClick={() => onDeleteSeries(item)}
                                          className="text-destructive focus:text-destructive"
                                        >
                                          <Trash2 className="h-4 w-4 mr-2" />
                                          Excluir s├®rie ({item.totalInstallments}x)
                                        </DropdownMenuItem>
                                      ) : (
                                        <DropdownMenuItem
                                          onClick={() => onDelete(item)}
                                          className="text-destructive focus:text-destructive"
                                        >
                                          <Trash2 className="h-4 w-4 mr-2" />
                                          Excluir transa├º├úo
                                        </DropdownMenuItem>
                                      )}
                                    </>
                                  )}
                                </DropdownMenuContent>
                              </DropdownMenu>
                            )}
                          </div>
                        </div>
                      </div>

                      <div className="hidden md:contents">
                        <div className="col-span-1">
                          {item.isPaid ? (
                            <CheckCircle2 className="h-5 w-5 text-success" />
                          ) : isWaitingMe || isWaitingOther ? (
                            <Clock className="h-5 w-5 text-warning animate-pulse" />
                          ) : (
                            <div
                              className={cn(
                                "h-5 w-5 rounded-full border-2",
                                isCredit ? "border-success" : "border-destructive"
                              )}
                            />
                          )}
                        </div>

                        <div className="col-span-5">
                          <div className="flex items-center gap-2 flex-wrap">
                            <p
                              className={cn(
                                "font-medium",
                                item.isPaid && "text-muted-foreground line-through"
                              )}
                            >
                              {item.description}
                            </p>
                            {item.creatorName && (
                              <span className="text-sm bg-accent/15 text-accent px-1.5 py-0.5 rounded uppercase tracking-wider font-medium">
                                ­ƒÆ│ {item.creatorName}
                              </span>
                            )}
                          </div>
                          {item.category && (
                            <p className="text-sm text-muted-foreground">{item.category}</p>
                          )}
                        </div>

                        <div className="col-span-2 text-muted-foreground">
                          {(() => {
                            if (!item.date) return "-";
                            const dt = new Date(item.date + "T12:00:00");
                            return dateFns.isValid(dt) ? dateFns.format(dt, "dd/MM/yyyy") : "-";
                          })()}
                        </div>

                        <div className="col-span-2 text-right">
                          <span
                            className={cn(
                              "font-mono text-sm font-medium",
                              item.isPaid
                                ? "text-muted-foreground"
                                : isCredit
                                  ? "text-success dark:text-success"
                                  : "text-destructive dark:text-destructive"
                            )}
                          >
                            {formatCurrency(item.amount, item.currency)}
                          </span>
                        </div>

                        <div className="col-span-2 flex items-center justify-end gap-2">
                          {item.isPaid && (
                            <Badge
                              variant="outline"
                              className="text-[11px] font-bold bg-success/12 text-success border-0"
                            >
                              PAGO
                            </Badge>
                          )}

                          <Badge
                            variant="outline"
                            className={cn(
                              "text-[11px] font-bold border-0",
                              item.isPaid
                                ? "bg-muted text-muted-foreground"
                                : isCredit
                                  ? "bg-success/12 text-success"
                                  : "bg-destructive/12 text-destructive"
                            )}
                          >
                            {isCredit ? "CR├ëDITO" : "D├ëBITO"}
                          </Badge>

                          {isWaitingMe && (
                            <Button
                              size="sm"
                              variant="outline"
                              className="h-8 text-sm bg-warning/8 border-warning/20 text-warning hover:bg-warning/12 font-bold"
                              onClick={() => onConfirmReceipt(item)}
                            >
                              <CheckCircle className="h-3 w-3 mr-1" />
                              Confirmar
                            </Button>
                          )}

                          {isWaitingOther && (
                            <Badge
                              variant="outline"
                              className="text-[11px] bg-warning/8 text-warning border-warning/20"
                            >
                              Aguardando
                            </Badge>
                          )}

                          {!item.isSettled && !isWaitingMe && !isWaitingOther && (
                            <Button
                              size="sm"
                              variant="outline"
                              className="h-8 text-sm bg-success/8 border-success/20 text-success hover:bg-success/12 font-bold"
                              onClick={() =>
                                onSettle(memberId, isCredit ? "RECEIVE" : "PAY", item.amount, item)
                              }
                            >
                              <Wallet className="h-3 w-3 mr-1" />
                              Acertar
                            </Button>
                          )}

                          {(item.isPaid ||
                            item.creatorUserId === user?.id ||
                            (item.totalInstallments &&
                              item.totalInstallments > 1 &&
                              !item.isPaid &&
                              item.canAnticipate)) && (
                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button variant="ghost" size="icon" className="h-8 w-8">
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                {item.isPaid && (
                                  <DropdownMenuItem onClick={() => onUndo(item)}>
                                    <Undo2 className="h-4 w-4 mr-2" />
                                    Desfazer acerto
                                  </DropdownMenuItem>
                                )}
                                {!item.isPaid &&
                                  item.totalInstallments &&
                                  item.totalInstallments > 1 &&
                                  item.seriesId &&
                                  item.canAnticipate && (
                                    <DropdownMenuItem
                                      onClick={() => onAnticipate(item)}
                                      className="text-accent focus:text-accent"
                                    >
                                      <Calendar className="h-4 w-4 mr-2" />
                                      Antecipar Parcelas
                                    </DropdownMenuItem>
                                  )}
                                {item.creatorUserId === user?.id && (
                                  <>
                                    {item.totalInstallments && item.totalInstallments > 1 ? (
                                      <DropdownMenuItem
                                        onClick={() => onDeleteSeries(item)}
                                        className="text-destructive focus:text-destructive"
                                      >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        Excluir s├®rie ({item.totalInstallments}x)
                                      </DropdownMenuItem>
                                    ) : (
                                      <DropdownMenuItem
                                        onClick={() => onDelete(item)}
                                        className="text-destructive focus:text-destructive"
                                      >
                                        <Trash2 className="h-4 w-4 mr-2" />
                                        Excluir transa├º├úo
                                      </DropdownMenuItem>
                                    )}
                                  </>
                                )}
                              </DropdownMenuContent>
                            </DropdownMenu>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {memberNet !== 0 && memberItems.filter((i) => !i.isPaid).length > 0 && (
                <div className="px-4 py-3 bg-muted/20">
                  <Button
                    variant={memberNet < 0 ? "destructive" : "default"}
                    size="sm"
                    className={cn(
                      "h-12 sm:h-10 w-full",
                      memberNet > 0 && "bg-success hover:bg-success/92"
                    )}
                    onClick={() =>
                      onSettle(memberId, memberNet < 0 ? "PAY" : "RECEIVE", Math.abs(memberNet))
                    }
                  >
                    <span>{memberNet < 0 ? "Pagar" : "Receber"}</span>
                  </Button>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from "react";
import { Check, ChevronDown, ChevronRight, Loader2, Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useUserProfile } from "@/hooks/useUserProfile";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useCreateCategory } from "@/hooks/useCategories";
import { toast } from "sonner";

interface Category {
  id: string;
  name: string;
  icon: string | null;
  type: string;
  parent_category_id: string | null;
}

interface CategorySelectorProps {
  categories: Category[];
  value: string;
  onValueChange: (value: string) => void;
  type: 'income' | 'expense';
  placeholder?: string;
}

export function CategorySelector({
  categories,
  value,
  onValueChange,
  type,
  placeholder = "Selecione uma categoria"
}: CategorySelectorProps) {
  const [open, setOpen] = useState(false);
  const [expandedParents, setExpandedParents] = useState<Set<string>>(new Set());
  const { data: profile } = useUserProfile();
  const useSubcategories = profile?.use_subcategories ?? false;

  // Estados para cria├º├úo r├ípida de categoria
  const createCategory = useCreateCategory();
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [newCatName, setNewCatName] = useState("");
  const [newCatIcon, setNewCatIcon] = useState("­ƒÅÀ´©Å");
  const [newParentId, setNewParentId] = useState<string | null>(null);

  const handleCreateCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCatName.trim()) return;

    try {
      const newCat = await createCategory.mutateAsync({
        name: newCatName.trim(),
        type: type,
        icon: newCatIcon,
        parent_category_id: newParentId
      });
      toast.success("Categoria criada com sucesso!");
      setShowCreateDialog(false);
      setNewCatName("");
      setNewCatIcon("­ƒÅÀ´©Å");
      setNewParentId(null);
      
      // Auto-seleciona a categoria rec├®m-criada
      if (newCat && newCat.id) {
        onValueChange(newCat.id);
        setOpen(false);
      }
    } catch (err: any) {
      toast.error(err.message || "Erro ao criar categoria");
    }
  };

  // Prevenir scroll da p├ígina quando o popover est├í aberto (mobile)
  React.useEffect(() => {
    if (open) {
      // Salvar posi├º├úo atual do scroll
      const scrollY = window.scrollY;
      document.body.style.position = 'fixed';
      document.body.style.top = `-${scrollY}px`;
      document.body.style.width = '100%';
    } else {
      // Restaurar scroll
      const scrollY = document.body.style.top;
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
      if (scrollY) {
        window.scrollTo(0, parseInt(scrollY || '0') * -1);
      }
    }

    return () => {
      // Cleanup ao desmontar
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
    };
  }, [open]);

  // Valida├º├úo: se categories n├úo existe ou est├í vazio, retornar componente vazio
  if (!categories || categories.length === 0) {
    return (
      <Button
        variant="outline"
        disabled
        className="h-12 w-full justify-between font-normal"
      >
        <span className="text-muted-foreground">Carregando categoriasÔÇª</span>
      </Button>
    );
  }

  // Organizar categorias em hierarquia
  const ALLOWED_EXPENSE_PARENTS = [
    "Supermercado",
    "Restaurantes e Lanches",
    "Delivery",
    "Gasolina",
    "Transporte",
    "Moradia",
    "Contas e Assinaturas",
    "Sa├║de",
    "Educa├º├úo",
    "Compras",
    "Lazer",
    "Viagens",
    "Fam├¡lia e Pets",
    "Financeiro",
    "Impostos",
    "Outros"
  ];

  const parents = categories.filter(c => {
    if (c.parent_category_id) return false;
    if (c.type !== type) return false;
    if (type === 'expense') {
      return ALLOWED_EXPENSE_PARENTS.includes(c.name);
    }
    return true;
  });

  const childrenMap = new Map<string, Category[]>();
  
  categories.forEach(cat => {
    if (cat.parent_category_id && cat.type === type) {
      if (!childrenMap.has(cat.parent_category_id)) {
        childrenMap.set(cat.parent_category_id, []);
      }
      childrenMap.get(cat.parent_category_id)!.push(cat);
    }
  });

  // Encontrar categoria selecionada
  const selectedCategory = categories.find(c => c.id === value);
  const selectedParent = selectedCategory?.parent_category_id 
    ? categories.find(c => c.id === selectedCategory.parent_category_id)
    : null;

  const toggleParent = (parentId: string) => {
    const newExpanded = new Set(expandedParents);
    if (newExpanded.has(parentId)) {
      newExpanded.delete(parentId);
    } else {
      newExpanded.add(parentId);
    }
    setExpandedParents(newExpanded);
  };

  const handleSelect = (categoryId: string) => {
    onValueChange(categoryId);
    setOpen(false);
  };

  return (
    <>
      <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          role="combobox"
          aria-expanded={open}
          className="h-12 w-full justify-between font-normal"
        >
          {selectedCategory ? (
            <div className="flex items-center gap-2">
              {selectedParent && (
                <span className="text-muted-foreground text-sm">
                  {selectedParent.icon} {selectedParent.name} /
                </span>
              )}
              <span>{selectedCategory.icon} {selectedCategory.name}</span>
            </div>
          ) : (
            <span className="text-muted-foreground">{placeholder}</span>
          )}
          <ChevronDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent 
        className="w-[400px] p-0" 
        align="start"
        onWheel={(e) => {
          e.stopPropagation();
        }}
        onTouchStart={(e) => {
          e.stopPropagation();
        }}
        onTouchMove={(e) => {
          e.stopPropagation();
        }}
      >
        <div 
          className="max-h-[400px] overflow-y-auto p-2 overscroll-contain touch-pan-y"
          style={{ 
            overscrollBehavior: 'contain',
            WebkitOverflowScrolling: 'touch'
          }}
        >
          {parents.map((parent) => {
            const children = childrenMap.get(parent.id) || [];
            const isExpanded = expandedParents.has(parent.id);
            const hasChildren = useSubcategories && children.length > 0;

            return (
              <div key={parent.id} className="mb-1">
                <div className="flex items-center gap-1">
                  {hasChildren && (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-8 w-8 shrink-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleParent(parent.id);
                      }}
                    >
                      {isExpanded ? (
                        <ChevronDown className="h-4 w-4" />
                      ) : (
                        <ChevronRight className="h-4 w-4" />
                      )}
                    </Button>
                  )}
                  {!hasChildren && <div className="w-8 shrink-0" />}
                  
                  <button
                    type="button"
                    onClick={() => handleSelect(parent.id)}
                    className={cn(
                      "flex-1 flex items-center gap-2 px-3 py-2.5 text-sm font-medium rounded-md transition-colors",
                      value === parent.id
                        ? "bg-primary text-primary-foreground"
                        : "hover:bg-muted"
                    )}
                  >
                    <span className="text-base">{parent.icon}</span>
                    <span className="flex-1 text-left font-semibold">{parent.name}</span>
                    {value === parent.id && (
                      <Check className="h-4 w-4 shrink-0" />
                    )}
                  </button>
                </div>

                {/* Subcategorias */}
                {isExpanded && hasChildren && (
                  <div className="ml-8 mt-1 space-y-2 border-l-2 border-muted pl-2">
                    {children.map((child) => (
                      <button
                        key={child.id}
                        type="button"
                        onClick={() => handleSelect(child.id)}
                        className={cn(
                          "w-full flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-md transition-colors",
                          value === child.id
                            ? "bg-primary/20 text-primary border border-primary/30"
                            : "hover:bg-muted text-muted-foreground"
                        )}
                      >
                        <span className="text-base">{child.icon}</span>
                        <span className="flex-1 text-left">{child.name}</span>
                        {value === child.id && (
                          <Check className="h-3 w-3 shrink-0" />
                        )}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
        <div className="border-t border-border p-2 bg-muted/20">
          <Button
            type="button"
            variant="ghost"
            className="w-full text-sm font-bold justify-center text-primary gap-1"
            onClick={() => setShowCreateDialog(true)}
          >
            <Plus className="h-3 w-3" />
            Criar Nova Categoria
          </Button>
        </div>
      </PopoverContent>
    </Popover>

    <Dialog open={showCreateDialog} onOpenChange={setShowCreateDialog}>
      <DialogContent className="sm:max-w-[400px] w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <DialogHeader>
          <DialogTitle>Nova Categoria</DialogTitle>
          <DialogDescription>Crie uma nova categoria para organizar seus lan├ºamentos de {type === 'expense' ? 'despesas' : 'receitas'}</DialogDescription>
        </DialogHeader>
