          </div>
        ) : (
          <div className="space-y-2">
            <Label>Categoria</Label>
            <div className="h-10 flex items-center justify-center bg-muted rounded-md">
              <span className="text-sm font-bold text-muted-foreground">Autom├ítico</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

