            <DialogTitle className="flex items-center gap-2 text-accent">
              <Sparkles className="h-5 w-5" />
              {titles[type]}
            </DialogTitle>
            <DialogDescription>
              {descriptions[type]} em <strong>{destination}</strong>
            </DialogDescription>
          </DialogHeader>

