            {isLoading ? (
              <div className="space-y-3">
                <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
                  <Loader2 className="h-8 w-8 animate-spin mb-4 text-accent" />
                  <p className="text-sm text-center">
                    A IA est├í montando sugest├Áes personalizadas para {destination}...
                  </p>
                </div>
                {[1, 2, 3, 4].map((i) => (
                  <div
                    key={i}
                    className="flex items-start space-x-3 p-3 rounded-xl border border-border/50 bg-muted/20 animate-pulse"
                  >
                    <div className="w-4 h-4 rounded bg-muted-foreground/20 mt-1 shrink-0" />
                    <div className="space-y-2 flex-1">
                      <div className="h-4 bg-muted-foreground/20 rounded w-3/4" />
                      <div className="h-3 bg-muted-foreground/20 rounded w-1/2" />
                    </div>
                  </div>
                ))}
              </div>
            ) : suggestions.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground text-sm">
                N├úo foi poss├¡vel gerar sugest├Áes no momento. Tente novamente.
              </div>
            ) : (
              <div className="space-y-2">
                <div className="flex justify-between items-center py-1">
                  <span className="text-sm font-medium text-muted-foreground">
                    {selectedIndices.size} de {suggestions.length} selecionados
                  </span>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-sm h-8 text-accent"
                    onClick={() => {
                      if (selectedIndices.size === suggestions.length) {
                        setSelectedIndices(new Set());
                      } else {
                        setSelectedIndices(new Set(suggestions.map((_, i) => i)));
                      }
                    }}
                  >
                    {selectedIndices.size === suggestions.length
                      ? 'Desmarcar todos'
                      : 'Marcar todos'}
                  </Button>
                </div>

                <div className="space-y-2">
                  {suggestions.map((item, index) => (
                    <div
                      key={index}
                      className={`flex items-start space-x-3 p-3 rounded-xl border transition-colors cursor-pointer ${
                        selectedIndices.has(index)
                          ? 'border-accent/50 bg-accent/10 dark:bg-accent/20'
                          : 'border-border/50 hover:bg-muted/50'
                      }`}
                      onClick={() => toggleSelection(index)}
                    >
                      <Checkbox
                        checked={selectedIndices.has(index)}
                        onCheckedChange={() => toggleSelection(index)}
                        className="mt-1 data-[state=checked]:bg-accent data-[state=checked]:border-accent shrink-0"
                        onClick={(e) => e.stopPropagation()}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="font-medium text-sm leading-tight">
                          {type === 'shopping' && item.item}
                          {type === 'itinerary' && item.title}
                          {type === 'checklist' && item.item}
                        </p>
                        <p className="text-xs text-muted-foreground mt-1">
                          {type === 'shopping' &&
                            `Custo estimado: ${currency} ${item.estimatedCost?.toFixed(2)}`}
                          {type === 'itinerary' &&
                            `${item.location} ÔÇó Aprox. ${item.durationHours}h`}
                          {type === 'checklist' && item.category}
                        </p>
                        {type === 'itinerary' && item.description && (
                          <p className="text-xs text-muted-foreground mt-1 line-clamp-2">
                            {item.description}
                          </p>
                        )}
                        {type === 'itinerary' && (
                          <div className="flex gap-1 mt-2">
                            <a
                              href={item.mapsUrl || `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(item.title + (item.location ? ', ' + item.location : '') + ', ' + destination)}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              className="inline-flex items-center gap-1 text-[10px] font-medium px-2 py-1 rounded-md bg-blue-50 text-blue-600 hover:bg-blue-100 dark:bg-blue-950 dark:text-blue-400 dark:hover:bg-blue-900 transition-colors"
                              onClick={(e) => e.stopPropagation()}
                              title={item.mapsUrl ? 'Abrir localiza├º├úo exata no Google Maps' : 'Buscar no Google Maps'}
                            >
                              <MapPin className="h-3 w-3" />
                              Maps{item.mapsUrl ? ' Ô£ô' : ''}
                            </a>
                            {item.rating && (
                              <span className="inline-flex items-center gap-0.5 text-[10px] font-bold px-1.5 py-1 rounded-md bg-yellow-50 text-yellow-700 dark:bg-yellow-950 dark:text-yellow-400">
                                Ô¡É {item.rating}
                              </span>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          <div className="px-6 py-4 flex gap-3 justify-end border-t border-border/50 shrink-0">
            <Button variant="ghost" onClick={() => setIsOpen(false)}>
              Cancelar
            </Button>
            <Button
              onClick={handleApply}
              disabled={isLoading || suggestions.length === 0 || selectedIndices.size === 0}
              className="bg-accent hover:bg-accent/90 text-white"
            >
              Adicionar {selectedIndices.size} {selectedIndices.size === 1 ? 'item' : 'itens'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState } from "react";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Users, UserPlus, UserCircle2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { useSharedContacts } from "@/hooks/useFamily";

interface AddParticipantDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  availableMembers: any[];
  onAdd: (member: any) => void;
  onAddGuest?: (guestName: string) => void;
  onNavigateToFamily: () => void;
  getInitials: (name: string) => string;
  currentParticipantNames?: string[];
}

export function AddParticipantDialog({
  open,
  onOpenChange,
  availableMembers,
  onAdd,
  onAddGuest,
  onNavigateToFamily,
  getInitials,
  currentParticipantNames = [],
}: AddParticipantDialogProps) {
  const [tab, setTab] = useState<'family' | 'contacts' | 'guest'>('family');
  const [guestName, setGuestName] = useState('');
  const { data: contacts = [] } = useSharedContacts();

  // Filter out contacts already in the trip
  const availableContacts = contacts.filter(
    c => !currentParticipantNames.includes(c.name)
  );

  const handleAddGuest = () => {
    if (!guestName.trim()) return;
    onAddGuest?.(guestName.trim());
    setGuestName('');
    onOpenChange(false);
  };

  const handleAddContact = (contact: any) => {
    // Se o contato tem linked_user_id (usu├írio registrado), envia convite
    if (contact.linked_user_id) {
      onAdd({ linked_user_id: contact.linked_user_id, name: contact.name, email: contact.email });
    } else {
      // Contato externo sem conta ÔåÆ adiciona como guest
      onAddGuest?.(contact.name);
    }
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={(v) => { onOpenChange(v); setGuestName(''); setTab('family'); }}>
      <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle>Adicionar Participante</DialogTitle>
          <DialogDescription>Fam├¡lia, contatos ou convidado externo</DialogDescription>
        </DialogHeader>

        {/* Tab toggle */}
        <div className="px-6 pt-1 pb-3 shrink-0">
          <div className="flex gap-1 p-1 rounded-xl bg-muted">
            <button
              type="button"
              onClick={() => setTab('family')}
              className={cn(
                "flex-1 py-2 text-xs font-medium rounded-lg transition-all",
                tab === 'family' ? "bg-background shadow-sm text-foreground" : "text-muted-foreground"
              )}
            >
              Fam├¡lia
            </button>
            {contacts.length > 0 && (
              <button
                type="button"
                onClick={() => setTab('contacts')}
                className={cn(
                  "flex-1 py-2 text-xs font-medium rounded-lg transition-all",
                  tab === 'contacts' ? "bg-background shadow-sm text-foreground" : "text-muted-foreground"
                )}
              >
                Contatos
              </button>
            )}
            <button
              type="button"
              onClick={() => setTab('guest')}
              className={cn(
                "flex-1 py-2 text-xs font-medium rounded-lg transition-all",
                tab === 'guest' ? "bg-background shadow-sm text-foreground" : "text-muted-foreground"
              )}
            >
              Novo
            </button>
          </div>
        </div>

        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar space-y-3">
          {tab === 'family' && (
            <>
              {availableMembers.length === 0 ? (
                <div className="py-8 text-center bg-muted/20 rounded-xl border border-border/50">
                  <Users className="h-12 w-12 mx-auto mb-3 text-muted-foreground" />
                  <p className="text-sm font-medium mb-1">Nenhum membro dispon├¡vel</p>
                  <p className="text-sm text-muted-foreground mb-4">
                    Todos os membros da fam├¡lia j├í est├úo nesta viagem.
                  </p>
                  <Button variant="outline" size="sm" className="rounded-xl" onClick={onNavigateToFamily}>
                    Adicionar Novos Membros
                  </Button>
                </div>
              ) : (
                availableMembers.map((member) => (
                  <div
                    key={member.id}
                    className="flex items-center justify-between p-4 rounded-xl border border-border hover:border-foreground/20 hover:bg-accent/50 cursor-pointer transition-colors"
                    onClick={() => onAdd(member)}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-primary/10 text-primary flex items-center justify-center font-bold">
                        {getInitials(member.name)}
                      </div>
                      <span className="font-medium text-sm">{member.name}</span>
                    </div>
                  </div>
                ))
              )}
            </>
          )}

          {tab === 'contacts' && (
            <>
              {availableContacts.length === 0 ? (
                <div className="py-8 text-center bg-muted/20 rounded-xl border border-border/50">
                  <UserCircle2 className="h-12 w-12 mx-auto mb-3 text-muted-foreground" />
                  <p className="text-sm font-medium mb-1">Nenhum contato dispon├¡vel</p>
                  <p className="text-sm text-muted-foreground">
                    Todos os seus contatos j├í est├úo nesta viagem, ou voc├¬ ainda n├úo adicionou contatos.
                  </p>
                </div>
              ) : (
                availableContacts.map((contact) => (
                  <div
                    key={contact.id}
                    className="flex items-center justify-between p-4 rounded-xl border border-border hover:border-foreground/20 hover:bg-accent/50 cursor-pointer transition-colors"
                    onClick={() => handleAddContact(contact)}
                  >
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-full bg-muted text-muted-foreground flex items-center justify-center font-bold text-sm">
                        {getInitials(contact.name)}
                      </div>
                      <div>
                        <span className="font-medium text-sm">{contact.name}</span>
                        <p className="text-xs text-muted-foreground">{contact.linked_user_id ? 'Usu├írio registrado' : 'Contato externo'}</p>
                      </div>
                    </div>
                  </div>
                ))
              )}
            </>
          )}

          {tab === 'guest' && (
            <div className="space-y-4 pt-1">
              <div className="flex items-center gap-3 p-4 rounded-xl bg-muted/30 border border-border/50">
                <UserPlus className="h-5 w-5 text-muted-foreground shrink-0" />
                <p className="text-sm text-muted-foreground">
                  Adicione algu├®m que n├úo tem conta no app ÔÇö amigo, familiar ou colega de viagem.
                  O nome aparecer├í nos rateios e no resumo da viagem.
                </p>
              </div>
              <div className="space-y-2">
                <Label htmlFor="guest-name">Nome do convidado</Label>
                <Input
                  id="guest-name"
                  placeholder="Ex: Jo├úo Silva"
                  value={guestName}
                  onChange={(e) => setGuestName(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAddGuest()}
                  className="rounded-xl"
                  autoFocus
                />
              </div>
              <Button
                onClick={handleAddGuest}
                disabled={!guestName.trim()}
                className="w-full rounded-xl"
              >
                Adicionar Convidado
              </Button>
            </div>
          )}

          <div className="pt-1">
            <Button variant="outline" className="w-full rounded-xl" onClick={() => onOpenChange(false)}>
              Fechar
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Trip } from "@/hooks/useTrips";
import { moneyUtils } from "@/utils/money";

const CURRENCIES = [
  { code: 'BRL', symbol: 'R$', name: 'Real Brasileiro' },
  { code: 'USD', symbol: '$', name: 'D├│lar Americano' },
  { code: 'EUR', symbol: 'Ôé¼', name: 'Euro' },
  { code: 'GBP', symbol: '┬ú', name: 'Libra Esterlina' },
  { code: 'ARS', symbol: '$', name: 'Peso Argentino' },
  { code: 'CLP', symbol: '$', name: 'Peso Chileno' },
  { code: 'UYU', symbol: '$', name: 'Peso Uruguaio' },
  { code: 'PYG', symbol: 'Ôé▓', name: 'Guarani Paraguaio' },
];

interface EditTripDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  trip: Trip | null;
  onSubmit: (data: {
    name: string;
    destination: string;
    start_date: string;
    end_date: string;
    currency: string;
    budget: number;
  }) => void;
  isLoading: boolean;
}

export function EditTripDialog({
  open,
  onOpenChange,
  trip,
  onSubmit,
  isLoading,
}: EditTripDialogProps) {
  const [name, setName] = useState("");
  const [destination, setDestination] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [currency, setCurrency] = useState("BRL");
  const [budget, setBudget] = useState("");

  // Preencher campos quando trip mudar
  useEffect(() => {
    if (trip) {
      setName(trip.name);
      setDestination(trip.destination || "");
      setStartDate(trip.start_date);
      setEndDate(trip.end_date);
      setCurrency(trip.currency);
      setBudget(trip.budget?.toString() || "");
    }
  }, [trip]);

  const handleSubmit = () => {
    onSubmit({
      name: destination, // Usar destino como nome
      destination,
      start_date: startDate,
      end_date: endDate,
      currency,
      budget: moneyUtils.parse(budget),
    });
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full sm:max-w-2xl !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle>Editar Viagem</DialogTitle>
          <DialogDescription>
            Apenas o criador da viagem pode editar estes campos
          </DialogDescription>
        </DialogHeader>
        <div className="flex-1 overflow-y-auto px-6 hide-scrollbar">
          <div className="space-y-4 py-2">
            <div className="space-y-2 mt-2">
              <Label>Destino</Label>
              <Input
                placeholder="Ex: Rio de Janeiro, RJ"
                value={destination}
                onChange={(e) => setDestination(e.target.value)}
                className="rounded-xl"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>In├¡cio</Label>
                <Input
                  type="date"
                  value={startDate}
                  onChange={(e) => setStartDate(e.target.value)}
                  className="rounded-xl"
                />
              </div>
              <div className="space-y-2">
                <Label>Fim</Label>
                <Input
                  type="date"
                  value={endDate}
                  onChange={(e) => setEndDate(e.target.value)}
                  min={startDate}
                  className="rounded-xl"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Moeda</Label>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger className="rounded-xl">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="rounded-xl">
                    {CURRENCIES.map((curr) => (
                      <SelectItem key={curr.code} value={curr.code}>
                        {curr.symbol} {curr.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Or├ºamento Geral</Label>
                <Input
                  placeholder="5000"
                  value={budget}
                  onChange={(e) => setBudget(e.target.value.replace(/\D/g, ""))}
                  className="rounded-xl"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Rodap├® fixo */}
        <div className="shrink-0 flex gap-3 px-6 py-4 border-t border-border bg-background">
          <Button type="button" variant="outline" className="flex-1 h-11 rounded-xl" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button
            className="flex-1 h-11 rounded-xl font-bold"
            onClick={handleSubmit}
            disabled={isLoading || !destination || !startDate || !endDate || !budget}
          >
            {isLoading ? "Salvando..." : "Salvar"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { CurrencyInput } from "@/components/ui/currency-input";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { ExchangePurchase, ExchangePurchaseInput } from "@/types/tripExchange";
import { getCurrencySymbol } from "@/services/exchangeCalculations";
import { moneyUtils } from "@/utils/money";

interface ExchangePurchaseDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currency: string;
  purchase?: ExchangePurchase;
  onSubmit: (data: ExchangePurchaseInput) => void;
  isLoading: boolean;
}

export function ExchangePurchaseDialog({
  open,
  onOpenChange,
  currency,
  purchase,
  onSubmit,
  isLoading,
}: ExchangePurchaseDialogProps) {
  const [foreignAmount, setForeignAmount] = useState("");
  const [localAmount, setLocalAmount] = useState("");
  const [description, setDescription] = useState("");
  const [purchaseDate, setPurchaseDate] = useState(
    new Date().toISOString().split("T")[0]
  );

  const currencySymbol = getCurrencySymbol(currency);
  const isEditing = !!purchase;

  // Preencher campos quando editando
  useEffect(() => {
    if (purchase) {
      setForeignAmount(purchase.foreign_amount.toString());
      setLocalAmount((purchase.foreign_amount * purchase.exchange_rate).toFixed(2));
      setDescription(purchase.description || "");
      setPurchaseDate(purchase.purchase_date);
    } else {
      setForeignAmount("");
      setLocalAmount("");
      setDescription("");
      setPurchaseDate(new Date().toISOString().split("T")[0]);
    }
  }, [purchase, open]);

  // C├ílculos em tempo real
  const foreignAmountNum = moneyUtils.parse(foreignAmount) || 0;
  const localAmountNum = moneyUtils.parse(localAmount) || 0;

  let exchangeRateNum = 0;
  if (foreignAmountNum > 0 && localAmountNum > 0) {
    exchangeRateNum = localAmountNum / foreignAmountNum;
  }

  const handleSubmit = () => {
    if (foreignAmountNum <= 0 || localAmountNum <= 0) return;

    onSubmit({
      foreign_amount: foreignAmountNum,
      exchange_rate: exchangeRateNum,
      cet_percentage: 0,
      description: description || undefined,
      purchase_date: purchaseDate,
    });
  };

  const isValid = foreignAmountNum > 0 && localAmountNum > 0 && purchaseDate;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full sm:max-w-lg !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle>
            {isEditing ? "Editar Compra de C├ómbio" : "Nova Compra de C├ómbio"}
          </DialogTitle>
          <DialogDescription>
            Registre uma compra de {currency} para esta viagem
          </DialogDescription>
        </DialogHeader>

        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar space-y-4">
          <div className="space-y-4 mt-2">
            {/* Valor em moeda estrangeira */}
            <div className="space-y-2">
              <Label>Valor em {currency} *</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground z-10 font-medium">
                  {currencySymbol}
                </span>
                <CurrencyInput
                  id="foreign-amount"
                  name="foreign-amount"
                  placeholder="1000.00"
                  value={foreignAmount}
                  onChange={setForeignAmount}
                  currency={currency}
                  className="pl-10 h-12 rounded-xl"
                />
              </div>
            </div>

            {/* Total Pago */}
            <div className="space-y-2">
              <Label>Total Pago (R$) *</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground z-10 font-medium">
                  R$
                </span>
                <CurrencyInput
                  id="local-amount"
                  name="local-amount"
                  placeholder="0.00"
                  value={localAmount}
                  onChange={setLocalAmount}
                  currency="BRL"
                  className="pl-10 h-12 rounded-xl"
                />
              </div>
            </div>

            {/* C├ílculo em tempo real */}
            {exchangeRateNum > 0 && (
              <div className="p-4 rounded-xl bg-muted/50 border border-primary/20 bg-primary/5">
                <div className="flex justify-between text-sm items-center">
                  <span className="text-muted-foreground font-medium">Taxa Efetiva:</span>
                  <span className="font-mono font-bold text-base text-primary">
                    R$ {exchangeRateNum.toFixed(4).replace('.', ',')}
                  </span>
                </div>
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              {/* Data */}
              <div className="space-y-2">
                <Label>Data da Compra *</Label>
                <Input
                  id="purchase-date"
                  name="purchase-date"
                  type="date"
                  value={purchaseDate}
                  onChange={(e) => setPurchaseDate(e.target.value)}
                  className="rounded-xl"
                />
              </div>

              {/* Descri├º├úo */}
              <div className="space-y-2">
                <Label>Descri├º├úo</Label>
                <Input
                  id="purchase-description"
                  name="purchase-description"
                  placeholder="Ex: Wise, NomadÔÇª"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  className="rounded-xl"
                />
              </div>
            </div>
          </div>
          
          <div className="pt-2 flex gap-3">
            <Button type="button" variant="outline" className="flex-1 rounded-xl" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button className="flex-1 rounded-xl font-bold" onClick={handleSubmit} disabled={isLoading || !isValid}>
              {isLoading ? "SalvandoÔÇª" : isEditing ? "Salvar" : "Adicionar"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { useFamilyMembers } from "@/hooks/useFamily";
import { useAuth } from "@/contexts/AuthContext";
import { Users, Calendar, Loader2 } from "lucide-react";
import * as dateFns from "date-fns";
import { CurrencyInput } from "@/components/ui/currency-input";

const CURRENCIES = [
  { code: 'BRL', symbol: 'R$', name: 'Real Brasileiro' },
  { code: 'USD', symbol: '$', name: 'D├│lar Americano' },
  { code: 'EUR', symbol: 'Ôé¼', name: 'Euro' },
  { code: 'GBP', symbol: '┬ú', name: 'Libra Esterlina' },
  { code: 'ARS', symbol: '$', name: 'Peso Argentino' },
  { code: 'CLP', symbol: '$', name: 'Peso Chileno' },
  { code: 'UYU', symbol: '$', name: 'Peso Uruguaio' },
  { code: 'PYG', symbol: 'Ôé▓', name: 'Guarani Paraguaio' },
];

interface NewTripDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSubmit: (selectedMemberIds: string[]) => void;
  isLoading: boolean;
  name: string;
  setName: (v: string) => void;
  destination: string;
  setDestination: (v: string) => void;
  startDate: string;
  setStartDate: (v: string) => void;
  endDate: string;
  setEndDate: (v: string) => void;
  budget: string;
  setBudget: (v: string) => void;
  currency?: string;
  setCurrency?: (v: string) => void;
}

export function NewTripDialog({
  open,
  onOpenChange,
  onSubmit,
  isLoading,
  name,
  setName,
  destination,
  setDestination,
  startDate,
  setStartDate,
  endDate,
  setEndDate,
  budget,
  setBudget,
  currency = 'BRL',
  setCurrency,
}: NewTripDialogProps) {
  const { user } = useAuth();
  const { data: familyMembers = [] } = useFamilyMembers();
  const [selectedMembers, setSelectedMembers] = useState<string[]>([]);
  const [localCurrency, setLocalCurrency] = useState(currency);

  const handleCurrencyChange = (value: string) => {
    setLocalCurrency(value);
    if (setCurrency) setCurrency(value);
  };

  // Calcular n├║mero de dias
  const tripDays = useMemo(() => {
    if (!startDate || !endDate) return null;
    try {
      const start = dateFns.parseISO(startDate);
      const end = dateFns.parseISO(endDate);
      const days = dateFns.differenceInDays(end, start) + 1; // +1 para incluir o ├║ltimo dia
      return days > 0 ? days : null;
    } catch {
      return null;
    }
  }, [startDate, endDate]);

  const handleSubmit = () => {
    onSubmit(selectedMembers);
    setSelectedMembers([]); // Reset selection
  };

  const toggleMember = (userId: string) => {
    setSelectedMembers(prev =>
      prev.includes(userId)
        ? prev.filter(id => id !== userId)
        : [...prev, userId]
    );
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full sm:max-w-2xl !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle>Nova Viagem</DialogTitle>
          <DialogDescription>Crie uma viagem para organizar despesas</DialogDescription>
        </DialogHeader>
        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar space-y-4">
          <div className="space-y-2 mt-2">
            <Label>Destino</Label>
            <Input 
              placeholder="Ex: Rio de Janeiro, RJ" 
              value={destination}
              onChange={(e) => setDestination(e.target.value)}
              className="rounded-xl"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>In├¡cio</Label>
              <Input 
                type="date" 
                value={startDate}
                onChange={(e) => setStartDate(e.target.value)}
                className="rounded-xl"
              />
            </div>
            <div className="space-y-2">
              <Label>Fim</Label>
              <Input 
                type="date" 
                value={endDate}
                onChange={(e) => setEndDate(e.target.value)}
                min={startDate} // N├úo permitir data anterior ao in├¡cio
                className="rounded-xl"
              />
            </div>
          </div>
          
          {/* Mostrar n├║mero de dias */}
          {tripDays && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground bg-accent/50 p-3 rounded-xl border border-border/50">
              <Calendar className="h-4 w-4" />
              <span>
                {tripDays} {tripDays === 1 ? 'dia' : 'dias'} de viagem
              </span>
            </div>
          )}
          
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Moeda</Label>
              <Select value={localCurrency} onValueChange={handleCurrencyChange}>
                <SelectTrigger className="rounded-xl">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="rounded-xl">
                  {CURRENCIES.map((curr) => (
                    <SelectItem key={curr.code} value={curr.code}>
                      {curr.symbol} {curr.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>
                Or├ºamento Total
                <span className="ml-1 text-sm text-muted-foreground font-normal">(opcional)</span>
              </Label>
              <CurrencyInput 
                placeholder="5000" 
                value={budget}
                onChange={setBudget}
                currency={localCurrency}
              />
            </div>
          </div>

          {/* Sele├º├úo de membros da fam├¡lia */}
          {familyMembers.length > 0 && (
            <div className="space-y-3 pt-4 mt-2 border-t">
              <div className="flex items-center gap-2">
                <Users className="h-4 w-4 text-muted-foreground" />
                <Label>Convidar Participantes (opcional)</Label>
              </div>
              <p className="text-sm text-muted-foreground">
                Selecione membros da fam├¡lia para convidar. Eles poder├úo aceitar ou recusar.
              </p>
              <div className="space-y-2 max-h-40 overflow-y-auto hide-scrollbar border rounded-xl p-3 bg-muted/20">
                {familyMembers
                  .filter(member => member.linked_user_id) // Apenas membros cadastrados
                  .filter(member => member.linked_user_id !== user?.id) // Excluir o criador da viagem
                  .map((member) => (
                    <div
                      key={member.id}
                      className="flex items-center space-x-3 p-2 hover:bg-accent rounded-lg cursor-pointer"
                      onClick={() => toggleMember(member.linked_user_id!)}
                    >
                      <Checkbox
                        checked={selectedMembers.includes(member.linked_user_id!)}
                        className="pointer-events-none rounded-md"
                      />
                      <div className="flex-1">
                        <p className="text-sm font-medium">{member.name}</p>
                        {member.email && (
                          <p className="text-sm text-muted-foreground">{member.email}</p>
                        )}
                      </div>
                    </div>
                  ))}
              </div>
              {selectedMembers.length > 0 && (
                <p className="text-sm text-muted-foreground">
                  {selectedMembers.length} {selectedMembers.length === 1 ? 'convite ser├í enviado' : 'convites ser├úo enviados'}
                </p>
              )}
            </div>
          )}

          <div className="pt-2 flex gap-3">
            <Button type="button" variant="outline" className="flex-1 rounded-xl" onClick={() => onOpenChange(false)}>Cancelar</Button>
            <Button 
              className="flex-1 rounded-xl font-bold"
              onClick={handleSubmit} 
              disabled={isLoading || !destination || !startDate || !endDate}
            >
              {isLoading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Criando...
                </>
              ) : (
                "Criar Viagem"
              )}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Plane, Check, X, Calendar, MapPin } from "lucide-react";
import {
  usePendingTripInvitations,
  useAcceptTripInvitation,
  useRejectTripInvitation,
} from "@/hooks/useTripInvitations";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { logger } from "@/utils/logger";

export function PendingTripInvitationsAlert() {
  const { data: invitations = [], isLoading, error } = usePendingTripInvitations();
  const acceptInvitation = useAcceptTripInvitation();
  const rejectInvitation = useRejectTripInvitation();

  // logger.debug('­ƒƒú [PendingTripInvitationsAlert] Renderizado:', {
  //   invitations,
  //   isLoading,
  //   error,
  //   hasInvitations: invitations && invitations.length > 0
  // });

  if (isLoading) {
    // logger.debug('­ƒƒú [PendingTripInvitationsAlert] Carregando...');
    return null;
  }

  if (error) {
    // logger.error("­ƒƒú [PendingTripInvitationsAlert] Erro ao carregar convites:", error);
    return null;
  }

  if (!invitations || invitations.length === 0) {
    // logger.debug('­ƒƒú [PendingTripInvitationsAlert] Nenhum convite pendente');
    return null;
  }

  // logger.debug('­ƒƒú [PendingTripInvitationsAlert] Renderizando', invitations.length, 'convite(s)');

  return (
    <div className="space-y-3">
      {invitations.map((invitation) => {
        const tripName = invitation.trips?.name || "Viagem";
        const destination = invitation.trips?.destination;
        const startDate = invitation.trips?.start_date;
        const endDate = invitation.trips?.end_date;
        const inviterName = invitation.inviter?.full_name || invitation.inviter?.email || "Algu├®m";

        return (
          <Alert key={invitation.id} className="border-primary/50 bg-primary/5">
            <Plane className="h-4 w-4" />
            <AlertTitle>Novo Convite de Viagem</AlertTitle>
            <AlertDescription className="mt-2 space-y-3">
              <p>
                <strong>{inviterName}</strong> te convidou para <strong>"{tripName}"</strong>
              </p>

              {destination && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <MapPin className="h-4 w-4" />
                  <span>{destination}</span>
                </div>
              )}

              {startDate && endDate && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Calendar className="h-4 w-4" />
                  <span>
                    {dateFns.format(new Date(startDate), "dd/MM/yyyy", { locale: ptBR })} at├®{" "}
                    {dateFns.format(new Date(endDate), "dd/MM/yyyy", { locale: ptBR })}
                  </span>
                </div>
              )}

              <div className="flex gap-2">
                <Button
                  size="sm"
                  onClick={() => acceptInvitation.mutate(invitation.id)}
                  disabled={acceptInvitation.isPending || rejectInvitation.isPending}
                  className="gap-2"
                >
                  <Check className="h-4 w-4" />
                  Aceitar
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => rejectInvitation.mutate(invitation.id)}
                  disabled={acceptInvitation.isPending || rejectInvitation.isPending}
                  className="gap-2"
                >
                  <X className="h-4 w-4" />
                  Recusar
                </Button>
              </div>
            </AlertDescription>
          </Alert>
        );
      })}
    </div>
  );
}

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Trash2, Wallet, HeartHandshake, AlertTriangle, CheckCircle2, UserMinus } from "lucide-react";
import { moneyUtils } from "@/utils/money";
import { cn } from "@/lib/utils";

interface RemoveParticipantDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  participant: {
    id: string;
    trip_id: string;
    user_id: string | null;
    member_id: string;
    name: string;
    role: string;
  } | null;
  balance: {
    participantId: string;
    name: string;
    paid: number;
    owes: number;
    balance: number;
    currency: string;
  } | null;
  onConfirmDirectRemove: () => Promise<void>;
  onConfirmSettleRemove: (accountId: string) => Promise<void>;
  onConfirmForgiveRemove: () => Promise<void>;
  isRemoving: boolean;
  currency: string;
  accounts: any[];
}

import { useState } from "react";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

export function RemoveParticipantDialog({
  open,
  onOpenChange,
  participant,
  balance,
  onConfirmDirectRemove,
  onConfirmSettleRemove,
  onConfirmForgiveRemove,
  isRemoving,
  currency,
  accounts,
}: RemoveParticipantDialogProps) {
  const [selectedAccountId, setSelectedAccountId] = useState<string>("");
  const [activeMode, setActiveMode] = useState<"choose" | "settle">("choose");

  if (!participant) return null;

  if (participant.role === 'owner') {
    return (
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-md shadow-2xl w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background pb-[env(safe-area-inset-bottom)] overflow-hidden pb-[env(safe-area-inset-bottom)]">
          <DialogHeader className="space-y-3">
            <DialogTitle className="flex items-center gap-2 text-base font-display font-black tracking-tight text-destructive">
              <AlertTriangle className="h-5 w-5 animate-pulse" />
              A├º├úo N├úo Permitida
            </DialogTitle>
            <DialogDescription className="text-sm text-muted-foreground font-medium">
              N├úo ├® poss├¡vel remover <span className="font-bold text-foreground">{participant.name}</span> porque ele(a) ├® o criador da viagem.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => onOpenChange(false)} className="rounded-xl px-5">
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    );
  }

  const currentBalance = balance?.balance || 0;
  const isSettled = Math.abs(currentBalance) < 0.01;
  const owesGroup = currentBalance < -0.01;

  const handleSettleSubmit = async () => {
    if (!selectedAccountId) return;
    await onConfirmSettleRemove(selectedAccountId);
    setActiveMode("choose");
    setSelectedAccountId("");
  };

  return (
    <Dialog open={open} onOpenChange={(val) => {
      onOpenChange(val);
      if (!val) {
        setActiveMode("choose");
        setSelectedAccountId("");
      }
    }}>
      <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-card overflow-hidden">
        <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
          <div className="w-12 h-2 bg-muted rounded-full" />
        </div>
        <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
          <DialogTitle className="flex items-center gap-2 text-base font-display font-black tracking-tight text-foreground">
            <UserMinus className="h-5 w-5 text-destructive animate-pulse" />
            Remover Viajante
          </DialogTitle>
          <DialogDescription className="text-sm text-muted-foreground font-medium">
            Gerencie o encerramento da participa├º├úo de <span className="font-bold text-foreground">{participant.name}</span> na viagem.
          </DialogDescription>
        </DialogHeader>

        <div className="px-6 pb-6 overflow-y-auto hide-scrollbar">
        {activeMode === "choose" ? (
          <div className="space-y-4 my-4 max-h-[60vh] overflow-y-auto pr-2">
            {/* Visualiza├º├úo de Saldos do Participante */}
            <div className={cn(
              "p-5 rounded-xl border transition-all duration-300",
              isSettled 
                ? "border-success/20 bg-success/5 dark:bg-success/5" 
                : owesGroup
                  ? "border-warning/20 bg-warning/5 dark:bg-warning/5"
                  : "border-accent/20 bg-accent/5 dark:bg-accent/[0.02]"
            )}>
              <div className="flex items-center gap-3.5 mb-4">
                <div className={cn(
                  "w-10 h-10 rounded-xl flex items-center justify-center shadow-md",
                  isSettled ? "bg-success text-white" : owesGroup ? "bg-warning text-white" : "bg-accent text-white"
                )}>
                  {isSettled ? <CheckCircle2 className="h-5 w-5" /> : <Wallet className="h-5 w-5" />}
                </div>
                <div>
                  <h4 className="font-bold text-sm text-foreground">Status Financeiro</h4>
                  <p className="text-sm text-muted-foreground">
                    {isSettled 
                      ? "Totalmente em dia com a viagem." 
                      : owesGroup 
                        ? `Deve ${moneyUtils.format(Math.abs(currentBalance), currency)} ao grupo.`
                        : `O grupo deve ${moneyUtils.format(currentBalance, currency)} a ele(a).`}
                  </p>
                </div>
              </div>

              <div className="grid grid-cols-3 gap-2 text-center border-t border-border/40 pt-3">
                <div>
                  <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-0.5">Pagou</p>
                  <p className="font-mono text-sm font-black text-foreground">
                    {moneyUtils.format(balance?.paid || 0, currency)}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-0.5">Sua Parte</p>
                  <p className="font-mono text-sm font-black text-foreground">
                    {moneyUtils.format(balance?.owes || 0, currency)}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-0.5">Saldo</p>
                  <p className={cn(
                    "font-mono text-xs font-black",
                    isSettled ? "text-success dark:text-success" :
                    owesGroup ? "text-warning" : "text-accent"
                  )}>
                    {isSettled ? moneyUtils.format(0, currency) : (owesGroup ? "-" : "+") + moneyUtils.format(Math.abs(currentBalance), currency)}
                  </p>
                </div>
              </div>
            </div>

            {/* A├º├Áes Inteligentes de Remo├º├úo baseadas no Saldo */}
            {isSettled ? (
              <div className="p-4 rounded-xl border border-success/10 bg-success/5 flex items-start gap-3">
                <CheckCircle2 className="h-5 w-5 text-success shrink-0 mt-0.5" />
                <p className="text-sm text-muted-foreground">
                  Como este participante n├úo possui pend├¬ncias, voc├¬ pode remov├¬-lo diretamente. O hist├│rico de transa├º├Áes passadas dele continuar├í preservado na viagem.
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                <p className="text-sm font-bold text-muted-foreground uppercase tracking-wider">Como deseja lidar com as pend├¬ncias?</p>
                
                {/* Op├º├úo 1: Zerar e Remover */}
                <button
                  onClick={() => {
                    if (accounts.length > 0) {
                      setSelectedAccountId(accounts[0].id);
                    }
                    setActiveMode("settle");
                  }}
                  className="w-full flex items-center justify-between p-4 rounded-xl border border-border bg-card hover:bg-muted/30 hover:border-primary/20 text-left transition-all group"
                >
                  <div className="flex gap-3">
                    <div className="w-10 h-10 rounded-xl bg-primary/10 group-hover:bg-primary/20 text-primary flex items-center justify-center shrink-0 transition-colors">
                      <Wallet className="h-5 w-5" />
                    </div>
                    <div>
                      <p className="font-bold text-sm text-foreground">Zerar e Remover (Recomendado)</p>
                      <p className="text-sm text-muted-foreground mt-0.5">
