                    <div>
                      <p className="font-bold text-sm text-foreground">Apenas Remover (Manter Hist├│rico)</p>
                      <p className="text-sm text-muted-foreground mt-0.5">
                        Cortar o acesso do participante na hora, mantendo o saldo pendente vis├¡vel no relat├│rio da viagem.
                      </p>
                    </div>
                  </div>
                </button>
              </div>
            )}
          </div>
        ) : (
          <div className="space-y-4 my-4 animate-fade-in">
            <div className="space-y-4">
              <div className="p-4 rounded-xl bg-primary/5 border border-primary/10 flex gap-3">
                <AlertTriangle className="h-5 w-5 text-primary shrink-0 mt-0.5" />
                <p className="text-sm text-muted-foreground">
                  Voc├¬ est├í registrando um acerto no valor de <span className="font-black text-foreground">{moneyUtils.format(Math.abs(currentBalance), currency)}</span> para zerar as contas de <span className="font-bold text-foreground">{participant.name}</span>. Por favor, escolha a conta financeira associada.
                </p>
              </div>

              <div className="space-y-2">
                <label className="text-sm font-bold text-muted-foreground uppercase tracking-widest">Conta Financeira</label>
                {accounts.length === 0 ? (
                  <p className="text-sm text-destructive">Nenhuma conta cadastrada para registrar a transa├º├úo.</p>
                ) : (
                  <Select value={selectedAccountId} onValueChange={setSelectedAccountId}>
                    <SelectTrigger id="settleAccountId" name="settleAccountId" className="w-full rounded-xl border-border bg-card">
                      <SelectValue placeholder="Selecione a contaÔÇª" />
                    </SelectTrigger>
                    <SelectContent className="rounded-xl border-border bg-card/95 backdrop-blur-md">
                      {accounts.map(acc => (
                        <SelectItem key={acc.id} value={acc.id} className="rounded-lg py-2.5">
                          {acc.name} ({acc.bank_name || 'Carteira'})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
              </div>
            </div>

            <div className="flex gap-3 justify-end pt-2">
              <Button 
                variant="outline" 
                onClick={() => setActiveMode("choose")}
                disabled={isRemoving}
                className="rounded-xl px-5"
              >
                Voltar
              </Button>
              <Button 
                onClick={handleSettleSubmit}
                disabled={isRemoving || !selectedAccountId}
                className="rounded-xl px-5 shadow-lg shadow-primary/20"
              >
                {isRemoving ? "ProcessandoÔÇª" : "Confirmar e Remover"}
              </Button>
            </div>
          </div>
        )}

        <DialogFooter className={cn("gap-2 sm:gap-0", activeMode !== "choose" && "hidden")}>
          <Button 
            variant="outline" 
            onClick={() => onOpenChange(false)}
            disabled={isRemoving}
            className="rounded-xl px-5"
          >
            Cancelar Remo├º├úo
          </Button>
          {isSettled && (
            <Button 
              variant="destructive" 
              onClick={onConfirmDirectRemove}
              disabled={isRemoving}
              className="rounded-xl px-5 shadow-lg shadow-destructive/10"
            >
              {isRemoving ? "RemovendoÔÇª" : "Confirmar Remo├º├úo"}
            </Button>
          )}
        </DialogFooter>
        </div>
      </DialogContent>
    </Dialog>
  );
}

