import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, ListChecks, Trash2 } from "lucide-react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { AITripSuggestions } from './AITripSuggestions';
import { EmptyState } from "@/components/ui/empty-state";

interface ChecklistItem {
  id: string;
  trip_id: string;
  item: string;
  is_completed: boolean;
  assigned_to: string | null;
  category: string | null;
  order_index: number;
  created_at: string;
}

interface TripChecklistProps {
  trip: any;
}

const CATEGORIES = [
  { value: "documentos", label: "Documentos" },
  { value: "roupas", label: "Roupas" },
  { value: "higiene", label: "Higiene" },
  { value: "eletronicos", label: "Eletr├┤nicos" },
  { value: "remedios", label: "Rem├®dios" },
  { value: "outros", label: "Outros" },
];

export function TripChecklist({ trip }: TripChecklistProps) {
  const tripId = trip.id;
  const [showDialog, setShowDialog] = useState(false);
  const [newItem, setNewItem] = useState("");
  const [newCategory, setNewCategory] = useState("");
  const [isApplyingAI, setIsApplyingAI] = useState(false);

  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Fetch checklist items
  const { data: items = [], isLoading } = useQuery({
    queryKey: ["trip-checklist", tripId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("trip_checklist")
        .select("*")
        .eq("trip_id", tripId)
        .order("category", { ascending: true })
        .order("order_index", { ascending: true });

      if (error) throw error;
      return data as ChecklistItem[];
    },
  });

  // Create mutation
  const createItem = useMutation({
    mutationFn: async (item: { trip_id: string; item: string; category: string | null }) => {
      const { data, error } = await supabase
        .from("trip_checklist")
        .insert({
          ...item,
          is_completed: false,
          order_index: items.length,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-checklist", tripId] });
      toast({ title: "Item adicionado" });
      setNewItem("");
      setNewCategory("");
      setShowDialog(false);
    },
    onError: (error) => {
      toast({ title: "Erro ao adicionar", description: error.message, variant: "destructive" });
    },
  });

  // Toggle completion mutation
  const toggleItem = useMutation({
    mutationFn: async ({ id, is_completed }: { id: string; is_completed: boolean }) => {
      const { error } = await supabase
        .from("trip_checklist")
        .update({ is_completed })
        .eq("id", id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-checklist", tripId] });
    },
    onError: (error) => {
      toast({ title: "Erro ao atualizar", description: error.message, variant: "destructive" });
    },
  });

  // Delete mutation
  const deleteItem = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from("trip_checklist")
        .delete()
        .eq("id", id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-checklist", tripId] });
      toast({ title: "Item removido" });
    },
    onError: (error) => {
      toast({ title: "Erro ao remover", description: error.message, variant: "destructive" });
    },
  });

  const handleSubmit = () => {
    if (!newItem.trim()) return;
    createItem.mutate({
      trip_id: tripId,
      item: newItem.trim(),
      category: newCategory || null,
    });
  };

  const handleApplyAISuggestions = async (suggestions: any[]) => {
    setIsApplyingAI(true);
    try {
      const promises = suggestions.map((s, idx) => {
        return supabase.from("trip_checklist").insert({
          trip_id: tripId,
          item: s.item,
          category: s.category || "outros",
          is_completed: false,
          order_index: items.length + idx,
        });
      });

      await Promise.all(promises);
      
      queryClient.invalidateQueries({ queryKey: ["trip-checklist", tripId] });
      toast({ title: "Sucesso", description: `${suggestions.length} itens adicionados ao checklist.` });
    } catch (error: any) {
      toast({ title: "Erro ao salvar", description: error.message, variant: "destructive" });
    } finally {
      setIsApplyingAI(false);
    }
  };

  // Agrupar por categoria
  const groupedItems = items.reduce((acc, item) => {
    const cat = item.category || "outros";
    if (!acc[cat]) acc[cat] = [];
    acc[cat].push(item);
    return acc;
  }, {} as Record<string, ChecklistItem[]>);

  // Calcular progresso
  const completedCount = items.filter((i) => i.is_completed).length;
  const progress = items.length > 0 ? (completedCount / items.length) * 100 : 0;

  // Estado vazio
  if (!isLoading && items.length === 0) {
    return (
      <div className="space-y-6">
        <EmptyState
          icon={ListChecks}
          title="Checklist vazio"
          description="Organize o que levar na viagem. Adicione itens manualmente ou deixe a IA sugerir com base no destino."
          action={
            <div className="flex items-center justify-center gap-3">
              <Button onClick={() => setShowDialog(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Adicionar item
              </Button>
              <AITripSuggestions
                type="checklist"
                destination={trip.destination || trip.name}
                startDate={trip.start_date}
                endDate={trip.end_date}
                onApply={handleApplyAISuggestions}
              />
            </div>
          }
        />

        <ChecklistDialog
          open={showDialog}
          onOpenChange={setShowDialog}
          isLoading={createItem.isPending}
          newItem={newItem}
          setNewItem={setNewItem}
          newCategory={newCategory}
          setNewCategory={setNewCategory}
          onSubmit={handleSubmit}
        />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header com progresso */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h2 className="text-sm uppercase tracking-widest text-muted-foreground font-medium">
            Checklist ({completedCount}/{items.length})
          </h2>
          <div className="flex items-center gap-2">
            <AITripSuggestions 
              type="checklist"
              destination={trip.destination || trip.name}
              startDate={trip.start_date}
              endDate={trip.end_date}
              onApply={handleApplyAISuggestions}
            />
            <Button variant="outline" size="sm" onClick={() => setShowDialog(true)}>
              <Plus className="h-4 w-4 mr-1" />
              Adicionar
            </Button>
          </div>
        </div>
        <div className="w-full bg-muted rounded-full h-2 overflow-hidden">
          <div
            className="h-full bg-positive transition-all rounded-full"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* Lista agrupada por categoria */}
      <div className="space-y-6">
        {Object.entries(groupedItems).map(([category, categoryItems]) => {
          const categoryLabel = CATEGORIES.find((c) => c.value === category)?.label || "Outros";
          return (
            <div key={category} className="space-y-2">
              <h3 className="font-medium text-sm text-muted-foreground">{categoryLabel}</h3>
              <div className="space-y-2">
                {categoryItems.map((item) => (
                  <div
                    key={item.id}
                    className={cn(
                      "flex items-center justify-between p-3 rounded-xl border transition-all duration-300",
                      item.is_completed 
                        ? "bg-muted/30 border-transparent opacity-70" 
                        : "bg-card/40 border-border/50 hover:bg-card/80 hover:shadow-sm"
                    )}
                  >
                    <div className="flex items-center gap-3 flex-1 min-w-0">
                      <Checkbox
                        checked={item.is_completed}
                        disabled={toggleItem.isPending && toggleItem.variables?.id === item.id}
                        className="rounded-full h-5 w-5 border-muted-foreground/30 data-[state=checked]:bg-positive data-[state=checked]:border-positive data-[state=checked]:text-white shadow-sm transition-all duration-300"
                        onCheckedChange={async (checked) => {
                          try {
                            await toggleItem.mutateAsync({ id: item.id, is_completed: !!checked });
                          } catch (err: any) {
                            toast.error(err.message || "Erro ao atualizar item");
                          }
                        }}
                      />
                      <span className={cn(
                        "text-sm font-medium transition-all duration-300 truncate",
                        item.is_completed ? "line-through text-muted-foreground" : "text-foreground"
                      )}>
                        {item.item}
                      </span>
                    </div>
                    <Button
                      variant="ghost"
                      size="icon"
                      disabled={deleteItem.isPending && deleteItem.variables === item.id}
                      onClick={async () => {
                        try {
                          await deleteItem.mutateAsync(item.id);
                        } catch (err: any) {
                          toast.error(err.message || "Erro ao excluir item");
                        }
                      }}
                      className="h-8 w-8 text-muted-foreground hover:text-destructive"
                    >
                      {deleteItem.isPending && deleteItem.variables === item.id ? (
                        <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                      ) : (
                        <Trash2 className="h-4 w-4" />
                      )}
                    </Button>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {/* Dialog */}
      <ChecklistDialog
        open={showDialog}
        onOpenChange={setShowDialog}
        isLoading={createItem.isPending}
        newItem={newItem}
        setNewItem={setNewItem}
        newCategory={newCategory}
        setNewCategory={setNewCategory}
        onSubmit={handleSubmit}
      />
    </div>
  );
}

// Dialog component
function ChecklistDialog({
  open,
  onOpenChange,
  isLoading,
  newItem,
  setNewItem,
  newCategory,
  setNewCategory,
  onSubmit,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  isLoading: boolean;
  newItem: string;
  setNewItem: (v: string) => void;
  newCategory: string;
  setNewCategory: (v: string) => void;
  onSubmit: () => void;
}) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-3xl !rounded-b-none sm:!rounded-3xl transition-transform duration-500 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-2xl flex flex-col overflow-hidden max-h-[90vh]">
        {/* Swipe handle */}
        <div className="w-full flex justify-center pt-4 sm:hidden shrink-0">
          <div className="w-12 h-1.5 bg-muted rounded-full" />
        </div>

        <DialogHeader className="px-6 shrink-0">
          <DialogTitle>Novo Item</DialogTitle>
          <DialogDescription>Adicione um item ao checklist</DialogDescription>
        </DialogHeader>

        {/* Conte├║do rol├ível */}
        <div className="flex-1 overflow-y-auto px-6">
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Item *</Label>
              <Input
                placeholder="Ex: Passaporte"
                value={newItem}
                onChange={(e) => setNewItem(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && onSubmit()}
                className="h-11"
              />
            </div>
            <div className="space-y-2">
              <Label>Categoria</Label>
              <Select value={newCategory} onValueChange={setNewCategory}>
                <SelectTrigger className="h-11">
                  <SelectValue placeholder="Selecione uma categoria" />
                </SelectTrigger>
                <SelectContent>
                  {CATEGORIES.map((cat) => (
                    <SelectItem key={cat.value} value={cat.value}>
                      {cat.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </div>

        {/* Rodap├® fixo */}
        <div className="shrink-0 flex gap-3 px-6 py-4 border-t border-border bg-background">
          <Button type="button" variant="outline" className="w-1/2 h-11" onClick={() => onOpenChange(false)}>
            Cancelar
          </Button>
          <Button className="w-1/2 h-11 font-bold" onClick={onSubmit} disabled={isLoading || !newItem.trim()}>
            {isLoading ? "Adicionando..." : "Adicionar"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

