import { UserAvatar } from "@/components/ui/user-avatar";

interface TripDetailHeaderProps {
  trip: any;
  permissions: any;
  participants?: any[];
  onBack: () => void;
  onEdit: () => void;
  onAddParticipant: () => void;
  onArchive: () => void;
  onUnarchive: () => void;
  onDelete: () => void;
  onOpenBudget: () => void;
  hasPersonalBudget: boolean;
  onExportPDF: () => void;
  onExportExcel: () => void;
}

export function TripDetailHeader({
  trip,
  permissions,
  participants,
  onBack,
  onEdit,
  onAddParticipant,
  onArchive,
  onUnarchive,
  onDelete,
  onOpenBudget,
  hasPersonalBudget,
  onExportPDF,
  onExportExcel,
}: TripDetailHeaderProps) {
