              {trip.destination && (
                <span className="flex items-center gap-2 font-medium">
                  <MapPin className="h-4 w-4 text-primary/70" />
                  {trip.destination}
                </span>
              )}
              <span className="flex items-center gap-2 font-medium">
                <Globe className="h-4 w-4 text-primary/70" />
                Moeda: <strong className="text-foreground">{trip.currency}</strong>
              </span>
              {currency !== "BRL" && (
                <span className="flex items-center gap-2 font-medium px-2.5 py-1 bg-card/60 backdrop-blur shadow-sm border border-border/50 rounded-lg">
                  {isRateLoading ? (
                    <RefreshCcw className="h-3.5 w-3.5 animate-spin text-muted-foreground" />
                  ) : realTimeRate ? (
                    <span className="font-mono text-sm font-bold text-foreground">
                      1 {currency} = R${" "}
                      {realTimeRate.toLocaleString("pt-BR", {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 3,
                      })}
                    </span>
                  ) : (
                    <span className="text-sm text-muted-foreground">Cota├º├úo indispon├¡vel</span>
                  )}
                </span>
              )}
              <span className="flex items-center gap-2 font-medium">
                <User className="h-4 w-4 text-primary/70" />
                {permissions?.isOwner ? "Propriet├írio" : "Colaborador"}
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-3 mt-4 md:mt-0">
          <Button
            variant={hasPersonalBudget ? "outline" : "default"}
            size="default"
            onClick={onOpenBudget}
            className={cn(
              "gap-2 rounded-2xl h-12 px-6 transition-all hover:-translate-y-1 font-bold",
              !hasPersonalBudget
                ? "shadow-xl shadow-primary/20 hover:shadow-primary/30"
                : "bg-card/50 backdrop-blur-sm"
            )}
          >
            <Coins className="h-5 w-5" />
            <span>{hasPersonalBudget ? "Meu Or├ºamento" : "Definir Or├ºamento"}</span>
          </Button>

          {permissions?.isOwner && (
            <>
              <Button
                variant="outline"
                size="default"
                onClick={onEdit}
                className="gap-2 rounded-2xl h-12 px-5 hover:bg-muted transition-all active:scale-95 bg-card/50 backdrop-blur-sm"
              >
                <Pencil className="h-4 w-4" />
                <span className="hidden sm:inline font-bold">Editar</span>
              </Button>

              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <Button
                    variant="outline"
                    size="icon"
                    className="rounded-2xl h-12 w-12 hover:bg-muted transition-all active:scale-95 bg-card/50 backdrop-blur-sm shadow-sm"
                  >
                    <MoreVertical className="h-5 w-5 text-muted-foreground" />
                  </Button>
                </DropdownMenuTrigger>
                <DropdownMenuContent
                  align="end"
                  className="w-56 rounded-xl p-2 shadow-xl border-border/50 backdrop-blur-sm"
                >
                  <DropdownMenuItem
                    onClick={onAddParticipant}
                    className="gap-3 rounded-lg py-2.5 cursor-pointer"
                  >
                    <Plus className="h-4 w-4 text-primary" />
                    <span>Adicionar participante</span>
                  </DropdownMenuItem>

                  <DropdownMenuSeparator className="my-1" />

                  <DropdownMenuItem
                    onClick={onExportPDF}
                    className="gap-3 rounded-lg py-2.5 cursor-pointer"
                  >
                    <FileDown className="h-4 w-4 text-success" />
                    <span>Exportar Relat├│rio PDF</span>
                  </DropdownMenuItem>

                  <DropdownMenuItem
                    onClick={onExportExcel}
                    className="gap-3 rounded-lg py-2.5 cursor-pointer"
                  >
                    <Download className="h-4 w-4 text-success" />
                    <span>Exportar Planilha Excel</span>
                  </DropdownMenuItem>

                  <DropdownMenuSeparator className="my-1" />

                  {trip.is_archived ? (
                    <DropdownMenuItem
                      onClick={onUnarchive}
                      className="gap-3 rounded-lg py-2.5 cursor-pointer"
                    >
                      <ArchiveRestore className="h-4 w-4 text-primary" />
                      <span>Desarquivar viagem</span>
                    </DropdownMenuItem>
                  ) : (
                    <DropdownMenuItem
                      onClick={onArchive}
                      className="gap-3 rounded-lg py-2.5 cursor-pointer"
                    >
                      <Archive className="h-4 w-4 text-muted-foreground" />
                      <span>Arquivar viagem</span>
                    </DropdownMenuItem>
                  )}

                  <DropdownMenuSeparator className="my-1" />

                  <DropdownMenuItem
                    onClick={onDelete}
                    className="gap-3 rounded-lg py-2.5 cursor-pointer text-destructive focus:text-destructive focus:bg-destructive/10"
                  >
                    <Trash2 className="h-4 w-4" />
                    <span>Excluir viagem</span>
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { TrendingUp, DollarSign, ShoppingCart, Plane, Route, ListChecks } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { TripDetailHeader } from "@/components/trips/TripDetailHeader";
import { TripDetailSummary } from "@/components/trips/TripDetailSummary";
import { TripSummaryTab } from "@/components/trips/TripSummaryTab";
import { TripExpensesTab } from "@/components/trips/TripExpensesTab";
import { TripShopping } from "@/components/trips/TripShopping";
import { TripExchange } from "@/components/trips/TripExchange";
import { TripItinerary } from "@/components/trips/TripItinerary";
import { TripChecklist } from "@/components/trips/TripChecklist";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";

interface TripDetailViewProps {
  trip: any;
  permissions: any;
  participants: any[];
  tripTransactions: any[];
  tripFinancialSummary: any;
  user: any;
  activeTab: string;
  setActiveTab: (tab: any) => void;
  myPersonalBudget: number | null;
  balances: any[];
  onBack: () => void;
  onEdit: () => void;
  onAddParticipant: () => void;
  onArchive: () => void;
  onUnarchive: () => void;
  onDelete: () => void;
  onOpenBudget: () => void;
  onUpdateTrip: (updates: any) => Promise<void>;
  formatCurrency: (val: number, cur?: string) => string;
  onExportPDF: () => void;
  onExportExcel: () => void;
  onRemoveParticipantClick?: (participant: any, balance: any) => void;
  pendingInvitations?: any[];
  onCancelInvitation?: (id: string) => void;
}

export function TripDetailView({
  trip,
  permissions,
  participants,
  tripTransactions,
  tripFinancialSummary,
  user,
  activeTab,
  setActiveTab,
  myPersonalBudget,
  balances,
  onBack,
  onEdit,
  onAddParticipant,
  onArchive,
  onUnarchive,
  onDelete,
  onOpenBudget,
  onUpdateTrip,
  formatCurrency,
  onExportPDF,
  onExportExcel,
  onRemoveParticipantClick,
  pendingInvitations,
  onCancelInvitation,
}: TripDetailViewProps) {
  const relevantTransactions = tripTransactions.filter(
    (t) =>
      t.type === "EXPENSE" &&
      (t.is_shared || t.creator_user_id === user?.id || t.user_id === user?.id)
  );
  const totalExpenses = relevantTransactions.reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  // IMPACTO REAL NO OR├çAMENTO (Accrual Basis - Regime de Compet├¬ncia):
  // 1. Gastos individuais (s├│ meus)
  const myIndividualExpenses = tripTransactions
    .filter(
      (t) =>
        t.type === "EXPENSE" &&
        !t.is_shared &&
        (t.creator_user_id === user?.id || t.user_id === user?.id)
    )
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  // 2. Minha parte nos gastos compartilhados (mesmo que eu n├úo tenha pago)
  const myShareOfShared = tripTransactions
    .filter((t) => t.type === "EXPENSE" && t.is_shared)
    .reduce((sum, t) => {
      if (!t.transaction_splits) return sum;
      const mySplit = t.transaction_splits.find((s: any) => s.user_id === user?.id);
      return sum + (mySplit ? Number(mySplit.amount) : 0);
    }, 0);

  // myTotalSpent = o impacto real no meu or├ºamento, independente de quem j├í pagou
  const myTotalSpent = myIndividualExpenses + myShareOfShared;

  return (
    <div className="space-y-6 animate-fade-in pb-20">
      <TripDetailHeader
        trip={trip}
        permissions={permissions}
        participants={participants}
        onBack={onBack}
        onEdit={onEdit}
        onAddParticipant={onAddParticipant}
        onArchive={onArchive}
        onUnarchive={onUnarchive}
        onDelete={onDelete}
        onOpenBudget={onOpenBudget}
        hasPersonalBudget={!!myPersonalBudget}
        onExportPDF={onExportPDF}
        onExportExcel={onExportExcel}
      />
      <TripDetailSummary
        totalExpenses={totalExpenses}
        myTotalSpent={myTotalSpent}
        myPersonalBudget={myPersonalBudget}
        startDate={trip.start_date}
        endDate={trip.end_date}
        currency={trip.currency}
        formatCurrency={formatCurrency}
      />

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <div className="mb-6 relative">
          <TabsList className="w-full h-auto flex overflow-x-auto snap-x hide-scrollbar bg-card/60 backdrop-blur-md rounded-3xl shadow-inner border border-border/40 p-2 gap-2 justify-start relative z-10">
            <TabsTrigger
              value="summary"
              className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
            >
              <div className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4" />
                <span className="font-bold uppercase tracking-widest text-sm">Resumo</span>
              </div>
            </TabsTrigger>
            <TabsTrigger
              value="expenses"
              className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
            >
              <div className="flex items-center gap-2">
                <DollarSign className="h-4 w-4" />
                <span className="font-bold uppercase tracking-widest text-sm">Gastos</span>
              </div>
            </TabsTrigger>
            <TabsTrigger
              value="shopping"
              className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
            >
              <div className="flex items-center gap-2">
                <ShoppingCart className="h-4 w-4" />
                <span className="font-bold uppercase tracking-widest text-sm">Compras</span>
              </div>
            </TabsTrigger>
            {trip.currency !== "BRL" && (
              <TabsTrigger
                value="exchange"
                className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
              >
                <div className="flex items-center gap-2">
                  <Plane className="h-4 w-4" />
                  <span className="font-bold uppercase tracking-widest text-sm">C├ómbio</span>
                </div>
              </TabsTrigger>
            )}
            <TabsTrigger
              value="itinerary"
              className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
            >
              <div className="flex items-center gap-2">
                <Route className="h-4 w-4" />
                <span className="font-bold uppercase tracking-widest text-sm">Roteiro</span>
              </div>
            </TabsTrigger>
            <TabsTrigger
              value="checklist"
              className="shrink-0 snap-start rounded-xl py-3 px-5 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground data-[state=active]:shadow-lg data-[state=active]:shadow-primary/30 transition-all duration-300 hover:bg-muted/50"
            >
              <div className="flex items-center gap-2">
                <ListChecks className="h-4 w-4" />
                <span className="font-bold uppercase tracking-widest text-sm">Checklist</span>
              </div>
            </TabsTrigger>
          </TabsList>

          {/* Sombra para indicar scroll no mobile */}
          <div className="absolute right-0 top-0 bottom-0 w-12 bg-gradient-to-l from-background to-transparent pointer-events-none md:hidden z-20" />
        </div>

        <TabsContent value="summary">
          <TripSummaryTab
            selectedTrip={trip}
            totalExpenses={totalExpenses}
            myTotalSpent={myTotalSpent}
            myPersonalBudget={myPersonalBudget}
            participants={participants}
            balances={balances}
            tripTransactions={tripTransactions}
            tripFinancialSummary={tripFinancialSummary}
            user={user}
            onAddParticipant={onAddParticipant}
            permissions={permissions}
            dateFns={dateFns}
            ptBR={ptBR}
            onRemoveClick={onRemoveParticipantClick}
            pendingInvitations={pendingInvitations}
            onCancelInvitation={onCancelInvitation}
            setActiveTab={setActiveTab}
          />
        </TabsContent>
        <TabsContent value="expenses">
          <TripExpensesTab
            tripTransactions={tripTransactions}
            participants={participants}
            selectedTrip={trip}
            user={user}
            formatCurrency={formatCurrency}
            balances={balances}
            myTotalSpent={myTotalSpent}
          />
        </TabsContent>
        <TabsContent value="shopping">
          <TripShopping trip={trip} onUpdateTrip={onUpdateTrip} isUpdating={false} />
        </TabsContent>
        {trip.currency !== "BRL" && (
          <TabsContent value="exchange">
            <TripExchange trip={trip} totalExpenses={totalExpenses} />
          </TabsContent>
        )}
        <TabsContent value="itinerary">
          <TripItinerary trip={trip} />
        </TabsContent>
        <TabsContent value="checklist">
          <TripChecklist trip={trip} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from "react";
import {
  DollarSign,
  Tag,
  Calendar,
  Users,
  User,
  CheckCircle,
  Clock,
  ArrowRight,
  ExternalLink,
  ChevronDown,
  ChevronUp,
} from "lucide-react";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { useNavigate } from "react-router-dom";
import { useUserProfile } from "@/hooks/useUserProfile";
import { useCurrencyRate } from "@/hooks/useCurrencyRate";
import { UserAvatar } from "@/components/ui/user-avatar";
import { useTransactionModal } from "@/contexts/TransactionModalContext";
import { Plus } from "lucide-react";
import { EmptyState } from "@/components/ui/empty-state";
import { moneyUtils } from "@/utils/money";

interface TripExpensesTabProps {
  tripTransactions: any[];
  participants: any[];
  selectedTrip: any;
  user: any;
  formatCurrency: (value: number, currency: string) => string;
  balances?: any[];
  myTotalSpent?: number;
}

export function TripExpensesTab({
  tripTransactions,
  participants,
  selectedTrip,
  user,
  formatCurrency,
  balances = [],
  myTotalSpent,
}: TripExpensesTabProps) {
  const [isSharedExpanded, setIsSharedExpanded] = useState(false);
  const [isPersonalExpanded, setIsPersonalExpanded] = useState(false);
  const navigate = useNavigate();
  const currency = selectedTrip.currency || "BRL";

  const { data: profile } = useUserProfile();
  const { setShowTransactionModal } = useTransactionModal();
  const baseCurrency = profile?.base_currency || "BRL";
  const isInternational = currency !== baseCurrency;
  const { data: rate } = useCurrencyRate(isInternational ? currency : "", baseCurrency);

  // ===== SEPARA├ç├âO CLARA DE DESPESAS =====
  // Compartilhadas: qualquer participante pode ter pago
  const sharedExpenses = tripTransactions.filter((t) => t.type === "EXPENSE" && t.is_shared);

  // Pessoais: apenas minhas, n├úo compartilhadas e que n├úo sejam acertos financeiros (para evitar poluir a viagem e duplicar or├ºamento)
  const personalExpenses = tripTransactions.filter((t) => {
    const isMineAndNotShared =
      (t.type === "EXPENSE" || t.type === "INCOME") &&
      !t.is_shared &&
      (t.creator_user_id === user?.id || t.user_id === user?.id);
    const isSettlement =
      t.description?.toLowerCase().includes("acerto") ||
      t.description?.toLowerCase().includes("compensa├º├úo");
    return isMineAndNotShared && !isSettlement;
  });

  const myBalance = balances.find((b) => b.participantId === user?.id);
  const myShareOfShared = myBalance?.owes || 0;

  // Totais
  const totalShared = sharedExpenses.reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
  const totalPersonalOnly = personalExpenses.reduce(
    (sum, t) => sum + (t.type === "INCOME" ? -Number(t.amount) : Number(t.amount)),
    0
  );
  const totalPersonal = totalPersonalOnly + myShareOfShared;
  const spentToDisplay = myTotalSpent !== undefined ? myTotalSpent : totalPersonal;
  const mySharedPaid = sharedExpenses
    .filter((t) => t.creator_user_id === user?.id || t.user_id === user?.id)
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  const getParticipantName = (userId: string) => {
    if (userId === user?.id) return "Voc├¬";
    const p = participants.find((p) => p.user_id === userId);
    return p?.name || "Participante";
  };

  const getSettlementStatus = (expense: any) => {
    // Se a transa├º├úo tem splits, verificar se foram acertados
    if (!expense.transaction_splits || expense.transaction_splits.length === 0) {
      return "no_splits";
    }
    const allSettled = expense.transaction_splits.every((s: any) => s.is_settled);
    const anySettled = expense.transaction_splits.some((s: any) => s.is_settled);

    // Check if waiting for confirmation (one side settled, the other didn't)
    const waitingConfirmation = expense.transaction_splits.some(
      (s: any) =>
        (s.settled_by_debtor && !s.settled_by_creditor) ||
        (!s.settled_by_debtor && s.settled_by_creditor)
    );

    if (allSettled) return "settled";
    if (waitingConfirmation) return "waiting";
    if (anySettled) return "partial";
    return "pending";
  };

  return (
    <div className="space-y-8 mt-6 animate-fade-in">
      {/* ===== RESUMO R├üPIDO ===== */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="p-4 rounded-2xl border border-accent/20 bg-accent/5 text-center">
          <p className="text-sm font-bold uppercase tracking-widest text-accent mb-1">
            Total Compartilhado
          </p>
          <p className="font-mono font-black text-base text-foreground">
            {formatCurrency(totalShared, currency)}
          </p>
          {isInternational && rate && (
            <p className="text-sm font-mono text-muted-foreground font-medium mt-0.5">
              Ôëê {formatCurrency(moneyUtils.mul(totalShared, rate), baseCurrency)}
            </p>
          )}
          <p className="text-sm text-muted-foreground mt-0.5">{sharedExpenses.length} despesas</p>
        </div>
        <div className="p-4 rounded-2xl border border-accent/20 bg-accent/5 text-center">
          <p className="text-sm font-bold uppercase tracking-widest text-accent mb-1">
            Eu Paguei (Compartilhado)
          </p>
          <p className="font-mono font-black text-base text-foreground">
            {formatCurrency(mySharedPaid, currency)}
          </p>
          {isInternational && rate && (
            <p className="text-sm font-mono text-muted-foreground font-medium mt-0.5">
              Ôëê {formatCurrency(moneyUtils.mul(mySharedPaid, rate), baseCurrency)}
            </p>
          )}
          <p className="text-sm text-muted-foreground mt-0.5">impacto no or├ºamento</p>
        </div>
        <div className="p-4 rounded-2xl border border-border/50 bg-card/50 text-center">
          <p className="text-sm font-bold uppercase tracking-widest text-muted-foreground mb-1">
            Meu Gasto (Or├ºamento)
          </p>
          <p className="font-mono font-black text-base text-foreground">
            {formatCurrency(spentToDisplay, currency)}
          </p>
          {isInternational && rate && (
            <p className="text-sm font-mono text-muted-foreground font-medium mt-0.5">
              Ôëê {formatCurrency(moneyUtils.mul(spentToDisplay, rate), baseCurrency)}
            </p>
          )}
          <p className="text-sm text-muted-foreground mt-0.5">
            {myTotalSpent !== undefined
              ? "Impacto real no seu or├ºamento"
              : `${personalExpenses.length} privadas + sua parte (${formatCurrency(myShareOfShared, currency)})`}
          </p>
        </div>
      </div>

      {/* ===== SE├ç├âO: DESPESAS COMPARTILHADAS ===== */}
      <section className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Users className="h-4 w-4 text-accent" />
            <h2 className="text-sm uppercase tracking-widest text-muted-foreground font-bold">
              Despesas Compartilhadas ({sharedExpenses.length})
            </h2>
          </div>
          {sharedExpenses.length > 0 && (
            <Button
              variant="ghost"
              size="sm"
              className="h-7 gap-2 text-sm text-accent hover:text-accent/92 hover:bg-accent/10"
              onClick={() => navigate("/compartilhados?tab=TRAVEL")}
            >
              Ir para Acertos <ExternalLink className="h-3 w-3" />
            </Button>
          )}
        </div>

        {/* Aviso sobre a l├│gica de or├ºamento */}
        {mySharedPaid > 0 && (
          <div className="flex items-start gap-3 p-3 rounded-xl border border-warning/20 bg-warning/8 dark:bg-warning/12 text-sm text-warning dark:text-warning">
            <span className="text-base shrink-0">­ƒÆí</span>
            <span>
              <strong>Como funciona o or├ºamento:</strong> Quando voc├¬ paga uma despesa
              compartilhada, o valor integral baixa do seu or├ºamento. Ao acertar nos{" "}
