                                    {formatCurrency(amount, currency)}
                                  </p>
                                  {isInternational && rate && (
                                    <p className="font-mono text-sm text-muted-foreground font-medium mt-0.5">
                                      Ôëê {formatCurrency(moneyUtils.mul(amount, rate), baseCurrency)}
                                    </p>
                                  )}
                                  <p className="text-sm text-muted-foreground mt-0.5">
                                    valor total pago
                                  </p>
                                  {expense.transaction_splits && (
                                    <p className="text-sm text-accent font-bold mt-1">
                                      Sua parte: {formatCurrency(mySplitAmount, currency)}
                                    </p>
                                  )}
                                </>
                              ) : (
                                <>
                                  <p className="font-mono font-black text-base sm:text-base text-warning tracking-tight tabular-nums">
                                    {formatCurrency(mySplitAmount, currency)}
                                  </p>
                                  {isInternational && rate && (
                                    <p className="font-mono text-sm text-warning/70 dark:text-warning/70 font-medium mt-0.5">
                                      Ôëê {formatCurrency(moneyUtils.mul(mySplitAmount, rate), baseCurrency)}
                                    </p>
                                  )}
                                  <p className="text-sm text-warning/70 dark:text-warning/70 mt-0.5 font-bold uppercase tracking-widest">
                                    Sua parte
                                  </p>
                                  <p className="text-sm text-muted-foreground mt-1.5">
                                    Total: {formatCurrency(amount, currency)}
                                  </p>
                                </>
                              )}
                            </div>
                          </div>
                        );
                      })()}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ) : (
          <EmptyState
            icon={Users}
            title="Nenhuma despesa compartilhada"
            description="Despesas marcadas como compartilhadas aparecer├úo aqui."
            action={
              <Button
                size="sm"
                onClick={() => setShowTransactionModal(true, { tripId: selectedTrip.id })}
                className="bg-accent hover:bg-accent/90"
              >
                <Plus className="h-4 w-4 mr-2" /> Lan├ºar Despesa
              </Button>
            }
          />
        )}
      </section>

      {/* ===== DIVISOR ===== */}
      {personalExpenses.length > 0 && sharedExpenses.length > 0 && (
        <div className="relative">
          <div className="absolute inset-0 flex items-center">
            <span className="w-full border-t border-border/40" />
          </div>
          <div className="relative flex justify-center">
            <span className="bg-background px-3 text-sm text-muted-foreground uppercase tracking-widest font-bold">
              Gastos Pessoais
            </span>
          </div>
        </div>
      )}

      {/* ===== SE├ç├âO: DESPESAS PESSOAIS ===== */}
      <section className="space-y-4">
        {personalExpenses.length === 0 && sharedExpenses.length === 0 ? (
          <EmptyState
            icon={User}
            title="Nenhuma despesa pessoal"
            description="Seus gastos privados na viagem aparecer├úo aqui."
            action={
              <Button
                size="sm"
                variant="outline"
                onClick={() => setShowTransactionModal(true, { tripId: selectedTrip.id })}
              >
                <Plus className="h-4 w-4 mr-2" /> Lan├ºar Despesa
              </Button>
            }
          />
        ) : personalExpenses.length > 0 ? (
          <>
            {sharedExpenses.length === 0 && (
              <div className="flex items-center gap-2">
                <User className="h-4 w-4 text-accent" />
                <h2 className="text-sm uppercase tracking-widest text-muted-foreground font-bold">
                  Gastos Pessoais ({personalExpenses.length})
                </h2>
              </div>
            )}
            <div className="border border-border rounded-2xl overflow-hidden bg-card/20">
              <button
                onClick={() => setIsPersonalExpanded(!isPersonalExpanded)}
                className="w-full flex items-center justify-between p-4 bg-muted/10 hover:bg-muted/30 transition-colors"
              >
                <div className="flex items-center gap-2">
                  <span className="text-sm font-semibold">
                    Ver {personalExpenses.length}{" "}
                    {personalExpenses.length === 1 ? "despesa pessoal" : "despesas pessoais"}
                  </span>
                </div>
                {isPersonalExpanded ? (
                  <ChevronUp className="h-4 w-4 text-muted-foreground" />
                ) : (
                  <ChevronDown className="h-4 w-4 text-muted-foreground" />
                )}
              </button>

              {isPersonalExpanded && (
                <div className="p-3 grid gap-3 border-t border-border animate-in slide-in-from-top-2 fade-in duration-300">
                  {personalExpenses.map((expense) => {
                    const categoryIcon = expense.category?.icon || "­ƒÆ©";
                    const categoryName = expense.category?.name || "Sem categoria";
                    const amount = Number(expense.amount);

                    return (
                      <div
                        key={expense.id}
                        onClick={(e) => {
                          const target = e.target as HTMLElement;
                          if (target.closest("button")) return;
                          window.dispatchEvent(
                            new CustomEvent("openTransactionModal", {
                              detail: { transaction: expense },
                            })
                          );
                        }}
                        className="group p-4 rounded-2xl border border-border/50 bg-card/50 hover:bg-card hover:border-primary/20 hover:shadow-lg hover:shadow-primary/5 transition-all duration-300 flex items-center justify-between gap-4 cursor-pointer"
                      >
                        <div className="flex items-center gap-3.5 flex-1 min-w-0">
                          <div className="w-12 h-12 rounded-xl bg-muted group-hover:bg-primary/10 flex items-center justify-center text-base shrink-0 transition-colors duration-300">
                            {categoryIcon}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap mb-1">
                              <p className="font-bold text-foreground truncate group-hover:text-primary transition-colors">
                                {expense.description}
                              </p>
                              <span
                                className={cn(
                                  "text-[9px] px-2 py-0.5 rounded-full uppercase tracking-widest font-bold",
                                  expense.type === "INCOME"
                                    ? "bg-success/12 text-success dark:text-success"
                                    : "bg-accent/10 text-accent"
                                )}
                              >
                                {expense.type === "INCOME" ? "Recebimento" : "Pessoal"}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                              <span className="flex items-center gap-2 px-2 py-0.5 rounded-full bg-primary/10 text-primary text-sm font-bold uppercase tracking-widest border border-primary/20">
                                <Tag className="h-2.5 w-2.5" />
                                {categoryName}
                              </span>
                              <span className="text-muted-foreground/30">ÔÇó</span>
                              <span className="flex items-center gap-1">
                                <Calendar className="h-3 w-3 text-muted-foreground/60" />
                                {dateFns.format(new Date(expense.date), "dd MMM yyyy", {
                                  locale: ptBR,
                                })}
                              </span>
                            </div>
                          </div>
                        </div>
                        <div className="text-right shrink-0">
                          <p
                            className={cn(
                              "font-mono font-black text-base sm:text-lg tracking-tight tabular-nums",
                              expense.type === "INCOME"
                                ? "text-success dark:text-success"
                                : "text-foreground"
                            )}
                          >
                            {expense.type === "INCOME" ? "+" : ""}
                            {formatCurrency(amount, currency)}
                          </p>
                          {isInternational && rate && (
                            <p
                              className={cn(
                                "font-mono text-xs font-medium mt-0.5",
                                expense.type === "INCOME"
                                  ? "text-success/70 dark:text-success/70"
                                  : "text-muted-foreground"
                              )}
                            >
                              Ôëê {formatCurrency(moneyUtils.mul(amount, rate), baseCurrency)}
                            </p>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          </>
        ) : null}
      </section>
    </div>
  );
}

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { Clock, ExternalLink, MapPin, Pencil, Plus, Route, Search, Trash2 } from "lucide-react";
import { useState } from "react";

interface ItineraryItem {
  id: string;
  trip_id: string;
  date: string;
  title: string;
  description: string | null;
  location: string | null;
  start_time: string | null;
  end_time: string | null;
  order_index: number;
  created_at: string;
}

import { EmptyState } from "@/components/ui/empty-state";
import { AITripSuggestions } from "./AITripSuggestions";

interface TripItineraryProps {
  trip: any;
}

export function TripItinerary({ trip }: TripItineraryProps) {
  const tripId = trip.id;
  const [showDialog, setShowDialog] = useState(false);
  const [editingItem, setEditingItem] = useState<ItineraryItem | null>(null);
  const [deletingItem, setDeletingItem] = useState<ItineraryItem | null>(null);
  const [isApplyingAI, setIsApplyingAI] = useState(false);

  // Form state
  const [date, setDate] = useState("");
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [location, setLocation] = useState("");
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [mapsUrl, setMapsUrl] = useState("");

  const queryClient = useQueryClient();
  const { toast } = useToast();

  // Helper: extrai metadados embedados no description (mapsUrl, rating)
  const parseMeta = (
    desc: string | null
  ): { text: string; mapsUrl: string; rating: number | null } => {
    if (!desc) return { text: "", mapsUrl: "", rating: null };
    const match = desc.match(/<!--meta:(.+?)-->/);
    if (!match) return { text: desc, mapsUrl: "", rating: null };
    try {
      const meta = JSON.parse(match[1]);
      return {
        text: desc.replace(/<!--meta:.+?-->/, "").trim(),
        mapsUrl: meta.mapsUrl || "",
        rating: meta.rating || null,
      };
    } catch {
      return { text: desc.replace(/<!--meta:.+?-->/, "").trim(), mapsUrl: "", rating: null };
    }
  };

  // Fetch itinerary items
  const { data: items = [], isLoading } = useQuery({
    queryKey: ["trip-itinerary", tripId],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("trip_itinerary")
        .select("*")
        .eq("trip_id", tripId)
        .order("date", { ascending: true })
        .order("start_time", { ascending: true });

      if (error) throw error;
      return data as ItineraryItem[];
    },
  });

  // Create mutation
  const createItem = useMutation({
    mutationFn: async (item: Omit<ItineraryItem, "id" | "created_at">) => {
      const { data, error } = await supabase.from("trip_itinerary").insert(item).select().single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-itinerary", tripId] });
      toast({ title: "Atividade adicionada" });
      resetForm();
      setShowDialog(false);
    },
    onError: (error) => {
      toast({ title: "Erro ao adicionar", description: error.message, variant: "destructive" });
    },
  });

  // Update mutation
  const updateItem = useMutation({
    mutationFn: async ({ id, ...item }: Partial<ItineraryItem> & { id: string }) => {
      const { data, error } = await supabase
        .from("trip_itinerary")
        .update(item)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-itinerary", tripId] });
      toast({ title: "Atividade atualizada" });
      resetForm();
      setShowDialog(false);
      setEditingItem(null);
    },
    onError: (error) => {
      toast({ title: "Erro ao atualizar", description: error.message, variant: "destructive" });
    },
  });

  // Delete mutation
  const deleteItem = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("trip_itinerary").delete().eq("id", id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trip-itinerary", tripId] });
      toast({ title: "Atividade removida" });
      setDeletingItem(null);
    },
    onError: (error) => {
      toast({ title: "Erro ao remover", description: error.message, variant: "destructive" });
    },
  });

  const handleApplyAISuggestions = async (suggestions: any[]) => {
    setIsApplyingAI(true);
    const startDate = trip.start_date || dateFns.format(new Date(), "yyyy-MM-dd");

    try {
      const promises = suggestions.map((s, idx) => {
        // Embed mapsUrl and rating as JSON metadata in description
        const metadata = JSON.stringify({ mapsUrl: s.mapsUrl || "", rating: s.rating || null });
        const fullDescription = s.description
          ? `${s.description}\n<!--meta:${metadata}-->`
          : `<!--meta:${metadata}-->`;

        return supabase.from("trip_itinerary").insert({
          trip_id: tripId,
          date: startDate,
          title: s.title,
          description: fullDescription,
          location: s.location,
          start_time: null,
          end_time: null,
          order_index: items.length + idx,
        });
      });

      await Promise.all(promises);

      queryClient.invalidateQueries({ queryKey: ["trip-itinerary", tripId] });
      toast({
        title: "Sucesso",
        description: `${suggestions.length} atividades adicionadas no 1┬║ dia.`,
      });
    } catch (error: any) {
      toast({ title: "Erro ao salvar", description: error.message, variant: "destructive" });
    } finally {
      setIsApplyingAI(false);
    }
  };

  const resetForm = () => {
    setDate("");
    setTitle("");
    setDescription("");
    setLocation("");
    setStartTime("");
    setEndTime("");
    setMapsUrl("");
  };

  const handleOpenDialog = (item?: ItineraryItem) => {
    if (item) {
      setEditingItem(item);
      setDate(item.date);
      setTitle(item.title);
      const meta = parseMeta(item.description);
      setDescription(meta.text);
      setLocation(item.location || "");
      setStartTime(item.start_time || "");
      setEndTime(item.end_time || "");
      setMapsUrl(meta.mapsUrl || "");
    } else {
      setEditingItem(null);
      resetForm();
    }
    setShowDialog(true);
  };

  const handleSubmit = () => {
    if (!date || !title) return;

    // Embute mapsUrl nos metadados da descri├º├úo
    const metadata = JSON.stringify({ mapsUrl: mapsUrl || "", rating: null });
    const fullDescription = description
      ? `${description}\n<!--meta:${metadata}-->`
      : `<!--meta:${metadata}-->`;

    const itemData = {
      trip_id: tripId,
      date,
      title,
      description: fullDescription,
      location: location || null,
      start_time: startTime || null,
      end_time: endTime || null,
      order_index: items.length,
    };

    if (editingItem) {
      updateItem.mutate({ id: editingItem.id, ...itemData });
    } else {
      createItem.mutate(itemData);
    }
  };

  // Agrupar por data
  const groupedItems = items.reduce(
    (acc, item) => {
      const dateKey = item.date;
      if (!acc[dateKey]) acc[dateKey] = [];
      acc[dateKey].push(item);
      return acc;
    },
    {} as Record<string, ItineraryItem[]>
  );

  // Estado vazio
  if (!isLoading && items.length === 0) {
    return (
      <div className="space-y-6">
        <EmptyState
          icon={Route}
          title="Roteiro vazio"
          description="Adicione atividades e passeios para organizar os dias da viagem."
          action={
            <div className="flex items-center justify-center gap-3">
              <Button onClick={() => handleOpenDialog()}>
                <Plus className="h-4 w-4 mr-2" />
                Adicionar atividade
              </Button>
              <AITripSuggestions
                type="itinerary"
                destination={trip.destination || trip.name}
                onApply={handleApplyAISuggestions}
              />
            </div>
          }
        />

        <ItineraryDialog
          open={showDialog}
          onOpenChange={setShowDialog}
          isEditing={!!editingItem}
          isLoading={createItem.isPending || updateItem.isPending}
          date={date} setDate={setDate}
          title={title} setTitle={setTitle}
          description={description} setDescription={setDescription}
          location={location} setLocation={setLocation}
          startTime={startTime} setStartTime={setStartTime}
          endTime={endTime} setEndTime={setEndTime}
          mapsUrl={mapsUrl} setMapsUrl={setMapsUrl}
          onSubmit={handleSubmit}
        />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className="text-sm uppercase tracking-widest text-muted-foreground font-medium">
          Roteiro ({items.length} atividades)
        </h2>
        <div className="flex items-center gap-2">
          <AITripSuggestions
            type="itinerary"
            destination={trip.destination || trip.name}
            onApply={handleApplyAISuggestions}
          />
          <Button variant="outline" size="sm" onClick={() => handleOpenDialog()}>
            <Plus className="h-4 w-4 mr-1" />
            Adicionar
          </Button>
        </div>
      </div>

      {/* Lista agrupada por data */}
      <div className="space-y-6">
        {Object.entries(groupedItems).map(([dateKey, dayItems]) => (
          <div key={dateKey} className="space-y-3">
            <h3 className="text-sm font-semibold capitalize text-foreground">
              {dateFns.format(new Date(dateKey + 'T12:00:00'), "EEEE, dd 'de' MMMM", { locale: ptBR })}
            </h3>
            <div className="space-y-2">
              {dayItems.map((item) => {
                const meta = parseMeta(item.description);
                return (
                  <div
                    key={item.id}
                    className="flex items-start justify-between p-4 rounded-xl border border-border hover:border-foreground/20 transition-colors"
                  >
                    <div className="flex-1">
                      <div className="flex items-center gap-2">
                        {item.start_time && (
                          <span className="text-sm text-muted-foreground flex items-center gap-1">
                            <Clock className="h-3 w-3" />
                            {item.start_time.slice(0, 5)}
                            {item.end_time && ` - ${item.end_time.slice(0, 5)}`}
                          </span>
                        )}
                      </div>
                      <p className="font-medium mt-1">{item.title}</p>
                      {item.location && (
                        <p className="text-sm text-muted-foreground flex items-center gap-1 mt-1">
                          <MapPin className="h-3 w-3" />
                          {item.location}
                        </p>
                      )}
                      {meta.text && (
                        <p className="text-sm text-muted-foreground mt-2">{meta.text}</p>
                      )}
                      <div className="flex gap-1 mt-2">
                        <a
                          href={(() => {
                            if (meta.mapsUrl) return meta.mapsUrl;
                            const query = encodeURIComponent((item.location || item.title) + (trip.destination ? ", " + trip.destination : ""));
                            return `https://www.google.com/maps/search/?api=1&query=${query}`;
                          })()}
                          onClick={(e) => {
                            const query = encodeURIComponent((item.location || item.title) + (trip.destination ? ", " + trip.destination : ""));
                            const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
                            if (isIOS) {
                              e.preventDefault();
                              // Tenta abrir o app do Google Maps; fallback para web
                              window.location.href = `comgooglemaps://?q=${query}`;
                              setTimeout(() => {
                                window.open(`https://www.google.com/maps/search/?api=1&query=${query}`, '_blank');
                              }, 500);
                            }
                          }}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="inline-flex items-center gap-1 text-[10px] font-medium px-2 py-1 rounded-md bg-blue-50 text-blue-600 hover:bg-blue-100 dark:bg-blue-950 dark:text-blue-400 dark:hover:bg-blue-900 transition-colors"
                          title="Abrir no Google Maps"
                        >
                          <MapPin className="h-3 w-3" />
                          Maps{meta.mapsUrl ? " Ô£ô" : ""}
                        </a>
                        {meta.rating && (
                          <span className="inline-flex items-center gap-0.5 text-[10px] font-bold px-1.5 py-1 rounded-md bg-yellow-50 text-yellow-700 dark:bg-yellow-950 dark:text-yellow-400">
                            Ô¡É {meta.rating}
                          </span>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-1">
                      <Button variant="ghost" size="icon" onClick={() => handleOpenDialog(item)}>
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => setDeletingItem(item)}
                        className="text-destructive hover:text-destructive"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      {/* Dialog */}
      <ItineraryDialog
        open={showDialog}
        onOpenChange={setShowDialog}
        isEditing={!!editingItem}
        isLoading={createItem.isPending || updateItem.isPending}
        date={date} setDate={setDate}
        title={title} setTitle={setTitle}
        description={description} setDescription={setDescription}
        location={location} setLocation={setLocation}
        startTime={startTime} setStartTime={setStartTime}
        endTime={endTime} setEndTime={setEndTime}
        mapsUrl={mapsUrl} setMapsUrl={setMapsUrl}
        onSubmit={handleSubmit}
      />

      {/* Delete confirmation */}
      <AlertDialog open={!!deletingItem} onOpenChange={() => setDeletingItem(null)}>
        <AlertDialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-2xl !rounded-b-none sm:!rounded-b-2xl p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden">
          <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
            <div className="w-12 h-2 bg-muted rounded-full" />
          </div>
          <AlertDialogHeader className="px-6 pt-2 pb-2 text-left">
            <AlertDialogTitle>Excluir atividade?</AlertDialogTitle>
            <AlertDialogDescription>Esta a├º├úo n├úo pode ser desfeita.</AlertDialogDescription>
          </AlertDialogHeader>
          <div className="px-6 py-4 flex gap-3 justify-end border-t border-border/50">
            <AlertDialogCancel className="rounded-xl h-11">Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deletingItem && deleteItem.mutate(deletingItem.id)}
              className="rounded-xl h-11 bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Excluir
            </AlertDialogAction>
          </div>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

// Dialog component
function ItineraryDialog({
  open, onOpenChange, isEditing, isLoading,
  date, setDate, title, setTitle,
  description, setDescription,
  location, setLocation,
  startTime, setStartTime,
  endTime, setEndTime,
  mapsUrl, setMapsUrl,
  onSubmit,
}: {
  open: boolean; onOpenChange: (open: boolean) => void;
  isEditing: boolean; isLoading: boolean;
  date: string; setDate: (v: string) => void;
  title: string; setTitle: (v: string) => void;
  description: string; setDescription: (v: string) => void;
  location: string; setLocation: (v: string) => void;
  startTime: string; setStartTime: (v: string) => void;
  endTime: string; setEndTime: (v: string) => void;
  mapsUrl: string; setMapsUrl: (v: string) => void;
  onSubmit: () => void;
}) {
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);

  const openMapsSearch = () => {
    const query = encodeURIComponent(location || title);
    const url = isIOS
      ? `https://maps.apple.com/?q=${query}`
      : `https://www.google.com/maps/search/?api=1&query=${query}`;
    window.open(url, '_blank');
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        className="max-w-lg max-h-[90vh] overflow-y-auto w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-3xl !rounded-b-none sm:!rounded-3xl transition-transform duration-500 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-2xl"
        onOpenAutoFocus={(e) => e.preventDefault()}
      >
        <div className="w-full flex justify-center pt-4 sm:hidden">
          <div className="w-12 h-1.5 bg-muted rounded-full" />
        </div>

        <DialogHeader>
          <DialogTitle>{isEditing ? "Editar Atividade" : "Nova Atividade"}</DialogTitle>
          <DialogDescription className="sr-only">Formul├írio de atividade do roteiro</DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Data */}
          <div className="space-y-2">
            <Label>Data *</Label>
            <Input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="h-11" />
          </div>

          {/* T├¡tulo */}
          <div className="space-y-2">
            <Label>T├¡tulo *</Label>
            <Input placeholder="Ex: Visita ao museu" value={title} onChange={(e) => setTitle(e.target.value)} className="h-11" />
          </div>

          {/* Hor├írios */}
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-2">
              <Label>Hor├írio in├¡cio</Label>
              <Input type="time" value={startTime} onChange={(e) => setStartTime(e.target.value)} className="h-11" />
            </div>
            <div className="space-y-2">
              <Label>Hor├írio fim</Label>
              <Input type="time" value={endTime} onChange={(e) => setEndTime(e.target.value)} className="h-11" />
            </div>
          </div>

          {/* Local + busca */}
          <div className="space-y-2">
            <Label>Local</Label>
            <div className="flex gap-2">
              <Input
                placeholder="Ex: Museu do Louvre"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                className="h-11"
              />
              <Button
                type="button"
                variant="outline"
                size="icon"
                className="h-11 w-11 shrink-0"
                onClick={openMapsSearch}
                disabled={!location && !title}
                title="Buscar no Maps"
              >
                <Search className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {/* Link do Maps */}
          <div className="space-y-2">
            <Label className="flex items-center gap-1.5">
              <MapPin className="h-3.5 w-3.5 text-muted-foreground" />
              Link do Google Maps
            </Label>
            <div className="flex gap-2">
              <Input
                placeholder="Cole o link copiado do MapsÔÇª"
                value={mapsUrl}
                onChange={(e) => setMapsUrl(e.target.value)}
                className="h-11 text-sm"
              />
              {mapsUrl && (
                <a
                  href={mapsUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="h-11 w-11 shrink-0 flex items-center justify-center rounded-md border border-input bg-background hover:bg-accent transition-colors"
                >
                  <ExternalLink className="h-4 w-4" />
                </a>
              )}
            </div>
            <p className="text-[11px] text-muted-foreground leading-relaxed">
              Toque em ­ƒöì para buscar, copie o link no Maps e cole aqui.
            </p>
          </div>

          {/* Descri├º├úo */}
          <div className="space-y-2">
            <Label>Descri├º├úo</Label>
            <Textarea
              placeholder="Detalhes da atividadeÔÇª"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="resize-none"
              rows={3}
            />
          </div>

          {/* Bot├Áes */}
          <div className="flex gap-3 pt-2 pb-2">
            <Button type="button" variant="outline" className="w-1/2 h-11" onClick={() => onOpenChange(false)}>
              Cancelar
            </Button>
            <Button className="w-1/2 h-11 font-bold" onClick={onSubmit} disabled={isLoading || !date || !title}>
              {isLoading ? "SalvandoÔÇª" : isEditing ? "Salvar" : "Adicionar"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { Plane, Archive } from "lucide-react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { TripCard } from "@/components/trips/TripCard";
import { TripArchivedCard } from "@/components/trips/TripArchivedCard";
import { EmptyState } from "@/components/ui/empty-state";

interface TripListViewProps {
  trips: any[];
  tripFilter: "active" | "archived";
  setTripFilter: (filter: "active" | "archived") => void;
  onTripClick: (id: string) => void;
  onUnarchive: (id: string) => void;
}

export function TripListView({ trips, tripFilter, setTripFilter, onTripClick, onUnarchive }: TripListViewProps) {
  const filteredTrips = trips.filter(t => tripFilter === "active" ? !t.is_archived : t.is_archived);

  return (
    <Tabs value={tripFilter} onValueChange={(v) => setTripFilter(v as any)}>
      <TabsList className="w-full sm:w-auto">
        <TabsTrigger value="active" className="flex-1 sm:flex-none gap-2">
          <Plane className="h-4 w-4" /> Ativas ({trips.filter(t => !t.is_archived).length})
        </TabsTrigger>
        <TabsTrigger value="archived" className="flex-1 sm:flex-none gap-2">
          <Archive className="h-4 w-4" /> Arquivadas ({trips.filter(t => t.is_archived).length})
        </TabsTrigger>
      </TabsList>

      <TabsContent value="active" className="mt-6">
        <div className="space-y-3">
          {filteredTrips.length > 0 ? (
            filteredTrips.map(t => <TripCard key={t.id} trip={t} onClick={() => onTripClick(t.id)} />)
          ) : (
            <EmptyState
              icon={Plane}
              title="Nenhuma viagem ativa"
              description="Suas viagens ativas aparecer├úo aqui. Crie uma nova viagem usando o bot├úo acima."
            />
          )}
        </div>
      </TabsContent>

      <TabsContent value="archived" className="mt-6">
        <div className="space-y-3">
          {filteredTrips.length > 0 ? (
            filteredTrips.map(t => (
              <TripArchivedCard key={t.id} trip={t} onUnarchive={() => onUnarchive(t.id)} onClick={() => onTripClick(t.id)} />
            ))
          ) : (
            <EmptyState
              icon={Archive}
              title="Nenhuma viagem arquivada"
              description="Viagens conclu├¡das ou arquivadas aparecer├úo aqui para consulta futura."
            />
          )}
        </div>
      </TabsContent>
    </Tabs>
  );
}

import React, { useState } from 'react';
import { Loader2, Plus, Trash2, ShoppingCart, Check } from 'lucide-react';
import { EmptyState } from '@/components/ui/empty-state';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { CurrencyInput } from '@/components/ui/currency-input';
import { Checkbox } from '@/components/ui/checkbox';
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { toast } from 'sonner';
import { AITripSuggestions } from './AITripSuggestions';
import { moneyUtils } from "@/utils/money";

interface ShoppingItem {
  id: string;
  item: string;
  estimatedCost: number;
  purchased: boolean;
}

interface TripShoppingProps {
  trip: {
    id: string;
    name: string;
    currency: string;
    destination?: string;
    shopping_list?: ShoppingItem[];
  };
  onUpdateTrip: (updates: { shopping_list: ShoppingItem[] }) => Promise<void>;
  isUpdating?: boolean;
}

export function TripShopping({ trip, onUpdateTrip, isUpdating = false }: TripShoppingProps) {
  const [shoppingList, setShoppingList] = useState<ShoppingItem[]>(
    trip.shopping_list || []
  );
  const [newItem, setNewItem] = useState('');
  const [newCost, setNewCost] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const handleApplyAISuggestions = async (suggestions: any[]) => {
    setIsAdding(true);
    const newItems: ShoppingItem[] = suggestions.map(s => ({
      id: crypto.randomUUID(),
      item: s.item,
      estimatedCost: Number(s.estimatedCost) || 0,
      purchased: false
    }));

    const updatedList = [...shoppingList, ...newItems];
    setShoppingList(updatedList);

    try {
      await onUpdateTrip({ shopping_list: updatedList });
      toast.success(`${suggestions.length} itens adicionados com sucesso!`);
    } catch (error) {
      setShoppingList(shoppingList);
      toast.error('Erro ao salvar sugest├Áes');
    } finally {
      setIsAdding(false);
    }
  };

  const handleCostChange = (value: string) => {
    setNewCost(value);
  };

  const getNumericCost = () => {
    return moneyUtils.parse(newCost) || 0;
  };

  const handleAddItem = async () => {
    if (!newItem.trim()) {
      toast.error('Digite o nome do item');
      return;
    }

    const cost = getNumericCost();
    if (cost <= 0) {
      toast.error('Digite um valor v├ílido');
      return;
    }

    setIsAdding(true);

    const newShoppingItem: ShoppingItem = {
      id: crypto.randomUUID(),
      item: newItem.trim(),
      estimatedCost: cost,
      purchased: false,
    };

    const updatedList = [...shoppingList, newShoppingItem];
    setShoppingList(updatedList);

    try {
      await onUpdateTrip({ shopping_list: updatedList });
      setNewItem('');
      setNewCost('');
      toast.success('Item adicionado');
    } catch (error) {
      setShoppingList(shoppingList);
      toast.error('Erro ao adicionar item');
    } finally {
      setIsAdding(false);
    }
  };

  const handleTogglePurchased = async (id: string) => {
    const updatedList = shoppingList.map((item) =>
      item.id === id ? { ...item, purchased: !item.purchased } : item
    );
    setShoppingList(updatedList);

    try {
      await onUpdateTrip({ shopping_list: updatedList });
    } catch (error) {
      setShoppingList(shoppingList);
      toast.error('Erro ao atualizar item');
    }
  };

  const handleDeleteItem = async (id: string) => {
    const updatedList = shoppingList.filter((item) => item.id !== id);
    setShoppingList(updatedList);

    try {
      await onUpdateTrip({ shopping_list: updatedList });
      toast.success('Item removido');
    } catch (error) {
      setShoppingList(shoppingList);
      toast.error('Erro ao remover item');
    }
  };

  const totalEstimated = shoppingList.reduce((sum, item) => SafeFinancialCalculator.add(sum, item.estimatedCost), 0);
  const totalPurchased = shoppingList
    .filter((item) => item.purchased)
    .reduce((sum, item) => SafeFinancialCalculator.add(sum, item.estimatedCost), 0);
  const purchasedCount = shoppingList.filter((item) => item.purchased).length;

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Summary Cards */}
      <div className="grid grid-cols-2 gap-4">
        <div className="p-4 rounded-xl border border-border bg-muted/30">
          <p className="text-xs text-muted-foreground uppercase tracking-widest mb-1">
            Previs├úo Total
          </p>
          <p className="font-mono text-2xl font-bold">
            {trip.currency} {totalEstimated.toFixed(2)}
          </p>
          <p className="text-xs text-muted-foreground mt-1">
            {shoppingList.length} {shoppingList.length === 1 ? 'item' : 'itens'}
          </p>
        </div>

        <div className="p-4 rounded-xl border border-border bg-muted/30">
          <p className="text-xs text-muted-foreground uppercase tracking-widest mb-1">
            J├í Comprado
          </p>
          <p className="font-mono text-2xl font-bold text-positive">
            {trip.currency} {totalPurchased.toFixed(2)}
          </p>
          <p className="text-xs text-muted-foreground mt-1">
            {purchasedCount} de {shoppingList.length} itens
          </p>
        </div>
      </div>

      {/* Add New Item */}
      <div className="p-4 rounded-xl border border-border bg-muted/30 space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <ShoppingCart className="h-5 w-5 text-muted-foreground" />
            <h3 className="font-semibold">Adicionar Item</h3>
          </div>
          <AITripSuggestions 
            type="shopping"
            destination={trip.destination || trip.name}
            currency={trip.currency}
            onApply={handleApplyAISuggestions}
          />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div className="space-y-2">
            <Label>Item</Label>
            <Input
              id="shoppingItem" name="shoppingItem"
              placeholder="Ex: Protetor solar, SnorkelÔÇª"
              value={newItem}
              onChange={(e) => setNewItem(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  e.preventDefault();
                  handleAddItem();
                }
              }}
            />
          </div>

          <div className="space-y-2">
            <Label>Custo Estimado ({trip.currency})</Label>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm z-10">
                  {trip.currency}
                </span>
                <CurrencyInput
                  placeholder="0,00"
                  value={newCost}
                  onChange={handleCostChange}
                  currency={trip.currency}
                  className="pl-16"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleAddItem();
                    }
                  }}
                />
              </div>
              <Button
                onClick={handleAddItem}
                disabled={isAdding || isUpdating}
                size="icon"
              >
                {isAdding ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Plus className="h-4 w-4" />
                )}
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* Shopping List */}
      {shoppingList.length === 0 ? (
        <EmptyState
          icon={ShoppingCart}
          title="Nenhum item na lista"
          description="Adicione itens que deseja comprar para a viagem."
        />
      ) : (
        <div className="space-y-2">
          <h3 className="text-xs uppercase tracking-widest text-muted-foreground font-medium">
            Lista de Compras
          </h3>
          {shoppingList.map((item) => (
            <div
              key={item.id}
              className={cn(
                "flex items-center gap-4 p-4 rounded-xl border transition-all duration-300",
                item.purchased 
                  ? "bg-muted/30 border-transparent opacity-70" 
                  : "bg-card/40 border-border/50 hover:bg-card/80 hover:shadow-sm"
              )}
            >
              <Checkbox
                checked={item.purchased}
                onCheckedChange={() => handleTogglePurchased(item.id)}
                className="flex-shrink-0 rounded-full h-5 w-5 border-muted-foreground/30 data-[state=checked]:bg-positive data-[state=checked]:border-positive data-[state=checked]:text-white shadow-sm transition-all duration-300"
              />

              <div className="flex-1 min-w-0">
                <p
                  className={cn(
                    "font-medium text-sm transition-all duration-300",
                    item.purchased
                      ? 'line-through text-muted-foreground'
                      : 'text-foreground'
                  )}
                >
                  {item.item}
                </p>
                <p className="text-sm text-muted-foreground font-mono mt-0.5">
                  {trip.currency} {item.estimatedCost.toFixed(2)}
                </p>
              </div>

              {item.purchased && (
                <Check className="h-4 w-4 text-positive flex-shrink-0" />
              )}

              <Button
                variant="ghost"
                size="icon"
                onClick={() => handleDeleteItem(item.id)}
                className="flex-shrink-0 text-muted-foreground hover:text-destructive"
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { Button } from '@/components/ui/button';
import { supabase } from '@/integrations/supabase/client';
import { cn } from '@/lib/utils';
import { parseLocalDate } from '@/utils/dateUtils';
import { moneyUtils } from '@/utils/money';
import { useQuery } from '@tanstack/react-query';
import {
  ArrowRight,
  Calendar,
  CheckCircle,
  DollarSign,
  Info,
  Plus,
  Receipt,
  Trash2,
  TrendingUp,
  User,
  Users,
  Wallet,
} from 'lucide-react';

interface TripSummaryTabProps {
  selectedTrip: any;
  totalExpenses: number;
  myTotalSpent: number;
  myPersonalBudget: number | null;
  participants: any[];
  balances: any[];
  tripTransactions: any[];
  tripFinancialSummary: any;
  user: any;
  onAddParticipant: () => void;
  permissions: any;
  dateFns: any;
  ptBR: any;
  onRemoveClick?: (participant: any, balance: any) => void;
  pendingInvitations?: any[];
  onCancelInvitation?: (id: string) => void;
  setActiveTab?: (tab: string) => void;
}

export function TripSummaryTab({
  selectedTrip,
  totalExpenses,
  myTotalSpent,
  myPersonalBudget,
  participants,
  balances,
  tripTransactions,
  user,
  onAddParticipant,
  permissions,
  onRemoveClick,
  pendingInvitations = [],
  onCancelInvitation,
  setActiveTab,
}: TripSummaryTabProps) {
  const tripDays = Math.max(
    1,
    Math.ceil(
      (parseLocalDate(selectedTrip.end_date).getTime() -
        parseLocalDate(selectedTrip.start_date).getTime()) /
        (1000 * 60 * 60 * 24),
    ) + 1,
  );
  const currency = selectedTrip.currency || 'BRL';

  // (a) Gastos pessoais: minhas transa├º├Áes N├âO compartilhadas
  const myPersonalExpenses = tripTransactions
    .filter(
      (t) =>
        t.type === 'EXPENSE' &&
        !t.is_shared &&
        (t.creator_user_id === user?.id || t.user_id === user?.id),
    )
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  // Saldo do participante atual (do RPC ÔÇö fonte ├║nica da verdade)
  const myBalance = balances.find((b) => b.participantId === user?.id);

  const myShareOfSharedExpenses = tripTransactions
    .filter((t) => t.type === 'EXPENSE' && t.is_shared)
    .reduce((sum, t) => {
      if (!t.transaction_splits) return sum;
      const mySplit = t.transaction_splits.find((s: any) => s.user_id === user?.id);
      return sum + (mySplit ? Number(mySplit.amount) : 0);
    }, 0);

  const myTotalPersonal = myPersonalExpenses + myShareOfSharedExpenses;

  // (b) Gastos compartilhados pagos por mim (eu paguei a conta toda)
  const mySharedExpensesPaid = tripTransactions
    .filter(
      (t) =>
        t.type === 'EXPENSE' &&
        t.is_shared &&
        (t.creator_user_id === user?.id || t.user_id === user?.id),
    )
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  // (c) Total de despesas compartilhadas do grupo (para exibi├º├úo geral)
  const totalSharedExpenses = tripTransactions
    .filter((t) => t.type === 'EXPENSE' && t.is_shared)
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  // Busca cota├º├úo em tempo real se n├úo for BRL
  const { data: realTimeRate } = useQuery({
    queryKey: ['currency-quote', currency],
    queryFn: async () => {
      if (currency === 'BRL') return null;

      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (!session) return null;

      const { data, error } = await supabase.functions.invoke('get-currency-quote', {
        body: { currency },
        headers: {
          Authorization: `Bearer ${session.access_token}`,
        },
      });

      if (error) throw error;
      return data.rate as number;
    },
    enabled: currency !== 'BRL',
    staleTime: 5 * 60 * 1000, // 5 minutos
  });

  const { data: session } = useQuery({
    queryKey: ['session'],
    queryFn: async () => {
      const { data } = await supabase.auth.getSession();
      return data.session;
    },
  });

  return (
    <div className="space-y-8 mt-6 animate-fade-in pb-20">
      {/* Mensagem de Boas Vindas caso n├úo haja transa├º├Áes */}
      {tripTransactions.length === 0 && (
        <div className="p-6 rounded-4xl border border-primary/20 bg-gradient-to-br from-primary/10 via-primary/5 to-card relative overflow-hidden text-center sm:text-left flex flex-col sm:flex-row items-center justify-between gap-4 shadow-sm">
          <div className="relative z-10 max-w-xl">
            <h2 className="font-display font-black text-2xl mb-1 text-foreground">
              Sua viagem est├í pronta! Ô£ê´©Å
            </h2>
            <p className="text-muted-foreground text-sm">
              Use as a├º├Áes r├ípidas abaixo para convidar amigos, montar seu roteiro e iniciar os
              lan├ºamentos. O resumo da viagem ser├í atualizado automaticamente.
            </p>
          </div>
          <TrendingUp className="w-32 h-32 text-primary/5 absolute right-4 top-1/2 -translate-y-1/2 sm:-right-4" />
        </div>
      )}

      {/* ===== A├ç├òES R├üPIDAS (Sempre vis├¡veis) ===== */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <button
          onClick={onAddParticipant}
          className="flex flex-col items-center justify-center gap-3 p-4 rounded-2xl border border-border/50 bg-card/50 hover:bg-card hover:border-accent/30 hover:shadow-accent/10 transition-all group backdrop-blur-sm"
        >
          <div className="w-12 h-12 rounded-full bg-accent/10 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
            <Users className="h-6 w-6 text-accent" />
          </div>
          <span className="font-bold text-sm text-center leading-tight">
            Convidar
            <br />
            Amigos
          </span>
        </button>

        <button
          onClick={() => setActiveTab && setActiveTab('itinerary')}
          className="flex flex-col items-center justify-center gap-3 p-4 rounded-2xl border border-border/50 bg-card/50 hover:bg-card hover:border-warning/30 hover:shadow-warning/10 transition-all group backdrop-blur-sm"
        >
          <div className="w-12 h-12 rounded-full bg-warning/10 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
            <Calendar className="h-6 w-6 text-warning" />
          </div>
          <span className="font-bold text-sm text-center leading-tight">
            Montar
            <br />
            Roteiro
          </span>
        </button>

        <button
          onClick={() => setActiveTab && setActiveTab('expenses')}
          className="flex flex-col items-center justify-center gap-3 p-4 rounded-2xl border border-border/50 bg-card/50 hover:bg-card hover:border-success/30 hover:shadow-[0_0_15px_rgba(34,197,94,0.1)] transition-all group backdrop-blur-sm"
        >
          <div className="w-12 h-12 rounded-full bg-success/12 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
            <DollarSign className="h-6 w-6 text-success" />
          </div>
          <span className="font-bold text-sm text-center leading-tight">
            Lan├ºar
            <br />
            Despesa
          </span>
        </button>

        <button
          onClick={() => setActiveTab && setActiveTab('checklist')}
          className="flex flex-col items-center justify-center gap-3 p-4 rounded-2xl border border-border/50 bg-card/50 hover:bg-card hover:border-accent/30 hover:shadow-accent/10 transition-all group backdrop-blur-sm"
        >
          <div className="w-12 h-12 rounded-full bg-accent/10 flex items-center justify-center shrink-0 group-hover:scale-110 transition-transform">
            <CheckCircle className="h-6 w-6 text-accent" />
          </div>
          <span className="font-bold text-sm text-center leading-tight">
            Fazer as
            <br />
            Malas
          </span>
        </button>
      </div>

      {/* Grid de Informa├º├Áes Principais */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="p-5 rounded-2xl border border-border/50 bg-card/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 mb-3 text-muted-foreground">
            <Calendar className="h-4 w-4" />
            <span className="text-sm font-bold uppercase tracking-widest">Dura├º├úo</span>
          </div>
          <p className="font-mono text-3xl font-black tracking-tighter">
            {tripDays}
            <span className="text-sm font-normal text-muted-foreground ml-1">dias</span>
          </p>
        </div>

        <div className="p-5 rounded-2xl border border-border/50 bg-card/50 backdrop-blur-sm">
          <div className="flex items-center gap-2 mb-3 text-muted-foreground">
            <TrendingUp className="h-4 w-4" />
            <span className="text-sm font-bold uppercase tracking-widest">Minha M├®dia/Dia</span>
          </div>
          <p className="font-mono text-3xl font-black tracking-tighter text-primary">
            {moneyUtils.format(myTotalPersonal / tripDays, currency)}
          </p>
        </div>
      </div>

      {/* ===== SE├ç├âO DE GASTOS ÔÇö 3 BLOCOS SEPARADOS ===== */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* (A) Gastos Pessoais ÔÇö apenas meus, privados e impacto no or├ºamento */}
        <div className="p-6 rounded-3xl border border-border/50 bg-gradient-to-br from-card/50 to-muted/20 backdrop-blur-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity">
            <User className="w-32 h-32" />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4 text-muted-foreground">
              <User className="h-4 w-4 text-accent" />
              <h3 className="text-sm font-bold uppercase tracking-widest">Meu Gasto (Or├ºamento)</h3>
            </div>
            <p className="font-mono text-3xl font-black tracking-tighter text-foreground mb-1">
              {moneyUtils.format(myTotalSpent, currency)}
            </p>
            <p className="text-sm text-muted-foreground">
              Impacto real (caixa): privadas + adiantamentos pendentes em compartilhados
            </p>
            {myPersonalBudget && (
              <div className="mt-3 pt-3 border-t border-border/50">
                <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-1">
                  Or├ºamento Pessoal
                </p>
                <p className="text-sm font-mono font-bold text-accent">
                  {((myTotalSpent / myPersonalBudget) * 100).toFixed(1)}% utilizado
                </p>
              </div>
            )}

            {/* Aviso de Cota├º├úo em Tempo Real para Moedas Estrangeiras */}
            {currency !== 'BRL' && realTimeRate && (
              <div className="mt-4 p-3 rounded-lg border border-warning/30 bg-warning/10 backdrop-blur-sm relative overflow-hidden group">
                <div className="flex items-start gap-2 relative z-10">
                  <Info className="h-4 w-4 text-warning mt-0.5 shrink-0" />
                  <div>
                    <p className="text-sm font-bold text-warning mb-0.5">Cota├º├úo Oficial de Hoje</p>
                    <p className="text-sm text-muted-foreground">
                      Seu gasto pelo <strong>PM atual</strong> ├®{' '}
                      {moneyUtils.format(myTotalSpent, currency)}. Pela cota├º├úo de hoje (R${' '}
                      {realTimeRate.toFixed(2)}), custaria{' '}
                      <strong className="text-warning">
                        R${' '}
                        {(myTotalSpent * realTimeRate).toLocaleString('pt-BR', {
                          minimumFractionDigits: 2,
                          maximumFractionDigits: 2,
                        })}
                      </strong>
                      .
                    </p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* (B) Compartilhados que EU paguei */}
        <div className="p-6 rounded-3xl border border-border/50 bg-gradient-to-br from-card/50 to-muted/20 backdrop-blur-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity">
            <Receipt className="w-32 h-32" />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4 text-muted-foreground">
              <Receipt className="h-4 w-4 text-accent" />
              <h3 className="text-sm font-bold uppercase tracking-widest">
                Compartilhados que Paguei
              </h3>
            </div>
            <p className="font-mono text-3xl font-black tracking-tighter text-foreground mb-1">
              {moneyUtils.format(mySharedExpensesPaid, currency)}
            </p>
            <p className="text-sm text-muted-foreground">
              {
                tripTransactions.filter(
                  (t) =>
                    t.type === 'EXPENSE' &&
                    t.is_shared &&
                    (t.creator_user_id === user?.id || t.user_id === user?.id),
                ).length
              }{' '}
              despesas do grupo
            </p>
            <div className="mt-3 pt-3 border-t border-border/50">
              <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-1">
                Total do Grupo
              </p>
              <p className="text-sm font-mono font-bold text-accent">
                {moneyUtils.format(totalSharedExpenses, currency)}
              </p>
            </div>
          </div>
        </div>

        {/* (C) Valores que me devem / Eu devo (do RPC ÔÇö fonte de verdade) */}
        <div className="p-6 rounded-3xl border border-border/50 bg-gradient-to-br from-card/50 to-muted/20 backdrop-blur-sm relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] group-hover:opacity-[0.05] transition-opacity">
            <DollarSign className="w-32 h-32" />
          </div>
          <div className="relative z-10">
            <div className="flex items-center gap-2 mb-4 text-muted-foreground">
              <DollarSign className="h-4 w-4 text-success" />
              <h3 className="text-sm font-bold uppercase tracking-widest">Saldo Compartilhado</h3>
            </div>
            {myBalance ? (
              <>
                <p
                  className={cn(
                    'font-mono text-3xl font-black tracking-tighter mb-1',
                    Math.abs(myBalance.balance) < 0.01
                      ? 'text-muted-foreground'
                      : myBalance.balance > 0
                        ? 'text-success dark:text-success'
                        : 'text-warning',
                  )}
                >
                  {Math.abs(myBalance.balance) < 0.01 ? (
                    'Em dia!'
                  ) : (
                    <>
                      {myBalance.balance > 0 ? '+' : ''}
                      {moneyUtils.format(myBalance.balance, currency)}
                    </>
                  )}
                </p>
                <p className="text-sm text-muted-foreground">
                  {Math.abs(myBalance.balance) < 0.01
                    ? 'Tudo acertado'
                    : myBalance.balance > 0
                      ? 'Outros te devem'
                      : 'Voc├¬ deve ao grupo'}
                </p>
                <div className="mt-3 pt-3 border-t border-border/50 grid grid-cols-2 gap-2">
                  <div>
                    <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-0.5">
                      Paguei
                    </p>
                    <p className="text-sm font-mono font-bold text-success dark:text-success">
                      {moneyUtils.format(mySharedExpensesPaid, currency)}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest mb-0.5">
                      Minha parte
                    </p>
                    <p className="text-sm font-mono font-bold text-warning">
                      {moneyUtils.format(myShareOfSharedExpenses, currency)}
                    </p>
                  </div>
                </div>
              </>
            ) : (
              <p className="text-sm text-muted-foreground">Sem dados de saldo</p>
            )}
          </div>
        </div>
      </div>

      {/* Painel de Acerto Final */}
      {participants.length > 0 &&
        myBalance &&
        (() => {
          const isSettled = Math.abs(myBalance.balance) < 0.01;

          // Verificar se h├í acertos pendentes de confirma├º├úo
          const waitingMyConfirmation = tripTransactions.some(
            (t) =>
              t.type === 'EXPENSE' &&
              t.is_shared &&
              t.transaction_splits?.some(
                (s: any) =>
                  s.user_id !== user?.id && // n├úo sou eu que devo
                  (t.creator_user_id === user?.id || t.user_id === user?.id) && // eu paguei
                  s.settled_by_debtor === true &&
                  !s.settled_by_creditor,
              ),
          );

          const waitingTheirConfirmation = tripTransactions.some(
            (t) =>
              t.type === 'EXPENSE' &&
              t.is_shared &&
              t.transaction_splits?.some(
                (s: any) =>
                  s.user_id === user?.id && // eu devo
                  s.settled_by_debtor === true &&
                  !s.settled_by_creditor,
              ),
          );

          return (
            <div
              className={cn(
                'p-8 rounded-4xl border transition-all duration-500 relative overflow-hidden',
                isSettled
                  ? 'border-success/20 bg-success/5'
                  : myBalance.balance >= 0
                    ? 'border-accent/20 bg-accent/5'
                    : 'border-warning/20 bg-warning/5',
              )}
            >
              <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between gap-8">
                <div className="flex items-center gap-5">
                  <div
                    className={cn(
                      'w-16 h-16 rounded-2xl flex items-center justify-center shadow-lg transition-transform hover:scale-110',
                      isSettled
                        ? 'bg-success shadow-success/20'
                        : myBalance.balance >= 0
                          ? 'bg-accent shadow-accent/20'
                          : 'bg-warning shadow-warning/20',
                    )}
                  >
                    {isSettled ? (
                      <CheckCircle className="h-8 w-8 text-white" />
                    ) : (
                      <Wallet className="h-8 w-8 text-white" />
                    )}
                  </div>
                  <div>
                    <h3 className="font-display font-bold text-2xl tracking-tight">
                      Meu Saldo de Acertos
                    </h3>
                    <p className="text-muted-foreground">
                      {isSettled
                        ? 'Voc├¬ est├í em dia com a viagem!'
                        : myBalance.balance >= 0
                          ? 'Voc├¬ pagou mais que a sua parte.'
                          : 'Voc├¬ deve para o grupo ou participante.'}
                    </p>
                  </div>
                </div>

                <div className="flex flex-wrap gap-8 md:gap-12">
                  <div className="space-y-2">
                    <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest">
                      Eu Paguei
                    </p>
                    <p className="font-mono text-2xl font-black tracking-tighter text-success dark:text-success">
                      {moneyUtils.format(mySharedExpensesPaid, currency)}
                    </p>
                  </div>
                  <div className="space-y-2">
                    <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest">
                      Minha Parte
                    </p>
                    <p className="font-mono text-2xl font-black tracking-tighter text-warning">
                      {moneyUtils.format(myShareOfSharedExpenses, currency)}
                    </p>
                  </div>
                  <div className="space-y-2">
                    <p className="text-sm text-muted-foreground uppercase font-bold tracking-widest">
                      Saldo Atual
                    </p>
                    <p
                      className={cn(
                        'font-mono text-2xl font-black tracking-tighter',
                        isSettled
                          ? 'text-success dark:text-success'
                          : myBalance.balance >= 0
                            ? 'text-accent'
                            : 'text-warning',
                      )}
                    >
                      {isSettled ? (
                        moneyUtils.format(0, currency)
                      ) : (
                        <>
                          {myBalance.balance >= 0 ? '+' : ''}
                          {moneyUtils.format(myBalance.balance, currency)}
                        </>
                      )}
                    </p>
                  </div>
                </div>
              </div>

              {!isSettled && (
                <div className="mt-8 pt-6 border-t border-border/50 flex flex-col sm:flex-row items-center justify-between gap-4">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground italic">
                    <Info className="h-4 w-4" />
                    {waitingMyConfirmation ? (
                      <span className="text-accent font-semibold">
                        Existem pagamentos aguardando sua confirma├º├úo de recebimento.
                      </span>
                    ) : waitingTheirConfirmation ? (
                      <span className="text-warning font-semibold">
                        Aguardando o credor confirmar o seu pagamento.
                      </span>
                    ) : myBalance.balance >= 0 ? (
                      'Aguarde os outros participantes realizarem o acerto com voc├¬.'
                    ) : (
                      'Realize o acerto na aba Compartilhados para equilibrar seu saldo.'
                    )}
                  </div>
                  <Button
                    variant="outline"
                    className="rounded-xl gap-2 hover:bg-muted"
                    onClick={() => (window.location.href = '/compartilhados?tab=TRAVEL')}
                  >
                    Ir para Acertos <ArrowRight className="h-4 w-4" />
                  </Button>
                </div>
              )}
            </div>
          );
        })()}

      {/* Se├º├úo de Viajantes da Viagem */}
      {participants.length > 0 && (
        <section className="p-6 rounded-3xl border border-border/50 bg-gradient-to-br from-card/50 to-muted/20 backdrop-blur-sm space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2 text-muted-foreground">
              <Users className="h-4 w-4 text-primary" />
              <h3 className="text-sm font-bold uppercase tracking-widest">
                Viajantes ({participants.length})
              </h3>
            </div>
            {permissions?.isOwner && (
              <Button
                variant="outline"
                size="sm"
                className="rounded-xl gap-2 h-10"
                onClick={onAddParticipant}
              >
                <Plus className="h-4 w-4" /> Convidar Viajante
              </Button>
            )}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {participants
              .map((participant) => {
