  useArchivedAccounts,
  useUnarchiveAccount,
  useCreditCardInvoice,
  useAccountDependencies,
  useCreditCardClosingOverride,
} from "@/hooks/useAccounts";
import { useDependentTransactions } from "@/hooks/transactions/useDependentTransactions";
import {
  useTransactions,
  useCreateTransaction,
  useDeleteTransaction,
  useBulkCreateTransactions,
} from "@/hooks/useTransactions";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { getInvoiceData, getTargetDate, formatCycleRange } from "@/lib/invoiceUtils";
import { formatDateISO, getMonthDateRange } from "@/utils/dateUtils";
import { getInvoiceData as getInvoiceDataNew } from "@/utils/credit-cards/invoiceData";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { useAuth } from "@/contexts/AuthContext";
import { getBankById } from "@/lib/banks";
import { moneyUtils } from "@/utils/money";
import { CascadeDeleteType } from "@/components/modals/DeleteTransactionModal";

export type CardView = "list" | "detail";

export interface CreditCardAccount {
  id: string;
  name: string;
  bank_id: string | null;
  credit_limit: number | null;
  balance: number;
  closing_day: number | null;
  due_day: number | null;
  currency?: string;
  is_international?: boolean;
  user_id?: string;
  is_shared_with_me?: boolean;
}

export function useCreditCardsDashboard() {
  const { user } = useAuth();
  const { currentDate, startDay } = useMonth();
  const [view, setView] = useState<CardView>("list");
  const [selectedCard, setSelectedCard] = useState<CreditCardAccount | null>(null);
  const [showArchiveConfirmModal, setShowArchiveConfirmModal] = useState(false);
  const urlParamsProcessed = useRef(false);
  const [showNewCardDialog, setShowNewCardDialog] = useState(false);

  const { data: exportTransactions = [] } = useTransactions({
    startDate: `${currentDate.getFullYear()}-01-01`,
    endDate: `${currentDate.getFullYear()}-12-31`,
  });

  const [showImportDialog, setShowImportDialog] = useState(false);
  const [showPayDialog, setShowPayDialog] = useState(false);
  const [showSharingDialog, setShowSharingDialog] = useState(false);
  const [showTransactionModal, setShowTransactionModal] = useState(false);
  const [searchParams, setSearchParams] = useSearchParams();

  const [selectedDate, setSelectedDate] = useState(() => new Date());

  // New Card State
  const [newBankId, setNewBankId] = useState("");
  const [newCustomBankName, setNewCustomBankName] = useState("");
  const [newBrand, setNewBrand] = useState("");
  const [newCardName, setNewCardName] = useState("");
  const [newClosingDay, setNewClosingDay] = useState("");
  const [newDueDay, setNewDueDay] = useState("");
  const [newLimit, setNewLimit] = useState("");
  const [newIsInternational, setNewIsInternational] = useState(false);
  const [newCurrency, setNewCurrency] = useState("USD");

  const { data: accounts = [], isLoading, refetch: refetchAccounts } = useAccounts();

  // Expandir a janela de busca para garantir que compras de meses anteriores
  // que caem na fatura atual sejam inclu├¡das no c├ílculo da lista de cart├Áes.
  const { startDate, endDate } = getMonthDateRange(currentDate, startDay);
  const extendedStartDate = dateFns.subMonths(new Date(startDate), 2).toISOString();
  const extendedEndDate = dateFns.addMonths(new Date(endDate), 1).toISOString();

  const {
    data: transactions = [],
    isLoading: transactionsLoading,
    refetch: refetchTransactions,
  } = useTransactions({
    startDate: extendedStartDate,
    endDate: extendedEndDate,
    limit: 5000,
  });

  const creditCards = useMemo(
    () => (accounts || []).filter((acc) => acc.type === "CREDIT_CARD") as CreditCardAccount[],
    [accounts]
  );

  const ownedCardIds = useMemo(
    () => creditCards.filter((c) => !c.is_shared_with_me).map((c) => c.id),
    [creditCards]
  );
  const { data: dependentTransactions = [] } = useDependentTransactions({
    cardIds: ownedCardIds,
    startDate: extendedStartDate,
    endDate: extendedEndDate,
  });

  const createAccount = useCreateAccount();
  const updateAccount = useUpdateAccount();
  const deleteAccountMutation = useDeleteAccount();
  const archiveAccountMutation = useArchiveAccount();
  const { data: archivedCards = [] } = useArchivedAccounts();
  const unarchiveAccountMutation = useUnarchiveAccount();
  const createTransaction = useCreateTransaction();
  const bulkCreateTransactions = useBulkCreateTransactions();
  const deleteTransaction = useDeleteTransaction();

  const [deleteCardConfirm, setDeleteCardConfirm] = useState<{
    isOpen: boolean;
    card: CreditCardAccount | null;
  }>({ isOpen: false, card: null });

  const { data: deleteCardDeps } = useAccountDependencies(deleteCardConfirm.card?.id);
  const deleteCardCanDelete = deleteCardDeps?.can_delete === true;

  const { data: selectedCardDeps } = useAccountDependencies(selectedCard?.id);
  const selectedCardCanDelete = selectedCardDeps?.can_delete === true;

  const [editingTransaction, setEditingTransaction] = useState<any>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<{ isOpen: boolean; transaction: any | null }>({
    isOpen: false,
    transaction: null,
  });
  const [showEditCardDialog, setShowEditCardDialog] = useState(false);

  const [editCardName, setEditCardName] = useState("");
  const [editCardColor, setEditCardColor] = useState("");
  const [editClosingDay, setEditClosingDay] = useState("");
  const [editDueDay, setEditDueDay] = useState("");
  const [editLimit, setEditLimit] = useState("");
  const [editBankId, setEditBankId] = useState("");
  const [editCustomBankName, setEditCustomBankName] = useState("");

  useEffect(() => {
    if (selectedCard) {
      if (urlParamsProcessed.current) {
        urlParamsProcessed.current = false;
        return;
      }
      setSelectedDate(getTargetDate(new Date(), selectedCard.closing_day || 1));
    }
  }, [selectedCard]);

  const { data: invoiceDataRPC, isFetching: invoiceFetching } = useCreditCardInvoice(
    selectedCard?.id || null,
    dateFns.format(dateFns.startOfMonth(selectedDate), "yyyy-MM-dd"),
    dateFns.format(dateFns.endOfMonth(selectedDate), "yyyy-MM-dd")
  );

  useEffect(() => {
    const cardId = searchParams.get("cardId");
    const invoiceDateParam = searchParams.get("invoiceDate") || searchParams.get("month");

    if (
      cardId &&
      accounts.length > 0 &&
      (!selectedCard || selectedCard.id !== cardId || invoiceDateParam)
    ) {
      const card = accounts.find((a) => a.id === cardId);
      if (card) {
        urlParamsProcessed.current = true;
        setSelectedCard(card as CreditCardAccount);
        setView("detail");

        // Se vier um m├¬s de fatura espec├¡fico na URL, navega para aquele m├¬s
        if (invoiceDateParam) {
          const [year, month] = invoiceDateParam.split("-").map(Number);
          if (year && month) {
            setSelectedDate(new Date(year, month - 1, 1));
          }
        }

        setSearchParams({}, { replace: true });
      }
    }
  }, [searchParams, accounts, selectedCard, setSearchParams]);

  const { data: closingOverride } = useCreditCardClosingOverride(
    selectedCard?.id || null,
    dateFns.format(dateFns.startOfMonth(selectedDate), "yyyy-MM-dd")
  );

  const invoiceData = useMemo(() => {
    if (!selectedCard) return null;
    const baseData = getInvoiceData(
      { ...selectedCard, closing_date_override: closingOverride },
      transactions,
      selectedDate
    );
    if (invoiceDataRPC) {
      return {
        ...baseData,
        invoiceTotal: Number(invoiceDataRPC.total) || 0,
        transactions: invoiceDataRPC.transactions || [],
      };
    }
    return baseData;
  }, [selectedCard, invoiceDataRPC, transactions, selectedDate, closingOverride]);

  const getCardInvoice = useCallback(
    (card: CreditCardAccount) => {
      const targetDate = getTargetDate(new Date(), card.closing_day || 1);
      const data = getInvoiceData(card, transactions, targetDate);

      if (data.status === "OPEN") {
        const prevDate = dateFns.subMonths(targetDate, 1);
        const prevData = getInvoiceData(card, transactions, prevDate);
        if (prevData.status === "CLOSED" && prevData.invoiceTotal > 0.01) {
          return {
            value: prevData.invoiceTotal,
            dueDate: prevData.dueDate,
            status: prevData.status,
          };
        }
      }

      return { value: data.invoiceTotal, dueDate: data.dueDate, status: data.status };
    },
    [transactions]
  );

  const getCardInstallments = (invoiceTxs: any[]) =>
    invoiceTxs
      .filter((t) => t.is_installment)
      .map((t) => ({
        id: t.id,
        description: t.description,
        current: t.current_installment || 1,
        total: t.total_installments || 1,
        value: t.amount,
      }));

  const formatCurrency = (value: number) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(value);

  const getDaysUntilDue = (dueDate: Date) =>
    Math.ceil((dueDate.getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24));

  const handleCreateCard = async () => {
    if (!newCardName.trim()) {
      toast.error("O nome do cart├úo ├® obrigat├│rio");
      return;
    }
    const isCustom =
      newBankId === "default" || newBankId === "default_international" || newBankId === "other";
    const finalBankId =
      isCustom && newCustomBankName.trim() ? `custom:${newCustomBankName.trim()}` : newBankId;

    await createAccount.mutateAsync({
      name: newCardName.trim(),
      type: "CREDIT_CARD",
      bank_id: finalBankId || null,
      credit_limit: moneyUtils.parse(newLimit) || 0,
      closing_day: parseInt(newClosingDay) || undefined,
      due_day: parseInt(newDueDay) || undefined,
      is_international: newIsInternational,
      currency: newIsInternational ? newCurrency : "BRL",
    });
    setShowNewCardDialog(false);
    resetNewCardForm();
  };

  const resetNewCardForm = () => {
    setNewBankId("");
    setNewCustomBankName("");
    setNewBrand("");
    setNewCardName("");
    setNewClosingDay("");
    setNewDueDay("");
    setNewLimit("");
    setNewIsInternational(false);
    setNewCurrency("USD");
  };

  const totalInvoices = useMemo(
    () => creditCards.reduce((sum, card) => sum + getCardInvoice(card).value, 0),
    [creditCards, getCardInvoice]
  );

  const totalDebt = useMemo(() => {
    return creditCards.reduce((accTotal, card) => {
      const balanceVal = Number(card.balance) || 0;
      return accTotal + (balanceVal < 0 ? Math.abs(balanceVal) : 0);
    }, 0);
  }, [creditCards]);

  const nextDueDate = useMemo(() => {
    if (creditCards.length === 0) return 0;
    return Math.min(...creditCards.map((card) => getDaysUntilDue(getCardInvoice(card).dueDate)));
  }, [creditCards, getCardInvoice]);

  const handleDeleteTransaction = async (cascadeType: CascadeDeleteType) => {
    if (!deleteConfirm.transaction) return;
    showActionFeedback("success");
    setTimeout(() => {
      setDeleteConfirm({ isOpen: false, transaction: null });
    }, 80);
    deleteTransaction.mutate({
      id: deleteConfirm.transaction.id,
      cascadeType,
    });
    refetchTransactions();
  };

  const handleEditCard = async () => {
    if (!selectedCard) return;
    const isCustom = editBankId === "default" || editBankId === "other";
    const finalBankId =
      isCustom && editCustomBankName.trim() ? `custom:${editCustomBankName.trim()}` : editBankId;

    showActionFeedback("success");
    setTimeout(() => {
      setShowEditCardDialog(false);
    }, 80);
    
    updateAccount.mutate({
      id: selectedCard.id,
      name: editCardName,
      closing_day: editClosingDay ? parseInt(editClosingDay) : null,
      due_day: editDueDay ? parseInt(editDueDay) : null,
      credit_limit: editLimit ? moneyUtils.parse(editLimit) : null,
      bank_color: editCardColor,
      bank_id: finalBankId || null,
    });
    refetchAccounts();
  };

  const handleExportCards = async (formatType: "PDF" | "CSV", period: "MONTH" | "YEAR") => {
    const { exportCardsToCSV, exportCardsToPDF } = await import("@/utils/exportData");
    let filteredTxs = exportTransactions;
    let periodLabel = `${currentDate.getFullYear()}`;

    if (period === "MONTH") {
      const startOfM = dateFns.startOfMonth(currentDate);
      const endOfM = dateFns.endOfMonth(currentDate);
      filteredTxs = exportTransactions.filter((t) => {
        const d = new Date(t.date);
        return d >= startOfM && d <= endOfM;
      });
      const monthNames = [
        "Janeiro",
        "Fevereiro",
        "Mar├ºo",
        "Abril",
        "Maio",
        "Junho",
        "Julho",
        "Agosto",
        "Setembro",
        "Outubro",
        "Novembro",
        "Dezembro",
      ];
      periodLabel = `${monthNames[currentDate.getMonth()]} de ${currentDate.getFullYear()}`;
    } else {
      periodLabel = `Ano ${currentDate.getFullYear()}`;
    }

    const totalLimit = creditCards.reduce((sum, c) => sum + (Number(c.credit_limit) || 0), 0);
    const totalInvoicesVal = creditCards.reduce((sum, card) => sum + getCardInvoice(card).value, 0);

    if (formatType === "PDF") {
      exportCardsToPDF(filteredTxs, creditCards, periodLabel, totalLimit, totalInvoicesVal);
    } else {
      exportCardsToCSV(filteredTxs, creditCards, periodLabel);
    }
  };

  const handlePayInvoice = async (fromId: string, amt: number, rate?: number) => {
    if (!selectedCard || !invoiceData) return;
    const debit = rate ? amt * rate : amt;
    const competenceFormatted = dateFns.format(selectedDate, "MMMM/yyyy", { locale: ptBR });
    const capitalizedCompetence =
      competenceFormatted.charAt(0).toUpperCase() + competenceFormatted.slice(1);

    await createTransaction.mutateAsync({
      amount: debit,
      description: `Pagamento Fatura ${selectedCard.name} - ${capitalizedCompetence}`,
      date: formatDateISO(new Date()),
      competence_date: dateFns.format(selectedDate, "yyyy-MM-01"),
      type: "TRANSFER",
      account_id: fromId,
      destination_account_id: selectedCard.id,
      domain: "PERSONAL",
      currency: rate ? "BRL" : selectedCard.currency || "BRL",
    });

    // Rotative Logic (Partial Payment)
    const remaining = invoiceData.invoiceTotal - amt;
    if (remaining > 0.01) {
      const nextMonth = dateFns.addMonths(selectedDate, 1);
      const nextMonthFmt = dateFns.format(nextMonth, "MMMM/yyyy", { locale: ptBR });

      // 1. Estorno no m├¬s atual para anular o impacto duplicado
      await createTransaction.mutateAsync({
        amount: remaining,
        description: `Estorno Saldo Rotativo Fatura ${capitalizedCompetence}`,
        date: formatDateISO(new Date()),
        competence_date: dateFns.format(selectedDate, "yyyy-MM-01"),
        type: "TRANSFER",
        account_id: selectedCard.id,
        destination_account_id: selectedCard.id,
        domain: "PERSONAL",
        currency: selectedCard.currency || "BRL",
      });

      // 2. Cobran├ºa do saldo rotativo no m├¬s seguinte
      await createTransaction.mutateAsync({
        amount: remaining,
        description: `Saldo Rotativo Fatura Anterior (${capitalizedCompetence})`,
        date: formatDateISO(new Date()),
        competence_date: dateFns.format(nextMonth, "yyyy-MM-01"),
        type: "TRANSFER",
        account_id: selectedCard.id,
        destination_account_id: selectedCard.id,
        domain: "PERSONAL",
        currency: selectedCard.currency || "BRL",
      });
    }

    toast.success("Pagamento processado!");
    setShowPayDialog(false);
    refetchAccounts();
    refetchTransactions();
  };

  return {
    user,
    accounts,
    view,
    setView,
    selectedCard,
    setSelectedCard,
    showArchiveConfirmModal,
    setShowArchiveConfirmModal,
    showNewCardDialog,
    setShowNewCardDialog,
    showImportDialog,
    setShowImportDialog,
    showPayDialog,
    setShowPayDialog,
    showSharingDialog,
    setShowSharingDialog,
    showTransactionModal,
    setShowTransactionModal,
    selectedDate,
    setSelectedDate,

    newBankId,
    setNewBankId,
    newCustomBankName,
    setNewCustomBankName,
    newBrand,
    setNewBrand,
    newCardName,
    setNewCardName,
    newClosingDay,
    setNewClosingDay,
    newDueDay,
    setNewDueDay,
    newLimit,
    setNewLimit,
    newIsInternational,
    setNewIsInternational,
    newCurrency,
    setNewCurrency,

    isLoading,
    transactionsLoading,
    creditCards,
    archivedCards,

    createAccount,
    archiveAccountMutation,
    unarchiveAccountMutation,
    deleteAccountMutation,
    bulkCreateTransactions,

    deleteCardConfirm,
    setDeleteCardConfirm,
    deleteCardCanDelete,
    selectedCardCanDelete,

    editingTransaction,
    setEditingTransaction,
    deleteConfirm,
    setDeleteConfirm,

    showEditCardDialog,
    setShowEditCardDialog,
    editCardName,
    setEditCardName,
    editCardColor,
    setEditCardColor,
    editClosingDay,
    setEditClosingDay,
    editDueDay,
    setEditDueDay,
    editLimit,
    setEditLimit,
    editBankId,
    setEditBankId,
    editCustomBankName,
    setEditCustomBankName,

    invoiceData,
    invoiceFetching,

    getCardInvoice,
    getCardInstallments,
    formatCurrency,
    getDaysUntilDue,

    handleCreateCard,
    handleDeleteTransaction,
    handleEditCard,
    handleExportCards,
    handlePayInvoice,

    totalInvoices,
    totalDebt,
    nextDueDate,
    exportTransactions,
    closingOverride,

    refetchAccounts,
    refetchTransactions,
  };
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { dateUtils } from "@/utils/dateUtils";
import { calculateTransactionSplits } from "@/utils/sharedFinanceCalculations";
import {
  invalidateFinancialQueries,
  invalidateSharedQueries,
  invalidateTripQueries,
} from "@/utils/queryInvalidation";
import { transactionToasts } from "@/utils/toastMessages";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { logger } from "@/utils/logger";
import {
  generateAllNotifications,
  dismissRelatedNotifications,
} from "@/services/notificationGenerator";
import { createNotification } from "@/services/notificationService";
import { CategoryPredictionService } from "@/services/categoryPredictionService";
import { matchAutoShareRule, AutoShareRule } from "@/hooks/useAutoShareRules";
import { CreateTransactionInput, Transaction } from "./types";
import { validatePayerId } from "./helpers";
import { useRef, useEffect } from "react";

export function useCreateTransaction() {
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const inFlightRef = useRef(false);

  // [B-16] Reset inFlightRef on unmount para evitar bloqueio permanente
  // se o usu├írio navegar durante um submit
  useEffect(() => {
    return () => {
      inFlightRef.current = false;
    };
  }, []);

  return useMutation({
    onMutate: async (newTx) => {
      // Cancelar refetches de transa├º├Áes para n├úo sobrescrever nossa atualiza├º├úo otimista
      await queryClient.cancelQueries({ queryKey: ["transactions"] });
      await queryClient.cancelQueries({ queryKey: ["dashboard_data"] });

      // Save previous data for all transaction queries in case we need to rollback
      const previousTransactions = queryClient.getQueriesData({ queryKey: ["transactions"] });

      // Injetar transa├º├úo tempor├íria em todas as consultas relacionadas a transa├º├Áes na UI
      if (user) {
        queryClient.setQueriesData(
          { queryKey: ["transactions"] },
          (old: Transaction[] | undefined) => {
            const optimisticTx = {
              id: `temp-${Date.now()}`,
              user_id: user.id,
              creator_user_id: user.id,
              amount: newTx.amount,
              description: newTx.description,
              date: newTx.date,
              type: newTx.type,
              account_id: newTx.account_id,
              category_id: newTx.category_id,
              is_shared: newTx.is_shared,
              domain: newTx.domain || "PERSONAL",
              created_at: new Date().toISOString(),
              is_optimistic: true, // ├Ütil caso queiramos mostrar um ├¡cone de carregando
              category: { id: newTx.category_id, name: "...", icon: "ÔÅ│" },
              account: { id: newTx.account_id, name: "..." },
            };

            if (!old) return [optimisticTx] as Transaction[];
            return [optimisticTx, ...old] as Transaction[];
          }
        );
      }

      return { previousTransactions };
    },
    mutationFn: async (input: CreateTransactionInput) => {
      if (!user) throw new Error("User not authenticated");
      if (inFlightRef.current) throw new Error("Submiss├úo em andamento. Aguarde.");
      inFlightRef.current = true;

      // Ô£à PARALELIZAR CONSULTAS INICIAIS
      const accDataPromise = input.account_id
        ? supabase
            .from("accounts")
            .select("type, closing_day")
            .eq("id", input.account_id)
            .maybeSingle()
        : Promise.resolve({ data: null });

      const memberDataPromise = supabase
        .from("family_members")
        .select("id")
        .eq("linked_user_id", user.id)
        .maybeSingle();

      // [B-17] Duplicate check ÔÇö verifica transa├º├Áes recentes (├║ltimos 60s)
      // sem .gt("created_at",...) para evitar erros 400 de formato de timestamp no PostgREST
      const recentWindow = new Date(Date.now() - 60000).toISOString().replace(/\.\d{3}Z$/, "Z");

      const existingTxPromise = supabase
        .from("transactions")
        .select("id")
        .eq("user_id", user.id)
        .eq("amount", input.amount)
        .eq("description", (input.description || "").trim())
        .eq("date", input.date)
        .is("deleted_at", null)
        .gte("created_at", recentWindow)
        .maybeSingle();

      const existingTxPromise2 = input.account_id
        ? supabase
            .from("transactions")
            .select("id")
            .eq("user_id", user.id)
            .eq("amount", input.amount)
            .eq("description", (input.description || "").trim())
            .eq("date", input.date)
            .eq("account_id", input.account_id)
            .is("deleted_at", null)
            .gte("created_at", recentWindow)
            .maybeSingle()
        : Promise.resolve({ data: null });

      const [accResult, memberResult, existingTxResult, existingTxResult2] = await Promise.all([
        accDataPromise,
        memberDataPromise,
        existingTxPromise,
        existingTxPromise2,
      ]);

      let cardClosingDay: number | null = null;
      if (accResult.data && accResult.data.type === "CREDIT_CARD") {
        cardClosingDay = accResult.data.closing_day || 1;
      }

      const calculateCompetence = (dateStr: string) => {
        const d = dateUtils.parseDate(dateStr);
        if (cardClosingDay !== null) {
          const day = d.getUTCDate();
          let compMonth = d.getUTCMonth();
          let compYear = d.getUTCFullYear();
          if (day >= cardClosingDay) {
            compMonth++;
            if (compMonth > 11) {
              compMonth = 0;
              compYear++;
            }
          }
          return `${compYear}-${String(compMonth + 1).padStart(2, "0")}-01`;
        }
        return dateUtils.getCompetenceDate(d);
      };

      // Resolve o family_member ID do criador para uso consistente em splits
      const myFamilyMemberId = memberResult.data?.id || null;

      // Ô£à VALIDA├ç├âO: Payer ID (Quem pagou)
      let resolvedPayerId = input.payer_id;

      if (input.is_shared && !resolvedPayerId) {
        if (myFamilyMemberId) {
          resolvedPayerId = myFamilyMemberId;
          input.payer_id = resolvedPayerId;
        } else {
          // Fallback final: Tentar encontrar admin se necess├írio
          const { data: adminMember } = await supabase
            .from("family_members")
            .select("id")
            .eq("role", "admin")
            .limit(1)
            .maybeSingle();

          if (adminMember) {
            resolvedPayerId = adminMember.id;
            input.payer_id = resolvedPayerId;
          } else {
            throw new Error("N├úo foi poss├¡vel identificar seu perfil de membro.");
          }
        }
      }

      // Validar payer_id se fornecido
      if (input.payer_id) {
        await validatePayerId(input.payer_id);
      }

      // Ô£à VALIDA├ç├âO E AUTO-COMPLETAGEM DE SPLITS
      const finalSplits = [...(input.splits || [])];

      if (input.is_shared) {
        const totalPercentage = finalSplits.reduce(
          (sum, s) => SafeFinancialCalculator.add(sum, Number(s.percentage || 0)),
          0
        );

        if (totalPercentage > 100) {
          throw new Error(
            `A soma das porcentagens n├úo pode exceder 100% (atualmente: ${totalPercentage.toFixed(1)}%)`
          );
        }

        if (finalSplits.length === 0) {
          throw new Error("Transa├º├úo compartilhada deve ter pelo menos um membro selecionado.");
        }

        if (totalPercentage < 100) {
          const remainingPercentage = 100 - totalPercentage;
          // Guard: floating-point imprecision can produce a near-zero remainder ÔÇö skip it
          if (remainingPercentage >= 0.01) {
            const mySplitIndex = finalSplits.findIndex(
              (s) => s.member_id === myFamilyMemberId || s.member_id === user!.id
            );

            if (mySplitIndex >= 0) {
              const currentPct = finalSplits[mySplitIndex].percentage || 0;
              const newPct = currentPct + remainingPercentage;

              finalSplits[mySplitIndex] = {
                ...finalSplits[mySplitIndex],
                percentage: newPct,
                amount: SafeFinancialCalculator.percentage(input.amount, newPct),
              };
            } else if (myFamilyMemberId) {
              finalSplits.push({
                member_id: myFamilyMemberId,
                percentage: remainingPercentage,
                amount: SafeFinancialCalculator.percentage(input.amount, remainingPercentage),
              });
            }
          }
        }
      }

      if (input.amount <= 0) {
        throw new Error("O valor da transa├º├úo deve ser maior que zero");
      }

      if (!input.description || input.description.trim() === "") {
        throw new Error("A descri├º├úo ├® obrigat├│ria");
      }

      // [B-17] TRAVA DE DUPLICIDADE ÔÇö janela de 15s, com e sem account_id
      if (existingTxResult.data || existingTxResult2?.data) {
        throw new Error(
          "ÔÜá´©Å Transa├º├úo duplicada detectada! Aguarde alguns segundos ou verifique se j├í foi lan├ºada."
        );
      }

      const { splits, transaction_splits, ...transactionData } = input;

      // Parcelamento ÔÇö usa RPC at├┤mica (ARC-02: rollback autom├ítico se splits falharem)
      if (input.is_installment && input.total_installments && input.total_installments > 1) {
        const seriesId = input.series_id || crypto.randomUUID();
        const startingInstallment = input.current_installment || 1;
        const installmentsToCreate = input.total_installments - startingInstallment + 1;

        const installmentAmount = SafeFinancialCalculator.calculateInstallment(
          input.amount,
          input.total_installments // divisor ├® o TOTAL de parcelas, n├úo as restantes
        );

        const baseDate = dateUtils.parseDate(input.date);

        // Resolve member data before building transactions (needed for embedded splits)
        let memberNames: Record<string, string> = {};
        let memberUserIds: Record<string, string> = {};
        let userIdToMemberId: Record<string, string> = {};
        let userIdToName: Record<string, string> = {};

        if (finalSplits && finalSplits.length > 0) {
          const memberIds = finalSplits.map((s) => s.member_id);
          const { data: membersData } = await supabase
            .from("family_members")
            .select("id, name, linked_user_id")
            .or(`id.in.(${memberIds.join(",")}),linked_user_id.in.(${memberIds.join(",")})`);

          membersData?.forEach((m) => {
            memberNames[m.id] = m.name;
            if (m.linked_user_id) {
              memberUserIds[m.id] = m.linked_user_id;
              userIdToMemberId[m.linked_user_id] = m.id;
              userIdToName[m.linked_user_id] = m.name;
            }
          });

          const invalidMembers = memberIds.filter(
            (id) => id !== user.id && !memberNames[id] && !userIdToName[id]
          );
          if (invalidMembers.length > 0) {
            logger.error("Membros de split inv├ílidos detectados:", invalidMembers);
            throw new Error("Um ou mais membros selecionados para divis├úo n├úo s├úo v├ílidos.");
          }
        }

        const transactionsForRpc = [];
        let allocatedAmount = SafeFinancialCalculator.ZERO;

        for (let i = 0; i < installmentsToCreate; i++) {
          const currentInstNum = startingInstallment + i;
          const installmentDate = dateUtils.addMonthsToDate(baseDate, i);
          const formattedDate = dateUtils.formatDate(installmentDate);
          const competenceDate = calculateCompetence(formattedDate);
          const isSharedNow = (finalSplits && finalSplits.length > 0) || input.domain === "SHARED";

          let currentAmount = installmentAmount;
          if (i === installmentsToCreate - 1) {
            currentAmount = SafeFinancialCalculator.subtract(input.amount, allocatedAmount);
          } else {
            allocatedAmount = SafeFinancialCalculator.add(allocatedAmount, currentAmount);
          }

          // Build embedded splits for this installment
          let embeddedSplits: Record<string, unknown>[] = [];
          if (finalSplits && finalSplits.length > 0) {
            const splitResults = calculateTransactionSplits(
              currentAmount.toNumber(),
              finalSplits,
              myFamilyMemberId || user.id
            );
            embeddedSplits = splitResults.map((split) => {
              const isUserId = !memberNames[split.member_id] && userIdToName[split.member_id];
              return {
                member_id: isUserId ? userIdToMemberId[split.member_id] : split.member_id,
                user_id: isUserId ? split.member_id : memberUserIds[split.member_id],
                percentage: split.percentage,
                amount: split.amount,
                name:
                  (isUserId ? userIdToName[split.member_id] : memberNames[split.member_id]) ||
                  "Membro",
              };
            });
          }

          transactionsForRpc.push({
            ...transactionData,
            amount: currentAmount.toNumber(),
            date: formattedDate,
            competence_date: competenceDate,
            description: `${input.description} (${currentInstNum}/${input.total_installments})`,
            current_installment: currentInstNum,
            series_id: seriesId,
            is_shared: isSharedNow,
            domain: input.trip_id ? "TRAVEL" : isSharedNow ? "SHARED" : input.domain || "PERSONAL",
            payer_id: input.payer_id,
            splits: embeddedSplits,
          });
        }

        const { data: rpcData, error } = await supabase.rpc("create_installment_series", {
          p_transactions: transactionsForRpc,
          p_user_id: user.id,
        });

        if (error) {
          logger.error("Erro ao criar parcelas (RPC at├┤mica):", error);
          throw error;
        }

        if (finalSplits && finalSplits.length > 0) {
          try {
            const otherUserIds = Array.from(
              new Set(
                finalSplits
                  .map((s) => {
                    const isUserId = !memberNames[s.member_id] && userIdToName[s.member_id];
                    return isUserId ? s.member_id : memberUserIds[s.member_id];
                  })
                  .filter((uid): uid is string => !!uid && uid !== user?.id)
              )
            );

            await Promise.all(
              otherUserIds.map((otherUserId) =>
                createNotification({
                  user_id: otherUserId,
                  type: "SHARED_EXPENSE",
                  title: "Novas Transa├º├Áes Compartilhadas",
                  message: `${user?.user_metadata?.name || user?.email || "Algu├®m"} criou uma transa├º├úo parcelada compartilhada "${input.description}".`,
                  icon: "­ƒñØ",
                  priority: "NORMAL",
                }).catch((e) =>
                  logger.error("Erro ao criar notifica├º├úo de parcelamento compartilhado:", e)
                )
              )
            );
          } catch (notificationError) {
            logger.error(
              "Erro ao notificar cria├º├úo de parcelamento compartilhado:",
              notificationError
            );
          }
        }

        return rpcData;
      }

      // Transa├º├úo ├║nica
      let categoryId = input.category_id;

      if (!categoryId && (input.type === "EXPENSE" || input.type === "INCOME")) {
        try {
          const prediction = await CategoryPredictionService.predictCategory(
            input.description,
            user.id,
            input.type.toLowerCase() as "expense" | "income"
          );

          if (prediction && prediction.confidence > 0.5) {
            categoryId = prediction.categoryId;
            logger.debug("Categoriza├º├úo autom├ítica aplicada", {
              description: input.description,
              categoryId,
              confidence: prediction.confidence,
              reason: prediction.reason,
            });
          }
        } catch (error) {
          logger.warn("Categoriza├º├úo autom├ítica falhou, continuando sem categoria", { error });
        }
      }

      // Auto-share: verificar regras configuradas pelo usu├írio
      if (input.type === "EXPENSE" && (!finalSplits || finalSplits.length === 0)) {
        try {
          const { data: autoRules } = await supabase
            .from("transaction_auto_share_rules")
            .select("*")
            .eq("user_id", user.id)
            .eq("is_active", true);

          if (autoRules && autoRules.length > 0) {
            const matched = matchAutoShareRule(
              autoRules as AutoShareRule[],
              categoryId,
              input.description
            );
            if (matched) {
              const otherPct = matched.split_ratio * 100;
              finalSplits.push({
                member_id: matched.member_id,
                percentage: otherPct,
              });
              // Criador tamb├®m precisa de split expl├¡cito ÔÇö sen├úo o ├║ltimo split
              // (que ├® o outro membro) absorve 100% em calculateTransactionSplits.
              // S├│ adiciona se o criador tiver participa├º├úo (evita split com 0%).
              const myPct = 100 - otherPct;
              if (myPct > 0 && myFamilyMemberId) {
                finalSplits.push({
                  member_id: myFamilyMemberId,
                  percentage: myPct,
                });
              }
            }
          }
        } catch {
          // silencioso: auto-share n├úo deve bloquear cria├º├úo
        }
      }

      const isSharedNow = (finalSplits && finalSplits.length > 0) || input.domain === "SHARED";

      // Transa├º├úo ├║nica ÔÇö usa RPC at├┤mica se tiver splits (ARC-01)
      const txPayload = {
        competence_date: input.competence_date || calculateCompetence(input.date),
        ...transactionData,
        category_id: categoryId,
        is_shared: isSharedNow,
        domain: input.trip_id ? "TRAVEL" : isSharedNow ? "SHARED" : input.domain || "PERSONAL",
        payer_id: input.payer_id,
        is_recurring: input.is_recurring || false,
        recurrence_pattern: input.frequency || null,
        recurrence_day: input.recurrence_day || null,
      };

      let data: Transaction | null;

      if (finalSplits && finalSplits.length > 0) {
        const memberIds = finalSplits.map((s) => s.member_id);
        const { data: membersData } = await supabase
          .from("family_members")
          .select("id, name, linked_user_id")
          .or(`id.in.(${memberIds.join(",")}),linked_user_id.in.(${memberIds.join(",")})`);

        const memberNames: Record<string, string> = {};
        const memberUserIds: Record<string, string> = {};
        const userIdToMemberId: Record<string, string> = {};
        const userIdToName: Record<string, string> = {};

        membersData?.forEach((m) => {
          memberNames[m.id] = m.name;
          if (m.linked_user_id) {
            memberUserIds[m.id] = m.linked_user_id;
            userIdToMemberId[m.linked_user_id] = m.id;
            userIdToName[m.linked_user_id] = m.name;
          }
        });

        const splitResults = calculateTransactionSplits(
          input.amount,
          finalSplits,
          myFamilyMemberId || user.id
        );
        const splitsPayload = splitResults.map((split) => {
          const isUserId = !memberNames[split.member_id] && userIdToName[split.member_id];
          return {
            member_id: isUserId ? userIdToMemberId[split.member_id] : split.member_id,
            user_id: isUserId ? split.member_id : memberUserIds[split.member_id],
            percentage: split.percentage,
            amount: split.amount,
            name:
              (isUserId ? userIdToName[split.member_id] : memberNames[split.member_id]) || "Membro",
            is_settled: false,
          };
        });

        const { data: rpcResult, error: rpcError } = await supabase.rpc(
          "create_transaction_with_splits",
          {
            p_transaction: txPayload,
            p_splits: splitsPayload,
            p_user_id: user.id,
          }
        );

        if (rpcError) {
          logger.error(
            "Erro ao criar transa├º├úo+splits (RPC at├┤mica), tentando fallback direto:",
            rpcError
          );

          // Fallback: insert transaction + splits diretamente
          const { data: fallbackTx, error: fallbackTxError } = await supabase
            .from("transactions")
            .insert({ user_id: user.id, creator_user_id: user.id, ...txPayload })
            .select()
            .single();

          if (fallbackTxError) {
            logger.error("Fallback transaction insert tamb├®m falhou:", fallbackTxError);
            throw fallbackTxError;
          }

          // Insert splits
          if (splitsPayload.length > 0) {
            const splitsToInsert = splitsPayload.map((s: Record<string, unknown>) => ({
              ...s,
              transaction_id: fallbackTx.id,
            }));
            const { error: splitsError } = await supabase
              .from("transaction_splits")
              .insert(splitsToInsert);

            if (splitsError) {
              logger.error(
                "Fallback splits insert falhou, tentando deletar transaction ├│rf├ú:",
                splitsError
              );
              await supabase.from("transactions").delete().eq("id", fallbackTx.id);
              throw splitsError;
            }
          }

          data = fallbackTx;
        } else {
          data = rpcResult;
        }
      } else {
        const { data: inserted, error } = await supabase
          .from("transactions")
          .insert({ user_id: user.id, creator_user_id: user.id, ...txPayload })
          .select()
          .single();

        if (error) {
          logger.error("Erro ao criar transa├º├úo:", error);
          throw error;
        }

        data = inserted;
      }

      const isTransactionShared =
        (finalSplits && finalSplits.length > 0) ||
        data?.domain === "SHARED" ||
        input.domain === "SHARED";
      if (data && isTransactionShared) {
        try {
          const { data: splitsData } = await supabase
            .from("transaction_splits")
            .select("user_id")
            .eq("transaction_id", data.id);

          if (splitsData && splitsData.length > 0) {
            const otherUserIds = Array.from(
              new Set(splitsData.map((s) => s.user_id).filter((uid) => uid && uid !== user?.id))
            );
            await Promise.all(
              otherUserIds.map((otherUserId) =>
                createNotification({
                  user_id: otherUserId,
                  type: "SHARED_EXPENSE",
                  title: "Nova Transa├º├úo Compartilhada",
                  message: `${user?.user_metadata?.name || user?.email || "Algu├®m"} criou a transa├º├úo compartilhada "${data.description}".`,
                  icon: "­ƒñØ",
                  priority: "NORMAL",
                }).catch((e) =>
                  logger.error("Erro ao criar notifica├º├úo de cria├º├úo compartilhada:", e)
                )
              )
            );
          }
        } catch (notificationError) {
          logger.error("Erro ao notificar cria├º├úo de compartilhada:", notificationError);
        }
      }

      return data as Transaction;
    },
    onSuccess: async (_data, variables) => {
      if (user?.id) {
        if (variables?.type === "TRANSFER" && variables?.destination_account_id) {
          dismissRelatedNotifications(
            user.id,
            variables.destination_account_id,
            "credit_card"
          ).catch((e) => logger.error("Erro dismiss", e));
        }
        generateAllNotifications(user.id).catch((e) =>
          logger.error("Erro ao gerar notifica├º├Áes p├│s-transa├º├úo", e)
        );
      }
    },
    onError: (
      error,
      _newTx,
      context: { previousTransactions: [unknown, unknown][] } | undefined
    ) => {
      if (context?.previousTransactions) {
        context.previousTransactions.forEach(([queryKey, data]) => {
          queryClient.setQueryData(
            queryKey as Parameters<typeof queryClient.setQueryData>[0],
            data
          );
        });
      }
      // Error feedback is handled by performSubmit catch block
    },
    onSettled: () => {
      inFlightRef.current = false;
      // Ao finalizar (sucesso ou erro), revalidamos os dados finais
      invalidateFinancialQueries(queryClient);
      invalidateSharedQueries(queryClient);
      invalidateTripQueries(queryClient);
    },
  });
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { dateUtils } from "@/utils/dateUtils";
import {
  invalidateFinancialQueries,
  invalidateSharedQueries,
  invalidateTripQueries,
} from "@/utils/queryInvalidation";
import { transactionToasts } from "@/utils/toastMessages";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { logger } from "@/utils/logger";
import { generateAllNotifications } from "@/services/notificationGenerator";
import { createNotification } from "@/services/notificationService";
import { CreateTransactionInput, Transaction } from "./types";
import { validatePayerId } from "./helpers";
import { toast } from "sonner";
import { rpcWithRetry } from "@/utils/rpcWithRetry";

export function useBulkCreateTransactions() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (inputs: CreateTransactionInput[]) => {
      if (!user) throw new Error("Usu├írio n├úo autenticado");

      const transactionsToInsert = inputs.map((input) => {
        const { splits, transaction_splits, ...transactionData } = input;

        return {
          user_id: user.id,
          creator_user_id: user.id,
          ...transactionData,
        };
      });

      const { data, error } = await supabase
        .from("transactions")
        .insert(transactionsToInsert)
        .select();

      if (error) {
        logger.error("Erro ao criar transa├º├Áes em lote:", error);
        throw new Error(`Erro ao criar transa├º├Áes em lote: ${error.message}`);
      }

      return data as Transaction[];
    },
    onSuccess: async () => {
      // Run invalidations
      invalidateFinancialQueries(queryClient);
      invalidateSharedQueries(queryClient);
      invalidateTripQueries(queryClient);
      transactionToasts.created();
    },
    onError: (error) => {
      transactionToasts.error("criar", error);
    },
  });
}

export function useUpdateTransaction() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    onMutate: async (updateData: Partial<Transaction> & { id: string }) => {
      await queryClient.cancelQueries({ queryKey: ["transactions"] });
      const previousTransactions = queryClient.getQueriesData({ queryKey: ["transactions"] });

      if (user) {
        queryClient.setQueriesData({ queryKey: ["transactions"] }, (old: Transaction[]) => {
          if (!Array.isArray(old)) return old;
          return old.map((tx) => (tx.id === updateData.id ? { ...tx, ...updateData } : tx));
        });
      }
      return { previousTransactions };
    },
    mutationFn: async ({ id, ...updateData }: Partial<Transaction> & { id: string }) => {
      if (!user) throw new Error("Usu├írio n├úo autenticado");

      // Verificar se a transa├º├úo j├í foi liquidada OU tem splits com acertos parciais
      const { data: existingTx } = await supabase
        .from("transactions")
        .select("is_settled")
        .eq("id", id)
        .single();

      if (existingTx?.is_settled) {
        throw new Error(
          "Esta transa├º├úo j├í foi liquidada/acertada. Desfa├ºa o acerto antes de edit├í-la."
        );
      }

      // Verificar se h├í splits com acertos parciais (settled_by_debtor/creditor)
      const { data: existingSplits } = await supabase
        .from("transaction_splits")
        .select("id, is_settled, settled_by_debtor, settled_by_creditor")
        .eq("transaction_id", id);

      if (
        existingSplits?.some((s) => s.is_settled || s.settled_by_debtor || s.settled_by_creditor)
      ) {
        throw new Error(
          "Esta transa├º├úo possui acertos parciais. Desfa├ºa os acertos antes de edit├í-la."
        );
      }

      // Validate payer_id and members if they are being updated
      if (updateData.payer_id !== undefined) {
        await validatePayerId(updateData.payer_id);
      }

      // We update splits separately since they are in another table.
      const { splits, transaction_splits, ...restUpdateData } =
        updateData as Partial<Transaction> & {
          splits?: TransactionSplitData[];
          transaction_splits?: TransactionSplitData[];
        };
      const actualSplits = transaction_splits || splits;

      const { data, error } = await supabase
        .from("transactions")
        .update({
          ...restUpdateData,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id)
        .eq("user_id", user.id)
        .select()
        .single();

      if (error) {
        logger.error("Erro ao atualizar transa├º├úo:", error);
        throw new Error(`Erro ao atualizar transa├º├úo: ${error.message}`);
      }

      if (actualSplits) {
        const finalSplits = [...actualSplits];

        // Auto-completar splits se a soma for menor que 100% (Crit├®rio #6: O pr├│prio criador assume o restante)
        if (finalSplits.length > 0) {
          const totalPercentage = SafeFinancialCalculator.safeSum(
            finalSplits.map((s: TransactionSplitData) => s.percentage)
          );
          if (totalPercentage < 100) {
            const remainingPercentage = SafeFinancialCalculator.subtract(100, totalPercentage);
            const { data: currentUserMember } = await supabase
              .from("family_members")
              .select("id")
              .eq("linked_user_id", user.id)
              .maybeSingle();

            if (currentUserMember) {
              finalSplits.push({
                member_id: currentUserMember.id,
                percentage: remainingPercentage,
                amount: SafeFinancialCalculator.percentage(data.amount, remainingPercentage),
              });
            }
          }
        }

        // Save existing splits so we can restore them if the insert fails
        const { data: existingSplits } = await supabase
          .from("transaction_splits")
          .select("*")
          .eq("transaction_id", id);

        await supabase.from("transaction_splits").delete().eq("transaction_id", id);

        // Inserir os novos
        if (finalSplits.length > 0) {
          const memberIds = finalSplits.map((s: TransactionSplitData) => s.member_id);
          const { data: membersData } = await supabase
            .from("family_members")
            .select("id, name, linked_user_id")
            .or(`id.in.(${memberIds.join(",")}),linked_user_id.in.(${memberIds.join(",")})`);

          const memberNames: Record<string, string> = {};
          const memberUserIds: Record<string, string> = {};
          const userIdToMemberId: Record<string, string> = {};
          const userIdToName: Record<string, string> = {};

          membersData?.forEach((m) => {
            memberNames[m.id] = m.name;
            if (m.linked_user_id) {
              memberUserIds[m.id] = m.linked_user_id;
              userIdToMemberId[m.linked_user_id] = m.id;
              userIdToName[m.linked_user_id] = m.name;
            }
          });

          let allocatedSum = 0;
          const splitsToInsert = finalSplits.map((split: TransactionSplitData, index: number) => {
            const isUserId = !memberNames[split.member_id] && userIdToName[split.member_id];
            const actualMemberId = isUserId ? userIdToMemberId[split.member_id] : split.member_id;
            const actualUserId = isUserId ? split.member_id : memberUserIds[split.member_id];
            const actualName = isUserId
              ? userIdToName[split.member_id]
              : memberNames[split.member_id];

            let splitAmount = 0;
            if (index === finalSplits.length - 1) {
              splitAmount = SafeFinancialCalculator.subtract(data.amount, allocatedSum);
            } else {
              const baseAmount =
                split.amount !== undefined
                  ? split.amount
                  : SafeFinancialCalculator.percentage(data.amount, split.percentage);
              splitAmount = baseAmount;
              allocatedSum = SafeFinancialCalculator.add(allocatedSum, splitAmount);
            }

            return {
              transaction_id: id,
              member_id: actualMemberId,
              user_id: actualUserId,
              percentage: split.percentage,
              amount: splitAmount,
              name: actualName || "Membro",
              is_settled: false,
            };
          });

          const { error: splitsError } = await supabase
            .from("transaction_splits")
            .insert(splitsToInsert);

          if (splitsError) {
            // Restore original splits to avoid data loss
            if (existingSplits && existingSplits.length > 0) {
              await supabase.from("transaction_splits").insert(existingSplits);
            }
            logger.error("Erro ao atualizar splits:", splitsError);
            throw new Error(`Erro ao atualizar divis├Áes: ${splitsError.message}`);
          }
        }
      }

      return data as Transaction;
    },
    onSuccess: async () => {
      invalidateFinancialQueries(queryClient);
      invalidateSharedQueries(queryClient);
      invalidateTripQueries(queryClient);
      showActionFeedback("success");
    },
    onError: (error, _variables, context: { previousTransactions?: [QueryKey, unknown][] }) => {
      if (context?.previousTransactions) {
        context.previousTransactions.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
      showActionFeedback("error");
    },
  });
}

export function useDeleteTransaction() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    onMutate: async ({ id, cascadeType = "NONE" }) => {
      await queryClient.cancelQueries({ queryKey: ["transactions"] });
      const previousTransactions = queryClient.getQueriesData({ queryKey: ["transactions"] });

      if (user) {
        queryClient.setQueriesData({ queryKey: ["transactions"] }, (old: Transaction[]) => {
          if (!Array.isArray(old)) return old;
          return old.filter((tx) => tx.id !== id);
        });
      }
      return { previousTransactions };
    },
    mutationFn: async ({
      id,
      cascadeType = "NONE",
    }: {
      id: string;
      cascadeType?: "ALL" | "NEXT" | "NONE";
    }) => {
      // 1. Buscar a transa├º├úo antes de deletar
      const { data: existingTx } = await supabase
        .from("transactions")
        .select(
          "is_shared, domain, description, user_id, is_settled, series_id, current_installment"
        )
        .eq("id", id)
        .maybeSingle();

      if (existingTx && existingTx.is_settled) {
        throw new Error(
          "Esta transa├º├úo j├í foi liquidada/acertada. Desfa├ºa o acerto antes de exclu├¡-la."
        );
      }

      // Verificar splits com acertos parciais
      const { data: existingSplits } = await supabase
        .from("transaction_splits")
        .select("id, is_settled, settled_by_debtor, settled_by_creditor")
        .eq("transaction_id", id);

      if (
        existingSplits?.some((s) => s.is_settled || s.settled_by_debtor || s.settled_by_creditor)
      ) {
        throw new Error(
          "Esta transa├º├úo possui acertos parciais. Desfa├ºa os acertos antes de exclu├¡-la."
        );
      }

      // 2. Se for compartilhada, buscar splits antes de deletar
      let otherUserIds: string[] = [];
      if (existingTx && (existingTx.is_shared || existingTx.domain === "SHARED")) {
        const { data: splitsData } = await supabase
          .from("transaction_splits")
          .select("user_id")
          .eq("transaction_id", id);

        if (splitsData && splitsData.length > 0) {
          otherUserIds = Array.from(
            new Set(splitsData.map((s) => s.user_id).filter((uid) => uid && uid !== user?.id))
          );
        }
      }

      // 3. Deletar a transa├º├úo (com l├│gica de cascata)
      let deleteQuery = supabase
        .from("transactions")
        .update({ deleted_at: new Date().toISOString() });

      if (cascadeType === "ALL" && existingTx?.series_id) {
        deleteQuery = deleteQuery.eq("series_id", existingTx.series_id);
      } else if (cascadeType === "NEXT" && existingTx?.series_id) {
        // Para NEXT, precisamos deletar onde series_id bate E current_installment >= tx.current_installment
        // Como o Supabase delete() com m├║ltiplos filtros funciona com AND, podemos fazer:
        deleteQuery = deleteQuery
          .eq("series_id", existingTx.series_id)
          .gte("current_installment", existingTx.current_installment || 1);
      } else {
        // Padr├úo (NONE) ou transa├º├úo sem s├®rie
        deleteQuery = deleteQuery.eq("id", id);
      }
      
      // Defesa em profundidade: garantir que s├│ o dono pode deletar
      deleteQuery = deleteQuery.eq("user_id", user.id);

      const { error } = await deleteQuery;

      if (error) throw error;

      // 4. Notificar outros membros
      if (existingTx && otherUserIds.length > 0) {
        try {
          // Fire and forget notification
          Promise.all(
            otherUserIds.map((otherUserId) =>
              createNotification({
                user_id: otherUserId,
                type: "SHARED_EXPENSE",
                title: "Transa├º├úo Exclu├¡da",
                message: `${user?.user_metadata?.name || user?.email || "Algu├®m"} excluiu a transa├º├úo compartilhada "${existingTx.description}".`,
                icon: "ÔØî",
                priority: "NORMAL",
              }).catch((e) =>
                logger.error("Erro ao criar notifica├º├úo de exclus├úo compartilhada:", e)
              )
            )
          );
        } catch (notificationError) {
          logger.error(
            "Erro ao tentar enviar notifica├º├úo de exclus├úo compartilhada:",
            notificationError
          );
        }
      }
    },
    onSuccess: async () => {
      // Run invalidations without awaiting to unblock UI instantly
      invalidateFinancialQueries(queryClient);
      invalidateSharedQueries(queryClient);
      invalidateTripQueries(queryClient);
      transactionToasts.deleted();

      // Ô£à INTELIG├èNCIA FINANCEIRA: Atualizar or├ºamentos e saldos em tempo real
      if (user?.id) {
        generateAllNotifications(user.id).catch((e) =>
          logger.error("Erro ao gerar notifica├º├Áes p├│s-exclus├úo", e)
        );
      }
    },
    onError: (error, _variables, context: { previousTransactions?: [QueryKey, unknown][] }) => {
      if (context?.previousTransactions) {
        context.previousTransactions.forEach(([queryKey, data]) => {
          queryClient.setQueryData(queryKey, data);
        });
      }
      transactionToasts.error("remover", error);
    },
  });
}

