import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { useRecalculateBalances } from "@/hooks/useAccountManagement";
import { logger } from "@/utils/logger";

// A senha administrativa n├úo ├® mais mantida em texto puro no c├│digo do frontend
const CONFIRM_WORD = "RESETAR";

interface EnrichedUser {
  id: string;
  email: string;
  full_name: string | null;
  created_at: string;
  avatar_color: string | null;
  avatar_icon: string | null;
  accountsCount: number;
  transactionsCount: number;
  assetsCount: number;
  totalBalance: number;
}

interface AuditLog {
  id: string;
  user_id: string | null;
  operation: string;
  table_name: string;
  record_id: string;
  old_data: Record<string, unknown> | null;
  new_data: Record<string, unknown> | null;
  created_at: string;
}

interface ErrorLog {
  id: string;
  user_id: string | null;
  user_email: string | null;
  error_message: string;
  stack_trace: string | null;
  context: string | null;
  status: string;
  created_at: string;
}

interface SystemStats {
  totalUsers: number;
  totalTransactions: number;
  totalVolume: number;
  totalAccounts: number;
  totalFamilies: number;
  totalAssets: number;
}

export function useAdminActions() {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [passwordError, setPasswordError] = useState(false);

  // States
  const [enrichedUsers, setEnrichedUsers] = useState<EnrichedUser[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [errorLogs, setErrorLogs] = useState<ErrorLog[]>([]);
  const [stats, setStats] = useState<SystemStats>({
    totalUsers: 0,
    totalTransactions: 0,
    totalVolume: 0,
    totalAccounts: 0,
    totalFamilies: 0,
    totalAssets: 0,
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [selectedUser, setSelectedUser] = useState<string>("all");
  const [confirmWord, setConfirmWord] = useState("");
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  // Loading states
  const [isLoadingStats, setIsLoadingStats] = useState(false);
  const [isLoadingUsers, setIsLoadingUsers] = useState(false);
  const [isLoadingLogs, setIsLoadingLogs] = useState(false);
  const [isLoadingErrorLogs, setIsLoadingErrorLogs] = useState(false);
  const [isPurging, setIsPurging] = useState(false);
  const [isInjectingCategories, setIsInjectingCategories] = useState(false);
  const [isRecalculatingTarget, setIsRecalculatingTarget] = useState<string | null>(null);
  const [isResettingPassword, setIsResettingPassword] = useState<string | null>(null);

  const handleResetUserPassword = async (email: string, userId: string) => {
    setIsResettingPassword(userId);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}`,
      });

      if (error) throw error;

      toast.success(`E-mail de redefini├º├úo de senha enviado com sucesso para ${email}!`);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Unknown error";
      logger.error("Error sending reset email:", error);
      toast.error(`Erro ao disparar redefini├º├úo de senha: ${message}`);
    } finally {
      setIsResettingPassword(null);
    }
  };

  const [userDetailOpen, setUserDetailOpen] = useState(false);
  const [selectedDetailUser, setSelectedDetailUser] = useState<EnrichedUser | null>(null);
  const [detailAccounts, setDetailAccounts] = useState<any[]>([]);
  const [detailFamilies, setDetailFamilies] = useState<any[]>([]);
  const [isLoadingDetails, setIsLoadingDetails] = useState(false);

  const [selectedErrorLog, setSelectedErrorLog] = useState<ErrorLog | null>(null);
  const [errorDetailOpen, setErrorDetailOpen] = useState(false);

  // Unified parser for database change-data-capture logs
  const parseAuditLog = (log: AuditLog) => {
    const op = log.operation || "OUTRO";
    const tbl = log.table_name || "";

    let opType = `${op} - ${tbl.toUpperCase()}`;
    let reason = `Registro de ${tbl} modificado.`;
    let amount: number | null = null;
    let currency = "BRL";
    let isSettlement = false;
    const isBlocked = false;

    if (tbl === "transactions") {
      const data = log.new_data || log.old_data || {};
      amount = data.amount ? Number(data.amount) : null;
      currency = data.currency || "BRL";
      const desc = data.description || "";

      if (op === "INSERT") {
        opType = "NOVA TRANSA├ç├âO";
        reason = `Transa├º├úo inserida: "${desc}"`;
      } else if (op === "UPDATE") {
        opType = "TRANSA├ç├âO EDITADA";
        reason = `Transa├º├úo alterada: "${desc}"`;
      } else if (op === "DELETE") {
        opType = "TRANSA├ç├âO EXCLU├ìDA";
        reason = `Transa├º├úo removida definitivamente: "${desc}"`;
      }

      if (
        desc.toLowerCase().includes("acerto") ||
        desc.toLowerCase().includes("concilia├º├úo") ||
        data.is_settled
      ) {
        isSettlement = true;
      }
    } else if (tbl === "accounts") {
      const data = log.new_data || log.old_data || {};
      amount = data.balance ? Number(data.balance) : null;
      currency = data.currency || "BRL";
      const name = data.name || "";

      if (op === "INSERT") {
        opType = "NOVA CONTA";
        reason = `Conta criada: "${name}" (${data.type || ""})`;
      } else if (op === "UPDATE") {
        opType = "CONTA EDITADA";
        reason = `Conta alterada: "${name}"`;
      } else if (op === "DELETE") {
        opType = "CONTA EXCLU├ìDA";
        reason = `Conta removida definitivamente: "${name}"`;
      }
    } else if (tbl === "families") {
      const data = log.new_data || log.old_data || {};
      const name = data.name || "";
      if (op === "INSERT") {
        opType = "NOVA FAM├ìLIA";
        reason = `Grupo familiar criado: "${name}"`;
      } else if (op === "DELETE") {
        opType = "FAM├ìLIA REMOVIDA";
        reason = `Grupo familiar removido: "${name}"`;
      }
    } else {
      if (op === "INSERT") {
        opType = `NOVO - ${tbl.toUpperCase()}`;
        reason = `Inser├º├úo na tabela ${tbl} (ID: ${log.record_id})`;
      } else if (op === "UPDATE") {
        opType = `ATUALIZADO - ${tbl.toUpperCase()}`;
        reason = `Atualiza├º├úo na tabela ${tbl} (ID: ${log.record_id})`;
      } else if (op === "DELETE") {
        opType = `REMOVIDO - ${tbl.toUpperCase()}`;
        reason = `Exclus├úo na tabela ${tbl} (ID: ${log.record_id})`;
      }
    }

    return { opType, reason, amount, currency, isSettlement, isBlocked };
  };

  const handleAuthenticate = async () => {
    setIsLoadingStats(true);
    try {
      // Authentication is now handled by the DB via is_admin() (admin_users table).
      // The password field in the UI is kept as an extra local confirmation step,
      // but it is NOT sent to the database.
      const { data, error } = await supabase.rpc("get_admin_system_stats");
      if (error) throw error;

      setIsAuthenticated(true);
      setPasswordError(false);

      if (data) {
        setStats({
          totalUsers: Number((data as unknown as Record<string, any>).totalUsers) || 0,
          totalTransactions:
            Number((data as unknown as Record<string, any>).totalTransactions) || 0,
          totalVolume: Number((data as unknown as Record<string, any>).totalVolume) || 0,
          totalAccounts: Number((data as unknown as Record<string, any>).totalAccounts) || 0,
          totalFamilies: Number((data as unknown as Record<string, any>).totalFamilies) || 0,
          totalAssets: Number((data as unknown as Record<string, any>).totalAssets) || 0,
        });
      }

      loadUsersDetailed();
      loadAuditLogs();
      loadErrorLogs();
    } catch (error) {
      setPasswordError(true);
      toast.error("Credencial administrativa inv├ílida");
    } finally {
      setIsLoadingStats(false);
    }
  };

  const loadAllAdminData = () => {
    // loadSystemStats is now called in handleAuthenticate
    loadUsersDetailed();
    loadAuditLogs();
    loadErrorLogs();
  };

  const loadSystemStats = async () => {
    setIsLoadingStats(true);
    try {
      const { data, error } = await supabase.rpc("get_admin_system_stats");

      if (error) throw error;

      if (data) {
        setStats({
          totalUsers: Number((data as unknown as Record<string, any>).totalUsers) || 0,
          totalTransactions:
            Number((data as unknown as Record<string, any>).totalTransactions) || 0,
          totalVolume: Number((data as unknown as Record<string, any>).totalVolume) || 0,
          totalAccounts: Number((data as unknown as Record<string, any>).totalAccounts) || 0,
          totalFamilies: Number((data as unknown as Record<string, any>).totalFamilies) || 0,
          totalAssets: Number((data as unknown as Record<string, any>).totalAssets) || 0,
        });
      }
    } catch (error) {
      logger.error("Error loading stats:", error);
      toast.error("Erro ao carregar m├®tricas globais");
    } finally {
      setIsLoadingStats(false);
    }
  };

  const loadUsersDetailed = async () => {
    setIsLoadingUsers(true);
    try {
      const { data, error } = await supabase.rpc("get_admin_users_detailed");

      if (error) throw error;

      if (data) {
        const enriched = (data as unknown as EnrichedUser[]).map((u) => ({
          id: u.id,
          email: u.email,
          full_name: u.full_name,
          created_at: u.created_at,
          avatar_color: u.avatar_color,
          avatar_icon: u.avatar_icon,
          accountsCount: Number(u.accountsCount) || 0,
          transactionsCount: Number(u.transactionsCount) || 0,
          assetsCount: Number(u.assetsCount) || 0,
          totalBalance: Number(u.totalBalance) || 0,
        }));
        setEnrichedUsers(enriched);
      }
    } catch (error) {
      logger.error("Error enriching users:", error);
      toast.error("Erro ao processar dados dos usu├írios");
    } finally {
      setIsLoadingUsers(false);
    }
  };

  const loadAuditLogs = async () => {
    setIsLoadingLogs(true);
    try {
      const { data, error } = await supabase.rpc("get_admin_audit_logs");

      if (error) throw error;

      setAuditLogs(data || []);
    } catch (error) {
      logger.error("Error loading audit logs:", error);
      toast.error("Erro ao carregar logs de auditoria");
    } finally {
      setIsLoadingLogs(false);
    }
  };

  const loadErrorLogs = async () => {
    setIsLoadingErrorLogs(true);
    try {
      const { data, error } = await supabase.rpc("get_admin_error_logs");
      if (error) throw error;
      setErrorLogs(data || []);
    } catch (error) {
      logger.error("Error loading error logs:", error);
      toast.error("Erro ao carregar relat├│rios de erros");
    } finally {
      setIsLoadingErrorLogs(false);
    }
  };

  const resolveErrorLog = async (reportId: string) => {
    try {
      const { error } = await supabase.rpc("resolve_error_report", { p_report_id: reportId });
      if (error) throw error;
      toast.success("Erro marcado como resolvido!");
      loadErrorLogs();
      setErrorDetailOpen(false);
    } catch (error) {
      logger.error("Error resolving report:", error);
      toast.error("Erro ao marcar como resolvido");
    }
  };

  const handleClearErrorLogs = async () => {
    setIsPurging(true);
    try {
      const { error } = await supabase.rpc("clear_error_logs");

      if (error) throw error;

      toast.success("Logs de erro apagados com sucesso");
      loadErrorLogs();
    } catch (error) {
      toast.error("Erro ao apagar logs");
      logger.error(error);
    } finally {
      setIsPurging(false);
    }
  };

  const handleReset = async () => {
    if (confirmWord !== CONFIRM_WORD) {
      toast.error(`Digite "${CONFIRM_WORD}" para confirmar`);
      return;
    }

    setIsResetting(true);
    try {
      if (selectedUser === "all") {
        await resetAllUsers();
      } else {
        await resetSingleUser(selectedUser);
      }

      toast.success(
        selectedUser === "all"
          ? "Sistema resetado com sucesso!"
          : "Dados do usu├írio resetados com sucesso!"
      );

      setShowConfirmDialog(false);
      setConfirmWord("");
      loadAllAdminData();
    } catch (error) {
      logger.error("Reset error:", error);
      toast.error("Erro ao resetar sistema");
    } finally {
      setIsResetting(false);
    }
  };

  const resetAllUsers = async () => {
    // This RPC is now service_role only ÔÇö must be called from a server-side function, not the browser.
    throw new Error("admin_reset_all_data deve ser chamado via Edge Function com service_role.");
  };

  const resetSingleUser = async (userId: string) => {
    // This RPC is now service_role only ÔÇö must be called from a server-side function, not the browser.
    throw new Error("admin_reset_single_user deve ser chamado via Edge Function com service_role.");
  };

  const handlePurgeSoftDeleted = async () => {
    setIsPurging(true);
    try {
      // Purgamos apenas as contas marcadas como deletadas (accounts.deleted = true).
      // Como transactions n├úo tem soft-delete, a exclus├úo da conta propaga a remo├º├úo das transa├º├Áes vinculadas via cascade trigger.
      const { count: accCount, error: accErr } = await supabase
        .from("accounts")
        .delete({ count: "exact" })
        .eq("deleted", true);

      if (accErr) throw accErr;

      toast.success(
        `Limpeza conclu├¡da! ${accCount || 0} conta(s) inativa(s) deletada(s) definitivamente.`
      );
      loadSystemStats();
    } catch (error) {
      logger.error("Error purging soft-deletes:", error);
      toast.error("Erro ao purgar registros deletados");
    } finally {
      setIsPurging(false);
    }
  };

  const handleRecalculateTargetBalances = async (targetUserId: string) => {
    setIsRecalculatingTarget(targetUserId);
    try {
      const { data, error } = await supabase.rpc("recalculate_all_balances", {
        p_user_id: targetUserId,
      });

      if (error) throw error;

      toast.success(`Saldos recalculados para o usu├írio! (${data || 0} contas atualizadas)`);
      loadUsersDetailed();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Unknown error";
      logger.error("Error recalculating target balances:", error);
      toast.error("Erro ao recalcular saldos: " + message);
    } finally {
      setIsRecalculatingTarget(null);
    }
  };

  const handleInjectDefaultCategories = async (userId: string) => {
    setIsInjectingCategories(true);
    try {
      const { data: existing, error: checkError } = await supabase
        .from("categories")
        .select("id")
        .eq("user_id", userId)
        .limit(1);

      if (checkError) throw checkError;
      if (existing && existing.length > 0) {
        toast.warning("O usu├írio j├í possui categorias cadastradas!");
        return;
      }

      const { DEFAULT_CATEGORIES } = await import("@/lib/defaultCategories");

      const parentCategories = DEFAULT_CATEGORIES.map((cat) => ({
        user_id: userId,
        name: cat.name,
        icon: cat.icon,
        type: cat.type,
        parent_category_id: null,
      }));

      const { data: createdParents, error: parentError } = await supabase
        .from("categories")
        .insert(parentCategories)
        .select();

      if (parentError) throw parentError;

      const parentMap = new Map(createdParents.map((cat) => [cat.name, cat.id]));
      const childCategories: Database["public"]["Tables"]["categories"]["Insert"][] = [];

      DEFAULT_CATEGORIES.forEach((parent) => {
        const parentId = parentMap.get(parent.name);
        if (parent.children && parentId) {
          parent.children.forEach((child) => {
            childCategories.push({
              user_id: userId,
              name: child.name,
              icon: child.icon,
              type: child.type,
              parent_category_id: parentId,
            });
          });
        }
      });

      if (childCategories.length > 0) {
        const { error: childError } = await supabase.from("categories").insert(childCategories);

        if (childError) throw childError;
      }

      toast.success(
        `Categorias padr├úo criadas com sucesso! (${createdParents.length} principais e ${childCategories.length} subcategorias)`
      );
      loadUsersDetailed();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : "Unknown error";
      logger.error("Error injecting default categories:", error);
      toast.error("Erro ao injetar categorias padr├úo: " + message);
    } finally {
      setIsInjectingCategories(false);
    }
  };

  const openUserDetailModal = async (targetUser: EnrichedUser) => {
    setSelectedDetailUser(targetUser);
    setIsLoadingDetails(true);
    setUserDetailOpen(true);
    try {
      const { data, error } = await supabase.rpc("get_admin_user_dossier", {
        target_user_id: targetUser.id,
      });

      if (error) throw error;

      if (data) {
        setDetailAccounts(data.accounts || []);
        setDetailFamilies(data.families || []);
      }
    } catch (error) {
      logger.error("Error loading user details:", error);
      toast.error("Erro ao carregar detalhes do perfil");
    } finally {
      setIsLoadingDetails(false);
    }
  };

  const handleLogout = () => {
    setIsAuthenticated(false);
    setPassword("");
    setEnrichedUsers([]);
    setAuditLogs([]);
  };

  const getInitials = (name: string) => {
    if (!name) return "?";
    return name
      .split(" ")
      .map((n) => n[0])
      .join("")
      .toUpperCase()
      .slice(0, 2);
  };

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format(value);
  };

  const getUserEmail = (userId: string) => {
    const found = enrichedUsers.find((u) => u.id === userId);
    return found ? found.full_name || found.email : "Admin/Sistema";
  };

  // Filter users by search query
  const filteredUsers = enrichedUsers.filter(
    (u) =>
      u.email.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (u.full_name && u.full_name.toLowerCase().includes(searchQuery.toLowerCase()))
  );

  return {
    isAuthenticated,
    setIsAuthenticated,
    password,
    setPassword,
    showPassword,
    setShowPassword,
    passwordError,
    setPasswordError,
    enrichedUsers,
    setEnrichedUsers,
    auditLogs,
    setAuditLogs,
    errorLogs,
    setErrorLogs,
    stats,
    setStats,
    searchQuery,
    setSearchQuery,
    selectedUser,
    setSelectedUser,
    confirmWord,
    setConfirmWord,
    showConfirmDialog,
    setShowConfirmDialog,
    isResetting,
    setIsResetting,
    isLoadingStats,
    setIsLoadingStats,
    isLoadingUsers,
    setIsLoadingUsers,
    isLoadingLogs,
    setIsLoadingLogs,
    isLoadingErrorLogs,
    setIsLoadingErrorLogs,
    isPurging,
    setIsPurging,
    isInjectingCategories,
    setIsInjectingCategories,
    isRecalculatingTarget,
    setIsRecalculatingTarget,
    isResettingPassword,
    setIsResettingPassword,
    handleResetUserPassword,
    userDetailOpen,
    setUserDetailOpen,
    selectedDetailUser,
    setSelectedDetailUser,
    detailAccounts,
    setDetailAccounts,
    detailFamilies,
    setDetailFamilies,
    isLoadingDetails,
    setIsLoadingDetails,
    selectedErrorLog,
    setSelectedErrorLog,
    errorDetailOpen,
    setErrorDetailOpen,
    handleAuthenticate,
    handleLogout,
    handlePurgeSoftDeleted,
    handleClearErrorLogs,
    handleRecalculateTargetBalances,
    handleInjectDefaultCategories,
    handleReset,
    filteredUsers,
    loadAllAdminData,
    loadAuditLogs,
    loadErrorLogs,
    parseAuditLog,
    formatCurrency,
    getInitials,
    getUserEmail,
    resolveErrorLog,
    openUserDetailModal,
  };
}

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { logger } from "@/utils/logger";
import { SettlementValidator, SettlementErrorCode, ERROR_MESSAGES } from "@/services/settlementValidation";

interface AnticipateInstallmentsParams {
  seriesId: string;
  installmentIds: string[];
  newCompetenceDate: string; // Format: YYYY-MM-DD (always day 1)
}

interface InstallmentData {
  id: string;
  transaction_date: string;
  competence_date: string;
  is_settled: boolean;
  settled_by_debtor: boolean;
  settled_by_creditor: boolean;
}

/**
 * Hook para antecipar parcelas de uma s├®rie
 * 
 * Valida que:
 * - Parcelas n├úo est├úo acertadas
 * - Atualiza apenas competence_date (mant├®m transaction_date)
 * - Invalida queries relacionadas
 * 
 * @example
 * ```tsx
 * const { mutate: anticipate, isLoading } = useAnticipateInstallments();
 * 
 * anticipate({
 *   seriesId: "series-123",
 *   installmentIds: ["inst-1", "inst-2"],
 *   newCompetenceDate: "2024-01-01"
 * });
 * ```
 */
export function useAnticipateInstallments() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (params: AnticipateInstallmentsParams) => {
      const { seriesId, installmentIds, newCompetenceDate } = params;

      logger.debug('­ƒöä [useAnticipateInstallments] Iniciando antecipa├º├úo:', {
        seriesId,
        installmentIds,
        newCompetenceDate
      });

      // 1. Buscar dados das parcelas para valida├º├úo
      const { data: installments, error: fetchError } = await supabase
        .from('transactions')
        .select('id, transaction_date:date, competence_date, is_settled')
        .in('id', installmentIds);

      if (fetchError) {
        logger.error('ÔØî [useAnticipateInstallments] Erro ao buscar parcelas:', fetchError);
        throw new Error('Erro ao buscar parcelas: ' + fetchError.message);
      }

      if (!installments || installments.length === 0) {
        throw new Error('Nenhuma parcela encontrada');
      }

      logger.debug('­ƒôè [useAnticipateInstallments] Parcelas encontradas:', installments);

      // 2. Buscar splits das transa├º├Áes para valida├º├úo completa
      const { data: splits, error: splitsError } = await supabase
        .from('transaction_splits')
        .select('id, transaction_id, is_settled, settled_by_debtor, settled_by_creditor')
        .in('transaction_id', installmentIds);

      if (splitsError) {
        logger.error('ÔØî [useAnticipateInstallments] Erro ao buscar splits:', splitsError);
        throw new Error('Erro ao buscar splits: ' + splitsError.message);
      }

      logger.debug('­ƒôè [useAnticipateInstallments] Splits encontrados:', splits);

      // 3. Validar que nenhuma parcela est├í acertada
      const settledInstallments: string[] = [];
      
      for (const installment of installments) {
        // Buscar splits desta transa├º├úo
        const installmentSplits = splits?.filter(s => s.transaction_id === installment.id) || [];
        
        // Verificar se algum split est├í settled
        const hasSettledSplit = installmentSplits.some(split => 
          split.is_settled || split.settled_by_debtor || split.settled_by_creditor
        );

        if (installment.is_settled || hasSettledSplit) {
          settledInstallments.push(installment.id);
        }
      }

      if (settledInstallments.length > 0) {
        logger.error('ÔØî [useAnticipateInstallments] Parcelas acertadas encontradas:', settledInstallments);
        const errorMsg = ERROR_MESSAGES[SettlementErrorCode.INSTALLMENT_SETTLED];
        throw new Error(errorMsg.message + ` (${settledInstallments.length} parcela(s))`);
      }

      // 4. TASK 15: Validar que newCompetenceDate n├úo cria duplicatas
      const { data: existingInstallments, error: duplicateError } = await supabase
        .from('transactions')
        .select('id')
        .eq('series_id', seriesId)
        .eq('competence_date', newCompetenceDate)
        .not('id', 'in', `(${installmentIds.join(',')})`); // Excluir as pr├│prias parcelas sendo antecipadas

      if (duplicateError) {
        logger.error('ÔØî [useAnticipateInstallments] Erro ao verificar duplicatas:', duplicateError);
        throw new Error('Erro ao verificar duplicatas: ' + duplicateError.message);
      }

      if (existingInstallments && existingInstallments.length > 0) {
        logger.error('ÔØî [useAnticipateInstallments] DUPLICA├ç├âO DETECTADA - J├í existe parcela com esta competence_date:', {
          seriesId,
          newCompetenceDate,
          existingInstallments
        });
        throw new Error(`J├í existe uma parcela com a data de compet├¬ncia ${newCompetenceDate}. Escolha outra data para evitar duplica├º├úo.`);
      }

      logger.debug('Ô£à [useAnticipateInstallments] Valida├º├úo de duplica├º├úo passou - nenhuma duplicata encontrada');

      // 5. Atualizar competence_date das parcelas (mant├®m transaction_date)
      const { error: updateError } = await supabase
        .from('transactions')
        .update({ competence_date: newCompetenceDate })
        .in('id', installmentIds);

      if (updateError) {
        logger.error('ÔØî [useAnticipateInstallments] Erro ao atualizar parcelas:', updateError);
        throw new Error('Erro ao antecipar parcelas: ' + updateError.message);
      }

      logger.debug('Ô£à [useAnticipateInstallments] Parcelas antecipadas com sucesso');

      return {
        success: true,
        anticipatedCount: installmentIds.length,
        newCompetenceDate
      };
    },
    onSuccess: (data) => {
      logger.debug('Ô£à [useAnticipateInstallments] Sucesso:', data);
      
      // Invalidar queries relacionadas
      queryClient.invalidateQueries({ queryKey: ['transactions'] });
      queryClient.invalidateQueries({ queryKey: ['shared-finances'] });
      queryClient.invalidateQueries({ queryKey: ['invoices'] });
      
      toast.success(`${data.anticipatedCount} parcela(s) antecipada(s) com sucesso!`);
    },
    onError: (error: Error) => {
      logger.error('ÔØî [useAnticipateInstallments] Erro:', error);
      toast.error(error.message || 'Erro ao antecipar parcelas');
    }
  });
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Asset, AssetPerformance } from '@/types/database';
import { useToast } from '@/hooks/use-toast';
import { logger } from '@/utils/logger';

export const useAssets = () => {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Buscar todos os investimentos
  const { data: assets, isLoading } = useQuery({
    queryKey: ['assets'],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('assets')
        .select('*')
        .order('created_at', { ascending: false });

      if (error) throw error;
      return data as Asset[];
    },
  });

  // Buscar performance de um investimento
  const getAssetPerformance = async (assetId: string) => {
    const { data, error } = await supabase.rpc('get_asset_performance', {
      p_asset_id: assetId,
    });

    if (error) throw error;
    return data as AssetPerformance[];
  };

  // Criar investimento
  const createAsset = useMutation({
    mutationFn: async (asset: Omit<Asset, 'id' | 'user_id' | 'created_at' | 'updated_at' | 'deleted'>) => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) throw new Error('Usu├írio n├úo autenticado');

      const { data: assetData, error } = await supabase
        .from('assets')
        .insert([{ ...asset, user_id: user.id }])
        .select()
        .single();

      if (error) throw error;

      // SE houver conta vinculada e valor investido, gerar transa├º├úo autom├ítica
      if (assetData.account_id && asset.purchase_price && asset.quantity) {
        const totalAmount = asset.purchase_price * asset.quantity;
        const purchaseDate = asset.purchase_date || new Date().toISOString().split('T')[0];
        const competenceDate = `${purchaseDate.substring(0, 7)}-01`;

        // Buscar categoria de Investimentos ou usar uma padr├úo
        const { data: catData } = await supabase
          .from('categories')
          .select('id')
          .eq('user_id', user.id)
          .ilike('name', '%investimento%')
          .limit(1)
          .maybeSingle();

        const { error: txError } = await supabase.from('transactions').insert({
          user_id: user.id,
          creator_user_id: user.id,
          account_id: assetData.account_id,
          type: 'EXPENSE',
          amount: totalAmount,
          description: `Compra de Ativo: ${assetData.ticker || assetData.name}`,
          category_id: catData?.id || null,
          date: purchaseDate,
          competence_date: competenceDate,
          domain: 'PERSONAL',
          is_shared: false,
          is_installment: false,
          is_recurring: false,
          currency: assetData.currency || 'BRL',
          notes: `Compra de ${assetData.quantity} cotas de ${assetData.name}`,
          asset_id: assetData.id,
        });

        if (txError) {
          logger.error("Erro ao gerar transa├º├úo de ativo:", txError);
          // N├úo falhamos a cria├º├úo do ativo se a transa├º├úo falhar, mas avisamos
        }

        // TAMB├ëM INSERE NA asset_transactions PARA MANTER O HIST├ôRICO CORRETO
        const { error: assetTxError } = await supabase.from('asset_transactions').insert({
          user_id: user.id,
          asset_id: assetData.id,
          account_id: assetData.account_id,
          type: 'BUY',
          quantity: asset.quantity,
          price: asset.purchase_price,
          date: purchaseDate
        });

        if (assetTxError) {
          logger.error("Erro ao gerar transa├º├úo de hist├│rico de ativo:", assetTxError);
        }
      }

      return assetData;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['assets'] });
      queryClient.invalidateQueries({ queryKey: ['asset-transactions'] }); // ADICIONADO
      toast({
        title: 'Investimento criado',
        description: 'Investimento criado com sucesso!',
      });
    },
    onError: (error: Error) => {
      toast({
        title: 'Erro ao criar investimento',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  // Atualizar investimento
  const updateAsset = useMutation({
    mutationFn: async ({ id, ...asset }: Partial<Asset> & { id: string }) => {
      const { data, error } = await supabase
        .from('assets')
        .update(asset)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['assets'] });
      toast({
        title: 'Investimento atualizado',
        description: 'Investimento atualizado com sucesso!',
      });
    },
    onError: (error: Error) => {
      toast({
        title: 'Erro ao atualizar investimento',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  // Atualizar pre├ºo atual
  const updateAssetPrice = useMutation({
    mutationFn: async ({ id, currentPrice }: { id: string; currentPrice: number }) => {
      const { data, error } = await supabase
        .from('assets')
        .update({ current_price: currentPrice })
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['assets'] });
      toast({
        title: 'Pre├ºo atualizado',
        description: 'Pre├ºo atualizado com sucesso!',
      });
    },
    onError: (error: Error) => {
      toast({
        title: 'Erro ao atualizar pre├ºo',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  // Deletar investimento (soft delete)
  const deleteAsset = useMutation({
    mutationFn: async (id: string) => {
      // 1. Fetch the asset to know its name/ticker
      const { data: asset, error: fetchError } = await supabase
        .from('assets')
        .select('*')
        .eq('id', id)
        .single();
        
      if (fetchError || !asset) throw fetchError || new Error('Investimento n├úo encontrado');

      const assetIdentifier = asset.ticker || asset.name;

      // 2. Delete auto-generated transactions (Efeito Cascata via ON DELETE CASCADE no banco)
      // O banco cuidar├í da exclus├úo na tabela transactions via FK asset_id ON DELETE CASCADE
      // e na asset_transactions via FK asset_id ON DELETE CASCADE (se aplic├ível, mas j├í temos manual abaixo para garantir).

      // 3. Delete from asset_transactions (Efeito Cascata)
      await supabase
        .from('asset_transactions')
        .delete()
        .eq('asset_id', id);

      // 4. Finally, delete the asset
      const { error } = await supabase
        .from('assets')
        .delete()
        .eq('id', id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['assets'] });
      toast({
        title: 'Investimento exclu├¡do',
        description: 'Investimento exclu├¡do com sucesso!',
      });
    },
    onError: (error: Error) => {
      toast({
        title: 'Erro ao excluir investimento',
        description: error.message,
        variant: 'destructive',
      });
    },
  });

  return {
    assets,
    isLoading,
    getAssetPerformance,
    createAsset: createAsset.mutate,
    updateAsset: updateAsset.mutate,
    updateAssetPrice: updateAssetPrice.mutate,
    deleteAsset: deleteAsset.mutate,
    isCreating: createAsset.isPending,
    isUpdating: updateAsset.isPending,
    isDeleting: deleteAsset.isPending,
  };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Budget, BudgetProgress } from '@/types/database';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/contexts/AuthContext';
import { useMonth } from '@/contexts/MonthContext';
import { getMonthDateRange } from '@/utils/dateUtils';
import * as dateFns from 'date-fns';
import { invalidateBudgetQueries } from '@/utils/queryInvalidation';
import { SafeFinancialCalculator } from '@/services/SafeFinancialCalculator';
import { budgetToasts } from '@/utils/toastMessages';
import { defaultQueryConfig } from '@/utils/queryConfig';

// Interface para o progresso do or├ºamento retornado pelo banco
export interface BudgetWithProgress {
  budget_id: string;
  budget_name: string;
  category_id: string | null;
  category_name: string | null;
  category_icon: string | null;
  budget_amount: number;
  spent_amount: number;
  remaining_amount: number;
  percentage_used: number;
  currency: string;
  period: string;
}

export const useBudgets = () => {
  const { toast } = useToast();
  const { user } = useAuth();
  const { currentDate, startDay } = useMonth();
  const queryClient = useQueryClient();

  // Calcular datas do per├¡odo atual
  const { startDate, endDate } = getMonthDateRange(currentDate, startDay);

  // Buscar todos os or├ºamentos COM progresso calculado pelo banco de dados
  // SINGLE SOURCE OF TRUTH: O gasto ├® calculado diretamente das transa├º├Áes
  const { data: budgetsWithProgress, isLoading } = useQuery({
    queryKey: ['budgets-progress', user?.id, startDate, endDate],
    queryFn: async () => {
      if (!user) return [];
      
      const { data, error } = await supabase.rpc('get_user_budgets_progress_with_rollover', {
        p_user_id: user.id,
        p_start_date: startDate,
        p_end_date: endDate,
      });

      if (error) throw error;
      
      return data as (BudgetWithProgress & { _original_budget?: number, _rollover?: number })[];
    },
    enabled: !!user,
    ...defaultQueryConfig,
  });

  // Buscar or├ºamentos b├ísicos (para edi├º├úo/exclus├úo)
  const { data: budgets } = useQuery({
    queryKey: ['budgets', user?.id],
    queryFn: async () => {
      if (!user) return [];
      
      const { data, error } = await supabase
        .from('budgets')
        .select('*')
        .eq('user_id', user.id)
        .eq('is_active', true)
        .or('deleted.is.null,deleted.eq.false')
        .order('created_at', { ascending: false });

      if (error) throw error;
      return data as Budget[];
    },
    enabled: !!user,
    ...defaultQueryConfig,
  });

  // Buscar progresso de um or├ºamento espec├¡fico (usa fun├º├úo do banco)
  const getBudgetProgress = async (budgetId: string, pStartDate: string, pEndDate: string) => {
    if (!user) return [];
    
    // Buscar o or├ºamento para pegar a categoria
    const budget = budgets?.find(b => b.id === budgetId);
    if (!budget?.category_id) return [];

    const { data, error } = await supabase.rpc('calculate_budget_spent', {
      p_user_id: user.id,
      p_category_id: budget.category_id,
      p_start_date: pStartDate,
      p_end_date: pEndDate,
      p_currency: budget.currency || 'BRL',
    });

    if (error) throw error;
    return data as number;
  };

  // Criar or├ºamento
  const createBudget = useMutation({
    onMutate: async (budget: Omit<Budget, 'id' | 'user_id' | 'created_at' | 'updated_at' | 'deleted'>) => {
      await queryClient.cancelQueries({ queryKey: ['budgets', user?.id] });
      const previous = queryClient.getQueryData<Budget[]>(['budgets', user?.id]);
      const optimistic = { ...budget, id: `temp-${Date.now()}`, user_id: user?.id ?? '', created_at: new Date().toISOString(), updated_at: new Date().toISOString(), deleted: false } as Budget;
      queryClient.setQueryData<Budget[]>(['budgets', user?.id], (old) => [optimistic, ...(old ?? [])]);
      return { previous };
    },
    onError: (error: Error, _vars, context) => {
      if (context?.previous) queryClient.setQueryData(['budgets', user?.id], context.previous);
      budgetToasts.error('criar', error);
    },
    mutationFn: async (budget: Omit<Budget, 'id' | 'user_id' | 'created_at' | 'updated_at' | 'deleted'>) => {
      if (!user) throw new Error('Usu├írio n├úo autenticado');

      const { data, error } = await supabase
        .from('budgets')
        .insert([{ ...budget, user_id: user.id }])
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      budgetToasts.created();
    },
    onSettled: async () => {
      await invalidateBudgetQueries(queryClient);
    },
  });

  // Atualizar or├ºamento
  const updateBudget = useMutation({
    onMutate: async ({ id, ...budget }: Partial<Budget> & { id: string }) => {
      await queryClient.cancelQueries({ queryKey: ['budgets', user?.id] });
      const previous = queryClient.getQueryData<Budget[]>(['budgets', user?.id]);
      queryClient.setQueryData<Budget[]>(['budgets', user?.id], (old) =>
        old?.map((b) => b.id === id ? { ...b, ...budget } : b) ?? []
      );
      return { previous };
    },
    onError: (error: Error, _vars, context) => {
      if (context?.previous) queryClient.setQueryData(['budgets', user?.id], context.previous);
      budgetToasts.error('atualizar', error);
    },
    mutationFn: async ({ id, ...budget }: Partial<Budget> & { id: string }) => {
      const { data, error } = await supabase
        .from('budgets')
        .update(budget)
        .eq('id', id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      budgetToasts.updated();
    },
    onSettled: async () => {
      await invalidateBudgetQueries(queryClient);
    },
  });

  // Deletar or├ºamento (soft delete)
  const deleteBudget = useMutation({
    onMutate: async (id: string) => {
      await queryClient.cancelQueries({ queryKey: ['budgets', user?.id] });
      const previous = queryClient.getQueryData<Budget[]>(['budgets', user?.id]);
      queryClient.setQueryData<Budget[]>(['budgets', user?.id], (old) =>
        old?.filter((b) => b.id !== id) ?? []
      );
      return { previous };
    },
    onError: (error: Error, _id, context) => {
      if (context?.previous) queryClient.setQueryData(['budgets', user?.id], context.previous);
      budgetToasts.error('excluir', error);
    },
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from('budgets')
        .update({ deleted: true, is_active: false })
        .eq('id', id);

      if (error) throw error;
    },
    onSuccess: () => {
      budgetToasts.deleted();
    },
    onSettled: async () => {
      await invalidateBudgetQueries(queryClient);
    },
  });

  return {
    budgets,
    budgetsWithProgress, // Novo: or├ºamentos com progresso calculado pelo banco
    isLoading,
    getBudgetProgress,
    createBudget: createBudget.mutateAsync,
    updateBudget: updateBudget.mutateAsync,
    deleteBudget: deleteBudget.mutateAsync,
    isCreating: createBudget.isPending,
    isUpdating: updateBudget.isPending,
    isDeleting: deleteBudget.isPending,
  };
};

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useMemo } from "react";
import { invalidateCategoryQueries } from "@/utils/queryInvalidation";
import { categoryToasts } from "@/utils/toastMessages";
import { defaultQueryConfig } from "@/utils/queryConfig";
import { logger } from "@/utils/logger";

export interface Category {
  id: string;
  user_id: string;
  name: string;
  icon: string | null;
  type: "expense" | "income";
  color: string | null;
  parent_category_id: string | null; // Para hierarquia
  created_at: string;
  is_archived?: boolean | null;
}

export interface CreateCategoryInput {
  name: string;
  icon?: string;
  type: "expense" | "income";
  color?: string;
  parent_category_id?: string | null; // Para hierarquia
}

export function useCategories(includeArchived = false) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["categories", user?.id, includeArchived],
    queryFn: async () => {
      let query = supabase
        .from("categories")
        .select("*")
        .eq("user_id", user!.id)
        .is("deleted_at", null)
        .order("name");

      if (!includeArchived) {
        query = query.is("is_archived", false);
      }

      const { data, error } = await query;

      if (error) throw error;
      return data as Category[];
    },
    enabled: !!user,
    ...defaultQueryConfig,
  });
}

// Hook para buscar categorias organizadas hierarquicamente
export function useCategoriesHierarchical(includeArchived = false) {
  const { data: allCategories, ...rest } = useCategories(includeArchived);

  const hierarchical = useMemo(() => {
    if (!allCategories) return { parents: [], children: new Map() };

    // Separar pais e filhos
    const parents = allCategories.filter(cat => !cat.parent_category_id);
    const children = new Map<string, Category[]>();

    // Agrupar filhos por pai
    allCategories
      .filter(cat => cat.parent_category_id)
      .forEach(cat => {
        const parentId = cat.parent_category_id!;
        if (!children.has(parentId)) {
          children.set(parentId, []);
        }
        children.get(parentId)!.push(cat);
      });

    return { parents, children };
  }, [allCategories]);

  return {
    ...rest,
    data: allCategories,
    hierarchical,
  };
}

export function useCreateCategory() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateCategoryInput) => {
      if (!user) throw new Error("User not authenticated");

      const { data, error } = await supabase
        .from("categories")
        .insert({
          user_id: user.id,
          ...input,
        })
        .select()
        .single();

      if (error) throw error;
      return data as Category;
    },
    onSuccess: async () => {
      await invalidateCategoryQueries(queryClient);
      categoryToasts.created();
    },
    onError: (error) => {
      categoryToasts.error('criar', error);
    },
  });
}

export interface UpdateCategoryInput {
  name?: string;
  icon?: string;
  color?: string;
}

export function useUpdateCategory() {
  const queryClient = useQueryClient();

  return useMutation({
    onMutate: async ({ id, ...input }: UpdateCategoryInput & { id: string }) => {
      await queryClient.cancelQueries({ queryKey: ["categories"] });
      const previousData = queryClient.getQueriesData<Category[]>({ queryKey: ["categories"] });
      queryClient.setQueriesData<Category[]>({ queryKey: ["categories"] }, (old) =>
        old?.map((c) => c.id === id ? { ...c, ...input } : c) ?? []
      );
      return { previousData };
    },
    onError: (error, _vars, context) => {
      context?.previousData?.forEach(([key, data]) => queryClient.setQueryData(key, data));
      categoryToasts.error('atualizar', error);
    },
    mutationFn: async ({ id, ...input }: UpdateCategoryInput & { id: string }) => {
      const { data, error } = await supabase
        .from("categories")
        .update(input)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data as Category;
    },
    onSuccess: () => {
      categoryToasts.updated();
    },
    onSettled: async () => {
      await invalidateCategoryQueries(queryClient);
    },
  });
}

export function useDeleteCategory() {
  const queryClient = useQueryClient();

  return useMutation({
    onMutate: async (id: string) => {
      await queryClient.cancelQueries({ queryKey: ["categories"] });
      const previousData = queryClient.getQueriesData<Category[]>({ queryKey: ["categories"] });
      queryClient.setQueriesData<Category[]>({ queryKey: ["categories"] }, (old) =>
        old?.filter((c) => c.id !== id) ?? []
      );
      return { previousData };
    },
    onError: (error, _id, context) => {
      context?.previousData?.forEach(([key, data]) => queryClient.setQueryData(key, data));
      categoryToasts.error('remover', error);
    },
    mutationFn: async (id: string) => {
      // INTEGRIDADE DO BANCO: Verificar subcategorias filhas antes de excluir
      const { count: subCount } = await supabase
        .from("categories")
        .select("id", { count: "exact", head: true })
        .eq("parent_category_id", id);

      if (subCount && subCount > 0) {
        throw new Error(
          `Esta categoria possui ${subCount} subcategoria(s) vinculada(s). ` +
          `Exclua as subcategorias primeiro antes de remover a categoria principal.`
        );
      }

      // Removida a valida├º├úo de transa├º├Áes e or├ºamentos vinculados, pois agora usamos Soft Delete.
      // O hist├│rico financeiro ser├í mantido intacto.

      const { error } = await supabase
        .from("categories")
        .update({ deleted_at: new Date().toISOString() })
        .eq("id", id);

      if (error) throw error;
    },
    onSuccess: () => {
      categoryToasts.deleted();
    },
    onSettled: async () => {
      await invalidateCategoryQueries(queryClient);
    },
  });
}

// Criar categorias padr├úo para um novo usu├írio
export function useCreateDefaultCategories() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ force = false }: { force?: boolean } = {}) => {
      if (!user) throw new Error("User not authenticated");

      // Buscar as categorias existentes pelo nome para n├úo duplicar
      const { data: existing, error: checkError } = await supabase
        .from("categories")
        .select("id, name")
        .eq("user_id", user.id);

      if (checkError) throw checkError;
      
      const existingNames = new Set((existing || []).map(c => c.name.toLowerCase()));

      if (!force && existing && existing.length >= 20) {
        logger.info("Usu├írio j├í possui estrutura completa de categorias. Ignorando cria├º├úo padr├úo.");
        return;
      }

      // Importar categorias hier├írquicas
      const { DEFAULT_CATEGORIES } = await import("@/lib/defaultCategories");

      // Filtrar as categorias pai que ainda N├âO existem
      const parentCategoriesToCreate = DEFAULT_CATEGORIES.filter(cat => !existingNames.has(cat.name.toLowerCase())).map(cat => ({
        user_id: user.id,
        name: cat.name,
        icon: cat.icon,
        type: cat.type,
        parent_category_id: null,
      }));

      let createdParents: any[] = [];
      if (parentCategoriesToCreate.length > 0) {
        const { data, error: parentError } = await supabase
          .from("categories")
          .insert(parentCategoriesToCreate)
          .select();
        if (parentError) throw parentError;
        createdParents = data || [];
      }

      // Buscar novamente todos os pais atualizados (os antigos + os novos criados)
      const { data: allParents } = await supabase
        .from("categories")
        .select("id, name")
        .eq("user_id", user.id)
        .is("parent_category_id", null);

      const parentMap = new Map((allParents || []).map(cat => [cat.name.toLowerCase(), cat.id]));

      // Agora preparar as subcategorias
      const childCategories: unknown[] = [];
      
      DEFAULT_CATEGORIES.forEach(parent => {
        const parentId = parentMap.get(parent.name.toLowerCase());
        if (parent.children && parentId) {
          parent.children.forEach(child => {
            // Se a subcategoria j├í existe com este nome, n├úo cria de novo
            if (!existingNames.has(child.name.toLowerCase())) {
              childCategories.push({
                user_id: user.id,
                name: child.name,
                icon: child.icon,
                type: child.type,
                parent_category_id: parentId,
              });
            }
          });
        }
      });

      if (childCategories.length > 0) {
        const { error: childError } = await supabase
          .from("categories")
          .insert(childCategories);

        if (childError) throw childError;
      }

      logger.success(`Criadas ${createdParents.length} categorias pai e ${childCategories.length} subcategorias`);
    },
    onSuccess: async () => {
      await invalidateCategoryQueries(queryClient);
    },
  });
}

import { useQuery, keepPreviousData } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useMonth } from "@/contexts/MonthContext";
import { getMonthDateRange } from "@/utils/dateUtils";
import { logger } from "@/utils/logger";

export interface DashboardTransaction {
  id: string;
  type: string;
  amount: number;
  currency: string | null;
  date: string;
  description: string;
  is_shared: boolean;
  payer_id: string | null;
  account_id: string | null;
  source_transaction_id: string | null;
  creator_user_id?: string | null;
  category: { id: string; name: string; icon: string | null } | null;
  account: { id: string; name: string; currency: string | null } | null;
}

export interface DashboardSummary {
  total_income: number;
  total_expense: number;
  pending_income: number;
  pending_expense: number;
  balance: number;
  totals_by_currency: {
    currency: string;
    income: number;
    expense: number;
    pending_income: number;
    pending_expense: number;
    balance: number;
  }[];
  recent_transactions: DashboardTransaction[];
}

/**
 * Hook de alta performance para o Dashboard.
 * Substitui useTransactions() (1000 rows) por uma RPC que retorna
 * apenas os totais + 5 transa├º├Áes recentes em uma ├║nica chamada.
 */
export function useDashboardData() {
  const { user } = useAuth();
  const { currentDate, startDay } = useMonth();
  const { startDate, endDate, monthKey } = getMonthDateRange(currentDate, startDay);

  return useQuery({
    queryKey: ["dashboard-data", user?.id, monthKey],
    staleTime: 1000 * 60 * 5, // 5 minutes cache to avoid excessive refetching
    queryFn: async (): Promise<DashboardSummary> => {
      if (!user)
        return {
          total_income: 0,
          total_expense: 0,
          pending_income: 0,
          pending_expense: 0,
          balance: 0,
          totals_by_currency: [],
          recent_transactions: [],
        };

      const { data, error } = await (supabase.rpc as any)("get_dashboard_summary", {
        p_user_id: user.id,
        p_start_date: startDate,
        p_end_date: endDate,
      });

      if (error) {
        logger.error("[useDashboardData] Erro RPC:", JSON.stringify(error, null, 2));
        return {
          total_income: 0,
          total_expense: 0,
          pending_income: 0,
          pending_expense: 0,
          balance: 0,
          totals_by_currency: [],
          recent_transactions: [],
        };
      }

      return {
        total_income: Number(data?.total_income) || 0,
        total_expense: Number(data?.total_expense) || 0,
        pending_income: Number(data?.pending_income) || 0,
        pending_expense: Number(data?.pending_expense) || 0,
        balance: Number(data?.balance) || 0,
        totals_by_currency: data?.totals_by_currency || [],
        recent_transactions: (data?.recent_transactions as DashboardTransaction[]) || [],
      };
    },
    enabled: !!user,
    refetchOnWindowFocus: false,
    placeholderData: keepPreviousData,
  });
}

interface MonthlyEvolutionRow {
  month_date: string;
  total_income: number;
  total_expense: number;
  currency: string;
}

/**
 * Hook para evolu├º├úo mensal ÔÇö retorna dados dos ├║ltimos N meses via RPC.
 * Substitui o c├ílculo manual em Reports.tsx que iterava sobre 1000 transa├º├Áes.
 */
export function useMonthlyEvolutionReport(months: number = 6, currency: string = "BRL") {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["monthly-evolution-report", user?.id, months, currency],
    queryFn: async () => {
      if (!user) return [];

      const { data, error } = await supabase.rpc("get_monthly_evolution_report", {
        p_user_id: user.id,
        p_months: months,
      });

      if (error) {
        logger.error("[useMonthlyEvolutionReport] Erro RPC:", error);
        return [];
      }

      const typed = data as unknown as MonthlyEvolutionRow[] | null;
      const currencyData = (Array.isArray(typed) ? typed : []).filter(
        (row) => (row.currency || "BRL") === currency
      );

      return currencyData.map((row) => ({
        month_start: row.month_date,
        income: Number(row.total_income) || 0,
        expense: Number(row.total_expense) || 0,
        savings: (Number(row.total_income) || 0) - (Number(row.total_expense) || 0),
      }));
    },
    enabled: !!user,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Goal, GoalProgress } from "@/types/database";
import { useToast } from "@/hooks/use-toast";
import { generateAllNotifications } from "@/services/notificationGenerator";
import { logger } from "@/utils/logger";

// AUDITORIA 2026-05-10: Corrigido contributeToGoal ÔÇö agora cria transa├º├úo financeira
// para rastrear o aporte no fluxo de caixa. Sem isso, o dinheiro "sumia" do saldo
// sem registro. Se a meta tem linked_account_id, debita dessa conta; caso contr├írio
// cria uma despesa gen├®rica na categoria "Meta".

export const useGoals = () => {
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Buscar todas as metas
  const { data: goals, isLoading } = useQuery({
    queryKey: ["goals"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("goals")
        .select("*")
        .eq("deleted", false)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data as Goal[];
    },
    staleTime: 30 * 1000,
    refetchOnWindowFocus: false,
  });

  // Buscar progresso de uma meta
  const getGoalProgress = async (goalId: string) => {
    // Verificar se a fun├º├úo RPC existe antes de chamar
    const { data, error } = await supabase.rpc("get_goal_progress", {
      p_goal_id: goalId,
    });

    if (error) {
      // Se a fun├º├úo n├úo existir, retornar array vazio em vez de quebrar
      logger.warn("[useGoals] get_goal_progress n├úo dispon├¡vel:", error.message);
      return [] as GoalProgress[];
    }
    return (data as Array<GoalProgress & { percentage_complete: number }>).map((item) => ({
      ...item,
      percentage: item.percentage_complete,
    })) as GoalProgress[];
  };

  // Criar meta
  const createGoal = useMutation({
    onMutate: async (
      goal: Omit<
        Goal,
        | "id"
        | "user_id"
        | "created_at"
        | "updated_at"
        | "deleted"
        | "completed_at"
        | "creator_user_id"
      >
    ) => {
      await queryClient.cancelQueries({ queryKey: ["goals"] });
      const previous = queryClient.getQueryData<Goal[]>(["goals"]);
      const optimistic = {
        ...goal,
        id: `temp-${Date.now()}`,
        user_id: "",
        creator_user_id: "",
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        deleted: false,
        completed_at: null,
      } as Goal;
      queryClient.setQueryData<Goal[]>(["goals"], (old) => [optimistic, ...(old ?? [])]);
      return { previous };
    },
    onError: (error: Error, _vars, context) => {
      if (context?.previous) queryClient.setQueryData(["goals"], context.previous);
      toast({ title: "Erro ao criar meta", description: error.message, variant: "destructive" });
    },
    mutationFn: async (
      goal: Omit<
        Goal,
        | "id"
        | "user_id"
        | "created_at"
        | "updated_at"
        | "deleted"
        | "completed_at"
        | "creator_user_id"
      >
    ) => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("Usu├írio n├úo autenticado");

      const { data, error } = await supabase
        .from("goals")
        .insert([{ ...goal, user_id: user.id, creator_user_id: user.id }])
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      toast({ title: "Meta criada", description: "Meta criada com sucesso!" });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["goals"] });
    },
  });

  // Atualizar meta
  const updateGoal = useMutation({
    onMutate: async ({ id, ...goal }: Partial<Goal> & { id: string }) => {
      await queryClient.cancelQueries({ queryKey: ["goals"] });
      const previous = queryClient.getQueryData<Goal[]>(["goals"]);
      queryClient.setQueryData<Goal[]>(
        ["goals"],
        (old) => old?.map((g) => (g.id === id ? { ...g, ...goal } : g)) ?? []
      );
      return { previous };
    },
    onError: (error: Error, _vars, context) => {
      if (context?.previous) queryClient.setQueryData(["goals"], context.previous);
      toast({
        title: "Erro ao atualizar meta",
        description: error.message,
        variant: "destructive",
      });
    },
    mutationFn: async ({ id, ...goal }: Partial<Goal> & { id: string }) => {
      const { data, error } = await supabase
        .from("goals")
        .update(goal)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      toast({ title: "Meta atualizada", description: "Meta atualizada com sucesso!" });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["goals"] });
    },
  });

  // Adicionar contribui├º├úo ├á meta (CRIT-05: RPC at├┤mica)
  const contributeToGoal = useMutation({
    mutationFn: async ({
      id,
      amount,
      accountId,
      description,
    }: {
      id: string;
      amount: number;
      accountId?: string;
      description?: string;
    }) => {
      const result = await callRPCWithRetry("contribute_to_goal", {
        p_goal_id: id,
        p_amount: amount,
        p_account_id: accountId || null,
        p_description: description || null,
      });

      // Re-fetch goal to get full updated data
      const { data: goal, error: fetchError } = await supabase
        .from("goals")
        .select("*")
        .eq("id", id)
        .single();

      if (fetchError) throw fetchError;
      return goal;
    },
    onSuccess: async () => {
      queryClient.invalidateQueries({ queryKey: ["goals"] });
      queryClient.invalidateQueries({ queryKey: ["transactions"] });
      queryClient.invalidateQueries({ queryKey: ["accounts"] });
      queryClient.invalidateQueries({ queryKey: ["financial-summary"] });
      toast({
        title: "Aporte registrado",
        description: "Contribui├º├úo adicionada e registrada no seu extrato.",
      });

      // Ô£à INTELIG├èNCIA FINANCEIRA: Verificar marcos de metas
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (user?.id) {
        generateAllNotifications(user.id).catch(logger.error);
      }
    },
    onError: (error: Error) => {
      toast({
        title: "Erro ao adicionar contribui├º├úo",
        description: error.message,
        variant: "destructive",
      });
    },
  });

  // Deletar meta (soft delete)
  const deleteGoal = useMutation({
    onMutate: async (id: string) => {
      await queryClient.cancelQueries({ queryKey: ["goals"] });
      const previous = queryClient.getQueryData<Goal[]>(["goals"]);
      queryClient.setQueryData<Goal[]>(["goals"], (old) => old?.filter((g) => g.id !== id) ?? []);
      return { previous };
    },
    onError: (error: Error, _id, context) => {
      if (context?.previous) queryClient.setQueryData(["goals"], context.previous);
      toast({ title: "Erro ao excluir meta", description: error.message, variant: "destructive" });
    },
    mutationFn: async (id: string) => {
      // CRIT-06: Dele├º├úo por goal_id FK (substitui LIKE '%meta%' fr├ígil)
      await supabase.from("transactions").delete().eq("goal_id", id);

      // Soft delete the goal
      const { error } = await supabase.from("goals").update({ deleted: true }).eq("id", id);

      if (error) throw error;
    },
    onSuccess: () => {
      toast({ title: "Meta exclu├¡da", description: "Meta exclu├¡da com sucesso!" });
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["goals"] });
    },
  });

  return {
    goals,
    isLoading,
    getGoalProgress,
    createGoal: createGoal.mutate,
    updateGoal: updateGoal.mutate,
    contributeToGoal: contributeToGoal.mutate,
    deleteGoal: deleteGoal.mutate,
    isCreating: createGoal.isPending,
    isUpdating: updateGoal.isPending,
    isContributing: contributeToGoal.isPending,
    isDeleting: deleteGoal.isPending,
  };
};

import React from 'react';
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { Asset } from '@/types/database';
import { getAssetTransactions, getPositionAtDate, getIRDetails } from '@/utils/investmentExport';
import { formatCurrency } from '@/utils/currencyFormatter';
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { 
  ShieldCheck, 
  Copy, 
  Check, 
  Calendar, 
  Briefcase, 
  Coins, 
  Percent, 
  TrendingUp,
  Download,
  AlertCircle,
  HelpCircle,
  ExternalLink,
  ChevronRight,
  TrendingDown
} from 'lucide-react';
import { Button } from "@/components/ui/button";
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from "@/components/ui/card";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { toast } from 'sonner';
import { exportToIRPDF, exportToIRExcel } from '@/utils/investmentExport';
import { logger } from '@/utils/logger';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface InvestmentIRPanelProps {
  assets: Asset[];
}



export function useInvestmentIR({ assets }: InvestmentIRPanelProps) {

  const currentYear = new Date().getFullYear();
  const [selectedYear, setSelectedYear] = useState<number>(currentYear - 1);
  const [copiedField, setCopiedField] = useState<string | null>(null);

  // Anos dispon├¡veis para declara├º├úo
  const availableYears = [currentYear - 1, currentYear - 2, currentYear - 3];

  // 1. Query para carregar as transa├º├Áes de ativos (compra/venda) da tabela asset_transactions
  const { data: assetTransactions, isLoading: isLoadingAssetTxs } = useQuery({
    queryKey: ['asset-transactions-ir', selectedYear],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('asset_transactions')
        .select('*')
        .order('date', { ascending: true })
        .order('created_at', { ascending: true });

      if (error) {
        logger.error("Erro ao buscar transa├º├Áes de ativos para IR:", error);
        throw error;
      }
      return data || [];
    }
  });

  // 2. Query para carregar transa├º├Áes financeiras gerais (proventos e dividendos) do ano-calend├írio
  const { data: financeTransactions, isLoading: isLoadingFinanceTxs } = useQuery({
    queryKey: ['finance-transactions-ir', selectedYear],
    queryFn: async () => {
      const { data, error } = await supabase
        .from('transactions')
        .select(`
          *,
          category:categories(id, name, parent_category_id)
        `)
        .eq('type', 'INCOME')
        .gte('date', `${selectedYear}-01-01`)
        .lte('date', `${selectedYear}-12-31`);

      if (error) {
        logger.error("Erro ao buscar proventos para IR:", error);
        throw error;
      }
      return data || [];
    }
  });

  const handleCopy = (text: string, fieldId: string) => {
    navigator.clipboard.writeText(text);
    setCopiedField(fieldId);
    toast.success("Copiado para a ├írea de transfer├¬ncia!");
    setTimeout(() => setCopiedField(null), 2000);
  };

  const allTxs = assetTransactions || [];
  const incomeTxs = financeTransactions || [];

  // --- 1. L├ôGICA DE BENS E DIREITOS ---
  const bensEDireitosList = assets
    .map(asset => {
      const posAnt = getPositionAtDate(asset, allTxs, `${selectedYear - 1}-12-31`);
      const posAtu = getPositionAtDate(asset, allTxs, `${selectedYear}-12-31`);

      return {
        asset,
        posAnt,
        posAtu,
        irDetails: getIRDetails(asset, selectedYear, posAnt.totalCost, posAtu.totalCost, posAtu.quantity, posAtu.avgPrice)
      };
    })
    .filter(item => item.posAnt.quantity > 0 || item.posAtu.quantity > 0);

  // --- 2. L├ôGICA DE RENDIMENTOS ISENTOS ---
  // Mapear transa├º├Áes financeiras de INCOME de subcategorias isentas
  // Subcategorias isentas comuns: Dividendos, Fundos Imobili├írios, Rendimento Poupan├ºa
  const isentosMap: Record<string, {
    codigo: string;
    tipo: string;
    cnpj: string;
    fontePagadora: string;
    valor: number;
    detalhes: string[];
  }> = {};

  // Dicion├írio de CNPJs de ativos para auto-resolu├º├úo de proventos
  const cnpjMap: Record<string, string> = {
    'PETR4': '33.000.167/0001-01', 'PETR3': '33.000.167/0001-01',
    'VALE3': '33.592.510/0001-54', 'ITUB4': '60.872.504/0001-23',
    'ITUB3': '60.872.504/0001-23', 'BBDC4': '60.746.948/0001-12',
    'BBDC3': '60.746.948/0001-12', 'BBAS3': '00.000.000/0001-91',
    'MGLU3': '47.960.950/0001-21', 'ABEV3': '07.526.557/0001-00',
    'WEGE3': '84.429.695/0001-11', 'B3SA3': '09.346.601/0001-25',
    'ITSA4': '17.217.989/0001-04', 'ITSA3': '17.217.989/0001-04',
    'MXRF11': '12.006.126/0001-60', 'HGLG11': '11.728.847/0001-70',
    'XPML11': '28.757.540/0001-48', 'KNIP11': '23.223.940/0001-38',
    'XPLG11': '26.685.992/0001-24', 'KNRI11': '12.005.956/0001-65',
    'HGRE11': '09.072.068/0001-16', 'VISC11': '18.860.759/0001-30'
  };

  // Helper para tentar achar o ativo e CNPJ a partir da descri├º├úo
  const resolveFontePagadora = (description: string) => {
    const descUpper = description.toUpperCase();
    const matchedAsset = assets.find(a => {
      const ticker = (a.ticker || '').toUpperCase();
      return ticker && descUpper.includes(ticker);
    });

    if (matchedAsset) {
      const ticker = (matchedAsset.ticker || '').toUpperCase();
      const cnpj = cnpjMap[ticker] || '';
      return {
        cnpj,
        razaoSocial: matchedAsset.name,
        ticker
      };
    }

    // Tenta encontrar algum ticker do mapa de CNPJ diretamente na descri├º├úo
    for (const ticker of Object.keys(cnpjMap)) {
      if (descUpper.includes(ticker)) {
        return {
          cnpj: cnpjMap[ticker],
          razaoSocial: `${ticker} - EMISSORA CONFORME TBL B3`,
          ticker
        };
      }
    }

    return { cnpj: '', razaoSocial: 'Outros Rendimentos / Proventos', ticker: '' };
  };

  incomeTxs.forEach(tx => {
    const catName = tx.category?.name || '';
    const amount = Number(tx.amount || 0);
    const desc = tx.description || '';
    const { cnpj, razaoSocial, ticker } = resolveFontePagadora(desc);

    const keyPrefix = ticker || razaoSocial;

    if (catName === 'Dividendos' || desc.toLowerCase().includes('dividendo') || desc.toLowerCase().includes('prov.')) {
      const code = '09';
      const key = `${code}-${keyPrefix}`;
      if (!isentosMap[key]) {
        isentosMap[key] = {
          codigo: '09 - Lucros e dividendos recebidos',
          tipo: 'Lucros e Dividendos',
          cnpj,
          fontePagadora: razaoSocial,
          valor: 0,
          detalhes: []
        };
      }
      isentosMap[key].valor = SafeFinancialCalculator.add(isentosMap[key].valor, amount);
      isentosMap[key].detalhes.push(`${tx.date.split('-').reverse().slice(0, 2).join('/')}: R$ ${amount.toFixed(2)} (${desc})`);
    } 
    else if (catName === 'Fundos Imobili├írios' || desc.toLowerCase().includes('fii') || desc.toLowerCase().includes('rend. fii')) {
      const code = '26';
      const key = `${code}-${keyPrefix}`;
      if (!isentosMap[key]) {
        isentosMap[key] = {
          codigo: '26 - Outros (Rendimentos de Fundos Imobili├írios Isentos)',
          tipo: 'Rendimento de FII (Isento)',
          cnpj,
          fontePagadora: razaoSocial,
          valor: 0,
          detalhes: []
        };
      }
      isentosMap[key].valor = SafeFinancialCalculator.add(isentosMap[key].valor, amount);
      isentosMap[key].detalhes.push(`${tx.date.split('-').reverse().slice(0, 2).join('/')}: R$ ${amount.toFixed(2)} (${desc})`);
    }
    else if (catName === 'Rendimento Poupan├ºa' || desc.toLowerCase().includes('poupan├ºa') || desc.toLowerCase().includes('lci') || desc.toLowerCase().includes('lca')) {
      const code = '12';
      const key = `${code}-${keyPrefix}`;
      if (!isentosMap[key]) {
        isentosMap[key] = {
          codigo: '12 - Rendimentos de cadernetas de poupan├ºa, letras de cr├®dito (LCI, LCA, CRI, CRA, etc.)',
          tipo: 'Rendimento de Renda Fixa Isenta',
          cnpj,
          fontePagadora: razaoSocial,
          valor: 0,
          detalhes: []
        };
      }
      isentosMap[key].valor = SafeFinancialCalculator.add(isentosMap[key].valor, amount);
      isentosMap[key].detalhes.push(`${tx.date.split('-').reverse().slice(0, 2).join('/')}: R$ ${amount.toFixed(2)} (${desc})`);
    }
  });

  // --- 3. L├ôGICA DE TRIBUTA├ç├âO EXCLUSIVA ---
  const tributacaoExclusivaMap: Record<string, {
    codigo: string;
    tipo: string;
    cnpj: string;
    fontePagadora: string;
    valor: number;
    detalhes: string[];
  }> = {};

  incomeTxs.forEach(tx => {
    const catName = tx.category?.name || '';
    const amount = Number(tx.amount || 0);
    const desc = tx.description || '';
    const { cnpj, razaoSocial, ticker } = resolveFontePagadora(desc);

    const keyPrefix = ticker || razaoSocial;

    if (catName === 'Juros' || desc.toLowerCase().includes('jcp') || desc.toLowerCase().includes('juros sobre capital') || desc.toLowerCase().includes('juros s/')) {
      const code = '10';
      const key = `${code}-${keyPrefix}`;
      if (!tributacaoExclusivaMap[key]) {
        tributacaoExclusivaMap[key] = {
          codigo: '10 - Juros sobre capital pr├│prio (JCP)',
          tipo: 'Juros sobre Capital Pr├│prio',
          cnpj,
          fontePagadora: razaoSocial,
          valor: 0,
          detalhes: []
        };
      }
      tributacaoExclusivaMap[key].valor = SafeFinancialCalculator.add(tributacaoExclusivaMap[key].valor, amount);
      tributacaoExclusivaMap[key].detalhes.push(`${tx.date.split('-').reverse().slice(0, 2).join('/')}: R$ ${amount.toFixed(2)} (${desc})`);
    }
    else if (catName === 'Rendimento CDB' || desc.toLowerCase().includes('cdb') || desc.toLowerCase().includes('tesouro direto') || desc.toLowerCase().includes('rdb')) {
      const code = '06';
      const key = `${code}-${keyPrefix}`;
      if (!tributacaoExclusivaMap[key]) {
        tributacaoExclusivaMap[key] = {
          codigo: '06 - Rendimentos de aplica├º├Áes financeiras (CDB, RDB, Tesouro Direto, Deb├¬ntures Comuns)',
          tipo: 'Rendimento de Aplica├º├úo Tributada',
          cnpj,
          fontePagadora: razaoSocial,
          valor: 0,
          detalhes: []
        };
      }
      tributacaoExclusivaMap[key].valor = SafeFinancialCalculator.add(tributacaoExclusivaMap[key].valor, amount);
      tributacaoExclusivaMap[key].detalhes.push(`${tx.date.split('-').reverse().slice(0, 2).join('/')}: R$ ${amount.toFixed(2)} (${desc})`);
    }
  });

  // --- 4. L├ôGICA DE RENDA VARI├üVEL / OPERA├ç├òES M├èS A M├èS ---
  // Coletar as transa├º├Áes ocorridas no ano selecionado
  const yearStart = `${selectedYear}-01-01`;
  const yearEnd = `${selectedYear}-12-31`;

  const operationsOfYear = allTxs.filter(tx => tx.date >= yearStart && tx.date <= yearEnd);

  // Mapear opera├º├Áes m├¬s a m├¬s
  const monthlyResumo: Record<number, {
    month: number;
    compras: number;
    vendas: number;
    vendasAcoes: number; // Para controle do limite de 20k
    lucroVendaAcoes: number;
    prejuizoAcumulado: number;
    txsCount: number;
    lucroEstimado: number;
  }> = {};

  // Inicializar os 12 meses
  for (let m = 0; m < 12; m++) {
    monthlyResumo[m] = {
      month: m,
      compras: 0,
      vendas: 0,
      vendasAcoes: 0,
      lucroVendaAcoes: 0,
      prejuizoAcumulado: 0,
      txsCount: 0,
      lucroEstimado: 0
    };
  }

  // L├│gica exata para c├ílculo de PnL de Vendas
  operationsOfYear.forEach(tx => {
    const txDate = new Date(tx.date);
    const m = txDate.getUTCMonth();
    const amount = Number(tx.quantity) * Number(tx.price);
    const asset = assets.find(a => a.id === tx.asset_id);

    monthlyResumo[m].txsCount++;

    if (tx.type === 'BUY') {
      monthlyResumo[m].compras = SafeFinancialCalculator.add(monthlyResumo[m].compras, amount);
    } else if (tx.type === 'SELL') {
      monthlyResumo[m].vendas = SafeFinancialCalculator.add(monthlyResumo[m].vendas, amount);

      // Calcular o lucro/preju├¡zo matem├ítico dessa venda com custo m├®dio ponderado
      if (asset) {
        // Obter todas as transa├º├Áes deste ativo ordenadas
        const assetTxs = allTxs.filter(t => t.asset_id === asset.id);
        
        // Obter transa├º├Áes anteriores a esta venda
        const priorTxs = assetTxs.filter(t => t.date < tx.date || (t.date === tx.date && t.id !== tx.id && t.created_at < tx.created_at));

        let qty = 0;
        let totalCost = 0;
        
        priorTxs.forEach(t => {
          const tQty = Number(t.quantity);
          const tPrice = Number(t.price);
          if (t.type === 'BUY') {
            totalCost = SafeFinancialCalculator.add(totalCost, SafeFinancialCalculator.multiply(tQty, tPrice));
            qty = SafeFinancialCalculator.add(qty, tQty);
          } else if (t.type === 'SELL') {
            if (qty > 0) {
              const currentAvg = SafeFinancialCalculator.divide(totalCost, qty);
              const soldQty = Math.min(tQty, qty);
              qty = SafeFinancialCalculator.subtract(qty, soldQty);
              totalCost = SafeFinancialCalculator.multiply(qty, currentAvg);
            }
          }
        });

        const avgPrice = qty > 0 ? SafeFinancialCalculator.divide(totalCost, qty) : Number(asset.purchase_price || 0);
        const salePrice = Number(tx.price);
        const saleQty = Number(tx.quantity);
        const profit = SafeFinancialCalculator.multiply(SafeFinancialCalculator.subtract(salePrice, avgPrice), saleQty);

        monthlyResumo[m].lucroEstimado = SafeFinancialCalculator.add(monthlyResumo[m].lucroEstimado, profit);

        if (asset.type === 'STOCK') {
          monthlyResumo[m].vendasAcoes = SafeFinancialCalculator.add(monthlyResumo[m].vendasAcoes, amount);
          if (profit > 0) {
            monthlyResumo[m].lucroVendaAcoes = SafeFinancialCalculator.add(monthlyResumo[m].lucroVendaAcoes, profit);
          } else {
            monthlyResumo[m].prejuizoAcumulado = SafeFinancialCalculator.add(monthlyResumo[m].prejuizoAcumulado, Math.abs(profit)); // Salva como positivo
          }
        }
      }
    }
  });

  const monthNames = [
    'Janeiro', 'Fevereiro', 'Mar├ºo', 'Abril', 'Maio', 'Junho',
    'Julho', 'Agosto', 'Setembro', 'Outubro', 'Novembro', 'Dezembro'
  ];


  return {
    currentYear,
    selectedYear, setSelectedYear,
    copiedField, setCopiedField,
    availableYears,
    assetTransactions, isLoadingAssetTxs,
    bensEDireitosList,
    isentosMap,
    tributacaoExclusivaMap,
    monthlyResumo,
    operationsOfYear,
    copyToClipboard: handleCopy,
    handleExportPDF: exportToIRPDF,
    handleExportExcel: exportToIRExcel,
    monthNames
  };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import type { Notification } from "@/services/notificationService";
import { logger } from "@/utils/logger";

export function useNotifications() {
  const { user } = useAuth();

  const query = useQuery({
    queryKey: ["notifications", user?.id],
    queryFn: async () => {
      if (!user) return [];

      const { data, error } = await supabase
        .from("notifications")
        .select("*")
        .eq("user_id", user.id)
        .eq("is_dismissed", false)
        .order("created_at", { ascending: false })
        .limit(50);

      if (error) throw error;
      return data as Notification[];
    },
    enabled: !!user,
    refetchInterval: 15000, // Polling a cada 15s como fallback do Realtime
    staleTime: 10000, // 10s de cache (Realtime invalida antes)
  });

  // Calcular notifica├º├Áes n├úo lidas
  const unreadCount = query.data?.filter((n) => !n.is_read).length || 0;

  return {
    ...query,
    unreadCount,
  };
}

export function useMarkNotificationAsRead() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (notificationId: string) => {
      const { error } = await supabase
        .from("notifications")
        .update({ is_read: true })
        .eq("id", notificationId);

      if (error) throw error;
    },
    onMutate: async (notificationId: string) => {
      await queryClient.cancelQueries({ queryKey: ["notifications", user?.id] });
      const previous = queryClient.getQueryData<Notification[]>(["notifications", user?.id]);
      queryClient.setQueryData<Notification[]>(
        ["notifications", user?.id],
        (old) => old?.map((n) => (n.id === notificationId ? { ...n, is_read: true } : n)) ?? []
      );
      return { previous };
    },
    onError: (_err, _id, context) => {
      if (context?.previous)
        queryClient.setQueryData(["notifications", user?.id], context.previous);
      logger.error("Erro ao marcar notifica├º├úo como lida:", _err);
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["notifications"] });
    },
  });
}

