// Hook para buscar prefer├¬ncias de notifica├º├úo
export function useNotificationPreferences() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["notification-preferences", user?.id],
    queryFn: async () => {
      if (!user) return null;

      const { data, error } = await (supabase.from("notification_preferences" as any) as any)
        .select("*")
        .eq("user_id", user.id)
        .maybeSingle();

      if (error) throw error;

      // Se n├úo existir, criar com valores padr├úo
      if (!data) {
        const { data: newPrefs, error: insertError } = await (
          supabase.from("notification_preferences" as any) as any
        )
          .insert({
            user_id: user.id,
            invoice_due_enabled: true,
            invoice_due_days_before: 3,
            budget_warning_enabled: true,
            budget_warning_threshold: 80,
            shared_pending_enabled: true,
            recurring_enabled: true,
            savings_goal_enabled: true,
            weekly_summary_enabled: true,
            email_notifications: false,
            push_notifications: false,
          })
          .select()
          .single();

        if (insertError) throw insertError;
        return newPrefs;
      }

      return data;
    },
    enabled: !!user,
    staleTime: 5 * 60 * 1000, // 5 minutos de cache
  });

  const updateMutation = useMutation({
    mutationFn: async (updates: Record<string, unknown>) => {
      if (!user) throw new Error("User not authenticated");

      const { data, error } = await (supabase.from("notification_preferences" as any) as any)
        .update(updates)
        .eq("user_id", user.id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["notification-preferences"] });
      toast.success("Prefer├¬ncias atualizadas");
    },
    onError: (error) => {
      toast.error("Erro ao atualizar prefer├¬ncias");
      logger.error("Erro ao atualizar prefer├¬ncias", error);
    },
  });

  return {
    preferences: query.data,
    isLoading: query.isLoading,
    updatePreferences: updateMutation.mutate,
    isUpdating: updateMutation.isPending,
  };
}

import { useState, useEffect } from 'react';
import { useMutation, useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import { useAuth } from '@/contexts/AuthContext';
import { toast } from 'sonner';

// VAPID public key ÔÇö deve estar em .env como VITE_VAPID_PUBLIC_KEY
const VAPID_PUBLIC_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY as string | undefined;

function urlBase64ToUint8Array(base64String: string): Uint8Array {
  const padding = '='.repeat((4 - (base64String.length % 4)) % 4);
  const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
  const rawData = atob(base64);
  return Uint8Array.from([...rawData].map(c => c.charCodeAt(0)));
}

export function usePushNotifications() {
  const { user } = useAuth();
  const [permission, setPermission] = useState<NotificationPermission>('default');

  useEffect(() => {
    if ('Notification' in window) setPermission(Notification.permission);
  }, []);

  const isSupported = 'serviceWorker' in navigator && 'PushManager' in window && !!VAPID_PUBLIC_KEY;

  const { data: hasSubscription, refetch } = useQuery({
    queryKey: ['push-subscription', user?.id],
    queryFn: async () => {
      if (!user) return false;
      const { count } = await supabase
        .from('push_subscriptions')
        .select('*', { count: 'exact', head: true })
        .eq('user_id', user.id);
      return (count ?? 0) > 0;
    },
    enabled: !!user && isSupported,
  });

  const subscribe = useMutation({
    mutationFn: async () => {
      if (!VAPID_PUBLIC_KEY) throw new Error('VAPID key n├úo configurada');
      const perm = await Notification.requestPermission();
      setPermission(perm);
      if (perm !== 'granted') throw new Error('Permiss├úo negada');

      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY),
      });
      const json = sub.toJSON();
      const { error } = await supabase.from('push_subscriptions').upsert({
        user_id: user!.id,
        endpoint: json.endpoint!,
        p256dh: (json.keys as any).p256dh,
        auth: (json.keys as any).auth,
      }, { onConflict: 'user_id,endpoint' });
      if (error) throw error;
    },
    onSuccess: () => { refetch(); toast.success('Notifica├º├Áes push ativadas'); },
    onError: (e: Error) => {
      if (e.message === 'Permiss├úo negada') toast.error('Permiss├úo negada pelo navegador');
      else toast.error('Erro ao ativar notifica├º├Áes');
    },
  });

  const unsubscribe = useMutation({
    mutationFn: async () => {
      const reg = await navigator.serviceWorker.ready;
      const sub = await reg.pushManager.getSubscription();
      if (sub) {
        await supabase.from('push_subscriptions').delete()
          .eq('user_id', user!.id).eq('endpoint', sub.endpoint);
        await sub.unsubscribe();
      }
    },
    onSuccess: () => { refetch(); toast.success('Notifica├º├Áes push desativadas'); },
    onError: () => toast.error('Erro ao desativar notifica├º├Áes'),
  });

  return { isSupported, permission, hasSubscription: !!hasSubscription, subscribe, unsubscribe };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
