export interface ScheduledBill {
  id: string;
  description: string;
  amount: number;
  date: string;
  currency: string | null;
  type: string;
  status: string;
  category: { id: string; name: string; icon: string | null } | null;
  account: { id: string; name: string } | null;
}

export function useScheduledBills() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["scheduled-bills", user?.id],
    staleTime: 1000 * 60 * 2,
    queryFn: async (): Promise<ScheduledBill[]> => {
      if (!user) return [];

      const { data, error } = await supabase
        .from("transactions")
        .select(
          `
          id, description, amount, date, currency, type, status,
          category:categories(id, name, icon),
          account:accounts!account_id(id, name)
        `
        )
        .eq("user_id", user.id)
        .eq("status", "PENDING")
        .is("deleted_at", null)
        .order("date", { ascending: true })
        .limit(50);

      if (error) throw error;
      return (data || []) as ScheduledBill[];
    },
    enabled: !!user,
  });
}

export function useConfirmScheduledBill() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({
      id,
      amount,
      paidDate,
    }: {
      id: string;
      amount?: number;
      paidDate?: string;
    }) => {
      if (!user) throw new Error("Usu├írio n├úo autenticado");

      const date = paidDate ?? format(new Date(), "yyyy-MM-dd");
      const update: Record<string, unknown> = { status: "CONFIRMED", date };
      if (amount !== undefined) update.amount = amount;
      const { error } = await supabase
        .from("transactions")
        .update(update)
        .eq("id", id)
        .eq("user_id", user.id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["scheduled-bills"] });
      queryClient.invalidateQueries({ queryKey: ["transactions"] });
      toast.success("Confirmado com sucesso");
    },
    onError: () => {
      toast.error("Erro ao confirmar");
    },
  });
}

