export interface SharedCreditCard {
  id: string;
  account_id: string;
  user_id: string;
  status: 'PENDING' | 'ACCEPTED' | 'REJECTED' | 'REVOKED';
  credit_limit?: number | null;
  created_at: string;
  updated_at: string;
  account?: any; // Para quando vier com join
  user?: any; // Para quando vier com join
}

export function useSharedCreditCards(accountId?: string) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["shared-credit-cards", accountId, user?.id],
    queryFn: async () => {
      if (!user) return [];

      let query = supabase
        .from("shared_credit_cards")
        .select("*, user:profiles!shared_credit_cards_user_id_fkey(full_name, email, avatar_url, avatar_icon, avatar_color), accounts(name)");

      if (accountId) {
        query = query.eq("account_id", accountId);
      } else {
        query = query.eq("user_id", user.id);
      }

      const { data, error } = await query.order("created_at");

      if (error) {
        logger.error("Erro ao buscar cart├Áes compartilhados:", error);
        throw error;
      }
      return data as SharedCreditCard[];
    },
    enabled: !!user,
  });
}

export function useInviteSharedCard() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ accountId, userId, cardName, creditLimit }: { accountId: string; userId: string; cardName: string; creditLimit?: number | null }) => {
      // First check if it exists
      const { data: existing } = await supabase
        .from("shared_credit_cards")
        .select("id")
        .eq("account_id", accountId)
        .eq("user_id", userId)
        .maybeSingle();

      let data, error;
      
      if (existing) {
        const res = await supabase
          .from("shared_credit_cards")
          .update({ status: 'PENDING', credit_limit: creditLimit || null })
          .eq("id", existing.id)
          .select()
          .single();
        data = res.data;
        error = res.error;
      } else {
        const res = await supabase
          .from("shared_credit_cards")
          .insert({
            account_id: accountId,
            user_id: userId,
            status: 'PENDING',
            credit_limit: creditLimit || null,
          })
          .select()
          .single();
        data = res.data;
        error = res.error;
      }

      if (error) throw error;

      // Criar notifica├º├úo para o usu├írio convidado
      if (user) {
        await supabase.from("notifications").insert({
          user_id: userId,
          title: "Convite de Cart├úo Compartilhado",
          message: `Voc├¬ foi convidado para compartilhar o cart├úo ${cardName}.`,
          type: "INVITATION",
          read: false,
          metadata: { type: 'shared_card_invite', shared_card_id: data.id, account_id: accountId }
        });
      }

      return data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["shared-credit-cards", variables.accountId] });
      toast.success("Convite enviado com sucesso!");
    },
    onError: (error: any) => {
      toast.error(error.message || "Erro ao convidar usu├írio.");
    },
  });
}

