    },
  });
}

import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { ERROR_MESSAGES, SettlementErrorCode } from "@/services/settlementValidation";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { User } from "@supabase/supabase-js";
import {
  createSettlementRequestNotification,
  createPaymentConfirmedNotification,
  createSettlementRejectedNotification,
  createNotification,
  createDebtorSettlementRequestNotification,
} from "@/services/notificationService";

import { FamilyMember } from "@/hooks/useFamily";
import { moneyUtils } from "@/utils/money";
import { logger } from "@/utils/logger";

interface SharedExpensesActionsProps {
  selectedMember: string | null;
  settleAccountId: string;
  settleType: "PAY" | "RECEIVE";
  settleAmount: string;
  selectedItems: string[];
  settleDate: string;
  members: FamilyMember[];
  getFilteredInvoice: (memberId: string) => InvoiceItem[];
  createTransaction: any; // Facilitando a integra├º├úo de tipos complexos do Tanstack Query
  queryClient?: any; /* any */
  user: User | null;
  invalidateRelated: (txId: string) => Promise<void>;
  refetch: () => Promise<void | any>;
  undoConfirm: { isOpen: boolean; item: InvoiceItem | null };
  setUndoConfirm: (val: { isOpen: boolean; item: InvoiceItem | null }) => void;
  deleteConfirm: { isOpen: boolean; item: InvoiceItem | null };
  setDeleteConfirm: (val: { isOpen: boolean; item: InvoiceItem | null }) => void;
  deleteSeriesConfirm: { isOpen: boolean; item: InvoiceItem | null };
  setDeleteSeriesConfirm: (val: { isOpen: boolean; item: InvoiceItem | null }) => void;
  setIsUndoingAll: (val: boolean) => void;
  setUndoAllConfirm: (val: boolean) => void;
  setIsSettling: (val: boolean) => void;
  setShowSettleDialog: (val: boolean) => void;
  setSelectedMember: (val: string | null) => void;
  setSettleAmount: (val: string) => void;
  setSettleAccountId: (val: string) => void;
  setSelectedItems: (val: string[]) => void;
  formatCurrency: (amount: number, currency: string) => string;
  exchangeRate?: string;
  accounts: any[];
  onConfirmReceipt?: (items: InvoiceItem[], accountId: string, date: string) => Promise<void>;
  onRejectSettlement?: (item: InvoiceItem, reason: string) => Promise<void>;
}

export function useSharedExpensesActions(props: SharedExpensesActionsProps) {
  const {
    selectedMember,
    settleAccountId,
    settleAmount,
    selectedItems,
    settleDate,
    members,
    getFilteredInvoice,
    user,
    invalidateRelated,
    refetch,
    undoConfirm,
    setUndoConfirm,
    deleteConfirm,
    setDeleteConfirm,
    deleteSeriesConfirm,
    setDeleteSeriesConfirm,
    setIsUndoingAll,
    setUndoAllConfirm,
    setIsSettling,
    setShowSettleDialog,
    setSelectedMember,
    setSettleAmount,
    setSettleAccountId,
    setSelectedItems,
    formatCurrency,
    queryClient,
  } = props;

  const handleSettle = async () => {
    if (!user) {
      toast.error("Usu├írio n├úo autenticado");
      return;
    }

    if (!selectedMember || !settleAccountId) {
      toast.error("Selecione uma conta");
      return;
    }

    setIsSettling(true);
    try {
      const member = members.find((m) => m.id === selectedMember);
      const items = getFilteredInvoice(selectedMember);

      const itemsToSettle =
        selectedItems.length > 0
          ? items.filter((i) => selectedItems.includes(i.id))
          : items.filter((i) => !i.isPaid);

      if (itemsToSettle.length === 0) {
        toast.error("Nenhum item para acertar");
        setIsSettling(false);
        return;
      }

      const amount = moneyUtils.parse(settleAmount.replace(".", "").replace(",", "."));
      if (isNaN(amount) || amount < 0) {
        toast.error("Valor inv├ílido");
        setIsSettling(false);
        return;
      }

      const settlementCurrency = itemsToSettle[0]?.currency || "BRL";

      const itemsTotal = itemsToSettle.reduce((sum, item) => {
        if (item.type === "CREDIT") return SafeFinancialCalculator.add(sum, item.amount);
        return SafeFinancialCalculator.subtract(sum, item.amount);
      }, 0);

      const absoluteTotalDue = Math.abs(itemsTotal);

      if (amount > absoluteTotalDue + 0.01) {
        toast.error(
          `O valor do acerto (${SafeFinancialCalculator.formatCurrency(amount, settlementCurrency)}) n├úo pode ser maior que o total devido (${SafeFinancialCalculator.formatCurrency(absoluteTotalDue, settlementCurrency)})`
        );
        setIsSettling(false);
        return;
      }

      const splitIds = itemsToSettle.map((i) => i.splitId).filter((id): id is string => !!id);
      const txId: string | null = null;

      // SEC-004: bloquear liquida├º├úo de itens de dom├¡nios distintos na mesma opera├º├úo
      const uniqueTripIdsCheck = [...new Set(itemsToSettle.map((i) => i.tripId ?? null))];
      const domainsInBatch = new Set(itemsToSettle.map((i) => (i.tripId ? "TRAVEL" : "PERSONAL")));
      if (domainsInBatch.size > 1 || uniqueTripIdsCheck.filter(Boolean).length > 1) {
        toast.error(
          "N├úo ├® poss├¡vel acertar itens de viagens diferentes em uma ├║nica opera├º├úo. Selecione apenas itens da mesma origem."
        );
        setIsSettling(false);
        return;
      }

      const hasCredits = itemsToSettle.some((i) => i.type === "CREDIT");
      const hasDebits = itemsToSettle.some((i) => i.type === "DEBIT");
      const isCompensated = hasCredits && hasDebits;

      // ATUALIZA├ç├âO OTIMISTA
      setShowSettleDialog(false);
      const previousState = queryClient
        ? queryClient.getQueryData(["shared-transactions-consolidated"])
        : null;
      if (queryClient) {
        queryClient.setQueryData(["shared-transactions-consolidated"], (old: any /* any */) => {
          if (!old) return old;
          return old.map((tx: any /* any */) => {
            if (tx.transaction_splits && Array.isArray(tx.transaction_splits)) {
              return {
                ...tx,
                transaction_splits: tx.transaction_splits.map((split: any /* any */) => {
                  if (splitIds.includes(split.id)) {
                    const isPerfectComp = Math.abs(itemsTotal) < 0.01;
                    return {
                      ...split,
                      settled_by_debtor:
                        user?.id === split.debtor_id ? true : split.settled_by_debtor,
                      settled_by_creditor:
                        user?.id === split.creditor_id ? true : split.settled_by_creditor,
                      is_settled: isPerfectComp ? true : split.is_settled,
                    };
                  }
                  return split;
                }),
              };
            }
            return tx;
          });
        });
      }

      const uniqueTripIds = [...new Set(itemsToSettle.map((i) => i.tripId).filter(Boolean))];
      const tripId = uniqueTripIds.length === 1 ? uniqueTripIds[0] : null;
      const domain = tripId ? "TRAVEL" : "SHARED";

      // 1. Caso de compensa├º├úo perfeita (valores iguais se anulam)
      if (Math.abs(itemsTotal) < 0.01) {
        const { error: updateError } = await supabase
          .from("transaction_splits")
          .update({
            settled_by_debtor: true,
            settled_by_creditor: true,
            is_settled: true,
            settled_at: new Date().toISOString(),
          })
          .in("id", splitIds);

        if (updateError) throw updateError;

        // Notificar o outro usu├írio de que as d├¡vidas foram compensadas perfeitamente
        const otherUserId = member?.linked_user_id || itemsToSettle[0]?.creatorUserId;
        if (otherUserId && otherUserId !== user.id) {
          import("@/services/notificationService").then(
            ({ createPerfectCompensationNotification }) => {
              createPerfectCompensationNotification(
                otherUserId,
                user?.user_metadata?.name || user?.email || "Algu├®m",
                itemsToSettle.length
              ).catch((err) =>
                logger.error("Error creating perfect compensation notification:", err)
              );
            }
          );
        }

        toast.success("Compensa├º├úo realizada com sucesso! As despesas m├║tuas se anularam.");
      }
      // 2. O usu├írio ├® o credor l├¡quido (recebendo o valor compensado)
      else if (itemsTotal > 0) {
        const { data, error } = await supabase.rpc("request_settlement", {
          p_split_ids: splitIds,
          p_account_id: settleAccountId,
          p_user_id: user.id,
          p_is_payment: false,
        });

        if (error) throw error;

        // Notificar devedor para vincular a conta de onde o dinheiro saiu
        const debtorUserId = member?.linked_user_id;
        if (debtorUserId && debtorUserId !== user.id) {
          await createDebtorSettlementRequestNotification(
            debtorUserId,
            user?.user_metadata?.name || user?.email || "O credor",
            amount,
            settlementCurrency,
            splitIds,
            (data as any)?.transaction_id,
            isCompensated
          );
        }

        toast.success(
          `Solicita├º├úo de confirma├º├úo de conta enviada para ${member?.name || "o devedor"}!`
        );
      }
      // 3. O usu├írio ├® o devedor l├¡quido (pagando o saldo compensado)
      else {
        const { data, error } = await supabase.rpc("request_settlement", {
          p_split_ids: splitIds,
          p_account_id: settleAccountId,
          p_user_id: user.id,
          p_is_payment: true,
        });

        if (error) throw error;

        // Enviar notifica├º├úo de acerto para o credor confirmar
        const creditorUserId = member?.linked_user_id || itemsToSettle[0]?.creatorUserId;
        if (creditorUserId && creditorUserId !== user.id) {
          await createSettlementRequestNotification(
            creditorUserId,
            user?.user_metadata?.name || user?.email || "Algu├®m",
            amount,
            settlementCurrency,
            splitIds[0],
            isCompensated
          );
        }

        toast.success(
          `Acerto de ${formatCurrency(amount, settlementCurrency)} enviado para confirma├º├úo do credor!`
        );
      }

      setSelectedMember(null);
      setSettleAmount("");
      setSettleAccountId("");
      setSelectedItems([]);

      if (itemsToSettle[0]?.originalTxId) {
        await invalidateRelated(itemsToSettle[0].originalTxId);
      }
      refetch(); // Sem await para n├úo travar a UI
    } catch (error) {
      logger.error("Settlement error", error);
      // Rollback imediato do optimistic update
      if (queryClient && previousState) {
        queryClient.setQueryData(["shared-transactions-consolidated"], previousState);
      }
      queryClient?.invalidateQueries({ queryKey: ["shared-transactions-consolidated"] });
      toast.error("Erro ao realizar acerto");
    } finally {
      setIsSettling(false);
    }
  };

  const handleUndoSettlement = async () => {
    const item = undoConfirm.item;
    if (!item || !item.splitId) return;

    try {
      const { data, error } = await supabase.rpc("undo_settlement", {
        p_split_id: item.splitId,
        p_user_id: user?.id,
      });

      if (error) {
        logger.error("Erro no RPC undo_settlement:", error);
        throw error;
      }

      const result = data as { success?: boolean; error?: string };
      if (result && result.success === false) {
        toast.error(result.error || "Erro ao desfazer acerto");
        return;
      }

      showActionFeedback("success");
      setTimeout(() => {
        setUndoConfirm({ isOpen: false, item: null });
      }, 80);

      if (item.originalTxId) {
        await invalidateRelated(item.originalTxId);
      }
      await refetch();

      // Identificar o outro usu├írio corretamente: memberId ├® family_members.id,
      // user?.id ├® auth.users.id ÔÇö comparar via linked_user_id
      const myMember = members.find((m) => m.linked_user_id === user?.id);
      const isMe = myMember && item.memberId === myMember.id;
      const otherUserId = isMe
        ? item.creatorUserId
        : members.find((m) => m.id === item.memberId)?.linked_user_id;
      if (otherUserId && otherUserId !== user?.id) {
        await createSettlementRejectedNotification(
          otherUserId,
          user?.user_metadata?.name || user?.email || "Algu├®m",
          item.description
        );
      }

      toast.success("Acerto desfeito com sucesso!");
    } catch (error) {
      logger.error("Erro ao desfazer acerto", error);
      toast.error("Erro ao desfazer acerto");
    }
  };

  const handleDeleteTransaction = async () => {
    const item = deleteConfirm.item;
    if (!item || !item.originalTxId) return;

    try {
      if (!item.canDelete) {
        const errorMsg =
          item.blockReason || ERROR_MESSAGES[SettlementErrorCode.TRANSACTION_SETTLED];
        const errorMessage = typeof errorMsg === "string" ? errorMsg : errorMsg.message;
        toast.error(errorMessage);
        setDeleteConfirm({ isOpen: false, item: null });
        return;
      }

      if (item.creatorUserId && item.creatorUserId !== user?.id) {
        toast.error("Apenas o criador da transa├º├úo pode exclu├¡-la");
        setDeleteConfirm({ isOpen: false, item: null });
        return;
      }

      const { error } = await supabase.from("transactions").delete().eq("id", item.originalTxId);

      if (error) throw error;

      showActionFeedback("success");
      setTimeout(() => {
        setDeleteConfirm({ isOpen: false, item: null });
      }, 80);

      await invalidateRelated(item.originalTxId);
      await refetch();

      const otherUserId = members.find((m) => m.id === item.memberId)?.linked_user_id;
      if (otherUserId && otherUserId !== user?.id) {
        await createNotification({
          user_id: otherUserId,
          type: "SHARED_EXPENSE",
          title: "Transa├º├úo Removida",
          message: `${user?.user_metadata?.name || user?.email || "Algu├®m"} excluiu a transa├º├úo compartilhada "${item.description}".`,
          icon: "­ƒùæ´©Å",
          priority: "NORMAL",
        });
      }
    } catch (error) {
      logger.error("Erro ao excluir transa├º├úo", error);
      showActionFeedback("error");
      toast.error("Erro ao excluir transa├º├úo");
    }
  };

  const handleDeleteSeries = async () => {
    const item = deleteSeriesConfirm.item;
    if (!item || !item.seriesId) return;

    try {
      if (!item.canDelete) {
        const errorMsg =
          item.blockReason || ERROR_MESSAGES[SettlementErrorCode.SERIES_HAS_SETTLED_INSTALLMENTS];
        const errorMessage = typeof errorMsg === "string" ? errorMsg : errorMsg.message;
        toast.error(errorMessage);
        setDeleteSeriesConfirm({ isOpen: false, item: null });
        return;
      }

      if (item.creatorUserId && item.creatorUserId !== user?.id) {
        toast.error("Apenas o criador da s├®rie pode exclu├¡-la");
        setDeleteSeriesConfirm({ isOpen: false, item: null });
        return;
      }

      const { data, error } = await supabase.rpc("delete_installment_series" as any, {
        p_series_id: item.seriesId,
      });
      if (error) throw error;

      const deletedCount = data?.[0]?.deleted_count || 0;
      if (deletedCount === 0) throw new Error("Nenhuma parcela foi exclu├¡da.");

      showActionFeedback("success");
      setTimeout(() => {
        setDeleteSeriesConfirm({ isOpen: false, item: null });
      }, 80);
      if (item.originalTxId) await invalidateRelated(item.originalTxId);
      await refetch();

      const otherUserId = members.find((m) => m.id === item.memberId)?.linked_user_id;
      if (otherUserId && otherUserId !== user?.id) {
        await createNotification({
          user_id: otherUserId,
          type: "SHARED_EXPENSE",
          title: "S├®rie de Parcelas Removida",
          message: `${user?.user_metadata?.name || user?.email || "Algu├®m"} excluiu uma s├®rie de ${item.totalInstallments} parcelas compartilhadas ("${item.description}").`,
          icon: "­ƒùæ´©Å",
          priority: "NORMAL",
        });
      }
    } catch (error) {
      logger.error("Erro ao excluir s├®rie", error);
      toast.error("Erro ao excluir s├®rie");
    }
  };

  const handleUndoAll = async () => {
    setIsUndoingAll(true);
    try {
      const allPaidItems: InvoiceItem[] = [];
      members.forEach((member) => {
        const items = getFilteredInvoice(member.id);
        const paidItems = items.filter((i) => i.isPaid && i.splitId);
        allPaidItems.push(...paidItems);
      });

      if (allPaidItems.length === 0) {
        toast.info("N├úo h├í itens acertados para desfazer neste per├¡odo.");
        setUndoAllConfirm(false);
        setIsUndoingAll(false);
        return;
      }

      let successCount = 0;
      for (const item of allPaidItems) {
        try {
          if (item.splitId) {
            const { error } = await supabase.rpc("undo_settlement", {
              p_split_id: item.splitId,
              p_user_id: user?.id,
            });

            if (error) {
              logger.error(`Erro ao desfazer split ${item.splitId}:`, error);
              continue;
            }

            successCount++;
          }
        } catch (err) {
          logger.error("Erro ao desfazer item no Undo All", err);
        }
      }

      setUndoAllConfirm(false);
      await refetch();
      toast.success(`${successCount} acerto(s) desfeito(s) com sucesso!`);
    } catch (error) {
      logger.error("Erro ao desfazer todos os acertos", error);
      toast.error("Erro ao desfazer os acertos");
    } finally {
      setIsUndoingAll(false);
      setUndoAllConfirm(false);
    }
  };

  const handleConfirmReceipt = async (
    items: InvoiceItem[],
    accountId: string,
    date: string,
    exchangeRate?: number
  ) => {
    if (!user?.id) return;
    setIsSettling(true);
    try {
      const hasCredit = items.some((i) => i.type === "CREDIT");
      const hasDebit = items.some((i) => i.type === "DEBIT");
      const isNetting = hasCredit && hasDebit;

      // ATUALIZA├ç├âO OTIMISTA
      const previousConfirmState = queryClient
        ? queryClient.getQueryData(["shared-transactions-consolidated"])
        : null;
      if (queryClient) {
        queryClient.setQueryData(["shared-transactions-consolidated"], (old: any /* any */) => {
          if (!old) return old;
          return old.map((tx: any /* any */) => {
            if (tx.transaction_splits && Array.isArray(tx.transaction_splits)) {
              return {
                ...tx,
                transaction_splits: tx.transaction_splits.map((split: any /* any */) => {
                  if (items.some((i) => i.splitId === split.id)) {
                    return { ...split, settled_by_creditor: true, is_settled: true };
                  }
                  return split;
                }),
              };
            }
            return tx;
          });
        });
      }

      if (isNetting) {
        // Netting confirmation: handle custom netting transaction and split update
        const netTotal = items.reduce((sum, item) => {
          if (item.type === "CREDIT") return SafeFinancialCalculator.add(sum, item.amount);
          return SafeFinancialCalculator.subtract(sum, item.amount);
        }, 0);

        const amount = Math.abs(netTotal);
        const settlementCurrency = items[0]?.currency || "BRL";
        let txId: string | null = null;

        const uniqueTripIds = [...new Set(items.map((i) => i.tripId).filter(Boolean))];
        const tripId = uniqueTripIds.length === 1 ? uniqueTripIds[0] : null;
        const domain = tripId ? "TRAVEL" : "SHARED";

        if (amount > 0.01) {
          const isIncome = netTotal > 0;
          const { data: txData, error: txError } = await supabase
            .from("transactions")
            .insert({
              user_id: user.id,
              creator_user_id: user.id,
              account_id: accountId,
              amount: amount,
              type: isIncome ? "INCOME" : "EXPENSE",
              description: `Recebimento de acerto por compensa├º├úo`,
              date: date,
              competence_date: date,
              domain: domain,
              trip_id: tripId,
              is_shared: false,
              is_settled: true,
              currency: settlementCurrency,
            })
            .select("id")
            .single();

          if (txError) throw txError;
          txId = txData.id;
        }

        // Update all splits to mark them as fully settled
        const splitIds = items.map((i) => i.splitId).filter((id): id is string => !!id);
        const { error: updateError } = await supabase
          .from("transaction_splits")
          .update({
            settled_by_creditor: true,
            settled_by_debtor: true,
            is_settled: true,
            settled_at: new Date().toISOString(),
            settled_transaction_id: txId || undefined,
          })
          .in("id", splitIds);

        if (updateError) throw updateError;

        toast.success("Acerto por compensa├º├úo confirmado com sucesso!");
      } else {
        // Standard non-netted confirmation: use standard RPC
        const splitIds = items.map((i) => i.splitId).filter((id): id is string => !!id);
        const { data, error } = await supabase.rpc("confirm_settlement", {
          p_split_ids: splitIds,
          p_account_id: accountId,
          p_user_id: user.id,
          p_is_receiving: true,
        });

        if (error) throw error;

        // Link created transaction to trip if applicable
        const uniqueTripIds = [...new Set(items.map((i) => i.tripId).filter(Boolean))];
        const tripId = uniqueTripIds.length === 1 ? uniqueTripIds[0] : null;
        if (tripId) {
          const txId = (data as any)?.transaction_id;
          if (txId) {
            await supabase
              .from("transactions")
              .update({ trip_id: tripId, domain: "TRAVEL" })
              .eq("id", txId);
          }
        }

        const result = data as unknown as { success?: boolean; error?: string };
        if (result && result.success === false) {
          toast.error(result.error || "Erro ao confirmar recebimento");
          setIsSettling(false);
          return;
        }

        toast.success("Recebimento confirmado!");
      }

      refetch(); // Sem await

      const debtorId =
        items[0]?.memberId === user?.id ? items[0]?.creatorUserId : items[0]?.memberId;
      const debtorUserId = members.find((m) => m.id === debtorId)?.linked_user_id;

      if (debtorUserId && debtorUserId !== user?.id) {
        await createPaymentConfirmedNotification(
          debtorUserId,
          user?.user_metadata?.name || user?.email || "O credor"
        );
      }
    } catch (error) {
      logger.error("Erro ao confirmar recebimento", error);
      // Rollback imediato do optimistic update
      if (queryClient && previousConfirmState) {
        queryClient.setQueryData(["shared-transactions-consolidated"], previousConfirmState);
      }
      queryClient?.invalidateQueries({ queryKey: ["shared-transactions-consolidated"] });
      toast.error("Erro ao confirmar recebimento");
    } finally {
      setIsSettling(false);
    }
  };

  const handleRejectSettlement = async (item: InvoiceItem, reason: string) => {
    if (!user?.id || !item.splitId) return;
    try {
      const { error } = await supabase.rpc("reject_settlement_request", {
        p_split_id: item.splitId,
        p_reason: reason,
      });
      if (error) throw error;
      toast.success("Acerto recusado.");
      await refetch();

      const debtorUserId = members.find((m) => m.id === item.memberId)?.linked_user_id;
      if (debtorUserId && debtorUserId !== user?.id) {
        await createSettlementRejectedNotification(
          debtorUserId,
          user?.user_metadata?.name || user?.email || "O credor",
          item.description,
          reason
        );
      }
    } catch (error) {
      logger.error("Erro ao recusar acerto", error);
      toast.error("Erro ao recusar acerto");
    }
  };

  const handleConfirmPayment = async (
    items: InvoiceItem[],
    accountId: string,
    date: string,
    exchangeRate?: number
  ) => {
    if (!user?.id) return;
    setIsSettling(true);
    try {
      const amount = items.reduce((sum, item) => SafeFinancialCalculator.add(sum, item.amount), 0);
      const settlementCurrency = items[0]?.currency || "BRL";

      const uniqueTripIds = [...new Set(items.map((i) => i.tripId).filter(Boolean))];
      const tripId = uniqueTripIds.length === 1 ? uniqueTripIds[0] : null;
      const domain = tripId ? "TRAVEL" : "SHARED";

      const splitIds = items.map((i) => i.splitId).filter((id): id is string => !!id);

      // ATUALIZA├ç├âO OTIMISTA
      if (queryClient) {
        queryClient.setQueryData(["shared-transactions-consolidated"], (old: any /* any */) => {
          if (!old) return old;
          return old.map((tx: any /* any */) => {
            if (tx.transaction_splits && Array.isArray(tx.transaction_splits)) {
              return {
                ...tx,
                transaction_splits: tx.transaction_splits.map((split: any /* any */) => {
                  if (splitIds.includes(split.id)) {
                    const creditorAlreadyConfirmed = split.settled_by_creditor === true;
                    return {
                      ...split,
                      settled_by_debtor: true,
                      is_settled: creditorAlreadyConfirmed ? true : split.is_settled,
                    };
                  }
                  return split;
                }),
              };
            }
            return tx;
          });
        });
      }

      const { data, error } = await supabase.rpc("confirm_settlement", {
        p_split_ids: splitIds,
        p_account_id: accountId,
        p_user_id: user.id,
        p_is_receiving: false,
      });

      if (error) throw error;

      // Link created transaction to trip if applicable
      if (tripId) {
        const txId = (data as any)?.transaction_id;
        if (txId) {
          await supabase
            .from("transactions")
            .update({ trip_id: tripId, domain: "TRAVEL" })
            .eq("id", txId);
        }
      }

      // 3. Notificar o credor de que a conta foi vinculada e o acerto foi liquidado bilateralmente!
      const creditorUserId = items[0]?.creatorUserId;
      if (creditorUserId && creditorUserId !== user.id) {
        await createPaymentConfirmedNotification(
          creditorUserId,
          user?.user_metadata?.name || user?.email || "O devedor"
        );
      }

      toast.success("Pagamento e conta vinculada confirmados com sucesso! Acerto finalizado.");
      refetch(); // Sem await
    } catch (error) {
      logger.error("Erro ao confirmar pagamento", error);
      if (queryClient) {
        queryClient.invalidateQueries({ queryKey: ["shared-transactions-consolidated"] });
      }
      toast.error("Erro ao confirmar pagamento");
    } finally {
      setIsSettling(false);
    }
  };

  const handleRejectDebtorSettlement = async (items: InvoiceItem[], reason: string) => {
    if (!user?.id || items.length === 0) return;
    try {
      // 1. Buscar a transa├º├úo do credor associada
      const splitIds = items.map((i) => i.splitId).filter((id): id is string => !!id);
      const { data: splitsData, error: splitsError } = await supabase
        .from("transaction_splits")
        .select("creditor_settlement_tx_id")
        .in("id", splitIds)
        .not("creditor_settlement_tx_id", "is", null);

      if (splitsError) throw splitsError;

      const creditorTxId = splitsData?.[0]?.creditor_settlement_tx_id;

      // 2. Se houver transa├º├úo do credor, excluir para estornar o cr├®dito tempor├írio
      if (creditorTxId) {
        await supabase.from("transactions").delete().eq("id", creditorTxId);
      }

      // 3. Resetar os splits para pendentes
      const { error: updateError } = await supabase
        .from("transaction_splits")
        .update({
          settled_by_creditor: false,
          creditor_settlement_tx_id: null,
          settled_by_debtor: false,
          debtor_settlement_tx_id: null,
          is_settled: false,
          settled_at: null,
        })
        .in("id", splitIds);

      if (updateError) throw updateError;

      toast.success(
        "Acerto recusado. A transa├º├úo do credor foi desfeita e os lan├ºamentos voltaram a ficar pendentes."
      );
      await refetch();

      // 4. Notificar credor
      const creditorUserId = items[0]?.creatorUserId;
      if (creditorUserId && creditorUserId !== user?.id) {
        await createSettlementRejectedNotification(
          creditorUserId,
          user?.user_metadata?.name || user?.email || "O devedor",
          items[0].description,
          reason
        );
      }
    } catch (error) {
      logger.error("Erro ao recusar acerto do credor", error);
      toast.error("Erro ao recusar acerto");
    }
  };

  return {
    handleSettle,
    handleUndoSettlement,
    handleDeleteTransaction,
    handleDeleteSeries,
    handleUndoAll,
    handleConfirmReceipt,
    handleRejectSettlement,
    handleConfirmPayment,
    handleRejectDebtorSettlement,
  };
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { SafeFinancialCalculator } from '@/services/SafeFinancialCalculator';

/**
 * Testes para useSharedFinances
 * 
 * Valida c├ílculos de finan├ºas compartilhadas, splits e faturas
 * 
 * **Validates: Requirements 1.5**
 */

describe('useSharedFinances - Shared Finances Calculations', () => {
  describe('C├ílculo de Splits', () => {
    it('deve calcular splits corretamente quando dividindo entre m├║ltiplos membros', () => {
      const total = 100;
      const splits = [
        { percentage: 50 },
        { percentage: 50 },
      ];

      const result = SafeFinancialCalculator.distributeSplits(total, splits);

      expect(result).toHaveLength(2);
      expect(result[0].amount).toBe(50);
      expect(result[1].amount).toBe(50);
      expect(result[0].amount + result[1].amount).toBe(100);
    });

    it('deve validar que soma de splits n├úo excede total + 1 centavo', () => {
      const total = 100;
      const splits = [
        { amount: 33.33 },
        { amount: 33.33 },
        { amount: 33.33 },
      ];

      const isValid = SafeFinancialCalculator.validateSplits(total, splits);

      expect(isValid).toBe(true);
    });

    it('deve rejeitar splits que excedem total', () => {
      const total = 100;
      const splits = [
        { amount: 60 },
        { amount: 50 },
      ];

      const isValid = SafeFinancialCalculator.validateSplits(total, splits);

      expect(isValid).toBe(false);
    });

    it('deve distribuir splits com ajuste na ├║ltima parcela para precis├úo', () => {
      const total = 100;
      const splits = [
        { percentage: 33.33 },
        { percentage: 33.33 },
        { percentage: 33.34 },
      ];

      const result = SafeFinancialCalculator.distributeSplits(total, splits);
      const sum = result.reduce((acc, r) => SafeFinancialCalculator.add(acc, r.amount), 0);

      expect(sum).toBe(100);
    });
  });

  describe('C├ílculo de Faturas', () => {
    it('deve calcular total de fatura corretamente', () => {
      const transactions = [
        { type: 'EXPENSE', amount: 100 },
        { type: 'EXPENSE', amount: 50 },
        { type: 'INCOME', amount: 30 },
      ];

      const total = transactions.reduce((acc, tx) => {
        if (tx.type === 'EXPENSE') return acc + tx.amount;
        if (tx.type === 'INCOME') return acc - tx.amount;
        return acc;
      }, 0);

      expect(total).toBe(120);
    });

    it('deve filtrar transa├º├Áes por m├¬s de compet├¬ncia corretamente', () => {
      const transactions = [
        { competence_date: '2024-01-01', amount: 100 },
        { competence_date: '2024-01-01', amount: 50 },
        { competence_date: '2024-02-01', amount: 75 },
      ];

      const targetMonth = '2024-01';
      const filtered = transactions.filter(tx => tx.competence_date.startsWith(targetMonth));

      expect(filtered).toHaveLength(2);
      expect(filtered[0].amount + filtered[1].amount).toBe(150);
    });

    it('deve agrupar transa├º├Áes por membro corretamente', () => {
      const invoiceItems = [
        { memberId: 'member-1', amount: 100, type: 'CREDIT' },
        { memberId: 'member-1', amount: 50, type: 'CREDIT' },
        { memberId: 'member-2', amount: 75, type: 'DEBIT' },
      ];

      const grouped: Record<string, any[]> = {};
      invoiceItems.forEach(item => {
        if (!grouped[item.memberId]) {
          grouped[item.memberId] = [];
        }
        grouped[item.memberId].push(item);
      });

      expect(grouped['member-1']).toHaveLength(2);
      expect(grouped['member-2']).toHaveLength(1);
    });
  });

  describe('C├ílculo de Totais por Moeda', () => {
    it('deve calcular totais separados por moeda', () => {
      const items = [
        { currency: 'BRL', amount: 100, type: 'CREDIT', isPaid: false },
        { currency: 'BRL', amount: 50, type: 'DEBIT', isPaid: false },
        { currency: 'USD', amount: 20, type: 'CREDIT', isPaid: false },
      ];

      const totalsByCurrency: Record<string, { credits: number; debits: number; net: number }> = {};

      items.forEach(item => {
        const curr = item.currency || 'BRL';
        if (!totalsByCurrency[curr]) {
          totalsByCurrency[curr] = { credits: 0, debits: 0, net: 0 };
        }

        if (item.type === 'CREDIT') {
          totalsByCurrency[curr].credits += item.amount;
        } else {
          totalsByCurrency[curr].debits += item.amount;
        }
      });

      Object.keys(totalsByCurrency).forEach(curr => {
        totalsByCurrency[curr].net = totalsByCurrency[curr].credits - totalsByCurrency[curr].debits;
      });

      expect(totalsByCurrency['BRL'].credits).toBe(100);
      expect(totalsByCurrency['BRL'].debits).toBe(50);
      expect(totalsByCurrency['BRL'].net).toBe(50);
      expect(totalsByCurrency['USD'].credits).toBe(20);
      expect(totalsByCurrency['USD'].net).toBe(20);
    });

    it('deve nunca somar moedas diferentes', () => {
      const items = [
        { currency: 'BRL', amount: 100, type: 'CREDIT' },
        { currency: 'USD', amount: 100, type: 'CREDIT' },
      ];

      const totalsByCurrency: Record<string, number> = {};

      items.forEach(item => {
        const curr = item.currency || 'BRL';
        if (!totalsByCurrency[curr]) {
          totalsByCurrency[curr] = 0;
        }
        totalsByCurrency[curr] += item.amount;
      });

      // Verificar que BRL e USD s├úo mantidos separados
      expect(totalsByCurrency['BRL']).toBe(100);
      expect(totalsByCurrency['USD']).toBe(100);
      // Nunca somar: 100 + 100 = 200 (ERRADO!)
    });
  });

  describe('Filtro de Abas', () => {
    it('deve filtrar REGULAR: apenas itens n├úo pagos, sem viagens, do m├¬s atual', () => {
      const items = [
        { isPaid: false, tripId: null, date: '2024-01-15' },
        { isPaid: true, tripId: null, date: '2024-01-15' },
        { isPaid: false, tripId: 'trip-1', date: '2024-01-15' },
      ];

      const currentDate = new Date('2024-01-20');
      const filtered = items.filter(item => {
        if (item.isPaid) return false;
        if (item.tripId) return false;
        
        const [year, month] = item.date.split('-').map(Number);
        return month === currentDate.getMonth() + 1 && year === currentDate.getFullYear();
      });

      expect(filtered).toHaveLength(1);
      expect(filtered[0].isPaid).toBe(false);
      expect(filtered[0].tripId).toBeNull();
    });

    it('deve filtrar TRAVEL: todos os itens de viagens', () => {
      const items = [
        { isPaid: false, tripId: 'trip-1', date: '2024-01-15' },
        { isPaid: true, tripId: 'trip-1', date: '2024-01-15' },
        { isPaid: false, tripId: null, date: '2024-01-15' },
      ];

      const filtered = items.filter(item => !!item.tripId);

      expect(filtered).toHaveLength(2);
      filtered.forEach(item => {
        expect(item.tripId).toBe('trip-1');
      });
    });

    it('deve filtrar HISTORY: apenas itens pagos do m├¬s atual', () => {
      const items = [
        { isPaid: true, tripId: null, date: '2024-01-15' },
        { isPaid: false, tripId: null, date: '2024-01-15' },
        { isPaid: true, tripId: null, date: '2024-02-15' },
      ];

      const currentDate = new Date('2024-01-20');
      const filtered = items.filter(item => {
        if (!item.isPaid) return false;
        
        const [year, month] = item.date.split('-').map(Number);
        return month === currentDate.getMonth() + 1 && year === currentDate.getFullYear();
      });

      expect(filtered).toHaveLength(1);
      expect(filtered[0].isPaid).toBe(true);
      expect(filtered[0].date).toContain('2024-01');
    });
  });

  describe('Propriedades de Corre├º├úo', () => {
    it('Invariante: Soma de splits <= total + 1 centavo', () => {
      const total = 100;
      const splits = [
        { percentage: 33.33 },
        { percentage: 33.33 },
        { percentage: 33.34 },
      ];

      const result = SafeFinancialCalculator.distributeSplits(total, splits);
      const sum = result.reduce((acc, r) => SafeFinancialCalculator.add(acc, r.amount), 0);

      expect(sum).toBeLessThanOrEqual(total + 0.01);
    });

    it('Idempot├¬ncia: Calcular faturas m├║ltiplas vezes produz mesmo resultado', () => {
      const transactions = [
        { type: 'EXPENSE', amount: 100, competence_date: '2024-01-01' },
        { type: 'EXPENSE', amount: 50, competence_date: '2024-01-01' },
      ];

      const targetMonth = '2024-01';
      const filtered1 = transactions.filter(tx => tx.competence_date.startsWith(targetMonth));
      const filtered2 = transactions.filter(tx => tx.competence_date.startsWith(targetMonth));

      expect(filtered1).toHaveLength(filtered2.length);
      expect(filtered1[0].amount).toBe(filtered2[0].amount);
    });

    it('Conflu├¬ncia: Ordem de processamento n├úo afeta totais finais', () => {
      const items1 = [
        { amount: 100, type: 'CREDIT' },
        { amount: 50, type: 'DEBIT' },
      ];

      const items2 = [
        { amount: 50, type: 'DEBIT' },
        { amount: 100, type: 'CREDIT' },
      ];

      const sum1 = items1.reduce((acc, item) => {
        if (item.type === 'CREDIT') return acc + item.amount;
        return acc - item.amount;
      }, 0);

      const sum2 = items2.reduce((acc, item) => {
        if (item.type === 'CREDIT') return acc + item.amount;
        return acc - item.amount;
      }, 0);

      expect(sum1).toBe(sum2);
      expect(sum1).toBe(50);
