} from "@/services/exchangeCalculations";

/**
 * Hook para buscar compras de c├ómbio de uma viagem
 */
export function useTripExchangePurchases(tripId: string | null) {
  return useQuery({
    queryKey: ["trip-exchange-purchases", tripId],
    queryFn: async () => {
      if (!tripId) return [];

      // 1. Buscar detalhes da viagem para saber a moeda estrangeira
      const { data: trip, error: tripError } = await supabase
        .from("trips")
        .select("currency")
        .eq("id", tripId)
        .single();

      if (tripError || !trip) {
        throw tripError || new Error("Viagem n├úo encontrada");
      }

      // Se for BRL, n├úo precisa de compras de c├ómbio
      if (trip.currency === "BRL") {
        return [];
      }

      // 2. Buscar compras de c├ómbio manuais registradas para a viagem
      const { data: manualPurchases, error: manualError } = await supabase
        .from("trip_exchange_purchases")
        .select("*")
        .eq("trip_id", tripId)
        .order("purchase_date", { ascending: false });

      if (manualError) throw manualError;

      // 3. Buscar transfer├¬ncias entre moedas (BRL -> Moeda da Viagem) nas contas globais
      // Filtramos por transfer├¬ncias que tenham a moeda de destino igual ├á moeda da viagem,
      // e que estejam vinculadas ├á viagem atual (trip_id = tripId) OU sem v├¡nculo direto (trip_id is null)
      // para puxar todos os aportes feitos na moeda durante o per├¡odo
      const { data: transfers, error: transfersError } = await supabase
        .from("transactions")
        .select("*")
        .eq("type", "TRANSFER")
        .eq("destination_currency", trip.currency)
        .or(`trip_id.eq.${tripId},trip_id.is.null`);

      if (transfersError) throw transfersError;

      // 4. Mapear as transfer├¬ncias globais para o formato ExchangePurchase
      const mappedTransfers: ExchangePurchase[] = (transfers || []).map((t) => {
        const localAmount = t.amount || 0;
        const foreignAmount = t.destination_amount || 0;
        const exchangeRate = t.exchange_rate || (foreignAmount > 0 ? localAmount / foreignAmount : 0);

        return {
          id: t.id,
          trip_id: tripId,
          user_id: t.user_id,
          foreign_amount: foreignAmount,
          exchange_rate: exchangeRate,
          cet_percentage: 0,
          effective_rate: exchangeRate,
          local_amount: localAmount,
          description: t.description || `Transf. Conta Global (${t.destination_currency})`,
          purchase_date: t.date,
          created_at: t.created_at,
          updated_at: t.updated_at || t.created_at,
          is_automated: true,
        };
      });

      // 5. Combinar compras manuais e autom├íticas, ordenando por data de compra decrescente
      const combined = [...(manualPurchases || []), ...mappedTransfers];
      combined.sort((a, b) => new Date(b.purchase_date).getTime() - new Date(a.purchase_date).getTime());

      return combined as ExchangePurchase[];
    },
    enabled: !!tripId,
    staleTime: 0, // Ô£à Dados sempre frescos
    refetchOnMount: 'always',
  });
}

/**
 * Hook para criar uma compra de c├ómbio
 */
export function useCreateExchangePurchase() {
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async ({
      tripId,
      input,
    }: {
      tripId: string;
      input: ExchangePurchaseInput;
    }) => {
      if (!user) throw new Error("Usu├írio n├úo autenticado");

      const effectiveRate = calculateEffectiveRate(
        input.exchange_rate,
        input.cet_percentage
      );
      const localAmount = calculateLocalAmount(
        input.foreign_amount,
        effectiveRate
      );

      const { data, error } = await supabase
        .from("trip_exchange_purchases")
        .insert({
          trip_id: tripId,
          user_id: user.id,
          foreign_amount: input.foreign_amount,
          exchange_rate: input.exchange_rate,
          cet_percentage: input.cet_percentage,
          effective_rate: effectiveRate,
          local_amount: localAmount,
          description: input.description || null,
          purchase_date: input.purchase_date,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({
        queryKey: ["trip-exchange-purchases", variables.tripId],
      });
      toast({
        title: "C├ómbio registrado",
        description: "Compra de c├ómbio adicionada com sucesso",
      });
    },
    onError: (error) => {
      toast({
        title: "Erro ao registrar c├ómbio",
        description: error.message,
        variant: "destructive",
      });
    },
  });
}

