    queryKey: ["trip-permissions", tripId, user?.id],
    queryFn: async () => {
      if (!tripId || !user) return null;

      const { data, error } = await supabase
        .from("trip_members")
        .select("role, can_edit_details, can_manage_expenses")
        .eq("trip_id", tripId)
        .eq("user_id", user.id)
        .single();

      if (error) {
