import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import { logger } from "@/utils/logger";
import { callRPCWithRetry } from "@/utils/supabaseHelpers";

export type TripStatus = "PLANNING" | "ACTIVE" | "COMPLETED" | "CANCELLED";

export interface Trip {
  id: string;
  owner_id: string;
  name: string;
  destination: string | null;
  start_date: string;
  end_date: string;
  currency: string;
  budget: number | null;
  status: TripStatus;
  cover_image: string | null;
  notes: string | null;
  is_archived: boolean | null;
  archived_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface TripWithPersonalBudget extends Trip {
  my_personal_budget: number | null;
}

export interface TripParticipant {
  id: string;
  trip_id: string;
  user_id: string | null;
  member_id: string | null;
  name: string;
  avatar_url: string | null;
  avatar_color: string | null;
  avatar_icon: string | null;
  personal_budget: number | null;
  created_at: string;
}

export interface CreateTripInput {
  name: string;
  destination: string;
  start_date: string;
  end_date: string;
  currency?: string;
  budget?: number;
  notes?: string;
  memberIds?: string[]; // IDs dos membros da fam├¡lia para adicionar
}

export function useTrips() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["trips", user?.id],
    queryFn: async () => {
      if (!user) return [];

      // CORRE├ç├âO: Buscar viagens atrav├®s de trip_members
      const { data: memberTrips, error: memberError } = await supabase
        .from("trip_members")
        .select("trip_id")
        .eq("user_id", user.id);

      if (memberError) throw memberError;

      if (!memberTrips || memberTrips.length === 0) return [];

      const tripIds = memberTrips.map((m) => m.trip_id);

      // Buscar as viagens completas
      const { data: trips, error: tripsError } = await supabase
        .from("trips")
        .select("*")
        .in("id", tripIds)
        .is("deleted_at", null)
        .order("start_date", { ascending: true });

      if (tripsError) throw tripsError;

      if (!trips || trips.length === 0) return [];

      // Buscar or├ºamentos pessoais para essas viagens (de trip_members)
      const { data: budgets } = await supabase
        .from("trip_members")
        .select("trip_id, personal_budget")
        .eq("user_id", user.id)
        .in("trip_id", tripIds);

      // Mapear or├ºamentos para viagens
      const budgetMap = new Map(budgets?.map((b) => [b.trip_id, b.personal_budget]) || []);

      return trips.map((trip) => ({
        ...trip,
        my_personal_budget: budgetMap.get(trip.id) || null,
      })) as unknown as TripWithPersonalBudget[];
    },
    enabled: !!user,
    retry: false,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

export function useTrip(id: string | null) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["trip", id],
    queryFn: async () => {
      if (!id) return null;

      const { data, error } = await supabase.from("trips").select("*").eq("id", id).maybeSingle();

      if (error) throw error;
      return data as unknown as Trip;
    },
    enabled: !!user && !!id,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

export function useTripParticipants(tripId: string | null) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["trip-participants", tripId],
    queryFn: async () => {
      if (!tripId) return [];

      // CORRE├ç├âO: Usar um JOIN ├║nico com profiles para evitar o problema N+1
      // Incluir guest_name para participantes sem conta (convidados externos)
      const { data, error } = await supabase
        .from("trip_members")
        .select(
          `
          id,
          trip_id,
          user_id,
          guest_name,
          role,
          personal_budget,
          created_at,
          profile:profiles!fk_trip_members_profiles(full_name, avatar_url, avatar_color, avatar_icon)
        `
        )
        .eq("trip_id", tripId)
        .order("created_at");

      if (error) throw error;

      return (data || []).map((member: any) => ({
        id: member.id,
        trip_id: member.trip_id,
        user_id: member.user_id,
        member_id: member.id, // ID da tabela trip_members
        role: member.role,
        name: member.profile?.full_name || member.guest_name || "Participante",
        avatar_url: member.profile?.avatar_url || null,
        avatar_color: member.profile?.avatar_color || null,
        avatar_icon: member.profile?.avatar_icon || null,
        personal_budget: member.personal_budget,
        created_at: member.created_at,
      })) as TripParticipant[];
    },
    enabled: !!user && !!tripId,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

export function useCreateTrip() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: CreateTripInput) => {
      if (!user) throw new Error("User not authenticated");

      const { memberIds, ...tripData } = input;

      const { data, error } = await supabase
        .from("trips")
        .insert({
          owner_id: user.id,
          creator_user_id: user.id,
          ...tripData,
        })
        .select()
        .single();

      if (error) throw error;

      // Owner ├® adicionado automaticamente via trigger add_trip_owner()

      // Criar convites para membros selecionados
      if (memberIds && memberIds.length > 0) {
        const invitations = memberIds.map((userId) => ({
          trip_id: data.id,
          inviter_id: user.id,
          invitee_id: userId,
          message: null,
        }));

        const { error: invitationsError } = await supabase
          .from("trip_invitations")
          .insert(invitations);

        if (invitationsError) {
          logger.error("Erro ao criar convites de viagem:", invitationsError);
          toast.warning(
            `Viagem criada, mas houve erro ao enviar convites: ${invitationsError.message}`,
            { duration: 5000 }
          );
        } else {
          toast.success(`Viagem criada com sucesso! ${memberIds.length} convite(s) enviado(s).`, {
            duration: 3000,
          });
        }
      } else {
        // Sem convites, apenas sucesso simples
        toast.success("Viagem criada com sucesso!");
      }

      return data as unknown as Trip;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["trips"] });
      // N├úo mostrar toast aqui se j├í mostramos acima
    },
    onError: (error) => {
      toast.error("Erro ao criar viagem: " + error.message);
    },
  });
}

export function useUpdateTrip() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, ...input }: Partial<Trip> & { id: string }) => {
      const { data, error } = await supabase
        .from("trips")
        .update(input as any)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data as unknown as Trip;
    },

    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["trips"] });
      queryClient.invalidateQueries({ queryKey: ["trip", data.id] });
      toast.success("Viagem atualizada!");
    },
    onError: (error: Error) => {
      logger.error("Erro ao atualizar viagem:", error);
      toast.error("Erro ao atualizar viagem");
    },
  });
}

