export function useAddTripParticipant() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({
      tripId,
      name,
      userId,
      personalBudget,
    }: {
      tripId: string;
      name: string;
      userId: string;
      personalBudget?: number;
    }) => {
      if (!userId) throw new Error("ID do usu├írio ├® obrigat├│rio para adicionar participante");

      const { data, error } = await supabase
        .from("trip_members")
        .insert({
          trip_id: tripId,
          user_id: userId,
          personal_budget: personalBudget || null,
          role: "member",
          status: "active",
        })
        .select()
        .single();

      if (error) {
        if (error.code === "23505") {
          throw new Error("Este participante j├í est├í na viagem");
        }
        throw error;
      }

      return {
        id: data.id,
        trip_id: data.trip_id,
        user_id: data.user_id,
        name: name,
        personal_budget: data.personal_budget,
        created_at: data.created_at,
      } as TripParticipant;
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ["trip-participants", variables.tripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-members", variables.tripId] });
      toast.success("Participante adicionado!");
    },
    onError: (error: Error) => {
      logger.error("Erro ao adicionar membro:", error);
      toast.error("Erro ao adicionar membro ├á viagem");
    },
  });
}

export function useRemoveTripParticipant() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ id, tripId }: { id: string; tripId: string }) => {
      const { error } = await supabase.from("trip_members").delete().eq("id", id);

      if (error) throw error;
      return tripId;
    },
    onSuccess: (tripId) => {
      queryClient.invalidateQueries({ queryKey: ["trip-participants", tripId] });
      toast.success("Participante removido!");
    },
    onError: (error) => {
      toast.error("Erro ao remover participante: " + error.message);
    },
  });
}

// Hook para buscar transa├º├Áes de uma viagem
// PRIVACIDADE: Cada viajante v├¬ apenas:
//   (a) Todas as despesas compartilhadas (is_shared = true)
//   (b) Suas pr├│prias despesas pessoais (is_shared = false && user_id = meu id)
//   N├âO v├¬: despesas pessoais de outros participantes
export function useTripTransactions(tripId: string | null) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["trip-transactions", tripId, user?.id],
    queryFn: async () => {
      if (!tripId || !user) return [];

      const { data, error } = await supabase
        .from("transactions")
        .select(
          `
          *,
          account:accounts!account_id(name, bank_id),
          category:categories(name, icon),
          transaction_splits:transaction_splits!transaction_id(*)
        `
        )
        .eq("trip_id", tripId)
        .is("source_transaction_id", null)
        .order("date", { ascending: false });

      if (error) throw error;
      return data;
    },
    enabled: !!user && !!tripId,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

// Interface para resumo financeiro da viagem
export interface TripFinancialSummary {
  total_budget: number | null;
  total_spent: number;
  total_settled: number; // Total de acertos feitos
  remaining: number;
  percentage_used: number;
  currency: string;
  participants_count: number;
  transactions_count: number;
}

// Hook para buscar resumo financeiro da viagem (SINGLE SOURCE OF TRUTH)
// O total gasto ├® calculado diretamente das transa├º├Áes pelo banco de dados
export function useTripFinancialSummary(tripId: string | null) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["trip-financial-summary", tripId],
    queryFn: async () => {
      if (!tripId) return null;
      try {
        const data = await callRPCWithRetry("get_trip_financial_summary", {
          p_trip_id: tripId,
        });
        return (Array.isArray(data) ? data[0] : data) as TripFinancialSummary;
      } catch (error) {
        logger.error("Erro ao buscar resumo financeiro da viagem:", error);
        throw error;
      }
    },
    enabled: !!user && !!tripId,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

// Hook para calcular gasto pessoal em uma viagem
export function useMyTripSpent(tripId: string | null) {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["my-trip-spent", tripId, user?.id],
    queryFn: async () => {
      if (!tripId || !user) return 0;
      try {
        const data = await callRPCWithRetry("calculate_trip_spent", {
          p_trip_id: tripId,
          p_user_id: user?.id,
        });
        return Number(data || 0);
      } catch (error) {
        logger.error("Erro ao calcular gasto da viagem:", error);
        throw error;
      }
    },
    enabled: !!user && !!tripId,
    staleTime: 60 * 1000,
    refetchOnWindowFocus: false,
  });
}

