export function useDeleteAccount() {
  const { user } = useAuth();

  return useMutation({
    mutationFn: async () => {
      if (!user) throw new Error("N├úo autenticado");

      // ÔöÇÔöÇÔöÇ LGPD: Expurgo f├¡sico em cascata de todos os dados do usu├írio ÔöÇÔöÇÔöÇ
      // Agora realizado via fun├º├úo segura e at├┤mica no banco (RPC)
      // garantindo que n├úo restem registros fantasmas nem falhas de rede intermedi├írias.
      
      const { error } = await supabase.rpc('delete_user_account');
      
      if (error) {
        throw new Error(`Erro no banco de dados ao excluir conta: ${error.message}`);
      }

      // Deslogar localmente
      await supabase.auth.signOut();
      return true;
    },
    onSuccess: () => {
      toast.success("Sua conta e todos os seus dados foram removidos permanentemente.");
    },
    onError: (error) => {
      toast.error("Erro ao excluir conta: " + error.message);
    },
  });
}

