        icon={AlertCircle}
        title="Erro ao carregar contas"
        description="N├úo foi poss├¡vel buscar suas contas. Verifique sua conex├úo e tente novamente."
        variant="danger"
        action={
          <Button onClick={() => refetch()} variant="outline" className="h-12 px-8 rounded-full">
            Tentar novamente
