                rightAction={{
                  icon: <Archive className="w-5 h-5" />,
                  color: "bg-muted-foreground",
                  label: "Arquivar",
                  onClick: () => archiveAccount.mutate(acc.id),
                }}
              >
                <AccountCard
                  account={acc}
                  lastTransactions={getLastTransactions(acc.id)}
                  formatCurrency={formatCurrency}
                  getCurrencySymbol={getCurrencySymbol}
                  accountTypeLabels={accountTypeLabels}
                />
              </SwipeableRow>
            ))}
          </div>
        )}
      </div>

      <AccountFormModal
        isOpen={showAddDialog}
        onClose={() => setShowAddDialog(false)}
        onSubmit={handleCreateSubmit}
        mode="create"
        isLoading={createAccount.isPending}
      />

      <AccountFormModal
        isOpen={!!editAccount}
        onClose={() => setEditAccount(null)}
        onSubmit={handleEditSubmit}
        mode="edit"
        initialData={editAccount}
        isLoading={updateAccount.isPending}
      />

      <ArchivedAccountsSection />
      <TransactionModal open={showTransactionModal} onOpenChange={setShowTransactionModal} />
    </div>
  );
}

import { useState } from "react";
import { Navigate, useNavigate } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { FormField } from "@/components/ui/form-field";
import { Mail, Lock, User, Eye, EyeOff, Loader2 } from "lucide-react";
import { toast } from "sonner";
import { z } from "zod";
import { Checkbox } from "@/components/ui/checkbox";

const authSchema = z.object({
  email: z.string().trim().email("Email inv├ílido").max(255),
  password: z.string().min(6, "Senha deve ter no m├¡nimo 6 caracteres").max(100),
  fullName: z.string().trim().max(100).optional(),
});

export function Auth() {
  const { user, loading, signIn, signUp } = useAuth();
  const navigate = useNavigate();

  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isResetting, setIsResetting] = useState(false);

  // Redirect if already logged in
  if (!loading && user) {
    return <Navigate to="/" replace />;
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      if (isResetting) {
        const { error } = await supabase.auth.resetPasswordForEmail(email, {
          redirectTo: `${window.location.origin}/reset-password`,
        });
        if (error) {
          toast.error(error.message);
        } else {
          toast.success("Link de recupera├º├úo enviado para seu e-mail!");
          setIsResetting(false);
        }
        return;
      }

      // Validate inputs
      const validation = authSchema.safeParse({
        email,
        password,
        fullName: isLogin ? undefined : fullName,
      });

      if (!validation.success && !isResetting) {
        toast.error(validation.error.errors[0].message);
        setIsSubmitting(false);
        return;
      }

      if (isLogin) {
        const { error } = await signIn(email, password);
        if (error) {
          if (error.message.includes("Invalid login credentials")) {
            toast.error("Email ou senha incorretos");
          } else {
            toast.error(error.message);
          }
        } else {
          toast.success("Bem-vindo de volta!");
          navigate("/");
        }
      } else {
        const { error } = await signUp(email, password, fullName);
        if (error) {
          if (error.message.includes("already registered")) {
            toast.error("Este email j├í est├í cadastrado");
          } else {
            toast.error(error.message);
          }
        } else {
          toast.success("Conta criada com sucesso!");
          navigate("/");
        }
      }
    } catch (err) {
      toast.error("Ocorreu um erro. Tente novamente.");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-background">
      {/* Header */}
      <header className="p-4">
        <span className="font-display font-bold text-lg tracking-tight">p├® de meia</span>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex items-center justify-center px-4">
        <div className="w-full max-w-md space-y-5 animate-fade-in">
          {/* Title */}
          <div className="text-center">
            <div className="mx-auto w-20 h-20 flex items-center justify-center mb-3">
              <img
                src="/icon-512.png"
                alt="P├® de Meia"
                className="w-full h-full object-contain drop-shadow-sm"
              />
            </div>
            <h1 className="font-display font-bold text-2xl tracking-tight">
              {isResetting ? "Recuperar senha" : isLogin ? "Bem-vindo de volta" : "Crie sua conta"}
            </h1>
            <p className="text-muted-foreground mt-2">
              {isResetting
                ? "Enviaremos um link de recupera├º├úo para seu e-mail"
                : isLogin
                  ? "Entre para gerenciar suas finan├ºas"
                  : "Comece a organizar suas finan├ºas hoje"}
            </p>
          </div>

          {/* Form */}
          <form onSubmit={handleSubmit} className="form-stack">
            {!isLogin && !isResetting && (
              <FormField label="Nome completo" htmlFor="fullName">
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="fullName"
                    type="text"
                    placeholder="Seu nome"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    className="pl-10"
                    disabled={isSubmitting}
                    autoComplete="name"
                    autoCapitalize="words"
                  />
                </div>
              </FormField>
            )}

            <FormField label="Email" htmlFor="email">
              <div className="relative">
                <Mail className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                <Input
                  id="email"
                  type="email"
                  placeholder="seu@email.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="pl-10"
                  disabled={isSubmitting}
                  required
                  autoComplete="email"
                  autoCapitalize="none"
                  autoCorrect="off"
                  spellCheck="false"
                />
              </div>
            </FormField>

            {!isResetting && (
              <div className="form-field">
                <div className="flex items-center justify-between">
                  <label htmlFor="password" className="text-sm font-medium leading-none">
                    Senha
                  </label>
                  {isLogin && (
                    <button
                      type="button"
                      onClick={() => setIsResetting(true)}
                      className="text-sm text-primary hover:underline"
                    >
                      Esqueceu a senha?
                    </button>
                  )}
                </div>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                  <Input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    placeholder="ÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇóÔÇó"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    className="pl-10 pr-10"
                    disabled={isSubmitting}
                    required
                    autoComplete={isLogin ? "current-password" : "new-password"}
                  />
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className="absolute right-0 top-1/2 -translate-y-1/2"
                    onClick={() => setShowPassword(!showPassword)}
                    tabIndex={-1}
                    aria-label={showPassword ? "Ocultar senha" : "Mostrar senha"}
                  >
                    {showPassword ? (
                      <EyeOff className="h-4 w-4 text-muted-foreground" />
                    ) : (
                      <Eye className="h-4 w-4 text-muted-foreground" />
                    )}
                  </Button>
                </div>
              </div>
            )}

            <Button
              type="submit"
              size="lg"
              className="w-full"
              disabled={isSubmitting}
              loading={isSubmitting}
            >
              {isResetting ? "Enviar link de recupera├º├úo" : isLogin ? "Entrar" : "Criar conta"}
            </Button>

            {isResetting && (
              <Button
                type="button"
                variant="ghost"
                className="w-full"
                onClick={() => setIsResetting(false)}
              >
                Voltar para o login
              </Button>
            )}
          </form>

          {!isResetting && (
            <p className="text-center text-sm text-muted-foreground">
              {isLogin ? "N├úo tem uma conta?" : "J├í tem uma conta?"}{" "}
              <button
                type="button"
                onClick={() => setIsLogin(!isLogin)}
                className="text-foreground font-medium hover:underline"
              >
                {isLogin ? "Criar conta" : "Entrar"}
              </button>
            </p>
          )}
        </div>
      </main>
    </div>
  );
}

import { moneyUtils } from "@/utils/money";
import { useState, useMemo } from "react";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { Button } from "@/components/ui/button";
