import { useBudgets } from "@/hooks/useBudgets";
import { useMonth } from "@/contexts/MonthContext";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { BudgetCard } from "@/components/budgets/BudgetCard";
import { logger } from "@/utils/logger";

export function Budgets() {
  const { currentDate } = useMonth();
  const safeCurrentDate = useMemo(() => {
    if (!currentDate || isNaN(currentDate.getTime())) {
      return new Date();
    }
    return currentDate;
  }, [currentDate]);

  const { data: categories = [] } = useCategories();
  const { data: accounts = [] } = useAccounts();
  const {
    budgets = [],
    budgetsWithProgress = [],
    isLoading,
    createBudget,
    updateBudget,
    deleteBudget,
    isCreating,
    isUpdating,
  } = useBudgets();

  const [showNewBudgetDialog, setShowNewBudgetDialog] = useState(false);
  const [editingBudget, setEditingBudget] = useState<any>(null);
  const [amount, setAmount] = useState("");
  const [categoryId, setCategoryId] = useState<string>("");
  const [currency, setCurrency] = useState("BRL");
  const [openCategoryPopover, setOpenCategoryPopover] = useState(false);

  const availableCurrencies = useMemo(() => {
    const set = new Set<string>(["BRL"]);
    accounts.forEach((acc) => {
      if (acc.is_international && acc.currency) set.add(acc.currency);
    });
    return Array.from(set);
  }, [accounts]);

  const resetForm = () => {
    setAmount("");
    setCategoryId("");
    setCurrency("BRL");
  };

  const handleSubmit = async () => {
    const generatedName = categoryId
      ? categories.find((c) => c.id === categoryId)?.name || "Or├ºamento"
      : "Or├ºamento Global";

    const data = {
      name: generatedName,
      amount: moneyUtils.parse(amount),
      category_id: categoryId || null,
      currency,
      period: "MONTHLY" as const,
      is_active: true,
      start_date: null,
      end_date: null,
    };

    try {
      showActionFeedback("success");
      if (editingBudget) {
        setTimeout(() => setEditingBudget(null), 80);
        updateBudget({ id: editingBudget.id, ...data });
      } else {
        setTimeout(() => setShowNewBudgetDialog(false), 80);
        createBudget(data);
      }
      resetForm();
      if (document.activeElement instanceof HTMLElement) {
        document.activeElement.blur();
      }
    } catch (err) {
      logger.error("Erro ao salvar or├ºamento", err);
    }
  };

  const totalBudgeted = useMemo(
    () => budgetsWithProgress.reduce((sum, b) => sum + b.budget_amount, 0),
    [budgetsWithProgress]
  );
  const totalSpent = useMemo(
    () => budgetsWithProgress.reduce((sum, b) => sum + b.spent_amount, 0),
    [budgetsWithProgress]
  );

  // Alertas de or├ºamento estourado ou pr├│ximo do limite
  const overBudgetAlerts = useMemo(() => {
    const over: Array<{ name: string; percentage: number; isOver: boolean }> = [];
    budgetsWithProgress.forEach((b) => {
      const pct = Number(b.percentage_used) || 0;
      if (pct >= 80) {
        over.push({
          name: b.category_name || "Or├ºamento Global",
          percentage: pct,
          isOver: pct > 100,
        });
      }
    });
    return over;
  }, [budgetsWithProgress]);

  if (isLoading) {
    return (
      <div className="space-y-8 animate-fade-in pb-20">
        <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 border border-border/50 bg-card/50">
          <div className="space-y-3">
            <div className="skeleton h-10 w-56 rounded-xl" />
            <div className="skeleton h-4 w-72 rounded-lg" />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-64 bg-muted rounded-2xl animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      {/* Header com Glassmorphism */}
      <div className="sticky top-2 z-40 relative overflow-hidden rounded-4xl p-5 md:p-8 transition-all duration-700 ease-out bg-background/60 backdrop-blur-xl border border-border/40 shadow-sm">
        <div className="absolute top-0 right-0 w-64 h-64 bg-primary/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 pointer-events-none" />
        <div className="relative flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6">
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <h1 className="font-display font-black text-3xl md:text-3xl tracking-tighter">
                Or├ºamentos
              </h1>
              <TooltipProvider>
                <Tooltip>
                  <TooltipTrigger asChild>
                    <div className="h-6 w-6 rounded-full bg-primary/10 text-primary flex items-center justify-center cursor-help transition-transform hover:scale-110">
                      <HelpCircle className="h-3.5 w-3.5" />
                    </div>
                  </TooltipTrigger>
                  <TooltipContent className="max-w-xs space-y-2 p-3 bg-card text-card-foreground shadow-premium-sm border-border">
                    <p className="font-bold text-sm">Controle Inteligente</p>
                    <p className="text-sm text-muted-foreground">
                      Aqui voc├¬ define limites de gastos por categoria. O sistema possui{" "}
                      <strong>Rollover Autom├ítico</strong>: se voc├¬ gastar menos que o limite em um
                      m├¬s, o que sobrou ser├í somado ao limite do m├¬s seguinte!
                    </p>
                  </TooltipContent>
                </Tooltip>
              </TooltipProvider>
            </div>
            <p className="text-muted-foreground mt-2 text-sm md:text-base font-medium flex items-center gap-2">
              Gest├úo de limites para{" "}
              {dateFns.format(safeCurrentDate, "MMMM yyyy", { locale: ptBR })}
            </p>
          </div>
          <Button
            onClick={() => setShowNewBudgetDialog(true)}
            size="default"
            className="shadow-xl shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95 group h-12 px-6 w-full sm:w-auto font-bold rounded-2xl"
          >
            <Plus className="h-5 w-5 mr-2 transition-transform group-hover:scale-110" />
            Novo Or├ºamento
          </Button>
        </div>
      </div>

      {/* Mini Dashboard de Or├ºamentos */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 sm:gap-6">
        <div className="p-4 sm:p-6 rounded-4xl border border-border/40 bg-card/60 backdrop-blur-md shadow-sm flex items-center gap-4 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform duration-500">
            <Target className="w-16 h-16 text-primary" />
          </div>
          <div className="relative z-10 w-12 h-12 sm:w-14 sm:h-14 rounded-2xl bg-primary/10 flex items-center justify-center text-primary shrink-0">
            <Target className="h-6 w-6 sm:h-7 sm:w-7" />
          </div>
          <div className="relative z-10 min-w-0">
            <p className="text-sm sm:text-sm text-muted-foreground uppercase font-semibold tracking-widest truncate">
              Total Planejado
            </p>
            <p className="text-base sm:text-3xl font-display font-black truncate">
              {moneyUtils.format(totalBudgeted, "BRL")}
            </p>
          </div>
        </div>
        <div className="p-4 sm:p-6 rounded-4xl border border-border/40 bg-card/60 backdrop-blur-md shadow-sm flex items-center gap-4 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform duration-500">
            <TrendingUp className="w-16 h-16 text-warning" />
          </div>
          <div className="relative z-10 w-12 h-12 sm:w-14 sm:h-14 rounded-2xl bg-warning/10 flex items-center justify-center text-warning shrink-0">
            <TrendingUp className="h-6 w-6 sm:h-7 sm:w-7" />
          </div>
          <div className="relative z-10 min-w-0">
            <p className="text-sm sm:text-sm text-muted-foreground uppercase font-semibold tracking-widest truncate">
              Total Consumido
            </p>
            <p className="text-base sm:text-3xl font-display font-black truncate">
              {moneyUtils.format(totalSpent, "BRL")}
            </p>
          </div>
        </div>
        <div className="p-4 sm:p-6 rounded-4xl border border-border/40 bg-gradient-to-br from-positive/10 to-card shadow-sm flex items-center gap-4 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:scale-110 transition-transform duration-500">
            <Wallet className="w-16 h-16 text-positive" />
          </div>
          <div className="relative z-10 w-12 h-12 sm:w-14 sm:h-14 rounded-2xl bg-positive/10 flex items-center justify-center text-positive shrink-0">
            <Wallet className="h-6 w-6 sm:h-7 sm:w-7" />
          </div>
          <div className="relative z-10 min-w-0">
            <p className="text-sm sm:text-sm text-muted-foreground uppercase font-semibold tracking-widest truncate">
              Dispon├¡vel Total
            </p>
            <p className="text-base sm:text-3xl font-display font-black truncate text-positive">
              {moneyUtils.format(Math.max(0, totalBudgeted - totalSpent), "BRL")}
            </p>
          </div>
        </div>
      </div>

      {budgets.length === 0 ? (
        <EmptyState
          icon={Wallet}
          title="Comece a planejar seus gastos"
          description="Estabele├ºa limites por categoria e conquiste paz de esp├¡rito acompanhando o or├ºamento em tempo real."
          action={
            <Button
              onClick={() => setShowNewBudgetDialog(true)}
              size="lg"
              className="h-12 px-8 rounded-2xl shadow-lg shadow-primary/20 hover:shadow-primary/30 hover:-translate-y-0.5 transition-all font-semibold"
            >
              <Plus className="w-5 h-5 mr-2" />
              Criar Primeiro Or├ºamento
            </Button>
          }
        />
      ) : (
        <>
          {/* Alertas de or├ºamento */}
          {overBudgetAlerts.length > 0 && (
            <div className="space-y-2">
              {overBudgetAlerts.map((alert, i) => (
                <div
                  key={i}
                  className={cn(
                    "flex items-center gap-3 p-4 rounded-2xl border text-sm font-medium animate-fade-in",
                    alert.isOver
                      ? "border-destructive/30 bg-destructive/5 text-destructive"
                      : "border-warning/30 bg-warning/5 text-warning"
                  )}
                >
                  {alert.isOver ? (
                    <AlertCircle className="h-5 w-5 shrink-0" />
                  ) : (
                    <AlertTriangle className="h-5 w-5 shrink-0" />
                  )}
                  <span>
                    <strong>{alert.name}:</strong>{" "}
                    {alert.isOver
                      ? `${alert.percentage.toFixed(0)}% consumido ÔÇö acima do limite!`
                      : `${alert.percentage.toFixed(0)}% consumido ÔÇö pr├│ximo do limite.`}
                  </span>
                </div>
              ))}
            </div>
          )}

          <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
            {budgetsWithProgress.map((b) => (
              <BudgetCard
                key={b.budget_id}
                budget={b}
                formatCurrency={(val, curr) => moneyUtils.format(val, curr || "BRL")}
                onEdit={(orig) => {
                  const budget = budgets.find((x) => x.id === orig.budget_id);
                  if (budget) {
                    setEditingBudget(budget);
                    setAmount(budget.amount.toString());
                    setCategoryId(budget.category_id || "");
                    setCurrency(budget.currency);
                  }
                }}
                onDelete={(id) => {
                  showActionFeedback("error");
                  deleteBudget(id);
                }}
              />
            ))}
          </div>
        </>
      )}

      <Dialog
        open={showNewBudgetDialog || !!editingBudget}
        onOpenChange={(o) => {
          if (!o) {
            setShowNewBudgetDialog(false);
            setEditingBudget(null);
            resetForm();
          }
        }}
      >
        <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:rounded-lg rounded-b-none sm:rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b">
          <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
            <div className="w-12 h-2 bg-muted rounded-full" />
          </div>
          <DialogHeader className="px-6 pt-2 pb-2 text-left shrink-0">
            <DialogTitle className="font-display text-2xl font-bold">
              {editingBudget ? "Ajustar Planejamento" : "Novo Limite Mensal"}
            </DialogTitle>
          </DialogHeader>
          <div className="px-6 pb-6 overflow-y-auto hide-scrollbar space-y-6">
            <div className="space-y-2 mt-4">
              <Label className="text-sm uppercase font-bold tracking-widest text-muted-foreground">
                Categoria (Opcional)
              </Label>
              <Popover
                open={openCategoryPopover}
                onOpenChange={setOpenCategoryPopover}
                modal={true}
              >
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    role="combobox"
                    aria-expanded={openCategoryPopover}
                    className="w-full justify-between rounded-xl h-12 font-normal"
                  >
                    {categoryId ? (
                      categories.find((c) => c.id === categoryId) ? (
                        <span className="flex items-center gap-2">
                          {categories.find((c) => c.id === categoryId)?.icon}{" "}
                          {categories.find((c) => c.id === categoryId)?.name}
                        </span>
                      ) : (
                        "Filtro Global"
                      )
                    ) : (
                      "Filtro Global"
                    )}
                    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent
                  className="w-[var(--radix-popover-trigger-width)] p-0 rounded-xl shadow-xl"
                  align="start"
                >
                  <Command>
                    <CommandInput placeholder="Buscar categoriaÔÇª" />
                    <CommandList>
                      <CommandEmpty>Nenhuma categoria encontrada.</CommandEmpty>
                      <CommandGroup>
                        <CommandItem
                          key="all"
                          value="all"
                          onSelect={() => {
                            setCategoryId("");
                            setOpenCategoryPopover(false);
                          }}
                        >
                          <Check
                            className={cn(
                              "mr-2 h-4 w-4",
                              !categoryId ? "opacity-100" : "opacity-0"
                            )}
                          />
                          Filtro Global
                        </CommandItem>
                        {categories
                          .filter((c) => c.type === "expense")
                          .map((c) => (
                            <CommandItem
                              key={c.id}
                              value={c.name}
                              onSelect={() => {
                                setCategoryId(c.id);
                                setOpenCategoryPopover(false);
                              }}
                            >
                              <Check
                                className={cn(
                                  "mr-2 h-4 w-4",
                                  categoryId === c.id ? "opacity-100" : "opacity-0"
                                )}
                              />
                              {c.icon} {c.name}
                            </CommandItem>
                          ))}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label className="text-sm uppercase font-bold tracking-widest text-muted-foreground">
                  Valor Limite
                </Label>
                <CurrencyInput
                  id="budgetAmount"
                  name="budgetAmount"
                  value={amount}
                  onChange={setAmount}
                  currency={currency}
                />
              </div>
              <div className="space-y-2">
                <Label className="text-sm uppercase font-bold tracking-widest text-muted-foreground">
                  Moeda
                </Label>
                <Select value={currency} onValueChange={setCurrency}>
                  <SelectTrigger
                    id="budgetCurrency"
                    name="budgetCurrency"
                    className="rounded-xl h-12"
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent className="rounded-xl">
                    {availableCurrencies.map((c) => (
                      <SelectItem key={c} value={c}>
                        {moneyUtils.getSymbol(c)} {c}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="pt-2 flex gap-3">
              <Button
                type="button"
                variant="outline"
                className="flex-1 rounded-xl h-12"
                onClick={() => {
                  setShowNewBudgetDialog(false);
                  setEditingBudget(null);
                  resetForm();
                }}
              >
                Descartar
              </Button>
              <Button
                className="flex-1 rounded-xl h-12 font-bold"
                onClick={handleSubmit}
                disabled={!amount || isCreating || isUpdating}
              >
                {editingBudget ? "Salvar" : "Ativar"}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect, useMemo, useRef, useCallback } from "react";
import { useSearchParams, useParams, useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { CurrencyInput } from "@/components/ui/currency-input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Plus, CreditCard, Trash2, Archive, Download, Loader2, AlertCircle, Pencil } from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useMonth } from "@/contexts/MonthContext";
import { getBankById, banks, internationalBanks } from "@/lib/banks";
import { BankIcon } from "@/components/financial/BankIcon";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  useAccounts,
  useCreateAccount,
  useUpdateAccount,
  useDeleteAccount,
  useArchiveAccount,
  useArchivedAccounts,
  useUnarchiveAccount,
  useCreditCardInvoice,
  useAccountDependencies,
} from "@/hooks/useAccounts";
import { useDependentTransactions } from "@/hooks/transactions/useDependentTransactions";
import {
  useTransactions,
  useCreateTransaction,
  useDeleteTransaction,
  useBulkCreateTransactions,
} from "@/hooks/useTransactions";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";
import { getInvoiceData, getTargetDate, formatCycleRange } from "@/lib/invoiceUtils";
import { formatDateISO, getMonthDateRange } from "@/utils/dateUtils";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";

import { TransactionModal } from "@/components/modals/TransactionModal";
import {
  DeleteTransactionModal,
  CascadeDeleteType,
} from "@/components/modals/DeleteTransactionModal";
import { EmptyState } from "@/components/ui/empty-state";

// Modular Components
import { CreditCardDetailView } from "@/components/credit-cards/CreditCardDetailView";
import { CreditCardsList } from "@/components/credit-cards/CreditCardsList";
import { NewCardDialog } from "@/components/credit-cards/NewCardDialog";
import { ImportBillsDialog } from "@/components/credit-cards/ImportBillsDialog";

import { PayInvoiceDialog } from "@/components/credit-cards/PayInvoiceDialog";
import { ArchivedCardsSection } from "@/components/credit-cards/ArchivedCardsSection";
import { ArchiveConfirmModal } from "@/components/modals/ArchiveConfirmModal";
import { ShareCardDialog } from "@/components/credit-cards/ShareCardDialog";
import { PendingSharedCardInvitationsAlert } from "@/components/credit-cards/PendingSharedCardInvitationsAlert";
import { moneyUtils } from "@/utils/money";
import { useCreditCardsDashboard } from "@/hooks/credit-cards/useCreditCardsDashboard";

type CardView = "list" | "detail";

interface CreditCardAccount {
  id: string;
  name: string;
  bank_id: string | null;
  credit_limit: number | null;
  balance: number;
  closing_day: number | null;
  due_day: number | null;
  currency?: string;
  is_international?: boolean;
}

import { useQueryClient } from "@tanstack/react-query";

export function CreditCards() {
  const queryClient = useQueryClient();

  const {
    view,
    setView,
    selectedCard,
    setSelectedCard,
    showArchiveConfirmModal,
    setShowArchiveConfirmModal,
    showNewCardDialog,
    setShowNewCardDialog,
    showImportDialog,
    setShowImportDialog,
    showPayDialog,
    setShowPayDialog,
    showSharingDialog,
    setShowSharingDialog,
    showTransactionModal,
    setShowTransactionModal,
    selectedDate,
    setSelectedDate,

    newBankId,
    setNewBankId,
    newCustomBankName,
    setNewCustomBankName,
    newBrand,
    setNewBrand,
    newCardName,
    setNewCardName,
    newClosingDay,
    setNewClosingDay,
    newClosingDayMode,
    setNewClosingDayMode,
    newDueDay,
    setNewDueDay,
    newLimit,
    setNewLimit,
    newIsInternational,
    setNewIsInternational,
    newCurrency,
    setNewCurrency,

    isLoading,
    transactionsLoading,
    creditCards,
    archivedCards,

    createAccount,
    archiveAccountMutation,
    unarchiveAccountMutation,
    deleteAccountMutation,
    bulkCreateTransactions,

    deleteCardConfirm,
    setDeleteCardConfirm,
    deleteCardCanDelete,
    selectedCardCanDelete,

    editingTransaction,
    setEditingTransaction,
    deleteConfirm,
    setDeleteConfirm,

    showEditCardDialog,
    setShowEditCardDialog,
    editCardName,
    setEditCardName,
    editClosingDay,
    setEditClosingDay,
    editDueDay,
    setEditDueDay,
    editLimit,
    setEditLimit,
    editCardColor,
    setEditCardColor,
    editBankId,
    setEditBankId,
    editCustomBankName,
    setEditCustomBankName,

    invoiceData,
    invoiceFetching,

    getCardInvoice,
    getCardInstallments,
    formatCurrency,
    getDaysUntilDue,

    handleCreateCard,
    handleDeleteTransaction,
    handleEditCard,
    handleExportCards,
    handlePayInvoice,

    totalInvoices,
    totalDebt,
    nextDueDate,
    exportTransactions,
    closingOverride,

    refetchAccounts,
    refetchTransactions,
    user,
  } = useCreditCardsDashboard();

  // Fetch transactions from family members who used owned cards
  const ownedCardIds = useMemo(
    () => creditCards.filter((c: any) => !c.is_shared_with_me).map((c: any) => c.id),
    [creditCards]
  );
  const depStartDate = selectedDate
    ? dateFns.format(dateFns.subMonths(selectedDate, 2), "yyyy-MM-dd")
    : undefined;
  const depEndDate = selectedDate
    ? dateFns.format(dateFns.addMonths(selectedDate, 1), "yyyy-MM-dd")
    : undefined;
  const { data: dependentTransactions = [] } = useDependentTransactions({
    cardIds: ownedCardIds,
    startDate: depStartDate,
    endDate: depEndDate,
  });

  const { id: urlCardId } = useParams<{ id: string }>();
  const navigate = useNavigate();

  // Sincroniza URL ÔåÆ estado: ao navegar diretamente para /cartoes/:id
  useEffect(() => {
    if (!creditCards.length) return;
    if (urlCardId) {
      const card = creditCards.find((c) => c.id === urlCardId);
      if (card) {
        setSelectedCard(card);
        setView("detail");
      } else {
        navigate("/cartoes", { replace: true });
      }
    } else {
      setView("list");
      setSelectedCard(null);
    }
  }, [urlCardId, creditCards.length]);

  const handleSelectCard = useCallback(
    (card: CreditCardAccount) => {
      setSelectedCard(card);
      setView("detail");
      navigate(`/cartoes/${card.id}`);
    },
    [navigate, setSelectedCard, setView]
  );

  const handleGoBack = useCallback(() => {
    setView("list");
    setSelectedCard(null);
    navigate("/cartoes");
  }, [navigate, setSelectedCard, setView]);

  const { data: accounts = [] } = useAccounts();

  if (isLoading)
    return (
      <div className="space-y-5 animate-fade-in pb-20">
        <div className="relative overflow-hidden rounded-2xl p-4 md:p-5 border border-border/50 bg-card/50">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="space-y-2">
              <div className="skeleton h-10 w-36 rounded-xl" />
              <div className="skeleton h-4 w-52 rounded-lg" />
            </div>
            <div className="skeleton h-12 w-36 rounded-xl" />
          </div>
        </div>
        {/* Summary skeleton */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="skeleton h-24 rounded-2xl" />
          ))}
        </div>
        {/* Cards list skeleton */}
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="skeleton h-28 rounded-2xl" />
          ))}
        </div>
      </div>
    );

  if (view === "detail" && selectedCard && invoiceData) {
    return (
      <>
        <CreditCardDetailView
          selectedCard={{ ...selectedCard, closing_date_override: closingOverride }}
          goBack={handleGoBack}
          openEditCardDialog={(card) => {
            setEditCardName(card.name);
            setEditCardColor(card.bank_color || getBankById(card.bank_id).color || "#3b82f6");
            setEditClosingDay(card.closing_day?.toString() || "");
            setEditDueDay(card.due_day?.toString() || "");
            setEditLimit(card.credit_limit?.toString() || "");
            if (card.bank_id && card.bank_id.startsWith("custom:")) {
              setEditBankId("other");
              setEditCustomBankName(card.bank_id.replace("custom:", ""));
            } else {
              setEditBankId(card.bank_id || "");
              setEditCustomBankName("");
            }
            setShowEditCardDialog(true);
          }}
          setDeleteCardConfirm={setDeleteCardConfirm}
          selectedDate={selectedDate}
          changeMonth={(offset) => setSelectedDate((prev) => dateFns.addMonths(prev, offset))}
          goToCurrentMonth={() => setSelectedDate(dateFns.startOfMonth(new Date()))}
          monthName={dateFns.format(selectedDate, "MMMM 'de' yyyy", { locale: ptBR })}
          cycleRange={formatCycleRange(invoiceData.startDate, invoiceData.closingDate)}
          invoiceFetching={invoiceFetching}
          invoiceData={invoiceData}
          formatCurrency={formatCurrency}
          daysUntilDue={getDaysUntilDue(invoiceData.dueDate)}
          usagePercent={
            selectedCard.credit_limit
              ? (invoiceData.invoiceTotal / selectedCard.credit_limit) * 100
              : 0
          }
          bank={getBankById(selectedCard.bank_id)}
          setShowPayDialog={setShowPayDialog}
          setShowImportDialog={setShowImportDialog}
          handleEditTransaction={(tx) => {
            setEditingTransaction({
              ...tx,
              category_id: tx.category_id || tx.category?.id,
              date: tx.date.includes("T") ? tx.date : `${tx.date}T00:00:00`,
            });
            setShowTransactionModal(true);
          }}
          setDeleteConfirm={setDeleteConfirm}
          installments={getCardInstallments(invoiceData.transactions)}
          allYearTransactions={exportTransactions}
          canDelete={selectedCardCanDelete}
          onArchive={(card) => setShowArchiveConfirmModal(true)}
          onUnarchive={async (card) => {
            try {
              await unarchiveAccountMutation.mutateAsync(card.id);
            } catch {
              /* onError do hook j├í trata */
            }
            toast.success("Cart├úo desarquivado!");
            handleGoBack();
          }}
          setShowSharingDialog={setShowSharingDialog}
          dependentTransactions={dependentTransactions}
          onAdjustClosingDate={async (newDay, referenceDate) => {
            if (!selectedCard) return;
            const refStart = dateFns.startOfMonth(referenceDate);
            // Evitar dias inv├ílidos (ex: 31 de abril vira 30)
            const safeClosingDate = dateFns.setDate(refStart, Math.min(newDay, dateFns.getDaysInMonth(refStart)));

            const { error } = await supabase
              .from("credit_card_closing_overrides")
              .upsert({
                account_id: selectedCard.id,
                reference_date: dateFns.format(refStart, "yyyy-MM-dd"),
                closing_date: dateFns.format(safeClosingDate, "yyyy-MM-dd")
              }, { onConflict: "account_id, reference_date" });

            if (!error) {
              toast.success(`Fechamento da fatura atual ajustado para dia ${newDay}`);
              queryClient.invalidateQueries({ queryKey: ["credit-card-closing-override"] });
              queryClient.invalidateQueries({ queryKey: ["credit-card-invoice"] });
              refetchAccounts();
              refetchTransactions();
            } else {
              toast.error("Erro ao ajustar fechamento da fatura");
            }
          }}
        />

        <ShareCardDialog
          isOpen={showSharingDialog}
          onClose={() => setShowSharingDialog(false)}
          card={selectedCard}
        />

        <ImportBillsDialog
          isOpen={showImportDialog}
          onClose={() => setShowImportDialog(false)}
          account={selectedCard}
          onImport={async (txs) => {
            try {
              await bulkCreateTransactions.mutateAsync(txs as any);
            } catch {
              /* onError do hook j├í trata */
            }
            toast.success("Faturas importadas!");
            setShowImportDialog(false);
          }}
        />

        <PayInvoiceDialog
          isOpen={showPayDialog}
          onClose={() => setShowPayDialog(false)}
          card={selectedCard}
          invoiceTotal={invoiceData.invoiceTotal}
          accounts={accounts.filter((a) => a.type !== "CREDIT_CARD")}
          onPay={handlePayInvoice}
        />

        <TransactionModal
          open={showTransactionModal}
          onOpenChange={(open) => {
            setShowTransactionModal(open);
            if (!open) {
              setEditingTransaction(null);
              refetchTransactions();
            }
          }}
          initialData={editingTransaction}
        />

        <DeleteTransactionModal
          isOpen={deleteConfirm.isOpen}
          onClose={() => setDeleteConfirm({ isOpen: false, transaction: null })}
          onConfirm={handleDeleteTransaction}
          transaction={deleteConfirm.transaction}
        />

        <Dialog open={showEditCardDialog} onOpenChange={setShowEditCardDialog}>
          <DialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-lg !rounded-b-none sm:!rounded-b-lg p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b overflow-hidden bg-background">
            <div className="w-full flex justify-center pt-3 pb-1 sm:hidden">
              <div className="w-12 h-2 bg-muted rounded-full" />
            </div>
            <DialogHeader className="px-5 pt-2 pb-2 text-left shrink-0 border-b border-border/40">
              <DialogTitle className="flex items-center gap-2.5">
                <div className="w-8 h-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
                  <Pencil className="w-4 h-4 text-primary" />
                </div>
                <div className="flex flex-col">
                  <span className="text-sm font-bold">Editar Cart├úo</span>
                  <span className="text-xs font-medium text-muted-foreground">
                    {selectedCard?.name}
                  </span>
                </div>
              </DialogTitle>
            </DialogHeader>
            <div className="px-5 py-4 space-y-4 overflow-y-auto">
              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  Nome
                </Label>
                <Input
                  value={editCardName}
                  onChange={(e) => setEditCardName(e.target.value)}
                  className="rounded-xl"
                />
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  Banco Emissor
                </Label>
                {editBankId === "other" && (
                  <div className="flex items-center gap-2 p-2 bg-warning/10 text-warning rounded-lg text-sm border border-warning/20">
                    <AlertCircle className="w-4 h-4 shrink-0" /> O banco ser├í salvo com o ├¡cone
                    padr├úo.
                  </div>
                )}
                <Select value={editBankId} onValueChange={setEditBankId}>
                  <SelectTrigger className="rounded-xl">
                    <SelectValue placeholder="Selecione o banco" />
                  </SelectTrigger>
                  <SelectContent>
                    {(selectedCard?.is_international
                      ? Object.values(internationalBanks)
                      : Object.values(banks)
                    ).map((b) => (
                      <SelectItem key={b.id} value={b.id}>
                        <div className="flex items-center gap-2">
                          <BankIcon bankId={b.id} size="sm" />
                          {b.name}
                        </div>
                      </SelectItem>
                    ))}
                    <SelectItem
                      value="other"
                      className="text-warning font-medium border-t mt-1 pt-1"
                    >
                      Outro Banco
                    </SelectItem>
                  </SelectContent>
                </Select>
                {editBankId === "other" && (
                  <Input
                    placeholder="Ex: Carrefour, C&A..."
                    value={editCustomBankName}
                    onChange={(e) => setEditCustomBankName(e.target.value)}
                    className="rounded-xl border-warning/30 mt-1"
                  />
                )}
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  Cor do cart├úo
                </Label>
                <div className="flex flex-wrap gap-2">
                  {[
                    "#0f172a",
                    "#3b82f6",
                    "#8b5cf6",
                    "#ec4899",
                    "#f43f5e",
                    "#ef4444",
                    "#f97316",
                    "#eab308",
                    "#22c55e",
                    "#14b8a6",
                    "#06b6d4",
                    "#64748b",
                  ].map((color) => (
                    <button
                      key={color}
                      type="button"
                      className={`w-9 h-9 rounded-xl border-2 transition-all ${editCardColor === color ? "border-primary scale-110 shadow-md" : "border-transparent hover:scale-105"}`}
                      style={{ backgroundColor: color }}
                      onClick={() => setEditCardColor(color)}
                    />
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                    Fechamento
                  </Label>
                  <Input
                    type="number"
                    inputMode="numeric"
                    min={1}
                    max={31}
                    className="rounded-xl font-mono"
                    value={editClosingDay}
                    onChange={(e) => {
                      const v = e.target.value;
                      if (v === "") {
                        setEditClosingDay("");
                        return;
                      }
                      const n = parseInt(v);
                      if (!isNaN(n)) setEditClosingDay(Math.min(31, Math.max(1, n)).toString());
                    }}
                    disabled={selectedCard?.user_id !== user?.id}
                  />
                </div>
                <div className="space-y-1.5">
                  <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                    Vencimento
                  </Label>
                  <Input
                    type="number"
                    inputMode="numeric"
                    min={1}
                    max={31}
                    className="rounded-xl font-mono"
                    value={editDueDay}
                    onChange={(e) => {
                      const v = e.target.value;
                      if (v === "") {
                        setEditDueDay("");
                        return;
                      }
                      const n = parseInt(v);
                      if (!isNaN(n)) setEditDueDay(Math.min(31, Math.max(1, n)).toString());
                    }}
                    disabled={selectedCard?.user_id !== user?.id}
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <Label className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  Limite
                </Label>
                <CurrencyInput
                  value={editLimit}
                  onChange={setEditLimit}
                  currency={selectedCard?.currency || "BRL"}
                />
              </div>

              {selectedCard?.user_id !== user?.id && (
                <p className="text-sm text-warning">
                  As datas de ciclo s├úo gerenciadas pelo dono do cart├úo.
                </p>
              )}
            </div>
            <DialogFooter className="px-5 pb-5 pt-3 border-t border-border/40 gap-2">
              <Button
                variant="outline"
                className="rounded-xl flex-1"
                onClick={() => setShowEditCardDialog(false)}
              >
                Cancelar
              </Button>
              <Button
                className="rounded-xl flex-1 font-semibold shadow-lg shadow-primary/20"
                onClick={handleEditCard}
                disabled={
                  !editCardName ||
                  !editClosingDay ||
                  !editDueDay ||
                  !editLimit ||
                  !editBankId ||
                  (editBankId === "other" && !editCustomBankName.trim())
                }
              >
                Salvar Altera├º├Áes
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <AlertDialog
          open={deleteCardConfirm.isOpen}
          onOpenChange={(open) => !open && setDeleteCardConfirm({ isOpen: false, card: null })}
        >
          <AlertDialogContent className="w-full sm:max-w-md !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden">
            <AlertDialogHeader>
              <AlertDialogTitle>Remover cart├úo "{deleteCardConfirm.card?.name}"?</AlertDialogTitle>
            </AlertDialogHeader>
            <div className="flex flex-col gap-3 py-4">
              <Button
                variant="outline"
                className="justify-start gap-3"
                onClick={async () => {
                  if (deleteCardConfirm.card) {
                    try {
                      await archiveAccountMutation.mutateAsync(deleteCardConfirm.card.id);
                    } catch {
                      /* onError do hook j├í trata */
                    }
                    setDeleteCardConfirm({ isOpen: false, card: null });
                  }
                }}
              >
                <Archive className="h-4 w-4" /> Arquivar (Recomendado)
              </Button>
              {deleteCardCanDelete && (
                <Button
                  variant="destructive"
                  className="justify-start gap-3"
                  onClick={async () => {
                    if (deleteCardConfirm.card) {
                      try {
                        await deleteAccountMutation.mutateAsync(deleteCardConfirm.card.id);
                      } catch {
                        /* onError do hook j├í trata */
                      }
                      setDeleteCardConfirm({ isOpen: false, card: null });
                      setView("list");
                      refetchAccounts();
                    }
                  }}
                >
                  <Trash2 className="h-4 w-4" /> Excluir Permanentemente
                </Button>
              )}
            </div>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancelar</AlertDialogCancel>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </>
    );
  }

  return (
    <div className="space-y-5 animate-fade-in pb-20">
      <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 transition-all duration-700 ease-out bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        <div className="relative flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="font-display font-black text-2xl md:text-3xl tracking-tighter">
              Cart├Áes
            </h1>
            <p className="text-muted-foreground mt-1 text-sm md:text-base font-medium">
              Gerencie faturas e limites
            </p>
          </div>
          <div className="grid grid-cols-2 sm:flex sm:flex-row gap-2 w-full sm:w-auto">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  size="default"
                  variant="outline"
                  className="gap-2 shadow-sm border-border/80 w-full sm:w-auto px-2"
                >
                  <Download className="h-4 w-4" />
                  <span className="text-sm md:text-sm">Exportar</span>
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-[200px]">
                <DropdownMenuItem onClick={() => handleExportCards("PDF", "MONTH")}>
                  Mensal em PDF
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportCards("CSV", "MONTH")}>
                  Mensal em Excel (CSV)
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportCards("PDF", "YEAR")}>
                  Anual em PDF
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportCards("CSV", "YEAR")}>
                  Anual em Excel (CSV)
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            <Button
              size="default"
              onClick={() => setShowNewCardDialog(true)}
              className="shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95 group w-full sm:w-auto font-bold px-2"
            >
              <Plus className="h-4 w-4 mr-1 md:mr-2 group-hover:scale-110 transition-transform" />
              <span className="text-sm md:text-sm">Novo cart├úo</span>
            </Button>
          </div>
        </div>
      </div>

      {creditCards.length > 0 ? (
        <CreditCardsList
          creditCards={creditCards}
          totalInvoices={totalInvoices}
          totalDebt={totalDebt}
          nextDueDate={nextDueDate}
          formatCurrency={formatCurrency}
          getCardInvoice={getCardInvoice}
          isLoading={isLoading || transactionsLoading}
          onRefresh={() => {
            refetchAccounts();
            refetchTransactions();
          }}
          onSelectCard={handleSelectCard}
        />
      ) : (
        <EmptyState
          icon={CreditCard}
          title="Nenhum cart├úo cadastrado"
          description="Voc├¬ ainda n├úo possui cart├Áes de cr├®dito. Adicione um para controlar faturas e limites."
          action={<Button onClick={() => setShowNewCardDialog(true)}>Novo cart├úo</Button>}
          className="my-8"
        />
      )}

      <ArchivedCardsSection
        archivedCards={archivedCards}
        formatCurrency={formatCurrency}
        onUnarchive={(id) => unarchiveAccountMutation.mutate(id)}
        isUnarchiving={unarchiveAccountMutation.isPending}
        onCardSelect={handleSelectCard}
      />

      <NewCardDialog
        open={showNewCardDialog}
        onOpenChange={setShowNewCardDialog}
        onSubmit={handleCreateCard}
        isLoading={createAccount.isPending}
        bankId={newBankId}
        setBankId={setNewBankId}
        customBankName={newCustomBankName}
        setCustomBankName={setNewCustomBankName}
        brand={newBrand}
        setBrand={setNewBrand}
        cardName={newCardName}
        setCardName={setNewCardName}
        closingDay={newClosingDay}
        setClosingDay={setNewClosingDay}
        dueDay={newDueDay}
        setDueDay={setNewDueDay}
        limit={newLimit}
        setLimit={setNewLimit}
        isInternational={newIsInternational}
        setIsInternational={setNewIsInternational}
        currency={newCurrency}
        setCurrency={setNewCurrency}
      />

      {selectedCard && (
        <ArchiveConfirmModal
          isOpen={showArchiveConfirmModal}
          onClose={() => setShowArchiveConfirmModal(false)}
          onConfirm={async () => {
            try {
              await archiveAccountMutation.mutateAsync(selectedCard.id);
            } catch {
              /* onError do hook j├í trata */
            }
            toast.success("Cart├úo arquivado com sucesso!");
            setShowArchiveConfirmModal(false);
            setView("list");
            setSelectedCard(null);
          }}
          itemName={selectedCard.name}
          isArchiving={archiveAccountMutation.isPending}
        />
      )}
    </div>
  );
}

import { FamilyMemberCard } from '@/components/family/FamilyMemberCard';
import { InviteMemberDialog } from '@/components/family/InviteMemberDialog';
import { Button } from '@/components/ui/button';
import { EmptyState } from '@/components/ui/empty-state';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { useAuth } from '@/contexts/AuthContext';
import {
  FamilyRole,
  useAddSharedContact,
  useConvertContactToMember,
  useConvertMemberToContact,
  useFamily,
  useFamilyMembers,
  useInviteFamilyMember,
  useRemoveFamilyMember,
  useSharedContacts,
  useToggleContactActiveInForm,
  useUpdateFamilyMember,
} from '@/hooks/useFamily';
import { useCancelInvitation, useFamilyInvitations } from '@/hooks/useFamilyInvitations';
import { cn } from '@/lib/utils';
import { Check, Crown, Plus, Trash2, UserCircle2, UserPlus, Users, X } from 'lucide-react';
import { useState } from 'react';
import { toast } from 'sonner';

const roleLabels: Record<FamilyRole, { label: string; description: string }> = {
  admin: { label: 'Administrador', description: 'Acesso total, pode gerenciar membros' },
  editor: { label: 'Editor', description: 'Pode criar e editar transa├º├Áes' },
  viewer: { label: 'Visualizador', description: 'Apenas visualiza├º├úo' },
};

export function Family() {
  const { user } = useAuth();
  const { data: family, isLoading: familyLoading } = useFamily();
  const { data: members = [], isLoading: membersLoading } = useFamilyMembers();
  const { data: contacts = [] } = useSharedContacts();
  const { data: invitations = [] } = useFamilyInvitations();
  const inviteMember = useInviteFamilyMember();
  const updateMember = useUpdateFamilyMember();
  const removeMember = useRemoveFamilyMember();
  const cancelInvitation = useCancelInvitation();
  const moveToContact = useConvertMemberToContact();
  const moveToFamily = useConvertContactToMember();
  const toggleActiveInForm = useToggleContactActiveInForm();
  const addContact = useAddSharedContact();

  const [showInviteDialog, setShowInviteDialog] = useState(false);
  const isOwner = family?.owner_id === user?.id;
  const canInvite = !family || isOwner;

  const getInitials = (n: string) =>
    n
      .split(' ')
      .map((x) => x[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  const getRoleColor = (r: string) =>
    r === 'admin'
      ? 'bg-foreground text-background'
      : r === 'editor'
        ? 'bg-primary/20 text-primary'
        : 'bg-muted text-muted-foreground';

  if (familyLoading || membersLoading)
    return (
      <div className="space-y-8 animate-fade-in pb-20">
        <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 border border-border/50 bg-card/50">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="space-y-2">
              <div className="skeleton h-10 w-48 rounded-xl" />
              <div className="skeleton h-4 w-64 rounded-lg" />
            </div>
            <div className="skeleton h-12 w-36 rounded-xl" />
          </div>
        </div>
        <div className="skeleton h-20 rounded-2xl" />
        <div className="space-y-2">
          <div className="skeleton h-4 w-32 rounded-lg" />
          {[1, 2, 3].map((i) => (
            <div key={i} className="skeleton h-20 rounded-xl" />
          ))}
        </div>
      </div>
    );

  const activeMembers = members.filter(
    (m) => m.status === 'active' && m.linked_user_id !== user?.id,
  );
  const pendingInvitations = [
    ...invitations.filter((i) => i.status === 'pending'),
    ...members.filter((m) => m.status === 'pending'),
  ];

  const formatFamilyName = (name: string) => {
    if (!name) return 'Fam├¡lia';

    // Se o nome cont├®m "Fam├¡lia de" seguido de algo com ponto ou cara de email
    if (name.includes('Fam├¡lia de') && (name.includes('.') || name.includes('_'))) {
      const parts = name.replace('Fam├¡lia de ', '').split(/[._]/);
      const firstName = parts[0];
      return `Fam├¡lia de ${firstName.charAt(0).toUpperCase() + firstName.slice(1)}`;
    }

    return name;
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 transition-all duration-700 ease-out bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        <div className="relative flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="font-display font-black text-2xl md:text-4xl tracking-tighter">
              {formatFamilyName(family?.name || 'Fam├¡lia')}
            </h1>
            <p className="text-muted-foreground mt-1 text-sm md:text-base font-medium">
              Gerencie o n├║cleo familiar e as contas vinculadas
            </p>
          </div>
          {canInvite && (
            <Button
              size="default"
              className="shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95 group h-12 w-full sm:w-auto font-bold"
              onClick={() => setShowInviteDialog(true)}
            >
              <UserPlus className="h-4 w-4 mr-2 transition-transform group-hover:scale-110" />
              Convidar
            </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        <div className="flex flex-col gap-1 p-4 rounded-2xl border border-border/50 bg-card/50">
          <p className="text-xs text-muted-foreground uppercase font-bold tracking-widest">
            Ativos
          </p>
          <p className="font-mono text-2xl font-bold text-foreground">{activeMembers.length}</p>
        </div>
        {pendingInvitations.length > 0 && (
          <div className="flex flex-col gap-1 p-4 rounded-2xl border border-warning/20 bg-warning/5">
            <p className="text-xs text-warning/70 dark:text-warning/70 uppercase font-bold tracking-widest">
              Pendentes
            </p>
            <p className="font-mono text-2xl font-bold text-warning dark:text-warning">
              {pendingInvitations.length}
            </p>
          </div>
        )}
        <div className="flex flex-col gap-1 p-4 rounded-2xl border border-border/50 bg-card/50">
          <p className="text-xs text-muted-foreground uppercase font-bold tracking-widest">Total</p>
          <p className="font-mono text-2xl font-bold text-foreground">{members.length}</p>
        </div>
      </div>

      <div className="space-y-4">
        <h2 className="text-xs uppercase tracking-widest text-muted-foreground font-medium">
          Membros ({activeMembers.length})
        </h2>
        {activeMembers.length === 0 ? (
          <EmptyState
            icon={Users}
            title="Nenhum membro ativo"
            description="Convide familiares para participarem da sua conta, compartilharem viagens ou cart├Áes de cr├®dito em conjunto."
            action={
              <Button
                onClick={() => setShowInviteDialog(true)}
                className="h-12 px-8 rounded-2xl shadow-lg shadow-primary/20 hover:-translate-y-0.5 transition-all font-semibold"
              >
                <Plus className="w-4 h-4 mr-2" />
                Convidar Membro
              </Button>
            }
          />
        ) : (
          <div className="space-y-2">
            {activeMembers.map((m) => (
              <FamilyMemberCard
                key={m.id}
                member={m}
                isSelf={m.linked_user_id === user?.id}
                roleLabels={roleLabels}
                getInitials={getInitials}
                onUpdateRole={async (id, r) => {
                  try {
                    await updateMember.mutateAsync({ id, role: r });
                    toast.success('Permiss├úo atualizada com sucesso');
                  } catch (e: any) {
                    toast.error(e.message || 'Erro ao atualizar permiss├úo');
                  }
                }}
                onRemove={async (id) => {
                  try {
                    await removeMember.mutateAsync(id);
                    toast.success('Membro removido com sucesso');
                  } catch (e: any) {
                    toast.error(e.message || 'Erro ao remover membro');
                  }
                }}
                onMoveToContact={
                  isOwner
                    ? async (id) => {
                        await moveToContact.mutateAsync(id);
                      }
                    : undefined
                }
              />
            ))}
          </div>
        )}
      </div>

      {pendingInvitations.length > 0 && (
        <div className="space-y-4">
          <h2 className="text-xs uppercase tracking-widest text-muted-foreground font-medium">
            Aguardando resposta ({pendingInvitations.length})
          </h2>
          <div className="space-y-2">
            {pendingInvitations.map((i: any) => (
              <div
                key={i.id}
                className="p-4 rounded-xl border border-dashed bg-muted/30 flex items-center justify-between"
              >
                <div className="flex items-center gap-4">
                  <div className="w-12 h-12 rounded-full bg-muted flex items-center justify-center text-sm">
                    {getInitials(i.member_name || i.name)}
                  </div>
                  <div>
                    <p className="font-display font-semibold">{i.member_name || i.name}</p>
                    <p className="text-xs text-muted-foreground">Convite pendente</p>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="text-destructive hover:bg-destructive/10 transition-colors"
                  disabled={cancelInvitation.isPending || removeMember.isPending}
                  onClick={async () => {
                    try {
                      if (i.member_name) {
                        await cancelInvitation.mutateAsync(i.id);
                      } else {
                        await removeMember.mutateAsync(i.id);
                      }
                      toast.success('Convite cancelado');
                    } catch (e: any) {
                      toast.error(e.message || 'Erro ao cancelar convite');
                    }
                  }}
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <UserCircle2 className="h-4 w-4 text-muted-foreground" />
            <h2 className="text-xs uppercase tracking-widest text-muted-foreground font-medium">
              Contatos de Despesa ({contacts.length})
            </h2>
          </div>
          {isOwner && (
            <Button
              variant="ghost"
              size="sm"
              className="h-8 text-xs gap-1"
