                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">No formul├írio</span>
                    <Switch
                      checked={!!c.active_in_form}
                      onCheckedChange={(checked) =>
