                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              </div>
              <SharedBalanceChart
                transactions={data.allCombinedTransactions}
                invoices={invoices}
                currentDate={safeCurrentDate}
                isGeneralReport={true}
                monthlyData={data.monthlyData}
                currency={selectedCurrency}
