    queryClient,
    selectedMember,
    settleAccountId,
    settleType,
    settleAmount,
    selectedItems,
    settleDate,
    members,
    getFilteredInvoice,
    createTransaction,
    user,
    invalidateRelated,
    refetch,
    undoConfirm,
    setUndoConfirm,
    deleteConfirm,
    setDeleteConfirm,
    deleteSeriesConfirm,
    setDeleteSeriesConfirm,
    setIsUndoingAll,
    setUndoAllConfirm,
    setIsSettling,
    setShowSettleDialog,
    setSelectedMember,
    setSettleAmount,
    setSettleAccountId,
    setSelectedItems,
    formatCurrency,
    accounts,
  });

  const handleExportShared = async (formatType: "PDF" | "CSV", period: "MONTH" | "YEAR") => {
    const { exportSharedToCSV, exportSharedToPDF } = await import("@/utils/exportData");
    const allItems: InvoiceItem[] = Object.values(invoices).flat();
    let filteredItems = allItems;
    let periodLabel = `${currentDate.getFullYear()}`;

    if (period === "MONTH") {
      filteredItems = allItems.filter((item) => {
        if (!item.date) return false;
        const [y, m] = item.date.split("-").map(Number);
        return y === currentDate.getFullYear() && m - 1 === currentDate.getMonth();
      });
      const monthNames = [
        "Janeiro", "Fevereiro", "Mar├ºo", "Abril", "Maio", "Junho",
        "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro",
      ];
      periodLabel = `${monthNames[currentDate.getMonth()]} de ${currentDate.getFullYear()}`;
    } else {
      filteredItems = allItems.filter((item) => {
        if (!item.date) return false;
        const [y] = item.date.split("-").map(Number);
        return y === currentDate.getFullYear();
      });
      periodLabel = `Ano ${currentDate.getFullYear()}`;
    }

    if (formatType === "PDF") {
      exportSharedToPDF(filteredItems, periodLabel, totalsByCurrency);
    } else {
      exportSharedToCSV(filteredItems, periodLabel);
    }
  };

  const handleSettleClick = (id: string, type: "PAY" | "RECEIVE", amt: number, specificItem?: InvoiceItem) => {
    setSelectedMember(id);
    setSettleType(type);
    if (specificItem) {
      setSelectedItems([specificItem.id]);
      setSettleAmount(Math.abs(amt).toFixed(2).replace(".", ","));
      setSettlingMode("SINGLE");
    } else {
      const pending = getFilteredInvoice(id).filter((i) => !i.isPaid);
      setSelectedItems(pending.map((i) => i.id));
      setSettleAmount(Math.abs(amt).toFixed(2).replace(".", ","));
      setSettlingMode("ALL");
    }
    setShowSettleDialog(true);
  };

  const handleSettleTripClick = (id: string, type: "PAY" | "RECEIVE", amt: number, specificItem: InvoiceItem | undefined, tripId: string) => {
    setSelectedMember(id);
    setSettleType(type);
    if (specificItem) {
      setSelectedItems([specificItem.id]);
      setSettleAmount(Math.abs(amt).toFixed(2).replace(".", ","));
      setSettlingMode("SINGLE");
    } else {
      const pending = getFilteredInvoice(id).filter((i) => !i.isPaid && i.tripId === tripId);
      setSelectedItems(pending.map((i) => i.id));
      setSettleAmount(Math.abs(amt).toFixed(2).replace(".", ","));
      setSettlingMode("ALL");
    }
    setShowSettleDialog(true);
  };

  useEffect(() => {
    const tabParam = searchParams.get("tab") as SharedTab;
    if (tabParam && ["REGULAR", "TRAVEL", "HISTORY"].includes(tabParam)) {
      setActiveTab(tabParam);
    }

    const splitIdsParam = searchParams.get("confirmSettlement");
    if (splitIdsParam && invoices && !sharedLoading) {
      const splitIds = splitIdsParam.split(",");
      const allItems = Object.values(invoices).flat();

      const itemsToConfirm = allItems.filter(
        (i) => splitIds.includes(i.splitId || "") && !i.isPaid
      );

      if (itemsToConfirm.length > 0) {
        setConfirmReceiptDialog({ isOpen: true, items: itemsToConfirm });
        navigate({ search: "" }, { replace: true });
      }
    }
  }, [searchParams, invoices, sharedLoading, navigate]);

  useEffect(() => {
    const splitIdsParam = searchParams.get("confirmPaymentSplit");
    if (splitIdsParam && invoices && !sharedLoading) {
      const splitIds = splitIdsParam.split(",");
      const allItems = Object.values(invoices).flat();

      const itemsToConfirm = allItems.filter(
        (i) => splitIds.includes(i.splitId || "") && !i.isPaid
      );

      if (itemsToConfirm.length > 0) {
        setConfirmPaymentDialog({ isOpen: true, items: itemsToConfirm });
        navigate({ search: "" }, { replace: true });
      }
    }
  }, [searchParams, invoices, sharedLoading, navigate]);

  const hasData = members.length > 0 && Object.keys(invoices).length > 0;
  const isInitialLoading = (membersLoading || sharedLoading) && !hasData;

  if (isInitialLoading) {
    return (
      <div className="space-y-8 animate-fade-in">
        <div className="h-12 w-48 bg-muted rounded animate-pulse" />
        <div className="h-24 bg-muted rounded animate-pulse" />
        <div className="space-y-2">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-24 bg-muted rounded animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 transition-all duration-700 ease-out bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        <div className="relative flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <div>
            <h1 className="font-display font-black text-3xl tracking-tighter">Compartilhados</h1>
            <p className="text-muted-foreground text-sm font-medium">
              Despesas divididas com a fam├¡lia e amigos
            </p>
          </div>
          <div className="flex flex-wrap sm:flex-nowrap gap-2 w-full sm:w-auto mt-4 sm:mt-0">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button size="default" variant="outline" className="gap-2 shadow-sm border-border/80 w-full sm:w-auto h-12">
                  <Download className="h-5 w-5" />
                  <span>Exportar</span>
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-[200px]">
                <DropdownMenuItem onClick={() => handleExportShared("PDF", "MONTH")}>Mensal em PDF</DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportShared("CSV", "MONTH")}>Mensal em Excel (CSV)</DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportShared("PDF", "YEAR")}>Anual em PDF</DropdownMenuItem>
                <DropdownMenuItem onClick={() => handleExportShared("CSV", "YEAR")}>Anual em Excel (CSV)</DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
            <Button size="default" variant="default" className="shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95 gap-2 w-full sm:w-auto h-12" onClick={() => setShowImportDialog(true)}>
              <Layers className="h-5 w-5" />
              <span>Importar Parcelas</span>
            </Button>
          </div>
        </div>
      </div>

      <Suspense fallback={null}>
        <SharedBalanceChart transactions={transactions} invoices={invoices} currentDate={currentDate} />
      </Suspense>
      <SharedSummarySection totalsByCurrency={totalsByCurrency} travelTotalsByCurrency={travelTotalsByCurrency} formatCurrency={formatCurrency} activeTab={activeTab} />

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as SharedTab)} className="w-full">
        <TabsList className="grid grid-cols-3 w-full h-auto p-1.5 bg-secondary/30 rounded-2xl mb-8 shadow-inner border border-border/40">
          <TabsTrigger value="REGULAR" className="rounded-xl py-3 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm transition-all duration-300">
            <div className="flex flex-col items-center gap-2">
              <Users className="h-4 w-4" />
              <span className="text-sm font-bold uppercase tracking-wider">Regular</span>
            </div>
          </TabsTrigger>
          <TabsTrigger value="TRAVEL" className="rounded-xl py-3 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm transition-all duration-300">
            <div className="flex flex-col items-center gap-2">
              <Plane className="h-4 w-4" />
              <span className="text-sm font-bold uppercase tracking-wider">Viagens</span>
            </div>
          </TabsTrigger>
          <TabsTrigger value="HISTORY" className="rounded-xl py-3 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm transition-all duration-300">
            <div className="flex flex-col items-center gap-2">
              <History className="h-4 w-4" />
              <span className="text-sm font-bold uppercase tracking-wider">Hist├│rico</span>
            </div>
          </TabsTrigger>
        </TabsList>

        <TabsContent value={activeTab}>
          {members.length === 0 ? (
            <EmptyState
              icon={Users}
              title="Nenhum membro ativo"
              description="Convide membros da sua fam├¡lia para come├ºar a dividir despesas e gerenciar or├ºamentos compartilhados."
              action={
                <Button onClick={() => navigate("/familia")} variant="outline" className="h-12 px-8 rounded-2xl gap-2 border-primary/20 hover:bg-primary/5 hover:text-primary hover:border-primary/40 transition-all font-semibold">
                  <Users className="h-4 w-4" />
                  Convidar Membros
                </Button>
              }
            />
          ) : (
            <div className="space-y-4">
              {activeTab === "HISTORY" && members.some((m) => getFilteredInvoice(m.id).some((i) => i.isPaid)) && (
                <div className="flex justify-end">
                  <Button variant="destructive" size="sm" onClick={() => setUndoAllConfirm(true)} className="gap-2">
                    <Undo2 className="h-4 w-4" /> Desfazer Tudo
                  </Button>
                </div>
              )}
              {activeTab !== "TRAVEL" ? (
                <SharedRegularList
                  members={members} user={user} activeTab={activeTab} getFilteredInvoice={getFilteredInvoice} getTotals={getTotals} formatCurrency={formatCurrency}
                  onSettle={handleSettleClick}
                  onUndo={(i) => setUndoConfirm({ isOpen: true, item: i })}
                  onDelete={(i) => setDeleteConfirm({ isOpen: true, item: i })}
                  onConfirmReceipt={(i) => setConfirmReceiptDialog({ isOpen: true, items: [i] })}
                  onRejectSettlement={(i) => setRejectDialog({ isOpen: true, item: i, reason: "" })}
                  onAnticipate={(i) => setAnticipateDialog({ isOpen: true, seriesId: i.seriesId ?? null, currentInstallment: i.installmentNumber ?? 0, totalInstallments: i.totalInstallments ?? 0 })}
                />
              ) : (
                <SharedTravelList
                  trips={trips} members={members} user={user} getFilteredInvoice={getFilteredInvoice} getTotals={getTotals} formatCurrency={formatCurrency}
                  onSettle={handleSettleTripClick}
                  onUndo={(i) => setUndoConfirm({ isOpen: true, item: i })}
                  onDelete={(i) => setDeleteConfirm({ isOpen: true, item: i })}
                  onDeleteSeries={(i) => setDeleteSeriesConfirm({ isOpen: true, item: i })}
                  onConfirmReceipt={(i) => setConfirmReceiptDialog({ isOpen: true, items: [i] })}
                  onAnticipate={(i) => setAnticipateDialog({ isOpen: true, seriesId: i.seriesId ?? null, currentInstallment: i.installmentNumber ?? 0, totalInstallments: i.totalInstallments ?? 0 })}
                />
              )}
              {(activeTab === "TRAVEL"
                ? trips.filter((t) => members.some((m) => getFilteredInvoice(m.id).some((i) => i.tripId === t.id))).length === 0
                : members.filter((m) => m.linked_user_id !== user?.id).every((m) => getFilteredInvoice(m.id).length === 0)) && (
                <EmptyState icon={CheckCircle2} title="Tudo em dia!" description="Nenhuma despesa compartilhada pendente neste per├¡odo." variant="success" />
              )}
            </div>
          )}
        </TabsContent>
      </Tabs>

      <SharedSettleDialog
        isOpen={showSettleDialog}
        onOpenChange={setShowSettleDialog}
        selectedMember={selectedMember}
        members={members}
        pendingMemberItems={selectedMember ? getFilteredInvoice(selectedMember).filter((i) => !i.isPaid) : []}
        selectedItems={selectedItems}
        onToggleItem={(id) =>
          setSelectedItems((prev) => {
            const ni = prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id];
            if (selectedMember) {
              const items = getFilteredInvoice(selectedMember);
              const tot = items.filter((i) => ni.includes(i.id)).reduce((s, x) => x.type === "CREDIT" ? SafeFinancialCalculator.add(s, x.amount) : SafeFinancialCalculator.subtract(s, x.amount), 0);
              setSettleAmount(Math.abs(tot).toFixed(2).replace(".", ","));
              setSettleType(tot >= 0 ? "RECEIVE" : "PAY");
            }
            return ni;
          })
        }
        onSelectAll={() => {
          if (!selectedMember) return;
          const items = getFilteredInvoice(selectedMember).filter((i) => !i.isPaid);
          if (selectedItems.length === items.length) {
            setSelectedItems([]);
            setSettleAmount("0,00");
            setSettleType("PAY");
          } else {
            setSelectedItems(items.map((i) => i.id));
            const tot = items.reduce((s, x) => x.type === "CREDIT" ? SafeFinancialCalculator.add(s, x.amount) : SafeFinancialCalculator.subtract(s, x.amount), 0);
            setSettleAmount(Math.abs(tot).toFixed(2).replace(".", ","));
            setSettleType(tot >= 0 ? "RECEIVE" : "PAY");
          }
        }}
        settleType={settleType}
        settleAmount={settleAmount}
        settleDate={settleDate}
        setSettleDate={setSettleDate}
        settleAccountId={settleAccountId}
        setSettleAccountId={setSettleAccountId}
        accounts={accounts}
        trips={trips}
        profile={profile}
        user={user}
        onSettle={handleSettle}
        isSettling={isSettling}
        settlingMode={settlingMode}
      />

      <SharedExpensesDialogs
        undoConfirm={undoConfirm} setUndoConfirm={setUndoConfirm}
        deleteConfirm={deleteConfirm} setDeleteConfirm={setDeleteConfirm}
        deleteSeriesConfirm={deleteSeriesConfirm} setDeleteSeriesConfirm={setDeleteSeriesConfirm}
        undoAllConfirm={undoAllConfirm} setUndoAllConfirm={setUndoAllConfirm}
        rejectDialog={rejectDialog} setRejectDialog={setRejectDialog}
        isUndoingAll={isUndoingAll}
        handleUndoSettlement={handleUndoSettlement}
        handleDeleteTransaction={handleDeleteTransaction}
        handleDeleteSeries={handleDeleteSeries}
        handleUndoAll={handleUndoAll}
        handleRejectSettlement={handleRejectSettlement}
        handleRejectDebtorSettlement={handleRejectDebtorSettlement}
      />

      <Suspense fallback={null}>
        <SharedInstallmentImport isOpen={showImportDialog} onClose={() => setShowImportDialog(false)} members={members} onSuccess={() => refetch()} />
      </Suspense>

      <TransactionModal open={showTransactionModal} onOpenChange={setShowTransactionModal} />

      <SettlementConfirmationDialog
        isOpen={confirmReceiptDialog.isOpen}
        onOpenChange={(o) => setConfirmReceiptDialog({ ...confirmReceiptDialog, isOpen: o })}
        items={confirmReceiptDialog.items}
        isSettling={isSettling}
        onConfirm={handleConfirmReceipt}
      />
      <SettlementConfirmationDialog
        isOpen={confirmPaymentDialog.isOpen}
        onOpenChange={(o) => setConfirmPaymentDialog({ ...confirmPaymentDialog, isOpen: o })}
        items={confirmPaymentDialog.items}
        isSettling={isSettling}
        onConfirm={handleConfirmPayment}
      />
      <Suspense fallback={null}>
        {anticipateDialog.seriesId && (
          <AnticipateInstallmentsDialog
            isOpen={anticipateDialog.isOpen}
            onClose={() => setAnticipateDialog((prev) => ({ ...prev, isOpen: false }))}
            seriesId={anticipateDialog.seriesId}
            currentInstallment={anticipateDialog.currentInstallment}
            totalInstallments={anticipateDialog.totalInstallments}
            onSuccess={() => {
              refetch();
              syncAllShared();
            }}
          />
        )}
      </Suspense>
    </div>
  );
}

import { useState, useEffect, useMemo } from "react";
import { PullToRefresh } from "@/components/ui/PullToRefresh";
import { showActionFeedback } from "@/components/ui/ActionFeedback";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import { useLocation } from "react-router-dom";
import { Clock, CalendarClock, List } from "lucide-react";
import { Button } from "@/components/ui/button";
import { useTransactions, useDeleteTransaction, Transaction } from "@/hooks/useTransactions";
import {
  DeleteTransactionModal,
  CascadeDeleteType,
} from "@/components/modals/DeleteTransactionModal";
import { useFamilyMembers } from "@/hooks/useFamily";
import { useAuth } from "@/contexts/AuthContext";
import { useMonth } from "@/contexts/MonthContext";
import { TransactionModal } from "@/components/modals/TransactionModal";
import { AdvanceInstallmentsDialog } from "@/components/transactions/AdvanceInstallmentsDialog";
import { TransactionDetailsModal } from "@/components/transactions/TransactionDetailsModal";
import { useUnconfirmScheduledBill } from "@/hooks/useScheduledBills";
import { OFXImportModal } from "@/components/modals/OFXImportModal";
import { TransactionHeader } from "@/components/transactions/TransactionHeader";
import { TransactionSummary } from "@/components/transactions/TransactionSummary";
import { TransactionFilters } from "@/components/transactions/TransactionFilters";
import { TransactionList } from "@/components/transactions/TransactionList";
import { UpcomingTransactions } from "@/components/transactions/UpcomingTransactions";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { getTransactionCurrency, groupTransactionsByDay, applyTransactionFilters } from "@/utils/transactionUtils";
import { getCurrencySymbol } from "@/services/exchangeCalculations";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import { useTransactionSync } from "@/hooks/useTransactionSync";
import { haptics } from "@/utils/haptics";

export function Transactions() {
  const location = useLocation();
  const [activeTab, setActiveTab] = useState<"lancadas" | "proximas">(
    (location.state as any)?.tab === "proximas" ? "proximas" : "lancadas"
  );
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedType, setSelectedType] = useState<string>("all");
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [selectedAccount, setSelectedAccount] = useState<string>("all");
  const [selectedPeriod, setSelectedPeriod] = useState<string>("all");
  const [showFilters, setShowFilters] = useState(false);

  const [deleteConfirm, setDeleteConfirm] = useState<{
    isOpen: boolean;
    transaction: Transaction | null;
  }>({ isOpen: false, transaction: null });
  const [showTransactionModal, setShowTransactionModal] = useState(false);
  const [editTransactionData, setEditTransactionData] = useState<Transaction | null>(null);

  const [detailsTransaction, setDetailsTransaction] = useState<Transaction | null>(null);
  const [advanceSeriesId, setAdvanceSeriesId] = useState<string | null>(null);
  const [advanceDescription, setAdvanceDescription] = useState<string>("");
  const [showOfxModal, setShowOfxModal] = useState(false);

  const { user } = useAuth();
  const { currentDate } = useMonth();
  const { data: transactions, isLoading, isError, refetch } = useTransactions();
  const { data: annualTransactions = [] } = useTransactions({
    startDate: `${currentDate.getFullYear()}-01-01`,
    endDate: `${currentDate.getFullYear()}-12-31`,
  });
  const { data: familyMembers = [] } = useFamilyMembers();
  const deleteTransaction = useDeleteTransaction();
  const unconfirmTransaction = useUnconfirmScheduledBill();
  const { invalidateRelated } = useTransactionSync();

  useEffect(() => {
    const handleOpenModal = () => setShowTransactionModal(true);
    window.addEventListener("openTransactionModal", handleOpenModal);
    return () => window.removeEventListener("openTransactionModal", handleOpenModal);
  }, []);

  const formatCurrency = (value: number, currency: string = "BRL") => {
    if (currency !== "BRL") {
      const symbol = getCurrencySymbol(currency);
      return `${symbol} ${Math.abs(value).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    }
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: "BRL",
    }).format(Math.abs(value));
  };

  const [selectedCurrency, setSelectedCurrency] = useState<string>("BRL");

  const { categories, accounts, availableCurrencies } = useMemo(() => {
    const catMap = new Map<string, { id: string; name: string; icon: string }>();
    const accMap = new Map<string, { id: string; name: string }>();
    const currencySet = new Set<string>();

    (transactions || []).forEach((t) => {
      if (t.category?.id && t.category?.name) {
        catMap.set(t.category.id, {
          id: t.category.id,
          name: t.category.name,
          icon: t.category.icon || "­ƒôü",
        });
      }
      if (t.account?.id && t.account?.name) {
        accMap.set(t.account.id, { id: t.account.id, name: t.account.name });
      }
      currencySet.add(getTransactionCurrency(t));
    });

    return {
      categories: Array.from(catMap.values()).sort((a, b) => a.name.localeCompare(b.name)),
      accounts: Array.from(accMap.values()).sort((a, b) => a.name.localeCompare(b.name)),
      availableCurrencies: Array.from(currencySet).sort(),
    };
  }, [transactions]);

  const filterParams = useMemo(() => ({
    searchQuery,
    selectedType,
    selectedCategory,
    selectedAccount,
    selectedPeriod,
    selectedCurrency,
    userId: user?.id,
    familyMembers,
  }), [searchQuery, selectedType, selectedCategory, selectedAccount, selectedPeriod, selectedCurrency, user?.id, familyMembers]);

  const filteredTransactions = useMemo(() => {
    return applyTransactionFilters(transactions || [], filterParams);
  }, [transactions, filterParams]);

  const filteredAnnualTransactions = useMemo(() => {
    return applyTransactionFilters(annualTransactions || [], { ...filterParams, selectedPeriod: "all" });
  }, [annualTransactions, filterParams]);

  const isSearchingHistory = searchQuery.trim().length > 0;
  const displayTransactions = isSearchingHistory
    ? filteredAnnualTransactions
    : filteredTransactions;
  const dayGroups = useMemo(
    () => groupTransactionsByDay(displayTransactions),
    [displayTransactions]
  );
  const totalIncome = filteredTransactions
    .filter((t) => t.type === "INCOME")
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
  const totalExpense = filteredTransactions
    .filter((t) => t.type === "EXPENSE")
    .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);

  const currencySummaries = useMemo(() => {
    if (selectedCurrency !== "all") return null;
    const map: Record<string, { income: number; expense: number }> = {};
    filteredTransactions.forEach((t) => {
      const cur = getTransactionCurrency(t);
      if (!map[cur]) map[cur] = { income: 0, expense: 0 };
      if (t.type === "INCOME") map[cur].income += Number(t.amount);
      if (t.type === "EXPENSE") map[cur].expense += Number(t.amount);
    });
    return Object.entries(map).filter(([, v]) => v.income > 0 || v.expense > 0);
  }, [filteredTransactions, selectedCurrency]);
  const hasFilters =
    selectedType !== "all" ||
    selectedCategory !== "all" ||
    selectedAccount !== "all" ||
    selectedPeriod !== "all";

  const clearFilters = () => {
    setSelectedType("all");
    setSelectedCategory("all");
    setSelectedAccount("all");
    setSelectedPeriod("all");
  };

  const handleDelete = async (cascadeType: CascadeDeleteType) => {
    if (!deleteConfirm.transaction) return;

    const tx = deleteConfirm.transaction;

    if (tx.is_shared && isFullySettled(tx)) {
      showActionFeedback("error");
      toast.error("Transa├º├úo acertada n├úo pode ser exclu├¡da");
      setDeleteConfirm({ isOpen: false, transaction: null });
      return;
    }

    showActionFeedback("success");
    haptics.heavy();

    setTimeout(() => {
      setDeleteConfirm({ isOpen: false, transaction: null });
      setDetailsTransaction(null);
    }, 80);

    try {
      deleteTransaction.mutate({ id: tx.id, cascadeType });
      if (tx.is_shared) invalidateRelated(tx.id);
    } catch {
      /* onError do hook j├í trata */
    }
  };

  const handleAdvance = (transaction: Transaction) => {
    if (transaction.series_id) {
      setAdvanceSeriesId(transaction.series_id);
      setAdvanceDescription(transaction.description.replace(/\s*\(\d+\/\d+\)$/, ""));
    }
  };

  const handleUnconfirm = (transaction: Transaction) => {
    showActionFeedback("success");
    setTimeout(() => {
      setDetailsTransaction(null);
    }, 80);
    unconfirmTransaction.mutate({ id: transaction.id });
  };

  const getCreatorName = (transaction: Transaction) => {
    if (!transaction.creator_user_id) return null;
    if (transaction.creator_user_id === user?.id) return "Voc├¬";
    const member = familyMembers.find(
      (m) =>
        m.user_id === transaction.creator_user_id ||
        m.linked_user_id === transaction.creator_user_id
    );
    return member?.name || "Outro membro";
  };

  const handleEdit = (transaction: Transaction) => {
    setEditTransactionData(transaction);
    setShowTransactionModal(true);
    if (detailsTransaction) {
      setDetailsTransaction(null);
    }
  };

  const getPayerInfo = (transaction: Transaction) => {
    if (!transaction.is_shared) return null;
    const myFamilyMemberId = familyMembers.find((m) => m.linked_user_id === user?.id)?.id;
    if (
      !transaction.payer_id ||
      transaction.payer_id === user?.id ||
      transaction.payer_id === myFamilyMemberId
    )
      return { label: "Voc├¬ pagou", isMe: true };
    const payer = familyMembers.find((m) => m.id === transaction.payer_id);
    return payer ? { label: `Pago por ${payer.name}`, isMe: false } : null;
  };

  const hasPendingSplits = (transaction: Transaction) =>
    !!(
      transaction.is_shared &&
      (transaction.transaction_splits?.some((s: any) => !s.is_settled) || false)
    );
  const isFullySettled = (transaction: Transaction) =>
    !!(
      transaction.is_shared &&
      transaction.transaction_splits &&
      transaction.transaction_splits.length > 0 &&
      transaction.transaction_splits.every((s: any) => s.is_settled)
    );

  if (isLoading)
    return (
      <div className="space-y-6 animate-fade-in">
        {/* Header skeleton */}
        <div className="relative overflow-hidden rounded-2xl p-6 border border-border/50 bg-card/50">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="space-y-2">
              <div className="skeleton h-10 w-44 rounded-xl" />
              <div className="skeleton h-4 w-24 rounded-lg" />
            </div>
            <div className="flex gap-2">
              <div className="skeleton h-10 w-32 rounded-xl" />
              <div className="skeleton h-10 w-28 rounded-xl" />
            </div>
          </div>
        </div>
        {/* Summary cards skeleton */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="skeleton h-20 rounded-2xl" />
          ))}
        </div>
        {/* List skeleton */}
        <div className="space-y-2">
          <div className="skeleton h-4 w-32 rounded-lg" />
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="skeleton h-16 rounded-xl" />
          ))}
        </div>
      </div>
    );
  if (isError)
    return (
      <div className="flex flex-col items-center justify-center min-h-[400px] text-center p-8 bg-background border border-border rounded-2xl">
        <div className="w-16 h-16 bg-negative/10 text-negative rounded-full flex items-center justify-center mb-4">
          <Clock className="h-8 w-8 opacity-50" />
        </div>
        <h2 className="text-xl font-bold mb-2">Erro ao carregar transa├º├Áes</h2>
        <Button onClick={() => refetch()} variant="outline">
          Tentar novamente
        </Button>
      </div>
    );

  return (
    <PullToRefresh queryKeys={[["transactions"], ["scheduled-bills"]]}>
      <div className="space-y-6 animate-fade-in">
        <TransactionHeader
          count={displayTransactions.length}
          filteredTransactions={displayTransactions}
          filteredAnnualTransactions={filteredAnnualTransactions}
          onImportOFX={() => setShowOfxModal(true)}
        />

        {/* Tabs: Lan├ºadas / Pr├│ximas */}
        <div className="flex gap-1 p-1 rounded-xl bg-muted/50 border border-border/50">
          <button
            onClick={() => setActiveTab("lancadas")}
            className={cn(
              "flex-1 flex items-center justify-center gap-2 py-2 px-3 rounded-lg text-sm font-medium transition-all",
              activeTab === "lancadas"
                ? "bg-card shadow-sm text-foreground border border-border/60"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            <List className="h-4 w-4" />
            Lan├ºadas
          </button>
          <button
            onClick={() => setActiveTab("proximas")}
            className={cn(
              "flex-1 flex items-center justify-center gap-2 py-2 px-3 rounded-lg text-sm font-medium transition-all",
              activeTab === "proximas"
                ? "bg-card shadow-sm text-foreground border border-border/60"
                : "text-muted-foreground hover:text-foreground"
            )}
          >
            <CalendarClock className="h-4 w-4" />
            Pr├│ximas
          </button>
        </div>

        {activeTab === "proximas" ? (
          <UpcomingTransactions />
        ) : (
          <>
            {availableCurrencies.length > 1 && (
              <div className="flex justify-end">
                <div className="w-32">
                  <Select value={selectedCurrency} onValueChange={setSelectedCurrency}>
                    <SelectTrigger className="h-10 bg-muted/50 border-border/50">
                      <SelectValue placeholder="Moeda" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all" className="font-medium">
                        Todas
                      </SelectItem>
                      {availableCurrencies.map((c) => (
                        <SelectItem key={c} value={c} className="font-medium">
                          {c}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
            )}

            {selectedCurrency !== "all" ? (
              <TransactionSummary
                totalIncome={totalIncome}
                totalExpense={totalExpense}
                formatCurrency={(v) => formatCurrency(v, selectedCurrency)}
              />
            ) : currencySummaries && currencySummaries.length > 0 ? (
              <div className="space-y-2">
                {currencySummaries.map(([cur, { income, expense }]) => (
                  <div
                    key={cur}
                    className="flex items-center gap-2 px-3 py-2.5 rounded-xl border border-border bg-card text-sm"
                  >
                    <span className="font-bold text-xs uppercase tracking-widest text-muted-foreground w-10 shrink-0">
                      {cur}
                    </span>
                    <span className="text-positive font-mono font-bold tabular-nums">
                      +{formatCurrency(income, cur)}
                    </span>
                    <span className="text-muted-foreground mx-1">┬À</span>
                    <span className="text-negative font-mono font-bold tabular-nums">
                      -{formatCurrency(expense, cur)}
                    </span>
                    <span className="text-muted-foreground mx-1">┬À</span>
                    <span
                      className={cn(
                        "font-mono font-bold tabular-nums ml-auto",
                        income - expense >= 0 ? "text-primary" : "text-warning"
                      )}
                    >
                      {income - expense >= 0 ? "+" : "-"}
                      {formatCurrency(Math.abs(income - expense), cur)}
                    </span>
                  </div>
                ))}
              </div>
            ) : null}
            <TransactionFilters
              searchQuery={searchQuery}
              setSearchQuery={setSearchQuery}
              selectedType={selectedType}
              setSelectedType={setSelectedType}
              selectedCategory={selectedCategory}
              setSelectedCategory={setSelectedCategory}
              selectedAccount={selectedAccount}
              setSelectedAccount={setSelectedAccount}
              selectedPeriod={selectedPeriod}
              setSelectedPeriod={setSelectedPeriod}
              showFilters={showFilters}
              setShowFilters={setShowFilters}
              categories={categories}
              accounts={accounts}
              hasFilters={hasFilters}
              clearFilters={clearFilters}
            />
            {isSearchingHistory && (
              <div className="flex items-center gap-2 px-3 py-2 rounded-xl bg-primary/10 border border-primary/20 text-sm text-primary font-medium -mt-1">
                <Clock className="h-4 w-4 shrink-0" />
                Buscando em todo o ano ┬À {displayTransactions.length} resultado
                {displayTransactions.length !== 1 ? "s" : ""}
              </div>
            )}

            <TransactionList
              dayGroups={dayGroups}
              user={user}
              familyMembers={familyMembers}
              formatCurrency={formatCurrency}
              onDetails={setDetailsTransaction}
              onSettlement={() => {}}
              onAdvance={handleAdvance}
              onEdit={handleEdit}
              onDelete={(tx) => setDeleteConfirm({ isOpen: true, transaction: tx })}
              isFullySettled={isFullySettled}
              hasPendingSplits={hasPendingSplits}
              getCreatorName={getCreatorName}
              getPayerInfo={getPayerInfo}
              selectedAccount={selectedAccount}
              hasActiveFilter={
                searchQuery.trim().length > 0 ||
                selectedType !== "all" ||
                selectedCategory !== "all" ||
                selectedAccount !== "all"
              }
            />
          </>
        )}

        {/* Alert Dialogs & Modals */}
        <DeleteTransactionModal
          isOpen={deleteConfirm.isOpen}
          onClose={() => setDeleteConfirm({ isOpen: false, transaction: null })}
          onConfirm={handleDelete}
          transaction={deleteConfirm.transaction}
          isDeleting={deleteTransaction.isPending}
        />

        <AdvanceInstallmentsDialog
          open={!!advanceSeriesId}
          onOpenChange={(open) => {
            if (!open) {
              setAdvanceSeriesId(null);
              setAdvanceDescription("");
            }
          }}
          seriesId={advanceSeriesId || ""}
          transactionDescription={advanceDescription}
        />
        <TransactionDetailsModal
          open={!!detailsTransaction}
          onOpenChange={(open) => {
            if (!open) setDetailsTransaction(null);
          }}
          transaction={detailsTransaction}
          onDelete={() =>
            detailsTransaction &&
            setDeleteConfirm({ isOpen: true, transaction: detailsTransaction })
          }
          onAdvance={() => detailsTransaction && handleAdvance(detailsTransaction)}
          onEdit={() => detailsTransaction && handleEdit(detailsTransaction)}
          onUnconfirm={() => detailsTransaction && handleUnconfirm(detailsTransaction)}
        />
        <TransactionModal
          open={showTransactionModal}
          onOpenChange={(open) => {
            setShowTransactionModal(open);
            if (!open) setEditTransactionData(null);
          }}
          initialData={editTransactionData}
        />
        <OFXImportModal isOpen={showOfxModal} onClose={() => setShowOfxModal(false)} />
      </div>
    </PullToRefresh>
  );
}

import { EditTripDialog } from "@/components/trips/EditTripDialog";
import { NewTripDialog } from "@/components/trips/NewTripDialog";
import { Button } from "@/components/ui/button";
import { useFamilyMembers } from "@/hooks/useFamily";
import { useAddGuestTripMember, useTripPermissions } from "@/hooks/useTripMembers";
import {
  useArchiveTrip,
  useCreateTrip,
  useDeleteTrip,
  useRemoveTripParticipant,
  useTrip,
  useTripFinancialSummary,
  useTripParticipantBalances,
  useTripParticipants,
  useTrips,
  useTripTransactions,
  useUnarchiveTrip,
  useUpdateTrip,
} from "@/hooks/useTrips";
import { moneyUtils } from "@/utils/money";
import { Loader2, Plus, Trash2 } from "lucide-react";
import { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";

import { AddParticipantDialog } from "@/components/trips/AddParticipantDialog";
import { PendingTripInvitationsAlert } from "@/components/trips/PendingTripInvitationsAlert";
import {
  useCancelTripInvitation,
  useCreateTripInvitation,
  useSentTripInvitations,
} from "@/hooks/useTripInvitations";

import { RemoveParticipantDialog } from "@/components/trips/RemoveParticipantDialog";
import { TripDetailView } from "@/components/trips/TripDetailView";
import { TripEmptyState } from "@/components/trips/TripEmptyState";
import { TripListView } from "@/components/trips/TripListView";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { useAuth } from "@/contexts/AuthContext";
import { useAccounts } from "@/hooks/useAccounts";
import { supabase } from "@/integrations/supabase/client";
import { dismissRelatedNotifications } from "@/services/notificationGenerator";
import { logger } from "@/utils/logger";
import { exportTripToExcel, exportTripToPDF } from "@/utils/tripExport";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

export function Trips() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [view, setView] = useState<"list" | "detail">("list");
  const [selectedTripId, setSelectedTripId] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("summary");
  const [tripFilter, setTripFilter] = useState<"active" | "archived">("active");
  const [showNewTripDialog, setShowNewTripDialog] = useState(false);
  const [showEditTripDialog, setShowEditTripDialog] = useState(false);

  const [showAddParticipantDialog, setShowAddParticipantDialog] = useState(false);

  const [removingParticipant, setRemovingParticipant] = useState<any | null>(null);
  const [removingParticipantBalance, setRemovingParticipantBalance] = useState<any | null>(null);
  const [showRemoveDialog, setShowRemoveDialog] = useState(false);
  const [isRemovingState, setIsRemovingState] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [tripToDelete, setTripToDelete] = useState<string | null>(null);

  const [tripName, setTripName] = useState("");
  const [tripDestination, setTripDestination] = useState("");
  const [tripStartDate, setTripStartDate] = useState("");
  const [tripEndDate, setTripEndDate] = useState("");
  const [tripBudget, setTripBudget] = useState("");
  const [tripCurrency, setTripCurrency] = useState("BRL");

  const { data: trips = [], isLoading } = useTrips();
  const { data: selectedTrip } = useTrip(selectedTripId);
  const { data: participants = [] } = useTripParticipants(selectedTripId);
  const { data: tripTransactions = [] } = useTripTransactions(selectedTripId);
  const { data: familyMembers = [] } = useFamilyMembers();

  const { data: permissions } = useTripPermissions(selectedTripId);
  const { data: tripFinancialSummary } = useTripFinancialSummary(selectedTripId);
  const { data: participantBalances = [] } = useTripParticipantBalances(selectedTripId);

  const createTrip = useCreateTrip();
  const updateTrip = useUpdateTrip();
  const deleteTrip = useDeleteTrip();
  const archiveTrip = useArchiveTrip();
  const unarchiveTrip = useUnarchiveTrip();
  const createInvitation = useCreateTripInvitation();
  const addGuestMember = useAddGuestTripMember();
  const { data: sentInvitations = [] } = useSentTripInvitations(selectedTripId);
  const pendingInvitations = sentInvitations.filter((inv: any) => inv.status === "pending");
  const cancelInvitation = useCancelTripInvitation();

  const removeParticipant = useRemoveTripParticipant();
  const { data: accounts = [] } = useAccounts();

  const handleConfirmDirectRemove = async () => {
    if (!removingParticipant || !selectedTripId) return;
    setIsRemovingState(true);
    try {
      await removeParticipant.mutateAsync({
        id: removingParticipant.member_id,
        tripId: selectedTripId,
      });
      queryClient.invalidateQueries({ queryKey: ["trip-participants", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-participant-balances", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-financial-summary", selectedTripId] });
      await dismissRelatedNotifications(user!.id, removingParticipant.member_id, "family_member");
      setShowRemoveDialog(false);
      setRemovingParticipant(null);
      setRemovingParticipantBalance(null);
      toast.success("Membro removido da viagem com sucesso");
    } catch (err: any) {
      logger.error(err);
      toast.error(err.message || "Erro ao remover membro da viagem");
    } finally {
      setIsRemovingState(false);
    }
  };

  const handleConfirmSettleRemove = async (accountId: string) => {
    if (
      !removingParticipant ||
      !selectedTripId ||
      !removingParticipantBalance ||
      !user ||
      !selectedTrip
    )
      return;
    setIsRemovingState(true);
    try {
      const balanceVal = removingParticipantBalance.balance;
      const { error: txError } = await supabase.from("transactions").insert({
        user_id: user.id,
        creator_user_id: user.id,
        account_id: accountId,
        amount: Math.abs(balanceVal),
        type: balanceVal < 0 ? "INCOME" : "EXPENSE",
        description: `Acerto de Contas - Remo├º├úo de ${removingParticipant.name}`,
        date: new Date().toISOString().split("T")[0],
        competence_date: new Date().toISOString().slice(0, 7) + "-01",
        domain: "TRAVEL",
        trip_id: selectedTripId,
        is_shared: false,
        is_settled: true,
        payer_id: balanceVal < 0 ? removingParticipant.user_id || removingParticipant.id : user.id,
        currency: selectedTrip.currency || "BRL",
      });

      if (txError) throw txError;

      await removeParticipant.mutateAsync({
        id: removingParticipant.member_id,
        tripId: selectedTripId,
      });

      queryClient.invalidateQueries({ queryKey: ["trip-participants", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-participant-balances", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-transactions", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-financial-summary", selectedTripId] });

      await dismissRelatedNotifications(user!.id, removingParticipant.member_id, "family_member");
      setShowRemoveDialog(false);
      setRemovingParticipant(null);
      setRemovingParticipantBalance(null);
      toast.success("Membro removido e acerto de contas registrado");
    } catch (err: any) {
      logger.error(err);
      toast.error(err.message || "Erro ao remover membro e acertar contas");
    } finally {
      setIsRemovingState(false);
    }
  };

  const handleConfirmForgiveRemove = async () => {
    if (
      !removingParticipant ||
      !selectedTripId ||
      !removingParticipantBalance ||
      !user ||
      !selectedTrip
    )
      return;
    setIsRemovingState(true);
    try {
      const balanceVal = removingParticipantBalance.balance;
      const { error: txError } = await supabase.from("transactions").insert({
        user_id: user.id,
        creator_user_id: user.id,
        amount: Math.abs(balanceVal),
        type: balanceVal < 0 ? "EXPENSE" : "INCOME",
        description: `Ajuste Cont├íbil (Perd├úo de D├¡vida) - Remo├º├úo de ${removingParticipant.name}`,
        date: new Date().toISOString().split("T")[0],
        competence_date: new Date().toISOString().slice(0, 7) + "-01",
        domain: "TRAVEL",
        trip_id: selectedTripId,
        is_shared: true,
        is_settled: true,
        payer_id: user.id,
        currency: selectedTrip.currency || "BRL",
      });

      if (txError) throw txError;

      await removeParticipant.mutateAsync({
        id: removingParticipant.member_id,
        tripId: selectedTripId,
      });

      queryClient.invalidateQueries({ queryKey: ["trip-participants", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-participant-balances", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-transactions", selectedTripId] });
      queryClient.invalidateQueries({ queryKey: ["trip-financial-summary", selectedTripId] });

      await dismissRelatedNotifications(user!.id, removingParticipant.member_id, "family_member");
      setShowRemoveDialog(false);
      setRemovingParticipant(null);
      setRemovingParticipantBalance(null);
      toast.success("Membro removido e d├¡vida perdoada");
    } catch (err: any) {
      logger.error(err);
      toast.error(err.message || "Erro ao remover membro e perdoar d├¡vida");
    } finally {
      setIsRemovingState(false);
    }
  };

  // Removed unused useSharedFinances call

  const balances = useMemo(() => {
    return participantBalances.map((pb) => ({
      participantId: pb.user_id || pb.participant_id,
      name: pb.name,
      paid: Number(pb.paid),
      owes: Number(pb.owes),
      balance: Number(pb.balance),
      currency: pb.currency,
    }));
  }, [participantBalances]);

  if (isLoading)
    return (
      <div className="space-y-8 animate-fade-in pb-20">
        <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 border border-border/50 bg-card/50">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
            <div className="space-y-2">
              <div className="skeleton h-10 w-36 rounded-xl" />
              <div className="skeleton h-4 w-64 rounded-xl" />
            </div>
            <div className="skeleton h-12 w-36 rounded-xl" />
          </div>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {[1, 2, 3, 4, 5, 6].map((i) => (
            <div key={i} className="skeleton h-40 rounded-2xl" />
          ))}
        </div>
      </div>
    );

  if (view === "detail" && selectedTrip) {
    return (
      <div className="animate-fade-in space-y-6">
        <TripDetailView
          trip={selectedTrip}
          permissions={permissions}
          participants={participants}
          tripTransactions={tripTransactions}
          tripFinancialSummary={tripFinancialSummary}
          user={user}
          activeTab={activeTab}
          setActiveTab={setActiveTab}
          myPersonalBudget={selectedTrip.budget || null}
          balances={balances}
          onBack={() => {
            setView("list");
            setSelectedTripId(null);
          }}
          onEdit={() => setShowEditTripDialog(true)}
          onAddParticipant={() => setShowAddParticipantDialog(true)}
          onArchive={async () => {
            try {
              await archiveTrip.mutateAsync(selectedTripId!);
            } catch {
              /* onError do hook */
            }
            setView("list");
          }}
          onUnarchive={async () => {
            try {
              await unarchiveTrip.mutateAsync(selectedTripId!);
              toast.success("Viagem desarquivada com sucesso!");
            } catch (err: any) {
              toast.error(err.message || "Erro ao desarquivar viagem");
            }
          }}
          onDelete={() => {
            setTripToDelete(selectedTripId!);
            setShowDeleteConfirm(true);
          }}
          onOpenBudget={() => setShowEditTripDialog(true)}
          onUpdateTrip={async (u) => {
            try {
              await updateTrip.mutateAsync({ id: selectedTrip.id, ...u });
            } catch {
              /* onError do hook */
            }
          }}
          formatCurrency={(val, cur) => moneyUtils.format(val, cur || "BRL")}
          onExportPDF={() => {
            if (user)
              exportTripToPDF({
                trip: selectedTrip,
                participants,
                tripTransactions,
                balances,
                user,
              });
          }}
          onExportExcel={() => {
            if (user)
              exportTripToExcel({
                trip: selectedTrip,
                participants,
                tripTransactions,
                balances,
                user,
              });
          }}
          onRemoveParticipantClick={(p, b) => {
            setRemovingParticipant(p);
            setRemovingParticipantBalance(b);
            setShowRemoveDialog(true);
          }}
          pendingInvitations={pendingInvitations}
          onCancelInvitation={cancelInvitation.mutate}
        />

        <RemoveParticipantDialog
          open={showRemoveDialog}
          onOpenChange={setShowRemoveDialog}
          participant={removingParticipant}
          balance={removingParticipantBalance}
          onConfirmDirectRemove={handleConfirmDirectRemove}
          onConfirmSettleRemove={handleConfirmSettleRemove}
          onConfirmForgiveRemove={handleConfirmForgiveRemove}
          isRemoving={isRemovingState}
          currency={selectedTrip.currency || "BRL"}
          accounts={accounts}
        />

        <AddParticipantDialog
          open={showAddParticipantDialog}
          onOpenChange={setShowAddParticipantDialog}
          availableMembers={familyMembers.filter(
            (m) =>
              m.linked_user_id &&
              !participants.some((p) => p.user_id === m.linked_user_id) &&
              m.linked_user_id !== user?.id
          )}
          currentParticipantNames={participants.map((p) => p.name)}
          onAdd={async (m) => {
            if (selectedTripId && m.linked_user_id) {
              try {
                await createInvitation.mutateAsync({
                  tripId: selectedTripId,
                  inviteeId: m.linked_user_id,
                  message: null,
                });
                setShowAddParticipantDialog(false);
              } catch (err) {
                // Erro j├í ├® tratado no hook (exibe o toast amig├ível)
              }
            }
          }}
          onAddGuest={async (guestName) => {
            if (selectedTripId) {
              try {
                await addGuestMember.mutateAsync({ tripId: selectedTripId, guestName });
                setShowAddParticipantDialog(false);
              } catch {
                /* onError do hook j├í trata */
              }
            }
          }}
          onNavigateToFamily={() => {
            setShowAddParticipantDialog(false);
            navigate("/familia");
          }}
          getInitials={(n) =>
            n
              .split(" ")
              .map((x) => x[0])
              .join("")
              .toUpperCase()
              .slice(0, 2)
          }
        />

        <EditTripDialog
          open={showEditTripDialog}
          onOpenChange={setShowEditTripDialog}
          trip={selectedTrip}
          onSubmit={async (d) => {
            try {
              await updateTrip.mutateAsync({ id: selectedTripId!, ...d });
              setShowEditTripDialog(false);
              if (document.activeElement instanceof HTMLElement) {
                document.activeElement.blur();
              }
            } catch (err) {
              logger.error("Erro ao editar viagem", err);
            }
          }}
          isLoading={updateTrip.isPending}
        />
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-fade-in pb-20">
      <div className="relative overflow-hidden rounded-2xl p-4 md:p-6 transition-all duration-700 ease-out bg-gradient-to-br from-primary/10 via-primary/5 to-transparent border border-primary/20">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
        <div className="relative flex flex-col sm:flex-row sm:items-center sm:justify-between gap-6">
          <div className="space-y-2">
            <h1 className="font-display font-black text-3xl tracking-tighter">Viagens</h1>
            <p className="text-muted-foreground text-sm font-medium">
              Organize despesas e roteiros em grupo
            </p>
          </div>
          <Button
            size="default"
            onClick={() => setShowNewTripDialog(true)}
            className="shadow-lg shadow-primary/20 hover:shadow-primary/30 transition-all active:scale-95 group h-12 w-full sm:w-auto font-bold"
          >
            <Plus className="h-4 w-4 mr-2 transition-transform group-hover:scale-110" />
            Nova Viagem
          </Button>
        </div>
      </div>

      <PendingTripInvitationsAlert />

      {trips.length === 0 ? (
        <TripEmptyState onCreateClick={() => setShowNewTripDialog(true)} />
      ) : (
        <TripListView
          trips={trips}
          tripFilter={tripFilter}
          setTripFilter={setTripFilter}
          onTripClick={(id) => {
            setSelectedTripId(id);
            setView("detail");
            setActiveTab("summary");
          }}
          onUnarchive={async (id) => {
            try {
              await unarchiveTrip.mutateAsync(id);
              toast.success("Viagem desarquivada com sucesso!");
            } catch (err: any) {
              toast.error(err.message || "Erro ao desarquivar viagem");
            }
          }}
        />
      )}

      <NewTripDialog
        open={showNewTripDialog}
        onOpenChange={setShowNewTripDialog}
        onSubmit={async (mids) => {
          try {
            await createTrip.mutateAsync({
              name: tripDestination,
              destination: tripDestination,
              start_date: tripStartDate,
              end_date: tripEndDate,
              budget: tripBudget ? moneyUtils.parse(tripBudget) : undefined,
              currency: tripCurrency,
              memberIds: mids,
            });
            setShowNewTripDialog(false);
            setTripName("");
            setTripDestination("");
            setTripStartDate("");
            setTripEndDate("");
            setTripBudget("");
            setTripCurrency("BRL");

            // Close keyboard on mobile
            if (document.activeElement instanceof HTMLElement) {
              document.activeElement.blur();
            }
          } catch (err) {
            logger.error("Erro ao criar viagem", err);
          }
        }}
        isLoading={createTrip.isPending}
        name={tripName}
        setName={setTripName}
        destination={tripDestination}
        setDestination={setTripDestination}
        startDate={tripStartDate}
        setStartDate={setTripStartDate}
        endDate={tripEndDate}
        setEndDate={setTripEndDate}
        budget={tripBudget}
        setBudget={setTripBudget}
        currency={tripCurrency}
        setCurrency={setTripCurrency}
      />
      <AlertDialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <AlertDialogContent className="border-border w-full !bottom-0 !top-auto !translate-y-0 sm:!top-[50%] sm:!bottom-auto sm:!-translate-y-1/2 rounded-t-[2rem] sm:!rounded-4xl !rounded-b-none sm:!rounded-b-[2rem] p-0 shadow-[0_-10px_40px_rgba(0,0,0,0.1)] sm:shadow-lg max-h-[90vh] flex flex-col border-b-0 sm:border-b bg-background overflow-hidden">
          <AlertDialogHeader>
            <AlertDialogTitle>Excluir viagem?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta a├º├úo ├® irrevers├¡vel. A viagem e todos os seus dados associados ser├úo removidos
              permanentemente.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={async (e) => {
                e.preventDefault();
                if (tripToDelete) {
                  try {
                    await deleteTrip.mutateAsync(tripToDelete);
                    toast.success("Viagem exclu├¡da com sucesso");
                    setView("list");
                    setShowDeleteConfirm(false);
                  } catch (err: any) {
                    toast.error(err.message || "Erro ao excluir viagem");
                  }
                }
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90 min-w-[120px]"
              disabled={deleteTrip.isPending}
            >
              {deleteTrip.isPending ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <Trash2 className="h-4 w-4 mr-2" />
              )}
              {deleteTrip.isPending ? "Excluindo..." : "Excluir"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useMemo } from "react";
import { moneyUtils } from "@/utils/money";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import * as dateFns from "date-fns";
import { ptBR } from "date-fns/locale";

const getTransactionCurrency = (tx: any): string => {
  if (tx.currency && tx.currency !== "BRL") return tx.currency;
  if (Array.isArray(tx.account) && tx.account.length > 0 && tx.account[0].currency)
    return tx.account[0].currency;
  if (tx.account && !Array.isArray(tx.account) && tx.account.currency) return tx.account.currency;
  return "BRL";
};

interface UseReportsDataProps {
  viewType: "MONTH" | "YEAR";
  txSearch: string;
  txTypeFilter: string;
  selectedCurrency: string;
  allTransactions: any[];
  sharedTransactions: any[];
  categories: any[];
  accounts: any[];
  familyMembers: any[];
  safeCurrentDate: Date;
  myMemberId?: string;
  user: any;
}

export function useReportsData({
  viewType,
  txSearch,
  txTypeFilter,
  selectedCurrency,
  allTransactions,
  sharedTransactions,
  categories,
  accounts,
  familyMembers,
  safeCurrentDate,
  myMemberId,
  user,
}: UseReportsDataProps) {
  const availableCurrencies = useMemo(() => {
    const currencies = new Set<string>(["BRL"]);
    allTransactions.forEach((tx) => {
      const currency = getTransactionCurrency(tx);
      if (currency !== "BRL") currencies.add(currency);
    });

    // Moedas das transa├º├Áes compartilhadas envolvidas
    sharedTransactions.forEach((tx: any) => {
      const isMeThePayer =
        tx.user_id === user?.id || (tx.payer_id === myMemberId && tx.payer_id != null);

      let isMeInvolved = isMeThePayer;
      if (!isMeInvolved && tx.is_shared && tx.transaction_splits) {
        isMeInvolved = tx.transaction_splits.some((s: any) => s.member_id === myMemberId);
      }
      if (
        !isMeInvolved &&
        !tx.is_shared &&
        tx.domain === "SHARED" &&
        tx.related_member_id === myMemberId
      ) {
        isMeInvolved = true;
      }

      if (isMeInvolved) {
        const currency = tx.currency || "BRL";
        if (currency !== "BRL") currencies.add(currency);
      }
    });

    accounts.forEach((acc) => {
      if (acc.is_international && acc.currency) currencies.add(acc.currency);
    });
    return Array.from(currencies).sort();
  }, [allTransactions, sharedTransactions, accounts, myMemberId, user?.id]);

  const allCombinedTransactions = useMemo(() => {
    // 1. Processar transa├º├Áes onde o usu├írio logado ├® o pagador
    const processedOwn = allTransactions
      .map((tx) => {
        const isSettlement =
          (tx.description?.includes("Acerto") ||
            tx.description?.includes("acerto") ||
            (tx as any).is_settled) &&
          tx.domain === "SHARED";
        if (isSettlement) return null;

        if (tx.is_shared && tx.transaction_splits && tx.transaction_splits.length > 0) {
          const settledByOthers = (tx.transaction_splits as any[])
            .filter(
              (s: any) =>
                s.member_id !== myMemberId &&
                (s.is_settled === true || s.settled_by_debtor === true)
            )
            .reduce((sum: number, s: any) => SafeFinancialCalculator.add(sum, Number(s.amount)), 0);

          const netAmount = Math.max(
            0,
            SafeFinancialCalculator.subtract(Number(tx.amount), settledByOthers)
          );
          return { ...tx, amount: netAmount };
        }

        if (!tx.is_shared && tx.domain === "SHARED" && (tx as any).related_member_id) {
          if ((tx as any).related_member_id !== myMemberId) {
            if ((tx as any).is_settled === true) return { ...tx, amount: 0 };
            return tx;
          }
        }

        return tx;
      })
      .filter(Boolean) as any[];

    // 2. Processar despesas de terceiros onde O USU├üRIO LOGADO J├ü ACERTOU
    const processedOthers: any[] = [];
    sharedTransactions.forEach((tx: any) => {
      const isMeThePayer =
        tx.user_id === user?.id || (tx.payer_id === myMemberId && tx.payer_id != null);
      if (isMeThePayer) return;

      const isSettlement =
        (tx.description?.includes("Acerto") ||
          tx.description?.includes("acerto") ||
          tx.is_settled) &&
        tx.domain === "SHARED";
      if (isSettlement) return;

      if (tx.is_shared && tx.transaction_splits) {
        const mySettledSplit = tx.transaction_splits.find(
          (s: any) =>
            s.member_id === myMemberId && (s.is_settled === true || s.settled_by_debtor === true)
        );
        if (mySettledSplit) {
          processedOthers.push({
            ...tx,
            id: `${tx.id}-injected-settled-split`,
            amount: Number(mySettledSplit.amount),
            user_id: user?.id || tx.user_id,
          });
        }
      }

      if (!tx.is_shared && tx.domain === "SHARED" && tx.related_member_id === myMemberId) {
        if ((tx as any).is_settled === true) {
          processedOthers.push({
            ...tx,
            id: `${tx.id}-injected-direct-settled`,
            amount: Number(tx.amount),
            user_id: user?.id || tx.user_id,
          });
        }
      }
    });

    return [...processedOwn, ...processedOthers];
  }, [allTransactions, sharedTransactions, myMemberId, user?.id]);

  const periodTransactions = useMemo(() => {
    return allCombinedTransactions.filter((tx: any) => {
      const creditCardIds = accounts.filter((a) => a.type === "CREDIT_CARD").map((a) => a.id);
      const isCreditCard = tx.account_id && creditCardIds.includes(tx.account_id);

      const txDateStr = isCreditCard && tx.competence_date ? tx.competence_date : tx.date;
      if (!txDateStr) return false;
      const parts = txDateStr.split("-");
      if (parts.length < 2) return false;
      const txYear = parseInt(parts[0], 10);
      const txMonth = parseInt(parts[1], 10) - 1;

      const targetYear = safeCurrentDate.getFullYear();
      const targetMonth = safeCurrentDate.getMonth();

      const isInPeriod =
        viewType === "MONTH"
          ? txYear === targetYear && txMonth === targetMonth
          : txYear === targetYear;

      if (!isInPeriod) return false;
      const txCurr = getTransactionCurrency(tx);
      const matchesCurrency = selectedCurrency === "ALL" || txCurr === selectedCurrency;

      return matchesCurrency;
    });
  }, [allCombinedTransactions, safeCurrentDate, selectedCurrency, viewType, accounts]);

  const sharedPeriodTransactions = useMemo(() => {
    const targetYear = safeCurrentDate.getFullYear();
    const targetMonth = safeCurrentDate.getMonth();

    return sharedTransactions.filter((tx: any) => {
      const creditCardIds = accounts.filter((a) => a.type === "CREDIT_CARD").map((a) => a.id);
      const isCreditCard = tx.account_id && creditCardIds.includes(tx.account_id);

      const txDateStr = isCreditCard && tx.competence_date ? tx.competence_date : tx.date;
      if (!txDateStr) return false;
      const parts = txDateStr.split("-");
      if (parts.length < 2) return false;
      const txYear = parseInt(parts[0], 10);
      const txMonth = parseInt(parts[1], 10) - 1;

      const isInPeriod =
        viewType === "MONTH"
          ? txYear === targetYear && txMonth === targetMonth
          : txYear === targetYear;

      if (!isInPeriod) return false;
      const txCurr = getTransactionCurrency(tx);
      return selectedCurrency === "ALL" || txCurr === selectedCurrency;
    });
  }, [sharedTransactions, safeCurrentDate, selectedCurrency, viewType, accounts]);

  const { totalIncome, totalExpense, balance } = useMemo(() => {
    const income = periodTransactions
      .filter((t) => t.type === "INCOME" && !(t as any).is_refund)
      .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
    const rawExpense = periodTransactions
      .filter((t) => t.type === "EXPENSE")
      .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
    const refunds = periodTransactions
      .filter((t) => t.type === "INCOME" && (t as any).is_refund)
      .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
    const netExpense = Math.max(0, rawExpense - refunds);
    return {
      totalIncome: income,
      totalExpense: netExpense,
      balance: income - netExpense,
    };
  }, [periodTransactions]);

  const categoryData = useMemo(() => {
    const map: Record<string, { value: number; count: number }> = {};
    const expenses = periodTransactions.filter((t) => t.type === "EXPENSE");

    expenses.forEach((tx) => {
      let categoryName = "Sem categoria";

      if (
        tx.category &&
        tx.category.id &&
        tx.category.name &&
        tx.category.name !== "null" &&
        tx.category.name !== "undefined"
      ) {
        const catId = tx.category.id;
        const catInfo = categories.find((c) => c.id === catId);

        if (catInfo) {
          if (catInfo.parent_category_id) {
            const parentCat = categories.find((c) => c.id === catInfo.parent_category_id);
            if (parentCat) {
              categoryName =
                `${parentCat.icon || "­ƒÅÀ´©Å"} ${parentCat.name} ÔÇ║ ${catInfo.icon || "­ƒÅÀ´©Å"} ${catInfo.name}`.trim();
            } else {
              categoryName = `${catInfo.icon || "­ƒÅÀ´©Å"} ${catInfo.name}`.trim();
            }
          } else {
            categoryName = `${catInfo.icon || "­ƒÅÀ´©Å"} ${catInfo.name}`.trim();
          }
        } else {
          categoryName = tx.category.icon
            ? `${tx.category.icon} ${tx.category.name}`
            : tx.category.name;
        }
      }

      if (
        !categoryName ||
        categoryName.trim() === "" ||
        categoryName === "null" ||
        categoryName === "undefined"
      ) {
        categoryName = "Sem categoria";
      }

      let finalAmount = Number(tx.amount || 0);
      if (tx.transaction_splits && Array.isArray(tx.transaction_splits)) {
        tx.transaction_splits.forEach((split: any) => {
          if (split.is_settled) {
            finalAmount = SafeFinancialCalculator.subtract(finalAmount, Number(split.amount || 0));
          }
        });
      }

      if (finalAmount > 0) {
        if (!map[categoryName]) map[categoryName] = { value: 0, count: 0 };
        map[categoryName].value = SafeFinancialCalculator.add(map[categoryName].value, finalAmount);
        map[categoryName].count += 1;
      }
    });
    const total = Object.values(map).reduce((sum, c) => SafeFinancialCalculator.add(sum, c.value), 0);
    return Object.entries(map)
      .map(([category, d]) => ({
        category,
        value: d.value,
        count: d.count,
        percent: total > 0 ? Math.round((d.value / total) * 100) : 0,
      }))
      .sort((a, b) => b.value - a.value);
  }, [periodTransactions, categories]);

  const personData = useMemo(() => {
    const map: Record<string, any> = {};

    familyMembers.forEach((m) => {
      map[m.name] = { name: m.name, spent: 0, received: 0, balance: 0, count: 0 };
    });

    sharedPeriodTransactions.forEach((tx: any) => {
      if (tx.is_shared && tx.transaction_splits) {
        const involvedMembers = new Set<string>();

        let payerName = "Desconhecido";
        if (tx.payer_id) {
          const payerMember = familyMembers.find(
            (m) => m.id === tx.payer_id || m.linked_user_id === tx.payer_id
          );
          if (payerMember) payerName = payerMember.name;
        }
        if (payerName === "Desconhecido") {
          const creatorMember = familyMembers.find((m) => m.linked_user_id === tx.user_id);
          if (creatorMember) payerName = creatorMember.name;
        }

        if (!map[payerName]) {
          map[payerName] = { name: payerName, spent: 0, received: 0, balance: 0, count: 0 };
        }
        map[payerName].spent = SafeFinancialCalculator.add(map[payerName].spent, Number(tx.amount));
        involvedMembers.add(payerName);

        tx.transaction_splits.forEach((split: any) => {
          const member = familyMembers.find(
            (m) => m.id === split.member_id || m.linked_user_id === split.member_id
          );
          const name = member?.name || split.name || "Desconhecido";

          if (!map[name]) {
            map[name] = { name, spent: 0, received: 0, balance: 0, count: 0 };
          }
          map[name].received = SafeFinancialCalculator.add(
            map[name].received,
            Number(split.amount)
          );
          involvedMembers.add(name);
        });

        involvedMembers.forEach((name) => {
          map[name].count += 1;
        });
      }
      else if (!tx.is_shared && tx.domain === "SHARED" && tx.related_member_id) {
        const creatorMember = familyMembers.find((m) => m.linked_user_id === tx.user_id);
        const receiverMember = familyMembers.find((m) => m.id === tx.related_member_id);

        const payerName = creatorMember?.name || "Desconhecido";
        const receiverName = receiverMember?.name || "Desconhecido";

        if (!map[payerName])
          map[payerName] = { name: payerName, spent: 0, received: 0, balance: 0, count: 0 };
        if (!map[receiverName])
          map[receiverName] = { name: receiverName, spent: 0, received: 0, balance: 0, count: 0 };

        map[payerName].spent = SafeFinancialCalculator.add(map[payerName].spent, Number(tx.amount));
        map[receiverName].received = SafeFinancialCalculator.add(
          map[receiverName].received,
          Number(tx.amount)
        );

        map[payerName].count += 1;
        if (payerName !== receiverName) {
          map[receiverName].count += 1;
        }
      }
      else if (
        !tx.is_shared &&
        tx.domain === "SHARED" &&
        (tx.description?.includes("Acerto") || tx.description?.includes("acerto") || tx.is_settled)
      ) {
        const creatorMember = familyMembers.find((m) => m.linked_user_id === tx.user_id);
        const otherMember = familyMembers.find((m) => m.linked_user_id !== tx.user_id);

        if (creatorMember && otherMember) {
          const payerName = tx.type === "EXPENSE" ? creatorMember.name : otherMember.name;
          const receiverName = tx.type === "EXPENSE" ? otherMember.name : creatorMember.name;

          if (!map[payerName])
            map[payerName] = { name: payerName, spent: 0, received: 0, balance: 0, count: 0 };
          if (!map[receiverName])
            map[receiverName] = { name: receiverName, spent: 0, received: 0, balance: 0, count: 0 };

          map[payerName].spent = SafeFinancialCalculator.add(
            map[payerName].spent,
            Number(tx.amount)
          );
          map[receiverName].received = SafeFinancialCalculator.add(
            map[receiverName].received,
            Number(tx.amount)
          );

          map[payerName].count += 1;
          map[receiverName].count += 1;
        }
      }
    });

    return Object.values(map)
      .map((p) => ({ ...p, balance: moneyUtils.round(p.spent - p.received) }))
      .sort((a, b) => b.spent - a.spent);
  }, [sharedPeriodTransactions, familyMembers]);

  const installmentsByPerson = useMemo(() => {
    const map: Record<string, any> = {};
    const targetYear = safeCurrentDate.getFullYear();
    const targetMonth = safeCurrentDate.getMonth();

    sharedTransactions
      .filter(
        (tx: any) =>
          tx.is_installment &&
          tx.series_id &&
          (selectedCurrency === "ALL" || getTransactionCurrency(tx) === selectedCurrency)
      )
      .forEach((tx: any) => {
        const creditCardIds = accounts.filter((a) => a.type === "CREDIT_CARD").map((a) => a.id);
        const isCreditCard = tx.account_id && creditCardIds.includes(tx.account_id);
        const txDateStr = isCreditCard && tx.competence_date ? tx.competence_date : tx.date;

        if (!txDateStr) return;
        const parts = txDateStr.split("-");
        if (parts.length < 2) return;
        const txYear = parseInt(parts[0], 10);
        const txMonth = parseInt(parts[1], 10) - 1;

        const isInPeriod =
          viewType === "MONTH"
            ? txYear === targetYear && txMonth === targetMonth
            : txYear === targetYear;

        if (tx.is_shared && tx.transaction_splits) {
          (tx as any).transaction_splits.forEach((split: any) => {
            const member = familyMembers.find(
              (m) => m.id === split.member_id || m.linked_user_id === split.member_id
            );
            const name = member?.name || split.name || "Desconhecido";
            if (!map[name])
              map[name] = {
                name,
                periodAmount: 0,
                totalAmount: 0,
                remainingAmount: 0,
                totalInstallments: 0,
                remainingInstallments: 0,
                series: new Set(),
              };

            map[name].series.add(tx.series_id!);
            const amt = Number(split.amount);

            map[name].totalAmount = SafeFinancialCalculator.add(map[name].totalAmount, amt);

            if (isInPeriod) {
              map[name].periodAmount = SafeFinancialCalculator.add(map[name].periodAmount, amt);
            }

            const isRemaining = !split.is_settled;
            if (isRemaining) {
              map[name].remainingAmount = SafeFinancialCalculator.add(
                map[name].remainingAmount,
                amt
              );
              map[name].remainingInstallments += 1;
            }
            map[name].totalInstallments += 1;
          });
        }
        else if (!tx.is_shared && tx.domain === "SHARED" && tx.related_member_id) {
          const member = familyMembers.find((m) => m.id === tx.related_member_id);
          const name = member?.name || "Desconhecido";
          if (!map[name])
            map[name] = {
              name,
              periodAmount: 0,
              totalAmount: 0,
              remainingAmount: 0,
              totalInstallments: 0,
              remainingInstallments: 0,
              series: new Set(),
            };

          map[name].series.add(tx.series_id!);
          const amt = Number(tx.amount);

          map[name].totalAmount = SafeFinancialCalculator.add(map[name].totalAmount, amt);

          if (isInPeriod) {
            map[name].periodAmount = SafeFinancialCalculator.add(map[name].periodAmount, amt);
          }

          const isRemaining = !tx.is_settled;
          if (isRemaining) {
            map[name].remainingAmount = SafeFinancialCalculator.add(map[name].remainingAmount, amt);
            map[name].remainingInstallments += 1;
          }
          map[name].totalInstallments += 1;
        }
      });
    return Object.values(map)
      .map((p) => ({ ...p, seriesCount: p.series.size }))
      .sort((a, b) => b.periodAmount - a.periodAmount);
  }, [sharedTransactions, familyMembers, safeCurrentDate, viewType, selectedCurrency, accounts]);

  const largestExpense = useMemo(() => {
    const expenses = periodTransactions.filter((t) => t.type === "EXPENSE");
    if (expenses.length === 0) return null;
    return expenses.reduce(
      (max, t) => (Number(t.amount) > Number(max.amount) ? t : max),
      expenses[0]
    );
  }, [periodTransactions]);

  const dailyAverageExpense = useMemo(() => {
    if (totalExpense <= 0) return 0;
    const isYearly = viewType === "YEAR";
    const days = isYearly ? 365 : dateFns.getDaysInMonth(safeCurrentDate);
    return moneyUtils.round(totalExpense / days);
  }, [totalExpense, viewType, safeCurrentDate]);

  const topCategory = useMemo(() => {
    if (categoryData.length === 0) return null;
    return categoryData[0];
  }, [categoryData]);

  const savingsGoalStatus = useMemo(() => {
    const rate = totalIncome > 0 ? (balance / totalIncome) * 100 : 0;
    if (rate >= 20)
      return {
        text: "Excelente! (Economizou > 20%)",
        color: "text-success bg-success/12 border-success/20",
      };
    if (rate >= 10)
      return {
        text: "No caminho! (Economizou > 10%)",
        color: "text-accent bg-accent/10 border-accent/20",
      };
    if (rate > 0)
      return {
        text: "Bom, mas tente poupar 10%",
        color: "text-warning bg-warning/12 border-warning/20",
      };
    return {
      text: "Alerta: Gastos superaram receitas",
      color: "text-destructive bg-destructive/12 border-destructive/20",
    };
  }, [totalIncome, balance]);

  const filteredTxList = useMemo(() => {
    return periodTransactions.filter((tx) => {
      const matchesSearch =
        txSearch.trim() === "" ||
        tx.description?.toLowerCase().includes(txSearch.toLowerCase()) ||
        tx.category?.name?.toLowerCase().includes(txSearch.toLowerCase());

      const matchesType = txTypeFilter === "ALL" || tx.type === txTypeFilter;

      return matchesSearch && matchesType;
    });
  }, [periodTransactions, txSearch, txTypeFilter]);

  const monthlyData = useMemo(() => {
    const months = [];
    for (let i = 5; i >= 0; i--) {
      const monthDate = dateFns.subMonths(safeCurrentDate, i);
      const year = monthDate.getFullYear();
      const month = monthDate.getMonth();

      const monthTxs = allCombinedTransactions.filter((tx) => {
        const creditCardIds = accounts.filter((a) => a.type === "CREDIT_CARD").map((a) => a.id);
        const isCreditCard = tx.account_id && creditCardIds.includes(tx.account_id);
        const txDateStr = isCreditCard && tx.competence_date ? tx.competence_date : tx.date;

        if (!txDateStr) return false;
        const parts = txDateStr.split("-");
        if (parts.length < 2) return false;
        const txYear = parseInt(parts[0], 10);
        const txMonth = parseInt(parts[1], 10) - 1;
        if (txYear !== year || txMonth !== month) return false;
        const txCurr = getTransactionCurrency(tx);
        return selectedCurrency === "ALL" || txCurr === selectedCurrency;
      });

      const income = monthTxs
        .filter((t) => t.type === "INCOME" && !(t as any).is_refund)
        .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
      const rawExpense = monthTxs
        .filter((t) => t.type === "EXPENSE")
        .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
      const refunds = monthTxs
        .filter((t) => t.type === "INCOME" && (t as any).is_refund)
        .reduce((sum, t) => SafeFinancialCalculator.add(sum, Number(t.amount)), 0);
      const netExpense = moneyUtils.round(Math.max(0, rawExpense - refunds));

      months.push({
        month: dateFns.format(monthDate, "MMM", { locale: ptBR }),
        income: moneyUtils.round(income),
        expense: netExpense,
        month_start: dateFns.format(monthDate, "yyyy-MM-01"),
      });
    }
    return months;
  }, [allCombinedTransactions, safeCurrentDate, selectedCurrency, accounts]);

  return {
    availableCurrencies,
    allCombinedTransactions,
    periodTransactions,
    sharedPeriodTransactions,
    totalIncome,
    totalExpense,
    balance,
    categoryData,
    personData,
    installmentsByPerson,
    largestExpense,
    dailyAverageExpense,
    topCategory,
    savingsGoalStatus,
    filteredTxList,
    monthlyData,
  };
}

import { useMemo } from "react";
import { InvoiceItem } from "@/utils/sharedFinanceCalculations";

interface UseSharedExpensesTotalsProps {
  members: any[];
  invoices: Record<string, InvoiceItem[]>;
  currentDate: Date;
}

export function useSharedExpensesTotals({
  members,
  invoices,
  currentDate,
}: UseSharedExpensesTotalsProps) {
  const { totalsByCurrency, travelTotalsByCurrency } = useMemo(() => {
    const totalsByCurrency: Record<string, any> = {};
    const travelTotalsByCurrency: Record<string, any> = {};

    members.forEach((m) => {
      const allItems = invoices[m.id] || [];

      let scopeFilteredItems = allItems;
      if (m.sharing_scope !== "all") {
        scopeFilteredItems = allItems.filter((item) => {
          switch (m.sharing_scope) {
            case "trips_only":
              return !!item.tripId;
            case "date_range": {
              if (!m.scope_start_date && !m.scope_end_date) return true;
              if (!item.date) return false;
              const itemDate = new Date(item.date);
              const startDate = m.scope_start_date ? new Date(m.scope_start_date) : null;
              const endDate = m.scope_end_date ? new Date(m.scope_end_date) : null;
              if (startDate && itemDate < startDate) return false;
              if (endDate && itemDate > endDate) return false;
              return true;
            }
            case "specific_trip":
              return item.tripId === m.scope_trip_id;
            default:
              return true;
          }
        });
      }

      scopeFilteredItems.forEach((item) => {
        const cur = item.currency || "BRL";

        if (item.tripId) {
          if (!travelTotalsByCurrency[cur]) {
            travelTotalsByCurrency[cur] = { owedToMe: 0, iOwe: 0, balance: 0, settled: 0 };
          }

          if (item.isPaid) {
            travelTotalsByCurrency[cur].settled += item.amount;
          } else if (item.type === "CREDIT") {
            travelTotalsByCurrency[cur].owedToMe += item.amount;
          } else {
            travelTotalsByCurrency[cur].iOwe += item.amount;
          }
        } else {
          if (!item.date) return;
          const [year, month] = item.date.split("-").map(Number);
          const itemDateObj = new Date(year, month - 1, 1);
          const currentViewDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);

          if (item.isPaid) {
            const isCurrentMonth =
              year === currentDate.getFullYear() && month - 1 === currentDate.getMonth();
            if (isCurrentMonth) {
              if (!totalsByCurrency[cur]) {
                totalsByCurrency[cur] = { owedToMe: 0, iOwe: 0, balance: 0, settled: 0 };
              }
              totalsByCurrency[cur].settled += item.amount;
            }
          } else {
            if (itemDateObj <= currentViewDate) {
              if (!totalsByCurrency[cur]) {
                totalsByCurrency[cur] = { owedToMe: 0, iOwe: 0, balance: 0, settled: 0 };
              }
              if (item.type === "CREDIT") {
                totalsByCurrency[cur].owedToMe += item.amount;
              } else {
                totalsByCurrency[cur].iOwe += item.amount;
              }
            }
          }
        }
      });
    });

    Object.values(totalsByCurrency).forEach((t) => (t.balance = t.owedToMe - t.iOwe));
    Object.values(travelTotalsByCurrency).forEach((t) => (t.balance = t.owedToMe - t.iOwe));

    return { totalsByCurrency, travelTotalsByCurrency };
  }, [members, invoices, currentDate]);

  return {
    totalsByCurrency,
    travelTotalsByCurrency,
  };
}

import { moneyUtils } from "@/utils/money";
import { Decimal } from "decimal.js";
import { logger } from "@/utils/logger";

/**
 * SafeFinancialCalculator
 * Provides safe financial calculations avoiding floating point errors using decimal.js
 * All methods return Decimal for precision. Convert to number only at display time with .toNumber().
 */

export class SafeFinancialCalculator {
  static readonly PRECISION = 2;
  static readonly MULTIPLIER = new Decimal(Math.pow(10, SafeFinancialCalculator.PRECISION));
  /** Zero constante para compara├º├Áes */
  static readonly ZERO = new Decimal(0);

  /**
   * Helper safely converts any value to Decimal
   */
  static toDecimal(val: any, defaultValue: Decimal = SafeFinancialCalculator.ZERO): Decimal {
    if (val === null || val === undefined) return defaultValue;
    if (val instanceof Decimal) return val;
    if (typeof val === "number" && isNaN(val)) return defaultValue;
    if (typeof val === "string") {
      const stripped = val.replace(/[^0-9.-]+/g, "");
      if (!stripped || isNaN(parseFloat(stripped))) return defaultValue;
      const parsed = moneyUtils.parse(val);
      if (isNaN(parsed)) return defaultValue;
      return new Decimal(parsed);
    }
    try {
      return new Decimal(val);
    } catch {
      return defaultValue;
    }
  }

  /**
   * Convert to safe integer representation (cents)
   */
  static toSafeNumber(value: number | string, defaultValue: number = 0): number {
    if (value === null || value === undefined) return defaultValue;
    if (typeof value === "number" && isNaN(value)) return defaultValue;
    if (typeof value === "string") {
      const stripped = value.replace(/[^0-9.-]+/g, "");
      if (!stripped || isNaN(parseFloat(stripped))) return defaultValue;
    }

    try {
      let num: number;
      if (typeof value === "string") {
        num = moneyUtils.parse(value);
        if (isNaN(num)) return defaultValue;
      } else {
        num = Number(value);
      }
      return new Decimal(num)
        .times(SafeFinancialCalculator.MULTIPLIER)
        .toDecimalPlaces(0, Decimal.ROUND_HALF_UP)
        .toNumber();
    } catch {
      return defaultValue;
    }
  }

  /**
   * Convert from safe integer back to decimal string
   */
  static fromSafeNumber(value: number): Decimal {
    return SafeFinancialCalculator.toDecimal(value).dividedBy(SafeFinancialCalculator.MULTIPLIER);
  }

  /**
   * Safe addition ÔÇö returns Decimal
   */
  static add(a: number | Decimal, b: number | Decimal): Decimal {
    const decA = SafeFinancialCalculator.toDecimal(a).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
    const decB = SafeFinancialCalculator.toDecimal(b).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
    return decA.plus(decB);
  }

  /**
   * Safe subtraction ÔÇö returns Decimal
   */
  static subtract(a: number | Decimal, b: number | Decimal): Decimal {
    const decA = SafeFinancialCalculator.toDecimal(a).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
    const decB = SafeFinancialCalculator.toDecimal(b).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
    return decA.minus(decB);
  }

  /**
   * Safe multiplication ÔÇö returns Decimal
   */
  static multiply(amount: number | Decimal, factor: number | Decimal): Decimal {
    const decAmount = SafeFinancialCalculator.toDecimal(amount).toDecimalPlaces(
      2,
      Decimal.ROUND_HALF_UP
    );
    const decFactor = SafeFinancialCalculator.toDecimal(factor);
    return decAmount.times(decFactor).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }

  /**
   * Safe division ÔÇö returns Decimal
   */
  static divide(amount: number | Decimal, divisor: number | Decimal): Decimal {
    const decDivisor = SafeFinancialCalculator.toDecimal(divisor);
    if (decDivisor.isZero()) throw new Error("Division by zero");
    const decAmount = SafeFinancialCalculator.toDecimal(amount).toDecimalPlaces(
      2,
      Decimal.ROUND_HALF_UP
    );
    return decAmount.dividedBy(decDivisor).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }

  /**
   * Safe sum of array ÔÇö returns Decimal
   */
  static safeSum(values: (number | Decimal)[]): Decimal {
    const sum = values.reduce(
      (acc, val) => acc.plus(SafeFinancialCalculator.toDecimal(val)),
      new Decimal(0)
    );
    return sum.toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }

  /**
   * Calculate percentage ÔÇö returns Decimal
   */
  static percentage(value: number | Decimal, percent: number | Decimal): Decimal {
    const decValue = SafeFinancialCalculator.toDecimal(value);
    const decPercent = SafeFinancialCalculator.toDecimal(percent).dividedBy(100);
    return decValue.times(decPercent).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }

  /**
   * Round to 2 decimal places ÔÇö returns Decimal
   */
  static round(value: number | Decimal): Decimal {
    return SafeFinancialCalculator.toDecimal(value).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }

  /**
   * Format as currency
   */
  static formatCurrency(value: number | Decimal, currency: string = "BRL"): string {
    const num = value instanceof Decimal ? value.toNumber() : value;
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency: currency,
    }).format(num);
  }

  /**
   * Validate split amounts don't exceed total
   */
  static validateSplits(
    total: number | Decimal,
    splits: Array<{ amount: number | Decimal }>
  ): boolean {
    const splitSum = SafeFinancialCalculator.safeSum(splits.map((s) => s.amount));
    const totalSafe = SafeFinancialCalculator.toSafeNumber(
      total instanceof Decimal ? total.toNumber() : total
    );
    const splitSumSafe = SafeFinancialCalculator.toSafeNumber(splitSum.toNumber());

    return splitSumSafe === totalSafe;
  }

  /**
   * Calculate installment amount ÔÇö returns Decimal
   */
  static calculateInstallment(total: number | Decimal, installments: number): Decimal {
    if (installments <= 0) throw new Error("Invalid number of installments");
    return SafeFinancialCalculator.divide(total, installments);
  }

  /**
   * Distribute amount across splits maintaining total
   */
  static distributeSplits(
    total: number | Decimal,
    splits: Array<{ percentage: number }>
  ): Array<{ percentage: number; amount: Decimal }> {
    const totalPercentage = splits.reduce((sum, s) => sum + s.percentage, 0);

    if (Math.abs(totalPercentage - 100) > 0.01 && totalPercentage !== 0) {
      logger.warn("Split percentages do not sum to 100%");
    }

    const result = splits.map((split) => ({
      percentage: split.percentage,
      amount: SafeFinancialCalculator.percentage(total, split.percentage),
    }));

    // Adjust last split to ensure exact total only if percentages sum to 100%
    const isCloseTo100 = Math.abs(totalPercentage - 100) < 0.01;
    const calculatedSum = SafeFinancialCalculator.safeSum(result.map((r) => r.amount));
    const difference = SafeFinancialCalculator.subtract(total, calculatedSum);

    if (isCloseTo100 && !difference.isZero() && result.length > 0) {
      result[result.length - 1].amount = SafeFinancialCalculator.add(
        result[result.length - 1].amount,
        difference
      );
    }

    return result;
  }

  /**
   * Calculate inflation-adjusted target amount ÔÇö returns Decimal
   * @param targetAmount The original target amount in today's money
   * @param monthsToTarget Number of months until the target date
   * @param annualInflationRate Annual inflation rate in percentage (e.g., 4.72 for 4.72%)
   */
  static calculateInflationAdjustedTarget(
    targetAmount: number | Decimal,
    monthsToTarget: number,
    annualInflationRate: number
  ): Decimal {
    if (monthsToTarget <= 0) return SafeFinancialCalculator.toDecimal(targetAmount);

    const decTarget = SafeFinancialCalculator.toDecimal(targetAmount);
    if (decTarget.isZero() || decTarget.isNegative()) return decTarget;

    // Convert annual rate (e.g., 4.72%) to decimal (0.0472)
    const annualRateDec = SafeFinancialCalculator.toDecimal(annualInflationRate).dividedBy(100);

    const base = annualRateDec.plus(1).toNumber();
    const monthlyRateDecimal = Math.pow(base, 1 / 12) - 1;

    const compoundFactor = Math.pow(1 + monthlyRateDecimal, monthsToTarget);

    return decTarget.times(compoundFactor).toDecimalPlaces(2, Decimal.ROUND_HALF_UP);
  }
}

