                data: competitorPatterns,
                error: null,
              }),
            }),
          }),
        }),
        delete: vi.fn().mockReturnValue({ eq: deleteMock }),
        update: vi.fn().mockReturnValue({ eq: updateMock }),
      } as any);

      await CategoryPredictionService.learnFromUser(
        'Uber Corrida para Casa',
        'cat-transporte',
        'user-123',
        true // Foi corre├º├úo!
      );

      // 'learn-old-1' tinha confian├ºa 0.4. 0.4 - 0.3 = 0.1 <= 0.2, logo deve ser exclu├¡do
      expect(deleteMock).toHaveBeenCalled();
      
      // 'learn-old-2' tinha confian├ºa 0.9. 0.9 - 0.3 = 0.6 > 0.2, logo deve ser atualizado/penalizado
      expect(updateMock).toHaveBeenCalled();
    });
  });
});

import { normalizeBrazilianText } from "@/utils/formatting";
import { logger } from "@/utils/logger";
import {
  getAutocompletePrompt,
  getFinancialAnalysisPrompt,
  getTripChecklistPrompt,
  getTripItineraryPrompt,
} from "./ai/aiPrompts";
import { LOCAL_BRAZILIAN_MAPPINGS, LocalMapping } from "./ai/localMappings";
import { fetchRealPOIs } from "./overpassService";

// In production, all Groq calls are proxied through a Supabase Edge Function
// so the API key never reaches the client bundle.
const GROQ_API_URL = import.meta.env.DEV
  ? "/api/ai"
  : `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/groq-proxy`;

export interface FinancialReportData {
  totalIncome: number;
  totalExpense: number;
  balance: number;
  savingsRate: number;
  currency: string;
  topCategories: { category: string; value: number }[];
  largestExpense: { description: string; amount: number } | null;
  periodLabel: string;
  viewType: "MONTH" | "YEAR";
}

export class AIAdvisorService {
  private static async fetchGroq(payload: any): Promise<any> {
    const isDev = import.meta.env.DEV;

    // In dev, use the local proxy (vite config) with optional direct key fallback.
    // In production, always route through the Supabase Edge Function ÔÇö no client key.
    const headers: Record<string, string> = { "Content-Type": "application/json" };

    if (!isDev) {
      // Attach the anon key so the Edge Function can authenticate the caller
      const anonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
      if (anonKey) headers["apikey"] = anonKey;

      // Also forward the user's auth token so the function can verify identity
      const { supabase } = await import("@/integrations/supabase/client");
      const {
        data: { session },
      } = await supabase.auth.getSession();
      if (session?.access_token) {
        headers["Authorization"] = `Bearer ${session.access_token}`;
      }
    }

    try {
      const response = await fetch(GROQ_API_URL, {
        method: "POST",
        headers,
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        return await response.json();
      } else {
        throw new Error(`Status ${response.status}`);
      }
    } catch (error) {
      logger.warn(`[AIAdvisorService] Erro ao chamar ${GROQ_API_URL}`, error);

      // Dev-only: fallback via Vite proxy (the proxy reads VITE_GROQ_API_KEY server-side).
      // In production, the edge function handles everything; no client key is ever used.
      if (isDev) {
        try {
          logger.debug("[AIAdvisorService] Tentando fallback via proxy local (dev)...");
          const fallbackResponse = await fetch("/api/ai", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          if (fallbackResponse.ok) return await fallbackResponse.json();
        } catch (fallbackError) {
          logger.error(
            "[AIAdvisorService] Erro no fallback dev",
            fallbackError instanceof Error ? fallbackError : undefined
          );
        }
      }
      return null;
    }
  }

  /**
   * Pede para a IA gerar uma an├ílise financeira baseada no hist├│rico mensal ou anual.
   */
  static async analyzeFinancialPeriod(data: FinancialReportData): Promise<string> {
    const prompt = getFinancialAnalysisPrompt(data);

    const result = await this.fetchGroq({
      model: "llama-3.3-70b-versatile",
      messages: [{ role: "system", content: prompt }],
      temperature: 0.5,
      max_tokens: 600,
    });

    if (result && result.choices && result.choices[0]) {
      return (
        result.choices[0].message.content || "Desculpe, n├úo consegui formular um conselho agora."
      );
    }

    throw new Error("Falha ao se comunicar com a Intelig├¬ncia Artificial.");
  }

  /**
   * Pede para a IA prever o resto da palavra que o usu├írio est├í digitando e categoriz├í-la.
   */
  static async predictAutocompleteAndCategory(
    partialDescription: string,
    historicalDescriptions: string[],
    userCategories: { id: string; name: string }[],
    transactionType?: "expense" | "income",
    historicalPairs?: { description: string; categoryName: string }[]
  ): Promise<{ suggestion: string; categoryId: string | null }> {
    const sanitizedPartial = (partialDescription || "").trim().substring(0, 80);
    if (sanitizedPartial.length < 2) {
      return { suggestion: "", categoryId: null };
    }

    // --- ÔÜí MOTOR H├ìBRIDO DETERMIN├ìSTICO BRASILEIRO ---
    const normalizedInput = normalizeBrazilianText(sanitizedPartial);

    // 1. Identifica se a lista de categorias fornecida ├® de receita ou despesa
    let targetType: "receita" | "despesa";
    if (transactionType) {
      targetType = transactionType === "income" ? "receita" : "despesa";
    } else {
      const isReceitaList = userCategories.some((uc) => {
        const name = normalizeBrazilianText(uc.name);
        return (
          name.includes("salario") ||
          name.includes("freelance") ||
          name.includes("investimento") ||
          name.includes("renda") ||
          name.includes("receita") ||
          name.includes("transferencia recebida")
        );
      });
      targetType = isReceitaList ? "receita" : "despesa";
    }

    // 2. Motor de busca local em 3 Fases
    let bestMatch: LocalMapping | null = null;

    // --- FASE 1: MATCH 100% EXATO ---
    // Se o usu├írio digitou exatamente uma keyword conhecida (evita concorr├¬ncia e falsos positivos de substrings)
    for (const mapping of LOCAL_BRAZILIAN_MAPPINGS) {
      if (mapping.type !== targetType) continue;

      for (const keyword of mapping.keywords) {
        const normalizedKeyword = normalizeBrazilianText(keyword);
        if (normalizedInput === normalizedKeyword) {
          bestMatch = mapping;
          break;
        }
      }
      if (bestMatch) break;
    }

    // --- FASE 2: CASAMENTO DE PALAVRA COMPLETA (EXATA) ---
    // Se n├úo achou match exato, verifica se a entrada ├® uma palavra inteira contida na keyword ou vice-versa (limite de palavra exato)
    if (!bestMatch) {
      for (const mapping of LOCAL_BRAZILIAN_MAPPINGS) {
        if (mapping.type !== targetType) continue;

        for (const keyword of mapping.keywords) {
          const normalizedKeyword = normalizeBrazilianText(keyword);

          const inputContainsKeyword = new RegExp(`\\b${normalizedKeyword}\\b`).test(
            normalizedInput
          );
          const keywordContainsInput = new RegExp(`\\b${normalizedInput}\\b`).test(
            normalizedKeyword
          );

          if (inputContainsKeyword || keywordContainsInput) {
            // Em caso de matches parciais por palavra, preferimos o termo mais curto para evitar alucina├º├Áes
            if (
              !bestMatch ||
              normalizedKeyword.length < normalizeBrazilianText(bestMatch.keywords[0]).length
            ) {
              bestMatch = mapping;
            }
          }
        }
      }
    }

    // --- FASE 3: AUTOCOMPLETE PARCIAL (PREFIXO) ---
    // Se o usu├írio est├í no in├¡cio da digita├º├úo (ex: "pa" ou "ub")
    if (!bestMatch && normalizedInput.length >= 2) {
      let shortestKeywordLength = Infinity;

      for (const mapping of LOCAL_BRAZILIAN_MAPPINGS) {
        if (mapping.type !== targetType) continue;

        for (const keyword of mapping.keywords) {
          const normalizedKeyword = normalizeBrazilianText(keyword);

          if (normalizedKeyword.startsWith(normalizedInput)) {
            // Damos prefer├¬ncia para a palavra mais curta (evita sugerir pao de queijo ao digitar apenas pao)
            if (normalizedKeyword.length < shortestKeywordLength) {
              shortestKeywordLength = normalizedKeyword.length;
              bestMatch = mapping;
            }
          }
        }
      }
    }

    if (bestMatch) {
      // Cruzamento local com o ID real da categoria cadastrada no banco do usu├írio
      const searchCat = bestMatch.categoryMatch;
      const matchedUserCategory = userCategories.find((uc) => {
        const normUserCatName = normalizeBrazilianText(uc.name);
        return (
          normUserCatName === searchCat ||
          normUserCatName.includes(searchCat) ||
          searchCat.includes(normUserCatName)
        );
      });

      if (matchedUserCategory) {
        logger.debug(`[AIAdvisorService] Match local encontrado para "${sanitizedPartial}"`, {
          suggestion: bestMatch.suggestion,
          categoryName: matchedUserCategory.name,
        });
        return {
          suggestion: bestMatch.suggestion,
          categoryId: matchedUserCategory.id,
        };
      }
    }
    // --- ÔÜí FIM DO MOTOR H├ìBRIDO ---

    // 1. Truncamento rigoroso contra payloads abusivos ou anomalias (ex: base64, anexos)
    const uniqueHistory = Array.from(
      new Set(
        (historicalDescriptions || [])
          .map((d) => (d || "").trim().substring(0, 50))
          .filter((d) => d.length >= 2 && !d.startsWith("data:") && !d.includes(";base64"))
      )
    ).slice(0, 25); // Reduzimos para 25 itens para garantir seguran├ºa m├íxima de token e payload

    const sanitizedCategories = (userCategories || []).map((c) => ({
      id: c.id,
      name: (c.name || "").trim().substring(0, 40),
    }));

    const categoryList = sanitizedCategories
      .map((c) => `- Categoria: "${c.name}", ID: "${c.id}"`)
      .join("\n");

    // Exemplos de classifica├º├Áes j├í feitas pelo usu├írio (aprendizado pessoal)
    const userExamples = (historicalPairs || [])
      .slice(0, 20)
      .map((p) => `"${p.description}" ÔåÆ ${p.categoryName}`)
      .join("\n");

    const prompt = getAutocompletePrompt(
      sanitizedPartial,
      uniqueHistory,
      categoryList,
      userExamples
    );
    const result = await this.fetchGroq({
      model: "llama-3.3-70b-versatile",
      messages: [{ role: "system", content: prompt }],
      temperature: 0.5,
      max_tokens: 300,
      response_format: { type: "json_object" },
    });

    if (result && result.choices && result.choices[0]) {
      try {
        const parsed = JSON.parse(result.choices[0].message.content);
        return {
          suggestion: parsed.suggestion || "",
          categoryId: parsed.categoryId || null,
        };
      } catch (e) {
        return { suggestion: "", categoryId: null };
      }
    }

    return { suggestion: "", categoryId: null };
  }

  /**
   * Busca lugares reais via Google Places (Edge Function no Supabase)
   */
  private static async fetchPlacesSuggestions(destination: string): Promise<
    Array<{
      title: string;
      location: string;
      description: string;
      durationHours: number;
      mapsUrl?: string;
      rating?: number;
      placeId?: string;
    }>
  > {
    const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
    const supabaseAnonKey = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
    if (!supabaseUrl || !supabaseAnonKey) return [];

    const response = await fetch(`${supabaseUrl}/functions/v1/get-place-suggestions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${supabaseAnonKey}`,
      },
      body: JSON.stringify({ destination }),
    });

    if (!response.ok) return [];

    const data = await response.json();
    return (data.suggestions || []).map((s: any) => ({
      title: s.title,
      location: s.location,
      description: s.description,
      durationHours: s.durationHours || 2,
      mapsUrl: s.mapsUrl || "",
      rating: s.rating,
      placeId: s.placeId,
    }));
  }

  static async suggestTripItinerary(destination: string): Promise<
    Array<{
      title: string;
      location: string;
      description: string;
      durationHours: number;
      mapsUrl?: string;
      rating?: number;
      placeId?: string;
    }>
  > {
    if (!destination) return [];

    // 1. Try Overpass API (real OSM data, free, no key needed)
    try {
      const pois = await fetchRealPOIs(destination, 10);
      if (pois.length >= 3) {
        return pois.map((poi) => ({
          title: poi.title,
          location: poi.location,
          description: poi.description,
          durationHours: poi.durationHours,
          mapsUrl: poi.mapsUrl,
        }));
      }
    } catch (e) {
      logger.warn("[AIAdvisorService] Overpass falhou, tentando Google Places", e);
    }

    // 2. Fallback: Google Places via Supabase Edge Function
    try {
      const placesResult = await this.fetchPlacesSuggestions(destination);
      if (placesResult.length > 0) return placesResult;
    } catch (e) {
      logger.warn("[AIAdvisorService] Google Places falhou, usando IA como fallback", e);
    }

    // 3. Last resort: AI-generated (may invent locations)
    const prompt = getTripItineraryPrompt(destination);
    const result = await this.fetchGroq({
      model: "llama-3.3-70b-versatile",
      messages: [{ role: "system", content: prompt }],
      temperature: 0.4,
      max_tokens: 600,
      response_format: { type: "json_object" },
    });

    if (result && result.choices && result.choices[0]) {
      try {
        const parsed = JSON.parse(result.choices[0].message.content);
        return parsed.suggestions || [];
      } catch (e) {
        return [];
      }
    }

    return [];
  }

  static async suggestTripChecklist(
    destination: string,
    startDate?: string,
    endDate?: string
  ): Promise<Array<{ item: string; category: string }>> {
    if (!destination) return [];

    const prompt = getTripChecklistPrompt(destination, startDate, endDate);

    const result = await this.fetchGroq({
      model: "llama-3.3-70b-versatile",
      messages: [{ role: "system", content: prompt }],
      temperature: 0.3,
      max_tokens: 400,
      response_format: { type: "json_object" },
    });

    if (result && result.choices && result.choices[0]) {
      try {
        const parsed = JSON.parse(result.choices[0].message.content);
        return parsed.suggestions || [];
      } catch (e) {
        return [];
      }
    }

    return [];
  }
}

import { supabase } from '@/integrations/supabase/client';
import { DEFAULT_KEYWORDS, CONCEPT_SYNONYMS, CONCEPT_EMOJIS } from '@/lib/categoryKeywords';
import type { CategoryPrediction } from '@/types/categoryPrediction';
import { logger } from '@/utils/logger';

export class CategoryPredictionService {
  
  /**
   * Calcula a dist├óncia de Levenshtein entre duas strings para tolerar erros de digita├º├úo (Fuzzy Matching)
   */
  private static levenshteinDistance(a: string, b: string): number {
    const matrix: number[][] = [];

    // Incrementar ao longo do primeiro par├ómetro
    for (let i = 0; i <= b.length; i++) {
      matrix[i] = [i];
    }

    // Incrementar ao longo do segundo par├ómetro
    for (let j = 0; j <= a.length; j++) {
      matrix[0][j] = j;
    }

    // Preencher a matriz
    for (let i = 1; i <= b.length; i++) {
      for (let j = 1; j <= a.length; j++) {
        if (b.charAt(i - 1) === a.charAt(j - 1)) {
          matrix[i][j] = matrix[i - 1][j - 1];
        } else {
          matrix[i][j] = Math.min(
            matrix[i - 1][j - 1] + 1, // substitui├º├úo
            Math.min(
              matrix[i][j - 1] + 1, // inser├º├úo
              matrix[i - 1][j] + 1  // dele├º├úo
            )
          );
        }
      }
    }

    return matrix[b.length][a.length];
  }

  /**
   * Higieniza e extrai o padr├úo de descri├º├úo removendo ru├¡dos e lixos transacionais
   */
  public static extractCleanPattern(description: string): string {
    if (!description) return '';
    
    let clean = description.toLowerCase().trim();
    
    // 1. Remover datas nos formatos DD/MM, DD/MM/AAAA, DD-MM-AAAA, DD.MM, etc.
    clean = clean.replace(/\b\d{1,2}[\/\-\.]\d{1,2}([\/\-\.]\d{2,4})?\b/g, '');
    
    // 2. Remover hor├írios nos formatos HH:MM, HHhMM, etc.
    clean = clean.replace(/\b\d{1,2}[h\:]\d{2}\b/g, '');
    
    // 3. Remover sufixos/prefixos transacionais comuns de cart├úo e adquirentes
    const transactionalGarbage = [
      /\bcompra\s+debito\b/g,
      /\bcompra\s+credito\b/g,
      /\bpg\s*\*\s*/g,
      /\bmp\s*\*\s*/g,
      /\bpicpay\s*\*\s*/g,
      /\brecargapay\s*\*\s*/g,
      /\bebanx\s*\*\s*/g,
      /\bstripe\s*\*\s*/g,
      /\bpag\s*\*\s*/g,
      /\bvisa\s+\d{4}\b/g,
      /\bmastercard\s+\d{4}\b/g,
      /\belo\s+\d{4}\b/g,
      /\bcartao\b/g,
      /\bfinal\s+\d{4}\b/g,
      /\bparcela\s+\d{1,2}\/\d{1,2}\b/g,
      /\bcompra\b/g,
    ];
    
    transactionalGarbage.forEach(regex => {
      clean = clean.replace(regex, '');
    });
    
    // 4. Remover c├│digos sequenciais, hashes ou n├║meros aleat├│rios maiores que 3 d├¡gitos
    clean = clean.replace(/\b[a-z0-9\-]{6,}\b/g, (match) => {
      return (/\d/.test(match) && /[a-z]/.test(match)) ? '' : match;
    });
    clean = clean.replace(/\b\d{4,}\b/g, '');
    clean = clean.replace(/#\d+\b/g, '');
    
    // 5. Remover caracteres especiais isolados e excesso de espa├ºos
    clean = clean.replace(/[^\w\s├Ç-├┐]/g, ' ');
    clean = clean.replace(/\s+/g, ' ').trim();
    
    return clean;
  }

  static async predictCategory(
    description: string,
    userId: string,
    type: 'expense' | 'income' | 'withdrawal' | 'deposit'
  ): Promise<CategoryPrediction | null> {
    if (!description || description.length < 3) {
      return null;
    }
    
    const normalizedDesc = description.toLowerCase().trim();
    
    // Disparar todas as verifica├º├Áes paralelamente para evitar gargalos sequenciais
    const [userLearning, keywordMatch, similarMatch] = await Promise.all([
      this.checkUserLearning(normalizedDesc, userId),
      this.matchKeywords(normalizedDesc, userId, type),
      this.findSimilarTransactions(normalizedDesc, userId, type)
    ]);
    
    // 1. Verificar hist├│rico do usu├írio (prioridade m├íxima)
    if (userLearning && userLearning.confidence > 0.6) {
      return userLearning;
    }
    
    // 2. Verificar palavras-chave padr├úo
    if (keywordMatch) {
      return keywordMatch;
    }
    
    // 3. Verificar transa├º├Áes similares do usu├írio
    if (similarMatch) {
      return similarMatch;
    }
    
    return null;
  }
  
  /**
   * Verifica aprendizado do usu├írio em mem├│ria com algoritmo de scoring multidimensional
   */
  private static async checkUserLearning(
    description: string,
    userId: string
  ): Promise<CategoryPrediction | null> {
    
    try {
      // Buscar todos os aprendizados do usu├írio
      const { data, error } = await supabase
        .from('user_category_learning')
        .select(`
          id,
          category_id,
          confidence,
          description_pattern,
          times_used,
          categories (
            id,
            name
          )
        `)
        .eq('user_id', userId)
        .order('last_used_at', { ascending: false, nullsFirst: false })
        .limit(200);
      
      if (error || !data || data.length === 0) return null;
      
      const cleanInput = this.extractCleanPattern(description);
      if (!cleanInput) return null;
      
      const cleanInputWords = cleanInput.split(' ');
      
      let bestMatch: any = null;
      let bestScore = 0;
      
      for (const row of data) {
        if (!row.categories || !row.description_pattern) continue;
        
        const cleanPattern = this.extractCleanPattern(row.description_pattern);
        if (!cleanPattern) continue;
        
        let matchQuality = 0; // 0.0 a 1.0
        
        // A. Match Exato
        if (cleanInput === cleanPattern) {
          matchQuality = 1.0;
        } 
        // B. Match de Prefixo
        else if (cleanInput.startsWith(cleanPattern)) {
          matchQuality = 0.9;
        } 
        // C. Match de Substring
        else if (cleanInput.includes(cleanPattern) || cleanPattern.includes(cleanInput)) {
          matchQuality = 0.8;
        }
        // D. Match de Tokens (Palavras)
        else {
          const cleanPatternWords = cleanPattern.split(' ');
          const allPatternWordsInInput = cleanPatternWords.every(pw => 
            cleanInputWords.some(iw => iw === pw || (pw.length >= 4 && this.levenshteinDistance(pw, iw) <= 1))
          );
          
          if (allPatternWordsInInput) {
            matchQuality = 0.75;
          } else {
            // E. Fuzzy match geral da frase inteira para pequenos erros de digita├º├úo
            const dist = this.levenshteinDistance(cleanInput, cleanPattern);
            const maxLen = Math.max(cleanInput.length, cleanPattern.length);
            if (dist <= 2 && maxLen > 5) {
              matchQuality = 0.70;
            }
          }
        }
        
        if (matchQuality > 0) {
          // Calcular pontua├º├úo final
          // Score = (Qualidade do Match * Confian├ºa Salva) + B├┤nus de Especificidade + B├┤nus de Frequ├¬ncia
          const baseWeight = Number(row.confidence) || 0.7;
          const lengthBonus = cleanPattern.length * 0.01; // D├í prefer├¬ncia a padr├Áes mais espec├¡ficos/longos
          const frequencyBonus = Math.min((row.times_used || 1) * 0.005, 0.05); // Pequena prefer├¬ncia a mais usados
          
          const score = (matchQuality * baseWeight) + lengthBonus + frequencyBonus;
          
          if (score > bestScore) {
            bestScore = score;
            bestMatch = row;
          }
        }
      }
      
      if (!bestMatch) return null;
      
      const categoryObj = bestMatch.categories as any;
      
      return {
        categoryId: bestMatch.category_id,
        categoryName: categoryObj?.name || 'Sem categoria',
        confidence: Math.min(Number(bestMatch.confidence), 1.0),
        reason: 'Baseado no seu hist├│rico',
      };
    } catch (error) {
      logger.error('Erro ao verificar aprendizado:', error);
      return null;
    }
  }
  
  /**
   * Match com palavras-chave padr├úo usando mapeamento conceitual e resili├¬ncia hier├írquica
   */
  private static async matchKeywords(
    description: string,
    userId: string,
    type: 'expense' | 'income' | 'withdrawal' | 'deposit'
  ): Promise<CategoryPrediction | null> {
    const predictionType = (type === 'withdrawal') ? 'expense' : (type === 'deposit') ? 'income' : type;
    
    try {
      // Buscar categorias do usu├írio
      const { data: categories } = await supabase
        .from('categories')
        .select('id, name, icon, parent_category_id')
        .eq('user_id', userId)
        .eq('type', predictionType);
      
      if (!categories || categories.length === 0) return null;
      
      const cleanInput = this.extractCleanPattern(description);
      if (!cleanInput) return null;
      
      const inputWords = cleanInput.split(' ');
      
      let bestConcept: string | null = null;
      let bestKeywordScore = 0;
      let matchedKeyword = '';
      
      // A. Varrer todos os conceitos em DEFAULT_KEYWORDS e achar o de maior afinidade com a descri├º├úo
      for (const [concept, keywordGroups] of Object.entries(DEFAULT_KEYWORDS)) {
        for (const group of keywordGroups) {
          for (const keyword of group.keywords) {
            const keywordWords = keyword.split(' ');
            
            // Palavra ├║nica: fazemos verifica├º├úo de token ou fuzzy de 1 erro
            if (keywordWords.length === 1) {
              const kw = keywordWords[0];
              const hasWord = inputWords.some(iw => {
                if (iw === kw) return true;
                return kw.length >= 4 && this.levenshteinDistance(kw, iw) <= 1;
              });
              
              if (hasWord) {
                const currentScore = group.weight;
                if (currentScore > bestKeywordScore) {
                  bestKeywordScore = currentScore;
                  bestConcept = concept;
                  matchedKeyword = keyword;
                }
              }
            } else {
              // Termo composto: verificamos se est├í contido na string inteira
              if (cleanInput.includes(keyword)) {
                const currentScore = group.weight;
                if (currentScore > bestKeywordScore) {
                  bestKeywordScore = currentScore;
                  bestConcept = concept;
                  matchedKeyword = keyword;
                }
              }
            }
          }
        }
      }
      
      if (!bestConcept) return null;
      
      // B. Casar o conceito vencedor com as categorias reais do usu├írio (hierarquia + sin├┤nimos + emoji)
      let matchedCategory: any = null;
      let matchTypeScore = 0;
      
      const subcategories = categories.filter(c => c.parent_category_id !== null);
      const parentCategories = categories.filter(c => c.parent_category_id === null);
      const candidates = [...subcategories, ...parentCategories];
      
      const cleanConcept = bestConcept.toLowerCase().trim();
      const synonyms = CONCEPT_SYNONYMS[bestConcept] || [];
      const emojis = CONCEPT_EMOJIS[bestConcept] || [];
      
      for (const category of candidates) {
        const catNameLower = category.name.toLowerCase().trim();
        const catIcon = category.icon;
        
        // 1. Match Exato ou Parcial Direto do Nome (Score: 100 para subcategoria, 95 para pai)
        if (catNameLower === cleanConcept || cleanConcept.includes(catNameLower) || catNameLower.includes(cleanConcept)) {
          const score = category.parent_category_id ? 100 : 95;
          if (score > matchTypeScore) {
            matchTypeScore = score;
            matchedCategory = category;
          }
        }
        
        // 2. Match de Sin├┤nimos Conceituais (Score: 80 para subcategoria, 75 para pai)
        const matchedSynonym = synonyms.find(syn => 
          catNameLower === syn || catNameLower.includes(syn) || syn.includes(catNameLower)
        );
        if (matchedSynonym) {
          const score = category.parent_category_id ? 80 : 75;
          if (score > matchTypeScore) {
            matchTypeScore = score;
            matchedCategory = category;
          }
        }
        
        // 3. Match por Emoji / Pista Visual (Score: 50)
        if (catIcon && emojis.includes(catIcon)) {
          const score = 50;
          if (score > matchTypeScore) {
            matchTypeScore = score;
            matchedCategory = category;
          }
        }
      }
      
      // Fallback: se n├úo mapeou especificamente, tenta verificar se algum pai direto bate com o conceito ou sin├┤nimos
      if (!matchedCategory) {
        for (const parent of parentCategories) {
          const parentNameLower = parent.name.toLowerCase().trim();
          if (parentNameLower === cleanConcept || synonyms.some(syn => parentNameLower.includes(syn))) {
            matchedCategory = parent;
            break;
          }
        }
      }
      
      if (!matchedCategory) return null;
      
      return {
        categoryId: matchedCategory.id,
        categoryName: matchedCategory.name,
        confidence: Math.min(bestKeywordScore / 10, 1.0),
        reason: `Detectado: "${matchedKeyword}"`,
      };
    } catch (error) {
      logger.error('Erro ao fazer match de keywords:', error);
      return null;
    }
  }
  
  /**
   * Busca transa├º├Áes similares do usu├írio
   */
  private static async findSimilarTransactions(
    description: string,
    userId: string,
    type: 'expense' | 'income' | 'withdrawal' | 'deposit'
  ): Promise<CategoryPrediction | null> {
    const predictionType = (type === 'withdrawal') ? 'expense' : (type === 'deposit') ? 'income' : type;
    
    try {
      const cleanDesc = this.extractCleanPattern(description);
      const searchTerm = cleanDesc ? cleanDesc.substring(0, 15) : description.substring(0, 15);
      if (!searchTerm) return null;
      
      const queryType = predictionType.toUpperCase();
      
      // Buscar transa├º├Áes com descri├º├úo similar
      const { data, error } = await supabase
        .from('transactions')
        .select(`
          category_id,
          categories (
            id,
            name
          )
        `)
        .eq('user_id', userId)
        .eq('type', queryType as any)
        .not('category_id', 'is', null)
        .ilike('description', `%${searchTerm}%`)
        .limit(10);
      
      if (error || !data || data.length === 0) return null;
      
      // Contar categorias mais usadas
      const categoryCount = new Map<string, { id: string, name: string, count: number }>();
      
      for (const tx of data) {
        if (!tx.category_id || !tx.categories) continue;
        
        const key = tx.category_id;
        const existing = categoryCount.get(key);
        
        if (existing) {
          existing.count++;
        } else {
          categoryCount.set(key, {
            id: tx.categories.id,
            name: tx.categories.name,
            count: 1,
          });
        }
      }
      
      // Pegar categoria mais usada
      let mostUsed: { id: string, name: string, count: number } | null = null;
      for (const cat of categoryCount.values()) {
        if (!mostUsed || cat.count > mostUsed.count) {
          mostUsed = cat;
        }
      }
      
      if (!mostUsed) return null;
      
      return {
        categoryId: mostUsed.id,
        categoryName: mostUsed.name,
        confidence: Math.min(mostUsed.count / 5, 0.8),
        reason: `Usado ${mostUsed.count}x em transa├º├Áes similares`,
      };
    } catch (error) {
      logger.error('Erro ao buscar transa├º├Áes similares:', error);
      return null;
    }
  }
  
  /**
   * Registra aprendizado quando o usu├írio confirma/corrige a categoria sugerida, aplicando limpeza e penaliza├º├úo de concorrentes
   */
  static async learnFromUser(
    description: string,
    categoryId: string,
    userId: string,
    wasCorrection: boolean
  ): Promise<void> {
    
    if (!description || description.length < 3) return;
    
    const cleanPattern = this.extractCleanPattern(description);
    if (!cleanPattern || cleanPattern.length < 3) return;
    
    try {
      // 1. Se foi uma corre├º├úo, penalizar ou remover padr├Áes antigos/concorrentes do mesmo padr├úo
      if (wasCorrection) {
        const { data: competitors } = await supabase
          .from('user_category_learning')
          .select('*')
          .eq('user_id', userId)
          .eq('description_pattern', cleanPattern)
          .neq('category_id', categoryId);
        
        if (competitors && competitors.length > 0) {
          for (const comp of competitors) {
            const newConfidence = Number(comp.confidence) - 0.3;
            if (newConfidence <= 0.2) {
              // Deletar concorr├¬ncia irrelevante
              await supabase
                .from('user_category_learning')
                .delete()
                .eq('id', comp.id);
            } else {
              // Penalizar ativamente a confian├ºa da concorr├¬ncia
              await supabase
                .from('user_category_learning')
                .update({
                  confidence: Math.max(newConfidence, 0.0),
                  updated_at: new Date().toISOString(),
                })
                .eq('id', comp.id);
            }
          }
        }
      }
      
      // 2. Verificar se j├í existe registro exato para esse padr├úo e categoria
      const { data: existing } = await supabase
        .from('user_category_learning')
        .select('*')
        .eq('user_id', userId)
        .eq('description_pattern', cleanPattern)
        .eq('category_id', categoryId)
        .maybeSingle();
      
      if (existing) {
        // Atualizar existente (incrementar times_used e calibrar confian├ºa)
        const increment = wasCorrection ? 0.15 : 0.08;
        const newConfidence = Math.min(Number(existing.confidence) + increment, 1.0);
        
        await supabase
          .from('user_category_learning')
          .update({
            times_used: (existing.times_used || 0) + 1,
            confidence: newConfidence,
            last_used_at: new Date().toISOString(),
          })
          .eq('id', existing.id);
      } else {
        // Criar novo padr├úo aprendido
        // Se for corre├º├úo manual expl├¡cita, a confian├ºa inicial ├® mais agressiva (0.85)
        await supabase
          .from('user_category_learning')
          .insert({
            user_id: userId,
            description_pattern: cleanPattern,
            category_id: categoryId,
            confidence: wasCorrection ? 0.85 : 0.70,
            times_used: 1,
            last_used_at: new Date().toISOString(),
          });
      }
    } catch (error) {
      logger.error('Erro ao registrar aprendizado:', error);
    }
  }
}

