interface GenerationResult {
  invoiceDue: number;
  budgetWarning: number;
  sharedPending: number;
  recurringPending: number;
  lowBalance: number;
  creditLimit: number;
  goalMilestone: number;
  upcomingBills: number;
  weeklySummary: number;
  total: number;
}

/**
 * Gera todas as notifica├º├Áes pendentes para um usu├írio
 */
export async function generateAllNotifications(userId: string): Promise<GenerationResult> {
  const result: GenerationResult = {
    invoiceDue: 0,
    budgetWarning: 0,
    sharedPending: 0,
    recurringPending: 0,
    lowBalance: 0,
    creditLimit: 0,
    goalMilestone: 0,
    upcomingBills: 0,
    weeklySummary: 0,
    total: 0,
  };

  try {
    // Buscar prefer├¬ncias do usu├írio
    const prefs = await getNotificationPreferences(userId);

    // Gerar notifica├º├Áes em paralelo
    const [
      invoices,
      budgets,
      shared,
      recurring,
      lowBalance,
      creditLimit,
      milestone,
      upcomingBills,
      weekly,
    ] = await Promise.all([
      prefs?.invoice_due_enabled !== false
        ? generateInvoiceDueNotifications(userId, prefs?.invoice_due_days_before || 3)
        : 0,
      prefs?.budget_warning_enabled !== false
        ? generateBudgetWarningNotifications(userId, prefs?.budget_warning_threshold || 80)
        : 0,
      prefs?.shared_pending_enabled !== false ? generateSharedPendingNotifications(userId) : 0,
      prefs?.recurring_enabled !== false ? generateRecurringPendingNotifications(userId) : 0,
      prefs?.low_balance_enabled !== false
        ? generateLowBalanceNotifications(userId, prefs?.low_balance_threshold || 100)
        : 0,
      prefs?.credit_limit_warning_enabled !== false
        ? generateCreditLimitNotifications(
            userId,
            (prefs as any)?.credit_limit_warning_threshold ?? 90
          )
        : 0,
      prefs?.savings_goal_enabled !== false ? generateGoalMilestoneNotifications(userId) : 0,
      prefs?.invoice_due_enabled !== false
        ? generateUpcomingBillNotifications(userId, [0, 1, 3])
        : 0,
      prefs?.weekly_summary_enabled ? generateWeeklySummaryNotification(userId) : 0,
    ]);

    result.invoiceDue = invoices;
    result.budgetWarning = budgets;
    result.sharedPending = shared;
    result.recurringPending = recurring;
    result.lowBalance = lowBalance || 0;
    result.creditLimit = creditLimit || 0;
    result.goalMilestone = milestone || 0;
    result.upcomingBills = upcomingBills || 0;
    result.weeklySummary = weekly || 0;
    result.total =
      invoices +
      budgets +
      shared +
      recurring +
      result.lowBalance +
      result.creditLimit +
      result.goalMilestone +
      result.upcomingBills +
      result.weeklySummary;

    // Disparar push para o dispositivo com as novas notifica├º├Áes
    if (result.total > 0) {
      supabase.functions
        .invoke("send-bill-reminders", { body: { user_id: userId } })
        .catch(() => {});
    }

    return result;
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes", error);
    return result;
  }
}

/**
 * Gera notifica├º├Áes de faturas pr├│ximas do vencimento
 */
async function generateInvoiceDueNotifications(
  userId: string,
  _daysBefore: number
): Promise<number> {
  let count = 0;

  try {
    // Buscar cart├Áes de cr├®dito ativos
    const { data: cards, error } = await supabase
      .from("accounts")
      .select("id, name, due_day, closing_day")
      .eq("user_id", userId)
      .eq("type", "CREDIT_CARD")
      .eq("is_active", true);

    if (error || !cards) return 0;

    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayDay = today.getDate();

    for (const card of cards) {
      const dueDay = card.due_day || 10;
      const closingDay = card.closing_day || 1;

      // REGRA: Notificar no dia do FECHAMENTO ou no ├║ltimo dia do m├¬s
      // quando o closing_day cadastrado ├® maior do que os dias do m├¬s atual
      // (ex: fechamento dia 31 em fevereiro ÔåÆ notificar no dia 28/29)
      const lastDayOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
      const effectiveClosingDay = Math.min(closingDay, lastDayOfMonth);
      if (todayDay !== effectiveClosingDay) continue;

      // A fatura que FECHOU HOJE vence no pr├│ximo m├¬s
      const dueDate = new Date(today);
      dueDate.setMonth(dueDate.getMonth() + 1);
      dueDate.setDate(dueDay);

      // Calcular dias at├® o vencimento (do fechamento at├® o vencimento)
      const diffTime = dueDate.getTime() - today.getTime();
      const daysUntilDue = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      // Calcular per├¡odo da fatura que FECHOU HOJE
      // Per├¡odo: do dia seguinte ao fechamento anterior at├® hoje (inclusive)
      const billingStart = new Date(today);
      billingStart.setMonth(billingStart.getMonth() - 1);
      billingStart.setDate(closingDay);
      // Adicionar 1 dia ao in├¡cio (transa├º├Áes come├ºam no dia seguinte ao fechamento)
      billingStart.setDate(billingStart.getDate() + 1);

      const billingEnd = new Date(today); // At├® hoje (inclusive)

      logger.debug(`Notifica├º├úo Fatura - Cart├úo: ${card.name}`);
      logger.debug(
        `  Per├¡odo: ${billingStart.toISOString().split("T")[0]} a ${billingEnd.toISOString().split("T")[0]}`
      );
      logger.debug(`  Vencimento: ${dueDate.toISOString().split("T")[0]} (${daysUntilDue} dias)`);

      // Buscar transa├º├Áes da fatura FECHADA
      const { data: transactions } = await supabase
        .from("transactions")
        .select("amount, date, description")
        .eq("account_id", card.id)
        .eq("type", "EXPENSE")
        .gte("date", billingStart.toISOString().split("T")[0])
        .lte("date", billingEnd.toISOString().split("T")[0]);

      const invoiceAmount = SafeFinancialCalculator.safeSum(
        ((transactions as TransactionData[]) || []).map((tx: TransactionData) => Number(tx.amount))
      );

      logger.debug(`  Transa├º├Áes: ${transactions?.length || 0}`);
      logger.debug(`  Valor total: R$ ${invoiceAmount.toFixed(2)}`);

      // S├│ notificar se houver valor a pagar
      if (invoiceAmount <= 0) {
        logger.debug(`  Sem valor a pagar, pulando notifica├º├úo`);
        continue;
      }

      // Definir a chave ├║nica da fatura
      const invoiceKey = `${card.id}-${billingEnd.getFullYear()}-${(billingEnd.getMonth() + 1).toString().padStart(2, "0")}`;

      // Verificar se j├í existe notifica├º├úo para ESTA FATURA ESPEC├ìFICA
      const { data: existingNotifications } = await (supabase as any)
        .from("notifications")
        .select("id, metadata")
        .eq("user_id", userId)
        .eq("related_id", card.id)
        .eq("related_type", "credit_card")
        .eq("type", "INVOICE_DUE");

      // Se j├í existe notifica├º├úo para esta fatura, pular
      if (existingNotifications) {
        const hasExisting = existingNotifications.some(
          (n: any /* any */) => n.metadata?.invoice_key === invoiceKey
        );
        if (hasExisting) {
          logger.debug(`  Notifica├º├úo j├í existe para fatura ${invoiceKey}`);
          continue;
        }
      }

      // Criar notifica├º├úo com metadata para identificar a fatura
      logger.debug(`  Criando notifica├º├úo`);
      await createInvoiceDueNotification(
        userId,
        card.name,
        card.id,
        invoiceAmount,
        daysUntilDue,
        invoiceKey
      );
      count++;
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de fatura:", error);
  }

  return count;
}

/**
 * Gera notifica├º├Áes de or├ºamentos em alerta
 */
async function generateBudgetWarningNotifications(
  userId: string,
  warningThreshold: number
): Promise<number> {
  let count = 0;

  try {
    // Buscar or├ºamentos ativos
    const { data: budgets, error: budgetError } = await (supabase as any)
      .from("budgets")
      .select("id, name, amount, currency, category_id")
      .eq("user_id", userId)
      .eq("is_active", true);

    if (budgetError || !budgets || budgets.length === 0) return 0;

    // Buscar transa├º├Áes do m├¬s atual
    const periodStart = new Date();
    periodStart.setDate(1);
    periodStart.setHours(0, 0, 0, 0);

    const { data: transactions, error: txError } = await supabase
      .from("transactions")
      .select("amount, category_id, currency, type, is_refund, exchange_rate")
      .eq("user_id", userId)
      .or("type.eq.EXPENSE,and(type.eq.INCOME,is_refund.eq.true)")
      .gte("competence_date", periodStart.toISOString().split("T")[0]);

    if (txError) return 0;

    const spentByCategory: Record<string, Record<string, number>> = {};

    ((transactions as (Transaction & { is_refund: boolean })[]) || []).forEach((tx) => {
      const catId = tx.category_id || "all";
      const txCurrency = tx.currency || "BRL";
      const amount = Number(tx.amount);
      const isRefund = tx.type === "INCOME" && tx.is_refund;
      const rate = Number(tx.exchange_rate) || 1.0;

      if (!spentByCategory[catId]) spentByCategory[catId] = {};

      // Se for estorno, subtra├¡mos
      const finalAmount = isRefund ? -amount : amount;

      // Armazenar valor nominal na moeda da transa├º├úo
      if (!spentByCategory[catId][txCurrency]) spentByCategory[catId][txCurrency] = 0;
      spentByCategory[catId][txCurrency] = SafeFinancialCalculator.add(
        spentByCategory[catId][txCurrency],
        finalAmount
      );

      // Se for moeda diferente de BRL, tamb├®m armazenamos o valor convertido em BRL para or├ºamentos em BRL
      if (txCurrency !== "BRL" && rate > 0) {
        if (!spentByCategory[catId]["BRL"]) spentByCategory[catId]["BRL"] = 0;
        spentByCategory[catId]["BRL"] = SafeFinancialCalculator.add(
          spentByCategory[catId]["BRL"],
          finalAmount * rate
        );
      }
    });

    // Verificar cada or├ºamento
    for (const budget of budgets as Budget[]) {
      const catId = budget.category_id || "all";
      const spent = spentByCategory[catId]?.[budget.currency] || 0;
      const percentage = (spent / budget.amount) * 100;

      // Verificar se j├í existe notifica├º├úo para este or├ºamento NESTE M├èS
      const periodStartStr = periodStart.toISOString().split("T")[0];
      const { data: existingNotification } = await (supabase as any)
        .from("notifications")
        .select("id, created_at, metadata")
        .eq("user_id", userId)
        .eq("related_id", budget.id)
        .eq("related_type", "budget")
        .gte("created_at", periodStartStr) // Criada neste m├¬s
        .limit(50);

      // Precisamos garantir que n├úo criamos a mesma notifica├º├úo (ex: 80% j├í notificado)
      if (existingNotification && existingNotification.length > 0) {
        const isExceeded = percentage >= 100;
        const alreadyNotified = existingNotification.some(
          (n: any /* any */) =>
            (isExceeded && n.metadata?.exceeded === true) ||
            (!isExceeded && n.metadata?.exceeded === false)
        );
        if (alreadyNotified) {
          logger.debug(`Notifica├º├úo de or├ºamento j├í existe este m├¬s para budget ${budget.id}`);
          continue;
        }
      }

      if (percentage >= 100) {
        await createBudgetWarningNotification(
          userId,
          budget.name,
          budget.id,
          percentage,
          true // exceeded
        );
        count++;
      } else if (percentage >= warningThreshold) {
        await createBudgetWarningNotification(
          userId,
          budget.name,
          budget.id,
          percentage,
          false // warning
        );
        count++;
      }
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de or├ºamento:", error);
  }

  return count;
}

interface PendingSplitItem {
  id: string;
  amount: number;
  member_id: string | null;
  transaction: {
    user_id: string;
    payer_id: string | null;
  } | null;
  member: {
    id: string;
    name: string;
