}

/**
 * Gera notifica├º├Áes de despesas compartilhadas pendentes
 */
async function generateSharedPendingNotifications(userId: string): Promise<number> {
  let count = 0;

  try {
    // Buscar splits n├úo acertados onde o usu├írio ├® o pagador
    const { data: pendingSplits, error } = await supabase
      .from("transaction_splits")
      .select(
        `
        id,
        amount,
        member_id,
        transaction:transactions!inner(
          user_id,
          payer_id
        ),
        member:family_members(
          id,
          name
        )
      `
      )
      .eq("is_settled", false)
      .not("member_id", "is", null);

    if (error || !pendingSplits) return 0;

    const typedSplits = (pendingSplits as unknown as PendingSplitItem[]) || [];

    // Filtrar apenas splits onde o usu├írio ├® o pagador original
    const userSplits = typedSplits.filter((split) => split.transaction?.user_id === userId);

    // Agrupar por membro
    const byMember: Record<string, MemberPendingData> = {};

    userSplits.forEach((split) => {
      const memberId = split.member_id;
      if (!memberId) return;
      const memberName = split.member?.name || "Membro";

      if (!byMember[memberId]) {
        byMember[memberId] = { name: memberName, amount: 0, count: 0 };
      }

      byMember[memberId].amount = SafeFinancialCalculator.add(
        byMember[memberId].amount,
        Number(split.amount)
      );
      byMember[memberId].count++;
    });

    // Criar notifica├º├úo para cada membro com pend├¬ncia significativa
    for (const [memberId, data] of Object.entries(byMember)) {
      if (data.amount >= 10) {
        // M├¡nimo de R$ 10 para notificar
        // Verificar se j├í existe notifica├º├úo n├úo dispensada para este membro nos ├ÜLTIMOS 7 DIAS
        const sevenDaysAgo = new Date();
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
        const sevenDaysAgoStr = sevenDaysAgo.toISOString().split("T")[0];
        const { data: existingNotification } = await (supabase as any)
          .from("notifications")
          .select("id, created_at, is_dismissed")
          .eq("user_id", userId)
          .eq("related_id", memberId)
          .eq("related_type", "family_member")
          .eq("type", "SHARED_PENDING")
          .gte("created_at", sevenDaysAgoStr) // Criada nos ├║ltimos 7 dias
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle();

        // Se j├í existe notifica├º├úo recente (ativa ou dispensada nos ├║ltimos 7 dias), pular
        if (existingNotification) {
          logger.debug(
            `Notifica├º├úo de compartilhado j├í existe nos ├║ltimos 7 dias para membro ${memberId}`
          );
          continue;
        }

        await createSharedPendingNotification(userId, data.name, memberId, data.amount, data.count);
        count++;
      }
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de compartilhados:", error);
  }

  return count;
}

