/**
 * Verifica se ├® a primeira vez do usu├írio e cria notifica├º├úo de boas-vindas
 */
export async function checkAndCreateWelcomeNotification(
  userId: string,
  userName: string
): Promise<boolean> {
  try {
    // Verificar se j├í existe notifica├º├úo de boas-vindas
    const { data: existing, error: checkError } = await (supabase as any)
      .from("notifications")
      .select("id")
      .eq("user_id", userId)
      .eq("type", "WELCOME")
      .maybeSingle();

    if (checkError) {
      // Se for erro de tabela inexistente, apenas loga e ignora
      if (checkError.code === "42P01") {
        logger.warn("Tabela notifications n├úo existe ainda");
        return false;
      }
      logger.error("Erro ao verificar boas-vindas", checkError);
      return false;
    }

    if (existing) {
      return false; // J├í existe
    }

    // Verificar se ├® usu├írio novo (sem transa├º├Áes)
    const { count } = await supabase
      .from("transactions")
      .select("*", { count: "exact", head: true })
      .eq("user_id", userId);

    if (count === 0) {
      await createWelcomeNotification(userId, userName);
      return true;
    }
  } catch (error) {
    logger.error("Erro ao verificar boas-vindas", error);
  }

  return false;
}

/**
 * Gera notifica├º├Áes de saldo baixo
 */
async function generateLowBalanceNotifications(userId: string, threshold: number): Promise<number> {
  let count = 0;
  try {
    const { data: accounts, error } = await supabase
      .from("accounts")
      .select("id, name, balance, type")
      .eq("user_id", userId)
      .eq("is_active", true)
      .neq("type", "CREDIT_CARD");

    if (error || !accounts) return 0;

    for (const acc of accounts) {
      if (acc.balance < threshold) {
        // Verificar se j├í existe nos ├ÜLTIMOS 7 DIAS
        const sevenDaysAgo = new Date();
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
        const sevenDaysAgoStr = sevenDaysAgo.toISOString().split("T")[0];
        const { data: existing } = await (supabase as any)
          .from("notifications")
          .select("id")
          .eq("user_id", userId)
          .eq("related_id", acc.id)
          .eq("type", "LOW_BALANCE")
          .gte("created_at", sevenDaysAgoStr)
          .limit(1)
          .maybeSingle();

        if (existing) continue;

        await createLowBalanceNotification(userId, acc.name, acc.id, Number(acc.balance));
        count++;
      }
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de saldo baixo", error);
  }
  return count;
}

/**
 * Gera notifica├º├Áes de limite de cart├úo
 */
async function generateCreditLimitNotifications(
  userId: string,
  thresholdPct: number
): Promise<number> {
  let count = 0;
  try {
    const { data: cards, error } = await supabase
      .from("accounts")
      .select("id, name, balance, credit_limit, type")
      .eq("user_id", userId)
      .eq("type", "CREDIT_CARD")
      .eq("is_active", true);

    if (error || !cards) return 0;

    for (const card of cards) {
      if (!card.credit_limit || card.credit_limit <= 0) continue;

      const spent = Math.abs(Number(card.balance));
      const percentage = (spent / Number(card.credit_limit)) * 100;

      if (percentage >= thresholdPct) {
        // Verificar se j├í existe nos ├ÜLTIMOS 7 DIAS
        const sevenDaysAgo = new Date();
        sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
        const sevenDaysAgoStr = sevenDaysAgo.toISOString().split("T")[0];
        const { data: existing } = await (supabase as any)
          .from("notifications")
          .select("id")
          .eq("user_id", userId)
          .eq("related_id", card.id)
          .eq("type", "CREDIT_LIMIT_WARNING")
          .gte("created_at", sevenDaysAgoStr)
          .limit(1)
          .maybeSingle();

        if (existing) continue;

        await createCreditLimitWarningNotification(userId, card.name, card.id, percentage);
        count++;
      }
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de limite de cart├úo", error);
  }
  return count;
}

/**
 * Gera notifica├º├Áes de marcos em metas
 */
async function generateGoalMilestoneNotifications(userId: string): Promise<number> {
  let count = 0;
  try {
    const { data: goals, error } = await supabase
      .from("goals")
      .select("id, name, current_amount, target_amount")
      .eq("user_id", userId)
      .eq("deleted", false)
      .eq("status", "IN_PROGRESS");

    if (error || !goals) return 0;

    for (const goal of goals) {
      const percentage = (Number(goal.current_amount) / Number(goal.target_amount)) * 100;

      // Marcos: 50%, 80%, 100%
      let milestone = 0;
      if (percentage >= 100) milestone = 100;
      else if (percentage >= 80) milestone = 80;
      else if (percentage >= 50) milestone = 50;

      if (milestone > 0) {
        // Verificar se j├í notificamos esse marco
        const { data: existing } = await (supabase as any)
          .from("notifications")
          .select("id")
          .eq("user_id", userId)
          .eq("related_id", goal.id)
          .eq("type", "GOAL_MILESTONE")
          .filter("metadata->>milestone", "eq", milestone.toString())
          .maybeSingle();

        if (existing) continue;

        await createGoalMilestoneNotification(userId, goal.name, goal.id, percentage, milestone);
        count++;
      }
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de metas", error);
  }
  return count;
}

/**
 * Gera resumo semanal financeiro (toda segunda-feira)
 */
async function generateWeeklySummaryNotification(userId: string): Promise<number> {
  try {
    const today = new Date();
    // S├│ dispara ├ás segundas (dia 1)
    if (today.getDay() !== 1) return 0;

    const todayStr = today.toISOString().split("T")[0];
    const { data: existing } = await (supabase as any)
      .from("notifications")
      .select("id")
      .eq("user_id", userId)
      .eq("type", "WEEKLY_SUMMARY")
      .gte("created_at", todayStr)
      .limit(1);

    if (existing && existing.length > 0) return 0;

    // Calcula receitas e despesas da semana passada
    const weekAgo = new Date(today);
    weekAgo.setDate(weekAgo.getDate() - 7);
    const weekAgoStr = weekAgo.toISOString().split("T")[0];

    const { data: txs } = await supabase
      .from("transactions")
      .select("amount, type")
      .eq("user_id", userId)
      .eq("status", "CONFIRMED")
      .is("deleted_at", null)
      .gte("date", weekAgoStr)
      .lt("date", todayStr);

    if (!txs || txs.length === 0) return 0;

    const expenses = txs
      .filter((t) => t.type === "EXPENSE")
      .reduce((s, t) => SafeFinancialCalculator.add(s, Number(t.amount)), 0);
    const income = txs.filter((t) => t.type === "INCOME").reduce((s, t) => SafeFinancialCalculator.add(s, Number(t.amount)), 0);
    const balance = income - expenses;
    const sign = balance >= 0 ? "+" : "";

    const fmt = (v: number) =>
      new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v);
    const { createNotification } = await import("./notificationService");
    await createNotification({
      user_id: userId,
      type: "WEEKLY_SUMMARY",
      title: "­ƒôè Resumo da semana",
      message: `Receitas ${fmt(income)} ┬À Despesas ${fmt(expenses)} ┬À Saldo ${sign}${fmt(balance)}`,
      icon: "­ƒôè",
      priority: "LOW",
      action_url: "/relatorios",
      action_label: "Ver relat├│rio",
    });
    return 1;
  } catch (error) {
    logger.error("Erro ao gerar resumo semanal", error);
    return 0;
  }
}

/**
 * Gera notifica├º├Áes para contas agendadas (PENDING) pr├│ximas do vencimento
 */
async function generateUpcomingBillNotifications(
  userId: string,
  daysBefore: number[]
): Promise<number> {
  let count = 0;
  try {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const maxDays = Math.max(...daysBefore);
    const maxDate = new Date(today);
    maxDate.setDate(maxDate.getDate() + maxDays);

    const { data: bills, error } = await supabase
      .from("transactions")
      .select("id, description, amount, date, type, currency")
      .eq("user_id", userId)
      .eq("status", "PENDING")
      .is("deleted_at", null)
      .gte("date", today.toISOString().split("T")[0])
      .lte("date", maxDate.toISOString().split("T")[0]);

    if (error || !bills) return 0;

    for (const bill of bills) {
      const billDate = new Date(bill.date + "T12:00:00");
      const daysUntil = Math.round((billDate.getTime() - today.getTime()) / 86400000);

      if (!daysBefore.includes(daysUntil)) continue;

      // Deduplicar: verificar se j├í existe notifica├º├úo para este item hoje
      const { data: existing } = await (supabase as any)
        .from("notifications")
        .select("id")
        .eq("user_id", userId)
        .eq("related_id", bill.id)
        .eq("related_type", "scheduled_bill")
        .gte("created_at", today.toISOString())
        .limit(1);

      if (existing && existing.length > 0) continue;

      const typeLabel =
        bill.type === "INCOME" ? "Receita" : bill.type === "TRANSFER" ? "Transfer├¬ncia" : "Conta";
      const urgencyLabel =
        daysUntil === 0
          ? "vence hoje"
          : daysUntil === 1
            ? "vence amanh├ú"
            : `vence em ${daysUntil} dias`;

      const { createNotification } = await import("./notificationService");
      await createNotification({
        user_id: userId,
        type: "INVOICE_DUE",
        title: `${typeLabel} agendada: ${bill.description}`,
        message: `${urgencyLabel.charAt(0).toUpperCase() + urgencyLabel.slice(1)}. Confirme quando for efetivada.`,
        icon: bill.type === "INCOME" ? "­ƒÆ░" : bill.type === "TRANSFER" ? "Ôåö´©Å" : "­ƒôï",
        priority: daysUntil === 0 ? "URGENT" : daysUntil === 1 ? "HIGH" : "NORMAL",
        action_url: "/transacoes",
        action_label: "Ver pr├│ximas",
        related_id: bill.id,
        related_type: "scheduled_bill",
      });
      count++;
    }
  } catch (error) {
    logger.error("Erro ao gerar notifica├º├Áes de contas agendadas", error);
  }
  return count;
}

