/**
 * Servi├ºo de Notifica├º├Áes
 *
 * Gerencia cria├º├úo, leitura e dismissal de notifica├º├Áes do sistema.
 * Integra com faturas, or├ºamentos, despesas compartilhadas, recorr├¬ncias, etc.
 */

import { supabase } from "@/integrations/supabase/client";
import { logger } from "@/utils/logger";

export type NotificationType =
  | "WELCOME"
  | "INVOICE_DUE"
  | "INVOICE_OVERDUE"
  | "BUDGET_WARNING"
  | "BUDGET_EXCEEDED"
  | "SHARED_PENDING"
  | "SHARED_SETTLED"
  | "SHARED_EXPENSE"
  | "RECURRING_PENDING"
  | "RECURRING_GENERATED"
  | "SAVINGS_GOAL"
  | "GOAL_MILESTONE"
  | "LOW_BALANCE"
  | "CREDIT_LIMIT_WARNING"
  | "SUBSCRIPTION_REMINDER"
  | "WEEKLY_SUMMARY"
  | "TRIP_INVITE"
  | "FAMILY_INVITE"
  | "SETTLEMENT_REQUEST"
  | "PAYMENT_CONFIRMED"
  | "SETTLEMENT_REJECTED"
  | "SECURITY_ALERT"
  | "GENERAL";

export type NotificationPriority = "LOW" | "NORMAL" | "HIGH" | "URGENT";

export interface Notification {
  id: string;
  user_id: string;
  type: NotificationType;
  title: string;
  message: string;
  icon?: string;
  action_url?: string;
  action_label?: string;
  related_id?: string;
  related_type?: string;
  priority: NotificationPriority;
  is_read: boolean;
  is_dismissed: boolean;
  expires_at?: string;
  created_at: string;
  read_at?: string;
  dismissed_at?: string;
  metadata?: Record<string, unknown>;
}

export interface NotificationPreferences {
  id: string;
  user_id: string;
  invoice_due_enabled: boolean;
  invoice_due_days_before: number;
  budget_warning_enabled: boolean;
  budget_warning_threshold: number;
  shared_pending_enabled: boolean;
  recurring_enabled: boolean;
  savings_goal_enabled: boolean;
  low_balance_enabled?: boolean | null;
  low_balance_threshold?: number | null;
  credit_limit_warning_enabled?: boolean | null;
  weekly_summary_enabled: boolean;
  email_notifications: boolean;
  push_notifications: boolean;
}

export interface CreateNotificationInput {
  user_id: string;
  type: NotificationType;
  title: string;
  message: string;
  icon?: string;
  action_url?: string;
  action_label?: string;
