  const { data, error } = await supabase
    .from("notifications")
    .select("*")
    .eq("user_id", userId)
    .eq("is_read", false)
    .eq("is_dismissed", false)
    .order("created_at", { ascending: false });

  if (error) {
    logger.error("Erro ao buscar notifica├º├Áes n├úo lidas", error);
    return [];
  }

  return (data || []) as Notification[];
}

