/**
 * Cria uma nova notifica├º├úo
 */
export async function createNotification(
  input: CreateNotificationInput
): Promise<Notification | null> {
  // Verifica se j├í existe notifica├º├úo similar N├âO DISPENSADA (evita duplicatas)
  if (input.related_id && input.type) {
    const { data: existing } = await supabase
      .from("notifications")
      .select("id")
      .eq("user_id", input.user_id)
      .eq("type", input.type)
      .eq("related_id", input.related_id)
      .eq("is_dismissed", false)
      .maybeSingle();

    if (existing) {
      return null; // J├í existe ativa, n├úo cria duplicata
    }
  }

  const { error } = await supabase
    .from("notifications")
    .insert({
      ...input,
      metadata: input.metadata as any,
      priority: input.priority || "NORMAL",
    });

  if (error) {
    logger.error("Erro ao criar notifica├º├úo", error);
    return null;
  }

  return null;
}

