/**
 * Cria notifica├º├úo de fatura pr├│xima do vencimento
 */
export async function createInvoiceDueNotification(
  userId: string,
  cardName: string,
  cardId: string,
  amount: number,
  daysUntilDue: number,
  invoiceKey?: string
): Promise<void> {
  const formatCurrency = (v: number) =>
    new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" }).format(v);

  const months = [
    "Janeiro",
    "Fevereiro",
    "Mar├ºo",
    "Abril",
    "Maio",
    "Junho",
    "Julho",
    "Agosto",
    "Setembro",
    "Outubro",
    "Novembro",
    "Dezembro",
  ];

  // Identificar o ano e m├¬s de refer├¬ncia da fatura a partir do invoiceKey
  let refYear = new Date().getFullYear();
  let refMonth = new Date().getMonth(); // 0-indexed
  let refMonthLabel = months[refMonth];

  if (invoiceKey) {
    const parts = invoiceKey.split("-");
    if (parts.length >= 3) {
      refYear = parseInt(parts[parts.length - 2], 10);
      refMonth = parseInt(parts[parts.length - 1], 10) - 1; // 0-indexed
      if (refMonth >= 0 && refMonth < 12) {
        refMonthLabel = months[refMonth];
      }
    }
  }

  // Determinar o t├¡tulo com base no status do vencimento
  let title = "";
  const isOverdue = daysUntilDue < 0;

  if (isOverdue) {
    const daysOverdue = Math.abs(daysUntilDue);
    title = `­ƒÜ¿ Fatura de ${refMonthLabel} (${cardName}) - VENCIDA h├í ${daysOverdue} dia${daysOverdue !== 1 ? "s" : ""}`;
  } else if (daysUntilDue === 0) {
    title = `ÔÜá´©Å Fatura de ${refMonthLabel} (${cardName}) - VENCE HOJE!`;
  } else {
    title = `­ƒÆ│ Fatura de ${refMonthLabel} (${cardName}) - Vence em ${daysUntilDue} dia${daysUntilDue !== 1 ? "s" : ""}`;
  }

  await createNotification({
    user_id: userId,
    type: isOverdue ? "INVOICE_OVERDUE" : "INVOICE_DUE",
    title,
    message: `Valor: ${formatCurrency(amount)}. N├úo esque├ºa de pagar!`,
    icon: isOverdue ? "­ƒÜ¿" : "­ƒÆ│",
    action_url: `/cartoes?cardId=${cardId}&month=${refYear}-${String(refMonth + 1).padStart(2, "0")}`,
    action_label: "Ver fatura",
    related_id: cardId,
    related_type: "credit_card",
    priority: isOverdue || daysUntilDue <= 1 ? "HIGH" : "NORMAL",
    metadata: invoiceKey ? { invoice_key: invoiceKey } : undefined,
  });
}

