/**
 * Overpass API + Nominatim service
 * Fetches real POIs (points of interest) for a destination using OpenStreetMap data.
 * Completely free, no API key required.
 */

export interface POI {
  title: string;
  location: string;
  description: string;
  durationHours: number;
  lat: number;
  lon: number;
  mapsUrl: string;
  osmType?: string;
  tags?: Record<string, string>;
}

// OSM tourism/amenity tags mapped to readable categories and suggested duration
const POI_TYPES: Array<{
  query: string;
  category: string;
  durationHours: number;
}> = [
  { query: 'tourism=museum',          category: 'Museu',        durationHours: 2   },
  { query: 'tourism=attraction',      category: 'Atra├º├úo',      durationHours: 1.5 },
  { query: 'tourism=viewpoint',       category: 'Mirante',      durationHours: 1   },
  { query: 'tourism=gallery',         category: 'Galeria',      durationHours: 1.5 },
  { query: 'historic=castle',         category: 'Castelo',      durationHours: 2   },
  { query: 'historic=monument',       category: 'Monumento',    durationHours: 1   },
  { query: 'historic=ruins',          category: 'Ru├¡nas',       durationHours: 1.5 },
  { query: 'amenity=restaurant',      category: 'Restaurante',  durationHours: 1.5 },
  { query: 'amenity=cafe',            category: 'Caf├®',         durationHours: 1   },
  { query: 'leisure=park',            category: 'Parque',       durationHours: 1.5 },
  { query: 'natural=beach',           category: 'Praia',        durationHours: 2.5 },
  { query: 'amenity=marketplace',     category: 'Mercado',      durationHours: 1.5 },
  { query: 'shop=mall',               category: 'Shopping',     durationHours: 2   },
];

// Best name field from OSM tags, in order of preference
function getBestName(tags: Record<string, string>): string | null {
  return (
    tags['name:pt'] ||
    tags['name'] ||
    tags['official_name'] ||
    tags['alt_name'] ||
    null
  );
}

// Build human-readable location string from OSM tags
function buildLocation(tags: Record<string, string>): string {
  const parts: string[] = [];
  if (tags['addr:street']) {
    parts.push(tags['addr:street'] + (tags['addr:housenumber'] ? `, ${tags['addr:housenumber']}` : ''));
  }
  if (tags['addr:suburb'] || tags['addr:neighbourhood']) {
    parts.push(tags['addr:suburb'] || tags['addr:neighbourhood']);
  }
  if (tags['addr:city']) parts.push(tags['addr:city']);
  if (parts.length === 0 && tags['district']) parts.push(tags['district']);
  return parts.join(' ÔÇö ') || '';
}

// Build description from available OSM tags
function buildDescription(tags: Record<string, string>, category: string): string {
  const parts: string[] = [];

  if (tags['description'] || tags['description:pt']) {
    parts.push(tags['description:pt'] || tags['description']);
  }
  if (tags['opening_hours']) {
    parts.push(`Hor├írio: ${tags['opening_hours']}`);
  }
  if (tags['fee'] === 'yes' && tags['charge']) {
    parts.push(`Entrada: ${tags['charge']}`);
  } else if (tags['fee'] === 'no') {
    parts.push('Entrada gratuita');
  }
  if (tags['cuisine']) {
    parts.push(`Culin├íria: ${tags['cuisine'].replace(/_/g, ' ')}`);
  }
  if (tags['website'] || tags['url']) {
    parts.push(`Site: ${tags['website'] || tags['url']}`);
  }

  return parts.length > 0 ? parts.join(' | ') : category;
}

/**
 * Get lat/lon for a destination string using Nominatim (OpenStreetMap geocoder).
 */
export async function geocodeDestination(destination: string): Promise<{ lat: number; lon: number } | null> {
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(destination)}&format=json&limit=1`;
    const res = await fetch(url, {
      headers: { 'Accept-Language': 'pt-BR,pt;q=0.9', 'User-Agent': 'SeuBolsoInteligente/1.0' },
      signal: controller.signal,
    });
    clearTimeout(timeout);
    if (!res.ok) return null;
    const data = await res.json();
    if (!data.length) return null;
    return { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon) };
  } catch {
    return null;
  }
}

/**
 * Fetch real POIs from Overpass API for a given lat/lon.
 * Returns up to `limit` diverse POIs sorted by tourist relevance.
 */
async function fetchOverpassPOIs(
  lat: number,
  lon: number,
  radiusMeters = 5000,
  limit = 12,
): Promise<POI[]> {
  // Build union query for all POI types
  const unionParts = POI_TYPES.map(({ query }) => {
    const [key, value] = query.split('=');
    return (
      `node["${key}"="${value}"](around:${radiusMeters},${lat},${lon});\n` +
      `way["${key}"="${value}"](around:${radiusMeters},${lat},${lon});`
    );
  }).join('\n');

  const overpassQuery = `[out:json][timeout:20];(\n${unionParts}\n);out center tags 50;`;

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 8000);

  // Try multiple Overpass mirrors ÔÇö some block CORS, pick first that works
  const mirrors = [
    'https://overpass.kumi.systems/api/interpreter',
    'https://overpass.openstreetmap.fr/api/interpreter',
  ];

  let res: Response | null = null;
  for (const mirror of mirrors) {
    try {
      res = await fetch(mirror, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: `data=${encodeURIComponent(overpassQuery)}`,
        signal: controller.signal,
      });
      if (res.ok) break;
    } catch {
      // try next mirror
    }
  }
  clearTimeout(timeout);
  if (!res || !res.ok) throw new Error(`Overpass error: all mirrors failed`);
  const data = await res.json();

  const elements: any[] = data.elements || [];

  // Deduplicate by name and map to POI
  const seen = new Set<string>();
  const pois: POI[] = [];

  for (const el of elements) {
    const tags: Record<string, string> = el.tags || {};
    const name = getBestName(tags);
    if (!name || seen.has(name.toLowerCase())) continue;
    seen.add(name.toLowerCase());

    // Determine coordinates (nodes have lat/lon directly, ways have center)
    const elLat = el.lat ?? el.center?.lat;
    const elLon = el.lon ?? el.center?.lon;
    if (!elLat || !elLon) continue;

    // Find matching POI type for category/duration
    let category = 'Atra├º├úo';
    let durationHours = 1.5;
    for (const { query, category: cat, durationHours: dur } of POI_TYPES) {
      const [key, value] = query.split('=');
      if (tags[key] === value) {
        category = cat;
        durationHours = dur;
        break;
      }
    }

    const location = buildLocation(tags);
    const description = buildDescription(tags, category);
    const mapsUrl = `https://www.google.com/maps/place/${elLat},${elLon}`;

    pois.push({ title: name, location, description, durationHours, lat: elLat, lon: elLon, mapsUrl, tags });

    if (pois.length >= limit * 3) break; // collect extra for diversity filtering
  }

  // Ensure category diversity ÔÇö pick best spread
  const byCategory = new Map<string, POI[]>();
  for (const poi of pois) {
    const cat = poi.tags?.tourism || poi.tags?.amenity || poi.tags?.historic || poi.tags?.leisure || 'other';
    if (!byCategory.has(cat)) byCategory.set(cat, []);
    byCategory.get(cat)!.push(poi);
  }

  const diverse: POI[] = [];
  const iters = Math.ceil(limit / byCategory.size) + 1;
  for (let i = 0; i < iters && diverse.length < limit; i++) {
    for (const items of byCategory.values()) {
      if (i < items.length && diverse.length < limit) diverse.push(items[i]);
    }
  }

  return diverse.slice(0, limit);
}

/**
 * Main entry point: geocode destination then fetch real POIs.
 * Falls back to empty array on any error.
 */
export async function fetchRealPOIs(destination: string, limit = 10): Promise<POI[]> {
  const coords = await geocodeDestination(destination);
  if (!coords) return [];

  try {
    return await fetchOverpassPOIs(coords.lat, coords.lon, 5000, limit);
  } catch {
    // Try wider radius if first attempt returns too few results
    try {
      return await fetchOverpassPOIs(coords.lat, coords.lon, 15000, limit);
    } catch {
      return [];
    }
  }
}

/**
 * Servi├ºo de Recorr├¬ncia de Transa├º├Áes
 * 
 * Gera automaticamente transa├º├Áes recorrentes baseadas em transa├º├Áes marcadas como is_recurring.
 * Este servi├ºo pode ser chamado:
 * - Ao abrir o app (verificar transa├º├Áes pendentes)
 * - Por um cron job no backend
 * - Manualmente pelo usu├írio
 */

import { supabase } from "@/integrations/supabase/client";
import * as dateFns from "date-fns";

export interface RecurringTransaction {
  id: string;
  user_id: string;
  type: "INCOME" | "EXPENSE" | "TRANSFER";
  amount: number;
  description: string;
  date: string;
  category_id: string | null;
  account_id: string | null;
  currency: string;
  is_recurring: boolean;
  recurrence_pattern: string | null; // 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'YEARLY'
  recurrence_day: number | null;
  last_generated_date: string | null;
}

export interface GenerationResult {
  success: boolean;
  generated: number;
  errors: string[];
}

/**
 * Calcula a pr├│xima data de ocorr├¬ncia baseada no padr├úo de recorr├¬ncia
 */
export function calculateNextOccurrence(
  lastDate: Date,
  pattern: string,
  recurrenceDay?: number | null
): Date {
  switch (pattern) {
    case "DAILY":
      return dateFns.addDays(lastDate, 1);
    case "WEEKLY":
      return dateFns.addWeeks(lastDate, 1);
    case "MONTHLY":
      // Se tem dia espec├¡fico, usa ele; sen├úo, adiciona 1 m├¬s
      if (recurrenceDay) {
        const nextMonth = dateFns.addMonths(lastDate, 1);
        // Ajusta para o dia correto, considerando meses com menos dias
        const maxDay = new Date(nextMonth.getFullYear(), nextMonth.getMonth() + 1, 0).getDate();
        const targetDay = Math.min(recurrenceDay, maxDay);
        return dateFns.setDate(nextMonth, targetDay);
      }
      return dateFns.addMonths(lastDate, 1);
    case "YEARLY":
      return dateFns.addYears(lastDate, 1);
    default:
      return dateFns.addMonths(lastDate, 1);
  }
}

/**
 * Gera transa├º├Áes recorrentes pendentes para um usu├írio
 */
export async function generatePendingRecurringTransactions(
  userId: string,
  upToDate: Date = new Date()
): Promise<GenerationResult> {
  const result: GenerationResult = {
    success: true,
    generated: 0,
    errors: [],
  };

  try {
    // Buscar transa├º├Áes recorrentes ativas
    const { data: recurringTransactions, error: fetchError } = await supabase
      .from("transactions")
      .select("*")
      .eq("user_id", userId)
      .eq("is_recurring", true)
      .order("date", { ascending: true });

    if (fetchError) {
      result.success = false;
      result.errors.push(`Erro ao buscar transa├º├Áes recorrentes: ${fetchError.message}`);
      return result;
    }

    if (!recurringTransactions || recurringTransactions.length === 0) {
      return result;
    }

    const today = dateFns.startOfDay(upToDate);
    const transactionsToCreate: any[] = [];

    // Buscar contas do usu├írio para calcular compet├¬ncia correta no cart├úo de cr├®dito
    const { data: userAccounts } = await supabase
      .from("accounts")
      .select("id, type, closing_day")
      .eq("user_id", userId);

    const accountMap = new Map<string, { type: string; closing_day: number | null }>();
    (userAccounts || []).forEach(acc => {
      accountMap.set(acc.id, { type: acc.type, closing_day: acc.closing_day });
    });

    /**
     * Calcula a competence_date respeitando o ciclo do cart├úo de cr├®dito.
     * Se n├úo for cart├úo, retorna o primeiro dia do m├¬s da transa├º├úo.
     */
    const calculateCompetenceForRecurrence = (dateStr: string, accountId: string | null): string => {
      const d = new Date(dateStr + 'T12:00:00Z');
      const account = accountId ? accountMap.get(accountId) : null;
      if (account && account.type === 'CREDIT_CARD' && account.closing_day !== null) {
        const day = d.getUTCDate();
        let compMonth = d.getUTCMonth();
        let compYear = d.getUTCFullYear();
        if (day > account.closing_day) {
          compMonth++;
          if (compMonth > 11) { compMonth = 0; compYear++; }
        }
        return `${compYear}-${String(compMonth + 1).padStart(2, '0')}-01`;
      }
      return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}-01`;
    };


    for (const tx of recurringTransactions) {
      if (!tx.recurrence_pattern) continue;

      // Determinar a ├║ltima data gerada de forma segura contra deslocamentos de fuso hor├írio
      const lastGeneratedDate = tx.last_generated_date 
        ? new Date(tx.last_generated_date + 'T12:00:00')
        : new Date(tx.date + 'T12:00:00');

      // Calcular pr├│ximas ocorr├¬ncias at├® hoje
      let nextDate = calculateNextOccurrence(
        lastGeneratedDate,
        tx.recurrence_pattern,
        tx.recurrence_day
      );

      // Gerar transa├º├Áes at├® a data limite (hoje)
      while (dateFns.isBefore(dateFns.startOfDay(nextDate), today) || dateFns.format(nextDate, 'yyyy-MM-dd') === dateFns.format(today, 'yyyy-MM-dd')) {
        // Criar nova transa├º├úo baseada na recorrente
        const formattedDate = dateFns.format(nextDate, "yyyy-MM-dd");
        const newTransaction = {
          user_id: tx.user_id,
          type: tx.type,
          amount: tx.amount,
          description: tx.description,
          date: formattedDate,
          competence_date: calculateCompetenceForRecurrence(formattedDate, tx.account_id),
          category_id: tx.category_id,
          account_id: tx.account_id,
          currency: tx.currency,
          is_recurring: false, // A transa├º├úo gerada n├úo ├® recorrente
          source_transaction_id: tx.id, // Refer├¬ncia ├á transa├º├úo original
          is_installment: false,
          is_shared: tx.is_shared || false,
          is_settled: false,
        };

        transactionsToCreate.push(newTransaction);

        // Calcular pr├│xima data
        nextDate = calculateNextOccurrence(
          nextDate,
          tx.recurrence_pattern,
          tx.recurrence_day
        );

        // Limite de seguran├ºa: m├íximo 12 transa├º├Áes por vez
        if (transactionsToCreate.length >= 12) {
          break;
        }
      }

      // Atualizar last_generated_date da transa├º├úo original
      if (transactionsToCreate.length > 0) {
        const lastCreatedDate = transactionsToCreate[transactionsToCreate.length - 1].date;
        
        const { error: updateError } = await supabase
          .from("transactions")
          .update({ last_generated_date: lastCreatedDate as string })
          .eq("id", tx.id);

        if (updateError) {
          result.errors.push(`Erro ao atualizar last_generated_date: ${updateError.message}`);
        }
      }
    }

    // Inserir todas as transa├º├Áes geradas
    if (transactionsToCreate.length > 0) {
      const { error: insertError } = await supabase
        .from("transactions")
        .insert(transactionsToCreate);

      if (insertError) {
        result.success = false;
        result.errors.push(`Erro ao criar transa├º├Áes: ${insertError.message}`);
      } else {
        result.generated = transactionsToCreate.length;
      }
    }

    return result;
  } catch (error: unknown) {
    result.success = false;
    result.errors.push(`Erro inesperado: ${error instanceof Error ? error.message : 'Erro desconhecido'}`);
    return result;
  }
}

/**
 * Verifica se h├í transa├º├Áes recorrentes pendentes
 */
export async function checkPendingRecurrences(userId: string): Promise<number> {
  try {
    const { data, error } = await supabase
      .from("transactions")
      .select("id, date, recurrence_pattern, recurrence_day, last_generated_date")
      .eq("user_id", userId)
      .eq("is_recurring", true);

    if (error || !data) return 0;

    const today = dateFns.startOfDay(new Date());
    let pendingCount = 0;

    for (const tx of data) {
      if (!tx.recurrence_pattern) continue;

      // Determinar a ├║ltima data de forma segura contra deslocamentos de fuso hor├írio
      const lastDate = tx.last_generated_date 
        ? new Date(tx.last_generated_date + 'T12:00:00')
        : new Date(tx.date + 'T12:00:00');

      const nextDate = calculateNextOccurrence(
        lastDate,
        tx.recurrence_pattern,
        tx.recurrence_day
      );

      if (dateFns.isBefore(dateFns.startOfDay(nextDate), today) || dateFns.format(nextDate, 'yyyy-MM-dd') === dateFns.format(today, 'yyyy-MM-dd')) {
        pendingCount++;
      }
    }

    return pendingCount;
  } catch {
    return 0;
  }
}

/**
 * VALIDATION SERVICE
 * Servi├ºo completo de valida├º├úo de transa├º├Áes
 * Baseado no PE copy com 20+ valida├º├Áes
 */

import { z } from "zod";
import { SafeFinancialCalculator } from "./SafeFinancialCalculator";
import { dateUtils } from "@/utils/dateUtils";

export interface ValidationResult {
  isValid: boolean;
  errors: string[];
  warnings: string[];
}

export const transactionSchema = z.object({
  id: z.string().uuid().optional(),
  amount: z.number().positive("Valor deve ser maior que zero"),
  description: z.string().min(1, "Descri├º├úo ├® obrigat├│ria").max(200),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, "Formato de data inv├ílido (YYYY-MM-DD)"),
  type: z.enum(["EXPENSE", "INCOME", "TRANSFER", "WITHDRAWAL", "DEPOSIT"]),
  account_id: z.string().uuid().nullable().optional(),
  destination_account_id: z.string().uuid().nullable().optional(),
  category_id: z.string().uuid().nullable().optional(),
  trip_id: z.string().uuid().nullable().optional(),
  is_shared: z.boolean().optional(),
  payer_id: z.string().uuid().nullable().optional(),
  is_installment: z.boolean().optional(),
  total_installments: z.number().int().min(2).max(48).nullable().optional(),
  is_recurring: z.boolean().nullable().optional(),
  frequency: z.enum(["DAILY", "WEEKLY", "MONTHLY", "YEARLY"]).nullable().optional(),
  recurrence_day: z.number().int().min(1).max(31).nullable().optional(),
  is_refund: z.boolean().nullable().optional(),
  refund_of_transaction_id: z.string().uuid().nullable().optional(),
  exchange_rate: z.number().positive().nullable().optional(),
  destination_amount: z.number().positive().nullable().optional(),
  destination_currency: z.string().nullable().optional(),
  transaction_splits: z
    .array(
      z.object({
        member_id: z.string().uuid(),
        percentage: z.number().min(0).max(100),
        amount: z.number().min(0),
      })
    )
    .optional(),
});

export type Transaction = z.infer<typeof transactionSchema>;

export interface Account {
  id: string;
  type: "CHECKING" | "SAVINGS" | "CREDIT_CARD" | "INVESTMENT" | "CASH" | "EMERGENCY_FUND";
  balance: number;
  credit_limit: number | null;
  currency: string;
  is_international?: boolean | null;
}

export interface Trip {
  id: string;
  currency: string;
}

/**
 * Valida se uma data ├® v├ílida no calend├írio
 *
 * Uses dateUtils.parseDate() to avoid timezone issues with new Date(year, month-1, day)
 */
function isValidDate(dateString: string): boolean {
  if (!dateString) return false;

  // Validate format YYYY-MM-DD
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(dateString)) return false;

  const [year, month, day] = dateString.split("-").map(Number);
  if (!year || !month || !day) return false;

  // Check if month is valid (1-12)
  if (month < 1 || month > 12) return false;

  // Check if day is valid for the given month
  const daysInMonth = new Date(year, month, 0).getDate();
  if (day < 1 || day > daysInMonth) return false;

  return true;
}

/**
 * Valida se uma data est├í em um intervalo razo├ível (┬▒1 ano)
 * Usa dateUtils.parseDate() para evitar bugs de timezone (invariante do MASTER_BLUEPRINT)
 */
function isReasonableDate(dateString: string): boolean {
  const date = dateUtils.parseDate(dateString);
  const now = new Date();
  const oneYearAgo = new Date(now.getFullYear() - 1, now.getMonth(), now.getDate());
  const oneYearAhead = new Date(now.getFullYear() + 1, now.getMonth(), now.getDate());

  return date >= oneYearAgo && date <= oneYearAhead;
}

/**
 * VALIDA├ç├âO PRINCIPAL DE TRANSA├ç├âO
 */
export function validateTransaction(
  transaction: Transaction,
  account?: Account,
  destinationAccount?: Account,
  trip?: Trip,
  allTransactions?: Transaction[],
  isPaidByOther?: boolean,
  currentUserMemberId?: string,
  currentUserId?: string
): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  // 0. VALIDA├ç├âO ZOD (Estrutural)
  const zodResult = transactionSchema.safeParse(transaction);
  if (!zodResult.success) {
    zodResult.error.errors.forEach((err) => {
      errors.push(`${err.path.join(".")}: ${err.message}`);
    });
    return { isValid: false, errors, warnings };
  }

  // ==========================================
  // 1. CAMPOS OBRIGAT├ôRIOS
  // ==========================================

  if (!transaction.amount || transaction.amount <= 0) {
    errors.push("Valor deve ser maior que zero");
  }

  if (!transaction.description || transaction.description.trim() === "") {
    errors.push("Descri├º├úo ├® obrigat├│ria");
  }

  if (!transaction.date) {
    errors.push("Data ├® obrigat├│ria");
  }

  if (!transaction.type) {
    errors.push("Tipo de transa├º├úo ├® obrigat├│rio");
  }

  // Conta obrigat├│ria para tipos que movem dinheiro (exceto quando pago por outro)
  // Priorizar o par├ómetro isPaidByOther se fornecido explicitamente. Caso contr├írio, usar a l├│gica de compara├º├úo.
  const isPaidByOtherBool =
    isPaidByOther !== undefined
      ? isPaidByOther
      : !!transaction.payer_id &&
        (currentUserMemberId ? transaction.payer_id !== currentUserMemberId : true) &&
        (currentUserId ? transaction.payer_id !== currentUserId : true);

  const isSingleAccountType = ["EXPENSE", "INCOME", "WITHDRAWAL", "DEPOSIT"].includes(
    transaction.type
  );

  if (isSingleAccountType && !transaction.account_id && !isPaidByOtherBool) {
    errors.push("Conta ├® obrigat├│ria");
  }

  // Validar que account_id ├® null quando pago por outro
  if (isPaidByOtherBool && transaction.account_id) {
    errors.push("Transa├º├úo paga por outra pessoa n├úo deve ter conta vinculada");
  }

  // Conta origem e destino obrigat├│rias para TRANSFER
  if (transaction.type === "TRANSFER") {
    if (!transaction.account_id) {
      errors.push("Conta de origem ├® obrigat├│ria");
    }
    if (!transaction.destination_account_id) {
      errors.push("Conta de destino ├® obrigat├│ria");
    }
    if (transaction.account_id === transaction.destination_account_id) {
      errors.push("Conta de origem e destino devem ser diferentes");
    }
  }

  // Categoria ├® obrigat├│ria para despesas e receitas
  if (
    (transaction.type === "EXPENSE" || transaction.type === "INCOME") &&
    !transaction.category_id
  ) {
    errors.push(
      transaction.type === "EXPENSE"
        ? "A categoria ├® obrigat├│ria para despesas"
        : "A categoria ├® obrigat├│ria para receitas"
    );
  }

  // ==========================================
  // 2. VALIDA├ç├âO DE DATA
  // ==========================================

  if (transaction.date) {
    // Data v├ílida no calend├írio
    if (!isValidDate(transaction.date)) {
      errors.push("Data inv├ílida (dia n├úo existe no m├¬s)");
    }

    // Data razo├ível (┬▒1 ano)
    if (!isReasonableDate(transaction.date)) {
      warnings.push("Data muito distante (mais de 1 ano)");
    }
  }

  // ==========================================
  // 3. VALIDA├ç├âO DE VALOR
  // ==========================================

  const MAX_AMOUNT = 1000000;
  if (transaction.amount && transaction.amount > MAX_AMOUNT) {
    warnings.push(
      `Valor muito alto (maior que ${MAX_AMOUNT.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })})`
    );
  }

  // ==========================================
  // 4. VALIDA├ç├âO DE LIMITE DE CART├âO
  // ==========================================

  if (account?.type === "CREDIT_CARD" && transaction.type === "EXPENSE") {
    if (account.credit_limit) {
      const currentUsed = Math.abs(account.balance);
      const newUsed = currentUsed + (transaction.amount || 0);

      if (newUsed > account.credit_limit) {
        const available = account.credit_limit - currentUsed;
        errors.push(
          `Limite do cart├úo ser├í ultrapassado. ` +
            `Dispon├¡vel: ${available.toLocaleString("pt-BR", { style: "currency", currency: "BRL" })}`
        );
      }
    }
  }

  // ==========================================
  // 4.1 VALIDA├ç├âO DE SALDO NEGATIVO EM CONTAS
  // ==========================================

  // Para despesas/saques em contas regulares (n├úo cart├úo de cr├®dito)
  const isMoneyOut = transaction.type === "EXPENSE" || transaction.type === "WITHDRAWAL";
  if (account && account.type !== "CREDIT_CARD" && isMoneyOut) {
    const newBalance = account.balance - (transaction.amount || 0);

    if (newBalance < 0) {
      warnings.push(
        `Esta transa├º├úo deixar├í a conta com saldo negativo: ` +
          `${newBalance.toLocaleString("pt-BR", { style: "currency", currency: account.currency || "BRL" })}`
      );
    }
  }

  // Para transfer├¬ncias, validar saldo da conta de origem
  if (account && transaction.type === "TRANSFER") {
    const newBalance = account.balance - (transaction.amount || 0);

    if (newBalance < 0) {
      errors.push(
        `Saldo insuficiente para transfer├¬ncia. ` +
          `Dispon├¡vel: ${account.balance.toLocaleString("pt-BR", { style: "currency", currency: account.currency || "BRL" })}`
      );
    }
  }

  // ==========================================
  // 5. VALIDA├ç├âO DE PARCELAMENTO
  // ==========================================

  if (transaction.is_installment) {
    if (!transaction.total_installments || transaction.total_installments < 2) {
      errors.push("Parcelamento deve ter pelo menos 2 parcelas");
    }

    if (transaction.total_installments && transaction.total_installments > 48) {
      warnings.push("N├║mero de parcelas muito alto (mais de 48)");
    }

    // Parcelamento em conta n├úo-cart├úo
    if (account && account.type !== "CREDIT_CARD") {
      warnings.push("Parcelamento geralmente ├® usado apenas em cart├Áes de cr├®dito");
    }
  }

  // ==========================================
  // 6. VALIDA├ç├âO DE DIVIS├âO COMPARTILHADA
  // ==========================================

  if (
    transaction.is_shared &&
    transaction.transaction_splits &&
    transaction.transaction_splits.length > 0
  ) {
    const totalPercentage = SafeFinancialCalculator.safeSum(
      transaction.transaction_splits.map((s) =>
        SafeFinancialCalculator.toSafeNumber(s.percentage, 0)
      )
    );

    const totalAssigned = SafeFinancialCalculator.safeSum(
      transaction.transaction_splits.map((s) => SafeFinancialCalculator.toSafeNumber(s.amount, 0))
    );

    // Soma de percentagens n├úo deve exceder 100%
    // Se for menor que 100%, o sistema auto-completa com a parte do criador no hook useCreateTransaction
    // Ô£à VALIDA├ç├âO RIGOROSA (Crit├®rio #6): Rejeitar se > 100% sem margem de erro
    if (totalPercentage > 100.0001) {
      errors.push(
        `A soma das porcentagens n├úo pode exceder 100% (atual: ${totalPercentage.toFixed(2)}%)`
      );
    } else if (totalPercentage <= 0 && transaction.is_shared) {
      // Se ├® compartilhada e tem splits, a soma deve ser > 0
      errors.push(`A soma das porcentagens deve ser maior que 0% para transa├º├Áes compartilhadas`);
    }

    // Soma de valores n├úo pode exceder o total
    const safeAmount = SafeFinancialCalculator.toSafeNumber(transaction.amount, 0);
    if (safeAmount > 0 && totalAssigned > safeAmount) {
      errors.push(
        `Divis├úo inv├ílida: soma dos valores (${totalAssigned.toFixed(2)}) ` +
          `├® maior que o total (${safeAmount.toFixed(2)})`
      );
    }
  }

  // ==========================================
  // 7. VALIDA├ç├âO DE TIPO DE CONTA
  // ==========================================

  // Transfer├¬ncia para cart├úo de cr├®dito ├® permitida (pagamento de fatura)
  if (transaction.type === "TRANSFER" && destinationAccount?.type === "CREDIT_CARD") {
    // Apenas uma nota informativa ou aviso se for o caso
  }

  // ==========================================
  // 8. VALIDA├ç├âO DE MOEDA (VIAGENS)
  // ==========================================

  if (trip && account && account.currency !== trip.currency) {
    warnings.push(
      `Lan├ºamento em ${account.currency} para viagem em ${trip.currency}. O valor ser├í convertido automaticamente.`
    );
  }

  // ==========================================
  // 9. VALIDA├ç├âO DE TRANSFER├èNCIA INTERNACIONAL
  // ==========================================

  if (transaction.type === "TRANSFER" && account && destinationAccount) {
    const isMultiCurrency = account.currency !== destinationAccount.currency;

    if (isMultiCurrency && !transaction.exchange_rate) {
      errors.push("Taxa de c├ómbio ├® obrigat├│ria para transfer├¬ncias entre moedas diferentes");
    }

    if (isMultiCurrency && transaction.exchange_rate && transaction.exchange_rate <= 0) {
      errors.push("Taxa de c├ómbio deve ser maior que zero");
    }
  }

  // ==========================================
  // 10. VALIDA├ç├âO DE RECORR├èNCIA
  // ==========================================

  if (transaction.is_recurring) {
    if (!transaction.frequency) {
      errors.push("Frequ├¬ncia ├® obrigat├│ria para transa├º├Áes recorrentes");
    }

    if (transaction.frequency === "MONTHLY" && !transaction.recurrence_day) {
      errors.push("Dia do m├¬s ├® obrigat├│rio para recorr├¬ncia mensal");
    }

    if (
      transaction.recurrence_day &&
      (transaction.recurrence_day < 1 || transaction.recurrence_day > 31)
    ) {
      errors.push("Dia de recorr├¬ncia deve estar entre 1 e 31");
    }
  }

  // ==========================================
  // 11. VALIDA├ç├âO DE DUPLICATAS
  // ==========================================

  if (allTransactions && transaction.amount && transaction.description && transaction.date) {
    const targetTime = new Date(transaction.date + "T12:00:00").getTime();
    const targetDescLower = transaction.description.toLowerCase().trim();

    const duplicates = allTransactions.filter((tx) => {
      if (tx.id === transaction.id) return false; // Ignorar a pr├│pria transa├º├úo em edi├º├úo
      if (
        (transaction as any).series_id &&
        (tx as any).series_id === (transaction as any).series_id
      )
        return false; // Ignorar transa├º├Áes da mesma s├®rie/parcelamento

      // 1. Filtros leves r├ípidos (evitam criar objetos de data desnecess├írios)
      const isSameAmount = Math.abs((tx.amount || 0) - (transaction.amount || 0)) < 0.01;
      if (!isSameAmount) return false;

      const isSameAccount = tx.account_id === transaction.account_id;
      if (!isSameAccount) return false;

      const isSameDescription = tx.description?.toLowerCase().trim() === targetDescLower;
      if (!isSameDescription) return false;

      // 2. Filtro pesado de data (apenas executado para transa├º├Áes pr├®-selecionadas)
      if (tx.date) {
        const txTime = new Date(tx.date + "T12:00:00").getTime();
        const diffDays = Math.abs((txTime - targetTime) / (1000 * 60 * 60 * 24));
        return diffDays <= 3;
      }

      return false;
    });

    if (duplicates.length > 0) {
      warnings.push(
        `Poss├¡vel duplicata: transa├º├úo similar encontrada (${duplicates.length} ocorr├¬ncia${duplicates.length > 1 ? "s" : ""})`
      );
    }
  }

  // ==========================================
  // 12. VALIDA├ç├âO DE REEMBOLSO
  // ==========================================

  if (transaction.is_refund && !transaction.refund_of_transaction_id) {
    warnings.push("Reembolso sem refer├¬ncia ├á transa├º├úo original");
  }

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
  };
}

/**
 * Valida uma conta
 */
export function validateAccount(account: Partial<Account>): ValidationResult {
  const errors: string[] = [];
  const warnings: string[] = [];

  if (!account.type) {
    errors.push("Tipo de conta ├® obrigat├│rio");
  }

  // Valida├º├Áes espec├¡ficas por tipo
  if (account.type === "CREDIT_CARD") {
    if (!account.credit_limit || account.credit_limit <= 0) {
      errors.push("Limite de cr├®dito ├® obrigat├│rio para cart├Áes");
    }
  }

  return {
    isValid: errors.length === 0,
    errors,
    warnings,
  };
}

import { create } from 'zustand';
import { TabType, TransactionSplitData } from '@/types/transactions';
import { Transaction } from '@/hooks/useTransactions';
import { parseISO } from 'date-fns';

export interface TransactionFormState {
  activeTab: TabType;
  amount: string;
  description: string;
  date: Date;
  accountId: string;
  destinationAccountId: string;
  categoryId: string;
  tripId: string;
  notes: string;
  exchangeRate: string;
  destinationAmount: string;

  isInstallment: boolean;
  totalInstallments: number;
  showSplitModal: boolean;
  payerId: string;
  splits: TransactionSplitData[];
  isRefund: boolean;
  isRecurring: boolean;
  frequency: 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'YEARLY';
  recurrenceDay: number;
  enableNotification: boolean;
  notificationDate?: Date;

  hasUserSelectedCategoryManually: boolean;
  lastAppliedCategoryId: string | null;

  transferType: 'account' | 'goal';
  goalId: string;
  saveAsPending: boolean;

  // Actions
  setActiveTab: (tab: TabType) => void;
  setAmount: (amount: string) => void;
  setDescription: (desc: string) => void;
  setDate: (date: Date) => void;
  setAccountId: (id: string) => void;
  setDestinationAccountId: (id: string) => void;
  setCategoryId: (id: string) => void;
  setTripId: (id: string) => void;
  setNotes: (notes: string) => void;
  setExchangeRate: (rate: string) => void;
  setDestinationAmount: (amount: string) => void;
  setIsInstallment: (val: boolean) => void;
  setTotalInstallments: (val: number) => void;
  setShowSplitModal: (val: boolean) => void;
  setPayerId: (id: string) => void;
  setSplits: (splits: TransactionSplitData[]) => void;
  setIsRefund: (val: boolean) => void;
  setIsRecurring: (val: boolean) => void;
  setFrequency: (freq: 'DAILY' | 'WEEKLY' | 'MONTHLY' | 'YEARLY') => void;
  setRecurrenceDay: (day: number) => void;
  setEnableNotification: (val: boolean) => void;
  setNotificationDate: (date?: Date) => void;

  setHasUserSelectedCategoryManually: (val: boolean) => void;
  setLastAppliedCategoryId: (id: string | null) => void;
  
  setTransferType: (type: 'account' | 'goal') => void;
  setGoalId: (id: string) => void;
  setSaveAsPending: (val: boolean) => void;

  reset: () => void;
  initFromData: (data: Partial<Transaction>) => void;
}

const initialState = {
  activeTab: 'EXPENSE' as TabType,
  amount: '',
  description: '',
  date: new Date(),
  accountId: '',
  destinationAccountId: '',
  categoryId: '',
  tripId: '',
  notes: '',
  exchangeRate: '',
  destinationAmount: '',

  isInstallment: false,
  totalInstallments: 1,
  showSplitModal: false,
  payerId: 'me',
  splits: [],
  isRefund: false,
  isRecurring: false,
  frequency: 'MONTHLY' as const,
  recurrenceDay: 1,
  enableNotification: false,
  notificationDate: undefined,

  hasUserSelectedCategoryManually: false,
  lastAppliedCategoryId: null,
  
  transferType: 'account' as const,
  goalId: '',
  saveAsPending: false,
};

export const useTransactionStore = create<TransactionFormState>((set) => ({
  ...initialState,

  setActiveTab: (tab) => set({ activeTab: tab }),
  setAmount: (amount) => set({ amount }),
  setDescription: (description) => {
    set(() => {
      // Se limpar a descri├º├úo, reseta a escolha manual de categoria
      if (description.trim() === '') {
        return { description, hasUserSelectedCategoryManually: false, lastAppliedCategoryId: null };
      }
      return { description };
    });
  },
  setDate: (date) => set({ date }),
  setAccountId: (id) => set({ accountId: id }),
  setDestinationAccountId: (id) => set({ destinationAccountId: id }),
  setCategoryId: (id) => set({ categoryId: id }),
  setTripId: (id) => set({ tripId: id }),
  setNotes: (notes) => set({ notes }),
  setExchangeRate: (rate) => set({ exchangeRate: rate }),
  setDestinationAmount: (amount) => set({ destinationAmount: amount }),
  setIsInstallment: (val) => set({ isInstallment: val }),
  setTotalInstallments: (val) => set({ totalInstallments: val }),
  setShowSplitModal: (val) => set({ showSplitModal: val }),
  setPayerId: (id) => set({ payerId: id }),
  setSplits: (splits) => set({ splits }),
  setIsRefund: (val) => set({ isRefund: val }),
  setIsRecurring: (val) => set({ isRecurring: val }),
  setFrequency: (freq) => set({ frequency: freq }),
  setRecurrenceDay: (day) => set({ recurrenceDay: day }),
  setEnableNotification: (val) => set({ enableNotification: val }),
  setNotificationDate: (date) => set({ notificationDate: date }),

  setHasUserSelectedCategoryManually: (val) => set({ hasUserSelectedCategoryManually: val }),
  setLastAppliedCategoryId: (id) => set({ lastAppliedCategoryId: id }),

  setTransferType: (type) => set({ transferType: type }),
  setGoalId: (id) => set({ goalId: id }),
  setSaveAsPending: (val) => set({ saveAsPending: val }),

  reset: () => set({ ...initialState, date: new Date() }),

  initFromData: (data: any) => {
    set(() => {
      const updates: Partial<TransactionFormState> = {};
      
      if (data.type) updates.activeTab = data.type;
      if (data.amount !== undefined && data.amount !== null) updates.amount = data.amount.toString();
      if (data.description) updates.description = data.description;
      if (data.date) updates.date = typeof data.date === 'string' ? parseISO(data.date) : data.date;
      if (data.account_id) updates.accountId = data.account_id;
      if (data.destination_account_id) updates.destinationAccountId = data.destination_account_id;
      if (data.category_id) updates.categoryId = data.category_id;
      if (data.trip_id) updates.tripId = data.trip_id;
      if (data.notes) updates.notes = data.notes;
      if (data.payer_id) updates.payerId = data.payer_id;
      if (data.is_installment) updates.isInstallment = data.is_installment;
      if (data.total_installments) updates.totalInstallments = data.total_installments;
      
      if (data.transaction_splits && Array.isArray(data.transaction_splits) && data.transaction_splits.length > 0) {
        updates.splits = data.transaction_splits.map((s: any) => ({
          memberId: s.member_id || s.memberId,
          percentage: s.percentage,
          amount: s.amount
        }));
      } else if (data.splits && Array.isArray(data.splits) && data.splits.length > 0) {
        updates.splits = data.splits.map((s: any) => ({
          memberId: s.member_id || s.memberId,
          percentage: s.percentage,
          amount: s.amount
        }));
      }

      return updates;
    });
  }
}));

