import type jsPDF from "jspdf";

const BRAND_COLOR: [number, number, number] = [5, 150, 105]; // Esmeralda / Verde Premium
const TEXT_COLOR: [number, number, number] = [31, 41, 55]; // Cinza Escuro

// Lazy-load jsPDF (dynamic import ÔÇö s├│ carrega quando usu├írio exporta PDF)
let _jsPDF: typeof jsPDF | null = null;
let _autoTable: typeof import("jspdf-autotable").default | null = null;
async function getJsPDF() {
  if (!_jsPDF) {
    const [pdfModule, tableModule] = await Promise.all([
      import("jspdf"),
      import("jspdf-autotable"),
    ]);
    _jsPDF = pdfModule.default;
    _autoTable = tableModule.default || (tableModule as any);
  }
  return { jsPDF: _jsPDF, autoTable: _autoTable };
}

export interface CalculatorExportData {
  title: string;
  parameters: { label: string; value: string }[];
  summary: { label: string; value: string; isWarning?: boolean }[];
  tableHead: string[];
  tableBody: string[][];
}

export const exportCalculatorToPDF = async (data: CalculatorExportData) => {
  const { jsPDF: JsPDF, autoTable } = await getJsPDF();
  const doc = new JsPDF();
  const today = new Date().toLocaleDateString("pt-BR");
  const now = new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });

  // 1. Cabe├ºalho e Branding Premium
  doc.setFillColor(BRAND_COLOR[0], BRAND_COLOR[1], BRAND_COLOR[2]);
  doc.rect(0, 0, 210, 40, "F");

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("p├® de meia", 14, 23);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(data.title, 14, 31);

  doc.setFontSize(9);
  doc.text(`Emitido em: ${today} ├ás ${now}`, 150, 23);

  // 2. Par├ómetros
  doc.setTextColor(TEXT_COLOR[0], TEXT_COLOR[1], TEXT_COLOR[2]);
  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("Par├ómetros Utilizados", 14, 52);

  const paramRows = data.parameters.map((p) => [p.label, p.value]);

  autoTable(doc, {
    body: paramRows,
    startY: 57,
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 2.5 },
    columnStyles: {
      0: { fontStyle: "bold", textColor: [100, 110, 120], cellWidth: 80 },
      1: { fontStyle: "bold", textColor: TEXT_COLOR },
    },
  });

  let currentY = (doc as Record<string, any>).lastAutoTable.finalY + 12;

  // 3. Resultados Resumo
  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.text("Resumo do Cen├írio", 14, currentY);

  const summaryRows = data.summary.map((s) => [s.label, s.value]);

  autoTable(doc, {
    body: summaryRows,
    startY: currentY + 5,
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 3 },
    columnStyles: {
      0: { fontStyle: "bold", textColor: [100, 110, 120], cellWidth: 80 },
      1: { fontStyle: "bold", textColor: TEXT_COLOR },
    },
    didParseCell: (cellData) => {
      const rowIndex = cellData.row.index;
      if (
        cellData.section === "body" &&
        data.summary[rowIndex].isWarning &&
        cellData.column.index === 1
      ) {
        cellData.cell.styles.textColor = [5, 150, 105]; // Highlight as primary color (or warning depending on logic, here we use primary green for good outcomes)
      }
    },
  });

  currentY = (doc as Record<string, any>).lastAutoTable.finalY + 12;

  // 4. Detalhamento Mensal/Anual (Tabela Principal)
  if (currentY > 220) {
    doc.addPage();
    currentY = 25;
  }

  doc.setFontSize(14);
  doc.setFont("helvetica", "bold");
  doc.setTextColor(TEXT_COLOR[0], TEXT_COLOR[1], TEXT_COLOR[2]);
  doc.text("Evolu├º├úo do Patrim├┤nio", 14, currentY);

  autoTable(doc, {
    head: [data.tableHead],
    body: data.tableBody,
    startY: currentY + 5,
    theme: "striped",
    headStyles: { fillColor: BRAND_COLOR, fontSize: 10 },
    bodyStyles: { fontSize: 9 },
  });

  // 5. Pagina├º├úo e Rodap├® Autom├ítico
  const pageCount = (doc as Record<string, any>).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Simulador Inteligente | P├ígina ${i} de ${pageCount}`, 105, 290, { align: "center" });
  }

  const filename = `simulacao_${data.title.toLowerCase().replace(/\s+/g, "_")}_${today.replace(/\//g, "-")}.pdf`;
  doc.save(filename);
};

/**
 * Error Handling Utilities
 * Centralized error handling for consistent error messages and logging
 */

import { toast } from 'sonner';
import { showActionFeedback } from '@/components/ui/ActionFeedback';
import { logger } from './logger';

export interface AppError {
  message?: string;
  code?: string;
  error_code?: string;
  error_description?: string;
  status?: number;
}

export const getError = (e: unknown): AppError => {
  if (typeof e === 'object' && e !== null) return e as AppError;
  return {};
};

/**
 * Handle query errors
 * Logs error and throws it for React Query to handle
 */
export const handleQueryError = (
  error: unknown,
  context: string
): never => {
  logger.error(`Erro ao ${context}`, { error });
  throw error;
};

/**
 * Handle mutation errors
 * Logs error and shows toast message
 */
export const handleMutationError = (
  error: unknown,
  action: string,
  entity: string
): void => {
  const message = `Erro ao ${action} ${entity}`;
  logger.error(message, { error });
  showActionFeedback("error");
  toast.error(`${message}: ${(error as Error)?.message || 'Erro desconhecido'}`);
};

/**
 * Handle Supabase errors
 * Provides user-friendly messages for common Supabase errors
 */
export const handleSupabaseError = (
  error: unknown,
  context: string
): never => {
  logger.error(`Erro Supabase ao ${context}`, { error });

  // Map common Supabase error codes to user-friendly messages
  const errorMessages: Record<string, string> = {
    '23505': 'Este registro j├í existe',
    '23503': 'N├úo ├® poss├¡vel excluir este registro pois est├í sendo usado',
    '42501': 'Voc├¬ n├úo tem permiss├úo para realizar esta a├º├úo',
    'PGRST116': 'Nenhum registro encontrado',
    '42P01': 'Tabela n├úo encontrada',
  };

  const err = getError(error);
  const code = String(err.code || err.error_code || '');
  const userMessage = errorMessages[code] || err.message || 'Erro desconhecido';

  throw new Error(userMessage as string);
};

/**
 * Handle validation errors
 * Shows toast with validation error message
 */
export const handleValidationError = (message: string): never => {
  logger.warn('Erro de valida├º├úo', { message });
  showActionFeedback("error");
  toast.error(message);
  throw new Error(message);
};

/**
 * Handle network errors
 * Shows toast with network error message
 */
export const handleNetworkError = (error: unknown): never => {
  logger.error('Erro de rede', { error });
  showActionFeedback("error");
  toast.error('Erro de conex├úo. Verifique sua internet e tente novamente.');
  throw error;
};

/**
 * Safe error handler
 * Catches all errors and provides fallback message
 */
export const safeErrorHandler = (
  error: unknown,
  fallbackMessage: string = 'Ocorreu um erro inesperado'
): void => {
  logger.error('Erro n├úo tratado', { error });
  showActionFeedback("error");
  
  if (error instanceof Error) {
    toast.error(error.message);
  } else {
    toast.error(fallbackMessage);
  }
};

/**
 * Async error wrapper
 * Wraps async functions with error handling
 */
export const withErrorHandling = <T>(
  fn: () => Promise<T>,
  errorMessage: string
): Promise<T> => {
  return fn().catch((error) => {
    logger.error(errorMessage, { error });
    showActionFeedback("error");
    toast.error(`${errorMessage}: ${error.message}`);
    throw error;
  });
};

/**
 * Retry with exponential backoff
 * Retries a function with exponential backoff on failure
 */
export const retryWithBackoff = async <T>(
  fn: () => Promise<T>,
  maxRetries: number = 3,
  baseDelay: number = 1000
): Promise<T> => {
  let lastError: unknown;

  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      logger.warn(`Tentativa ${i + 1}/${maxRetries} falhou`, { error });

      if (i < maxRetries - 1) {
        const delay = baseDelay * Math.pow(2, i);
        await new Promise(resolve => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError;
};

/**
 * Check if error is a network error
 */
export const isNetworkError = (error: unknown): boolean => {
  const err = getError(error);
  return (
    err.message === 'Network request failed' ||
    err.message === 'Failed to fetch' ||
    !navigator.onLine
  );
};

/**
 * Check if error is an authentication error
 */
export const isAuthError = (error: unknown): boolean => {
  const err = getError(error);
  return (
    err.status === 401 ||
    err.code === 'PGRST301' ||
    err.message?.includes('JWT') || false
  );
};

/**
 * Check if error is a permission error
 */
export const isPermissionError = (error: unknown): boolean => {
  const err = getError(error);
  return (
    err.status === 403 ||
    err.code === '42501'
  );
};

/**
 * Format error for display
 * Extracts user-friendly message from error object
 */
export const formatErrorMessage = (error: unknown): string => {
  if (typeof error === 'string') return error;
  if (error instanceof Error) return error.message;
  const err = getError(error);
  if (err.message) return err.message;
  if (err.error_description) return err.error_description;
  return 'Ocorreu um erro inesperado';
};

type CurrencyTotals = {
  income: number;
  expense: number;
  balance: number;
};

export const resolveItemCurrency = (item: any, accounts: any[] = []): string => {
  const account = item?.account || accounts.find((a) => a.id === item?.account_id);
  const destinationAccount = accounts.find((a) => a.id === item?.destination_account_id);
  return account?.currency || item?.currency || destinationAccount?.currency || "BRL";
};

export const formatExportMoney = (amount: number, currency = "BRL"): string => {
  try {
    return new Intl.NumberFormat("pt-BR", {
      style: "currency",
      currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(Number(amount || 0));
  } catch {
    return `${currency} ${Number(amount || 0).toLocaleString("pt-BR", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`;
  }
};

export const calculateTransactionTotalsByCurrency = (
  items: any[],
  accounts: any[] = []
): Record<string, CurrencyTotals> => {
  const totals: Record<string, CurrencyTotals> = {};

  items.forEach((item) => {
    const isIncome = item.type === "INCOME" || item.type === "RECEITA";
    const isExpense = item.type === "EXPENSE" || item.type === "DESPESA";
    if (!isIncome && !isExpense) return;

    const currency = resolveItemCurrency(item, accounts);
    if (!totals[currency]) totals[currency] = { income: 0, expense: 0, balance: 0 };

    if (isIncome) totals[currency].income += Number(item.amount || 0);
    if (isExpense) totals[currency].expense += Number(item.amount || 0);
  });

  Object.values(totals).forEach((total) => {
    total.balance = total.income - total.expense;
  });

  return totals;
};

export const formatTotalsInline = (
  totals: Record<string, CurrencyTotals>,
  field: keyof CurrencyTotals
): string => {
  const entries = Object.entries(totals);
  if (entries.length === 0) return formatExportMoney(0, "BRL");
  return entries.map(([currency, total]) => formatExportMoney(total[field], currency)).join(" / ");
};

