const safeCallAutoTable = (doc: jsPDF, options: any) => {
  try {
    if (typeof autoTable === "function") {
      autoTable(doc, options);
    } else if (autoTable && typeof (autoTable as any).default === "function") {
      (autoTable as any).default(doc, options);
    } else if (typeof (doc as any).autoTable === "function") {
      (doc as any).autoTable(options);
    } else {
      logger.warn("M├®todo autoTable n├úo encontrado no escopo global ou local do jsPDF.");
    }
  } catch (error) {
    logger.error("Erro ao renderizar autoTable no PDF:", error);
  }
};

// Helper para calcular dinamicamente o in├¡cio do pr├│ximo bloco
const getNextStartY = (doc: jsPDF, fallbackY: number): number => {
  const lastAutoTable = (doc as any).lastAutoTable;
  if (lastAutoTable && typeof lastAutoTable.finalY === "number") {
    return lastAutoTable.finalY + 12;
  }
  return fallbackY;
};

// Helper para formata├º├úo de datas de forma ultra-segura
const safeFormatDate = (dateVal: any): string => {
  if (!dateVal) return "N/A";
  try {
    const d = new Date(dateVal);
    if (isNaN(d.getTime())) return "N/A";
    // Corrige fuso hor├írio local na renderiza├º├úo
    const utcDate = new Date(d.getTime() + d.getTimezoneOffset() * 60000);
    return format(utcDate, "dd/MM/yyyy");
  } catch (e) {
    return "N/A";
  }
};

