export const exportDetailedCardReportToPDF = (
  transactions: any[],
  card: any,
  periodLabel: string
) => {
  if (!transactions || transactions.length === 0) {
    toast.error("N├úo h├í lan├ºamentos no per├¡odo selecionado para exportar.");
    return;
  }

  const doc = new jsPDF();
  const today = new Date().toLocaleDateString("pt-BR");
  const now = new Date().toLocaleTimeString("pt-BR", { hour: "2-digit", minute: "2-digit" });

  // 1. Cabe├ºalho Premium
  doc.setFillColor(BRAND_COLOR[0], BRAND_COLOR[1], BRAND_COLOR[2]);
  doc.rect(0, 0, 210, 35, "F");

  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont("helvetica", "bold");
  doc.text("controle financeiro", 14, 20);

  doc.setFontSize(10);
  doc.setFont("helvetica", "normal");
  doc.text(`Relat├│rio Detalhado: Cart├úo ${card?.name || ""} - ${periodLabel}`, 14, 28);
  doc.text(`Emitido em: ${today} ├ás ${now}`, 150, 20);

  // Calcular TOTAIS e CATEGORIAS
  let totalExpense = 0;
  let ownerExpense = 0;
  let otherExpense = 0;
  const categoriesMap: Record<string, number> = {};

  const currency = card?.currency || "BRL";
  const ownerId = card?.user_id;

  transactions.forEach((t) => {
    const amt = Number(t.amount || 0);
    if (t.type === "EXPENSE") {
      totalExpense += amt;
      if (t.user_id === ownerId) {
        ownerExpense += amt;
      } else {
        otherExpense += amt;
      }
      const catName = t.category?.name || "Outros";
      categoriesMap[catName] = (categoriesMap[catName] || 0) + amt;
    } else if (t.type === "INCOME") {
      totalExpense -= amt;
      if (t.user_id === ownerId) {
        ownerExpense -= amt;
      } else {
        otherExpense -= amt;
      }
    }
  });

  const categoriesList = Object.entries(categoriesMap)
    .sort((a, b) => b[1] - a[1]) // maior pra menor
    .filter(([_, val]) => val > 0);

  // 2. Resumo da Fatura/Per├¡odo
  doc.setTextColor(TEXT_COLOR[0], TEXT_COLOR[1], TEXT_COLOR[2]);
  doc.setFontSize(13);
  doc.setFont("helvetica", "bold");
  doc.text("Resumo do Cart├úo", 14, 48);

  safeCallAutoTable(doc, {
    body: [
      ["Gasto Total no Per├¡odo:", formatExportMoney(totalExpense, currency)],
      ["Limite do Cart├úo:", formatExportMoney(Number(card?.credit_limit || 0), currency)],
    ],
    startY: 52,
    theme: "plain",
    styles: { fontSize: 10, cellPadding: 2 },
    columnStyles: {
      0: { fontStyle: "bold", textColor: [100, 110, 120], cellWidth: 50 },
      1: { fontStyle: "bold", textColor: [239, 68, 68] },
    },
  });

  let nextStartY = getNextStartY(doc, 75);

  // 3. Distribui├º├úo por Categoria
  if (categoriesList.length > 0) {
    doc.setFontSize(13);
    doc.setFont("helvetica", "bold");
    doc.setTextColor(TEXT_COLOR[0], TEXT_COLOR[1], TEXT_COLOR[2]);
    doc.text("Maiores Gastos por Categoria", 14, nextStartY);

    safeCallAutoTable(doc, {
      head: [["Categoria", "Valor", "% do Total"]],
      body: categoriesList
        .slice(0, 10)
        .map(([cat, val]) => [
          cat,
          formatExportMoney(val, currency),
          ((val / Math.max(totalExpense, 1)) * 100).toFixed(1) + "%",
        ]),
      startY: nextStartY + 5,
      theme: "striped",
      styles: { fontSize: 9 },
      headStyles: { fillColor: [100, 110, 120] },
      columnStyles: {
        1: { halign: "right" },
        2: { halign: "right" },
      },
    });

    nextStartY = getNextStartY(doc, nextStartY + 30);
  }

  // 4. Lista de Lan├ºamentos
  doc.setFontSize(13);
  doc.setFont("helvetica", "bold");
  doc.text("Lan├ºamentos Detalhados", 14, nextStartY);

  const tableColumn = ["Data", "Descri├º├úo", "Categoria", "Parcela", "Moeda", "Valor"];
  const tableRows = transactions.map((t) => {
    const installmentText = t.is_installment
      ? `Parc. ${t.current_installment}/${t.total_installments}`
      : "├Ç vista";

    const tCurrency = resolveItemCurrency(t, [card]);
    return [
      safeFormatDate(t.date),
      t.description || "Sem descri├º├úo",
      t.category?.name || "Sem categoria",
      installmentText,
      tCurrency,
      formatExportMoney(Number(t.amount || 0), tCurrency),
    ];
  });

  safeCallAutoTable(doc, {
    head: [tableColumn],
    body: tableRows,
    startY: nextStartY + 5,
    theme: "striped",
    styles: { fontSize: 8.5 },
    headStyles: { fillColor: BRAND_COLOR },
    columnStyles: {
      5: { halign: "right", fontStyle: "bold" },
    },
    didParseCell: (cellData: any) => {
      if (cellData.section === "body" && cellData.column.index === 5) {
        cellData.cell.styles.textColor = [239, 68, 68]; // Red for expenses
      }
    },
  });

  addFooter(doc);
  doc.save(
    `relatorio_detalhado_${card?.name?.replace(/\s+/g, "_")}_${periodLabel.toLowerCase().replace(/\s+/g, "_")}.pdf`
  );
};

