  doc.rect(0, 0, 210, 25, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('controle financeiro', 14, 12);
  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
