/**
 * RPC with Retry Logic
 *
 * Wrapper para chamadas RPC com retry autom├ítico, backoff exponencial,
 * AbortController para cancelamento real de requests, e tratamento de erros.
 */

import { supabase } from '@/integrations/supabase/client';
import { logger } from './logger';

interface RpcRetryOptions {
  maxRetries?: number;
  baseDelayMs?: number;
  timeoutMs?: number;
  onRetry?: (attempt: number, error: Error) => void;
}

interface RpcCallResult<T> {
  data: T | null;
  error: Error | null;
  attempts: number;
  lastError?: Error;
}

function calculateBackoffDelay(attempt: number, baseDelayMs: number): number {
  const exponentialDelay = baseDelayMs * Math.pow(2, attempt);
  const jitter = Math.random() * 0.1 * exponentialDelay; // 10% jitter
  return exponentialDelay + jitter;
}

function isRetriableError(error: unknown): boolean {
  const err = error as Record<string, unknown>;
  // Whitelist-only: never retry client errors (4xx) unless explicitly allowed
  if ((err as Error)?.name === 'AbortError') return true;  // our own timeout = network flakiness
  if (err?.status === 429) return true;                    // rate-limited
  if (err?.status === 503 || err?.status === 504) return true; // server unavailable / gateway timeout
  if (err?.code === 'PGRST999') return true;               // Supabase internal transient
  // Everything else (400, 401, 403, 404, 409, 422, 500 logic errors) is not retriable
  return false;
}

/**
 * Executes a single RPC attempt with AbortController-based timeout.
 * The underlying fetch is actually cancelled on timeout (no zombie connections).
 */
async function rpcAttempt<T>(
  functionName: string,
  params: Record<string, unknown> | undefined,
  timeoutMs: number
): Promise<T> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const builder = supabase.rpc(functionName as never, params as never);
    // abortSignal wires the AbortController to the underlying fetch call
    const { data, error } = await (builder as any).abortSignal(controller.signal);

    if (error) throw error;
    return data as T;
  } catch (err) {
    if ((err as Error)?.name === 'AbortError') {
      throw new Error(`RPC timeout ap├│s ${timeoutMs}ms: ${functionName}`);
    }
    throw err;
  } finally {
    clearTimeout(timeoutId);
  }
}

export async function rpcWithRetry<T = unknown>(
  functionName: string,
  params?: Record<string, unknown>,
  options: RpcRetryOptions = {}
): Promise<T> {
  const {
    maxRetries = 3,
    baseDelayMs = 1000,
    timeoutMs = 30000,
    onRetry,
  } = options;

  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      logger.debug(`[RPC] Tentativa ${attempt + 1}/${maxRetries}: ${functionName}`, { params });

      const data = await rpcAttempt<T>(functionName, params, timeoutMs);

      logger.debug(`[RPC] Sucesso na tentativa ${attempt + 1}: ${functionName}`);
      return data;
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      const isRetriable = isRetriableError(error);
      const isLastAttempt = attempt === maxRetries - 1;

      logger.warn(`[RPC] Tentativa ${attempt + 1}/${maxRetries} falhou: ${functionName}`, {
        error: lastError.message,
        retriable: isRetriable,
        isLastAttempt,
      });

      if (onRetry && !isLastAttempt) onRetry(attempt + 1, lastError);

      if (!isRetriable || isLastAttempt) {
        logger.error(`[RPC] Falha final ap├│s ${attempt + 1} tentativa(s): ${functionName}`, {
          error: lastError.message,
        });
        throw lastError;
      }

      const delay = calculateBackoffDelay(attempt, baseDelayMs);
      logger.debug(`[RPC] Aguardando ${delay.toFixed(0)}ms antes de retry...`);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  throw lastError || new Error(`RPC falhou ap├│s ${maxRetries} tentativas`);
}

export async function rpcWithRetryDetailed<T = unknown>(
  functionName: string,
  params?: Record<string, unknown>,
  options: RpcRetryOptions = {}
): Promise<RpcCallResult<T>> {
  const {
    maxRetries = 3,
    baseDelayMs = 1000,
    timeoutMs = 30000,
    onRetry,
  } = options;

  let lastError: Error | null = null;

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      logger.debug(`[RPC] Tentativa ${attempt + 1}/${maxRetries}: ${functionName}`);

      const data = await rpcAttempt<T>(functionName, params, timeoutMs);

      logger.debug(`[RPC] Sucesso na tentativa ${attempt + 1}: ${functionName}`);
      return { data, error: null, attempts: attempt + 1 };
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));

      const isRetriable = isRetriableError(error);
      const isLastAttempt = attempt === maxRetries - 1;

      logger.warn(`[RPC] Tentativa ${attempt + 1}/${maxRetries} falhou: ${functionName}`, {
        error: lastError.message,
      });

      if (onRetry && !isLastAttempt) onRetry(attempt + 1, lastError);

      if (!isRetriable || isLastAttempt) {
        logger.error(`[RPC] Falha final ap├│s ${attempt + 1} tentativa(s): ${functionName}`, {
          error: lastError.message,
        });
        return { data: null, error: lastError, attempts: attempt + 1, lastError };
      }

      const delay = calculateBackoffDelay(attempt, baseDelayMs);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  return {
    data: null,
    error: lastError || new Error(`RPC falhou ap├│s ${maxRetries} tentativas`),
    attempts: maxRetries,
    lastError: lastError || undefined,
  };
}

export async function batchRpcWithRetry<T = unknown>(
  calls: Array<{ functionName: string; params?: Record<string, unknown> }>,
  options: RpcRetryOptions = {}
): Promise<T[]> {
  logger.debug(`[RPC] Iniciando batch de ${calls.length} chamadas RPC`);

  const results = await Promise.allSettled(
    calls.map(({ functionName, params }) =>
      rpcWithRetry<T>(functionName, params, options)
    )
  );

  const succeeded: T[] = [];
  for (const result of results) {
    if (result.status === 'fulfilled') {
      succeeded.push(result.value);
    } else {
      logger.error(`[RPC] Erro em batch call`, result.reason);
    }
  }

  logger.debug(`[RPC] Batch conclu├¡do: ${succeeded.length}/${calls.length} sucesso`);
  return succeeded;
}

import { SettlementValidator } from "@/services/settlementValidation";
import { dateUtils } from "@/utils/dateUtils";
import { Database } from "@/types/database";
import { SafeFinancialCalculator } from "@/services/SafeFinancialCalculator";
import type { TransactionSplit } from "@/services/settlementValidation";

export interface SplitInput {
  member_id: string;
  percentage: number;
  [key: string]: any;
}

/**
 * Calcula os valores de split garantindo que a soma exata seja igual ao valor da transa├º├úo (precis├úo de centavos).
 * O criador da transa├º├úo ├® priorizado para absorver qualquer d├¡zima/diferen├ºa de centavos.
 */
export const calculateTransactionSplits = <T extends SplitInput>(
  transactionAmount: number,
  splits: T[],
  creatorMemberId?: string
): (T & { amount: number })[] => {
  if (!splits || splits.length === 0) return [];

  // Ordenar para garantir que o 'Criador' fique por ├║ltimo e absorva o res├¡duo de centavos
  const sortedSplits = [...splits].sort((a, b) => {
    if (a.member_id === creatorMemberId) return 1;
    if (b.member_id === creatorMemberId) return -1;
    return 0;
  });

  // Usa Decimal internamente para precis├úo; converte a number apenas na sa├¡da
  let allocatedSum = SafeFinancialCalculator.toDecimal(0);

  return sortedSplits.map((split, index) => {
    let splitAmount: Decimal;
    if (index === sortedSplits.length - 1) {
      // O ├║ltimo (idealmente o criador) absorve a diferen├ºa para fechar os centavos
      splitAmount = SafeFinancialCalculator.subtract(transactionAmount, allocatedSum);
    } else {
      splitAmount = SafeFinancialCalculator.percentage(transactionAmount, split.percentage);
      allocatedSum = SafeFinancialCalculator.add(allocatedSum, splitAmount);
    }

    return {
      ...split,
      amount: splitAmount.toNumber(),
    };
  });
};

export interface InvoiceItem {
  id: string;
  originalTxId: string;
  splitId?: string;
  sourceTransactionId?: string;
  description: string;
  date: string;
  category?: string;
  amount: number;
  type: "CREDIT" | "DEBIT";
  isPaid: boolean;
  tripId?: string;
  memberId: string;
  memberName?: string;
  currency: string;
  installmentNumber?: number | null;
  totalInstallments?: number | null;
  seriesId?: string | null;
  creatorUserId?: string;
  creatorName?: string;
  isSettled: boolean;
  settledByDebtor: boolean;
  settledByCreditor: boolean;
  canEdit: boolean;
  canDelete: boolean;
  canAnticipate: boolean;
  blockReason?: string;
  settledAt?: string | null;
  originalDate: string;
  accountName?: string;
}

type DBTransaction = Database["public"]["Tables"]["transactions"]["Row"] & {
  category?: { id: string; name: string; icon: string | null; color: string | null } | null;
  transaction_splits?: DBSplit[];
  payer?: {
    id: string;
    name: string;
    user_id: string | null;
    linked_user_id: string | null;
  } | null;
  currency?: string;
  competence_date?: string | null;
};

type DBSplit = Database["public"]["Tables"]["transaction_splits"]["Row"] & {
  settled_by_debtor: boolean;
  settled_by_creditor: boolean;
};

type DBAccount = Pick<
  Database["public"]["Tables"]["accounts"]["Row"],
  "id" | "type" | "closing_day" | "due_day" | "user_id" | "name"
>;

export const calculateSharedDisplayDate = (
  transactionDate: string,
  competenceDate: string | null,
  accountId: string | null,
  accounts: DBAccount[],
  family?: any
): string => {
  if (!competenceDate) {
    return transactionDate;
  }

  if (!accountId) {
    return competenceDate;
  }

  const account = accounts.find((a) => a.id === accountId);
  if (!account) return competenceDate;

  if (account.type !== "CREDIT_CARD") {
    const closingMonth = dateUtils.parseDate(competenceDate);
    let dueMonth = closingMonth.getMonth() + 1;
    let dueYear = closingMonth.getFullYear();
    if (dueMonth > 11) {
      dueMonth = 0;
      dueYear++;
    }
    const dueDate = new Date(Date.UTC(dueYear, dueMonth, 1));
    return dateUtils.getCompetenceDate(dueDate);
  }

  const closingDay = account.closing_day || 1;
  const dueDay = account.due_day || 10;

  const closingMonth = dateUtils.parseDate(competenceDate);

  let dueMonth = closingMonth.getMonth();
  let dueYear = closingMonth.getFullYear();

  if (dueDay <= closingDay) {
    dueMonth++;
    if (dueMonth > 11) {
      dueMonth = 0;
      dueYear++;
    }
  }

  const dueDate = new Date(Date.UTC(dueYear, dueMonth, 1));
  return dateUtils.getCompetenceDate(dueDate);
};

export const generateInvoices = (
  transactions: DBTransaction[],
  accounts: DBAccount[],
  paidByOthersTransactions: DBTransaction[],
  members: Record<string, any>[],
  userId: string | undefined,
  profile?: any,
  family?: any
): Record<string, InvoiceItem[]> => {
  const invoiceMap: Record<string, InvoiceItem[]> = {};
  const processedTxIds = new Set<string>();

  const myMemberId = members.find((m) => m.linked_user_id === userId)?.id;

  members.forEach((m) => {
    invoiceMap[m.id] = [];
  });

  transactions.forEach((tx) => {
    if (tx.type !== "EXPENSE" && tx.type !== "INCOME") return;

    const isRefund = tx.type === "INCOME";
    const splits = tx.transaction_splits || [];
    const txCurrency = tx.currency || "BRL";

    const isMeTheRealCreditor =
      (tx.user_id === userId && !tx.payer_id) ||
      (tx.payer_id === myMemberId && tx.payer_id != null);

    if (isMeTheRealCreditor) {
      splits.forEach((split) => {
        const memberId = split.member_id;
        if (!memberId || memberId === myMemberId) return;

        const uniqueKey = `${tx.id}-credit-${memberId}`;
        if (processedTxIds.has(uniqueKey)) return;
        processedTxIds.add(uniqueKey);

        const member = members.find((m) => m.id === memberId);
        const creator = members.find((m) => m.linked_user_id === tx.user_id);
        const creatorName = creator?.name || (tx.user_id === userId ? "Voc├¬" : "Outro membro");

        if (!invoiceMap[memberId]) invoiceMap[memberId] = [];

        const settlementStatus = SettlementValidator.getSettlementStatus(
          { id: tx.id, user_id: tx.user_id, is_settled: tx.is_settled || false },
          split as unknown as TransactionSplit
        );

        const displayDate = calculateSharedDisplayDate(
          tx.date,
          tx.competence_date,
          tx.account_id,
          accounts,
          family
        );

        invoiceMap[memberId].push({
          id: uniqueKey,
          originalTxId: tx.id,
          splitId: split.id,
          description: tx.description,
          date: displayDate,
          category: tx.category?.name,
          amount: isRefund ? -split.amount : split.amount,
          type: isRefund ? "DEBIT" : "CREDIT",
          isPaid: split.is_settled === true || split.settled_by_creditor === true,
          tripId: tx.trip_id || undefined,
          memberId: memberId,
          memberName: member?.name || split.name,
          currency: txCurrency,
          installmentNumber: tx.current_installment,
          totalInstallments: tx.total_installments,
          seriesId: tx.series_id,
          creatorUserId: tx.user_id,
          creatorName: creatorName,
          isSettled: split.is_settled === true,
          settledByDebtor: split.settled_by_debtor || false,
          settledByCreditor: split.settled_by_creditor || false,
          canEdit: settlementStatus.canEdit,
          canDelete: settlementStatus.canDelete,
          canAnticipate: settlementStatus.canAnticipate,
          blockReason: settlementStatus.blockReason,
          settledAt: split.settled_at,
          originalDate: tx.date,
          accountName: accounts.find((a) => a.id === tx.account_id)?.name,
        });
      });
    } else {
      const mySplit = splits.find((s) => s.member_id === myMemberId);
      if (mySplit) {
        const creatorMember = members.find((m) => m.linked_user_id === tx.user_id);
        if (creatorMember) {
          const uniqueKey = `${tx.id}-debit-${creatorMember.id}`;
          if (!processedTxIds.has(uniqueKey)) {
            processedTxIds.add(uniqueKey);
            if (!invoiceMap[creatorMember.id]) invoiceMap[creatorMember.id] = [];

            const settlementStatus = SettlementValidator.getSettlementStatus(
              { id: tx.id, user_id: tx.user_id, is_settled: tx.is_settled || false },
              { ...mySplit, member_id: mySplit.member_id || "" } as unknown as TransactionSplit
            );

            const displayDate = calculateSharedDisplayDate(
              tx.date,
              tx.competence_date,
              tx.account_id,
              accounts,
              family
            );

            invoiceMap[creatorMember.id].push({
              id: uniqueKey,
              originalTxId: tx.id,
              splitId: mySplit.id,
              description: tx.description,
              date: displayDate,
              category: tx.category?.name,
              amount: mySplit.amount,
              type: "DEBIT",
              isPaid: mySplit.is_settled === true || mySplit.settled_by_debtor === true,
              tripId: tx.trip_id || undefined,
              memberId: creatorMember.id,
              memberName: creatorMember.name,
              currency: txCurrency,
              installmentNumber: tx.current_installment,
              totalInstallments: tx.total_installments,
              seriesId: tx.series_id,
              creatorUserId: tx.user_id,
              creatorName: creatorMember.name,
              isSettled: mySplit.is_settled === true,
              settledByDebtor: mySplit.settled_by_debtor || false,
              settledByCreditor: mySplit.settled_by_creditor || false,
              canEdit: settlementStatus.canEdit,
              canDelete: settlementStatus.canDelete,
              canAnticipate: settlementStatus.canAnticipate,
              blockReason: settlementStatus.blockReason,
              settledAt: mySplit.settled_at,
              originalDate: tx.date,
              accountName: accounts.find((a) => a.id === tx.account_id)?.name,
            });
          }
        }
      }
    }
  });

  paidByOthersTransactions.forEach((tx) => {
    if (tx.type !== "EXPENSE" && tx.type !== "INCOME") return;
    const isRefund = tx.type === "INCOME";
    const txCurrency = tx.currency || "BRL";
    const payer = tx.payer;
    if (!payer) return;
    const targetMemberId = payer.id;

    const uniqueKey = `${tx.id}-debit-${targetMemberId}`;
    if (processedTxIds.has(uniqueKey)) return;
    processedTxIds.add(uniqueKey);

    if (!invoiceMap[targetMemberId]) invoiceMap[targetMemberId] = [];
    const displayDate = calculateSharedDisplayDate(
      tx.date,
      tx.competence_date,
      tx.account_id,
      accounts,
      family
    );

    invoiceMap[targetMemberId].push({
      id: uniqueKey,
      originalTxId: tx.id,
      description: tx.description,
      date: displayDate,
      category: tx.category?.name,
      amount: isRefund ? -tx.amount : tx.amount,
      type: isRefund ? "CREDIT" : "DEBIT",
      isPaid: tx.is_settled === true,
      tripId: tx.trip_id || undefined,
      memberId: targetMemberId,
      memberName: payer.name,
      currency: txCurrency,
      installmentNumber: tx.current_installment,
      totalInstallments: tx.total_installments,
      seriesId: tx.series_id,
      creatorUserId: tx.user_id,
      creatorName: payer.name,
      isSettled: tx.is_settled === true,
      settledByDebtor: false,
      settledByCreditor: false,
      canEdit: !tx.is_settled,
      canDelete: !tx.is_settled,
      canAnticipate: !tx.is_settled,
      blockReason: tx.is_settled
        ? "Esta transa├º├úo j├í foi acertada e n├úo pode ser modificada"
        : undefined,
      settledAt: tx.settled_at,
      originalDate: tx.date,
      accountName: accounts.find((a) => a.id === tx.account_id)?.name,
    });
  });

  transactions.forEach((tx) => {
    if (tx.is_shared) return;
    if (tx.domain !== "SHARED") return;
    if (tx.type !== "EXPENSE" && tx.type !== "INCOME") return;

    const txCurrency = tx.currency || "BRL";

    if (tx.related_member_id) {
      const isPayerMe = tx.user_id === userId;
      const targetMemberId = tx.related_member_id;

      if (isPayerMe) {
        const uniqueKey = `${tx.id}-credit-${targetMemberId}`;
        if (!processedTxIds.has(uniqueKey)) {
          processedTxIds.add(uniqueKey);
          const member = members.find((m) => m.id === targetMemberId);
          const displayDate = calculateSharedDisplayDate(
            tx.date,
            tx.competence_date,
            tx.account_id,
            accounts,
            family
          );
          if (!invoiceMap[targetMemberId]) invoiceMap[targetMemberId] = [];

          invoiceMap[targetMemberId].push({
            id: uniqueKey,
            originalTxId: tx.id,
            description: tx.description,
            date: displayDate,
            category: tx.category?.name,
            amount: Number(tx.amount),
            type: "CREDIT",
            isPaid: tx.is_settled === true,
            tripId: tx.trip_id || undefined,
            memberId: targetMemberId,
            memberName: member?.name || "Membro",
            currency: txCurrency,
            installmentNumber: tx.current_installment,
            totalInstallments: tx.total_installments,
            seriesId: tx.series_id,
            creatorUserId: tx.user_id,
            creatorName: "Voc├¬",
            isSettled: tx.is_settled === true,
            settledByDebtor: tx.is_settled === true,
            settledByCreditor: tx.is_settled === true,
            canEdit: !tx.is_settled,
            canDelete: !tx.is_settled,
            canAnticipate: !tx.is_settled,
            settledAt: tx.settled_at,
            originalDate: tx.date,
            accountName: accounts.find((a) => a.id === tx.account_id)?.name,
          });
        }
      } else {
        const creatorMember = members.find((m) => m.linked_user_id === tx.user_id);
        if (creatorMember) {
          const uniqueKey = `${tx.id}-debit-${creatorMember.id}`;
          if (!processedTxIds.has(uniqueKey)) {
            processedTxIds.add(uniqueKey);
            const displayDate = calculateSharedDisplayDate(
              tx.date,
              tx.competence_date,
              tx.account_id,
              accounts,
              family
            );
            if (!invoiceMap[creatorMember.id]) invoiceMap[creatorMember.id] = [];

            invoiceMap[creatorMember.id].push({
              id: uniqueKey,
              originalTxId: tx.id,
              description: tx.description,
              date: displayDate,
              category: tx.category?.name,
              amount: Number(tx.amount),
              type: "DEBIT",
              isPaid: tx.is_settled === true,
              tripId: tx.trip_id || undefined,
              memberId: creatorMember.id,
              memberName: creatorMember.name,
              currency: txCurrency,
              installmentNumber: tx.current_installment,
              totalInstallments: tx.total_installments,
              seriesId: tx.series_id,
              creatorUserId: tx.user_id,
              creatorName: creatorMember.name,
              isSettled: tx.is_settled === true,
              settledByDebtor: tx.is_settled === true,
              settledByCreditor: tx.is_settled === true,
              canEdit: !tx.is_settled,
              canDelete: !tx.is_settled,
              canAnticipate: !tx.is_settled,
              settledAt: tx.settled_at,
              originalDate: tx.date,
              accountName: accounts.find((a) => a.id === tx.account_id)?.name,
            });
          }
        }
      }
    } else if (
      tx.description?.includes("Acerto") ||
      tx.description?.includes("acerto") ||
      tx.is_settled
    ) {
      const isCreatorMe = tx.user_id === userId;
      const otherMember = members.find((m) => m.linked_user_id !== userId);

      if (otherMember) {
        const targetMemberId = otherMember.id;
        const uniqueKey = `${tx.id}-${tx.type === "INCOME" ? "credit" : "debit"}-${targetMemberId}`;

        if (!processedTxIds.has(uniqueKey)) {
          processedTxIds.add(uniqueKey);
          const displayDate = calculateSharedDisplayDate(
            tx.date,
            tx.competence_date,
            tx.account_id,
            accounts,
            family
          );
          if (!invoiceMap[targetMemberId]) invoiceMap[targetMemberId] = [];

          invoiceMap[targetMemberId].push({
            id: uniqueKey,
            originalTxId: tx.id,
            description: tx.description,
            date: displayDate,
            category: "Acerto",
            amount: Number(tx.amount),
            type: tx.type === "EXPENSE" ? "CREDIT" : "DEBIT",
            isPaid: true,
            tripId: tx.trip_id || undefined,
            memberId: targetMemberId,
            memberName: otherMember.name,
            currency: txCurrency,
            creatorUserId: tx.user_id,
            creatorName: isCreatorMe ? "Voc├¬" : otherMember.name,
            isSettled: true,
            settledByDebtor: true,
            settledByCreditor: true,
            canEdit: false,
            canDelete: true,
            canAnticipate: false,
            settledAt: tx.settled_at || tx.created_at,
            originalDate: tx.date,
            accountName: accounts.find((a) => a.id === tx.account_id)?.name,
          });
        }
      }
    }
  });

  return invoiceMap;
};

import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { format } from 'date-fns';
import { formatCurrency } from './currencyFormatter';
import { logger } from '@/utils/logger';

const BRAND_COLOR: [number, number, number] = [5, 150, 105]; // Esmeralda / Verde Premium
const TEXT_COLOR: [number, number, number] = [31, 41, 55]; // Cinza Escuro

export interface TripExportData {
  trip: Record<string, any>;
  participants: Record<string, any>[];
  tripTransactions: Record<string, any>[];
  balances: Record<string, any>[];
  user: Record<string, any>;
}

// Helper para formata├º├úo de datas de forma ultra-segura
const safeFormatDate = (dateVal: unknown): string => {
  if (!dateVal) return 'N/A';
  try {
    const d = new Date(dateVal as string | number | Date);
    if (isNaN(d.getTime())) return 'N/A';
    return format(d, 'dd/MM/yyyy');
  } catch (e) {
    return 'N/A';
  }
};

export const exportTripToPDF = (data: TripExportData) => {
  const { trip, participants = [], tripTransactions = [], balances = [] } = data;
  
  if (!trip) {
    logger.error("Dados da viagem ausentes para exporta├º├úo em PDF.");
    return;
  }

  const doc = new jsPDF();
  const today = new Date().toLocaleDateString('pt-BR');
  const now = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });

  // 1. Cabe├ºalho e Branding Premium
  doc.setFillColor(BRAND_COLOR[0], BRAND_COLOR[1], BRAND_COLOR[2]);
  doc.rect(0, 0, 210, 40, 'F');
  
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(22);
  doc.setFont('helvetica', 'bold');
  doc.text('p├® de meia', 14, 23);
  
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.text('Relat├│rio Financeiro de Viagem', 14, 31);
  
  doc.setFontSize(9);
  doc.text(`Emitido em: ${today} ├ás ${now}`, 150, 23);

  // 2. Detalhes Gerais da Viagem
  doc.setTextColor(TEXT_COLOR[0], TEXT_COLOR[1], TEXT_COLOR[2]);
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('1. Informa├º├Áes da Viagem', 14, 52);

  const startDateFormatted = safeFormatDate(trip.start_date);
  const endDateFormatted = safeFormatDate(trip.end_date);

  // C├ílculos Financeiros
  const totalExpenses = tripTransactions
    .filter(t => t && t.type === 'EXPENSE')
    .reduce((sum, t) => sum + Number(t.amount || 0), 0);
  
  const budgetValue = Number(trip.budget) || 0;
  const balanceValue = budgetValue - totalExpenses;
  const perPersonCost = participants.length > 0 ? totalExpenses / participants.length : 0;

  autoTable(doc, {
    body: [
      ['Viagem/Destino:', trip.name || trip.destination || 'N/A', 'Per├¡odo:', `${startDateFormatted} a ${endDateFormatted}`],
      ['Or├ºamento Definido:', budgetValue > 0 ? formatCurrency(budgetValue, trip.currency) : 'N├úo informado', 'Total de Gastos:', formatCurrency(totalExpenses, trip.currency)],
      ['Saldo Dispon├¡vel:', budgetValue > 0 ? formatCurrency(balanceValue, trip.currency) : 'N/A', 'Custo por Participante:', formatCurrency(perPersonCost, trip.currency)]
    ],
    startY: 57,
    theme: 'plain',
    styles: { fontSize: 10, cellPadding: 2.5 },
    columnStyles: { 
      0: { fontStyle: 'bold', textColor: [100, 110, 120], cellWidth: 45 },
      1: { fontStyle: 'bold', textColor: TEXT_COLOR },
      2: { fontStyle: 'bold', textColor: [100, 110, 120], cellWidth: 45 },
      3: { fontStyle: 'bold', textColor: TEXT_COLOR }
    }
  });

  let currentY = (doc as Record<string, any>).lastAutoTable.finalY + 12;

  // 3. Participantes e Saldos de Acerto
  if (participants && participants.length > 0) {
    doc.setFontSize(14);
    doc.setFont('helvetica', 'bold');
    doc.text('2. Participantes e Balan├ºos', 14, currentY);

    const participantRows = balances.map(b => {
      const owesText = b.balance > 0 
        ? `Recebe ${formatCurrency(Math.abs(b.balance), trip.currency)}`
        : b.balance < 0 
        ? `Deve ${formatCurrency(Math.abs(b.balance), trip.currency)}`
        : 'Acertado';
      
      return [
        b.name || 'Desconhecido',
        formatCurrency(b.paid || 0, trip.currency),
        formatCurrency(b.owes || 0, trip.currency),
        owesText
      ];
    });

    autoTable(doc, {
      head: [['Nome', 'Valor Pago', 'Custo Individual (Rateio)', 'Balan├ºo de Acerto']],
      body: participantRows,
      startY: currentY + 5,
      theme: 'striped',
      headStyles: { fillColor: BRAND_COLOR, fontSize: 10, halign: 'left' },
      bodyStyles: { fontSize: 9.5, halign: 'left' },
      columnStyles: {
        3: { fontStyle: 'bold' }
      },
      didParseCell: (cellData: Record<string, any>) => {
        if (cellData.section === 'body' && cellData.column.index === 3) {
          const text = cellData.cell.text[0];
          if (text.startsWith('Recebe')) cellData.cell.styles.textColor = [16, 185, 129]; // Verde
          else if (text.startsWith('Deve')) cellData.cell.styles.textColor = [239, 68, 68]; // Vermelho
        }
      }
    });

    currentY = (doc as Record<string, any>).lastAutoTable.finalY + 12;
  }

  // 4. Detalhamento de Gastos (Tabela Principal)
  if (currentY > 220) {
    doc.addPage();
    currentY = 25;
  }

  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text('3. Detalhamento de Gastos', 14, currentY);

  const expenses = tripTransactions.filter(t => t && t.type === 'EXPENSE');

  if (expenses.length > 0) {
    const expenseRows = expenses.map(t => {
      const payer = participants.find(p => p.user_id === t.payer_id || p.member_id === t.payer_id);
      const payerName = payer?.name || t.account?.name || 'Desconhecido';
      
      return [
        safeFormatDate(t.date),
        t.description || 'Sem descri├º├úo',
        t.category?.name || 'Sem categoria',
        payerName,
        t.is_shared ? 'Compartilhado' : 'Individual',
        formatCurrency(t.amount, trip.currency)
      ];
    });

    autoTable(doc, {
      head: [['Data', 'Descri├º├úo', 'Categoria', 'Quem Pagou', 'Tipo', 'Valor']],
      body: expenseRows,
      startY: currentY + 5,
      theme: 'striped',
      headStyles: { fillColor: BRAND_COLOR, fontSize: 10 },
      bodyStyles: { fontSize: 9 },
      columnStyles: {
        5: { fontStyle: 'bold', halign: 'right' }
      }
    });
  } else {
    doc.setFontSize(10);
    doc.setFont('helvetica', 'italic');
    doc.text('Nenhuma despesa registrada nesta viagem.', 14, currentY + 8);
  }

  // 5. Pagina├º├úo e Rodap├® Autom├ítico
  const pageCount = (doc as Record<string, any>).internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Gest├úo Financeira | P├ígina ${i} de ${pageCount}`, 105, 290, { align: 'center' });
  }

  const filename = `relatorio_viagem_${trip.name.toLowerCase().replace(/\s+/g, '_')}_${today.replace(/\//g, '-')}.pdf`;
  doc.save(filename);
};

export const exportTripToExcel = (data: TripExportData) => {
  const { trip, participants = [], tripTransactions = [], balances = [] } = data;
  
  if (!trip) {
    logger.error("Dados da viagem ausentes para exporta├º├úo em Excel.");
    return;
  }

  const today = new Date().toLocaleDateString('pt-BR');
  const totalExpenses = tripTransactions
    .filter(t => t && t.type === 'EXPENSE')
    .reduce((sum, t) => sum + Number(t.amount || 0), 0);

  const budgetValue = Number(trip.budget) || 0;
  const balanceValue = budgetValue - totalExpenses;
  const perPersonCost = participants.length > 0 ? totalExpenses / participants.length : 0;
  
  const startDateFormatted = safeFormatDate(trip.start_date);
  const endDateFormatted = safeFormatDate(trip.end_date);

  // Montagem do HTML/XML formatado com folha de estilos lida diretamente pelo Excel
  let html = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel" xmlns="http://www.w3.org/TR/REC-html40">
    <head>
    <meta charset="utf-8" />
    <!--[if gte mso 9]><xml><x:ExcelWorkbook><x:ExcelWorksheets><x:ExcelWorksheet><x:Name>Relat├│rio de Viagem</x:Name><x:WorksheetOptions><x:DisplayGridlines/></x:WorksheetOptions></x:ExcelWorksheet></x:ExcelWorksheets></x:ExcelWorkbook></xml><![endif]-->
    <style>
      table { border-collapse: collapse; font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; }
      td, th { border: 1px solid #e5e7eb; padding: 6px 8px; font-size: 11px; }
      .brand-title { background-color: #059669; color: #ffffff; font-size: 16px; font-weight: bold; text-align: center; height: 35px; }
      .brand-subtitle { background-color: #047857; color: #ffffff; font-size: 10px; text-align: center; height: 20px; }
      .section-title { font-size: 12px; font-weight: bold; background-color: #f3f4f6; color: #1f2937; height: 25px; border-bottom: 2px solid #d1d5db; }
      .label-cell { font-weight: bold; color: #4b5563; background-color: #f9fafb; width: 150px; }
      .value-cell { font-weight: 500; color: #111827; }
      .th-premium { background-color: #059669; color: #ffffff; font-weight: bold; font-size: 10px; height: 25px; }
      .tr-zebra { background-color: #f9fafb; }
      .text-cell { mso-number-format:"\\@"; text-align: left; }
      .number-cell { mso-number-format:"\\#\\,\\#\\#0\\.00"; text-align: right; }
      .date-cell { mso-number-format:"dd\\/mm\\/yyyy"; text-align: center; }
      .green-text { color: #059669; font-weight: bold; }
      .red-text { color: #dc2626; font-weight: bold; }
    </style>
    </head>
    <body>
    <table>
      <!-- T├¡tulo Principal -->
      <tr>
        <th colspan="6" class="brand-title">CONTROLE FINANCEIRO</th>
      </tr>
      <tr>
        <th colspan="6" class="brand-subtitle">Relat├│rio Financeiro de Viagem ÔÇö Emitido em ${today}</th>
      </tr>
      <tr><td colspan="6" style="border:none; height: 10px;"></td></tr>

      <!-- Informa├º├Áes Gerais -->
      <tr>
        <th colspan="6" class="section-title">1. INFORMA├ç├òES GERAIS DA VIAGEM</th>
      </tr>
      <tr>
        <td class="label-cell">Destino/Viagem:</td>
        <td colspan="2" class="value-cell text-cell">${trip.name || trip.destination || 'N/A'}</td>
        <td class="label-cell">Per├¡odo:</td>
        <td colspan="2" class="value-cell text-cell">${startDateFormatted} a ${endDateFormatted}</td>
      </tr>
      <tr>
        <td class="label-cell">Or├ºamento da Viagem:</td>
        <td colspan="2" class="value-cell number-cell">${budgetValue}</td>
        <td class="label-cell">Total de Gastos:</td>
        <td colspan="2" class="value-cell number-cell" style="font-weight: bold; color: ${balanceValue >= 0 ? '#059669' : '#dc2626'}">${totalExpenses}</td>
      </tr>
      <tr>
        <td class="label-cell">Saldo Dispon├¡vel:</td>
        <td colspan="2" class="value-cell number-cell" style="font-weight: bold; color: ${balanceValue >= 0 ? '#059669' : '#dc2626'}">${budgetValue > 0 ? balanceValue : 0}</td>
        <td class="label-cell">Moeda Oficial:</td>
        <td colspan="2" class="value-cell text-cell">${trip.currency}</td>
      </tr>
      <tr>
        <td class="label-cell">Participantes:</td>
        <td colspan="2" class="value-cell text-cell">${participants.length} pessoas</td>
        <td class="label-cell">Custo por Pessoa (Rateio):</td>
        <td colspan="2" class="value-cell number-cell">${perPersonCost}</td>
      </tr>
      <tr><td colspan="6" style="border:none; height: 15px;"></td></tr>
  `;

  // Se├º├úo Participantes e Balan├ºos
  if (participants && participants.length > 0) {
    html += `
      <tr>
        <th colspan="6" class="section-title">2. PARTICIPANTES E BALAN├çO DE ACERTOS</th>
      </tr>
      <tr>
        <th colspan="2" class="th-premium text-cell">Nome</th>
        <th class="th-premium number-cell">Total Pago</th>
        <th class="th-premium number-cell">Custo Individual</th>
        <th colspan="2" class="th-premium text-cell">Balan├ºo de Acerto</th>
      </tr>
    `;

    balances.forEach((b, index) => {
      const owesText = b.balance > 0 
        ? `Recebe ${b.balance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
        : b.balance < 0 
        ? `Deve ${Math.abs(b.balance).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`
        : 'Acertado';
      
      const balanceClass = b.balance > 0 ? 'green-text' : b.balance < 0 ? 'red-text' : '';
      const zebraClass = index % 2 === 1 ? 'class="tr-zebra"' : '';

      html += `
        <tr ${zebraClass}>
          <td colspan="2" class="text-cell">${b.name || 'Desconhecido'}</td>
          <td class="number-cell">${b.paid || 0}</td>
          <td class="number-cell">${b.owes || 0}</td>
          <td colspan="2" class="text-cell ${balanceClass}">${owesText}</td>
        </tr>
      `;
    });

    html += `<tr><td colspan="6" style="border:none; height: 15px;"></td></tr>`;
  }

  // Se├º├úo Lista de Gastos
  html += `
    <tr>
      <th colspan="6" class="section-title">3. DETALHAMENTO DE DESPESAS</th>
    </tr>
    <tr>
      <th class="th-premium date-cell" style="width: 80px;">Data</th>
      <th colspan="2" class="th-premium text-cell">Descri├º├úo</th>
      <th class="th-premium text-cell">Categoria</th>
      <th class="th-premium text-cell">Quem Pagou</th>
      <th class="th-premium number-cell" style="width: 100px;">Valor (${trip.currency})</th>
    </tr>
  `;

  const expenses = tripTransactions.filter(t => t && t.type === 'EXPENSE');
  if (expenses.length > 0) {
    expenses.forEach((t, index) => {
      const payer = participants.find(p => p.user_id === t.payer_id || p.member_id === t.payer_id);
      const payerName = payer?.name || t.account?.name || 'Desconhecido';
      const zebraClass = index % 2 === 1 ? 'class="tr-zebra"' : '';
      const dateFormatted = safeFormatDate(t.date);

      html += `
        <tr ${zebraClass}>
          <td class="date-cell">${dateFormatted}</td>
          <td colspan="2" class="text-cell">${t.description || 'Sem descri├º├úo'}</td>
          <td class="text-cell">${t.category?.name || 'Sem categoria'}</td>
          <td class="text-cell">${payerName}</td>
          <td class="number-cell" style="font-weight: bold;">${Number(t.amount)}</td>
        </tr>
      `;
    });
  } else {
    html += `
      <tr>
        <td colspan="6" class="text-cell" style="font-style: italic; color: #6b7280; text-align: center;">Nenhuma despesa registrada nesta viagem.</td>
      </tr>
    `;
  }

  html += `
    </table>
    </body>
    </html>
  `;

  // Gera├º├úo do arquivo blob com formato de planilha Excel do Microsoft
  const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8;' });
  const link = document.createElement("a");
  const url = URL.createObjectURL(blob);
  
  const safeTripName = trip.name.toLowerCase().replace(/\s+/g, '_');
  const todayFilename = today.replace(/\//g, '-');
  
  link.setAttribute("href", url);
  link.setAttribute("download", `viagem_${safeTripName}_${todayFilename}.xls`);
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

